(window.GIM_TUR_P=window.GIM_TUR_P||{})["KYD.4"]={"from":271,"s":[["אֵין כּוֹתְבִין סֵפֶר תּוֹרָה עַל עוֹר בְּהֵמָה, חַיָּה וְעוֹף הַטְּמֵאִים; וְלֹא עַל עוֹר דָּג, אֲפִלּוּ טָהוֹר. אֲבָל כּוֹתְבִין עַל עוֹר בְּהֵמָה, חַיָּה וְעוֹף הַטְּהוֹרִים, וַאֲפִלּוּ עוֹר נְבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. וְצָרִיךְ שֶׁיְּהוּ הָעוֹרוֹת \u0010c0\u0011 מְעֻבָּדִין עַל יְדֵי יִשְׂרָאֵל לְשֵׁם \u0010c1\u0011 סֵפֶר תּוֹרָה, שֶׁיֹּאמַר בִּתְחִלַּת הָעִבּוּד כְּשֶׁמֵּשִׂים אוֹתָם לְתוֹךְ הַסִיד: עוֹרוֹת אֵלּוּ אֲנִי מְעַבֵּד לְשֵׁם \u0010c2\u0011 סֵפֶר תּוֹרָה. \u0005הַגָּה: וְאִם מְעַבְּדָן עוֹבֵד כּוֹכָבִים, יְסַיַּע הַיִּשְׂרָאֵל מְעַט (טוּר בְּשֵׁם ר\"ב)\u0006, \u0010c3\u0011 בִּתְחִלָּה כְּשֶׁנּוֹתְנוֹ לַסִּיד, וְיֹאמַר שֶׁהוּא עוֹשֶׂה לְשֵׁם קְדֻשַּׁת סֵפֶר תּוֹרָה \u0005(בֵּית יוֹסֵף)\u0006, וִיסַמֵּן אוֹתָן עוֹרוֹת שֶׁלֹּא יַחֲלִיפֵן הָעוֹבֵד כּוֹכָבִים, וְלֹא חַיְשִׁינָן אַחַר כָּךְ שֶׁמָּא הֶחֱלִיפָן הָעוֹבֵד כּוֹכָבִים וְזִיֵּף סִימָנָיו אַחֲרָיו \u0005(הַגָּהוֹת מַיְמוֹנִי פֶּרֶק א' מהל' סֵפֶר תּוֹרָה)\u0006. וְעַיֵּן בְּאֹרַח חַיִּים סִימָן ל\"ב.\nצָרִיךְ שֶׁיְּהוּ מְעֻבָּדִים בְּעַפְצָא אוֹ בְּסִיד וְכַיּוֹצֵא בוֹ, מִדְּבָרִים שֶׁמְּכַוְּצִים הָעוֹר וּמַחְזִיקִין אוֹתוֹ \u0005(רַמְבַּ\"ם ספ\"א מהל' סֵפֶר תּוֹרָה ד\"ו)\u0006.\nכּוֹתְבִין סֵפֶר תּוֹרָה עַל \u0010c4\u0011 הַגְּוִיל, וְהוּא הָעוֹר שֶׁלֹּא נֶחְלַק, וְכוֹתְבִין בּוֹ בִּמְקוֹם שֵׂעָר. וְאִם כָּתַב סֵפֶר תּוֹרָה עַל הַקְּלָף, כָּשֵׁר, וְהוּא שֶׁיִּהְיֶה כָּתוּב בַּצַּד הַפְּנִימִי שֶׁכְּלַפֵּי הַבָּשָׂר. \u0005הַגָּה: וּקְלָפִים שֶׁלָּנוּ הֵם יוֹתֵר מֻבְחָרִים מִגְּוִיל, וְכוֹתְבִין עֲלֵיהֶם לְכַתְּחִלָּה לְצַד בָּשָׂר. וְאֵין כּוֹתְבִין עַכְשָׁו עַל הַגְּוִיל (ר\"י מִינְץ סי' ס\"ו)\u0006. וְאִם שִׁנָּה וְכָתַב עַל קְלָפִים שֶׁלָּנוּ בִּמְקוֹם שֵׂעָר, פָּסוּל \u0005(אוֹר זָרוּעַ הִלְכוֹת תְּפִלִּין)\u0006. מִיהוּ יֵשׁ מְקִלִּין בָּזֶה \u0005(טוּר וְעוֹד פּוֹסְקִים עַיֵּן בֵּית יוֹסֵף)\u0006.\nכָּתַב מִקְּצָתוֹ עַל הַגְּוִיל וּמִקְּצָתוֹ עַל הַקְּלָף, פָּסוּל. אֲבָל אִם עָשָׂה חֶצְיוֹ גְּוִיל וְחֶצְיוֹ צְבָאִים, אַף עַל פִּי שֶׁאֵינָהּ מִצְוָה מִן הַמֻּבְחָר, כָּשֵׁר. \u0005וְעַיֵּן לְקַמָּן סִימָן ר\"ץ.\u0006\nסֵפֶר תּוֹרָה צָרִיךְ שִׂרְטוּט. וְאִם כְּתָבוֹ בְּלֹא שִׂרְטוּט, פָּסוּל. וְלֹא יְשַׂרְטֵט בְּעוֹפֶרֶת וְכַיּוֹצֵא בוֹ, שֶׁצּוֹבֵעַ.\nסֵפֶר תּוֹרָה צָרִיךְ שֶׁיִּכְתְּבֶנּוּ בִּדְיוֹ הֶעָשׂוּי מֵעֶשֶׁן הַשְּׁמָנִים שָׁרוּי בְּמֵי עֲפָצִים. \u0005וּלְכַתְּחִלָּה טוֹב לִזָּהֵר שֶׁלֹּא לַעֲשׂוֹת הַדְּיוֹ כִּי אִם מִדְּבָרִים הַבָּאִים מִן הָעֵץ (כֵּן מַשְׁמָע בַּזֹּהַר פ' תְּרוּמָה דַּף ע\"ב ע\"א)\u0006. וְאִם כְּתָבוֹ בְּמֵי עַפְצָא וְקַנְקַנְתּוּם, \u0010c5\u0011 כָּשֵׁר. אֲבָל לֹא בִּשְׁאָר מִינֵי צִבְעוֹנִים, כְּגוֹן הָאָדֹם וְהַיָּרֹק וְכַיּוֹצֵא בָהֶם, שֶׁאִם כָּתַב אֲפִלּוּ אוֹת אַחַת בִּשְׁאָר מִינֵי צִבְעוֹנִים אוֹ בְּזָהָב, פָּסוּל. \u0005הַגָּה: וְכֵן אָסוּר לִכְתֹּב שׁוּם שֵׁם מִסֵּפֶר עֶשְׂרִים וְאַרְבַּע סְפָרִים, שֶׁלֹּא בִּדְיוֹ (ר' יְרוּחָם בְּשֵׁם אֶבֶן יַרְחִי)\u0006. וְיֵשׁ אוֹמְרִים דְּלֹא בָּעֵינָן דְּיוֹ רַק בְּסֵפֶר תּוֹרָה \u0005(בְּמָרְדְּכַי ה\"ק)\u0006.\nסֵפֶר תּוֹרָה צָרִיךְ לְכָתְבוֹ \u0010c6\u0011 בְּיָמִין. \u0005יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לִכְתֹּב בְּקֻלְמוֹס שֶׁל \u0010c7\u0011 קָנֶה וְלֹא בְּנוֹצָה (מָרְדְּכַי פ\"ק דְּגִטִּין)\u0006.",[],["\u0003מעובדין. \u0004 כתב הש\"ך משמע אם עבדו שלא לשמה אפי' בדיעבד פסול ואפילו כתבו עליו ס\"ת פסול אבל הרא\"ש והטור הביאו תשוב' הגאון שכתב הלכך אם יש להם יכולת להחזיר יריעות הקלף לידי מתוח ולהעביר עליו סיד לשמה מה טוב ואם אין יכולת לעשות כן ואין להם ס\"ת אחרת ולא קלפים אחרים יכתבו בו אף על פי שאינו מעובד לשמה ויקראו בה בצבור עכ\"ל:","\u0003שיאמר. \u0004 בפירוש ולא במחשבה לחוד כמ\"ש בא\"ח סימן ל\"ב ס\"ח:","\u0003ס\"ת. \u0004 כתב ב\"י בא\"ח סימן ל\"ב אם מעובד לשם מזוזה פסול לתפילין ודאי דה\"ה אם מעובד לתפילין פסול לספר תורה דקדושת ס\"ת חמורה מתפילין עכ\"ל ד\"מ:","\u0003בתחלה. \u0004 כתב הט\"ז וה\"ה כי מסייע בגמר ודאי מהני אלא דבא למעט שא\"צ לסייע מתחלה ועד סוף ומ\"מ נ\"ל שלא נקרא סיוע אלא במעשה העיבוד עצמו אבל לא במה שמסייע להשחיר את העורות של תפילין וכל הנוהג קולא בזה הוא מחטיא רבים עכ\"ל \u0005(ובדיעבד אפשר אפילו לא סייע כלל אלא שאומר לעובד כוכבים שיעבדנו לשמה די בכך ש\"ך. וכתב הטור דתיקון הקלף והשרטוט א\"צ שיהא לשמה:\n\n\u0006","\u0003הגויל. \u0004 כתב הט\"ז ג' שמות יש בזה גויל קלף דוכסוסטוס פי' גויל עור שנגרד ותקנו במקום השער ובמקום הבשר לא תקנו וכותבין בו במקום שער קלף ודוכסוסטוס הוא עור הנחלק לשנים חלק החיצון של צד שער נקרא קלף וכותבין בצד פנימי של בשר וחלק הפנימי שבצד הבשר נקרא דוכסוסטוס וכותבין בו בצד החיצון שכלפי שער. קלפים שלנו היינו שמגרדין ומתקנין את העור מב' צדדים יש בו דין קלף של הש\"ס שכותבין בו לצד הבשר והם יותר נאים וקלים מגויל לכך כתב רמ\"א שהם יותר מובחרים וכתב הש\"ך דמדברי התוספות נראה שהספרים נכתבים על הנייר שאינו מחוק אבל מדברי סה\"ת ושאר פוסקים נראה שצריך לכתוב דוקא על עור בהמה טהורה וכן מבואר להדיא בתוספות במנחות דף ל\"א ע\"ב עכ\"ל:","\u0003כשר. \u0004 מפני שהוא שחור:","\u0003בימין. \u0004 ועיין בא\"ח סימן ל\"ב ס\"ח דאיטר יד שמאל דידיה הוא ימין ש\"ך:","\u0003קנה. \u0004 כתב הט\"ז שמעתי אומרים שאין בספרים הנדפסים קדושה כמו הנכתבים בכתב ולי נראה שאין חילוק בזה כלל \u0005(שמעשה הדפוס הוא קודש ככתב)\u0006 ומביא ראיות מהש\"ס דמוכח דדפוס מקרי שפיר כתיבה ומכל מקום לענין גט ודאי אין לעשות בדפוס כיון שקצת דומה לחקיקה אבל לענין קדושת הספרים כל המקיל עתיד ליתן את הדין עכ\"ל: \u0003ערב\u0004"]],["אֵין עוֹשִׂין סֵפֶר תּוֹרָה לֹא אָרְכּוֹ יָתֵר עַל הֶקֵּפוֹ, וְלֹא הֶקֵּפוֹ יָתֵר עַל אָרְכּוֹ. \u0005פֵּרוּשׁ, יְכַוֵּן שֶׁיְּהֵא חוּט הַמַּקִּיף יְרִיעוֹת כָּל הַסֵּפֶר לְאַחַר שֶׁיִּתְפֹּר וְיִגְלֹל, אָרֹךְ כְּשִׁעוּר אָרְכּוֹ (טוּר)\u0006. וְכַמָּה הוּא אָרְכּוֹ, בַּגְּוִיל, שִׁשָּׁה טְפָחִים שֶׁהֵם כ\"ד אֶצְבָּעוֹת \u0010c0\u0011 בְּרֹחַב אֲגֻדַּל שֶׁל יָד. וּבַקְּלָף, אוֹ פָּחוֹת אוֹ יוֹתֵר, וְהוּא שֶׁיְּהֵא אָרְכּוֹ כְּהֶקֵּפוֹ. וְכֵן אִם עָשָׂה בַּגְּוִיל \u0005(פָּחוֹת מִ)\u0006 \u0005שִּׁשָּׁה טְפָחִים, וּמִעֵט הַכְּתָב, אוֹ יִתֵּר עַל שִׁשָּׁה וְהִרְחִיב בַּכְּתָב, עַד שֶׁיִּהְיֶה אָרְכּוֹ כְּהֶקֵּפוֹ, הֲרֵי זֶה כְּמִצְוָה. וְהָעַמּוּד \u0010c1\u0011 שֶׁבְּתוֹךְ הַסֵּפֶר, יֵשׁ אוֹמְרִים דְּמִצְרַף לַהֶקֵּף\u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nאֹרֶךְ כָּל שִׁיטָה שְׁלֹשִׁים אוֹתִיּוֹת, כְּדֵי לִכְתֹּב לְמִשְׁפְּחוֹתֵיכֶם ג' פְּעָמִים. וְלֹא תִּהְיֶה קְצָרָה מִזֶּה, כְּדֵי שֶׁלֹּא יְהֵא הַדַּף נִרְאֶה כְּאִגֶּרֶת. וְלֹא אֲרֻכָּה יוֹתֵר עַל זֶה, כְּדֵי שֶׁלֹּא יִהְיוּ עֵינָיו \u0010c2\u0011 מְשׁוֹטְטוֹת בַּכְּתָב \u0005(ל' רַמְבַּ\"ם פ\"ז מֵהִלְכוֹת סֵפֶר תּוֹרָה ד\"ד)\u0006.\nאֵין עוֹשִׂין יְרִיעָה \u0010c3\u0011 פָּחוֹת מִג' דַּפִּין, וְלֹא יוֹתֵר עַל ח'. נִזְדַּמְּנָה לוֹ יְרִיעָה בַּת ט' דַּפִּין, לֹא יְחַלְּקֶנָּה בְּעִנְיָן שֶׁהָיוּ ג' דַּפִּין בְּאַחַת וְשִׁשָּׁה בַּשְּׁנִיָּה, אֶלָּא שֶׁיִּהְיוּ ד' בְּאַחַת וַחֲמִשָּׁה בַּשְּׁנִיָּה. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּכָל הַיְרִיעוֹת שֶׁבַּסֵפֶר, חוּץ מִבָּאַחֲרוֹנָה. אֲבָל בְּסוֹף הַסֵפֶר, \u0010c4\u0011 אֲפִלּוּ פָּסוּק אֶחָד עוֹשִׂין אוֹתוֹ דַּף לְבַדּוֹ וְתוֹפְרִים אוֹתוֹ עִם שְׁאָר יְרִיעוֹת.\nכְּשֶׁיִּגְמֹר אֶת הַתּוֹרָה, צָרִיךְ שֶׁיִּגְמֹר בָּאֶמְצַע שִׁיטָה שֶׁבְּסוֹף הַדַּף. וְאִם נִשְׁאַר מִן הַדַּף שִׁיטִין הַרְבֵּה, מְקַצֵּר וְעוֹלֶה \u0005וְעוֹשֶׂה אוֹתִיּוֹת אֲרֻכּוֹת מִמַּטָּה לְמַעְלָה, כְּדֵי שֶׁתַּחֲזִיק תֵּבָה אַחַת ד' וְה' שִׁיטִין (טוּר)\u0006. וּמַתְחִיל מִתְּחִלַּת הַשִּׁיטָה שֶׁבְּסוֹף הַדַּף, וְלֹא יִגְמֹר אֶת הַשִּׁיטָה, וּמִתְכַּוֵּן עַד שֶׁיִּהְיֶה לְעֵינֵי כָּל יִשְׂרָאֵל \u0005(דְּבָרִים לד, יב)\u0006 בְּאֶמְצַע שִׁיטָה שֶׁבְּסוֹף הַדַּף.",[],["\u0003אגודל. \u0004 כתב הרמב\"ם פ\"י מהל' ס\"ת דין רוחב גודל האמור בכל השיעורים האלו ובשאר שיעורי התורה כולם היא אצבע הבינוני וכבר דקדקנו בשיעורו ומצאנוהו רחב שבע שעורות בינוניות זו בצד זו בדוחק והן באורך שתי שעורות בריוח עכ\"ל:","\u0003שבתוך. \u0004 כתב הט\"ז שצ\"ל בסוף. אבל עמוד הראשון שבתחלתו אין מצטרף ונלמד מחלל הארון ב' טפחים והיינו שהעמוד שבסוף נכלל בחשבון שהוא מוכרח להיות בתוך הספר אחר הגלילה אבל עמוד הראשון היה מונח על הס\"ת ואינו נחשב בכלל עובי הס\"ת עכ\"ל וכתב הש\"ך שדעת הרמב\"ם דהיקף ששה טפחים בלא העמודים הם וע\"ש בנתינת סדר היאך יעשה הרוצה לכתוב ס\"ת שיעלה לו ארכו כהיקפו ע\"כ:","\u0003משוטטות. \u0004 פירוש כשהשיטות ארוכות טועה בראשי השיטות וכתב הגהת מיי' דשיעור ג\"פ למשפחותיכם היינו דוקא בכתיבה דקה אבל בכתיבה גסה הכל לפי הנוי ואין עיניו משוטטות כיון שהכתיבה גסה וכן נוהגין. ש\"ך:","\u0003פחות. \u0004 ומבואר בטור שעיקר הנוי הוא משל ד' או ה' אלא שאין איסור אלא בב' או תשעה ומדברי הסמ\"ג משמע דאם לא נכתב רק שני דפין ביריעה כשר בדיעבד וכן משמע בהרמב\"ם דלא חשיב זה בין הפסולים עכ\"ל הט\"ז:","\u0003פסוק. \u0004 כתב הש\"ך אע\"פ שאין בפסוק האחרון תיבות כמנין השיטות יעשה אותיות ארוכות כדי שתחזיק תיבה אחת ד' או ה' שיטין כדי שיסיים בסוף הדף. כ\"כ הטור ומשמע הא אם יש הרבה פסוקים יכול לכתוב בכל שיטה תיבה אחת כמנין השיטין מיהו כל זה בסוף התורה כיון שא\"א בענין אחר אבל באמצע התורה אין לעשות כן להמשיך האותיות לא לארכן ולא לרחבן אלא יכתוב כהלכתן מיהו אם אירע שהסופר כתב כן לא נפסל בשביל כך עכ\"ל:"]],["שִׁעוּר הַגִּלָּיוֹן לְמַטָּה, ד' אֶצְבָּעוֹת בְּגוּדָל. וּלְמַעְלָה, ג'. וּבֵין כָּל דַּף וְדַף, שְׁנַיִם. לְפִיכָךְ צָרִיךְ לְהַנִּיחַ בִּתְחִלַּת כָּל יְרִיעָה וְסוֹפָהּ כְּרֹחַב אֶצְבַּע, וּכְדֵי תְּפִירָה, וְנִמְצָא כְּשֶׁתּוֹפֵר הַיְרִיעוֹת בְּיַחַד יִהְיֶה בֵּין כָּל דַּף וְדַף בְּכָל הַסֵפֶר רֹחַב שְׁתֵּי אֶצְבָּעוֹת. וּבֵין שִׁיטָה לְשִׁיטָה, כִּמְלֹא רֹחַב שִׁיטָה. וּבֵין כָּל חֻמָּשׁ וְחֻמָּשׁ, ד' שִׁיטִין פְּנוּיוֹת בְּלֹא כְּתָב, וְיַתְחִיל הַחֻמָּשׁ מִתְּחִלַּת שִׁיטָה חֲמִישִׁית. וְיַנִּיחַ בִּתְחִלָּתוֹ וּבְסוֹפוֹ כְּדֵי לִגְלֹל עַל הָעַמּוּד, וְעוֹד שְׁתֵּי אֶצְבָּעוֹת שֶׁיִּשָּׁאֲרוּ בֵּין הָעַמּוּד וְהַדַּף.\nלֹא \u0010c0\u0011 יְמַעֵט הַכְּתָב מִפְּנֵי רֶוַח שֶׁלְּמַטָּה וּלְמַעְלָה, וְלֹא מִפְּנֵי רֶוַח שֶׁבֵּין פָּרָשָׁה לְפָרָשָׁה.\nנִזְדַּמְּנָה לוֹ תֵּבָה בַּת ה' אוֹתִיּוֹת, לֹא יִכְתֹּב שְׁתַּיִם בְּתוֹךְ הַדַּף וג' חוּץ לַדַּף, אֶלָּא כּוֹתֵב ג' בְּתוֹךְ הַדַּף וּשְׁתַּיִם חוּץ לַדַּף. וְאִם אֵין מָקוֹם כְּדֵי לִכְתֹּב ג' בְּתוֹךְ הַדַּף, יַנִּיחַ הַמָּקוֹם חָלָק וְלֹא יִמְשֹׁךְ הָאוֹתִיּוֹת לַעֲשׂוֹתָן גְּדוֹלוֹת מֵחֲבֶרְתָּן כְּדֵי לְמַלְּאוֹת עַד סוֹף הַדַּף \u0005(הגהמי\"י בְּשֵׁם הרמ\" ךָ)\u0006. וְתֵבָה בַּת ג' אוֹתִיּוֹת, יָכוֹל לִכְתֹּב מִמֶּנָּהּ שְׁתַּיִם חוּץ לַדַּף, אַף עַל פִּי שֶׁמִּעוּטָהּ בִּפְנִים. אֲבָל אִם אֵין בָּהּ אֶלָּא שְׁתֵּי אוֹתִיּוֹת, לֹא יִכְתְּבֶנָּה \u0010c1\u0011 חוּץ לַדַּף. \u0005הַגָּה: וַאֲפִלּוּ אִם ב' אוֹתִיּוֹת הֵם מִתֵּבָה גְּדוֹלָה \u0010c2\u0011 וְנִרְאִים כְּמוֹ תֵּבָה בִּפְנֵי עַצְמָהּ, לֹא יִכְתְּבֵם עַל הַגִּלָּיוֹן (בֵּית יוֹסֵף בְּשֵׁם מָרְדְּכַי שכ\"כ בְּשֵׁם סמ\"ק)\u0006.\nנִזְדַּמְּנָה לוֹ תֵּבָה בַּת עֶשֶׂר אוֹתִיּוֹת, אוֹ פָּחוֹת אוֹ יוֹתֵר, וְלֹא נִשְׁאַר מֵהַשִּׁיטָה כְּדֵי לִכְתֹּב אֶת כֻּלָּהּ בְּתוֹךְ הַדַּף, אִם יָכוֹל \u0010c3\u0011 לִכְתֹּב חֶצְיָהּ בְּתוֹךְ הַדַּף וְחֶצְיָהּ חוּץ לַדַּף, כּוֹתֵב. וְאִם לָאו, מַנִּיחַ הַמָּקוֹם פָּנוּי וּמַתְחִיל מִתְּחִלַּת הַשִּׁיטָה.\nכָּל אֵלּוּ הַדְּבָרִים אֵינָם אֶלָּא לְמִצְוָה מִן הַמֻּבְחָר, וְאִם שִׁנָּה כָּשֵׁר.\nשָׁכַח לִכְתֹּב אֶת הַשֵּׁם כֻּלּוֹ, תּוֹלֶה אוֹתוֹ בֵּין הַשִּׁיטוֹת. אֲבָל מִקְצָת הַשֵּׁם בַּשִּׁיטָה וּמִקְּצָתוֹ תָּלוּי, פָּסוּל. וּבִשְׁאָר תֵּבוֹת, אִם שָׁכַח, כּוֹתֵב מִקְצָת הַתֵּבָה בַּשִּׁיטָה וּמִקְצָתָהּ לְמַעְלָה. \u0005הַגָּה: יֵשׁ סוֹפְרִים מְדַקְדְּקִים לִכְתֹּב (אוֹתִיּוֹת)\u0006 \u0010c4\u0011 בי\"ה שמ\"ו בְּרֹאשׁ הָעַמּוּדִים, וְכֵן קְצָת מְדַקְדְּקִים לִכְתֹּב בְּרֹאשׁ כָּל עַמּוּד ו' וְקוֹרִין אוֹתוֹ וָוֵי הָעַמּוּדִים, וְאֵין לְדַקְדֵּק בְּכָל זֶה, וַאֲפִלּוּ הַמְדַקְדֵּק יִזָּהֵר שֶׁלֹּא יְמַעֵט אוֹ יַרְחִיב הַכְּתָב לִפְעָמִים מִשּׁוּם זֶה \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ז)\u0006, כִּי כָּל דְּבָרִים אֵלּוּ אֵין לָהֶם שֹׁרֶשׁ עַל מַה שֶּׁיִּסְמְכוּ \u0005(בֵּית יוֹסֵף)\u0006.",[],["\u0003ימעט. \u0004 פי' שלא יעשה אותיות קטנות בשטה העליונה ותחתונה כדי שישאר שיעור גליון. ובין פרשה לפרשה פי' כגון פרשה סתומה שצריכה להיות פתוחה באמצע וכתובה מב' צדדים לא ימעט הכתב כדי להתחיל בסוף עכ\"ל הטור וכתב הט\"ז ומשמע דבדיעבד מותר וכמו שסיים בסוף הסימן כל אלו הדברים למצוה מן המובחר:","\u0003חוץ. \u0004 כתב הש\"ך דוקא כולה חוץ לדף לא יכתוב אבל אות אחד בפנים ואחד בחוץ מותר ודלא כהלבוש:","\u0003ונראים. \u0004 ומדברי הט\"ז ושאר פוסקים נראה דאין קפידא בזה רק דוקא תיבה שלימה אסור. ש\"ך:","\u0003חציה. \u0004 כתב הש\"ך משמע דאפילו יותר מג' אותיות יכול לכתוב חוץ לדף כיון שאינה רוב התיבה וכ\"פ הב\"ח אבל לא משמע כן בכל הפוסקים וכ\"כ המחבר עצמו בא\"ח סימן ל\"ב סל\"ג גבי תפילין שלא יכתוב ג' אותיות חוץ לשטה ותימה שנראה שדברי המחבר סותרים זה את זה וצ\"ע עכ\"ל:","\u0003בי\"ה שמ\"ו. \u0004 והם ב' דבראשית. יו\"ד יהודה אתה יודוך. ה\"א הבאים אחריהם. שי\"ן שמר לך ויש עושים ש' שופטים ושוטרים. מ\"ם מה טובו. וי\"ו ואעידה בם כן הוא בהגהת סמ\"ק אבל מדברי המרדכי נראה דוי\"ו של בי\"ה שמ\"ו הוא וי\"ו אחרת חוץ מואעידה בם ובהגהת מרדכי כתב מצאתי דבי\"ה שמ\"ו אפי' בדיעבד פסול אם לא נכתב בראש העמוד וכתב הט\"ז ראיתי מעשה סופרים בורים הרבה כשאירע להם כ\"ף פשוטה בסוף השטה ויש עוד מקום פנוי קצת וא\"א לכתוב עוד תיבה אחרת הם מושכים הכ\"ף פשוטה כזה ד וזהו פיסול גמור שהוא דלי\"ת ולא ך' אלא הכ\"ף פשוטה צריכה להיות רגל שלה פי שנים מן הגג וס\"ת כזאת פסולה לקרות בה כלל וכשמתקן כ\"ף פשוטה הזאת צריך למחוק אותה כולה ואח\"כ יכתוב מחדש כראוי דאם לא ימחוק רק קצת מגגה יהיה כחק תוכות וכמ\"ש בא\"ח סי' ל\"ב סי\"ז ע\"ש עכ\"ל:"]],["צָרִיךְ שֶׁיֹּאמַר הַסוֹפֵר כְּשֶׁיַּתְחִיל לִכְתֹּב: סֵפֶר זֶה אֲנִי כּוֹתֵב לְשֵׁם קְדֻשַּׁת סֵפֶר תּוֹרָה. וּמַסְפִּיק לְכָל הַסֵפֶר.\nצָרִיךְ שֶׁיִּהְיֶה לְפָנָיו סֵפֶר אַחֵר, שֶׁיַּעְתִּיק מִמֶּנּוּ, \u0010c0\u0011 שֶׁאָסוּר לִכְתֹּב אוֹת אַחַת שֶׁלֹּא מִן הַכְּתָב. וְצָרִיךְ שֶׁיִּקְרָא כָּל תֵּבָה בְּפִיו קֹדֶם שֶׁיִּכְתְּבֶנָּה.\nיִכְתֹּב כְּתִיבָה נָאָה וּמְיֻשֶּׁרֶת, תַּמָּה. וְאִם כָּתַב אָלֶף לָמֶד בְּיַחַד, כָּזֶה ﭏ, אֵינוֹ כָּשֵׁר.\nצָרִיךְ שֶׁכָּל אוֹת תְּהֵא מֻקֶּפֶת גְּוִיל מֵאַרְבַּע רוּחוֹתֶיהָ, שֶׁלֹּא תִּדְבַּק אוֹת בַּחֲבֶרְתָּהּ, אֶלָּא יְהֵא בֵּינֵיהֶם כְּחוּט הַשַּׂעֲרָה. וְלֹא יִהְיוּ מֻפְרָדוֹת הַרְבֵּה זוֹ מִזּוֹ, כְּדֵי שֶׁלֹּא תְּהֵא תֵּבָה אַחַת נִרְאֵית כִּשְׁתַּיִם. וְיִהְיֶה בֵּין \u0010c1\u0011 תֵּבָה לְתֵבָה כִּמְלֹא אוֹת קְטַנָּה, וְלֹא יְקָרְבֵם בְּיוֹתֵר שֶׁלֹּא יִהְיוּ שְׁתֵּי תֵּבוֹת נִרְאוֹת כְּאַחַת. וְאִם שִׁנָּה, שֶׁהִרְחִיק בֵּין הָאוֹתִיּוֹת עַד שֶׁהַתֵּבָה נִרְאֵית כִּשְׁתַּיִם, אוֹ שֶׁקֵּרֵב שְׁתֵּי תֵּבוֹת עַד שֶׁנִּרְאוֹת כְּאַחַת, פָּסוּל.\nצָרִיךְ שֶׁלֹּא תִּפָּסֵל צוּרַת שׁוּם אוֹת עַד שֶׁאֵינָהּ נִקְרֵאת אוֹ דּוֹמָה לְאוֹת אַחֶרֶת, בֵּין בְּעִקַּר הַכְּתִיבָה, בֵּין בַּקֶּרַע, בֵּין בַּנֶּקֶב שֶׁנִּקָּב בָּהּ, בֵּין בְּטִשְׁטוּשׁ. \u0005וְיָכוֹל \u0010c2\u0011 לִטֹּל דְּיוֹ מִן אוֹת הַכָּתוּב כְּשֶׁצָּרִיךְ לִדְיוֹ (הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006 אוֹ שֶׁרוֹצֶה \u0010c3\u0011 לִגְלֹל הַסֵּפֶר \u0005(הָרֹא\"שׁ כְּלָל ג')\u0006.\nצָרִיךְ לִזָּהֵר בְּתִקּוּן הָאוֹתִיּוֹת וּבְזִיּוּנָן, כְּמוֹ שֶׁנִּתְבָּאֵר בְּאֹרֶךְ בְּהִלְכוֹת תְּפִלִּין סִימָן ל\"ב וסִימָן ל\"ו.\nסֵפֶר הַמְנֻקָּד, פָּסוּל. \u0010c4\u0011 וַאֲפִלּוּ הֵסִירוּ מִמֶּנּוּ הַנִּקּוּד. וְכֵן סֵפֶר שֶׁיֵּשׁ בּוֹ \u0010c5\u0011 פִּסוּק פְּסוּקִים, פָּסוּל. \u0005הַגָּה: וְדַוְקָא שֶׁעָשָׂה הֶפְסֵק בִּדְיוֹ. אֲבָל אִם הִנִּיחַ אֲוִיר בֵּין הַפְּסוּקִים, כָּל שֶׁאֵין בּוֹ שִׁעוּר פָּרָשָׁה, כְּשֵׁרָה (תְּשׁוּבַת ריב\"ש)\u0006. וְסֵפֶר תּוֹרָה שֶׁעֵרֵב בּוֹ הָאוֹתִיּוֹת, כְּמוֹ בְּגֵט, אֵינָהּ פְּסוּלָה. אֲבָל לְכַתְּחִלָּה אֵין לַעֲשׂוֹת כֵּן \u0005(שָׁם סִימָן קמ\"ו)\u0006.",[],["\u0003שאסור. \u0004 וכתב הר\"ן דמוכח מהירושלמי דאם כתב שלא מן הכתב אסור לקרות בו שלא בשעת הדחק וה\"ר מנוח כתב דוקא לכתחלה אבל אם עבר ועשה כך לא פסל וצ\"ע אי אותן פרשיות שבתפילין יכול לכתוב בס\"ת שלא מן הכתב כיון דגריסן עכ\"ל ועיין בא\"ח סימן ל\"ב סכ\"ט ונ\"א וכתב הט\"ז בשם סמ\"ג אף שאמר בהתחלת הכתיבה שכותב לשם קדושת ס\"ת יאמר עוד וכל האזכרות שבו לשם קדושת השם ע\"כ ונראה שכן נכון דשמא ישכח אח\"כ לקדש השם במקומו עכ\"ל:","\u0003כמלא. \u0004 כתב הט\"ז דשיעור זה אינו אלא לכתחלה אבל בדיעבד אינו פסול אלא כשהן ממש כאחת על פי תינוק דלא חכים ולא טיפש וכ\"ש אם נחסר איזה אות בסוף התיבה ותולה אותו בין השורות דלא נפסל מטעם שנאמר דהוי כאלו נכתב אות התלוי ממש בשורה ואם כן אין הפסק בין התיבות כלל ופסול הא ליתא דהא עכ\"פ אנו רואים עכשיו שהם ב' תיבות וכבר טעה בזה מורה אחד עכ\"ל:","\u0003דיו. \u0004 כתב הט\"ז היינו לצורך כתיבת ס\"ת אבל לא לצורך דבר אחר והש\"ך כתב דמשמע שאפילו מהשם יכול ליטול דיו ואפילו לכתוב בו דבר חול מותר דאין כאן אכחושי מצוה מיהו נהי דמשום אכחושי מצוה ליכא מ\"מ משום בזוי מצוה איכא ליטול מהשם לכתוב תיבה אחרת או ליטול מס\"ת ולכתוב בו דבר חול ולמ\"ד דאין מדליקין מנר לנר משום בזוי מצוה כמ\"ש בא\"ח סימן תר\"ע ה\"ה הכא אסור אא\"כ שנוטל הדיו כדי שתתייבש מהר ולא להשתמש בו דבר וכן נ\"ל עכ\"ל:","\u0003לגלול. \u0004 פי' הרא\"ש בתשו' בעוד הדיו לח הוצרך לגלול הס\"ת ונטל בקולמוס הדיו הכתובה כדי שתתייבש התיבה מהר ולא תמחק וכתב הט\"ז נראה ברור דלא התיר הרא\"ש אלא בטובל את הקולמוס ושואב מותרות הדיו ובו כותב אח\"כ בתורה אבל אם ילך לאיבוד מהדיו שנתקדשה כבר הוי בזוי מצוה ותו דקיי\"ל תשמישי קדושה אינן נזרקין \u0005(ובנה\"כ כ' דאין בזוי מצוה כלל דהכא עושה בשביל כבוד התורה שתמהר להתייבש ולא שייך בזה תשמישי קדושה אינן נזרקין ע\"ש)\u0006:","\u0003הסירו. \u0004 כתב הט\"ז וא\"ל למה יגרע מכותב מ\"ם פתוחה ונדבקה דמהני אם גורר החרטום לחוד ונשאר כעין נו\"ן ואח\"כ כותב חרטום מחדש דכאן גרע טפי כיון שנראה כוונת הסופר שאינו חושש למסורת כלל ובודאי לשם זה כתבו והוה כמזויף מתוכו ופסול לגמרי משא\"כ במקום שכתב בשוגג איזה טעות עכ\"ל:","\u0003פיסוק. \u0004 ונראה דאם היה בו פיסוק שיש תקנה לגרור אותה ול\"ד לניקוד ששם עושה פיסול בגוף התיבה שנשתנה משמעותה בין מקרא למסורת אבל בפיסוק פסוקים אין פירוש התיבות משתנים ט\"ז. וכתב עוד וראיתי בהרבה ס\"ת שחם נזדמן השם בסוף שטה עושים סמוך להשם שני שרטוטין בדיו כזה ויש בזה עבירה שעושה שינוי ממה שהיה בתורת משה ע\"כ יש לגרוד אותן השרטוטין יגמרי ועי' בסי' רע\"ו ס\"א. עוד נ\"ל בס\"ת שאין לה נקודות הראויות להיות על איזה מקומות כגון על אליו איה שרה או בשאר מקומות שאין לפוסלה מלקרות בה אף על פי שעדיין לא נתקנה שהנקודות הם רק מתקנת עזרא כמ\"ש התוספות בזבחים פרק רבי ישמעאל עכ\"ל [צ\"ל בפיסקי תוס' פ' כל קרבנות סי' רל\"ב]:"]],["פָּרָשָׁה פְּתוּחָה שֶׁעֲשָׂאָהּ \u0010c0\u0011 סְתוּמָה, אוֹ סְתוּמָה שֶׁעֲשָׂאָהּ פְּתוּחָה, יִגָּנֵז. \u0005הַגָּה: \u0010c1\u0011 וְיֵשׁ אוֹמְרִים דְּמֻתָּר לְתַקְּנוֹ, כְּמוֹ בִּשְׁאָר טָעֻיּוֹת (הָרֹא\"שׁ וְהָרַשְׁבָּ\"א וריב\"ש)\u0006. וְכֵן נָהֲגוּ הַסּוֹפְרִים לְתַקְּנוֹ, אִם אֶפְשָׁר לוֹ לִמְחֹק שֶׁלֹּא יִפְגַּע בַּשֵּׁם, כִּי אֵין לוֹ לַחְתֹּךְ הַשֵּׁם וְלַעֲשׂוֹת \u0010c2\u0011 נְקָבִים בַּיְּרִיעָה \u0005(הָרֹא\"שׁ כְּלָל ג')\u0006.\nבְּצוּרַת פְּתוּחָה וְצוּרַת סְתוּמָה יֵשׁ מַחֲלֹקֶת בֵּין הָרַמְבַּ\"ם וְהָרֹא\"שׁ, וִירֵא שָׁמַיִם יֵצֵא אֶת כֻּלָּם וְיַעֲשֶׂה בְּעִנְיָן שֶׁבְּפָרָשָׁה פְּתוּחָה יְסַיֵּם פָּרָשָׁה שֶׁלְּפָנֶיהָ בְּאֶמְצַע שִׁיטָה, וְיִשְׁתַּיֵּר בְּסוֹפָהּ חָלָק כְּדֵי \u0010c3\u0011 \u0010c4\u0011 תֵּשַׁע אוֹתִיּוֹת, וְיַתְחִיל לִכְתֹּב בְּרֹאשׁ שִׁיטָה שֶׁתַּחְתֶּיהָ. וּבְפָרָשָׁה סְתוּמָה, תָּמִיד יְסַיֵּם פָּרָשָׁה שֶׁלְּפָנֶיהָ בִּתְחִלַּת שִׁיטָה וְיַנִּיחַ חָלָק כְּדֵי תֵּשַׁע אוֹתִיּוֹת, וְיַתְחִיל לִכְתֹּב בְּסוֹף אוֹתָהּ שִׁיטָה עַצְמָהּ, וְלֹא יְשַׁנֶּה לַעֲשׂוֹת צוּרָה אַחֶרֶת לֹא לִפְתוּחָה וְלֹא לִסְתוּמָה, וּבְהָכֵי הָוֵי כָּשֵׁר בֵּין לְהָרַמְבַּ\"ם בֵּין לְהָרֹא\"שׁ. \u0005הַגָּה: וְאִם לֹא יוּכַל לְכַוֵּן בְּכָךְ, לֹא יָסוּר מִדִּבְרֵי \u0010c5\u0011 הָרַמְבַּ\"ם בָּזֶה, כִּי עָלָיו סָמְכוּ הָאַחֲרוֹנִים וְכָתְבוּ שֶׁדְּבָרָיו הֵם עִקָּר (מ\"כ בְּשֵׁם חָכָם א')\u0006. וּמִכָּל מָקוֹם אִם נִמְצָא סֵפֶר תּוֹרָה שֶׁאֵינָהּ \u0010c6\u0011 כְּתוּבָה לְפִי דְּבָרָיו, אֵין לְפָסְלָהּ, כִּי יֵשׁ גְּדוֹלִים שֶׁיֵּשׁ לָהֶם סְבָרוֹת אֲחֵרוֹת בָּזֶה \u0005(ר\"י מִינְץ סִימָן ח')\u0006.\nכָּתַב הַשִּׁירָה כִּשְׁאָר הַכְּתָב, אוֹ שֶׁכָּתַב שְׁאָר הַכְּתָב כַּשִּׁירָה, פָּסוּל. וְדַוְקָא שֶׁכָּתַב הַשִּׁירָה כִּשְׁאָר הַכְּתָב בְּלֹא פִּזּוּר, אֲבָל אִם שִׁנָּה בְּפִזּוּר מִמַּה שֶּׁנָּהֲגוּ, לֹא פָּסַל, וּבִלְבַד שֶׁיְּהֵא \u0010c7\u0011 אָרִיחַ עַל גַּבֵּי לְבֵנָה.\nשִׁירַת הַיָּם כּוֹתְבִים אוֹתָהּ בִּשְׁלֹשִׁים שִׁיטוֹת. שִׁיטָה רִאשׁוֹנָה, כְּדַרְכָּהּ, \u0010c8\u0011 וּשְׁאָר שִׁיטוֹת, אַחַת מַנִּיחִין בְּאֶמְצַע רֶוַח אֶחָד, וְאַחַת מַנִּיחִין הָרֶוַח בִּשְׁנֵי מְקוֹמוֹת בָּאֶמְצַע, עַד שֶׁתִּמָּצֵא הַשִּׁיטָה חֲלוּקָה לְשָׁלֹשׁ, וְנִמְצָא רֶוַח כְּנֶגֶד הַכְּתָב, וּכְתָב כְּנֶגֶד הָרֶוַח.\nצוּרַת שִׁירַת הַאֲזִינוּ, כָּל שִׁיטָה יֵשׁ בָּאֶמְצַע רֶוַח אֶחָד, וְנִמְצֵאת כָּל שִׁיטָה חֲלוּקָה לִשְׁתַּיִם, וְכוֹתְבִים אוֹתָהּ בְּשִׁבְעִים שִׁיטוֹת.\nכָּתַב הַמָּלֵא חָסֵר, אוֹ הֶחָסֵר מָלֵא, אוֹ שֶׁכָּתַב מִלָּה שֶׁהִיא קְרִי וּכְתִיב בִּקְרִיאָתָהּ, כְּגוֹן שֶׁכָּתַב: יִשְׁכָּבֶנָּה, בִּמְקוֹם ישגלנה \u0005(דְּבָרִים כח, ל)\u0006. אוֹ וּבַטְּחוֹרִים, בִּמְקוֹם ובעפולים \u0005(דְּבָרִים כח, כז)\u0006. וְכַיּוֹצֵא בָהֶן, פָּסוּל. \u0005הַגָּה: וְיֵשׁ עוֹד דְּבָרִים שֶׁנָּהֲגוּ בָּהֶן הַסּוֹפְרִים כְּמוֹ שֶׁהֶעְתִּיקוּ אִישׁ מִפִּי אִישׁ, כְּמוֹ בְּאוֹתִיּוֹת גְּדוֹלוֹת וּקְטַנּוֹת וְהַנְּקֻדּוֹת וְהַמְּשׁוּכוֹת. וְעוֹד נָהֲגוּ בְּמִנְיַן הַשִּׁיטִין לַעֲשׂוֹתָם לֹא פָּחוֹת ממ\"ח, וְיֵשׁ אוֹמְרִים מ\"ב, וְלֹא יוֹתֵר מִס'. וְעוֹד נָהֲגוּ בְּרָאשֵׁי הַשִּׁיטִין לְמַעְלָה מִשִּׁירַת הַיָּם ה' שִׁיטִין, וְזֶה הַתְחָלָתָן: הַבָּאִים (שְׁמוֹת יד, כח)\u0006, בַּיַּבָּשָׁה \u0005(שְׁמוֹת יד, כט)\u0006, ה' \u0005(שְׁמוֹת יד, ל)\u0006, מֵת \u0005(שְׁמוֹת יד, ל)\u0006. בְּמִצְרַיִם \u0005(שְׁמוֹת יד, לא)\u0006 וְכֵן לְמַטָּה מֵהַשִּׁירָה ה' שִׁיטִין, וְהַתְחָלָתָן: וַתִּקַּח \u0005(שְׁמוֹת טו, כ)\u0006, \u0005(אַחֲרֶיהָ)\u0006 \u0005(שְׁמוֹת טו, כ)\u0006, סוּס \u0005(שְׁמוֹת טו, כא)\u0006, וַיֵּצְאוּ \u0005(שְׁמוֹת טו, כב)\u0006, וַיָּבֹאוּ \u0005(שְׁמוֹת טו, כג)\u0006. \u0005(וְיִהְיוּ)\u0006 לְמַעְלָה מִשִּׁירַת הַאֲזִינוּ שִׁשָּׁה שִׁיטִין, וְהַתְחָלָתָן: וְאָעִידָה \u0005(דְּבָרִים לא, כח)\u0006, אַחֲרֵי \u0005(דְּבָרִים לא, כט)\u0006, הַדֶּרֶךְ \u0005(דְּבָרִים לא, כט)\u0006, בְּאַחֲרִית \u0005(דְּבָרִים לא, כט)\u0006, לְהַכְעִיסוֹ \u0005(דְּבָרִים לא כט)\u0006, קְהַל \u0005(דְּבָרִים לא, ל)\u0006 וּלְמַטָּה ה' שִׁיטִין, וְהַתְחָלָתָן: וַיָּבֹא \u0005(דְּבָרִים לב, מד)\u0006, וַיְדַבֵּר \u0005(דְּבָרִים לב, מה)\u0006, \u0005(דִּבְרֵי)\u0006 אֲשֶׁר \u0005(דְּבָרִים לב, מו)\u0006, הַזֹּאת \u0005(דְּבָרִים לב, מז)\u0006, \u0005(אֲשֶׁר)\u0006 \u0005(דְּבָרִים לב, מז)\u0006. וְכָל אֵלּוּ הַדְּבָרִים לְמִצְוָה, וְאִם שִׁנָּה לֹא פָּסַל \u0005(הַכֹּל מִלְּשׁוֹן הַטּוּר)\u0006.",[],["\u0003סתומה. \u0004 וכן אם הפסיק והניח פנוי במקום שאין בו פרשה או שכתב כדרכו ולא הפסיק בריוח במקום הפרשה פסולה כ\"כ הרמב\"ם וכתב הב\"ח דדעת הטור דאם הניח פנוי במקום שא\"צ אינה פסולה בדיעבד ואין דבריו מוכרחים עכ\"ל הש\"ך וכן דעת הט\"ז כהש\"ך:","\u0003לתקנו. \u0004 ובלבד שלא ימעט הכתב בשביל ריוח בבין פרשה לפרשה מיהו דיעבד אינו מעכב אם מחק לפניו או לאחריו ומיעט הכתב ש\"ך וע\"ל ס\"ס רע\"ט והט\"ז כ' דלדעת הרשב\"א ההיא דלא ימעט הכתב אינו אלא לכתחלה שיזהר מזה שלא יבוא לידי כך אבל בדיעבד כשר למעט \u0005(ולפ\"ז אם כבר טעה ועשה מפתוחה סתומה או להיפך מקרי זה דיעבד ומותר לתקנו על ידי שימעט הכתב וק\"ל)\u0006:","\u0003נקבים. \u0004 כתב הש\"ך משמע דמשום כבוד השם הוא דאסור אבל לא בשאר תיבות ודלא כדמשמע מהלבוש שהטעם הוא מפני שעושה נקבים ביריעה ולפ\"ז אפילו בשאר תיבה אסור וז\"א דבשאר תיבה לא אסרו כלל ומ\"ש הרב ולעשות נקבים ביריעה לאו לאפוקי אם מסיר הקליפה הדקה העליונה כי זה נראה כ\"ש דאסור דהוא יותר בזיון וקרוב למחיקה אלא שבא למעוטי שאם היה השם כתוב מתחלה על מטלית שהיה דבוקה בנקב שאז מותר להסיר המטלית עם השם דדוקא לחתוך ולקדור השם הוא דאסור אבל במטלית שרי להסיר לצורך תקון עכ\"ל:","\u0003תשעה. \u0004 כב\"י כשאין בו שיעור ט' אותיות קטנות אפשר דפסול נמי הוי ומיהו יש פוסקים דבדיעבד סגי בריוח ג' אותיות עכ\"ל הש\"ך אבל הט\"ז כתב דלהלכה אין לנו אלא כדברי הש\"ע שהוא מוסכם מרוב הפוסקים:","\u0003אותיות. \u0004 דהיינו ג\"פ אשר:","\u0003הרמב\"ם. \u0004 וכתב הט\"ז דשני פלוגתות יש בין הרמב\"ם להרא\"ש חדא דאם עושה מקום פנוי בתחלת השטה כדי ט' אותיות ומתחיל הפרשה באמצע השטה זהו סתומה להרמב\"ם ופתוחה להרא\"ש שנית אם מסיים בסוף שטה או שיש מקום פנוי אלא שאין בו כשיעור ט' אותיות אח\"כ מניח שורה א' כולה פנויה ומתחיל הפרשה בשורה שאחריה בתחלתה זהו להרמב\"ם פתוחה ולהרא\"ש הוי סתומה והכלל להרמב\"ם אינה פתוחה רק המתחלת בראש השיטה ואין סתומה רק המתחלת באמצע השיטה או בסופה עכ\"ל וכתב הלבוש דלדעת הרמב\"ם נ\"ל דה\"ה אם נזדמנה לו כן בשטה התחתונה שבסוף הדף שלא נשאר אלא מעט או שגמר בסוף השטה מניח שטה העליונה שבראש הדף שאחריו חלק ויתחיל לכתוב בשניה נמצא שמניח פנוי ביניהם שטה ועיין בתשו' מהרש\"ל ס' ל\"ז וברמב\"ם פ\"ח מהס\"ת שהאריך לבאר הפרשיות סתומות ופתוחות:","\u0003כתובה. \u0004 כ' הש\"ך ומ\"מ משמע דהיינו דוקא כשנמצאת ס\"ת שאינה כתובה לפי דברי הרמב\"ם דיש לתלות ולומר שנכתב' ע\"פ איזה גדול אחד אבל אם ידוע שהוא טעות סופר שטעה ושינה מסדר הרמב\"ם במקום שאין שום פוסק חולק עליו נראה דפסולה היא אף בדיעבד וכ' עוד שנשאל ע\"ד הס\"ת שראוי להיות בפ' צו וידבר ה' דכל חלב פחוחה כאשר היא בכל ס\"ת ואינה פתוחה ורצו לפסלה והשיב דברור הדבר דספרא דוקנא כתבה ע\"פ הרמב\"ם שלא מנה זאת הפתוחה כלל במנינו של כל הפתוחות בתורה בודאי שס\"ת זו היא כשרה וישרה וברורה תורת ה' טהורה עכ\"ל:","\u0003אריח. \u0004 פירש הט\"ז \u0005(*)\u0006 דאריח בת ג' טפחים ולבינה היא טפח ומחצה ור\"ל האריח הוא הכתב והלבינה היא מקום פנוי והש\"ך פירש איפכא דהלבינה ג' טפחים ואריח טפח ומחצה:","\u0003ושאר. \u0004 דהיינו כצורה הזאת וכן כולם זה אחר זה עד גמירא ועיין ברמב\"ם עוד כמה דינים ומנהגים בכתיבת ס\"ת:"]],["טָעָה וְדִלֵּג תֵּבָה אוֹ יוֹתֵר, יָכוֹל לִתְלוֹתָהּ בֵּין הַשִּׁיטִין אֲבָל לֹא בָּרֶוַח שֶׁבֵּין דַּף לְדַף.\nאַף עַל פִּי שֶׁאוֹמֵר בִּתְחִלַּת הַסֵפֶר שֶׁכּוֹתְבוֹ לְשֵׁם קְדֻשַּׁת סֵפֶר תּוֹרָה, בְּכָל פַּעַם שֶׁכּוֹתֵב שֵׁם מֵהַשֵּׁמוֹת שֶׁאֵינָם נִמְחָקִים צָרִיךְ לוֹמַר שֶׁכּוֹתֵב לְשֵׁם קְדֻשַּׁת הַשֵּׁם. וְאִם לֹא עָשָׂה כֵן, \u0010c0\u0011 פָּסוּל \u0005(כֵּן נִרְאֶה מֵרֹא\"שׁ וְכֵן כָּתַב סְמַ\"ג וסה\"ת)\u0006. \u0005הַגָּה: כָּתַב שֵׁם אֱלֹהִים אֲחֵרִים לְשֵׁם קְדֻשָּׁה, אֵינוֹ פָּסוּל, דְּהָוֵי כְּמַקְדִּישׁ בַּעֲלֵי \u0010c1\u0011 מוּמִין לַמִּזְבֵּחַ, דְּאֵינָן קְדוֹשִׁים\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם רשב\"ץ)\u0006.\nכְּשֶׁכּוֹתֵב הַשֵּׁם, אֲפִלּוּ מֶלֶךְ יִשְׂרָאֵל שׁוֹאֵל בִּשְׁלוֹמוֹ, לֹא \u0010c2\u0011 יְשִׁיבֶנּוּ. וְאִם הָיָה כּוֹתֵב שְׁנֵי שֵׁמוֹת זֶה אַחַר זֶה, מֻתָּר לְהַפְסִיק בֵּינֵיהֶם, וּכְשֶׁיַּחֲזֹר לִכְתֹּב שֵׁם שֵׁנִי צָרִיךְ לַחֲזֹר לוֹמַר שֶׁהוּא כּוֹתְבוֹ לְשֵׁם קְדֻשַּׁת הַשֵּׁם.\nכְּשֶׁטּוֹבֵל הַקֻּלְמוֹס לִכְתֹּב הַשֵּׁם, לֹא יַתְחִיל מִיָּד הַשֵּׁם לִכְתֹּב, שֶׁמָּא יִהְיֶה עָלָיו רִבּוּי דְּיוֹ וְלֹא יֵצֵא הַכְּתָב מְיֻשָּׁר, אֶלָּא יְכַוֵּן לְהַנִּיחַ אוֹת אַחַת מִלִּכְתֹּב קֹדֶם הַשֵּׁם, וּבְאוֹתוֹ הָאוֹת יַתְחִיל לִכְתֹּב \u0005וְאִם לֹא עָשָׂה כֵן, \u0010c3\u0011 יְחַפֵּשׂ אַחַר אוֹת שֶׁצְּרִיכָה דְּיוֹ, וִימַלְּאֶנָּה, וְכוֹתֵב אֶת הַשֵּׁם (בֵּית יוֹסֵף בְּשֵׁם מ\"כ)\u0006.\nכָּתַב \u0010c4\u0011 הָאַזְכָּרוֹת בִּדְיוֹ וְזָרַק עֲלֵיהֶם זָהָב, פָּסוּל.\nשָׁכַח לִכְתֹּב הַשֵּׁם כֻּלּוֹ, תּוֹלֶה אוֹתוֹ בֵּין הַשִּׁיטוֹת. אֲבָל מִקְצָת הַשֵּׁם בַּשִּׁיטָה \u0010c5\u0011 וּמִקְּצָתוֹ תָּלוּי, פָּסוּל.\nמֻתָּר לִכְתֹּב הַשֵּׁם עַל מְקוֹם \u0010c6\u0011 הַמַּחַק וְעַל מְקוֹם הַגֶּרֶד. \u0010c7\u0011 \u0005וְאֵין חִלּוּק בָּזֶה בֵּין סֵפֶר תּוֹרָה לִשְׁאָר סְפָרִים (כ\"כ בס\"ה)\u0006.\nצָרִיךְ שֶׁיִּהְיוּ כָּל אוֹתִיּוֹת הַשֵּׁם בְּתוֹךְ הַדַּף, וְלֹא יֵצֵא מֵהֶם כְּלָל חוּץ לַדַּף.\nאָסוּר לִמְחֹק אֲפִלּוּ אוֹת אַחַת מִשִּׁבְעָה שֵׁמוֹת שֶׁאֵינָם נִמְחָקִים, וְלֹא מֵאוֹתִיּוֹת הַנִּטְפָּלוֹת \u0010c8\u0011 מֵאַחֲרֵיהֶם כְּנוּן ך' שֶׁל אֱלֹהֱיךָ וכ\"ם שֶׁל אֱלֹהֵיכֶם. וְאֵלּוּ הַשִּׁבְעָה שֵׁמוֹת: שֵׁם הַהֲוָיָה; וְשֵׁם אַדְנוּת; וְאֵל, \u0010c9\u0011 אֱלוֹהַ, אֱלֹהִים; שַׁדַּי; צְבָאוֹת. וְיֵשׁ גּוֹרְסִין גַּם כֵּן אֶהְיֶ\"ה אֲשֶׁר אֶהְיֶ\"ה \u0005(טוּר)\u0006.\nכָּתַב אֵל מֵאֱלֹהִים, יָהּ מֵהַשֵּׁם, אוֹ שֶׁכָּתַב שֵׁם יָהּ, אֵינוֹ נִמְחָק. אֲבָל שד מִשַׁדַּי וְצב מִצְּבָאוֹת, נִמְחָקִים. \u0005הַגָּה: וְכֵן אד מֵאֲדֹנָי אוֹ אה מֵאֶהְיֶה (יְרוּשַׁלְמִי פ\"ק דִּמְגִלָּה)\u0006. וְיֵשׁ \u0010c10\u0011 מַחְמִירִין בָּזֶה \u0005(תוס' פ' שְׁבוּעוֹת הָעֵדוֹת בְּשֵׁם ר\"ח)\u0006. וְהַשֵּׁם שֶׁכּוֹתְבִין בַּסִּדּוּרִין שְׁתֵּי יוּדִין וְאֶחָד עַל גַּבֵּיהֶן, מֻתָּר לְמָחְקוֹ אִם הוּא לְצֹרֶךְ \u0005(פִּסְקֵי מהרא\"י סי' קע\"א)\u0006.\nנִדְבְּקָה אוֹת לַחֲבֶרְתָּהּ בְּאוֹתִיּוֹת הַשֵּׁם, יֵשׁ לוֹ לְגָרְדוֹ. \u0005הַגָּה: דְּיוֹ שֶׁנִּשְׁפְּכָה עַל הַשֵּׁם, מֻתָּר לְמָחְקוֹ כְּדֵי לְתַקְּנוֹ דְּאֵין זֶה דֶּרֶךְ מְחִיקָה, רַק דֶּרֶךְ תִּקּוּן (בֵּית יוֹסֵף בְּשֵׁם מַסֶכֶת סוֹפְרִים וּבְהַגָּהַת מַיְמוֹנִי פ\"ו)\u0006 ה' שֶׁל שֵׁם שֶׁכְּרָעָה נוֹגַעַת בְּגַגָּהּ, אִם נוֹגֵעַ מַמָּשׁ עַד שֶׁנִּרְאֵית כְּחֵ\"ת, מֻתָּר לִמְחֹק אוֹ לְגָרֵד הָרֶגֶל וּלְתַקְּנָהּ. אֲבָל אִם נוֹגַעַת רַק מְעַט, יֵשׁ \u0010c11\u0011 לְסַפֵּק בַּדָּבָר אִם מֻתָּר \u0005(בֵּית יוֹסֵף בְּשֵׁם ר\"י אסכנדרני)\u0006.\nהַכּוֹתֵב יְהוּדָה וְלֹא נָתַן בּוֹ דָּלֶת, יִתְלֶה הַדָּלֶ\"ת לְמַעְלָה. הָיָה לוֹ לִכְתֹּב הַשֵּׁם, וְכָתַב יְהוּדָה, עוֹשֶׂה ה' מֵהַדָּלֶ\"ת וּמוֹחֵק ה' אַחֲרוֹנָה.\nכְּלִי שֶׁהָיָה כָּתוּב עָלָיו שֵׁם, קוֹצֵץ מְקוֹם הַשֵּׁם, וְגוֹנְזוֹ. \u0005הַגָּה: וְאָסוּר לִכְתֹּב שֵׁם לְכַתְּחִלָּה שֶׁלֹּא בְּסֵפֶר, דְּיוּכַל לָבוֹא לִידֵי בִּזָּיוֹן, וְלָכֵן נִזְהָרִין שֶׁלֹּא לִכְתֹּב שֵׁם בְּאִגֶּרֶת. וְיֵשׁ נִזְהָרִין אֲפִלּוּ בְּמִלַּת \u0010c12\u0011 שְׁלוֹם, שֶׁלֹּא לִגְמֹר כְּתִיבָתוֹ (מהרי\"ל בְּשֵׁם התשב\"ץ)\u0006.",[],["\u0003פסול. \u0004 ולא מהני העברת קולמוס עליהן לשמן. ש\"ך וכתב הב\"ח דאם נתכוין וכתב לשם קדושה אע\"פ שלא הוציא בשפתיו אינו פסול בדיעבד הואיל והוציא בתחלת כתיבת הס\"ת בפיו וע\"ל ר\"ס רע\"ד והט\"ז כ' דלא מהני מחשבה בקדושת השם אלא צריך דוקא להוציא בשפתיו אם לא שאם בתחלת הכתיבה אמר בפירוש וכל אזכרות שבו אני כותב לשם קדושת השם כמ\"ש בשם הסמ\"ג בסימן רע\"ד הבאתיו שם בס\"ק א' ע\"ש \u0005(ובנה\"כ השיג עליו וכתב דאישתמיטתי' דברי הרמ\"א בא\"ח סימן ל\"ב סי\"ט ע\"ש)\u0006:","\u0003מומין. \u0004 כתב הט\"ז משמע דאם כ' השם במקום אחר בטעות שלא במקומו וכתבו לשם קדושה הוי קודש וצריך גניזה אבל שם שנכתב שלא בכונה אין בו קדושה עכ\"ל:","\u0003ישיבנו. \u0004 כ' הש\"ך ואם השיב לא נפסל כך משמע בב\"י ופירש מ\"ש במס' סופרים הפסיק באמצע השם פסול היינו שעשה שם א' כשני שמות כזה ראו בן עכ\"ל ור\"ל דהאי השם אינו שם קודש אלא כל תיבה קרוי שם כמה שמצינו הרבה פעמים בש\"ס תיבה בלשון שם ודלא כהב\"ח שהבין דהוא שם קודש עכ\"ל ואם מלך א\"ה שואל בשלומו מותר להשיבו כמ\"ש גבי תפלה בא\"ח ר\"ס ק\"ד:","\u0003יחפש. \u0004 משמע דלכתוב מקודם אות אחרת של חול על איזה דבר אסור דכיון שדיו זו מוכנת לשם אין ראוי לכתוב בה דבר חול. ש\"ך:","\u0003האזכרות. \u0004 כתבו הט\"ז והש\"ך דלאו דוקא האזכרות אלא ה\"ה שאר ס\"ת ונקט אזכרות משום דבשאר דברים מהני תקון למחוק אותם משא\"כ באזכרות שהרי אסור למחקם ודלא כהלבוש שכ' דבשאר דברים כשר בזרק עליהם זהב ע\"ש:","\u0003ומקצתו. \u0004 והב\"ח כ' דדעת הטור וקצת פוסקים דאין לפסלה בדיעבד אבל הט\"ז כ' בשם הרמב\"ם דאפילו בדיעבד פסולה וכן יש לכוין לשון הטור ע\"ש וע\"ל סימן רע\"ג ס\"ו:","\u0003המחק. \u0004 משמע קצת דעל המחק וגרד עדיף מלתלות וכן דעת יש פוסקים והלכך היכא דאפשר לתקן בתלי' או לכתוב על המחק וגרד לא יתלה וכמדומה לי שכן נהגו עכ\"ל הש\"ך:","\u0003ואין. \u0004 כתב הש\"ך דהג\"ה זו אין ענינה לכאן דמהיכא תיתי לחלק כאן בין ס\"ת לשאר ספרים ואדרבה כ\"ש היא דמותר בשאר ספרים אלא הג\"ה זו שייכא לעיל ס\"ו דמקצתו תלוי פסול היינו אפילו בשאר ספרים אין לתלות מקצתו וכן הוא בסה\"ת עכ\"ל ומ\"ש המחבר שלא יצא מן השם חוץ לדף פי' על הגליון חוץ לשטה והרבה סופרים טועין וסברי דאין לכתוב השם בסוף השטה ולכך כשמזדמן להם השם בסוף שטה הם מאריכין ומקצרין שאר האותיות שלא כדין גם קצת עושים רשומים בסוף אחר השם כמ\"ש בסימן רע\"ד ס\"ק ו' ויש לבטל מנהגם בזה:","\u0003מאחריהם. \u0004 וכתבו הט\"ז והש\"ך אבל מלפניהם כגון ל' מן לה' או ב' מן בה' או הא' מן האלהים וכיוצא בו מותר למחוק \u0005(אבל הנטפל לאחריהם יש בו קדושה שכבר קדשו השם)\u0006 וכ' הט\"ז דאם שכח לכתוב כ\"ם של אלהיכם יכול לתלות בין השיטין ואין בזה משום תולה מקצת השם דהא לא מן השם הוא זה \u0005(ואף מי שעולה על לבו להחמיר בזה לכתחלה מ\"מ בדיעבד פשוט דאין לפסלו)\u0006 ואם שכח היו\"ד מאלהינו וכתבו חסר אלהנו אין לזה שום תיקון אלא צריך לסלק היריעה לגמרי \u0005(דהיו\"ד היא שרשית של השם)\u0006 ומ\"מ כיון שכבר נהגו הסופרים לקדור השם שנכתב בטעות ע\"כ אם אינו אפשר בקלות לסלק היריעה ולכתוב אחרת גם בזה יעשה כן ע\"ש שהאריך בזה מאד במה שמבואר בענין זה בתשו' משאת בנימין וכ' הש\"ך דשם של חול אלא שהוא נכתב כשמות הקדושים כגון והייתם כאלהים וכה\"ג מותר למוחקו וכן שם של קודש שלא נכתב לשם קדושה מותר למחקו לצורך תיקון דוקא אבל לגוז ולגנוז שרי אפילו שלא לצורך תיקון אבל בנכתב לשם קדושתו אפילו לגוז ולגנוז לצורך תיקון אסור ואם הרבה שמות נכתבו שלא לשמן בס\"ת אסור למחקן אע\"פ שהוא לצורך תיקון משום דמחזי כמנומר עכ\"ל:","\u0003אלוה. \u0004 בטור כתב עוד אלהי וכן הוא במקצת ספרי הרמב\"ם והטעם דשם אלהי הוא גם כן שם העצם והיו\"ד מכלל שורש השם וכן דעת כסף משנה מאחר שמצינו בשם אלדים שגם היו\"ד היא שרשית ה\"נ הוא בשם אלדי עכ\"ל ט\"ז וכ' עוד שנמצא בס\"ת בפסוק ויטוש אלוד עשהו חסר וי\"ו ופסק דאינו מועיל לתקן ולתלות הוי\"ו כיון דמגוף השם הוא במקום הזה אלא דיש לקדור השם ולכתוב אחר במקומו עכ\"ל:","\u0003מחמירין. \u0004 הטעם מבואר בתוס' דהחמירו בזה יותר מבש\"ד וצ\"ב לפי שזה שם המיוחד הוא:","\u0003לספק. \u0004 דכיון דכל העולם קורין אותה ה\"א אלא שנפסלה בנגיעתה לגג הוי כמוחק השם משא\"כ בנפסלה ממש אין עליה קדושה כלל ודמיא לדיו שנפלה על החי\"ת ט\"ז וש\"ך:","\u0003שלום. \u0004 כתב הש\"ך ורוב העולם אינם נזהרין בזה וכ\"כ בתשו' הרא\"ש דמותר \u0005(ובנה\"כ מסיים אמנם בתוס' פ\"ק דסוטה דף י' ע\"א מוכח דאסור ואי' שם להדיא גדולה מזה דשלום הוא משמות שאינם נמחקין והא דלא תני ליה בהדי ז' שמות שאינם נמחקין משום דתנא ושייר ע\"ש ומ\"מ צ\"ע לדינא דמדברי שאר פוסקים לא משמע כן דלא לישתמיט חד מינייהו דכתב כן וצ\"ע למעשה עכ\"ל וע\"ש)\u0006:"]],["כָּתַב הַיְרִיעָה וּבָא לְהַנִּיחָהּ כְּדֵי שֶׁתִּתְיַבֵּשׁ, לֹא יַהֲפֹךְ הַכְּתָב לְמַטָּה. אַף עַל פִּי שֶׁמְּכַוֵּן כְּדֵי שֶׁלֹּא יַעֲלֶה אָבָק עַל הַכְּתָב, מִכָּל מָקוֹם דֶּרֶךְ בִּזָּיוֹן הוּא, אֶלָּא יִהְיֶה פְּנֵי הַכְּתָב לְמַעְלָה, \u0010c0\u0011 וְיִפְרֹשׂ עָלָיו בֶּגֶד.",[],["\u0003ויפרוש. \u0004 בפ' בתרא דעירובין אמרינן היכא דלא אפשר בפריסת בגד יהפוך הכתב דאי לא אפיך איכא בזיון כתבי הקדש טפי וכתב הב\"ח מכאן יש ללמוד שלא ילך אדם חוץ ויניח הספר פתוח אם אין עליו מפה דלאו דוקא ס\"ת אלא ה\"ה שאר ספרים וכ' הש\"ך וידוע לחכמי האמת שיש מלאך אחד נקרא ש\"ד והוא ש\"ומר ד\"פין על מי שמניח ספר פתוח ויוצא שמשכח תלמודו עכ\"ל:"]],["אֵין תּוֹפְרִין סֵפֶר תּוֹרָה אֶלָּא בְּגִידֵי בְּהֵמָה אוֹ חַיָּה הַטְּהוֹרִים. וְלֹא יִתְפֹּר כָּל הַיְרִיעָה מֵרֹאשָׁהּ \u0010c0\u0011 לְסוֹפָהּ, אֶלָּא יַנִּיחַ בְּרֹאשָׁהּ מְעַט וּבְסוֹפָהּ מְעַט שֶׁלֹּא יִהְיֶה תָּפוּר, וְכָל הַשְּׁאָר יִהְיֶה תָּפוּר מֵרֹאשׁ וְעַד סוֹף. וְיִתְפֹּר מִבַּחוּץ \u0005(תְּרוּמַת הַדֶּשֶׁן סי' נ')\u0006.\nיָשִׂים בַּסֵפֶר תּוֹרָה שְׁנֵי עַמּוּדִים, אֶחָד בְּרֹאשׁוֹ וְאֶחָד בְּסוֹפוֹ, וּמַה שֶׁשִּׁיֵּר גִּלָּיוֹן בְּרֹאשׁוֹ וּבְסוֹפוֹ יִכְרֹךְ עַל הָעֲמוּדִים וְיִתְפְּרֶנּוּ \u0010c1\u0011 בְּגִידִים, וְיִשָּׁאֵר בֵּין הָעַמּוּד לַדַּף שְׁתֵּי אֶצְבָּעוֹת. \u0005וּבִשְׁעַת הַדַּחַק, שֶׁאִי אֶפְשָׁר לְתָפְרָהּ בְּגִידִין, אִם נִתְפְּרָה \u0010c2\u0011 בְּמֶשִׁי סְבִיב הָעַמּוּדִים, קוֹרִין בָּהּ. מִיהוּ אִם אֶפְשָׁר לְתַקְּנָהּ בְּגִידִין, אַף עַל פִּי שֶׁכְּבָר נִתְפְּרָה בְּמֶשִׁי, אֵין קוֹרִין בָּהּ עַד שֶׁיְּתַקְּנֶנָּה (ת\"ה סי' נ\"א)\u0006.\nאִם נִקְרַע רֹב תְּפִירָה שֶׁבֵּין יְרִיעָה לִירִיעָה, \u0010c3\u0011 וַעֲדַיִן מְחֻבָּרוֹת בְּחָמֵשׁ אוֹ שֵׁשׁ תְּפִירוֹת שֶׁל קַיָּמָא, כָּשֵׁר \u0005(שָׁם סִימָן נ')\u0006.\nאִם יְרִיעָה אַחַת אֵינָהּ תְּפוּרָה עִמּוֹ, אֲפִלּוּ הִיא מֻנַּחַת עִמּוֹ, אֵין קוֹרִין בּוֹ.",[],["\u0003לסופה. \u0004 וכ' הב\"ח כיון דאינו אלא תקנת חכמים כדי שלא יקרע הס\"ת לא מיפסל ס\"ת בהכי וכ\"כ הר\"ן ושאר אחרונים:","\u0003בגידים. \u0004 אבל אסור לדבק היריעות בדבק סביב העמודים כי בימים רבים מתייבש הדבק ומתרפה מעל העמודים כ\"כ מהרי\"ו ובד\"מ מסיים בשמו מיהו בשעת הדחק שרי ולא נמצא כן במהרי\"ו שם עכ\"ל הש\"ך:","\u0003במשי. \u0004 וה\"ה בין היריעות כן הוא בת\"ה שם ומוכח שם להדיא דכ\"ש אם נתפר במשי במקום הקרע שכשר בשעת הדחק עכ\"ל נה\"כ:","\u0003מחוברות. \u0004 והט\"ז חולק ע\"ז ופסק דבעינן שיהיה רובו מחובר דוקא \u0005(כדי שיהא נקרא הכל ספר א')\u0006 ובאם לאו אסור לקרות בו \u0005(ובנה\"כ השיג עליו וכ' שדברי המחבר עיקר ע\"ש)\u0006:"]],["סֵפֶר תּוֹרָה שֶׁאֵינוֹ מֻגָּהּ, אָסוּר לְהַשְׁהוֹתוֹ יוֹתֵר מִשְּׁלֹשִׁים יוֹם, אֶלָּא יְתַקֵּן אוֹ יִגְנֹז. \u0005וְהוּא הַדִּין לִשְׁאָר סְפָרִים (רַשִׁ\"י וּבֵית יוֹסֵף בְּשֵׁם הַגָּהוֹת מַיְמוֹנִי וְרַבֵּנוּ יְרוּחָם נָתִיב נ')\u0006. וְאֵין לְהַגִּיהַּ שׁוּם סֵפֶר עַל פִּי הַסְּבָרָא, כִּי אִם בִּרְאָיָה בְּרוּרָה שֶׁיֵּשׁ בּוֹ טָעוּת \u0005(הָרַב ר' דָּוִד כֹּהֵן בַּיִת ט\"ו וְחֵרֶם קַדְמוֹנִים)\u0006.\nקָרְאוּ בְּסֵפֶר תּוֹרָה בְּצִבּוּר וְנִמְצָא בּוֹ טָעוּת, מוֹצִיאִין סֵפֶר תּוֹרָה אַחֶרֶת וּמַתְחִיל מִמָּקוֹם שֶׁנִּמְצָא הַטָּעוּת, וּמַשְׁלִימִין שִׁבְעָה עַל אוֹתָם שֶׁקָּרְאוּ בְּמֻטְעֶה. וְאִם נִמְצָא הַטָּעוּת בְּאֶמְצַע קְרִיאַת הַתּוֹרָה, גּוֹמֵר קְרִיאָתוֹ בַּסֵפֶר \u0010c0\u0011 הַכָּשֵׁר וּמְבָרֵךְ לְאַחֲרֶיהָ וְאֵינוֹ מְבָרֵךְ לְפָנֶיהָ, כִּי בְּרָכָה שֶׁבֵּרַךְ לְפָנֶיהָ בַּסֵפֶר תּוֹרָה הַפָּסוּל, וְכֵן קְרִיאָה שֶׁקָּרְאוּ בּוֹ, עָלְתָה לָהֶם בְּדִיעֲבַד. \u0005הַגָּה: וְאֵין חִלּוּק בָּזֶה בֵּין שֶׁנִּמְצָא \u0010c1\u0011 הַטָּעוּת בְּסֵפֶר תּוֹרָה רִאשׁוֹנָה בֵּין שֶׁנִּמְצָא הַטָּעוּת בַּשְּׁנִיָּה שֶׁקּוֹרִין בָּהּ חוֹבַת הַיּוֹם לְמַפְטִיר וְעַיֵּן בא\"ח סִימָן קמ\"ג.\u0006\nסֵפֶר תּוֹרָה שֶׁנִּמְצְאוּ בּוֹ שָׁלֹשׁ טָעֻיּוֹת, אָסוּר לִקְרוֹת בּוֹ עַד שֶׁיַּגִּיהֶנּוּ, כִּי הוּא מֻחְזָק בְּמֻטְעֶה.\nסֵפֶר תּוֹרָה שֶׁיֵּשׁ בּוֹ ג' טָעֻיּוֹת בְּכָל דַּף וְדַף, יְתַקֵּן. וְאִם הָיוּ ד', יִגָּנֵז. וְאִם הָיָה רֹב הַסֵפֶר מֻגָּהּ, וְהַשְּׁאָר יֵשׁ בּוֹ ד' טָעֻיּוֹת בְּכָל דַּף, וְנִשְׁאַר אֲפִלּוּ דַּף אֶחָד מֵאוֹתוֹ הַשְּׁאָר הַמְשֻׁבָּשׁ בְּלֹא ד' טָעֻיּוֹת, הֲרֵי זֶה יְתַקֵּן. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁכָּתַב הַמָּלֵא חָסֵר, לְפִי שֶׁהוּא גְּנַאי לִתְלוֹת כָּל כָּךְ בֵּינֵי שִׁיטֵי. אֲבָל אִם כָּתַב הֶחָסֵר מָלֵא, אֲפִלּוּ יֵשׁ בְּכָל דַּף וְדַף כַּמָּה טָעֻיּוֹת, יְתַקֵּן, לְפִי שֶׁאֵין הַגְּרִידָה גְּנַאי כְּמוֹ הַתְּלִיָּה. \u0005הַגָּה: וּכְשֶׁגּוֹרֵד, יַרְחִיב הָאוֹת שֶׁלְּפָנָיו וְשֶׁלְּאַחֲרָיו קְצָת, שֶׁלֹּא יְהֵא מָקוֹם הַגֶּרֶד \u0010c2\u0011 הֶפְסֵק בַּתֵּבָה (ב\"י וּמָרְדְּכַי ה\"ק)\u0006.\nאִם דִּלֵּג שְׁנֵי שִׁיטִין אוֹ ג', לֹא יִמְחֹק שְׁלֹשָׁה שִׁיטִין לִכְתֹּב בִּמְקוֹמָם אַרְבָּעָה אוֹ ה' לְהַכְנִיס מַה שֶּׁדִּלֵּג, מִפְּנֵי שֶׁמְּמַעֵט הַכְּתָב וּמִחְזֵי כִּמְנֻמָּר \u0005(פי' כְּעוֹר נָמֵר שֶׁיֵּשׁ בּוֹ גְּוָנִין הַרְבֵּה)\u0006. וְטוֹב לְסַלֵּק הַיְרִיעָה. \u0005וּמִכָּל מָקוֹם הַסּוֹפְרִים נָהֲגוּ לְתַקֵּן, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל רֵישׁ סי' רע\"ה.\u0006",[],["\u0003הכשר. \u0004 כתב הש\"ך היינו כשלא קרא ג' פסוקים אבל קרא ג' פסוקים ויכול להפסיק שם מברך לאחריה ומשלימין המנין בס\"ת האחרת כמ\"ש בא\"ח בסימן קמ\"ג ס\"ד:","\u0003הטעות. \u0004 והט\"ז פסק דאם נמצא הטעות בקריאת האחרון ינהוג כדברי המרדכי לקרות הטעות בעל פה ויגמר בספר ההוא כל הקריאה הצריכה ולא יוציא אחרת מטעם כבוד הצבור ואע\"ג דיקרא אח\"כ למפטיר מ\"מ אין שייך כאן כבוד הצבור דהא בלא\"ה מפסיקין קצת באמירת קדיש ואם נמצא הטעות בקריאת מפטיר ג\"כ לא יוציא אחרת אלא יאמר בע\"פ עכ\"ל:","\u0003הפסק. \u0004 דבכה\"ג פסול כיון שהרחיק התיבה עד שנראית כשתים כדלעיל סי' רע\"ג ס\"ד עכ\"ל הש\"ך:"]],["סֵפֶר תּוֹרָה שֶׁנִּקְרְעָה בּוֹ יְרִיעָה בְּתוֹךְ שְׁנֵי שִׁיטוֹת, \u0010c0\u0011 יִתְפֹּר. בְּתוֹךְ ג', לֹא יִתְפֹּר. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּיָשָׁן שֶׁאֵין עִפּוּצוֹ נִכָּר. וְאִם נִכָּר הַגְּוִיל שֶׁהוּא עָפוּץ, תּוֹפֵר אֲפִלּוּ קֶרַע הַבָּא בְּתוֹךְ ג'. \u0005אֲבָל לֹא \u0010c1\u0011 יוֹתֵר (ריב\"ש)\u0006. וְכֵן בֵּין דַּף לְדַף וּבֵין \u0010c2\u0011 תֵּבָה לְתֵבָה, יִתְפֹּר. וְכָל הַקְּרִיעוֹת אֵין תּוֹפְרִין אוֹתָם אֶלָּא בַּגִּידִים שֶׁתּוֹפְרִין בָּהֶם הַיְרִיעוֹת זוֹ לָזוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁנּוֹהֲגִין לְתָפְרָם בְּמֶשִׁי (ת\"ה סי' נ\"א וְהָרֹא\"שׁ כְּלָל ג' וסה\"ת)\u0006. וְכֵן נוֹהֲגִין הָאִדָּנָא, אֲבָל הָעִקָּר לְתָפְרָם בְּגִידִין, אִם אֶפְשָׁר \u0005(ש\"ס וּפוֹסְקִים וריב\"ש)\u0006. \u0010c3\u0011 וְיֵשׁ אוֹמְרִים דְּמֻתָּר לְדַבֵּק עָלָיו קְלָף מִבַּחוּץ, כָּל זְמַן שֶׁמֻּתָּר לְתָפְרָם, וּלְדַבֵּק הַקְּרִיעָה עַל יְדֵי כָּךְ \u0005(שָׁם סי' ל\"א)\u0006. וְכֵן אִם נֶחְסַר דָּבָר, כּוֹתְבִין עַל הַקְּלָף \u0010c4\u0011 הַדָּבוּק \u0005(מהרי\"ק שֹׁרֶשׁ קכ\"ב)\u0006, וְכֵן נָהֲגוּ וְעַיֵּן לְקַמָּן סִימָן ר\"ץ. וּבְכָל הַקְּרָעִים יִזָּהֵר שֶׁלֹּא תֶּחְסַר אוֹת אַחַת אוֹ תִּשְׁתַּנֶה צוּרָתָהּ אוֹ תֵּחָלֵק. \u0005הַגָּה: וְאִם \u0010c5\u0011 נֶחְלַק שׁוּם אוֹת עַל יְדֵי הַקְּרִיעָה, פְּסוּלָה, וְלֹא מְהָנֵי מַה שֶׁמְּדַבְּקוֹ מֵאֲחוֹרָיו (שָׁם)\u0006. וְכֵן יִזָּהֵר שֶׁלֹּא יִתְחַב הַמַּחַט תּוֹךְ הַכְּתָב, אֶלָּא חוּץ לַכְּתָב.\nסֵפֶר תּוֹרָה שֶׁבָּלוּ מִמֶּנּוּ יְרִיעוֹת וּבָא לְהַחְלִיפָם, אֲפִלּוּ לֹא בָּלוּ מִמֶּנּוּ אֶלָּא אַחַת אוֹ שְׁתַּיִם, צָרִיךְ לְהַחֲלִיף שָׁלֹשׁ, לְפִי שֶׁאִי אֶפְשָׁר שֶׁיִּהְיוּ אוֹתָם שֶׁמַּחֲלִיף דּוֹמוֹת לְגַמְרֵי לַאֲחֵרוֹת וּלְכָךְ \u0010c6\u0011 צָרִיךְ שֶׁיִּהְיוּ לְפָחוֹת שְׁלֹשָׁה דּוֹמוֹת.",[],["\u0003יתפור. \u0004 כתב הב\"ח כל זמן שלא תפרו אפילו לא נקרע אלא בשטה אחת אסור לקרות בו עד שיתפור אבל הט\"ז כ' דלא נראה לו דאין כאן פסול לגמרי כל שהוא בפחות משלשה אלא דקמ\"ל דאין איסור בתפירה דלא תימא דמיגניא בכך שזהו טעם שלא יתפור בנקרע עד שלשה משום דמיגניא ובעינן זה אלי ואנוהו קמ\"ל בפחות משלשה לא מיגניא אבל באמת אף אם לא תפרו כשר אם אינו בתוך ג' \u0005(ובנה\"כ כתב דאין נראין דבריו דמדברי הפוסקים משמע דצריך לתפור ע\"ש)\u0006 ואם הוא בתוך ג' כתב הט\"ז דצריך לסלק היריעה ופשוט שגם בדבוק מבחוץ בקלף לא מהני בזה ונראה דבדיעבד אם תקנה בתפירה או בדבק וזה נמצא בשעת הקריאה שאין להוציא אחרת בשביל זה וכ\"ש אם אין שם ס\"ת אחרת שיש לקרות בזאת התורה עכ\"ל וכ' הב\"ח דדין זה שנקרע היינו דוקא שהקרע התחיל ביריעה בגליון למעלה או למטה ובא בתוך ג' שיטין בזה לא יתפור אבל אם לא נקרע הגליון אלא שנקרע בתוך השיטין לבד אפילו בד' וה' נמי יתפור \u0005(והרא\"ם ח\"א סימן פ\"ט לא כ\"כ. ואנן נוהגין לדבק קלף עליו מבחוץ וכ' מהר\"מ הלוי נראה שכל שלא נקרע גוף היריעה או נסדק מעבר לעבר רק שריטה ע\"פ שטחיות הגויל והגויל קיים אין לחוש)\u0006 ואם רק הגליון בלבד נקרע למעלה או למטה יכולין לקרות בה לכתחלה עכ\"ל ונכון הוא ומ\"מ נראה דלכתחלה יתקן כל מה דאפשר. ש\"ך:","\u0003יותר. \u0004 וכ' בנה\"כ שמצא בהרבה תשובות שפסקו דאפילו יותר משלש יתפור ואין ספק אילו ראה הרב דברי הפוסקים אלו לא היה כותב כן עכ\"ל והב\"ח כתב דס\"ת דידן לכ\"ע יתפור שהרי הגידין הם לבנות והקלפים שלנו ג\"כ לבנות א\"כ הדבר ידוע שאין התפירות ניכרות בס\"ת ואפילו בג' יתפור וכן לדבק קלף על הקרעים בדבק:","\u0003לתיבה. \u0004 כתב הש\"ך נ\"ל פירושו דברישא מיירי בין אות לאות ומ\"מ לא נתקלקל האות וכאן מיירי בין תיבה לתיבה ולא בין אות לאות הלכך יתפור והט\"ז כתב ולענין הלכה יש להחמיר בין תיבה לתיבה כמו בין האותיות כדעת הטור בזה דתוך ג' לא יתפור:","\u0003לדבק. \u0004 כתב הש\"ך כלומר אם הוא קרע הבא בתוך ב' שיטין או בתוך ג' ועפיץ בענין שמותר לתפור מותר ג\"כ לדבק אבל אם אסור לתפור אסור לדבק ג\"כ אבל מדברי הב\"ח משמע דאפילו היכא דאסור לתפור מותר לדבק דהא בקרע תוך ג' דאסור לתפור מתיר הרא\"ש לדבק ונ\"ל דכדאי הוא הרא\"ש לסמוך עליו בשעת הדחק מיהו כל זה כשלא נחלק האות אבל אם נחלק האות אסור לדבק בכל ענין עכ\"ל:","\u0003הדבוק. \u0004 וכתב הב\"ח דמהרי\"ק התיר מה שנהגו לטלות במטלית על נקבים ביריעה קודם התחלת כתיבת ס\"ת ואח\"כ כותבין על הטלאי דלא כמקצת חכמים שהביאו ראיות לאיסור ודחה הוא ראיותיהם ול\"נ עיקר כדברי האוסרים אלא מאחר שנהגו הקדמונים לקרות בס\"ת כזו לפני גדולי עולם ולא מיחו בידם ע\"כ אין לשום גדול למחות ולהורות הוראה לאסור לאחרים אבל המחמיר לעצמו בס\"ת שלו הרי זה משובח ותע\"ב מיהו נראה אם כ' מקצת האות על היריעה ומקצתו על הטלאי ה\"ז פסול לדברי הכל דכשתחלק הטלאי ימצא כאן חצי אות וכאן חצי אות ולא עוד אלא אפילו נכתב האות כולו על היריעה אלא שמקצת הדיו מצד א' של האות ההוא עובר גם על הטלאי לא מהני הקפת גויל שבטלאי לאות שנכתב על היריעה אלא האות שביריעה צריך להיות מוקף גויל ביריעה עצמה בלא טלאי וכן האות שבטלאי צ\"ל מוקף גויל בטלאי עצמו בלא היריעה עכ\"ל והט\"ז חולק ע\"ז וכתב דכיון שבקלף הדבוק מהני למה שכתוב עליו דהוי כמו שנכתב על היריעה למה לא יועיל ג\"כ לכתוב חציה ע\"ז וחציה על זה:","\u0003נחלק. \u0004 ול\"ד למ\"ש בא\"ח סימן ל\"ב סט\"ז דאם נפסק א' מאותיות הפשוטות שהוא כשר דהתם מיירי שלא נשתנה צורת האות אף על פי שחלוק ולא נדבק בדבק ע\"ש כ\"כ הלבוש:","\u0003צריך. \u0004 וכתב הט\"ז נראה דבדיעבד אינו פסול בזה והש\"ך כתב ונראה שטוב שסופר הראשון יכתבם אם אפשר וסופר אחר יראה ג\"כ שמה שהוא מחזיר יהא כמדת הראשון בכתבו עכ\"ל \u0005(ובת' ח\"צ שאלה י\"ט הורה שאין מחליפין רק היריעה א' הן בלה או נקרע ס\"ת באופן שצריך לסלק די בסילוק יריעה א' ואם היריעה בת ו' דפין די בסילוק ג' דפין ע\"ש. אבל תשו' ש\"י ח\"ב שאלה פ\"ט מחלק בין היריעה שבלה שהיא שמנה צריכה להחליף ג' יריעות כפסק הש\"ע משא\"כ בשאר תיקוני ס\"ת ודאי די בסילוק א' מהם. ובכה\"ג מחלק בתשו' מהר\"י כהן סי' מ\"ט וחוט השני סי' פ\"ו ובס' חב\"י סי' ע\"ז. ועיין ט\"ז ס\"ק ה')\u0006:"]],["סֵפֶר תּוֹרָה שֶׁכְּתָבוֹ אֶפִּיקוֹרוֹס, יִשָּׂרֵף. כְּתָבוֹ \u0010c0\u0011 כּוּתִי, יִגָּנֵז. נִמְצָא בְּיַד אֶפִּיקוֹרוֹס, וְאֵינוֹ יוֹדֵעַ מִי כְּתָבוֹ, יִגָּנֵז. נִמְצָא בְּיַד כּוּתִי, וְאֵינוֹ יוֹדֵעַ מִי כְּתָבוֹ, יֵשׁ מִי שֶׁמַּכְשִׁיר וְיֵשׁ אוֹמְרִים יִגָּנֵז. וְחַיָּבִין הַצִּבּוּר לִקְנוֹתוֹ מִמֶּנּוּ בִּכְדֵי דָּמָיו אוֹ יוֹתֵר מְעַט וּלְגָנְזוֹ, כְּדֵי שֶׁלֹּא \u0010c1\u0011 יְזַלְזֵל בּוֹ. וְאִם רָצָה לְהַעֲלוֹת בְּדָמָיו יוֹתֵר מִכְּדֵי דָּמָיו הַרְבֵּה, מַנִּיחִין אוֹתוֹ בְּיָדוֹ. וְאִם \u0010c2\u0011 הֻחְזְקוּ שֶׁבָּזְזוּ כְּנַעֲנִים סִפְרֵי יִשְׂרָאֵל, תּוֹלִים שֶׁאוֹתָם סְפָרִים שֶׁלָּהֶם הָיוּ וְקוֹרִין בָּהֶם.\nגֵּר שֶׁחָזַר לְסוּרוּ מֵחֲמַת יִרְאָה, כָּשֵׁר לִכְתֹּב סֵפֶר תּוֹרָה.\nסֵפֶר תּוֹרָה שֶׁכְּתָבוֹ מַסוּר, \u0010c3\u0011 עֶבֶד, אִשָּׁה, קָטָן, כּוּתִי, יִשְׂרָאֵל מוּמָר, פְּסוּלִין.\nסֵפֶר תּוֹרָה שֶׁכְּתָבוֹ מַמְזֵר, יֵשׁ פּוֹסְלִין. \u0005וְהוּא הַדִּין גֵּר תּוֹשָׁב (מָרְדְּכַי סה\"ק)\u0006.\nסֵפֶר תּוֹרָה שֶׁאָמַר הַסוֹפֵר לְאַחַר שֶׁיָּצָא מִיָּדוֹ: לֹא כָּתַבְתִּי הָאַזְכָּרוֹת לִשְׁמָן, אֵינוֹ נֶאֱמָן לְפָסְלוֹ. אֲבָל נֶאֱמָן הוּא לְהַפְסִיד כָּל שְׂכָרוֹ. וְלָמָּה אֵינוֹ נֶאֱמָן לְפָסְלוֹ, שֶׁמָּא לֹא נִתְכַּוֵּן אֶלָּא לְהַפְסִיד עַל הַלּוֹקֵחַ אוֹ עַל זֶה שֶׁשְּׂכָרוֹ, וְדוֹמֶה שֶׁאֵינוֹ מַפְסִיד בַּאֲמִירָה זוֹ אֶלָּא שְׂכַר הָאַזְכָּרוֹת. לְפִיכָךְ אִם אָמַר: סֵפֶר תּוֹרָה זֶה עוֹרוֹת שֶׁלּוֹ אֵינָם מְעֻבָּדִים לִשְׁמָן, מִתּוֹךְ שֶׁנֶּאֱמָן לְהַפְסִיד \u0010c4\u0011 שְׂכָרוֹ נֶאֱמָן לְפָסְלוֹ, שֶׁהַכֹּל יוֹדְעִים שֶׁאִם אֵין הָעוֹרוֹת מְעֻבָּדִין לִשְׁמָן אֵין לוֹ שָׂכָר כְּלָל. \u0005הַגָּה: \u0010c5\u0011 מִיהוּ כִּשְׂכַר חֻמָּשׁ בְּעָלְמָא חַיָּב לְשַׁלֵּם לוֹ, דְּהָא מִכָּל מָקוֹם לֹא גָּרַע מֵחֻמָּשׁ (מָרְדְּכַי פ' הַנִּזָּקִין)\u0006.",[],["\u0003יגנז. \u0004 אפילו כתבו למכור לישראל. תוספות. ש\"ך. וכתב הט\"ז דבטור הוסיף ואין קורין בו נראה דקמ\"ל דאפילו בבית אין קורין בו ביחידות אפילו ביש ספק מי כתבו ונ\"ל דיש עוד חילוק בין זה לשאר הפסולין דהיינו כל פסול שנראה לכל פסולו ודאי קורין בו ביחידות ואין חשש שיקראו בו בציבור אבל בפיסול שאינו מוכח כגון שאינו מעובד לשמה יש לאסור לקרות בו אפילו ביחידות שמא יקראו בו בציבור כמו שמצינו לענין ספק טריפה בסי' נ\"ז שלא ישהנו מפני התקלה עכ\"ל \u0005(ובנה\"כ השיג עליו בזה וכ' דל\"ד לספק טריפות ע\"ש)\u0006 ועיין בא\"ח סימן ל\"ט:","\u0003יזלזל. \u0004 ומשמע בש\"ס דאין לומר לעובד כוכבים שיתן לו בזול יותר מדאי פן יכעוס וישליכה למקום האבוד וכתב הט\"ז כשהעובד כוכבים רוצה הרבה יותר מכדי דמיו לא יסלק וימשוך ידו ממנו תיכף אלא צריך לעסוק עמו בדברי ריצוי אולי ימכרנו בכדי דמיו ומעט יותר ואם אח\"כ עומד בדעתו אז מניחין בידו וילך לו ולא קודם לזה עכ\"ל:","\u0003שבזזו. \u0004 וכתב הש\"ך ונ\"ל דה\"ה במקומות שאין העובדי כוכבים יודעים לכתוב דאמרינן מסתמא בזזו אותם:","\u0003עבד. \u0004 והדרישה כ' שמדברי הרי\"ף והרא\"ש והטור נראה דדוקא גבי תפילין פסולין עבד ואשה וקטן ולא בס\"ת אבל הש\"ך כ' שאינו מוכרח ונראה דבקטן אפילו הגיע לחינוך פסול כמו גבי תפילין וכן משמע בלבוש להדיא עכ\"ל:","\u0003שכרו. \u0004 כ' הש\"ך משמע אם כתב לו בחנם כגון במתנה וכה\"ג אינו נאמן כיון שיצא מתחת ידו:","\u0003מיהו. \u0004 כ' הט\"ז פשוט שזה קאי גם אחלוקה ראשונה שלא כתב האזכרות לשמה וקשה לי אם כן דיש לו עכ\"פ איזה שכירות מאי שנא רישא דאנו אומרים שמא לא נתכוין אלא להפסיד על הלוקח ה\"נ נימא כן ולפי מ\"ש בסמוך דכל שיש פסול בדרך שאינו ניכר אסור לקרות בו אפילו ביחידות אתי שפיר כאן דודאי א\"צ ליתן לו שום שכר כיון שאסור לקרות בו אפי' ביחידות דאתי למיקרי ביה בצבור כיון שאין הפסול מוכח מתוכו בזה ודאי ניחא דא\"צ ליתן לו שום שכר \u0005(ובנה\"כ כ' שלא ראה דברי המרדכי פ' הנזקין ששם מבואר קושיתו והוא מתרצה בענין אחר ע\"ש)\u0006:"]],["חַיָּב אָדָם לִנְהֹג כָּבוֹד גָּדוֹל בְּסֵפֶר תּוֹרָה. וּמִצְוָה לְיַחֵד לוֹ מָקוֹם וּלְכַבֵּד הַמָּקוֹם הַהוּא וּלְהַדְּרוֹ בְּיוֹתֵר. וְלֹא יִרֹק כְּנֶגֶד סֵפֶר תּוֹרָה. וְלֹא יְגַלֶּה עֶרְוָתוֹ כְּנֶגְדּוֹ. וְלֹא יִפְשֹׁט רַגְלוֹ כְּנֶגְדּוֹ. וְלֹא יַנִּיחֶנוּ עַל רֹאשׁוֹ כְּמַשּׂוֹי. וְלֹא יַחֲזֹר אֲחוֹרָיו, אֶלָּא אִם כֵּן \u0010c0\u0011 גָּבוֹהַּ מִמֶּנּוּ עֲשָׂרָה טְפָחִים, אֶלָּא יֵשֵׁב לְפָנָיו בְּכֹבֶד רֹאשׁ וּבְיִרְאָה וָפַחַד, שֶׁהוּא הָעֵד הַנֶּאֱמָן עַל כָּל בָּאֵי עוֹלָם, שֶׁנֶּאֱמַר: וְהָיָה שָׁם בְּךָ לְעֵד \u0005(דְּבָרִים לא, כו)\u0006, וִיכַבְּדֶנּוּ כְּפִי כֹּחוֹ.\nהָרוֹאֶה סֵפֶר תּוֹרָה כְּשֶׁהוּא מְהַלֵּךְ, חַיָּב לַעֲמֹד לְפָנָיו, וְיִהְיוּ הַכֹּל עוֹמְדִים עַד \u0010c1\u0011 שֶׁיַּעֲמֹד זֶה שֶׁמּוֹלִיכוֹ וְיַגִּיעֶנּוּ לִמְקוֹמוֹ, אוֹ עַד שֶׁיִּתְכַּסֶה מֵעֵינֵיהֶם. \u0005הַגָּה: אֲבָל לִפְנֵי חֻמָּשִׁים שֶׁלָּנוּ אֵין צְרִיכִים לַעֲמֹד (ב\"י בְּשֵׁם הָרַמְבַּ\"ם)\u0006. וְיֵשׁ מַחְמִירִים \u0005(רשב\"א סי' קמ\"ד)\u0006. \u0010c2\u0011 הַשּׁוֹמֵעַ קוֹל הַנּוֹשֵׂא סֵפֶר תּוֹרָה אַף עַל פִּי שֶׁאֵינוֹ רוֹאֶה אוֹתוֹ, חַיָּב לַעֲמֹד \u0005(ב\"י בְּשֵׁם הָרַב רַבֵּנוּ מָנוֹחַ)\u0006.\nהָיָה הוֹלֵךְ מִמָּקוֹם לְמָקוֹם וְסֵפֶר תּוֹרָה עִמּוֹ, לֹא יַנִּיחֶנוּ בְּשַׂק וְיַנִּיחֶנּוּ עַל גַּבֵּי חֲמוֹר וְיִרְכַּב עָלָיו, אֶלָּא מַנִּיחוֹ בְּחֵיקוֹ כְּנֶגֶד לִבּוֹ וְהוּא רוֹכֵב עַל הַחֲמוֹר. וְאִם הָיָה \u0010c3\u0011 מְפַחֵד מִפְּנֵי הַגַּנָּבִים, מֻתָּר.\nלֹא יֶאֱחֹז אָדָם סֵפֶר תּוֹרָה וְיִכָּנֵס בּוֹ לְבֵית הַכִּסֵא אוֹ לְבֵית הַמֶּרְחָץ אוֹ לְבֵית הַקְּבָרוֹת, אַף עַל פִּי שֶׁכָּרוּךְ בְּמִטְפַּחַת וְנָתוּן בְּתִיק שֶׁלּוֹ, וְלֹא יִקְרָא בּוֹ עַד שֶׁיַּרְחִיק ד' אַמּוֹת מֵהַמֵּת אוֹ מִבֵּית הַקְּבָרוֹת אוֹ מִבֵּית הַכִּסֵא. וְלֹא יֶאֱחֹז סֵפֶר תּוֹרָה בְּלֹא מִטְפָּחוֹת.\nאֵין זוֹרְקִין כִּתְבֵי הַקֹּדֶשׁ, וַאֲפִלּוּ הֲלָכוֹת וְאַגָּדוֹת. \u0005וְאָסוּר לַהֲפֹךְ אוֹתוֹ עַל פְּנֵיהֶם, וּכְשֶׁמְּצָאוֹ כָּךְ צָרִיךְ לְהָפְכוֹ (מהרי\"ל)\u0006.\nהַקְּמֵעִין, אִם הָיוּ הַמְכֻסִים עוֹר מֻתָּר לִכָּנֵס בָּהֶם לְבֵית הַכִּסֵא, וְאִם לָאו, אָסוּר.\nאָסוּר לֵישֵׁב עַל \u0010c4\u0011 הַמִּטָּה שֶׁסֵפֶר תּוֹרָה עָלֶיהָ. \u0005הַגָּה: וְכָל שֶׁכֵּן שֶׁאָסוּר לְהַנִּיחָהּ עַל גַּבֵּי קַרְקַע. וְהוּא הַדִּין שְׁאָר \u0010c5\u0011 סְפָרִים (ב\"י בְּשֵׁם הר\"ר מָנוֹחַ וּבְשֵׁם א\"ח וְכָל בּוֹ)\u0006. וַאֲפִלּוּ עַל הַמַּדְרֵגוֹת שֶׁעוֹשִׂין לִפְנֵי אֲרוֹן הַקֹּדֶשׁ, אָסוּר לְהַנִּיחַ סְפָרִים \u0005(הגמ\"י)\u0006 וְלֹא \u0010c6\u0011 יַנִּיחַ אָדָם סֵפֶר תּוֹרָה עַל בִּרְכָּיו וּב' אֲצִילֵי יָדָיו עָלָיו \u0005(מהרי\"ל)\u0006. ונ\"ל דְּהוּא הַדִּין שְׁאָר סְפָרִים.\nבַּיִת שֶׁיֵּשׁ בּוֹ סֵפֶר תּוֹרָה לֹא יְשַׁמֵּשׁ בּוֹ מִטָּתוֹ עַד שֶׁיּוֹצִיאֶנּוּ. וְאִם אֵין לוֹ מָקוֹם לְהוֹצִיאוֹ, יַעֲשֶׂה לְפָנָיו מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים. אֲבָל עַל יְדֵי הַנָּחַת כְּלִי בְּתוֹךְ כְּלִי שֶׁאֵינוֹ מְיֻחָד אֵינוֹ מֻתָּר אֶלָּא בִּתְפִלִּין וּשְׁאָר כִּתְבֵי הַקֹּדֶשׁ וְחֻמָּשִׁים, אֲבָל לֹא בְּסֵפֶר תּוֹרָה, וְהָרַמְבַּ\"ם מַתִּיר אַף בְּסֵפֶר תּוֹרָה. וְאִם פָּרַשׂ טַלִּיתוֹ עַל הָאַרְגָּז שֶׁמֻּנָּח בּוֹ, חָשׁוּב כִּכְלִי בְּתוֹךְ כְּלִי.\nכָּל הַטְּמֵאִים, \u0010c7\u0011 אֲפִלּוּ נִדּוֹת, מֻתָּרִים לֶאֱחֹז בְּסֵפֶר תּוֹרָה וְלִקְרוֹת בּוֹ. וְהוּא שֶׁלֹּא יִהְיוּ יְדֵיהֶם מְטֻנָּפוֹת אוֹ מְלֻכְלָכוֹת.\nסֵפֶר תּוֹרָה שֶׁבָּלָה אוֹ נִפְסַל, נוֹתְנִין אוֹתוֹ בִּכְלִי חֶרֶס וְקוֹבְרִין אוֹתוֹ אֵצֶל \u0010c8\u0011 תַּלְמִיד חָכָם, וְזוֹ הִיא גְּנִיזָתוֹ.\nמִטְפְּחוֹת סְפָרִים שֶׁבָּלוּ, \u0010c9\u0011 עוֹשִׂין אוֹתָם תַּכְרִיכִין לְמֵת מִצְוָה וְזוֹ הִיא גְּנִיזָתָן.\nתִּיק שֶׁהוּכַן \u0010c10\u0011 לְסֵפֶר תּוֹרָה וְהֻנַּח בּוֹ, וְכֵן הַמִּטְפָּחוֹת וְהָאָרוֹן וְהַמִּגְדָּל שֶׁמַּנִּיחִים סֵפֶר תּוֹרָה בּוֹ, אַף עַל פִּי שֶׁאֵין מַנִּיחִים בּוֹ סֵפֶר תּוֹרָה כְּשֶׁהוּא לְבַדּוֹ אֶלָּא כְּשֶׁהוּא בַּתִּיק, וְכֵן הַכִּסֵא שֶׁהוּכַן לְהַנִּיחַ סֵפֶר תּוֹרָה עָלָיו, וְהֻנַּח, כֻּלָּם תַּשְׁמִישֵׁי קְדֻשָּׁה הֵם וַאֲסוּרִים, וּלְאַחַר שֶׁיִּבְּלוּ אוֹ יִשָּׁבְרוּ, נִגְנָזִים.\nתֵּבָה שֶׁנִּשְׁבְּרָה, מֻתָּר לַעֲשׂוֹת מִמֶּנָּהּ אַחֶרֶת קְטַנָּה. אֲבָל אָסוּר לַעֲשׂוֹת מִמֶּנָּהּ כִּסֵא לְסֵפֶר תּוֹרָה. וְכִסֵא שֶׁנִּשְׁבַּר, מֻתָּר לַעֲשׂוֹת מִמֶּנּוּ כִּסֵא קָטָן, וְאָסוּר לַעֲשׂוֹת מִמֶּנּוּ שְׁרַפְרַף \u0005(פי' סַפְסָל קָטָן)\u0006 לְכִסֵא.\nהַבִּימוֹת שֶׁעוֹמֵד עֲלֵיהֶם הָאוֹחֵז הַסֵפֶר, אֵין בָּהֶם קְדֻשַּׁת סֵפֶר תּוֹרָה אֲבָל יֵשׁ בָּהֶם מִשּׁוּם קְדֻשַּׁת בֵּית הַכְּנֶסֶת.\nכָּל מַה שֶּׁעוֹשֶׂה לְסֵפֶר תּוֹרָה, אִם עֲשָׂאוֹ עַל תְּנַאי לְהִשְׁתַּמֵּשׁ בּוֹ שְׁאָר תַּשְׁמִישׁ אִם רָצָה, מוֹעִיל בּוֹ הַתְּנַאי. \u0010c11\u0011\nתַּפּוּחֵי כֶּסֶף וְזָהָב שֶׁעוֹשִׂים לְסֵפֶר תּוֹרָה לְנוֹי, תַּשְׁמִישֵׁי קְדֻשָּׁה הֵם וְאָסוּר לְהוֹצִיאָם לְחֻלִּין, אִם לֹא לִקְנוֹת בָּהֶם סֵפֶר תּוֹרָה אוֹ חֻמָּשׁ.\nכָּל מַה שֶּׁאָסוּר לְשַׁנּוֹתוֹ לִקְדֻשָּׁה קַלָּה, אִם מְכָרוּהוּ שִׁבְעָה טוֹבֵי הָעִיר בְּמַעֲמַד אַנְשֵׁי הָעִיר, מֻתָּר.\nיָחִיד שֶׁמּוֹכֵר סֵפֶר תּוֹרָה שֶׁלּוֹ וְתַשְׁמִישׁוֹ, יֵשׁ מִי שֶׁמַּתִּיר לְהִשְׁתַּמֵּשׁ בְּדָמָיו, וְיֵשׁ מִי שֶׁאוֹסֵר. \u0005וְאִם הָיוּ בָּהּ \u0010c12\u0011 טָעֻיּוֹת לְכֻלֵּי עָלְמָא שָׁרֵי (ריב\"ש סי' רפ\"ו)\u0006. וְעַיֵּן בא\"ח סִימָן קנ\"ג.\nמֻתָּר לְהַנִּיחַ סֵפֶר תּוֹרָה עַל סֵפֶר תּוֹרָה, וּמַנִּיחִים חֻמָּשִׁים עַל גַּבֵּי נְבִיאִים וּכְתוּבִים, אֲבָל אֵין מַנִּיחִים נְבִיאִים וּכְתוּבִים עַל גַּבֵּי חֻמָּשִׁים, וְלֹא חֻמָּשִׁים עַל גַּבֵּי סֵפֶר תּוֹרָה. \u0005הַגָּה: אֲבָל כְּתוּבִים עַל גַּבֵּי נְבִיאִים (אוֹ אִיפְּכָא, שָׁרֵי)\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הר\"ן בְּשֵׁם תּוֹסָפוֹת פ\"ק דב\"ב)\u0006 וְכָל זֶה מַיְרֵי בְּב' כְּרִיכוֹת, שֶׁכָּל א' כָּרוּךְ בִּפְנֵי עַצְמוֹ, אֲבָל בְּכֶרֶךְ א' הַכֹּל שָׁרֵי \u0005(מָרְדְּכַי פ' הַשֻּׁתָּפִין)\u0006. וְעַיֵּן לְעֵיל סִימָן רמ\"ו דְּאָסוּר לְהַרְהֵר בְּדִבְרֵי תּוֹרָה בִּמְקוֹמוֹת הַמְטֻנָּפִים, וְהוּא מִשּׁוּם \u0010c13\u0011 כְּבוֹד תּוֹרָה.",[],["\u0003גבוה. \u0004 כתב הט\"ז ונראה דהס\"ת צריך שתהיה גבוה מן האדם אבל איפכא לא הוי דרך כבוד ונ\"ל דהרבנים שעומדים לפני ארון הקדש אינן בכלל איסור זה שעומדים אחוריהם לארון הקודש כיון שהס\"ת מונחת באה\"ק הוה כמו ברשות אחרת עכ\"ל:","\u0003שיעמוד. \u0004 ואם עומד לפוש דינו כמהלך מאחר שאינו עומד דרך קבע. כ\"כ הכסף משנה וע\"ל סימן רמ\"ב סי\"ח:","\u0003השומע. \u0004 כתב הש\"ך כן הוא בכל הספרים אבל אין נוהגין כן וכ\"כ הב\"י שנהגו שלא לעמוד מפניהם ומעולם לא נשמע פוצה פה לערער בדבר שיהיו צריכים לעמוד לפני חומש ונראה שכצ\"ל יש מחמירים ואומרים השומע קול הנושא וכו' ואלמטה קאי וכן גרס בלבוש עכ\"ל וכתב הט\"ז דבב\"י מביא בשם ה\"ר מנוח שע\"כ נהגו לעשות פעמונים ולא נראה לע\"ד דא\"כ בשבת אין להוציא ספר תורה הזאת דמשמיע קול לכך נראה לי שאין לעשות אותן פעמונים ומש\"ה לא הביאו רמ\"א וכבר ראינו שהיה כן באיזה בהכ\"נ ומיחו בהם וסלקום עכ\"ל:","\u0003מפחד. \u0004 והב\"ח כ' ולענין הלכה נקטינן דשלא במקום סכנה לא שרי אלא בחיקו כנגד לבו ואפי' בשאר ספרים ובמקום סכנה נמי לא שרי אלא להכשילו לאחוריו אבל לא לרכוב עליו ע\"כ ובודאי היכא דאפשר להחמיר בכבוד תורה עדיף אבל היכא דלא אפשר מותר אפילו לרכוב עליהם עכ\"ל הש\"ך:","\u0003המטה. \u0004 וראוי להחמיר שיהא מקום הס\"ת גבוה ממנו י' טפחים ולא יפחות מג' טפחים דכל דבציר מהכי לא חשיב גובה כלל ב\"י ונראה דמדת חסידות קאמר אבל מדינא סגי בגובה טפח לכ\"ע. ש\"ך:","\u0003ספרים. \u0004 וכתב הר\"ר מנוח דוקא שלא בשעת זמן בהמ\"ד אבל בזמן בהמ\"ד והמקום צר לתלמידים מותר לישב בשוה עם הספרים והפירושים וכן היה נוהג ה\"ר משולם מבדרשי אך כשלא היה במקום ב\"ה היה מדקדק שיהא הספר נתון ע\"ג דבר אחר כל שהוא וכ' בעל ספר א\"ח ונראה שאין להקל בדבר שלא יראה כמזלזל בכבוד הספרים עכ\"ל ב\"י:","\u0003יניח. \u0004 בחשו' רמ\"א סימן ל\"ד כ' שאין לישב על תיבה שיש בה ספרי קדש וכ' הט\"ז דנ\"ל אפי' מונח עליה הרבה מטלטלין זה על זה לא מהני והטעם דלישב עליהם הוה גנאי ביותר אבל אם נתחבר לכותל במסמרין מותר לישב שם עכ\"ל \u0005(ובנה\"כ סתר דבריו וכתב דהרב רמ\"א עצמו הניח שם בצ\"ע מטעם כיון שהספרים שלנו אינן כתב אשורי ע\"ש)\u0006:","\u0003נדות. \u0004 ועיין בא\"ח סימן פ\"ח מדין נשים נדות לתפלה:","\u0003ת\"ח. \u0004 אפי' אינו אלא שונה הלכות ולא שימש ת\"ח כ\"כ בא\"ח סימן קנ\"ד ס\"ה:","\u0003עושין. \u0004 כב\"י היינו דרשות לעשות כן ואין חיוב בדבר וכ\"פ הב\"ח דיכול לגנזם:","\u0003והונח. \u0004 תרתי בעינן דהזמנה לחוד לאו מילתא היא ונראה דה\"ה אם אומר כסף זה לתשמיש ס\"ת אין בו משום אמירה לגבוה דהא יכול למכרה ודוקא גבי צדקה אמרינן כן בסימן רנ\"ח סי\"ג עכ\"ל הט\"ז:","\u0003תפוחי. \u0004 פי' הט\"ז שהם של ס\"ת דרבים ולא מכרוהו שבעה טובי העיר אבל של יחיד מבואר בסי\"ח:","\u0003טעיות. \u0004 זה מדברי ריב\"ש וז\"ל אם חסר אות אחת או שייתר אות א' כיון שהוא פסול אין בו קדושת ס\"ת והוא כחומשין וימכרוהו ז' טובי העיר במעמד אנשי העיר ע\"כ ממילא ה\"ה ביחיד בס\"ת שלו עכ\"ל הט\"ז:","\u0003כבוד. \u0004 כ' הט\"ז נ\"ל דאותן אנשים שנוהגים בשעת לימודם בספר ורוצה להגבי' הספר שלומד פושט ידו ולוקח ספר אחר ומניח תחת ספר זה שלומד דאיסורא איכא משום בזיון כי בזה מבזה הספר להיות לתשמיש מה שיוכל לעשות בעץ או באבן אם לא כשהספר התחתון מונח כבר ודאי שרי להניח השני עליו ובתשו' מהרי\"ל מביא בשם ספר אגודה דאין לעשות תשמישי ס\"ת מבגד שנשתמש בו הדיוט ומ\"מ נראה דהיינו דוקא בדבר שהוא תשמיש קדושה עצמו כגון אותן הנזכרים בא\"ח סימן קנ\"ד אבל חשמיש דתשמיש כגון אותן הנזכרים שם מותר לעשות מבגד ואם נעשה כבר תשמיש קדושה ממנו אסור לעשות אח\"כ ממנו תשמיש דתשמיש דלהקל לא אמרינן דלא נתפס ביה הקדושה עכ\"ל:"]],["מֻתָּר לְדַבֵּק תּוֹרָה, נְבִיאִים וּכְתוּבִים בְּכֶרֶךְ אֶחָד, וּמַנִּיחַ בֵּין כָּל חֻמָּשׁ וְחֻמָּשׁ ד' שִׁיטִין, וּבֵין כָּל נָבִיא וְנָבִיא ג', וְכֵן בֵּין כָּל נָבִיא וְנָבִיא שֶׁל תְּרֵי עָשָׂר, וְאֵין קְדֻשָּׁתָם כִּקְדֻשַּׁת סֵפֶר תּוֹרָה, אֶלָּא כְּחֻמָּשׁ בְּעָלְמָא. \u0005וְכָל זֶה בְּחֻמָּשִׁים הָעֲשׂוּיִם בְּגִלָּיוֹן כְּסֵפֶר תּוֹרָה, אֲבָל בְּשֶׁלָּנוּ שֶׁהֵם נִכְרָכִים, אֵין חִלּוּק בֵּין חֻמָּשׁ לְנָבִיא (הר\"ן)\u0006. וּמֻתָּר לִכְתֹּב כָּל הַתּוֹרָה חֻמָּשׁ חֻמָּשׁ בִּפְנֵי עַצְמוֹ, וְאֵין בָּהֶם קְדֻשַּׁת סֵפֶר תּוֹרָה הַשָּׁלֵם. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁהֵם כְּסֵפֶר תּוֹרָה לְכָל דִּבְרֵיהֶם, אֶלָּא שֶׁאֵין קוֹרִין בָּהֶם בְּצִבּוּר.\nלֹא \u0010c0\u0011 יִכְתֹּב מְגִלָּה בִּפְנֵי עַצְמָהּ שֶׁיִּהְיוּ בָּהּ פָּרָשִׁיּוֹת. וְאֵין כּוֹתְבִין מְגִלָּה לְתִינוֹק לְהִתְלַמֵּד בָּהּ, וְאִם דַּעְתּוֹ לְהַשְׁלִימָהּ לְחֻמָּשׁ, מֻתָּר.\nכָּתַב מְגִלָּה שָׁלֹשׁ שָׁלֹשׁ תֵּבוֹת בְּשִׁיטָה אַחַת, \u0010c1\u0011 מֻתָּר.\nאָסוּר לִרְקֹם פְּסוּקִים \u0010c2\u0011 בְּטַלִּית.\nסִדְרָן שֶׁל נְבִיאִים: יְהוֹשֻׁעַ, שׁוֹפְטִים, שְׁמוּאֵל, מְלָכִים, יִרְמִיָּה, יְחֶזְקֵאל, יְשַׁעְיָה, תְּרֵי עָשָׂר. וְסֵדֶר הַכְּתוּבִים: רוּת, תִּילִּים, אִיּוֹב, מִשְׁלֵי, קֹהֶלֶת, שִׁיר הַשִּׁירִים, קִינוֹת, דָּנִיּאֵל, מְגִלַּת אֶסְתֵּר, עֶזְרָא, דִּבְרֵי הַיָּמִים.",[],["\u0003מגילה. \u0004 ודעת הרי\"ף ושאר פוסקים דמותר משום עת לעשות לה' וגו' שהרי אין הכל יודעים בע\"פ ואין לכל העולם חומשים בב\"ה ויבואו לידי ביטול ק\"ש ותפלה וכתב הב\"ח שכך המנהג פשוט בכל המדינות ע\"כ ומה\"ט שאין כותבין התורה מגלה אין כותבין ג\"כ מהתורה מגלה לתינוק אפי' להתלמד דדוקא חומש בפני עצמו שרי אבל לא מגלה מגלה עכ\"ל הש\"ך וכתב הט\"ז מ\"ש הב\"ח דכן המנהג להתיר היינו כדי להתלמד בו משום עת לעשות וגו' אבל אותן שכותבין פסוקים על הכותל לאיזה סימן טוב לאו שפיר עבדי דהתורה חתומה ניתנה:","\u0003מותר. \u0004 דכיון שיש בה שינוי אינו דומה למגלה מס\"ת:","\u0003בטלית. \u0004 וכ' הלבוש אבל התירו לכתוב פסוקים על המפות של ס\"ת מפני שהם תשמישי קדושה ואסור לנהוג בהם קלות עכ\"ל:"]],["כָּל כִּתְבֵי הַקֹּדֶשׁ אֵין כּוֹתְבִין בְּלֹא שִׂרְטוּט, אֲפִלּוּ כְּתוּבִים עַל הַנְּיָר.\nאָסוּר לִכְתֹּב ג' תֵּבוֹת מִפָּסוּק בְּלֹא שִׂרְטוּט, אִם הוּא כְּתַב אַשּׁוּרִית. \u0005וְאֵין חִלּוּק בֵּין כְּתִיבָה לַחֲקִיקָה בְּעֵצִים אוֹ בְּזָהָב (בֵּית יוֹסֵף בְּשֵׁם ר' יְרוּחָם נָתִיב ב')\u0006 וּמִיהוֹ בְּאִגֶּרֶת שְׁלוֹמִים מֻתָּר לִכְתֹּב אֲפִלּוּ כַּמָּה תֵּבוֹת מֵהַפָּסוּק לִדְבַר \u0010c0\u0011 צַחוּת. \u0005הַגָּה: וְאִם שִׂרְטֵט שִׁיטָה \u0010c1\u0011 הַעֶלְיוֹנָה, שׁוּב לֹא צָרִיךְ (טוּר בְּשֵׁם רַבֵּנוּ תָּם)\u0006. וְיֵשׁ אוֹמְרִים דְּאֵין לִכְתֹּב דְּבָרִים שֶׁל חֹל בִּכְתַב אַשּׁוּרִית שֶׁכּוֹתְבִין בּוֹ הַתּוֹרָה \u0005(שָׁם בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006.",[],["\u0003צחות. \u0004 וכ' הש\"ך מיהו בירושלמי פ' בתרא דמגלה משמע קצת דאפילו בכה\"ג אסור \u0005(ודוקא בכתב אשורית)\u0006 וכ\"כ יש פוסקים:","\u0003העליונה. \u0004 ובס\"ת ממש צריך שרטוט בכולה כדלעיל סימן רע\"א סעיף ה'."]],["\u0003הלכות מזוזה\u0004\nמִצְוַת עֲשֵׂה לִכְתֹּב פ' שְׁמַע \u0005(דְּבָרִים ו, ד ט)\u0006 וְהָיָה אִם שָׁמוֹעַ \u0005(דְּבָרִים יא, יג כא)\u0006 וּלְקָבְעָם עַל מְזוּזַת הַפֶּתַח, וְצָרִיךְ לִזָּהֵר בָּהּ מְאֹד; וְכָל הַזָּהִיר בָּהּ, \u0010c0\u0011 יַאֲרִיכוּ יָמָיו וִימֵי בָּנָיו. וְאִם אֵינוֹ זָהִיר בָּהּ, יִתְקַצְּרוּ. \u0005הַגָּה: וּמִכָּל מָקוֹם אִם אֵין יָדוֹ מַשֶּׂגֶת לִקְנוֹת תְּפִלִּין וּמְזוּזָה, יִקְנֶה תְּפִלִּין וְלֹא מְזוּזָה (יְרוּשַׁלְמִי סוֹף מְגִלָּה ובא\"ח סי' נ\"ח סי\"ב)\u0006, דְּמִצְוָה שֶׁהִיא חוֹבַת הַגּוּף עֲדִיפָא.\nנְתִינָתָהּ בַּטֶּפַח הַחִיצוֹן. \u0005הַגָּה: יֵשׁ אוֹמְרִים כְּשֶׁאָדָם \u0010c1\u0011 יוֹצֵא מִן הַבַּיִת יַנִּיחַ יָדוֹ עַל הַמְּזוּזָה (מהרי\"ל שָׁם וּמוּכָח בַּעֲבוֹדַת כּוֹכָבִים דַּף י\"א)\u0006, וְיֹאמַר: ה' יִשְׁמֹר צֵאתִי וְכו' \u0005(בַּמִּדְרָשׁ)\u0006. וְכֵן כְּשֶׁיִּכָּנֵס אָדָם לְבַיִת, יַנִּיחַ יָדוֹ עַל הַמְּזוּזָה.",[],["\u0003יאריכו. \u0004 דכתיב למען ירבו ימיכם וימי בניכם וגו':","\u0003יוצא. \u0004 וכשיוצא לדרך חוץ לעיר יניח ידיו על המזוזה ויאמר בשמך ט\"ל אטל\"ה כי טל בגימטריא כוז\"ו. כ\"כ במהרי\"ל:"]],["אֵלּוּ הַמְּקוֹמוֹת שֶׁחַיָּבִים בִּמְזוּזָה: אֶחָד שַׁעֲרֵי בָּתִּים וְשַׁעֲרֵי חֲצֵרוֹת, \u0010c0\u0011 מְדִינוֹת \u0010c1\u0011 וַעֲיָרוֹת, רֶפֶת בָּקָר וְלוּלִין וְאוֹצְרוֹת יַיִן וְשֶׁמֶן וּבֵית הָאִשָּׁה וּבֵית \u0010c2\u0011 הַשֻּׁתָּפִים, כֻּלָּם חַיָּבִים. \u0005הַגָּה: וְדַוְקָא כְּשֶׁבֵּית הַשֻּׁתָּפִים יִשְׂרָאֵלִים, אֲבָל בַּיִת שֶׁל יִשְׂרָאֵל וְעוֹבֵד כּוֹכָבִים \u0010c3\u0011 פָּטוּר מִמְּזוּזָה (מָרְדְּכַי ספ\"ק דַּעֲבוֹדַת כּוֹכָבִים)\u0006 וְכֵן חֲצֵרוֹת אוֹ \u0010c4\u0011 עֲיָרוֹת שֶׁמִּקְצָת עוֹבְדֵי כּוֹכָבִים דָּרִים שָׁם, פְּטוּרִין מִמְּזוּזָה \u0005(חִדּוּשֵׁי אֲגֻדָּה פ\"ק דְּיוֹמָא)\u0006.\nבֵּית הַתֶּבֶן, בֵּית הָעֵצִים וּבֵית הַבָּקָר חַיָּבִים. וְאִם הַנָּשִׁים רוֹחֲצוֹת בָּהֶם, כֵּיוָן שֶׁעוֹמְדוֹת שָׁם עֲרֻמּוֹת, אֵין כְּבוֹד שָׁמַיִם לִהְיוֹת שָׁם מְזוּזָה. \u0005הַגָּה: וְדַוְקָא אֵלּוּ, אֲבָל חֶדֶר מַמָּשׁ, אֲפִלּוּ מָקוֹם שֶׁאִישׁ וְאִשָּׁה יְשֵׁנִים וּמְשַׁמְּשִׁים שָׁם, חַיָּב בִּמְזוּזָה (בִּתְשׁוּבַת מהרי\"ל וְכֵן כָּתַב הַבֵּית יוֹסֵף)\u0006. וְיֵשׁ מְקִלִּין וְאוֹמְרִים דִּבְכָל מָקוֹם שֶׁנָּשִׁים שׁוֹכְבוֹת פָּטוּר מִמְּזוּזָה \u0005(בֵּית יוֹסֵף בְּשֵׁם סמ\"ק וְכָל בּוֹ וּמָרְדְּכַי סוֹף הִלְכוֹת מְזוּזָה)\u0006. וְנִרְאֶה לִי דִּבְמָקוֹם שֶׁהַדֶּלֶת מִבִּפְנִים, וּכְשֶׁשּׁוֹכְבִים שָׁם סוֹגְרִים הַדֶּלֶת וְנִמְצָא הַמְּזוּזָה מִבַּחוּץ \u0010c5\u0011 חַיָּב לְכֻלֵּי עָלְמָא \u0005(ד\"ע בד\"מ וכ\"מ בִּתְשׁוּבַת מהרי\"ל סי' צ\"ח)\u0006.\nבֵּית הַכְּנֶסֶת, אִם יֵשׁ בּוֹ דִּירָה לְשׁוּם אָדָם, חַיָּב בִּמְזוּזָה. \u0005הַגָּה: וְאִם בֵּית דִּירָה בָּעֲזָרָה שֶׁלִּפְנֵי בֵּית הַכְּנֶסֶת, הָעֲזָרָה חַיֶּבֶת וּבֵית הַכְּנֶסֶת פָּטוּר. (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006.\nבֵּית הַכִּסֵא וּבֵית הַמֶּרְחָץ וּבֵית הַבֻּרְסְקִי וּבֵית הַטְּבִילָה, פְּטוּרִים, לְפִי שֶׁאֵינָם עֲשׂוּיִים לְדִירַת כָּבוֹד.\nבְּמָקוֹם שֶׁיֵּשׁ טִנּוּף, כְּגוֹן שֶׁתִּינוֹקוֹת מְצוּיִים שָׁם, טוֹב \u0010c6\u0011 לְכַסוֹת הַמְּזוּזָה; וּבִמְקוֹם טָהֳרָה, טוֹב לִהְיוֹת \u0010c7\u0011 נִרְאֵית.\nאַכְסַדְרָה, וְהוּא הַמָּקוֹם שֶׁיֵּשׁ לוֹ ג' כְּתָלִים וְתִקְרָה, אַף עַל פִּי שֶׁיֵּשׁ לָהּ שְׁנֵי פְּצִימִין בְּרוּחַ רְבִיעִית, פְּטוּרָה, מִפְּנֵי שֶׁהַפְּצִימִין לְהַעֲמִיד הַתִּקְרָה הֵם עֲשׂוּיִים וְלֹא מִשּׁוּם מְזוּזוֹת \u0005(ל' הָרַמְבַּ\"ם פ\"ו מֵהַס\"ת ד\"ג)\u0006. אֲבָל אִם יֵשׁ לָהּ מְחִצָּה גַּם בָּרוּחַ הָרְבִיעִית, אַף עַל פִּי שֶׁהִיא נְמוּכָה אוֹ שֶׁעֲשׂוּיָה \u0010c8\u0011 חַלּוֹנוֹת חַלּוֹנוֹת, חַיֶּבֶת.\nמִרְפֶּסֶת, שֶׁהִיא דֶּרֶךְ לַעֲלוֹת בָּהּ לָעֲלִיּוֹת, וּבֵית \u0010c9\u0011 שַׁעַר וְהַגִּנָּה, פְּטוּרִים. וְאִם בַּיִת פָּתוּחַ לְאֶחָד מֵאֵלּוּ, \u0010c10\u0011 חַיָּבִים. וְיֵשׁ אוֹמְרִים שֶׁבֵּית שַׁעַר חַיָּב אֲפִלּוּ אֵין בַּיִת פָּתוּחַ לוֹ. \u0005(טוּר וְהַפּוֹסְקִים בְּשֵׁם ר\"י)\u0006.\nבֵּית שַׁעַר שֶׁפָּתוּחַ לַבַּיִת וְלֶחָצֵר, \u0010c11\u0011 חַיָּב בִּשְׁתֵּי מְזוּזוֹת, אַחַת בְּמָקוֹם שֶׁפָּתוּחַ לַבַּיִת וְאַחַת בְּמָקוֹם שֶׁפָּתוּחַ לֶחָצֵר.\nבֵּית שַׁעַר הָעוֹמֵד בֵּין הַגִּנָּה לַבַּיִת, חַיָּב בִּשְׁתֵּי מְזוּזוֹת, אַחַת בַּמָּקוֹם שֶׁפָּתוּחַ לַבַּיִת וְאַחַת בַּמָּקוֹם שֶׁפָּתוּחַ לַגִּנָּה.\nבֵּית הַמִּדְרָשׁ פָּטוּר מֵהַמְּזוּזָה. וְאִם יֵשׁ בּוֹ פֶּתַח שֶׁרָגִיל לָצֵאת בּוֹ לְבֵיתוֹ, חַיָּב בִּמְזוּזָה בְּאוֹתוֹ פֶּתַח. וְיֵשׁ אוֹמְרִים שֶׁבֵּית הַמִּדְרָשׁ חַיָּב בִּמְזוּזָה, וְנָכוֹן \u0010c12\u0011 לָחוּשׁ לְדִבְרֵיהֶם, אֲבָל לֹא יְבָרֵךְ עָלֶיהָ.\nסֻכַּת הֶחָג, בֶּחָג, וְהַבַּיִת שֶׁבַּסְפִינָה וְהַחֲנוּיוֹת שֶׁבַּשְּׁוָקִים, \u0010c13\u0011 פְּטוּרִים.\nשְׁתֵּי סֻכּוֹת שֶׁל יוֹצְרִים, זוֹ לְפָנִים מִזּוֹ, \u0010c14\u0011 הַפְּנִימִית חַיֶּבֶת וְהַחִיצוֹנָה פְּטוּרָה.\nבַּיִת שֶׁאֵין בּוֹ ד' אַמּוֹת עַל ד' אַמּוֹת, פָּטוּר. וְאִם יֵשׁ בּוֹ כְּדֵי לְרַבֵּעַ ד' אַמּוֹת עַל ד' אַמּוֹת בְּשָׁוֶה, אַף עַל פִּי שֶׁאָרְכּוֹ יָתֵר עַל רָחְבּוֹ אוֹ שֶׁהוּא עָגֹל אוֹ בַּעַל ה' זָוִיּוֹת, \u0010c15\u0011 חַיָּב \u0005(רַמְבַּ\"ם שָׁם ד\"ב)\u0006.\nבַּיִת שֶׁאֵין לוֹ תִּקְרָה, פָּטוּר. הָיָה מִקְּצָתוֹ מְקֹרֶה וּמִקְּצָתוֹ אֵינוֹ מְקֹרֶה, אִם הָיָה הַקֵּרוּי כְּנֶגֶד הַפֶּתַח, חַיָּב בִּמְזוּזָה, וְהוּא שֶׁיִּהְיֶה בַּמְקֹרֶה ד' \u0010c16\u0011 עַל ד'.\nהַבַּיִת, אַף עַל פִּי שֶׁאֵין לוֹ דְּלָתוֹת, חַיָּב בִּמְזוּזָה. וְיֵשׁ מִי \u0010c17\u0011 שֶׁפּוֹטֵר.\nהַרְבֵּה חֲדָרִים, זֶה לְפָנִים מִזֶּה, כֻּלָּם חַיָּבִים בִּמְזוּזָה.\nאִם יֵשׁ בְּבַיִת הַרְבֵּה פְּתָחִים פְּתוּחִים לֶחָצֵר אוֹ לִרְשׁוּת הָרַבִּים, וְנַעֲשׂוּ כֻּלָּם לִכְנִיסַת וִיצִיאַת בְּנֵי הַבַּיִת, כֻּלָּם חַיָּבִים, אֲפִלּוּ נִתְמַעֲטוּ הַדִּיּוּרִים שֶׁאֵין רְגִילִין עַתָּה לָצֵאת וְלָבוֹא אֶלָּא בְּאֶחָד מֵהֶם.\nבַּיִת שֶּׁיֵּשׁ לוֹ פְּתָחִים הַרְבֵּה, אַף עַל פִּי שֶּׁאֵינוֹ רָגִיל לָצֵאת וְלָבוֹא אֶלָּא בְּאֶחָד מֵהֶם, חַיָּב לַעֲשׂוֹת מְזוּזָה בְּכָל פֶּתַח וּפֶתַח. \u0005הַגָּה: הוֹאִיל וְנַעֲשׂוּ לִכְנִיסָה וִיצִיאָה (מַשְׁמָעוּת הַטּוּר)\u0006. מַרְתֵּף שֶׁיֵּשׁ לוֹ פֶּתַח מִן הָרְחוֹב, שֶׁמַּכְנִיסִין בּוֹ יַיִן בְּחָבִיּוֹת גְּדוֹלוֹת, וְיֵשׁ לוֹ פֶּתַח קָטָן מִן הַבַּיִת שֶׁנִּכְנָסִים וְיוֹצְאִים בּוֹ תָּמִיד, אִם הַפֶּתַח הַקָּטָן \u0010c18\u0011 רָאוּי לִמְזוּזָה, הִיא חַיֶּבֶת וְהַגְּדוֹלָה פְּטוּרָה, וְאִם אֵין הַקָּטָן רָאוּי לִמְזוּזָה, הַגְּדוֹלָה חַיֶּבֶת וְהַקָּטָן פָּטוּר \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבָה אַשְׁכְּנַזִּית וְהִיא בת' מהרי\"ל סי' צ\"ט)\u0006.\nאֲרֻבָּה שֶׁבֵּין בַּיִת לָעֲלִיָּה, וְעוֹלִים לָהּ בַּסֻלָּם וְעוֹשִׂים סְבִיב הַסֻלָּם הֶקֵּף מְחִצּוֹת פְּעָמִים לְמַטָּה בְּרַגְלֵי הַסֻלָּם וּפְעָמִים לְמַעְלָה בְּרֹאשׁוֹ, וְיֵשׁ בּוֹ צוּרַת פֶּתַח בַּמָּקוֹם שֶׁעוֹשִׂין אוֹתוֹ, חַיָּב, וְאִם עָשׂוּ לְמַעְלָה וְגַם לְמַטָּה, חַיָּב בִּשְׁתַּיִם.\nפֶּתַח \u0010c19\u0011 שֶׁאֲחוֹרֵי הַדֶּלֶת, אִם יֵשׁ לוֹ פְּצִים טֶפַח, חַיָּב בִּמְזוּזָה.\nפֶּתַח אֶחָד, וְחִלְּקוֹ בְּעַמּוּד בֵּינְתַיִם, כָּל שֶׁיֵּשׁ הֶכֵּר צִיר בָּזֶה וּבָזֶה לְצַד הָעַמּוּד, הֲרֵי הֵם כִּשְׁנֵי פְּתָחִים וְצָרִיךְ מְזוּזָה לְכָל פֶּתַח. אֲבָל כָּל שֶׁאֵין צִירִים לְצַד הָעַמּוּד, אֵין הָעַמּוּד \u0010c20\u0011 מְחַלְּקוֹ לִשְׁנַיִם, שֶׁאֵינוֹ אֶלָּא לְנוֹי בְּעָלְמָא.\nהַשּׂוֹכֵר בַּיִת בְּחוּצָה לָאָרֶץ וְהַדָּר בְּפֻנְדָּק בְּאֶרֶץ יִשְׂרָאֵל, פָּטוּר מִמְּזוּזָה שְׁלֹשִׁים יוֹם. וְהַשּׂוֹכֵר בַּיִת בְּאֶרֶץ יִשְׂרָאֵל, חַיָּב בִּמְזוּזָה מִיָּד, מִשּׁוּם יִשּׁוּב אֶרֶץ יִשְׂרָאֵל. \u0005וְהוּא הַדִּין לְשׁוֹאֵל בַּיִת דִּינוֹ כְּשׂוֹכֵר (בֵּית יוֹסֵף בְּשֵׁם הר\"ר מָנוֹחַ וכ\"מ בְּשַׁ\"ס)\u0006.\nהַשּׂוֹכֵר בַּיִת מֵאֵינוֹ יְהוּדִי, \u0010c21\u0011 חַיָּב בִּמְזוּזָה.",[],["\u0003מדינות. \u0004 מוקפות הרים ובקעות בכמה פרסאות ואין יוצאין ממנה אלא דרך שערים כגון ארץ הגר. רש\"י:","\u0003רפת. \u0004 ואע\"ג דהוא במקום הטינופת מ\"מ לא נפיש זוהמייהו והדרישה כ' כלל הדברים דהיכא דאיכא משום קדושה כגון בהכ\"נ או היכא דאיכא מקום טינופת אז בעינן בית דירה ממש שידור בה תמיד אבל היכא דליכא חד מהנך כגון מתבן כו' אפילו אינם דרים שם ממש כיון דיוצאים ונכנסין בו חשיב בית דירה עכ\"ל ולולין הוא חדר בנוי העשוי לאווזין ותרנגולים. ש\"ך:","\u0003חייבים\u0004 עיין. בסמ\"ע בח\"מ סימן תכ\"ז ס\"ק ב':","\u0003פטור. \u0004 כיון שהמקצת של עובדי כוכבים וגם משום סכנה שלא יאמר העובד כוכבים שהישראל עושה מעשה כשפים. ש\"ך:","\u0003שמקצת. \u0004 אפילו רובם ישראלים פטורים משום סכנה ומזה הטעם אין עושין מזוזה בשערי רחובות כגון בק\"ק קראקא ובק\"ק פראג שקבעו שערים ברחובות היהודים ונסגרים בלילה ולא קבעו בהם לעולם שום מזוזה ועוד מטעם אחר אין עושין שם מזוזה משום דהעובדי כוכבים בודאי יטלוה ויבזוה וא\"כ יהיו גורמין בזיון לכתבי הקדש ומכאן למדו לישראל החוכר חכירות מן השר למכור יין שרף או שכר או מי דבש שקורין שענ\"ק והעובדי כוכבים ממלאים הבית בכל יום ורגילים ליקח המזוזה ונוהגין בהן מנהג בזיון שאין לעשות מזוזה באותן פתחים אא\"כ שהפתח היא במקום שמור מעובדי כוכבים שלא יטלו המזוזה. עכ\"ל הש\"ך:","\u0003חייב. \u0004 וכתב בס' מעדני מלך ואלא מיהא איכא לברורי אם אותו החדר יש לפנים ממנו עוד חדר אחר ושם אינו משכב לנשים לתשמיש המטה והוא חדר שחייב במזוזה אלא מפני שהיכר ציר ודלת סובבין אותו וא\"כ חלל הפתח מבחוץ לתוך חדר משכב נשים כו' נראה בעיני שיש לקיים מצות מזוזה בחדר שאנו דנין עליו לקבעה אחורי הדלת עכ\"ל והב\"ח כתב דנתפשט המנהג שאין עושין מזוזה כ\"א בפתח הבית הסמוך לר\"ה והיינו משום דהנשים רוחצות בבית החורף בחורף ובהחדרים בקיץ ועומדים שם ערומים וכו' ומקרוב נהגו הלומדים לעשות מזוזו' לכל הפתחים שבבית ומיהו צריכין ליזהר שלא יעשו מזוזה במקום שרגילין שם לרחוץ ולכבס טנופת דבגדי קטנים ע\"כ ומיהו נראה שיש לתקן מזוזות בכל הפתחים ויכסה המזוזות כדלקמן ס\"ה. ש\"ך:","\u0003לכסות. \u0004 כתב הט\"ז מזה למדתי שאותן האנשים שאין עושין מזוזה מחמת שאומרים שגנבים גונבים אותה משם ונוהגין בזיון שאין זה מציל עליהם שיכולים ליתן המזוזה שם באופן שלא תהיה מגולה כלל מבחוץ אפי' נגד השם של שד\"י דזה עכ\"פ יותר טוב מלבטל המצוה לגמרי וכתב בב\"י בשם סמ\"ג ואפילו בפתח הבית במקום שתחלת שליש העליון הוא למעלה מי' טפחים יכול להניחה ואע\"פ שהחזירים מצויים שם עכ\"ל:","\u0003נראית. \u0004 כ' הט\"ז נ\"ל דאין לעשות בלי כיסוי כלל דנמשך מזה עבירה שע\"י משמוש בכל פעם ימחק שם שד\"י כמו שאנו רואין ברוב בתים אלא יכסהו בחתיכ' זכוכית וממילא יהיה השם נראה ובזה בטלה גם טענת המקילים בעשיית מזוזה מחמת שמצוי שם טינופת או הנשים רוחצות שם דבזה הוי כיסוי אע\"פ שנראה רק בחדר שאיש ואשתו משמשים שם לא די בכיסוי זכוכית וצריך לכסותה בשעוה עכ\"ל:","\u0003חלונות. \u0004 פירוש מכל הרוחות. נ\"י:","\u0003שער. \u0004 הוא בית קטן אצל שער החצר והגנה שהשומר יושב שם פטורים כיון שאינם מיוחדים לדירה:","\u0003וי\"א. \u0004 כתב הש\"ך וצ\"ע דהא הי\"א אלו גם במרפסת וגנה מחייבין ועב\"ח ופרישה:","\u0003בשתי. \u0004 כתוב בטור מלבד הפתח שנכנסין לשם מן רשות הרבים דפשיטא שצריך מזוזה:","\u0003לחוש. \u0004 בטור כ' וכן עשה הר\"מ מרוטנבורג מזוזה לבה\"מ ואמר כשהיה ישן בו שינת צהרים היה רוח רעה מבעתו קודם שתיקן בו מזוזה והב\"ח כתב דנכון הוא כשיקבע מזוזה בפתח הבית ויברך עליה שיהא דעתו ג\"כ על קביעת המזוזה שבבה\"מ ויקבע אותם זה אחר זה תחלה בפתח הבית ואח\"כ בפתח בה\"מ וברכה זו חוזרת על שניהם:","\u0003פטורים. \u0004 מפני שהם דירת עראי וכ' הט\"ז ונ\"ל אפי' אם יושבים בהם בכל יום פטורים דכיון דאינם שם בלילה מקרי עראי כמ\"ש בח\"מ סימן ק\"מ ס\"ח לענין חזקה אבל חנות שהוא בביתו פתוח לרשות הרבים פשיטא שצריך מזוזה לפתחיו עכ\"ל:","\u0003הפנימית. \u0004 ששם הוא דר ומצניע קדרותיו הלכך חייבת ובחיצונה הוא עושה מלאכתו ומוציא קדרותיו למכור ואינו דר שם לכך פטור ול\"ד לבית שער דלעיל דקביע תשמישו משא\"כ הכא. ש\"ך:","\u0003חייב. \u0004 כתב הש\"ך מאחר דיש פלוגתא בזה נראה דיש לקבעה בלא ברכה או שיברך מתחל' על אחרת ויהא דעתו גם על זו:","\u0003על. \u0004 או כדי לרבע ד' על ד' להרמב\"ם:","\u0003שפוטר. \u0004 ואם קבעה קודם תליית הדלת לא יצא חובתו כשנותן הדלת אח\"כ דהוי תעשה ולא מן העשוי כ\"כ הלבוש ולצאת ידי שניהם יתלה בה הדלת מיד ויקבענה ואם א\"א לתלותה מיד יקבענה בלא ברכה או יברך תחלה על אחרת ויהא דעתו גם על זו וכשיתלה בה הדלת יטלנה ויחזור ויעשה כך ובזה יוצא ידי כולם עכ\"ל הש\"ך:","\u0003ראוי. \u0004 שיש בו גבוה עשרה ורחב ארבעה כדלקמן סימן רפ\"ז:","\u0003שאחורי. \u0004 פירש רש\"י כגון שיש במקצוע הבית פצים קבוע לשני פתחים מחותכים א' לצפון וא' למערב וקבעו המזוזה בפצים בחלל הפתח הצפוני וכשהדלת פתוח הוי אחורי הדלת אם יש בעובי הפצים עובי הבדלת טפח בין פתח לפתח צריך מזוזה אחרת לפתח מערבי הואיל ואין המזוזה בחללה ואם לאו א\"צ מזוזה אחרת שהרי היא כמונחת בחללה עצמו ע\"כ ויראה מכאן אותן פתחים שהם חלוקים ועמוד באמצע די להם במזוזה א' אפי' אם יש בעובי העמוד טפח דלא מחייב בשתים אלא כשא' בצפון וא' במערב אבל כששני הפתחים ברוח א' אפילו אם יש בעובי הפצים טפח חשוב הכל כפתח א' עכ\"ל ומפרש הט\"ז דברי רש\"י דר\"ל דשני הפתחים הם בפצים עצמו מחותכים בו דהיינו שבמקצוע מערבית צפונית עומד פץ א' עב ורחב ונחתך בו חתך גדול כדי שיעור פתח מצד צפון לתוך חלל הבית ושם נכנסין ויוצאין מצפון לבית ומבית לצפון ועוד נחתך שם שיעור פתח מצד מערב לחלל הבית ושם הוי כניסה ויציאה מבית למערב וממערב לבית ועשה המזוזה בחלל הפתח המערבי דהיינו באותו צד שהוא ימין הנכנס ממערב לבית וא\"כ המזוזה של פתח המערבי פשיטא שהיא כדין אלא דפתח הצפוני יש חילוק אם יש באותו חלק פצים המבדיל בין מערב לצפון שיעור טפח צריך מזוזה אחרת לצפוני אבל אם אין שם הבדל טפח חשבינן אותו הבדל כמאן דליתי' ומתכשר גם הצפוני כאילו גם הוא בחלל המערבי וימין א' לשניהם סגי ומה שנקט רש\"י לשון דרומי ומערבי הוא נמי בדרך זה אלא שבזה צ\"ל שהמזוזה בפתח הדרומי בחלק ימין הנכנס ופתח מערבי מתכשר באותה מזוזה ג\"כ אם אין טפח בהבדל שהרי היא ימין לשניהם עכ\"ל:","\u0003מחלקו. \u0004 מבואר בטור דהיינו אם הוא בדרך שאין נבדלין זה מזה אלא אם זה נפתח גם השני נפתח משא\"כ אם יש שער א' גדול וסמוך לו שער קטן כדרך העשירים שאינם רוצים שהשער הגדול יהיה פתוח אלא משתמשים תמיד בקטן רק לפרקים בגדול בזה צריך ב' מזוזות עכ\"ל הט\"ז:","\u0003חייב. \u0004 לאחר ל' יום בח\"ל ובא\"י מיד וקמ\"ל דלא אמרינן כיון שהבית של עובדי כוכבים תפטור לגמרי ממזוזה מיהו כל זה היכא דליכא משום סכנה בבית של עובדי כוכבים דאל\"ה פטור ממזוזה כדלעיל ס\"א עכ\"ל הש\"ך:"]],["אֵין הַפֶּתַח חַיָּב בִּמְזוּזָה, אֶלָּא אִם כֵּן יֵשׁ לוֹ שְׁתֵּי \u0010c0\u0011 מְזוּזוֹת וּמַשְׁקוֹף.\nבַּיִת שֶׁיֵּשׁ לוֹ מְזוּזָה מִכָּאן וּמִכָּאן, וְכִפָּה כְּמִין קֶשֶׁת עַל שְׁתֵּי הַמְּזוּזוֹת בִּמְקוֹם הַמַּשְׁקוֹף, אִם יֵשׁ \u0010c1\u0011 בְּגֹבַהּ הַמְּזוּזוֹת י' טְפָחִים אוֹ יוֹתֵר, חַיָּב. וְאִם אֵין בּוֹ י' טְפָחִים, פָּטוּר, מִפְּנֵי שֶׁאֵין לוֹ מַשְׁקוֹף. \u0005הַגָּה: וְכָל שֶׁכֵּן פֶּתַח שֶׁאֵין לוֹ גֹּבַהּ עֲשָׂרָה טְפָחִים, דְּפָטוּר מִמְּזוּזָה (כ\"מ בַּטּוּר וּפוֹסְקִים עַיִּןִ בֵּית יוֹסֵף)\u0006 הַמִּנְהָג נִתְפַּשֵּׁט בִּמְדִינוֹת אֵלּוּ דְּרֹב עוֹלָם סוֹמְכִין עַל מְזוּזָה אַחַת שֶׁעוֹשִׂין עַל פֶּתַח בָּתֵּיהֶם, וְאֵינוֹ נָכוֹן, וְאֵין לָהֶם עַל מַה שֶּׁיִּסְמֹכוּ, לָכֵן כָּל \u0010c2\u0011 יְרֵא שָׁמַיִם יְתַקֵּן בֵּיתוֹ כְּדִינוֹ בְּכָל הַפְּתָחִים הַחַיָּבִים, וּכְמוֹ שֶׁנִּתְבָּאֵר \u0005(מהרי\"ל בִּתְשׁוּבָה וּבְהל' מְזוּזָה)\u0006.",[],["\u0003מזוזות. \u0004 בטור כתב פתח שאין לו אלא מזוזה אחת פירש\"י כגון שמצד אחד עובר בית אם המזוזה ואם מצד ואם הפתח הכותל להלאה פתח מצד ימין כזה שמאל כזה ממלא כל מהפתח כזה חייב פטור הרוח חייב אע\"פ שאין פצים בצד א' מ\"מ כותלי הבית שמן הצדדים חשיבי כמזוזות ע\"כ וכתב הש\"ך דאף מצד \u0005(שמאל דפטור)\u0006 [ימין] נ\"ל דיקבענה בלא ברכה:","\u0003בגובה. \u0004 פירוש שבעינן שיהא גבוה מן הארץ עשרה בשוה בלי עיקום דמן התחלת העיקום אינו נחשב בכלל העשרה טפחים וזה דעת הרמב\"ם אבל לרש\"י אף העיקום הוא מצרף לגובה עשרה טפחים כל שיש בחללו ארבעה טפחים ואפי' אם מתחיל מן הארץ להתעקם אבל אחר שאין שם חלל ארבעה מיקרי עיקום ולא מצטרף לשיעור גובה י' טפחים מן הארץ וצ\"ע למעשה היאך נעביד באם יש גובה י' טפחים בשוה בלי עיקום ואח\"כ יש עיקום אבל יש בחללו ד' שיעור גדול עד למעלה אם נעשה המזוזה במקום שכלה מקום השוה והיינו כהרמב\"ם יש לחוש דילמא קי\"ל כרש\"י דאף העיקום שלמעלה בשיעור הגובה יחשב כיון שיש שם ד' בחללו ממילא נעשה המזוזה למטה משליש העליון וזה פסול אפילו דיעבד כמ\"ש בסי' רפ\"ט ואם נעשה אותה למעלה במקום הרחב בשליש העליון שהוא עקום דילמא קי\"ל כהרמב\"ם דשם לא מצטרף לגובה והוה כעושה מזוזה למעלה במשקוף ונראה דיש לעשותה בשליש העליון דהיינו למעלה משני שלישים שלמטה דבזה כשר גם להרמב\"ם דאע\"פ שאין העיקום מצטרף לענין גובה עשרה מלמטה במזוזות מ\"מ כיון דכשר למטה בגובה עשרה קודם העיקום והוי עליה חיוב אז גם חלל העליון שייך לחיוב שלמטה והכל בכלל שעריך עד המשקוף וכו' ועכ\"פ לא יניחה למעלה מכתפיו כמ\"ש בב\"י בסי' רפ\"ט עכ\"ל הט\"ז:","\u0003ירא שמים. \u0004 כ' הט\"ז שכל מי שנגע יראת אלהים בלבו ורוצה לישב בטח ממורא רוחות רעות ח\"ו יעשה מזוזות לכל פתחיו בכ\"מ שהוא בית דירה ולא אכפת לן אם יש שם טינופת כמ\"ש הטור וב\"י וטעמם דהמזוזה גבוה עשרה וגם טוב לתקן בכיסוי זכוכית ובחדר שאיש ואשה משמשים יכסה אותה בשעוה כמ\"ש בסימן רפ\"ו ס\"ק ח' ע\"ש:"]],["כֵּיצַד כּוֹתְבִין אֶת הַמְּזוּזָה, כּוֹתְבִין שְׁתֵּי פָּרָשִׁיּוֹת שְׁמַע \u0005(דְּבָרִים ו, ד ט)\u0006 וְהָיָה אִם שָׁמוֹעַ \u0005(דְּבָרִים יא, יג כא)\u0006 עַל דַּף אֶחָד בִּירִיעָה אַחַת, וְעוֹשֶׂה לָהּ רֶוַח מִלְּמַטָּה וְרֶוַח מִלְּמַעְלָה כְּמוֹ חֲצִי צִפֹּרֶן, וּבִתְחִלָּתָהּ יְשַׁיֵּר כְּדֵי לָגֹל אוֹתָהּ אַחַר שֶׁתִּכָּרֵךְ. \u0005וּבְסוֹפָהּ אֵין צָרִיךְ לְהַנִּיחַ \u0010c0\u0011 כְּלָל (טוּר)\u0006.\nצָרִיךְ לְכָתְבָהּ בְּדַף אֶחָד. וְאִם כְּתָבָהּ בִּשְׁנַיִם אוֹ בְּג' דַּפִּין, כְּשֵׁרָה.\nכְּתָבָהּ שֶׁלֹּא עַל הַסֵדֶר, אֲפִלּוּ שָׁכַח מִלִּכְתֹּב אוֹת אַחַת, פְּסוּלָה וְאֵין לָהּ \u0010c1\u0011 תַּקָּנָה. וְאֵין צָרִיךְ לוֹמַר אִם הִקְדִּים פָּרָשָׁה לְפָרָשָׁה.\nכְּתָבָהּ בִּשְׁנֵי \u0010c2\u0011 עוֹרוֹת, אַף עַל פִּי שֶׁתְּפָרָן, פְּסוּלָה.\nצְרִיכָה עִבּוּד לִשְׁמָהּ, \u0010c3\u0011 לְכַתְּחִלָּה. אֲבָל בְּמָקוֹם שֶׁאִם יַמְתִּין לְעוֹר מְעֻבָּד לִשְׁמָהּ יִתְבַּטֵּל מֵהַמִּצְוָה, יִכְתְּבֶנָּה עַל עוֹר שֶׁאֵינוֹ מְעֻבָּד, הַנִּמְצָא, \u0010c4\u0011 וִיקַיֵּם הַמִּצְוָה מִיָּד בְּעוֹד שֶׁמְּבַקֵּשׁ עוֹר מְעֻבָּד לִשְׁמָהּ.\nכְּתָבָהּ עַל הַקְּלָף אוֹ עַל הַגְּוִיל, כְּשֵׁרָה. לֹא אָמְרוּ: דּוּכְסוּסְטוֹס, אֶלָּא לְמִצְוָה. \u0005וּקְלָפִים שֶׁלָּנוּ כְּשֵׁרִים לַכֹּל (מָרְדְּכַי הֲלָכוֹת קְטַנּוֹת)\u0006.\nדִּינָהּ \u0010c5\u0011 לְעִנְיַן הַדְּיוֹ וְהַכְּתִיבָה וְהַתַּגִּין שֶׁל שַׁעְטְנֵ\"ז גֵּ\"ץ, כְּמוֹ בְּסֵפֶר תּוֹרָה.\nצְרִיכָה שִׂרְטוּט. וְאִם כְּתָבָהּ בְּלֹא שִׂרְטוּט, פְּסוּלָה.\nכּוֹתֵב כָּל שִׁיטוֹתֶיהָ שָׁווֹת, שֶׁלֹּא תְּהֵא אַחַת אֲרֻכָּה מֵחֲבֶרְתָּהּ. וְאִם הֶאֱרִיךְ בְּשִׁיטָה אַחַת יוֹתֵר מִבְּאוֹתָה שֶׁלְּפָנֶיהָ, וּבְאוֹתָהּ שֶׁתַּחְתֶּיהָ קִצֵּר יוֹתֵר מִבְּאוֹתָה שֶׁלְּפָנֶיהָ וְלִפְנֵי פָּנֶיהָ, כְּשֵׁרָה, וּבִלְבַד שֶׁלֹּא יַעֲשֶׂנָּה כְּקֻבָּה אוֹ כְּזָנָב אוֹ כְּעִגּוּל.\nעַל הָאָרֶץ \u0010c6\u0011 \u0005(דְּבָרִים יא, כא)\u0006 יִכְתֹּב בְּרֹאשׁ הַשִּׁיטָה אַחֲרוֹנָה, וְלֹא יִכְתֹּב בָּהּ יוֹתֵר.\nנָהֲגוּ לַעֲשׂוֹתָהּ כ\"ב שִׁיטִין.\nצָרִיךְ לְכָתְבָהּ בְּיָמִין, כְּמוֹ בִּתְפִלִּין.\nרֶוַח שֶׁבֵּין פָּרָשַׁת שְׁמַע \u0005(דְּבָרִים ו, ד ט)\u0006 לְפָרָשַׁת וְהָיָה אִם שָׁמוֹעַ \u0005(דְּבָרִים יא, יג כא)\u0006 מִצְוָה לַעֲשׂוֹת פָּרָשָׁה \u0010c7\u0011 סְתוּמָה. וְאִם עֲשָׂאָהּ פְּתוּחָה, כְּשֵׁרָה, לְפִי שֶׁאֵינָהּ סְמוּכָה לָהּ בַּתּוֹרָה.\nכּוֹרְכָהּ מִסוֹפָהּ לְרֹאשָׁהּ, מֵאֶחָד \u0005(דְּבָרִים ו, ד)\u0006 כְּלַפֵּי שְׁמַע \u0005(דְּבָרִים ו, ד)\u0006.\nאָסוּר לְהוֹסִיף בָּהּ מְאוּמָה, אֶלָּא שֶׁמִּבַּחוּץ כּוֹתְבִין: שַׁדַּי, כְּנֶגֶד תֵּבַת וְהָיָה \u0005(דְּבָרִים יא, יג)\u0006 שֶׁבִּפְנִים. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים נֶגֶד הָרֶוַח שֶׁבֵּין הַפָּרָשִׁיּוֹת (טוּר בְּשֵׁם הָרֹא\"שׁ וּמָרְדְּכַי ה\"ק וְרַמְבַּ\"ם והגה\"מ בְּשֵׁם סה\"ת)\u0006, וְכֵן נוֹהֲגִין, וּמַנִּיחִים נֶקֶב בַּקָּנֶה נֶגֶד שֵׁם שַׁדַּי, שֶׁיְּהֵא נִרְאֶה מִבַּחוּץ \u0005(שָׁם בְּמָרְדְּכַי והגמי\"י)\u0006. עוֹד נוֹהֲגִין לִכְתֹּב מִבַּחוּץ: כוז\"ו במוכס\"ז כוז\"ו נֶגֶד ה' אֱלֹהֵינוּ ה' \u0005(דְּבָרִים ו, ד)\u0006 \u0005(טוּר)\u0006 וְיַהֲפֹךְ אֵלֶּה הָאוֹתִיּוֹת מִכְּתִיבַת הַמְּזוּזָה, כְּדֵי שֶׁיַּגִּיעַ כָּל אוֹת נֶגֶד הָאוֹת שֶׁמִּתְחַלֵּף בּוֹ בְּאַלְפָ\"א בֵּיתָ\"א \u0005(הגהמי\"י)\u0006, אֲבָל בִּפְנִים אֵין לְהוֹסִיף שׁוּם דָּבָר עַל ב' פָּרָשִׁיּוֹת \u0005(טוּר וְרַמְבַּ\"ם)\u0006.",[],["\u0003כלל. \u0004 רק מעט כדי שיהיו האותיות שבסוף השטות מוקפות גויל. ש\"ך:","\u0003תקנה. \u0004 לפי שאין תולין בה כמו שתולין בס\"ת משום דבעינן שתהא נכתבת כסדרן ולפ\"ז יכול לגרוד ממטה למעלה עד מקום החסרון ויכתוב שם החסרון ואח\"כ יכתוב מה שגרד על מקום הגרד דבכה\"ג הוי כסדרן ועיין בא\"ח סימן ל\"ב סכ\"ג וכ\"ד עכ\"ל הש\"ך וכ' הט\"ז דיש לתמוה על המחבר שכ' ואצ\"ל בהקדים פרשה ואיפכא מסתברא דיותר יש לפסול בכותב שלא כסדר בפרשה עצמה מבהקדים פרשה לפרשה וכן מצינו בא\"ח סימן ס\"ד קראה למפרע בד\"א בסדר הפסוקים אבל הקדים פרשה וכו' ע\"ש:","\u0003עורות. \u0004 כלומר בשני קלפין מחולקין:","\u0003לכתחלה. \u0004 ודעת רוב הפוסקים נראה דאפי' דיעבד פסולה בעור שאינו מעובד לשמה. כ\"כ הט\"ז וש\"ך:","\u0003ויקיים. \u0004 כתב הש\"ך דיקבענה בלא ברכה דכדאי הם הרמב\"ם וסייעתו לסמוך עליהם בשעת הדחק דלא כמ\"ש הב\"ח דלא יקבענה כלל אלא יקבענה שם וישתדל להמציא אחרת כשירה עכ\"ל:","\u0003לענין. \u0004 כ' הש\"ך ושאר דיני כתיבתה בחסרות ויתרות הוא כמו שכותבין אותן הפרשיות בתפילין ונתבאר בא\"ח סימן ל\"ב וכ' הטור שנכתבה שלא מן הכתב והרב לא כתבו שסמך אמ\"ש בא\"ח גבי תפילין וה\"ה למזוזה עכ\"ל והט\"ז כ' דמ\"מ יש לכתוב מתוך הכתב דהיינו מתוך ספר מוגה דשמא ישכח החסרות ויתרות ומש\"ה לא זכרו בש\"ע:","\u0003בראש. \u0004 הטעם דשטה שלפניה מסיימת השמים ורחוקה מהתחלת שטה האחרונה דכתיב שם על הארץ והוא רמז כי היכי דמרחקי שמים מארץ כן ירבו ימיכם. ט\"ז:","\u0003סתומה. \u0004 כ' הש\"ך ומ\"מ אינו יכול לעשות סתומה שכשרה אליבא דכ\"ע דהיינו שיהיה חלק באמצע כמ\"ש בסי' ער\"ה ס\"ב שהרי צריך להתחיל שטה שביעית והיה אם שמוע וגו' אלא יעשה סתומה הכשרה לדעת הרמב\"ם כמ\"ש הרב שם ועיין במשובת מהרש\"ל סי' ל\"ז עד כאן לשונו:"]],["בָּא לְקָבְעָהּ, יַנִּיחֶנָּה בִּשְׁפוֹפֶרֶת שֶׁל קָנֶה אוֹ שֶׁל כָּל דָּבָר, וְיִקְבָּעֶנָּה בִּמְקוֹמָהּ וִיבָרֵךְ: אקב\"ו לִקְבֹּעַ מְזוּזָה. וְלֹא יְבָרֵךְ בִּשְׁעַת כְּתִיבָתָהּ. \u0005וְהַקּוֹבֵעַ ב' אוֹ ג' מְזוּזוֹת, מְבָרֵךְ בְּרָכָה אַחַת לְכֻלָּן (בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006.\nאֵיזֶהוּ מְקוֹם קְבִיעָתָהּ, בְּתוֹךְ חָלָל שֶׁל פֶּתַח, בַּטֶּפַח הַסָמוּךְ לַחוּץ, \u0005וְאִם \u0010c0\u0011 שִׁנָּה, אֵינוֹ מְעַכֵּב, וּבִלְבַד שֶׁיַּנִּיחֶנָּה בַּמְּזוּזָה עַצְמָהּ (טוּר)\u0006, בִּתְחִלַּת שְׁלִישׁ הָעֶלְיוֹן גֹּבַהּ הַשַּׁעַר. וְאִם קָבַע לְמַעְלָה מִזֶּה, כְּשֵׁרָה, וְהוּא שֶׁיַּרְחִיקֶנָּה מֵהַמַּשְׁקוֹף \u0010c1\u0011 טֶפַח. וְצָרִיךְ לְקָבְעָהּ עַל יְמִין הַנִּכְנָס. \u0005וְאֵין חִלּוּק בֵּין אִם הוּא \u0010c2\u0011 אִטֵּר יָד אוֹ לֹא (מָרְדְּכַי ה\"ק)\u0006. וְאִם קְבָעָהּ מִשְּׂמֹאל, פְּסוּלָה.\nמִי שֶׁחוֹלֵק בֵּיתוֹ לִשְׁנַיִם, וּבְכָל חֵלֶק פֶּתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים, וּבַמְּחִצָּה הַחוֹלֶקֶת יֵשׁ פֶּתַח מִזֶּה לָזֶה, בְּמָקוֹם שֶׁעוֹשֶׂה הַחוֹר שֶׁבַּסַף \u0010c3\u0011 שֶׁצִּיר הַדֶּלֶת סוֹבֵב בּוֹ וּמַעֲמִיד שָׁם הַדְּלָתוֹת, הוּא הַבַּיִת, וּבְדֶרֶךְ יָמִין שֶׁנִּכְנָסִים לוֹ, קוֹבְעִים אוֹתָהּ.\nכֵּיצַד קוֹבְעָהּ, יְמַסְמְרֶנָּה \u0010c4\u0011 בְּמַסְמְרִים בִּמְזוּזַת הַפֶּתַח, אוֹ יַחְפֹּר בָּהּ חֲפִירָה וְיִקְבְּעֶנָּה בָּהּ. וְלֹא יַעֲמִיק לַחְפֹּר טֶפַח בָּעֹמֶק, שֶׁאִם עָשָׂה כֵן פְּסוּלָה.\nקְבָעָהּ בִּמְזוּזַת הַפֶּתַח, בְּעוֹדָהּ תְּלוּשָׁה, וְאַחַר כָּךְ חִבְּרָהּ לַפֶּתַח \u0010c5\u0011 פְּסוּלָה.\nצְרִיכָה לִהְיוֹת זְקוּפָה, אָרְכָּהּ לְאֹרֶךְ מְזוּזַת הַפֶּתַח, וִיכַוֵּן שֶׁיְּהֵא שְׁמַע \u0005(דְּבָרִים ו, ד)\u0006 דְּהַיְנוּ סוֹף הַגְּלִילָה, לְצַד חוּץ. \u0005הַגָּה: וְכֵן \u0010c6\u0011 נָהֲגוּ. (בֵּית יוֹסֵף)\u0006 אֲבָל יֵשׁ אוֹמְרִים שֶׁפְּסוּלָה בִּזְקוּפָה, אֶלָּא צְרִיכָה לִהְיוֹת שְׁכוּבָה, אָרְכָּהּ לְרֹחַב מְזוּזַת הַפֶּתַח \u0005(טוּר וְהַפּוֹסְקִים בְּשֵׁם רַבֵּנוּ תָּם)\u0006. וְהַמְּדַקְדְּקִין, יוֹצְאִין יְדֵי שְׁנֵיהֶם, וּמַנִּיחִים אוֹתָהּ בְּשִׁפּוּעַ וּבַאֲלַכְסוֹן \u0005(טוּר וְהַגָּהוֹת מַיְמוֹנִי ומהרי\"ל ות\"ה סי' נ\"ב)\u0006, וְכֵן רָאוּי לִנְהֹג, וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ. וִיכַוֵּן שֶׁיְּהֵא רֹאשׁ הַמְּזוּזָה, דְּהַיְנוּ שְׁמַע \u0005(דְּבָרִים ו, ד)\u0006 לְצַד פְּנִים, וְשִׁיטָה אַחֲרוֹנָה לְצַד חוּץ.",[],["\u0003שינה. \u0004 כתב הש\"ך דדעת הרב משמע שאפי' הניחה אחורי הדלת כשרה בדיעבד אבל דעת הרמב\"ם נראה דפסולה וכ\"כ הלבוש הלכך יש לחזור ולתקנה כהוגן ובספר מעדני מלך כתב דהנהו בתים הפתוחים לרחוב העובדי כוכבים ומניחים מפני כן המזוזות אחורי הדלת דיש להם על מה שיסמוכו על דברי הטור והרב עכ\"ל:","\u0003טפח. \u0004 וכתב ב\"י אבל בדיעבד כשר בלא הרחקה מלמעלה ואם הפתח גבוה הרבה אין לעשות המזוזה גבוה מכתיפיו דאז אינה נראה לעיניו בכניסה ויציאה עכ\"ל:","\u0003אטר. \u0004 כתב הש\"ך ונראה דה\"ה אם אחד לבדו דר בבית והוא אטר או שכל בני הבית אטרים אפ\"ה יעשנה בימין כל אדם דל\"ד לתפילין שהם מצות שבגופו לכך אזלינן בתר ימין דידיה משא\"כ מזוזה שהיא חובת הבית הלכך אזלינן בתר ימין של כל אדם וכ\"נ לדעת הרב שלעולם מניחה בימין וכן נוהגין עכ\"ל:","\u0003שציר. \u0004 כתב הט\"ז דבזה יש ספק איזה מהם ימין לביאה או ליציאה ע\"כ אזלינן בתר היכר ציר ומזה יש ללמוד במזוזה שעושה בפתח הפתוח מבית לחצר אם יש לילך אחר ימין של הנכנס לבית או אחר ימין הנכנס מחצר לבית והדין הוא כך אם החצר הוא סתום מכל צדדיו בלי פתח רק מבית לתוכו אז הוי החצר כמו חדר ולא אכפת לן בהיכר ציר הדלח ואזלינן בתר ימין הנכנס מבית לחצר ושם עושה המזוזה אבל אם יש פתח מהחצר למבוי אחר או לרה\"ר מלבד פתח הבית לתוכה אז אזלינן בתר היכר ציר דבאיזה צד דיש היכר ציר הפתח נחשב כמו בית ואזלינן בתר ימין הנכנס לתוכו ומבואר עוד בתשו' מהרי\"ל באם יש בית החורף וחדר גדול וכל א' יש לו פתח לחצר ובאותו החדר יש בו חדר קטן ויש לו ב' פתחים א' לבית החורף וא' לחדר הגדול אזלינן בפתחי חדר הקטן בתר היכר ציר דידהו דאם היכר ציר דפתח שפתוח לבית החורף הוא בבית החורף והיכר ציר דפתח הפתוח לחדר גדול הוא בחדר גדול חייב לעשות ב' המזוזות של פתחי חדר קטן האחד לימין הנכנס בבית החורף והב' לימין הנכנס מחדר קטן לגדול ואם היכר ציר דידהו בתוך חדר קטן עושה שניהם לימין הנכנס לחדר קטן הן מבית החורף הן מחדר גדול ואילו לא היה פתח מחדר גדול לחצר לא אזלינן בחדר קטן בתר היכר ציר היכן הוא אלא החדר קטן היה נחשב בכלל החדר גדול ועושה מזוזה בימין הנכנס מבית החורף לחדר קטן ובימין הנכנס מחדר קטן לגדול עכ\"ל וכ' הלבוש ופתח שנכנסים בו מן הבית לבית החורף שלנו עושין המזוזה בימין הכניסה שנכנסין מן הבית לבית החורף דעיקר תשמיש שלנו הוא בבית החורף ולא משגחינן כלל בהיכר ציר דבין היא מבחוץ או מבפנים עושין המזוזה תמיד בימין הכניסה ע\"כ ופשוט הוא. ש\"ך:","\u0003במסמרים. \u0004 ואם נתנה שם לפי שעה א\"צ לקבוע במסמרים כ\"כ הב\"ח מהירושלמי:","\u0003פסולה. \u0004 דהוי תעשה ולא מן העשוי:","\u0003נהגו. \u0004 כלומר כן נהגו בשאר מדינות ובמלכותו של המחבר כדאי' בב\"י אבל י\"א וכו' וכן נוהגין במדינות אלו עכ\"ל הש\"ך:"]],["סֵפֶר תּוֹרָה אוֹ \u0010c0\u0011 תְּפִלִּין שֶׁבָּלוּ, אֵין עוֹשִׂין מֵהֶם מְזוּזָה. וְאֵין כּוֹתְבִין אוֹתָהּ עַל גִּלְיוֹנֵי סֵפֶר תּוֹרָה, לְפִי שֶׁאֵין מוֹרִידִין מִקְּדֻשָּׁה חֲמוּרָה לִקְדֻשָּׁה קַלָּה. \u0005הַגָּה: אֲבָל מֻתָּר לְתַקֵּן הַסֵּפֶר תּוֹרָה עַצְמָהּ עִם גִּלְיוֹנוֹתֶיהָ, אִם אִי אֶפְשָׁר לְתַקְּנָהּ בְּעִנְיָן אַחֵר וְהָיָה צָרִיךְ לְגָנְזָהּ בְּלָאו הָכֵי (מהר\"מ פַּאדוֹאָה סִימָן פ\"ד)\u0006. אֲבָל אִם אֶפְשָׁר לְתַקְּנָהּ בְּעִנְיָן אַחֵר, אַף עַל פִּי שֶׁהַסֵּפֶר תּוֹרָה מִגְּוִילִין וְרוֹצֶה לְדַבֵּק עָלֶיהָ קְלָפִים, לֹא יַחְתֹּךְ הַגִּלְיוֹנוֹת לְתַקְּנָהּ, דְּאֵין אִסּוּר לְתַקְּנָהּ מִבַּחוּץ בִּקְלָף אַף עַל פִּי שֶׁהַסֵּפֶר תּוֹרָה מִגְּוִילִין \u0005(ג\"ז שָׁם)\u0006.",[],["\u0003שבלו. \u0004 כגון שנכתב פ' שמע בס\"ת בסוף הדף לא יוסיף לכתוב למטה בגליון פ' והיה אם שמוע דאע\"ג דהשתא נכתבו כסדרן וכהלכתן מ\"מ אין מורידין מקדושה חמורה לקדושה קלה. ש\"ך:"]],["מְזוּזַת יָחִיד נִבְדֶּקֶת פַּעֲמַיִם בְּשֶׁבַע שָׁנִים. וְשֶׁל רַבִּים, פַּעֲמַיִם בְּיוֹבֵל.\nהַשּׂוֹכֵר בַּיִת מֵחֲבֵרוֹ, הַשּׂוֹכֵר חַיָּב לִקְבֹּעַ בָּהּ מְזוּזָה וּלְתַקֵּן מְקוֹם קְבִיעוּתָהּ. \u0005וַאֲפִלּוּ שָׂכַר הַבַּיִת בְּחֶזְקָת שֶׁיֵּשׁ לָהּ מְזוּזָה, לֹא הָוֵי מִקָּח טָעוּת (בֵּית יוֹסֵף בְּשֵׁם הָרַב רַבֵּנוּ הַמָּנוֹחַ)\u0006. וּכְשֶׁיֵּצֵא, לֹא יִטְּלֶנָּה בְּיָדוֹ. \u0005וְאִם הִקְפִּיד עַל מְעוֹתֶיהָ, הַשֵּׁנִי צָרִיךְ לְשַׁלֵּם לוֹ (בֵּית יוֹסֵף בְּשֵׁם הָרַב מָנוֹחַ)\u0006. וְאִם שָׂכַר הַבַּיִת מֵעוֹבֵד כּוֹכָבִים, אוֹ שֶׁשְּׂכָרוֹ לְעוֹבֵד כּוֹכָבִים, נוֹטְלָהּ וְיוֹצֵא. \u0005הַגָּה: וְעוֹבֵד כּוֹכָבִים שֶׁבִּקֵּשׁ שֶׁיִּתְּנוּ לוֹ מְזוּזָה, וְרוֹצֶה לְקָבְעָהּ בְּפִתְחוֹ, אָסוּר לִתְּנָהּ לוֹ (כָּךְ הֵשִׁיב מהרי\"ל)\u0006. וְנִרְאֶה לִי דְּמִכָּל מָקוֹם בְּמָקוֹם דְּאִכָּא לְמֵיחַשׁ מִשּׁוּם אֵיבָה, וְשֶׁיֵּרַע מִשּׁוּם זֶה לְיִשְׂרָאֵל, שָׁרֵי כַּךְ נִרְאֶה לִי.\nהַכֹּל \u0010c0\u0011 חַיָּבִים בִּמְזוּזָה, אֲפִלּוּ נָשִׁים וַעֲבָדִים, וּמְחַנְּכִים אֶת הַקְּטַנִּים לַעֲשׂוֹת מְזוּזָה לְפִתְחֵיהֶם.",[],["\u0003חייבים. \u0004 דהוה ליה מצות עשה שאין הזמן גרמא ועוד דכתיב למען ירבו ימיכם והנהו נמי בעי חיי:"]],["\u0003הלכות שלוח הקן\u0004\nשִׁלּוּחַ הַקֵּן אֵינוֹ נוֹהֵג אֶלָּא בְּעוֹף טָהוֹר, אֲפִלּוּ אִם הָאֵם טְרֵפָה. וַאֲפִלּוּ אֵין שָׁם אֶלָּא אֶפְרוֹחַ אֶחָד אוֹ בֵּיצָה אַחַת, חַיָּב לְשַׁלֵּחַ.\nקֵן \u0010c0\u0011 הַמְזֻמָּן אֶצְלוֹ, כְּגוֹן יוֹנִים שֶׁדַּרְכָּן לִגָּדֵל עִם בְּנֵי אָדָם בַּבָּתִּים, וְאַוָּזִים וְתַרְנְגוֹלִים שֶׁקִּנְּנוּ בְּבַיִת, פָּטוּר. אֲבָל יוֹנֵי שׁוֹבָךְ וַעֲלִיָּה, וְצִפֳּרִים שֶׁקִּנְּנוּ בַּטְּפִיחִים \u0005(פֵּרוּשׁ כְּלִי חֶרֶס הַבָּנוּי בַּכְּתָלִים אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ)\u0006 וּבַבּוֹרוֹת, וְאַוָּזִים וְתַרְנְגוֹלִים שֶׁקִּנְּנוּ \u0010c1\u0011 בְּפַרְדֵּס, חַיָּב. וְהוּא שֶׁלֹּא \u0010c2\u0011 הֻגְבְּהָה הָאֵם מֵעַל הַבֵּיצִים כְּלָל, מִשֶּׁהֵטִילָם. אֲבָל אִם \u0010c3\u0011 הֻגְבְּהָה הָאֵם מֵעֲלֵיהֶם, אִם הַמְּקוֹמוֹת הַלָּלוּ שֶׁלּוֹ, זָכְתָה לוֹ חֲצֵרוֹ וַהֲוָה לֵיהּ מְזֻמָּן, וּפָטוּר.\nוּבְכָל מָקוֹם שֶׁיִּמְצָאֶנּוּ, בֵּין בְּאִילָן בֵּין בָּאָרֶץ, אוֹ בְּבוֹרוֹת שִׁיחִין וּמְעָרוֹת, אוֹ בַּיָּם אוֹ בְּרֹאשׁוֹ שֶׁל אָדָם, אוֹ בְּרֹאשׁ שְׁאָר בַּעֲלֵי חַיִּים, בֵּין בִּרְשׁוּת הָרַבִּים בֵּין בִּרְשׁוּת הַיָּחִיד, חַיָּב לְשַׁלֵּחַ.\nצָרִיךְ לְשַׁלֵּחַ הָאֵם עַד שֶׁתֵּצֵא מִתַּחַת יָדוֹ, וְאַחַר כָּךְ יִקַּח אֶת הַבָּנִים. וְאִם רוֹצֶה לַחְתֹּךְ כְּנָפֶיהָ קֹדֶם שֶׁיְּשַׁלְּחֶנָּה, כְּדֵי שֶׁלֹּא תּוּכַל לִפְרֹחַ וְיִקָּחֶנָּה, אֵינוֹ רַשַּׁאי, אֶלָּא יְשַׁלְּחֶנָּה מִיָּד עִם כְּנָפֶיהָ כְּדֵי שֶׁתּוּכַל לִפְרֹחַ, וּלְאַחַר שֶׁתֵּצֵא מִיָּדוֹ יִקָּחֶנָּה, אִם יִרְצֶה. וְאִם חֲתָכָן, יַשְׁהֶנָּה עַד שֶׁיִּגְדְּלוּ כְּנָפֶיהָ, וִישַׁלְּחֶנָּה.\nאִם רוֹצֶה לִקַּח הָאֵם וּלְשַׁלֵּחַ הַבָּנִים, אֵינוֹ רַשַּׁאי. שִׁלְּחָהּ \u0010c4\u0011 וְחָזְרָה, שִׁלְּחָהּ וְחָזְרָה, אֲפִלּוּ כַּמָּה פְּעָמִים, חַיָּב לַחֲזֹר וּלְשַׁלְּחָהּ. אֲבָל אִם שִׁלְּחָהּ וְנָטַל הַבָּנִים וְהֶחֱזִירָן לַקֵּן וְחָזְרָה הָאֵם עֲלֵיהֶם, פָּטוּר מִלְּשַׁלֵּחַ.\nאִם נָטַל הָאֵם מֵעַל הַבָּנִים וְלֹא שִׁלְּחָהּ, יְשַׁלְּחֶנָּה \u0010c5\u0011 וּפָטוּר.\nהָיוּ הַבֵּיצִים מוּזָרוֹת, אוֹ הָאֶפְרוֹחִים מַפְרִיחִים, אוֹ שֶׁהֵם טְרֵפָה, אוֹ שֶׁזָּכָר רוֹבֵץ עַל הַקֵּן, אוֹ שֶׁעוֹף טָמֵא רוֹבֵץ עַל בֵּיצֵי עוֹף טָהוֹר, אוֹ עוֹף טָהוֹר רוֹבֵץ עַל בֵּיצֵי עוֹף טָמֵא, פָּטוּר מִלְּשַׁלֵּחַ \u0005(ל' רַמְבַּ\"ם פ' י\"ג מהל' שְׁחִיטָה דִּין י')\u0006.\nהָיְתָה רוֹבֶצֶת עַל בֵּיצִים שֶׁאֵינָם מִינָהּ, וְהֵם \u0010c6\u0011 טְהוֹרִים, הֲרֵי זֶה מְשַׁלֵּחַ. וְאִם לֹא שִׁלַּח, אֵינוֹ לוֹקֶה \u0005(שָׁם דִּין י\"א)\u0006.\nהָיְתָה מַטְלִית אוֹ כַּנְפֵי נוֹצָה מֵעוֹף אַחֵר אוֹ בֵּיצִים מוּזָרוֹת מַפְסִיקִין בֵּינָהּ לַקֵּן, אוֹ שֶׁהָיוּ שְׁנֵי \u0010c7\u0011 סִדְרֵי בֵּיצִים זֶה עַל זֶה וּכְנָפֶיהָ נוֹגְעוֹת בַּסֵדֶר הָעֶלְיוֹן, אוֹ שֶׁהָיְתָה אֵם עַל גַּבֵּי אֵם, אוֹ שֶׁהָיָה הַזָּכָר עַל הַקֵּן וְהָאֵם עַל הַזָּכָר, הֲרֵי זֶה מְשַׁלֵּחַ וְאִם לֹא שִׁלַּח אֵינוֹ לוֹקֶה \u0005(שָׁם דִּין י\"ד)\u0006. \u0010c8\u0011\nשָׁחַט מִקְצָת סִימָנֵי הָאֶפְרוֹחִים בְּתוֹךְ הַקֵּן קֹדֶם שֶׁיִּקָּחֶנָּה, הֲרֵי זֶה מְשַׁלֵּחַ, וְאִם לֹא שִׁלַּח אֵינוֹ לוֹקֶה \u0005(שָׁם דִּין י\"ב)\u0006.\nהָיְתָה מְעוֹפֶפֶת עַל הַקֵּן, אִם כְּנָפֶיהָ נוֹגְעוֹת בַּקֵּן חַיָּב לְשַׁלֵּחַ, וְאִם לָאו, פָּטוּר אַף עַל פִּי שֶׁנּוֹגְעוֹת מִן הַצַּד.\nהָיְתָה יוֹשֶׁבֶת בֵּין הַבֵּיצִים אוֹ בֵּין הָאֶפְרוֹחִים, אֲפִלּוּ נוֹגַעַת בָּהֶן, \u0010c9\u0011 פָּטוּר.\nהָיְתָה יוֹשֶׁבֶת עַל שְׁנֵי עַנְפֵי הָאִילָן וְהַקֵּן תַּחְתֶּיהָ, רוֹאִים כָּל שֶׁאִלּוּ תִּשָּׁמֵט וְנוֹפֶלֶת עֲלֵיהֶם, חַיָּב, וְאִם לָאו, פָּטוּר.",[],["\u0003המזומן. \u0004 דכתיב כי יקרא פרט למזומן:","\u0003בפרדס. \u0004 שאינו משתמר דכיון שמרדו אין קינויו בידך אבל אם משתמר פטור. כן משמע מפירש\"י. ש\"ך:","\u0003הוגבהה. \u0004 דהשתא ליכא למימר שזכתה לו חצירו וה\"ל מזומן דכיון דאסור לזכות בביצים כל זמן שהאם רובצת עליהם א\"כ גם חצירו לא קנה ליה דכיון דאיהו לא מצי זכי לא זכי ליה חצירו. ש\"ך:","\u0003האם. \u0004 כתב הש\"ך דמיירי שהוגבהה עד כדי שתצא מתחת ידו כדלקמן ס\"ד דאל\"כ כיון דאיהו לא זכי בה חצירו נמי לא זכי ליה א\"נ דהכא מיירי שהוגבהה מעצמה והלכך כל שאינה נוגעת ע\"ג הקן סגי דומיא דהיתה מעופפת דסי\"א עכ\"ל:","\u0003וחזרה. \u0004 כתב הט\"ז קשה כיון דקי\"ל דגם ברשותו חייב בשלוח הקן למה כ' כאן סתם דחייב כיון דקודם חזרה היה יכול לזכות בבנים וממילא זכה לו חצירו שלא מדעתו וה\"ל מזומן וצ\"ל דכאן מיירי שלא ברשותו וצ\"ע דלא פירשו זה בהדיא עכ\"ל וכ\"כ הש\"ך דאם היה בחצירו וחזרה פטור מלשלח ומזה הטעם אם נטל הבנים והחזירן לקן פטור דכיון דכבר זכה בהן מזומן קרינן בהו:","\u0003ופטור. \u0004 ממלקות \u0005(כיון שבידו לשלוח עוד אינו חייב מלקות)\u0006 אבל אסור לעשות כן לכתחלה ואם מתה או ששחטה קודם ששלחה חייב מלקות כיון שאין בידו לקיים מצות שלוח כ\"כ הרמב\"ן והר\"ן ואם בא אחר וחטף האם מידו או שברחה מתחת ידו שלא מדעתו לוקה שנאמר שלח תשלח עד שישלח מעצמו והרי לא קיים עשה שבה. שם ברמב\"ם:","\u0003טהורים. \u0004 כתב הש\"ך מדלא חילק משמע אפי' בקורא נקבה אינה לוקה והוא דעת הרמב\"ם אבל דעת הרא\"ש ושאר גדולי הפוסקים דבקורא נקבה חייב אע\"פ שרובצת אביצים שאינן מינה כיון ששניהם טהורים ופירוש קורא כ' רבינו ירוחם שא\"א להיות עוף הנקרא קוקליי\"ו כמו שפי' קצת המפרשים קורא דגר ולא ילד כי הוא עוף טמא ופשוט לכ\"ע דפטור:","\u0003סדרי. \u0004 כתב הלבוש דנתכוין ליטול התחתונים לבד והיינו כפירש\"י ודלא כחידושי רשב\"א שפי' דהביצים עליונים הם מעוף טמא דפשט דברי הש\"ס עיקר כרש\"י עכ\"ל הש\"ך וע\"ש:","\u0003שחט. \u0004 כ' הש\"ך ואע\"ג דלדידן לא שייך דין זה דבכל שהוא ששהה מטרפינן נראה דמיירי דבשעה ששוחט נוטל האם כגון דשחט בחד ידא ונטל בחד ידא או מצוה לאחר ליקח האם א\"נ אפילו בשהה כל שהוא כיון דהרבה פוסקים מתירים כדלעיל סי' כ\"ג אלא דאנן מחמרינן והיינו לענין אכילה אבל לא להקל לענין שלוח הקן עכ\"ל:","\u0003פטור. \u0004 דעל הביצים והאפרוחים כתיב ואין זה על. עכ\"ל הש\"ך:"]],["\u0003הלכות חדש\u0004\nאָסוּר לֶאֱכֹל חָדָשׁ מִתְּבוּאַת \u0010c0\u0011 חֲמֵשֶׁת הַמִּינִים עַד שֶׁיִּקְרַב הָעֹמֶר שֶׁהוּא בְּט\"ז בְּנִיסָן, שֶׁנֶּאֱמַר: וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ עַד עֶצֶם הַיּוֹם הַזֶּה \u0005(וַיִּקְרָא כג, יד)\u0006 וְהָאִדָּנָא, דְּלֵיכָּא עֹמֶר, אָסוּר כָּל יוֹם ט\"ז. וּבְחוּץ לָאָרֶץ, שֶׁעוֹשִׂין ב' יָמִים, אָסוּר כָּל יוֹם י\"ז עַד תְּחִלַּת לֵיל י\"ח.\nאִסוּר הֶחָדָשׁ נוֹהֵג בֵּין בְּאֶרֶץ בֵּין בְּחוּץ לָאָרֶץ, בֵּין בְּשֶׁל יִשְׂרָאֵל בֵּין בְּשֶׁל \u0010c1\u0011 עוֹבֵד כּוֹכָבִים.\nתְּבוּאָה שֶׁלֹּא הִשְׁרִישָׁה קֹדֶם לְט\"ז בְּנִיסָן, אֲסוּרָה עַד שֶׁיָּבֹא \u0010c2\u0011 הָעֹמֶר הַבָּא. \u0005הַגָּה: וּמִכָּל מָקוֹם כָּל סְתָם תְּבוּאָה שָׁרֵי לְאַחַר הַפֶּסַח, מִכֹּחַ סְפֵק סְפֵיקָא, \u0010c3\u0011 סָפֵק הִיא מִשָּׁנָה שֶׁעָבְרָה. וְאִם תִּמְצָא לוֹמַר מִשָּׁנָה זוֹ, מִכָּל מָקוֹם דִּלְמָא נִשְׁרְשָׁה קֹדֶם הָעֹמֶר (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וּבְמִינֵי תְּבוּאָה שֶׁזּוֹרְעִים וַדַּאי לְאַחַר פֶּסַח, כְּגוֹן בְּמִקְצַת מְדִינוֹת שֶׁזּוֹרְעִין שִׁבּוֹלֶת שׁוּעָל וּשְׂעוֹרִים לְאַחַר פֶּסַח, אָז יֵשׁ לוֹ לְהַחְמִיר אַחַר הַקָּצִיר, אִם לֹא שֶׁאֵין דַּלְתוֹת הַמְּדִינוֹת נְעוּלוֹת, וְרֹב הַתְּבוּאָה בָּאָה מִמָּקוֹם אַחֵר שֶׁזּוֹרְעִין קֹדֶם הַפֶּסַח \u0005(הַגָּהוֹת מַיְמוֹנִי פי\"א מהמ\"א וְתוס' ספ\"ק דְּקִדּוּשִׁין)\u0006. וְכֵן בִּזְמַן שֶׁיְמוֹת הַחֹרֶף נִמְשָׁכִים לְאַחַר פֶּסַח, וּבְכָל הַגָּלִיל הַהוּא זוֹרְעִים לְאַחַר פֶּסַח דְּבָרִים הַנִּזְכָּרִים, יֵשׁ לְהַחְמִיר וְלָחוּשׁ מִן הַסְּתָם. אֲבָל אֵין לְהוֹרוֹת לַאֲחֵרִים בְּמָקוֹם שֶׁרֹב שְׁתִיָּתָן וַאֲכִילָתָן מִמִּינִים אֵלּוּ, כִּי \u0010c4\u0011 מוּטָב שֶׁיִּהְיוּ שׁוֹגְגִין וְאַל יִהְיוּ מְזִידִין \u0005(כֵּן מַשְׁמָע בַּטּוּר בְּשֵׁם הָרֹא\"שׁ ות\"ה סִימָן קנ\"ח)\u0006.\nתְּבוּאָה שֶׁנִּזְרְעָה אַחַר הָעֹמֶר וּקְצָרָהּ וּזְרָעָהּ, וּבִשְׁעַת הָעֹמֶר הָיְתָה תַּחַת הַקַּרְקַע וְלֹא הִתְחִילָה עֲדַיִן לְשָׁרֵשׁ, אָסוּר.\nשִׁבֹּלֶת שֶׁהֵבִיאָה שְׁלִישׁ קֹדֶם הָעֹמֶר, וַעֲקָרָהּ אַחַר הָעֹמֶר, וְחָזַר וּשְׁתָלָהּ, וְהוֹסִיפָהּ, הַתּוֹסֶפֶת אוֹסֵר הָעִקָּר שֶׁהֻתַּר.",[],["\u0003חמשת. \u0004 שהם חטים וכוסמין ושעורים ושבולת שועל והשיפון וכתב הט\"ז נ\"ל דעיסה שנילושה בשמרים של חדש אסור כל העיסה ולא מהני כאן ביטול בס' מתרי טעמי א' משום דכל מידי דלטעמא עבידא אפילו באלף לא בטיל שנית דה\"ל דבר שיש לו מתירין. כתבתי זאת לפי שראיתי מקצת נזהרין מחדש ובדבר הזה לא נזהרין והוא טעות בידם עכ\"ל:","\u0003עובד\u0004 \u0003כוכבים. \u0004 והב\"ח רוצה להוכיח מש\"ס ר\"ה דבשל עובד כוכבים אינו נוהג חדש והשיג עליו הט\"ז ודחה דבריו ע\"ש:","\u0003העומר. \u0004 כתב הש\"ך אבל אם נשרשה קודם העומר אע\"פ שלא נקצרה עד אחר העומר מתירה העומר ונשרש קודם העומר היינו ג' ימים:","\u0003ספק. \u0004 ואע\"ג דחדש הוי דבר שיש לו מתירין ודבר שיש לו מתירין אפילו בס\"ס אסור י\"ל כמ\"ש בסימן ק\"י ס\"ח בהג\"ה בשם תשו' הרא\"ש דדוקא בתערובות אמרינן דס\"ס לא מהני אבל בנדון זה דשמא אין כאן חדש כלל כה\"ג לא אסרי' ס\"ס בדשיל\"מ וע\"ש בש\"ך סימן ק\"י ס\"ק נ\"ו:","\u0003מוטב. \u0004 והט\"ז כתב שאין זה כדאי מלהציל מאיסור חדש אלא דנ\"ל עיקר הטעם דבמדינות אלו שהוא שעת הדחק דחייו של אדם תלוי בשתיית שכר שעורים ושבולת שועל כדאי הוא הת\"ק דמתני' דס\"ל חדש אינו נוהג בח\"ל לסמוך עליו בשעת הדחק כיון דלא איפסק הלכה בפי' כר\"א עכ\"ל והש\"ך כתב דאם רוב שתיית המדינה יין וא\"צ לשעורים ושבולת שועל רק לפעמים למאכל וליתא דוחקא דצבורא היכא דליכא אלא חד ספיקא שמא של אשתקד שמא של שנה זו מצוה למחות בהמון עם ולהורות להם לאיסור. ובספר לחם משנה האריך למצוא היתר על שכר שעורים הנעשה מחדש מטעם שהמשקה היוצא מהן מותר וצריך להתיישב בדבר כי מתשובת הרא\"ש ומת\"ה ושאר פוסקים משמע שאסור ובנה\"כ האריך גם כן להוכיח בראיות ברורות מהש\"ס דחדש בח\"ל דאורייתא דלא כהט\"ז ע\"ש:"]],["\u0003הלכות ערלה\u0004\nהַנּוֹטֵעַ עֵץ מַאֲכָל, מוֹנֶה לוֹ ג' שָׁנִים מֵעֵת נְטִיעָתוֹ, וְכָל הַפֵּרוֹת שֶׁיִּהְיוּ בּוֹ בְּתוֹךְ ג' שָׁנִים אֲסוּרִין בַּהֲנָאָה לְעוֹלָם, בֵּין עִקַּר הַפְּרִי בֵּין הַגַּרְעִינִים בֵּין הַקְּלִפּוֹת, כְּגוֹן קְלִפֵּי אֱגוֹזִים וְרִמּוֹנִים, וְהָנֵּץ שֶׁלָּהֶם, וְהַזַּגִּין וְהַגַּרְעִינִין שֶׁל עֲנָבִים, וְהַתֶּמֶד הֶעָשׂוּי מֵהֶם, וְהַפַּגִים וְהַתְּמָרִים שֶׁאֵינָם מִתְבַּשְּׁלִים, וְהָעֲנָבִים שֶׁלָּקוּ וְאֵין נִגְמָרִים בְּבִשּׁוּלָן, כֻּלָּם חַיָּבִים בְּעָרְלָה וּפְטוּרִים \u0010c0\u0011 מֵרְבָעי. וְיֵשׁ מִי \u0010c1\u0011 שֶׁאוֹסֵר תְּמָרִים שֶׁאֵינָם מִתְבַּשְּׁלִים אַף בִּרְבָעי.\nאֲבָל הֶעָלִים וְהַלּוּלָבִים וּמֵי גְּפָנִים, דְּהַיְנוּ כְּשֶׁחוֹתְכִין הַגֶּפֶן נוֹטֵף מִמֶּנּוּ כְּמוֹ מַיִם, \u0010c2\u0011 מֻתָּרִים מִשּׁוּם עָרְלָה.\nהָאֶבְיוֹנוֹת וְהַתְּמָרוֹת \u0005(וְהַקַפְרִיסִין)\u0006 שֶׁל צָלָף חַיָּבִים בְּעָרְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּאֶרֶץ יִשְׂרָאֵל, אֲבָל בְּחוּצָה \u0010c3\u0011 לָאָרֶץ, הָאֶבְיוֹנוֹת חַיָּבִים וּתְמָרוֹת וְקַפְרִיסִין פְּטוּרִים.\nג' שָׁנִים הַלָּלוּ אֵינָם נִמְנִים מִיּוֹם לְיוֹם, אֶלָּא הוֹלְכִים בָּהֶם אַחַר שְׁנוֹת הָעוֹלָם שֶׁהוּא מַתְחִיל מִתִּשְׁרֵי, וְאִם נִתְעַבְּרָה נִתְעַבְּרָה לְעָרְלָה וְלִרְבָעי. וּפְעָמִים שֶׁאֵינוֹ אֶלָּא שְׁתֵּי שָׁנִים וּמ\"ד יוֹם, וּפְעָמִים שֶׁהֵם יְתֵרִים עַל ג' שָׁנִים. כֵּיצַד, נָטַע מִקֹּדֶם ט\"ז בְּאָב, שֶׁנִּשְׁאַר \u0010c4\u0011 עֲדַיִן מ\"ד יוֹם עַד רֹאשׁ חֹדֶשׁ תִּשְׁרֵי, כֵּיוָן שֶׁהִגִּיעַ רֹאשׁ חֹדֶשׁ תִּשְׁרֵי עָלְתָה לָהּ שָׁנָה וּמוֹנֶה עוֹד שְׁתֵּי שָׁנִים. וְאִם נָטַע בְּיוֹם ט\"ז, וּמִיּוֹם ט\"ז וָאֵילָךְ, מוֹנֶה מֵרֹאשׁ חֹדֶשׁ תִּשְׁרֵי הַבָּא ג' שָׁנִים שְׁלֵמִים. וּלְאַחַר רֹאשׁ חֹדֶשׁ תִּשְׁרֵי שֶׁל שָׁנָה רְבִיעִית, כָּל \u0010c5\u0011 הַפֵּרוֹת שֶׁיַּחְנְטוּ בּוֹ קֹדֶם ט\"וּ בִּשְׁבָט יֵשׁ לָהֶם גַּם כֵּן דִּין עָרְלָה, אַף עַל פִּי שֶׁנִּגְמָרִים אַחַר כָּךְ. וְהַנֶּחְנָטִים בּוֹ מִטּ\"וּ בִּשְׁבָט שֶׁל שָׁנָה רְבִיעִית עַד ט\"וּ בִּשְׁבָט שֶׁל שָׁנָה חֲמִישִׁית, נִקְרָאִים רְבָעי. וּלְאַחַר ט\"וּ בִּשְׁבָט שֶׁל שָׁנָה חֲמִישִׁית הֵם חֻלִּין גְּמוּרִים.\nהָא דְּאָמְרִינַן שֶׁלְּאַחַר רֹאשׁ חֹדֶשׁ תִּשְׁרֵי שֶׁל שָׁנָה רְבִיעִית כָּל הַפֵּרוֹת שֶׁחָנְטוּ קֹדֶם ט\"וּ בִּשְׁבָט יֵשׁ לָהֶם גַּם כֵּן דִּין עָרְלָה, אַף עַל פִּי שֶׁנִּגְמָרִים אַחַר כָּךְ, דַּוְקָא בִּנְטִיעָה שֶׁהֵקַלְנוּ עָלֶיהָ בִּתְחִלָּתָהּ, שֶׁכֵּיוָן שֶׁעָבְרוּ עָלֶיהָ מ\"ד יוֹם עָלְתָה לָהּ שָׁנָה, לְפִיכָךְ הֶחְמַרְנוּ עָלֶיהָ בְּסוֹפָהּ, הָא \u0010c6\u0011 לָאו הָכִי, לֹא. וְיֵשׁ אוֹמְרִים דְּלֹא שְׁנָא.\nפֵּרוֹת רְבָעי יֵשׁ לָהֶם דִּין מַעֲשֵׂר שֵׁנִי לְכָל דָּבָר, וּבִזְמַן הַבַּיִת הָיוּ צְרִיכִין לְהַעֲלוֹתָן לִירוּשָׁלַיִם לְאָכְלָם שָׁם, אוֹ לִפְדּוֹתָם וּלְהַעֲלוֹת הַפִּדְיוֹן שָׁם, וְהֵם מֻתָּרִים מִיָּד אַחַר הַפִּדְיוֹן. וְהָאִדָּנָא, שֶׁאֵין יְכוֹלִין לְהַעֲלוֹתָם לִירוּשָׁלַיִם, \u0010c7\u0011 פּוֹדִים אוֹתָם אַחַר שֶׁיִּגָּמְרוּ וְיִתָּלְשׁוּ. וְיָכוֹל לִפְדּוֹת אֶת כֻּלָּם בִּשְׁוֵה פְּרוּטָה, אֲפִלּוּ הֵם רַבִּים, וְיַשְׁלִיךְ הַפְּרוּטָה לַיָּם הַגָּדוֹל אוֹ יִשְׁחֲקֶנָּה וִיפַזְּרֶנָּה לָרוּחַ, אוֹ יַשְׁלִיכֶנָּה בַּנָּהָר אַחַר שְׁחִיקָה, וִיבָרֵךְ בִּשְׁעַת פִּדְיוֹן: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן רְבָעי, אוֹ יִפְדֶּה בְּפֵרוֹת שֶׁיִּשְׁווּ שְׁוֵה פְּרוּטָה, שֶׁהוּא אֶחָד מִל\"ב בְּמָעָה כֶּסֶף שֶׁהִיא אשפיר\"ו אוטמאני\"ם שֶׁשּׁוֹקֵל ט\"ז גַּרְעִינֵי שְׂעוֹרָה שֶׁהוּא רְבִיעַ דְּרַ\"הַם \u0005(לְשׁוֹן עַצְמוֹ)\u0006. \u0005הַגָּה: וּמַטְבֵּעַ הָרְגִילָה בִּמְדִינוֹת אֵלּוּ, הַחֲצִי וי\"נר, הוּא יוֹתֵר מִשְּׁוֵה פְּרוּטָה פּוֹדִין עָלָיו\u0006 \u0005(תה\"ד סי' קצ\"ב)\u0006. פֵּרוֹת רְבָעי פְּטוּרִין מִלֶּקֶט וְשִׁכְחָה וּפֶרֶט וְעוֹלְלוֹת.\nדִּין נֶטַע רְבָעי נוֹהֵג אַף בְּחוּצָה לָאָרֶץ. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵינוֹ נוֹהֵג אֶלָּא בָּאָרֶץ, אֲבָל בְּחוּצָה לָאָרֶץ פֵּרוֹת הַבָּאִים אַחַר שֶׁעָבְרוּ שְׁנֵי עָרְלָה מֻתָּרִים בְּלֹא פִּדְיוֹן \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ נוֹהֵג בְּחוּצָה לָאָרֶץ רַק \u0010c8\u0011 בְּכֶרֶם, וְלֹא בִּשְׁאָר אִילָנוֹת (טוּר בְּשֵׁם הַגְּאוֹנִים וְרַמְבַּ\"ן וְרֹא\"שׁ וְעוֹד פּוֹסְקִים)\u0006.\nעָרְלָה נוֹהֶגֶת בְּכָל מָקוֹם וּבְכָל זְמַן, בֵּין בְּשֶׁל עוֹבֵד כּוֹכָבִים בֵּין בְּשֶׁל יִשְׂרָאֵל, אֶלָּא שֶׁבְּאֶרֶץ יִשְׂרָאֵל הִיא מִן הַתּוֹרָה, וּבְחוּצָה לָאָרֶץ הֲלָכָה לְמֹשֶׁה מִסִינַי. \u0005הַגָּה: וְאָסוּר לִלְקֹט לְנָכְרִי פֵּרוֹת מֵאִילָן שֶׁלּוֹ שֶׁהוּא עָרְלָה, מִשּׁוּם שֶׁנֶּהֱנֶה בַּמֶּה שֶּׁמַּחֲזִיק לוֹ הַנָּכְרִי טוֹבָה עַל זֶה (כָּל בּוֹ וב\"ה בְּשֵׁם א\"ח)\u0006.\nסְפֵק עָרְלָה בְּאֶרֶץ יִשְׂרָאֵל, אָסוּר. וּבְחוּצָה לָאָרֶץ, \u0010c9\u0011 מֻתָּר. כֵּיצַד, כֶּרֶם שֶׁיֵּשׁ בּוֹ נְטִיעוֹת שֶׁל \u0010c10\u0011 עָרְלָה, וַעֲנָבִים נִמְכָּרִים חוּצָה לוֹ, בְּאֶרֶץ יִשְׂרָאֵל, אָסוּר; וּבְסוּרְיָא, מֻתָּר, וְהוּא שֶׁלֹּא יָדַע שֶׁהוּבְאוּ מֵאוֹתוֹ הַכֶּרֶם; וּבְחוּץ לָאָרֶץ, מֻתָּר, אֲפִלּוּ יוֹדֵעַ שֶׁהוּבְאוּ מֵאוֹתוֹ הַכֶּרֶם, רַק שֶׁלֹּא יֵרָאֶה שֶׁנִּבְצְרוּ מִנְּטִיעוֹת שֶׁל עָרְלָה. \u0010c11\u0011 \u0005וְכָל שֶׁכֵּן שֶׁכֶּרֶם שֶׁהוּא סָפֵק עָרְלָה שֶׁהוּא מֻתָּר (כֵּן נִרְאֶה מֵהַטּוּר וְהָרֹא\"שׁ וּמָרְדְּכַי פֶּרֶק קַמָּא דְּקִדּוּשִׁין)\u0006.\nכֶּרֶם שֶׁהוּא סְפֵק עָרְלָה, בְּאֶרֶץ יִשְׂרָאֵל, אָסוּר; וּבְסוּרְיָא, מֻתָּר, וְאֵין צָרִיךְ לוֹמַר בְּחוּצָה לָאָרֶץ.\nחָבִית שֶׁל יַיִן הַטְּמוּנָה בְּכֶרֶם שֶׁל עָרְלָה, \u0010c12\u0011 מֻתָּר, שֶׁאֵין הַגַּנָּב גּוֹנֵב מִכֶּרֶם זֶה וְטוֹמֵן בְּתוֹכוֹ. אֲבָל עֲנָבִים שֶׁנִּמְצְאוּ טְמוּנִים בּוֹ, אֲסוּרִים, שֶׁקָּרוֹב הַדָּבָר שֶׁגְּנָבָם מִמֶּנּוּ וּטְמָנָם בְּתוֹכוֹ.\nאָסוּר \u0010c13\u0011 לִטַּע פְּרִי שֶׁל עָרְלָה; וְאִם נְטָעוֹ, הַפֵּרוֹת שֶׁיּוֹצְאִים מִמֶּנּוּ, מֻתָּרִים, דְּזֶה וְזֶה \u0010c14\u0011 גּוֹרֵם, מֻתָּר. וּמֻתָּר לִטַּע יִחוּר \u0005(פי' עָנָף מִן הָאִילָן)\u0006 שֶׁל עָרְלָה, שֶׁאֵין עָרְלָה אֶלָּא בִּפְרִי.\nנָכְרִי וְיִשְׂרָאֵל שֶׁהָיוּ שֻׁתָּפִין בִּנְטִיעָה, אִם לֹא הִתְנוּ מִתְּחִלָּה, אָסוּר. וְאִם \u0010c15\u0011 הִתְנוּ מִתְּחִלַּת הַשֻּׁתָּפוּת שֶׁיְּהֵא הָעוֹבֵד כּוֹכָבִים אוֹכֵל שְׁנֵי עָרְלָה, וְיִשְׂרָאֵל אוֹכֵל ג' שָׁנִים מִשְּׁנֵי הֶתֵּר כְּנֶגֶד שְׁנֵי עָרְלָה, הֲרֵי זֶה מֻתָּר, וּבִלְבַד שֶׁלֹּא יָבוֹאוּ לְחֶשְׁבּוֹן. כֵּיצַד, כְּגוֹן שֶׁיַּחֲשֹׁב כַּמָּה פֵּרוֹת אָכַל הָעוֹבֵד כּוֹכָבִים בִּשְׁנֵי עָרְלָה עַד שֶׁיֹּאכַל יִשְׂרָאֵל כְּנֶגֶד אוֹתָן הַפֵּרוֹת, שֶׁזֶּה אָסוּר מִפְּנֵי שֶׁהוּא כְּמַחֲלִיף פֵּרוֹת עָרְלָה. \u0005הַגָּה: וְיֵשׁ \u0010c16\u0011 מַתִּירִין אֲפִלּוּ לֹא הִתְנוּ מִתְּחִלָּה, רַק שֶׁהַיִּשְׂרָאֵל אוֹמֵר לָעוֹבֵד כּוֹכָבִים: טֹל אַתָּה שְׁנֵי הָעָרְלָה וַאֲנִי אֶטֹּל שְׁנֵי הֶתֵּר כְּנֶגְדָּן (טוּר \u0010c17\u0011 וְהָרֹא\"שׁ)\u0006.\nמֻתָּר לוֹמַר לְעוֹבֵד כּוֹכָבִים בִּשְׁנֵי עָרְלָה: עֲבֹד כַּרְמִי וְתִטֹּל פֵּירוֹתֶיהָ, וְתֵן לִי כַּרְמְךָ שֶׁעָבְרוּ עָלֶיהָ שְׁנֵי עָרְלָה וְאֶעֶבְדֶנָּה וְאֶטֹּל פֵּירוֹתֶיהָ.\nמֻתָּר לִמְכֹּר לְעוֹבֵד כּוֹכָבִים \u0010c18\u0011 פֵּרוֹת שְׁנֵי עָרְלָה לְשָׁלֹשׁ שָׁנִים, מֵאַחַר שֶׁלֹּא בָּאוּ לָעוֹלָם.\nאֶחָד הַנּוֹטֵעַ גַּרְעִין אוֹ יִחוּר אוֹ שֶׁעָקַר כָּל הָאִילָן וְנָטַע בְּמָקוֹם אַחֵר, וְאֶחָד הַמַּרְכִּיב יִחוּר בְּאִילָן אַחֵר, וְאֶחָד הַמַּבְרִיךְ, דְּהַיְנוּ שֶׁעוֹשֶׂה גּוּמָא אֵצֶל הָאִילָן וּמַשְׁפִּיל אֶחָד מֵעַנְפֵי הָאִילָן, וּמַטְמִין אֶמְצָעִיתוֹ בַּגּוּמָא, וְרֹאשׁוֹ יוֹצֵא מֵהַצַּד הָאַחֵר וְנַעֲשֶׂה אִילָן, כֻּלָּם חַיָּבִים בְּעָרְלָה. וְדַוְקָא שֶׁחֲתָכוֹ מִצַּד זֶה מֵעִקַּר הָאִילָן, אוֹ שֶׁאֵינוֹ יוֹנֵק מִמֶּנּוּ, אֲבָל כָּל זְמַן שֶׁהוּא \u0010c19\u0011 מְחֻבָּר וְיוֹנֵק מִמֶּנּוּ חָשׁוּב כָּאֶחָד מֵעֲנָפָיו, וּפָטוּר. וְאִם לְאַחַר שֶׁגָּדַל הֶעָנָף שֶׁהִבְרִיךְ הִבְרִיךְ מִמֶּנּוּ עוֹד עָנָף אַחֵר בָּאָרֶץ, וְעָשָׂה כֵן כַּמָּה פְּעָמִים זֶה אַחַר זֶה, כָּל זְמַן שֶׁהָרִאשׁוֹן מְחֻבָּר לְעִקַּר הָאִילָן כֻּלָּם פְּטוּרִים. הִפְסִיק הָרִאשׁוֹן מֵעִקַּר הָאִילָן, חַיָּבִים, וּמַתְחִילִים לִמְנוֹת לָהֶם מִשָּׁעָה שֶׁהִפְסִיק, וְהָעִקָּר פָּטוּר. וְאִם נֶעֱקַר הָעִקָּר מֵהַקַּרְקַע, חוֹזֵר לִהְיוֹת טָפֵל לֶעָנָף שֶׁהִבְרִיךְ, וּמוֹנִין בֵּין לָעִקָּר בֵּין לֶעָנָף מִשָּׁעָה שֶׁנֶּעֱקַר.\nאַף עַל פִּי שֶׁמִּנְהַג עוֹבְדֵי אֲדָמָה לְהַבְרִיךְ גְּפָנִים בְּכָל שָׁנָה, מֻתָּר לִשְׁתּוֹת יַיִן מִגַּפְנֵי הָעוֹבְדֵי כּוֹכָבִים, מִשּׁוּם דִּסְפֵק עָרְלָה מֻתָּר. וַאֲפִלּוּ בִּכְרָמִים שֶׁיִּשְׂרָאֵל עוֹבְדִים אוֹתָם וּמַבְרִיכִים אוֹתָם בְּכָל שָׁנָה, מֻתָּר, מִשּׁוּם דְּמַבְרִיךְ וּמַרְכִּיב אֵינוֹ חַיָּב בְּעָרְלָה אֶלָּא בָּאָרֶץ אֲבָל לֹא בְּחוּצָה לָאָרֶץ. וְיֵשׁ לִמְצֹא הֶתֵּר גַּם לִבְנֵי אֶרֶץ יִשְׂרָאֵל בְּיַיִן שֶׁל כַּרְמֵי הָעוֹבְדֵי כּוֹכָבִים, מִשּׁוּם דְּרֻבָּא דִּגְפָנִים לָאו עָרְלָה נִינְהוּ. וַאֲפִלּוּ בִּכְרָמִים שֶׁיָּדוּעַ וַדַּאי שֶׁיֵּשׁ בָּהֶם עָרְלָה, יֵשׁ לְהַתִּירָהּ מִשּׁוּם דְּקֹדֶם שֶׁיַּעַבְרוּ עָלֶיהָ שְׁנֵי עָרְלָה אֵינָם עוֹשִׂים פֵּרוֹת, וְאִם עוֹשִׂים, הֵם דַּקִּים וּקְלוּשִׁים שֶׁאֵינָם רְאוּיִים לַעֲשׂוֹת מֵהֶן יַיִן.\nאִילָן שֶׁנִּקְצַץ וְחָזַר וְגָדַל מֵהַשֹּׁרֶשׁ, אֵינוֹ חַיָּב אֶלָּא אִם כֵּן נִקְצַץ מֵעִם הָאָרֶץ, וּמוֹנִין לוֹ מִשְּׁעַת קְצִיצָה. אֲבָל אִם \u0010c20\u0011 נִשְׁאַר מִמֶּנּוּ כָּל שֶׁהוּא, פָּטוּר.\nאִילָן שֶׁעֲקָרוֹ רוּחַ אוֹ שְׁטָפוֹ נָהָר וְהוֹלִיכוֹ לְמָקוֹם אַחֵר, וּמֵהֶעָפָר שֶׁסְבִיב שָׁרָשָיו עִמּוֹ, וְהוֹסִיף עָלָיו שָׁם עָפָר וְנִשְׁרַשׁ שָׁם בָּאָרֶץ, אוֹמְדִים אוֹתוֹ אִם הָיָה יָכוֹל לִחְיוֹת בֶּעָפָר הָרִאשׁוֹן שֶׁבָּא עִמּוֹ בְּלֹא תּוֹסֶפֶת עָפָר אַחֵר, הֲרֵי זֶה כְּנָטוּעַ בִּמְקוֹמוֹ וּפָטוּר מֵהָעָרְלָה. וְאִם לָאו, חַיָּב.\nאִילָן שֶׁנֶּעֱקַר וְנִשְׁאַר מִשָּׁרָשָיו מְחֻבָּר, אֲפִלּוּ כָּעֳבִי הַמַּחַט שֶׁמּוֹתְחִין בּוֹ הַבֶּגֶד לְאַחַר אֲרִיגָה, בְּיָדוּעַ שֶׁיּוּכַל לִחְיוֹת בְּלֹא תּוֹסֶפֶת עָפָר, וּפָטוּר אֲפִלּוּ הוֹסִיף עָלָיו עָפָר הַרְבֵּה.\nיַלְדָּה שֶׁאֵינָהּ גְּבוֹהָה טֶפַח, חַיֶּבֶת בְּעָרְלָה לְעוֹלָם, מִשּׁוּם מַרְאִית הָעַיִן, שֶׁנִּרְאֶה כְּאִלּוּ הִיא בַּת שְׁנָתָהּ. בַּמֶּה דְבָרִים אֲמוּרִים, בִּנְטִיעָה אַחַת אוֹ אֲפִלּוּ שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצֵא זָנָב, אֲבָל אִם כָּל הַכֶּרֶם כָּךְ, שָׁרֵי, דְּאִית לֵהּ קָלָא.\nבְּרֵכָה שֶׁנִּפְסְקָה וְהִיא מְלֵאָה פֵּרוֹת, וְכֵן אִילָן זָקֵן שֶׁנֶּעֱקַר וּבוֹ פֵּרוֹת וּשְׁתָלוֹ בְּמָקוֹם אַחֵר, אוֹ שֶׁלָּקַח עָנָף מָלֵא פֵּרוֹת מֵאִילָן זָקֵן וְהִרְכִּיבוֹ בְּיַלְדָּה, אִם נִתּוֹסֵף בַּפְּרִי עַד שֶׁאֵין בַּפְּרִי הָרִאשׁוֹן שֶׁהוּא הֶתֵּר מָאתַיִם חֲלָקִים עַל הַתּוֹסֶפֶת, אָסוּר. וְאִם לָאו, מֻתָּר. אֲבָל אִם הִרְכִּיב עָנָף מָלֵא פֵּרוֹת שֶׁל עָרְלָה בְּתוֹךְ אִילָן זָקֵן, הַפֵּרוֹת שֶׁל הֶעָנָף אֲסוּרִים לְעוֹלָם, \u0010c21\u0011 אֲפִלּוּ גָּדְלוּ הַרְבֵּה.\nהַנּוֹטֵעַ אִילַן מַאֲכָל וְאֵין דַּעְתּוֹ לְצֹרֶךְ אֲכִילָה, אֶלָּא לִהְיוֹת גָּדֵר לְשָׂדֶה אוֹ בִּשְׁבִיל הָעֵצִים לְשָׂרְפָן אוֹ לְבִנְיָן, פָּטוּר. וְהוּא שֶׁיְּהֵא נִכָּר שֶׁאֵינוֹ לְצֹרֶךְ אֲכִילָה, כְּגוֹן אִם הוּא לִשְׂרֵפָה שֶׁנְּטָעָן רְצוּפִים וְאֵינוֹ מַרְחִיק בֵּין אִילָן לְאִילָן \u0010c22\u0011 כָּרָאוּי, וְאִם הוּא לְבִנְיָן שֶׁמְּשַׁפֶּה הָעֲנָפִים כְּדֵי שֶׁיִּתְעַבּוּ, וְאִם לְגָדֵר שֶׁהוּא בְּמָקוֹם שֶׁצָּרִיךְ לִגְדֹּר. וַאֲפִלּוּ אִם צִדּוֹ הָאֶחָד בֵּין פְּנִימִי בֵּין חִיצוֹן בֵּין תַּחְתּוֹן בֵּין \u0010c23\u0011 עֶלְיוֹן לְצֹרֶךְ אֶחָד מֵאֵלּוּ, וְצִדּוֹ הַשֵּׁנִי לֶאֱכֹל, אֶת שֶׁלְּצֹרֶךְ אֲכִילָה חַיָּב, וְהַשְּׁאָר פָּטוּר. וְאִם חָשַׁב עָלָיו אַחַר כָּךְ לַאֲכִילָה, חַיָּב בְּעָרְלָה וּבִרְבַעי, וּמוֹנִין לוֹ מִשְּׁעַת נְטִיעָה. אֲבָל אִם לֹא חָשַׁב עָלָיו עַד סוֹף שָׁנָה שְׁלִישִׁית, אֵין בּוֹ דִּין רְבַעי, שֶׁאֵין דִּין רְבַעי בְּלֹא עָרְלָה. וְאִם נְטָעוֹ לְמַאֲכָל וְאַחַר כָּךְ חָשַׁב עָלָיו לְאֶחָד מֵאֵלּוּ, חַיָּב\nהַנּוֹטֵעַ לְצֹרֶךְ מִצְוָה, כְּגוֹן לְצֹרֶךְ לוּלָב אוֹ אֶתְרוֹג, חַיָּב.\nהַנּוֹטֵעַ בְּתוֹךְ שֶׁלּוֹ לְצֹרֶךְ רַבִּים, חַיָּב.\nהַנּוֹטֵעַ בִּרְשׁוּת הָרַבִּים, וְהַגַּזְלָן שֶׁנָּטַע, וְהָעוֹבֵד כּוֹכָבִים שֶׁנָּטַע, בֵּין לְעַצְמוֹ בֵּין לְיִשְׂרָאֵל, וְהַנּוֹטֵעַ בַּבַּיִת וְעַל גַּג שֶׁמִּלְּאוֹ עָפָר וְנָטַע בּוֹ, וְהַנּוֹטֵעַ בִּסְפִינָה, אוֹ בְּעָצִיץ אַף עַל פִּי שֶׁאֵינוֹ נָקוּב, חַיָּב.\nהָעוֹלֶה מֵאֵלָיו \u0005(בִּרְשׁוּת הַיָּחִיד, חַיָּב)\u0006. בִּמְקוֹם \u0010c24\u0011 טְרָשִׁים, \u0005(פי' סְלָעִים חֲזָקִים וְקָשִׁים)\u0006, פָּטוּר. אֲפִלּוּ הַנּוֹטֵעַ בְּמָקוֹם שֶׁאֵינוֹ יִשּׁוּב, פָּטוּר, וְהוּא שֶׁלֹּא יִהְיֶה עוֹשֶׂה כְּדֵי טִפּוּל שֶׁמְּטַפֵּל בְּפֵירוֹתָיו עַד שֶׁמְּבִיאָם לְיִשּׁוּב. אֲבָל אִם הָיָה עוֹשֶׂה כְּדֵי טִפּוּל, חַיָּב.\nעוֹבֵד כּוֹכָבִים שֶׁהָיָה מוֹכֵר פֵּרוֹת וְאָמַר: שֶׁל עָרְלָה הֵן, אוֹ שֶׁל נֶטַע רְבַעי הֵן, \u0010c25\u0011 אֵינוֹ נֶאֱמָן, וַאֲפִלּוּ אָמַר: מֵאִישׁ פְּלוֹנִי לְקַחְתִּים.",[],["\u0003מרבעי. \u0004 דגבי ערלה כתיב את פריו ודרשינן את התפל לפריו אבל גבי רבעי לא כתיב את רק פרי לבד:","\u0003שאוסר. \u0004 כתב הש\"ך דנראה עיקר כדיעה זו ודברי המחבר הם ברורים ושלא כדת השיג עליו הב\"ח ע\"ש שמאריך בזה:","\u0003מותרים. \u0004 שאין טפלים אפילו לפירי אלא לאילן עצמו:","\u0003לארץ. \u0004 דמשום חומרא דא\"י חשבינן הכל כפירי ובח\"ל מאחר דערלה מדרבנן לא חשבינן הכל כפירות אלא אביונות שהן עיקר הפירות ש\"ס. ובלבוש כ' דקפריסין בא\"י נמי פטירי ולא נהירא וגם מוכח מש\"ס דלא כוותיה ובס' מע\"מ השיג ג\"כ עליו. ש\"ך:","\u0003מ\"ד. \u0004 ט\"ו יום דאב שהוא לעולם מלא וכ\"ט יום דאלול שהוא לעולם חסר והטעם דקי\"ל שלשים יום בשנה חשיב שנה לענין נטיעה אלא שאינה קולטת פחות מי\"ד יום:","\u0003שיחנטו. \u0004 הטעם דכל שהוא חונט בין תשרי לט\"ו בשבט היינו מחמת יציקת מים שלפני ר\"ה והרי הן כאלו חנטו קודם תשרי וכיון שכן ליכא לאפלוגי בין שנטעה מ\"ד יום לפני ר\"ה או פחות מכן. הר\"ן כתב הש\"ך בשם הרא\"ש דהאידנא אין חנטה בשום אילן קודם ט\"ו בשבט ולכן אין נזהרין בערלה אלא ג' שנים והא דלא כתבו המחבר משום דס\"ל דעיקר כדעת הרמב\"ם בס\"ה דס\"ל אפילו אם חנטו קודם ט\"ו בשבט לעולם לא משכחת לה יותר מן ג' שנים דכשנטע פחות מל' יום קודם ר\"ה א\"צ להמתין עד ט\"ו בשבט ולכך השמיט המחבר דברי הרא\"ש וע\"ל ס\"ה:","\u0003לאו. \u0004 כגון שנטעו בפחות ממ\"ד יום לפני ר\"ה דהשתא מונין השנה מר\"ה לכך לא החמרנו בסופה לאסור כל החניטה מאחר ר\"ה עד ט\"ו בשבט:","\u0003פודים. \u0004 כתב הש\"ך ונראה דיש ליזהר לכתחילה שלא לפדות אלא בתלוש ממש אבל בשעת הדחק וכהאי גוונא יש לפדות במחובר שלא יחול עד שיתלקט עכ\"ל:","\u0003בכרם. \u0004 ונראה דבין בכרם רבעי ובין בנטע רבעי יש לפדות בח\"ל בלא ברכה. ש\"ך:","\u0003מותר. \u0004 כתב הש\"ך אע\"ג דבכל הל\"מ קי\"ל ספיקא אסור כמו בשל תורה מ\"מ הל\"מ שבכאן נאמרה שספיקא יהא מותר הכי אמרינן בש\"ס:","\u0003ערלה. \u0004 ונטיעות של היתר ג\"כ:","\u0003וכ\"ש. \u0004 כתב הש\"ך צ\"ע למאי כתב הרמ\"א דין זה הרי מבואר בדברי המחבר סעיף י' ונראה משום דהמחבר העתיק לשון הרמב\"ם ומשמע מלשונו דבכרם שהוא ספק ערלה מותר ליקח ממנו בידים שהרי הוא ככרם של היתר והרב לא ס\"ל הכי אלא כדעת הטור וסייעתו דאסור ליקח ממנו בידים רק דזה מותר אפילו אם רואה שהעובד כוכבים בוצר ממנו לכן הוצרך לכתוב וכ\"ש וכו':","\u0003מותר. \u0004 והיינו בענין דליכא למיחש ביה משום יין נסך. ש\"ך:","\u0003ליטע. \u0004 דזה וז\"ג אסור לכתחילה:","\u0003גורם. \u0004 היינו פירות דאיסורא וקרקע דהתירא גורמין לאילן שיבא ועכ\"פ פשוט שצריך ג' שנים לאותו אילן שיגדל אח\"כ כדין ערלה אלא דלאחר ג' שנים מותר ואי לא הוה זוז\"ג היה אסור לעולם עכ\"ל הט\"ז:","\u0003התנו. \u0004 כתב הב\"ח דוקא שהתנו מתחלה גם ע\"ז שיבאו לחשבון אז אסור אבל אם לא התנו מתחלה אלא שהעובד כוכבים יאכל ג' שני ערלה והישראל ג' שני היתר א\"כ מדינא אין שם חשבון עליו הלכך אפי' באו לחשבון אין כאן איסור והט\"ז אוסר בזה דכיון שחולקי' פירות כנגד פירות הוי כמחליף וכן מוכח מהרמב\"ם בהל' שבת שלא כ' שם אלא אם התנו תחלה שיהיה שכר שבת לעובד כוכבים לבדו אם מעט אם הרבה ושכר יום א' כנגדו לישראל לבדו מותר משמע דוקא בענין זה מדלא כתב רבותא טפי כשבאו לחשבון אף אם לא התנו תחלה וכן משמע מדברי המחבר כאן שכ' ובלבד שלא יבאו לחשבון משמע בכל גווני וכן עיקר הן כאן והן לענין שבת עכ\"ל:","\u0003מתירין. \u0004 דדוקא לענין שבת אסור משום שהעובד כוכבים עושה מלאכה האסורה בשליחות הישראל משא\"כ כאן הרי המלאכה מותרת אפילו בערלה \u0005(ומה שישראל אוכל כנגדן אין זה נהנה שכן המשפט בשנה שזה עובד זה אוכל)\u0006 רש\"י:","\u0003לומר. \u0004 הטעם בזה דהוה כמו מכירה שמוכר לו הקרקע שלו בשכר שנותן לו הקרקע שלו לעבדה והוי כמו מכרה במעות וזה מותר לכ\"ע עכ\"ל הט\"ז:","\u0003פירות. \u0004 כ' הט\"ז לא ידעתי מקור לדין זה ותמוה הוא והניחו בצ\"ע דלמה בעינן בסי\"ב התנו דוקא בתחלת השותפות אמאי לא מהני ג\"כ אח\"כ כל זמן שלא גדלו הפירות וכו' ע\"ש \u0005(ובנה\"כ כ' שמצא כן בבדק הבית שם תשובת הרשב\"א ושאר פוסקים ומה שהקשה בט\"ז מסי\"ב לק\"מ דהתם יטול חלקו כנגדו אחר שבאו לעולם משא\"כ הכא דהמכירה היא מעכשיו)\u0006:","\u0003מחובר. \u0004 בב\"י כתב שהר\"ן הביא מהירושלמי דאף אם לא נפסק הראשון נוהג בה ערלה כל שאינה יונקת ממנה אלא מעצמה ואמרינן מאן מוכח ומשני שכשהיא יונקת מהאב הופכת עלין שלה שלא יעמדו כנגד האב וסימנך מאן דאכיל דלאו דיליה בהיל לאיסתכולי ביה עכ\"ל וכתב עוד הר\"ן דכאן מיירי שהרכיב באילן הנטוע לסייג ולקורות דפטור מערלה ע\"כ חייבת הנטיעה המורכבת בערלה א\"נ באילן סרק הרכיבה אע\"ג דעביד איסורא מכל מקום יש בה דין ערלה וגם רש\"י כתב בסוטה דהא דתנן המרכיב חייב בערלה היינו ילדה בילדה שאף אותו ענף חייב בערלה ואע\"ג שקצצה מזקנה נעשה עכשיו ילדה שזו היא נטיעתה:","\u0003נשאר. \u0004 ולדעת הרא\"ש שאפילו נשאר בו עד טפח חייב ומטפח ולמעלה פטור ולזה נוטה דעת הש\"ך ע\"ש:","\u0003גדלו. \u0004 שאין גדולי היתר מבטלין האיסור:","\u0003כראוי. \u0004 כמבואר בח\"מ סי' רי\"ו:","\u0003עליון. \u0004 ואע\"ג דהעליון גדל מתוך האיסור של תחתון אמרינן גידולי היתר מעלין את האיסור ול\"ק מהך דלעיל סכ\"ב ענף מלא פירות של ערלה וכו' שאין גדולי היתר וכו' דשאני התם דפירות הערלה היו ניכרים קודם שגדל ההיתר אבל הכא שהפירות גדלים בבת אחת מתוך ההיתר ומתוך האיסור ה\"ל זוז\"ג. ב\"י והאחרונים:","\u0003טרשים. \u0004 אבל בישוב אפילו עולה מאליו חייב דמסתמא ע\"י עבודת אדמה שעבדו מתחלה עלה. ש\"ך:","\u0003אינו. \u0004 בש\"ס יבמות אמרינן הטעם דלהשביח מקחו אומר כן וע\"ל סימן קכ\"ב ס\"ו וכ' הש\"ך דלעיל סימן צ\"ח נתבאר דערלה שנתערבה אינה בטלה אלא בר' והיינו במינו ואז אפילו ביבש לא אמרינן חד בתרי בטל עד ר' אבל שלא במינו לעולם בטלה בס' כשאר אסורים:"]],["\u0003הלכות כלאי אילן\u0004\nכִּלְאֵי הָאִילָנוֹת, הֲרֵי הֵם \u0010c0\u0011 בִּכְלָל מַה שֶּׁנֶּאֱמַר: שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם \u0005(וַיִּקְרָא יט, יט)\u0006 כֵּיצַד, הַמַּרְכִּיב אִילָן בְּאִילָן, כְּגוֹן שֶׁהִרְכִּיב יִחוּר שֶׁל תַּפּוּחַ בְּאֶתְרוֹג אוֹ אֶתְרוֹג בְּתַפּוּחַ, הֲרֵי זֶה לוֹקֶה מִן הַתּוֹרָה בְּכָל מָקוֹם, בֵּין בָּאָרֶץ בֵּין בְּחוּץ לָאָרֶץ. וְכֵן הַמַּרְכִּיב יָרָק בְּאִילָן אוֹ אִילָן בְּיָרָק, לוֹקֶה בְּכָל מָקוֹם.\nאָסוּר לְיִשְׂרָאֵל לְהַנִּיחַ לְעוֹבֵד כּוֹכָבִים שֶׁיַּרְכִּיב לוֹ אִילָנוֹ כִּלְאַיִם. \u0010c1\u0011\nמֻתָּר לִזְרֹעַ זְרָעִים וְזֶרַע אִילָן כְּאֶחָד. וְכֵן מֻתָּר לְעָרֵב זִרְעֵי אִילָנוֹת וּלְזָרְעָם כְּאֶחָד, שֶׁאֵין לְךָ כִּלְאַיִם בְּאִילָנוֹת אֶלָּא הַרְכָּבָה בִּלְבַד, בֵּין אִילָן בְּיָרָק, בֵּין יָרָק בְּאִילָן, בֵּין יָרָק בְּיָרָק שֶׁאֵינוֹ מִינוֹ, וַאֲפִלּוּ עֵץ סְרָק עַל עֵץ מַאֲכָל אוֹ עֵץ מַאֲכָל עַל עֵץ סְרָק.\nיֵשׁ אִסוּר הַרְכָּבָה אֲפִלּוּ תַּחַת הַקַּרְקַע, כְּגוֹן זְמוֹרַת הַגֶּפֶן שֶׁהִבְרִיכָהּ תַּחַת הַקַּרְקַע, אָסוּר לִזְרֹעַ עָלֶיהָ יָרָק, אֶלָּא אִם כֵּן יֵשׁ עַל גַּבָּהּ עָפָר שְׁלשָׁה טְפָחִים. וַאֲפִלּוּ הִבְרִיכָהּ בְּתוֹךְ דְּלַעַת שֶׁיָּבְשָׁה, אוֹ בְּתוֹךְ סִילוֹן שֶׁל \u0010c2\u0011 חֶרֶס, מִפְּנֵי שֶׁנִּשְׁרָשׁ בָּהּ וַהֲוָה לֵהּ מַרְכִּיב יָרָק בְּאִילָן. וְאִם הָיָה עַל גַּבָּהּ פָּחוֹת מִזֶּה, אָסוּר לִזְרֹעַ עַל גַּבָּהּ \u0010c3\u0011 וּמֻתָּר לִזְרֹעַ בְּצִדָּהּ. אֲבָל הִבְרִיכָהּ בְּסֶלַע קָשֶׁה, אֲפִלּוּ אֵין עָלֶיהָ עָפָר אֶלָּא שָׁלשׁ אֶצְבָּעוֹת, מֻתָּר לְהָבִיא זֶרַע עָלֶיהָ. בַּמֶּה דְבָרִים אֲמוּרִים, כְּשֶׁאֵין עִקַּר הַגֶּפֶן נִרְאֶה. אֲבָל אִם נִרְאֶה, צָרִיךְ לְהַרְחִיק שִׁשָּׁה טְפָחִים לְכָל רוּחַ וְאַחַר כָּךְ זוֹרֵעַ, כְּמוֹ שֶׁמְּרַחֵק מִכָּל גֶּפֶן יְחִידִית שֶׁלֹּא הֻבְרְכָה.\nוְדַוְקָא בִּכְהַאי גַּוְנָא שֶׁנִּקְרָא עָלָיו שֵׁם אִילָן קֹדֶם שֶׁהִבְרִיכָהּ. אֲבָל מֻתָּר לִזְרֹעַ אֵצֶל הָאִילָן, אַף עַל פִּי שֶׁשָּׁרְשֵׁי הַיָּרָק נִכְנָסִים בְּתוֹךְ שָׁרְשֵׁי הָאִילָן, כֵּיוָן שֶׁאֵין עַל הַשָּׁרָשִׁים שֵׁם אִילָן. וַאֲפִלּוּ בְּמַבְרִיךְ, דַּוְקָא בִּזְמוֹרַת הַגֶּפֶן מִפְּנֵי שֶׁהִיא רַכָּה וְשָׁרְשֵׁי הַזְּרָעִים נִכְנָסִים, אֲבָל הַמַּבְרִיךְ עָנָף מֵאִילָן אֶחָד, מֻתָּר לִזְרֹעַ עַל גַּבָּיו אֲפִלּוּ אֵין עָלָיו עָפָר שָׁלֹשׁ אֶצְבָּעוֹת.\nיֵשׁ בְּאִילָנוֹת דּוֹמִים זֶה לָזֶה בֶּעָלִין אוֹ בַּפֵּרוֹת, וְאַף עַל פִּי כֵן הוֹאִיל וְהֵם שְׁנֵי מִינִים הֲרֵי אֵלּוּ כִּלְאַיִם. כֵּיצַד, הַתַּפּוּחַ עִם הַחַזְרָד \u0005(פֵּרוּשׁ מִין תַּפּוּחַ יְעָרִי תַּרְגּוּם וְכַפְתּוֹר (שְׁמוֹת כה, לה, לז, כא)\u0006 וְחֵזוּר) הַפַּרְסְקִין \u0005(פֵּרוּשׁ פירסק\"י בְּלַעַ\"ז)\u0006 עִם הַשְּׁקֵדִים, הַשֵּׁזָפִין \u0005(פי' הִרְכִּיב זֵיתִים עַל רִמּוֹן, שֶׁהֵם פְּרִי דּוֹמֶה לְזַיִת, יוֹצֵא מֵהֶם שֵׁזָפִין)\u0006 עִם הָרִמּוֹן, אַף עַל פִּי שֶׁדּוֹמִים זֶה לָזֶה, כִּלְאַיִם זֶה בָּזֶה, אֲבָל הָאַגָּסִים \u0005(פי' פיר\"י בְּלַעַ\"ז)\u0006 עִם הַקְּרוּסְטוּמֵלִין \u0005(פי' מִין אַגָּסִים)\u0006 וְהַפְּרִישָׁן \u0005(פי' קודוציו)\u0006 עִם הָעֻזְרָדִין \u0005(פי' סורבוליי)\u0006, אֵינָם כִּלְאַיִם זֶה בָּזֶה. \u0005הַגָּה: וְכֵן מֻתָּר לְהַרְכִּיב מִין א', אֲפִלּוּ שְׁחֹרוֹת בִּלְבָנוֹת וְדַקּוֹת בְּגַסּוֹת, אַף עַל פִּי שֶׁיֵּשׁ לוֹ שֵׁם לְוַי (כָּל בּוֹ וב\"ח בְּשֵׁם א\"ח)\u0006. וְכֵן סְרָק עַל גַּבֵּי סְרָק, שָׁרֵי, אַף עַל פִּי שֶׁאֵינוֹ מִינוֹ \u0005(כֵּן מַשְׁמָע מֵהַטּוּר)\u0006. וּמִכָּל מָקוֹם הוֹאִיל וְאֵין רֹב הָעוֹלָם מַכִּירִין רֹב הַמִּינִין, טוֹב לִזָּהֵר מִכֻּלָּן \u0005(ב\"י בְּשֵׁם סמ\"ק)\u0006.\nאָסוּר לְקַיֵּם הַמֻּרְכָּב כִּלְאַיִם, אֲבָל הַפְּרִי הַיּוֹצֵא מִמֶּנּוּ, מֻתָּר, וַאֲפִלּוּ לְזֶה שֶׁעָבַר וְהִרְכִּיבוֹ. וּמֻתָּר לִקַּח עָנָף מֵהַמֻּרְכָּב וּלְנָטְעוֹ בְּמָקוֹם אַחֵר.",[],["\u0003בכלל. \u0004 כ' הדרישה דנראה אם זרע ב' מיני אילנות בארץ ישראל לא גרע איסורו מכלאי זרע השדה כו' ולא עיין ברמב\"ם שכ' בהדיא וכן מותר לערב זרעי אילנות ולזרען כאחד שאין לך כלאים באילנות אלא הרכבה בלבד וזה אפילו בא\"י שהרי כ' שאין לך כלאים וכו' עכ\"ל הט\"ז:","\u0003זרעים. \u0004 כ' הש\"ך משמע אפילו בא\"י מותר אבל באמת לא כיון יפה אלא נראה עיקר כדעת הטור דבא\"י אסור דנהי דמשום הרכבת אילן ליכא איסורא דכלאי זרעים מיהא איכא עכ\"ל וכ\"כ הט\"ז דכן מוכח מהירושלמי שזרעים עם האילן אסור וע\"ש:","\u0003חרס. \u0004 והטור כ' של עץ:","\u0003בצדה. \u0004 והש\"ך כתב דטוב ליזהר לכתחלה ולהחמיר שלא לזרוע תוך שלשה טפחים דכן דעת הר\"ן והתוספות ע\"ש: [ועי' בש\"ך עצמו]:"]],["\u0003הלכות כלאי הכרם\u0004\nהַזּוֹרֵעַ שְׁנֵי מִינֵי תְּבוּאָה אוֹ שְׁנֵי מִינֵי יְרָקוֹת עִם זֶרַע הַכֶּרֶם, הֲרֵי זֶה לוֹקֶה שְׁתַּיִם, אַחַת מִשּׁוּם שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם \u0005(וַיִּקְרָא יט, יט)\u0006 וְאַחַת מִשּׁוּם לֹא תִזְרַע כַּרְמְךָ כִּלְאָיִם \u0005(דְּבָרִים כב, ט)\u0006 וְאֵינוֹ לוֹקֶה מִשּׁוּם לֹא תִּזְרַע כַּרְמְךָ כִּלְאַיִם \u0005(דְּבָרִים כב, ט)\u0006 עַד שֶׁיִּזְרַע בְּאֶרֶץ יִשְׂרָאֵל חִטָּה וּשְׂעוֹרָה וְחַרְצָן בְּמַפֹּלֶת יָד. וְכֵן אִם חִפָּה אוֹתָם בְּעָפָר, לוֹקֶה. וְכֵן אִם זָרַע שְׁנֵי מִינֵי יָרָק וְחַרְצָן, אוֹ זֶרַע אֶחָד יָרָק וְזֶרַע אֶחָד מִין תְּבוּאָה וְחַרְצָן בְּמַפֹּלֶת יָד, הֲרֵי זֶה לוֹקֶה. וְאֵינוֹ חַיָּב מִן הַתּוֹרָה אֶלָּא עַל קַנְּבּוֹס וְלוּף וְכַיּוֹצֵא בָהֶם, מִזְּרָעִים שֶׁנִּגְמָרִים וְעִם תְּבוּאַת הַכֶּרֶם, אֲבָל שְׁאָר הַזְּרָעִים אָסוּר מִדִּבְרֵיהֶם. וְכֵן אָסוּר מִדִּבְרֵיהֶם לִזְרֹעַ כִּלְאֵי הַכֶּרֶם בְּחוּצָה לָאָרֶץ. וְאֵין עוֹדְרִין עִם הָעוֹבֵד כּוֹכָבִים בְּכִלְאַיִם, אֲבָל עוֹקְרִין עִמּוֹ כְּדֵי לְמַעֵט הַתִּפְלָה.\nאֵין אֲסוּרִים מִשּׁוּם כִּלְאֵי הַכֶּרֶם אֶלָּא מִינֵי תְּבוּאָה וּמִינֵי יְרָקוֹת בִּלְבַד. אֲבָל שְׁאָר מִינֵי זְרָעִים, מֻתָּר לְזָרְעָם בְּכֶרֶם. וְאֵין צָרִיךְ לוֹמַר שְׁאָר אִילָנוֹת.\nאָסוּר לִזְרֹעַ יְרָקוֹת אוֹ תְּבוּאָה בְּצַד הַגְּפָנִים, אוֹ לִטַּע גֶּפֶן בְּצַד הַיָּרָק אוֹ הַתְּבוּאָה. וְאִם עָשָׂה כֵן, אַף עַל פִּי שֶׁאֵינוֹ לוֹקֶה, הֲרֵי זֶה קִדֵּשׁ, וְנֶאֶסְרוּ שְׁנֵיהֶם בַּהֲנָאָה הַיָּרָק אוֹ הַתְּבוּאָה וְהַגְּפָנִים, וְשׂוֹרְפִין אֶת שְׁנֵיהֶם, שֶׁנֶּאֱמַר: פֶּן תִּקְדַּשׁ הַמְלֵאָה הַזֶּרַע. \u0005(דְּבָרִים כב, ט)\u0006 וַאֲפִלּוּ הַקַּשׁ שֶׁל תְּבוּאָה וְהָעֵצִים שֶׁל גְּפָנִים הָאֵלּוּ אֲסוּרִים בַּהֲנָאָה וְשׂוֹרְפִים אוֹתָם, וְלֹא יַסִיק בָּהֶם תַּנּוּר וְכִירַיִם, וְלא יְבַשֵּׁל בָּהֶם בְּאֵשׁ שְׂרֵפָתָן.\nאֶחָד הַנּוֹטֵעַ וְאֶחָד הַמְקַיֵּם, כֵּיוָן שֶׁרָאָה כִּלְאַיִם צָמְחוּ בְּכַרְמוֹ וְהִנִּיחָם, הֲרֵי זֶה קִדֵּשׁ. וְאֵין אָדָם מְקַדֵּשׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. לְפִיכָךְ הַמְּסַכֵּךְ גַּפְנוֹ עַל גַּבֵּי תְּבוּאָתוֹ שֶׁל חֲבֵרוֹ, קִדֵּשׁ גַּפְנוֹ וְלֹא נִתְקַדְּשָׁה הַתְּבוּאָה. סִכֵּךְ גֶּפֶן חֲבֵרוֹ עַל תְּבוּאָתוֹ, קִדֵּשׁ תְּבוּאָתוֹ וְלֹא קִדֵּשׁ גֶּפֶן חֲבֵרוֹ. סִכֵּךְ גֶּפֶן חֲבֵרוֹ עַל תְּבוּאַת חֲבֵרוֹ, לֹא קִדֵּשׁ אֶחָד מֵהֶם, וּמִפְּנֵי זֶה הַזּוֹרֵעַ כַּרְמוֹ בַּשְּׁבִיעִית לֹא קִדְּשׁוֹ.\nהָרוֹאֶה כִּלְאַיִם בְּכֶרֶם חֲבֵרוֹ וְקִיְּמָן, הֲרֵי זֶה \u0010c0\u0011 הָרוֹאֶה אָסוּר בַּהֲנָיָתָן וְכָל אָדָם מֻתָּרִים בָּהֶם. וְאֵלּוּ קִיְּמָן בַּעַל הַכֶּרֶם הָיָה מַקְדִּישׁ אוֹתָם לְכָל אָדָם, כְּמוֹ שֶׁבֵּאַרְנוּ.\nהָאַנָּס שֶׁזָּרַע כִּלְאַיִם בְּכֶרֶם חֲבֵרוֹ, אִם נִשְׁתַּקְּעוּ הַבְּעָלִים אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ, הֲרֵי זֶה קִדֵּשׁ מִן הַתּוֹרָה. וְאִם לֹא נִשְׁתַּקְּעוּ הַבְּעָלִים, אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ, אֵינוֹ מְקַדֵּשׁ אֶלָּא מִדִּבְרֵי סוֹפְרִים.\nהָרוּחַ שֶׁעָקְרָה פְּאֵרוֹת הַגֶּפֶן וְשָׁלְחָה אוֹתָם עַל הַתְּבוּאָה, יִגְדֹּר אוֹתָם מִיָּד. וְאִם אֵרְעוֹ אֹנֶס וְלא סִלְּקָן, הֲרֵי אֵלּוּ מֻתָּרִים וְלֹא נִתְקַדְּשׁוּ.\nאַנָּס שֶׁזָּרַע אֶת הַכֶּרֶם, כְּשֶׁיֵּצֵא הָאַנָּס יִקְצֹר הַזֶּרַע מִיָּד, וַאֲפִלּוּ בְּחֻלּוֹ שֶׁל מוֹעֵד. וְאִם לֹא מָצָא פּוֹעֲלִים, יוֹסִיף לָהֶם עַד שְׁלִישׁ בִּשְׂכָרָן. בִּקְּשׁוּ מִמֶּנּוּ יוֹתֵר, אוֹ שֶׁלֹּא מָצָא פּוֹעֲלִים, הֲרֵי זֶה מְבַקֵּשׁ בְּנַחַת וְקוֹצֵר. וְאִם נִשְׁתַּהָה הַזֶּרַע עַד שֶׁיַּגִּיעַ לָעוֹנָה שֶׁמְּקַדֵּשׁ, הֲרֵי זֶה קִדֵּשׁ וְיֵאָסְרוּ שְׁנֵיהֶם.\nמֵאֵימָתַי תְּבוּאָה אוֹ יָרָק מִתְקַדְּשִׁים, מִשֶּׁיַּשְׁרִישׁוּ. וַעֲנָבִים, מִשֶּׁיֵּעָשׂוּ כְּפוֹל הַלָּבָן.\nכֶּרֶם שֶׁלּא הִגִּיעוּ עֲנָבָיו לִהְיוֹת כְּפוֹל הַלָּבָן אֶלָּא עֲדַיִן הֵם בֹּסֶר, וְזָרַע בְּתוֹכוֹ יָרָק אוֹ תְּבוּאָה, וְהִשְׁרִישׁוּ, הֲרֵי זֶה לֹא קִדֵּשׁ. וְאַף עַל פִּי כֵן קוֹנְסִין אוֹתוֹ וְאוֹסְרִין הַזֶּרַע, אֲבָל הַבֹּסֶר מֻתָּר. וְאִם עָקַר הַזֶּרַע קֹדֶם שֶׁיַּעֲשׂוּ הָעֲנָבִים כְּפוֹל הַלָּבָן, הֲרֵי זֶה מֻתָּר בַּהֲנָאָה. מִקְּצָתָן נַעֲשׂוּ כְּפוֹל הַלָּבָן וּמִקְּצָתָן לֹא נַעֲשׂוּ, אֶת שֶׁנַּעֲשׂוּ נִתְקַדְּשׁוּ, וְאֶת שֶׁלֹּא נַעֲשׂוּ, מֻתָּרִים.\nעֲנָבִים שֶׁנַּעֲשׂוּ כְּפוֹל הַלָּבָן וְזָרַע בְּצִדָּן תְּבוּאָה אוֹ מִינֵי יְרָקוֹת וְלָקַט הַזֶּרַע קֹדֶם שֶׁיַּשְׁרִישׁ, הֲרֵי זֶה מֻתָּר בַּהֲנָאָה. וְאִם הִשְׁרִישׁ, אָסוּר.\nגֶּפֶן שֶׁיָּבְשׁוּ הֶעָלִים שֶׁלָּהּ וְנָפְלוּ כְּדֶרֶךְ שֶׁתִּיבַשׁ הַגֶּפֶן בִּימֵי \u0010c1\u0011 הַקֹּר, אָסוּר לִזְרֹעַ בְּצִדָּהּ יָרָק אוֹ תְּבוּאָה, וְאִם זָרַע לֹא קִדֵּשׁ. וְכֵן הַזּוֹרֵעַ בְּעָצִיץ שֶׁאֵינוֹ נָקוּב הַמֻּנָּח בְּכֶרֶם, לֹא קִדֵּשׁ, וּמַכִּין אוֹתוֹ מַכַּת מַרְדוּת. אֲבָל עָצִיץ נָקוּב, הֲרֵי הוּא כְּאֶרֶץ.\nהָיָה עוֹבֵר בְּכֶרֶם וְנָפְלוּ מִמֶּנּוּ זְרָעִים, אוֹ שֶׁיָּצְאוּ עִם הַזְּבָלִים אוֹ עִם הַמַּיִם, אוֹ שֶׁהָיָה זוֹרֵעַ אוֹ זוֹרֶה בְּשָׂדֶה לָבָן וְסִעֲרַתּוּ הָרוּחַ לַאֲחוֹרָיו וְנָפְלוּ הַזְּרָעִים בַּכֶּרֶם וְצָמְחוּ, הֲרֵי זֶה לֹא נִתְקַדֵּשׁ, שֶׁנֶּאֱמַר: אֲשֶׁר תִּזְרַע \u0005(דְּבָרִים כב, ט)\u0006 וְזֶה לֹא זָרַע. וְחַיָּב לַעֲקֹר כְּשֶׁיִּרְאֶה, וְאִם קִיְּמָן הֲרֵי זֶה קִדֵּשׁ. וְאִם סִעֲרַתּוּ הָרוּחַ לְפָנָיו וְרָאָה הַזְּרָעִים שֶׁנָּפְלוּ לַכֶּרֶם, הֲרֵי זֶה כְּזוֹרֵעַ. וְכֵיצַד יַעֲשֶׂה, אִם צָמְחוּ הָעֲשָׂבִים, יַהַפְכֵם בְּמַחֲרֵשָׁה וְדַיּוֹ. וְאִם מְצָאָם שֶׁנַּעֲשׂוּ אָבִיב, יְנַפֵּץ אוֹתוֹ אָבִיב כְּדֵי לְהַשְׁחִיתוֹ, שֶׁהַכֹּל אָסוּר בַּהֲנָאָה. וְאִם מְצָאָם שֶׁנַּעֲשִׂים דָּגָן, הֲרֵי זֶה תִּשָּׂרֵף. וְאִם רָאָה אוֹתָם וְקִיְּמָם, הֲרֵי אֶלָּא יִשָּׂרְפוּ עִם הַגְּפָנִים הַסְמוּכוֹת לָהֶם.\nהָרוֹאֶה בְּכֶרֶם עֶשֶׂב שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְזָרְעָהּ, אַף עַל פִּי שֶׁהוּא רוֹצֶה בְּקִיּוּמוֹ לִבְהֵמָה אוֹ לִרְפוּאָה, הֲרֵי זֶה לֹא קִדֵּשׁ עַד שֶׁיְּקַיֵּם דָּבָר שֶׁכְּמוֹתוֹ מְקַיְּמִים רֹב הָעָם בְּאוֹתוֹ מָקוֹם. כֵּיצַד, הַמְקַיֵּם קוֹצִים בְּכֶרֶם, \u0010c2\u0011 בַּעֲרָב שֶׁרוֹצִים בְּקוֹצִים לִגְמַלֵּיהֶם, הֲרֵי זֶה קִדֵּשׁ. הָאִירוּס וְהַקֵּסוּם וְשׁוֹשַׁנַּת הַמֶּלֶךְ וּשְׁאָר מִינֵי זְרָעִים, אֵינָם כִּלְאַיִם בְּכֶרֶם. הַקִּנְדּוֹס וְצֶמֶר גֶּפֶן, הֲרֵי הֵם כִּשְׁאָר מִינֵי יְרָקוֹת וּמְקַדְּשִׁים בְּכֶרֶם. וְכֵן כָּל מִינֵי דְּשָׁאִים שֶׁעוֹלִים מֵאֲלֵיהֶן בַּשָּׂדֶה, הֲרֵי הֵם מְקַדְּשִׁים בְּכֶרֶם. וּפוֹל הַמִּצְרִי, מִין זְרָעִים הוּא וְאֵינוֹ מְקַדֵּשׁ.\nהַקָּנִים וְהַוֶּרֶד וְהָאֲטָדִין \u0005(פי' עָרוּךְ מִין הֲדַס)\u0006, מִינֵי אִילָן הֵם וְאֵינָם כִּלְאַיִם בְּכֶרֶם. זֶה הַכְּלָל: כָּל הַמּוֹצִיא עָלִין מֵעִקָּרוֹ, הֲרֵי זֶה יָרָק. וְכָל שֶׁאֵינוֹ מוֹצִיא עָלִין מֵעִקָּרוֹ, הֲרֵי זֶה אִילָן. וְהַצָּלָף, אִילָן לְכָל דָּבָר.\nהָרוֹאֶה יָרָק בְּכֶרֶם וְאָמַר: כְּשֶׁאַגִּיעַ לוֹ אֲלַקְּטֶנּוּ, מֻתָּר. הִגִּיעַ לוֹ וְעָבַר מֵעָלָיו וְאָמַר: כְּשֶׁאֶחֱזֹר לוֹ אֲלַקְּטֶנּוּ, אִם שָׁהָה עַד שֶׁהוֹסִיף אֶחָד בְּק' ק', הֲרֵי זֶה קִדֵּשׁ.\nאָסוּר לַעֲבֹר בְּעָצִיץ נָקוּב שֶׁזָּרוּעַ בּוֹ יָרָק בְּתוֹךְ הַכֶּרֶם. וְאִם הִנִּיחוֹ תַּחַת הַגֶּפֶן וְנִשְׁתַּהָה שָׁם בָּאָרֶץ כְּדֵי לְהוֹסִיף אֶחָד מִמָּאתַיִם, הֲרֵי זֶה קִדֵּשׁ.\nבָּצָל שֶׁנְּטָעוֹ בְּכֶרֶם וְאַחַר כָּךְ נֶעֱקַר הַכֶּרֶם, וְאַחַר כָּךְ צָמְחוּ בְּצָלִים מִן הָעִקָּר הַנָּטוּעַ, אַף עַל פִּי שֶׁרַבּוּ הַגִּדּוּלִים עַל עִקָּרוֹ בְּמָאתַיִם, הֲרֵי אוֹתוֹ הָעִקָּר בְּאִסוּרוֹ, שֶׁאֵין גִּדּוּלֵי הֶתֵּר מַעֲלִין אֶת הָעִקָּר הָאָסוּר.\nהַזּוֹרֵעַ תְּבוּאָה אוֹ יָרָק בְּכֶרֶם אוֹ הַמְקַיְּמוֹ עַד שֶׁהוֹסִיף בְּמָאתַיִם, הֲרֵי זֶה מְקַדֵּשׁ מִן הַגְּפָנִים שֶׁסְבִיבוֹתָיו ט\"ז אַמָּה לְכָל רוּחַ, עֲגֻלּוֹת וְלֹא \u0010c3\u0011 מְרֻבָּעוֹת, וְרוֹאִים כָּל הָעִגּוּל שֶׁרָחְבּוֹ ל\"ב אַמָּה כְּאִלּוּ הוּא כֻּלּוֹ מָלֵא יָרָק, וְכָל גֶּפֶן שֶׁתִּהְיֶה בְּתוֹךְ עִגּוּל זֶה נִתְקַדְּשָׁה עִם הַיָּרָק, וְכָל שֶׁחוּץ לָעִגּוּל אֵינָהּ מִתְקַדֶּשֶׁת.\nבַּמֶּה דְבָרִים אֲמוּרִים, כְּשֶׁהָיָה בֵּין שִׂפְתֵי הָעִגּוּל הַזֶּה וּבֵין שׁוּרוֹת הַגְּפָנִים שֶׁחוּצָה לוֹ יוֹתֵר עַל ד' אַמּוֹת. אֲבָל אִם הָיָה בֵּינֵיהֶם אַרְבַּע אַמּוֹת מְצֻמְצָמוֹת אוֹ פָּחוֹת, רוֹאִין אֶת הָעִגּוּל כְּאִלּוּ הִגִּיעַ לַשּׁוּרָה הַסְמוּכָה לוֹ וּכְאִלּוּ רֹחַב הָעִגּוּל מ' אַמָּה, וְרוֹאִין כָּל גֶּפֶן שֶׁתִּפֹּל בְּתוֹךְ עִגּוּל זֶה שֶׁל אַרְבָּעִים אַמָּה הֲרֵי הִיא מִתְקַדֶּשֶׁת.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּזוֹרֵעַ אוֹ מְקַיֵּם תּוֹךְ הַכֶּרֶם. אֲבָל בַּזּוֹרֵעַ חוּץ לַכֶּרֶם וְסָמַךְ לוֹ, הֲרֵי זֶה מְקַדֵּשׁ שְׁתֵּי שׁוּרוֹת שֶׁל גְּפָנִים הַסְמוּכוֹת לַזֶּרַע, רוֹצֶה לוֹמַר בְּאֹרֶךְ כָּל הַזֶּרַע, וְיָתֵר ד' אַמּוֹת חוּץ לַזֶּרַע, וּמִתְקַדֵּשׁ מִן הַזֶּרַע רֹחַב ד' אַמּוֹת בְּאֹרֶךְ כָּל הַשּׁוּרָה שֶׁל כֶּרֶם. וְאִם זָרַע בְּצַד גֶּפֶן יְחִידִית, אֵינוֹ מְקַדֵּשׁ מֵהַזֶּרַע אֶלָּא שִׁשָּׁה טְפָחִים לְכָל רוּחַ.\nיַלְדָּה, פְּחוּתָה מִטֶּפַח, אֵינָהּ מְקַדֶּשֶׁת אֶת הַזְּרָעִים. בַּמֶּה דְבָרִים אֲמוּרִים, בִּשְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצֵאת זָנָב, אֲבָל אִם כָּל הַכֶּרֶם כֵּן, הֲרֵי זֶה מְקַדֵּשׁ.\nשְׁתֵּי גִּנּוֹת זוֹ עַל גַּב זוֹ, הַתַּחְתּוֹנָה עֲשׂוּיָה כֶּרֶם, זוֹרֵעַ אֶת הָעֶלְיוֹנָה עַד שֶׁהוּא מַגִּיעַ לַאֲוִיר י' טְפָחִים קָרוֹב לַכֶּרֶם, שֶׁאֲוִיר עֲשָׂרָה טְפָחִים סָמוּךְ לַכֶּרֶם אוֹ לְגֶפֶן יְחִידִית אָסוּר לִזְרֹעַ בּוֹ זְרָעִים. וְאִם הָיְתָה הָעֶלְיוֹנָה עֲשׂוּיָה כֶּרֶם, הֲרֵי זֶה זוֹרֵעַ אֶת הַתַּחְתּוֹנָה עַד שֶׁהוּא מַגִּיעַ לְמַטָּה מִשְּׁלשָׁה טְפָחִים מֵעִקַּר הַגְּפָנִים.\nמִי שֶׁהָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק אוֹ תְּבוּאָה וְנִמְלַךְ לִטַּע בָּהּ גְּפָנִים, הוֹפֵךְ אֶת הַזְּרָעִים בְּמַחֲרֵשָׁה וְאַחַר כָּךְ נוֹטֵעַ. וְלֹא יִטַּע וְאַחַר כָּךְ יַהֲפֹךְ.\nהָיְתָה נְטוּעָה גְּפָנִים וְנִמְלַךְ לִזְרֹעַ בָּהּ זְרָעִים, מְשָׁרֵשׁ אֶת הַגְּפָנִים וְאַחַר כָּךְ זוֹרֵעַ אֶת הַזְּרָעִים. וְאִם רָצָה לָקֹץ אֶת הַגְּפָנִים, עַד שֶׁלֹּא יִשָּׁאֵר מֵהֶן אֶלָּא פָּחוֹת מִטֶּפַח סָמוּךְ לָאָרֶץ, הֲרֵי זֶה מֻתָּר לִזְרֹעַ וְאַחַר כָּךְ יַחֲזֹר וִישָׁרֵשׁ אֶת הַנִּשְׁאָר בָּאָרֶץ מֵהַגְּפָנִים.\nהַמַּבְרִיךְ ג' גְּפָנִים וְעִקְּרֵיהֶם נִרְאִים, אִם יֵשׁ בֵּינֵיהֶם מִד' אַמּוֹת עַד ח' הֲרֵי אֵלּוּ מִצְטָרְפִים לִשְׁאָר גְּפָנִים הָעוֹמְדוֹת, וּכְאִלּוּ לֹא הִבְרִיכָן. וְאִם לָאו, אֵינָם מִצְטָרְפוֹת. הָיוּ פָּחוֹת מִג', אֵינָם מִצְטָרְפִים אֶלָּא מַרְחִיק מֵהֶם שִׁשָּׁה טְפָחִים לְכָל רוּחַ, וְזוֹרֵעַ.\nכָּל הַזּוֹרֵעַ תַּחַת הַשָּׂרִיגִים וְהֶעָלִים הַיּוֹצְאִים מִן הַגֶּפֶן, הֲרֵי זֶה קִדֵּשׁ וְאַף עַל פִּי שֶׁהַזֶּרַע רָחוֹק מֵעִקַּר הַגֶּפֶן כַּמָּה אַמּוֹת. הִדְלָה אֶת הַגֶּפֶן עַל מִקְצָת אֶפִּיפִירוֹת \u0005(פי' עֵצִים אוֹ קָנִים אֲרוּגִים שֶׁמַּדְלִין עֲלֵיהֶם שָׂרֵיגֵי הַגְּפָנִים כְּשֶׁהֵם אֲרֻכִּים הַרְבֵּה)\u0006, לֹא יִזְרַע תַּחַת מוֹתַר הָאֶפִּיפִירוֹת, וְאַף עַל פִּי שֶׁאֵין עֲלֵיהֶם לֹא עָלִים וְלֹא שָׂרִיגִים. וְאִם זָרַע, הוֹאִיל וְאֵין הַזֶּרַע תַּחַת סְכָךְ הַגֶּפֶן, הֲרֵי זֶה מֻתָּר. וְכֵן אִם הִדְלָה הַגֶּפֶן עַל מִקְצָת בַּדֵּי אִילָן שֶׁאֵינוֹ עוֹשֶׂה פֵּרוֹת, כְּגוֹן הָאֶרֶז וְהַבְּרוֹשׁ. אֲבָל אִם הִדְלָה עַל מִקְצָת אִילָן מַאֲכָל, הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחַת בַּדֵּי הָאִילָן שֶׁלֹּא נִמְשְׁכוּ עֲלֵיהֶם שָׂרִיגֵי הַגֶּפֶן, שֶׁאֵין אָדָם מְבַטֵּל אִילָן מַאֲכָל וְעוֹשֶׂהוּ אֶפִּיפִירוֹת לַגֶּפֶן. וְאִם נִמְשְׁכוּ הַשָּׂרִיגִים אַחַר שֶׁזָּרַע, וְסִכְּכוּ עַל הַזֶּרַע, הֲרֵי זֶה מַחֲזִירָם לְמָקוֹם אַחַר.\nהַזּוֹרֵעַ תַּחַת מוֹתַר הָאֶפִּיפִירוֹת, אוֹ תַּחַת מוֹתַר הָאִילָן שֶׁאֵינוֹ עוֹשֶׂה פֵּרוֹת, וְנִמְשְׁכוּ שָׂרִיגֵי הַגֶּפֶן וְסִכְּכוּ עַל הַזְּרָעִים, הֲרֵי זֶה אָסוּר לְקַיְּמוֹ אוֹ לְהַחֲזִיר הַשָּׂרִיגִים, אֶלָּא כֵּיצַד עוֹשֶׂה, עוֹקֵר הַזֶּרַע.\nקָנִים הַיּוֹצְאִים מִן הֶעָרִיס \u0005(פי' הָעֵצִים אוֹ קָנִים אֲשֶׁר עֲלֵיהֶם יִסְמֹךְ הַגֶּפֶן)\u0006 וְחָס עֲלֵיהֶם לְפָסְקָן כְּדֵי שֶׁלֹּא יַשְׁחִית הָאֶפִּיפִירוֹת, הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחְתֵּיהֶן. וְאִם הִנִּיחָם כְּדֵי שֶׁיְּהַלְּכוּ עָלָיו הַשָּׂרִיגִים וְהֶעָלִים הַיּוֹצְאִים, הֲרֵי זֶה אָסוּר לִזְרֹעַ תַּחְתֵּיהֶן.\nפֶּרַח הַיּוֹצֵא מִן הֶעָרִיס אוֹ מִן הַדָּלִית \u0005(פִּי' הַגֶּפֶן יְחִידִית הַמֻּדְלֵית עַל גַּבֵּי כְּלוֹנָסוֹת)\u0006, רוֹאִין אוֹתוֹ כְּאִלּוּ מִשְׁקֹלֶת תְּלוּיָה בּוֹ עַד הָאָרֶץ וְאָסוּר לִזְרֹעַ תַּחְתָּיו. וְכֵן הַמּוֹתֵחַ זְמוֹרָה מֵאִילָן לְאִילָן, אָסוּר לִזְרֹעַ תַּחְתֶּיהָ. קָשַׁר חֶבֶל אוֹ גֶּמִי בִּזְמוֹרָה וְקָשַׁר הָרֹאשׁ הָאֶחָד בָּאִילָן, הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחַת הַחֶבֶל. וְאִם מָתַח חֶבֶל זֶה כְּדֵי שֶׁיְּהַלְּכוּ עָלָיו הַשָׁרִיגִים וְהֶעָלִים, הֲרֵי הוּא כְּאֶפִּיפִירוֹת וְאָסוּר לִזְרֹעַ תַּחְתָּיו.\nהַבָּא לִזְרֹעַ בְּצַד הַכֶּרֶם, מַרְחִיק אַרְבַּע אַמּוֹת מֵעִקְּרֵי הַגְּפָנִים, וְזוֹרֵעַ. וְאִם גֶּפֶן יְחִידִית הִיא, מַרְחִיק מִמֶּנָּהּ שִׁשָּׁה טְפָחִים, וְזוֹרֵעַ.\nהָיְתָה שׁוּרָה אַחַת שֶׁל גְּפָנִים זוֹ בְּצַד זוֹ, וַאֲפִלּוּ הֵן מֵאָה, אֵין זֶה כֶּרֶם אֶלָּא כְּגֶפֶן יְחִידִית, וּמַרְחִיק מִן הַשּׁוּרָה שִׁשָּׁה טְפָחִים, וְזוֹרֵעַ. הָיוּ שְׁתֵּי שׁוּרוֹת, הֲרֵי זֶה כֶּרֶם וְצָרִיךְ לְהַרְחִיק ד' אַמּוֹת מִכָּל צַד, וְאַחַר כָּךְ יִזְרַע. וְכַמָּה יִהְיֶה בְּכָל שׁוּרָה, ג' גְּפָנִים אוֹ יוֹתֵר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה בֵּין כָּל גֶּפֶן וְגֶפֶן מִד' אַמּוֹת וְעַד ח'. אֲבָל אִם הָיָה בֵּין שְׁתֵּי הַשּׁוּרוֹת ח' אַמּוֹת, חוּץ מִמְּקוֹם הַגְּפָנִים, הֲרֵי אֵלּוּ כְּמֻבְדָּלוֹת זוֹ מִזּוֹ וְאֵינָם כֶּרֶם אֶחָד, וְאֵינוֹ מַרְחִיק אֶלָּא ו' טְפָחִים מִכָּל שׁוּרָה. וְכֵן אִם הָיָה בֵּינֵיהֶם פָּחוֹת מִד', הֲרֵי אֵלּוּ כְּגֶפֶן אַחַת וּמַרְחִיק ו' טְפָחִים לְכָל רוּחַ.\nהָיוּ ג' שׁוּרוֹת, אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶם פָּחוֹת מִד', הֲרֵי אֵלּוּ כֶּרֶם וְרוֹאִין אֶת הָאֶמְצָעִיּוֹת כְּאִלּוּ אֵינָם.\nהָיוּ ג' שׁוּרוֹת וּבֵין כָּל שׁוּרָה וְשׁוּרָה ח' אַמּוֹת אוֹ יוֹתֵר, הֲרֵי זֶה זוֹרֵעַ בֵּין הַשּׁוּרוֹת. לְפִיכָךְ הַנּוֹטֵעַ אֶת כַּרְמוֹ מִתְּחִלָּה, וְהִרְחִיק בֵּין כָּל שׁוּרָה וְשׁוּרָה ח' אַמּוֹת, מֻתָּר לְהָבִיא זֶרַע לְתוֹכוֹ וּמַרְחִיק מִכָּל שׁוּרָה וְשׁוּרָה שִׁשָּׁה טְפָחִים בִּלְבַד. אֲבָל אִם זָרַע חוּצָה לוֹ, צָרִיךְ לְהַרְחִיק מִשּׁוּרָה הַחִיצוֹנָה ד' אַמּוֹת כִּשְׁאָר הַכְּרָמִים. וְאֵין דִּין בֵּין הַשּׁוּרוֹת שֶׁל זֶה הַכֶּרֶם כְּכֶרֶם שֶׁחָרֵב בְּאֶמְצָעוֹ, שֶׁהֲרֵי מִתְּחִלָּה נְטָעָם מְרֻחָקִים.\nהָיְתָה בְּשָׂדֶה זוֹ שׁוּרָה אַחַת שֶׁל גְּפָנִים, וּבִשְׂדֵה חֲבֵרוֹ שׁוּרָה אַחֶרֶת כְּנֶגְדָּהּ, קְרוֹבָה לָהּ, אַף עַל פִּי שֶׁמַּפְסִיק בְּנֵיהֶם דֶּרֶךְ הַיָּחִיד אוֹ דֶּרֶךְ הָרַבִּים אוֹ גָּדֵר שֶׁהוּא נָמוּךְ מֵעֲשָׂרָה טְפָחִים, הֲרֵי אֵלּוּ מִצְטָרְפוֹת לִהְיוֹת שְׁתֵּיהֶן כֶּרֶם. וְהוּא שֶׁיִּהְיֶה בֵּינֵיהֶם פָּחוֹת מֵח'.\nנָטַע שׁוּרָה אַחַת בָּאָרֶץ וְשׁוּרָה אַחַת בַּמַּדְרֵגָה, אִם גְּבוֹהָה הַמַּדְרֵגָה מֵהָאֶרֶץ עֲשָׂרָה טְפָחִים, אֵינָם מִצְטָרְפִים. פָּחוֹת מִכָּאן, מִצְטָרְפִין.\nהַנּוֹטֵעַ חָמֵשׁ גְּפָנִים, שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצֵאת זָנָב, הֲרֵי זֶה נִקְרָא כֶּרֶם קָטָן וְצָרִיךְ לְהַרְחִיק מֵהֶן ד' אַמּוֹת לְכָל רוּחַ. אֲבָל אִם נְטָעָן שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת בָּאֶמְצַע, אוֹ ג' בְּשׁוּרָה וּשְׁתַּיִם כְּנֶגְדָּן בְּשׁוּרָה שְׁנִיָּה, אֵינָם כֶּרֶם וְאֵינוֹ מַרְחִיק מֵהֶם אֶלָּא ו' טְפָחִים לְכָל רוּחַ.\nכֶּרֶם שֶׁחָרַב, אִם יֵשׁ בּוֹ לְלַקֵּט עֶשֶׂר גְּפָנִים לְכָל בֵּית סְאָה וְיִהְיוּ נְטוּעוֹת שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצֵאת זָנָב, אוֹ יֵשׁ בּוֹ לְכַוֵּן ג' כְּנֶגֶד ג', הֲרֵי זֶה נִקְרָא כֶּרֶם דַּל וְאָסוּר לִזְרֹעַ בְּכֻלּוֹ.\nכֶּרֶם שֶׁאֵינוֹ נָטוּעַ שׁוּרוֹת שׁוּרוֹת, אֶלָּא מְעֻרְבָּב, אִם יֵשׁ בּוֹ לְכַוֵּן שְׁתַּיִם כְּנֶגֶד שָׁלֹשׁ הֲרֵי זֶה כֶּרֶם. וְאִם לָאו, אֵינוֹ כֶּרֶם אֶלָּא דַּיּוֹ לְהַרְחִיק ו' טְפָחִים מִכָּל גֶּפֶן וְגֶפֶן, וְזוֹרֵעַ.\nהָיוּ הָעִקָּרִים מְכֻוָּנִים וְהַנּוֹף אֵינוֹ מְכֻוָּן, הֲרֵי זֶה כֶּרֶם. הַנּוֹף מְכֻוָּן וְהָעִקָּר אֵינוֹ מְכֻוָּן, אֵינוֹ כֶּרֶם. הָיוּ דַּקּוֹת וְאֵינָן מְכֻוָּנוֹת, הָעֳבוּ וַהֲרֵי הֵן מְכֻוָּנוֹת, הֲרֵי זֶה כֶּרֶם.\nכֵּיצַד יוֹדֵעַ אִם הֵם מְכֻוָּנוֹת, מֵבִיא חוּט הַמִּדָּה וּמוֹתֵחַ מִזּוֹ לְזוֹ.\nכֶּרֶם שֶׁחָרַב בְּאֶמְצָעוֹ וְנִשְׁאַר שָׁלֵם מִכָּל סְבִיבָיו, אִם יֵשׁ בַּקָּרַחַת שֶׁבָּאֶמְצַע ט\"ז אַמָּה, הֲרֵי זֶה מַרְחִיק מֵעִקָּרֵי הַגְּפָנִים אַרְבַּע אַמּוֹת לְכָל רוּחַ, וְזוֹרֵעַ בְּאֶמְצַע הַקָּרַחַת. וְאִם אֵין בָּהּ ט\"ז אַמָּה, הֲרֵי זֶה לֹא יָבִיא זֶרַע לְשָׁם. וְאִם הֵבִיא, הוֹאִיל וְהִרְחִיק ד' אַמּוֹת לְכָל רוּחַ מֵהַגְּפָנִים שֶׁל כֶּרֶם, הֲרֵי זֶה לֹא קִדֵּשׁ.\nוְכֵן מָקוֹם שֶׁנִּשְׁאַר פָּנוּי בְּלֹא גְּפָנִים בֵּין סוֹף הַכֶּרֶם וּבֵין הַגָּדֵר שֶׁלּוֹ, וְהוּא הַנִּקְרָא \u0010c4\u0011 מְחוֹל הַכֶּרֶם, אִם יֵשׁ בּוֹ י\"ב אַמָּה מַרְחִיק מֵהַגְּפָנִים ד' אַמּוֹת וְזוֹרֵעַ אֶת הַשְּׁאָר. הָיָה בָּהּ פָּחוֹת מִי\"ב אַמָּה, לֹא יָבִיא זֶרַע לְשָׁם. וְאִם הֵבִיא, הוֹאִיל וְהִרְחִיק ד' אַמּוֹת, הֲרֵי זֶה לֹא קִדֵּשׁ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּכֶרֶם גָּדוֹל. אֲבָל בְּקָטָן, אֵין לוֹ מָחוֹל אֶלָּא מַרְחִיק אַרְבַּע אַמּוֹת מִסוֹף הַגְּפָנִים, וְזוֹרֵעַ עַד הַגָּדֵר. וְכֵן כֶּרֶם גָּדוֹל שֶׁהָיָה בֵּין כָּל שׁוּרָה וְשׁוּרָה שְׁמוֹנֶה אַמּוֹת אוֹ יוֹתֵר, אֵין לוֹ מָחוֹל.\nהָיָה גָּדֵר מַּקִּיף אֶת הַכֶּרֶם פָּחוֹת מֵעֲשָׂרָה טְפָחִים, אוֹ שֶׁהָיָה גָּבְהוֹ י' טְפָחִים וְאֵין בּוֹ רֹחַב ד' טְפָחִים, אֵין לוֹ מָחוֹל אֶלָּא מַרְחִיק מִסוֹף הַגְּפָנִים ד' אַמּוֹת וְזוֹרֵעַ עַד הַמְּחִצָּה, אֲפִלּוּ הָיָה בֵּין הַגְּפָנִים וּבֵין הַמְּחִצָּה ד' אַמּוֹת וּמֶחֱצָה, זוֹרֵעַ אֶת חֲצִי הָאַמָּה.\nגָּדֵר שֶׁהוּא גָּבוֹהַּ י' טְפָחִים, וְכֵן חָרִיץ שֶׁהוּא עָמֹק י' טְפָחִים וְרָחָב ד' טְפָחִים, הֲרֵי זֶה מֻתָּר לִטַּע כֶּרֶם בְּצִדּוֹ מִכָּאן וִירָקוֹת בְּצִדּוֹ מִכָּאן. אֲפִלּוּ מְחִצָּה שֶׁל קָנִים, אִם אֵין בֵּין קָנֶה לַחֲבֵרוֹ ג' טְפָחִים, הֲרֵי זוֹ מֻבְדֶּלֶת בֵּין הַכֶּרֶם וְהַיָּרָק, כְּגָדֵר.\nגָּדֵר הַמַּבְדִּיל בֵּין כֶּרֶם וְיָרָק שֶׁנִּפְרַץ עַד עֶשֶׂר אַמּוֹת, הֲרֵי זֶה כְּפֶתַח וּמֻתָּר. הָיְתָה פְּרוּצָה יוֹתֵר מֵעֶשֶׂר, כְּנֶגֶד הַפִּרְצָה אָסוּר עַד שֶׁיַּרְחִיק מִן הַגְּפָנִים כַּשִּׁעוּר. נִפְרְצוּ בּוֹ פְּרָצוֹת רַבּוֹת, אִם הָיָה הָעוֹמֵד כְּפָרוּץ, הֲרֵי זֶה מֻתָּר כְּאִלּוּ אֵין שָׁם פִּרְצָה. הָיָה פָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד, לֹא יִזְרַע כְּנֶגֶד כָּל הַמְּקוֹמוֹת הַפְּרוּצִים, עַד שֶׁיַּרְחִיק כַּשִּׁעוּר.\nמְחִצַּת הַכֶּרֶם שֶׁנִּפְרְצָה, אוֹמְרִים לוֹ: גְּדֹר. נִפְרְצָה, אוֹמְרִים לוֹ: גְּדֹר. נִתְיָאֵשׁ מִמֶּנָּהּ וְלֹא גְּדָרָהּ, הֲרֵי זֶה קִדֵּשׁ.\nבַּיִת שֶׁחֶצְיוֹ מְקֹרֶה וְחֶצְיוֹ אֵינוֹ מְקֹרֶה וּגְפָנִים נְטוּעִים בְּצַד זֶה, מֻתָּר לִזְרֹעַ יְרָקוֹת בַּצַּד הָאַחֵר, שֶׁהֲרֵי פִּי תִּקְרָה כְּאִלּוּ יָרַד וְסָתַם וְנַעֲשָׂה בֵּינֵיהֶם כִּמְחִצָּה. וְאִם הִשְׁוָה אֶת קֵרוּיוֹ, אָסוּר.\nחָצֵר קְטַנָּה שֶׁנִּפְרְצָה בְּמִלּוּאָהּ לִגְדוֹלָה, וְהָיוּ הַגְּפָנִים בַּגְּדוֹלָה, אָסוּר לִזְרֹעַ בַּקְּטַנָּה; וְאִם זָרַע, הַזְּרָעִים אֲסוּרִים וְהַגְּפָנִים מֻתָּרִים. הָיוּ גְּפָנִים בַּקְּטַנָּה, מֻתָּר לִזְרֹעַ בַּגְּדוֹלָה, הוֹאִיל וְיֵשׁ בַּגְּדוֹלָה פַּסִין מִכָּאן וּמִכָּאן הֲרֵי הִיא כְּמֻבְדֶּלֶת מִן הַקְּטַנָּה, וְאֵין הַקְּטַנָּה מֻבְדֶּלֶת מִן הַגְּדוֹלָה.\nחָרִיץ שֶׁהוּא עוֹבֵר בְּכֶרֶם, עָמֹק י' וְרָחָב ד', אִם הָיָה מְפֻלָּשׁ מֵרֹאשׁ הַכֶּרֶם וְעַד סוֹפוֹ הֲרֵי זֶה נִרְאֶה כְּבֵין שְׁנֵי הַכְּרָמִים וּמֻתָּר לִזְרֹעַ בְּתוֹכוֹ, וּבִלְבַד שֶׁלֹּא יִהְיוּ הַגְּפָנִים מְסַכְּכִין עָלָיו. וְאִם לֹא הָיָה מְפֻלָּשׁ, הֲרֵי הוּא כְּגַת שֶׁבְּאֶמְצַע הַכֶּרֶם, שֶׁאַף עַל פִּי שֶׁהִיא עֲמֻקָּה י' וּרְחָבָה ד' אוֹ יוֹתֵר, אָסוּר לוֹ לִזְרֹעַ בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיָה בַּקָּרַחַת ט\"ז אַמָּה.\nשְׁבִיל שֶׁבֵּין שְׁנֵי הַכְּרָמִים הֲרֵי הוּא כְּכֶרֶם שֶׁחָרֵב בְּאֶמְצָעוֹ, אִם יֵשׁ בֵּינֵיהֶם ט\"ז אַמָּה מַרְחִיק מִזֶּה ד' אַמּוֹת וּמִזֶּה ד' אַמּוֹת וְזוֹרֵעַ אֶת הַמּוֹתָר; וְאִם הָיָה פָּחוֹת מִכָּאן, לֹא יָבִיא זֶרַע לְשָׁם. \u0010c5\u0011\nשׁוֹמֵרָה \u0005(פי' בֵּית דִּירָה שֶׁעוֹשִׂים לְשׁוֹמֵר הַשָּׂדֶה)\u0006 שֶׁבַּכֶּרֶם, אִם גְּבוֹהָה עֲשָׂרָה וּרְחָבָה ד', מֻתָּר לִזְרֹעַ בְּרֹאשָׁהּ יָרָק, וּבִלְבַד שֶׁלֹּא יִהְיוּ הַשָּׂרִיגִים נוֹגְעִים בָּהּ, כְּדֵי שֶׁלֹּא יֵרָאֶה יָרָק בְּתוֹךְ הַכֶּרֶם מִלְּמַעְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְרֻבַּעַת. אֲבָל אִם הָיְתָה הַשּׁוֹמֵרָה עֲגֻלָּה, צְרִיכָה שֶׁיִּהְיֶה בְּתוֹכָהּ חֲלַל אַרְבָּעָה טְפָחִים, כְּדֵי שֶׁתִּהְיֶה מְפְלֶגֶת מִן הָאָרֶץ, וּצְרִיכָה עָפָר עַל רֹאשָׁהּ מִלְּמַעְלָה שְׁלֹשָׁה טְפָחִים.\nהַבַּיִת שֶׁבַּכֶּרֶם, אִם הָיָה יָתֵר מִשְּׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים, זוֹרְעִים בְּתוֹכוֹ יָרָק, וְאִם הָיָה פָּחוֹת מִשְּׁלֹשָׁה עַל שְׁלֹשָׁה, הֲרֵי הוּא כְּסָתוּם וְאֵין זוֹרְעִים בְּתוֹכוֹ.\nגֶּפֶן יְחִידִית שֶׁהָיְתָה נְטוּעָה בְּתוֹךְ הַבִּקְעָה אוֹ בְּתוֹךְ הֶחָרִיץ, מַרְחִיק מִמֶּנָּהּ שִׁשָּׁה טְפָחִים לְכָל רוּחַ, וְזוֹרֵעַ אֶת כָּל הֶחָרִיץ כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בַּמִּישׁוֹר. וְאִם הָיָה עָמֹק עֲשָׂרָה, וְהָיָה רָחָב שְׂפַת הֶחָרִיץ לְמַעְלָה אַרְבָּעָה, אָסוּר לִזְרֹעַ בְּתוֹכוֹ אַף עַל פִּי שֶׁהִרְחִיק שִׁשָּׁה.\nוְכֵן גֶּפֶן יְחִידִית שֶׁהָיְתָה מֻקָּפָה גָּדֵר גָּבוֹהַּ י' וְרָחָב ד', לֹא יִזְרַע בְּכָל הַמְּחִצָּה וְאַף עַל פִּי שֶׁהִרְחִיק ו'; וְאִם הִרְחִיק ו' וְזָרַע, לֹא קִדֵּשׁ. וְכַמָּה יַרְחִיק לְכַתְּחִלָּה וְיִזְרַע, ד' אַמּוֹת לְכָל רוּחַ, וְאַחַר כָּךְ יִזְרַע שְׁאָר הֶחָרִיץ אוֹ שְׁאָר הַמָּקוֹם הַמֻּקָּף גָּדֵר.\nהַגְּפָנִים שֶׁגָּדְלוּ כִּבְרִיָּתָן וַהֲרֵי הַשָּׂרִיגִים וְהָאֶשְׁכּוֹלוֹת שֶׁלָּהֶם מֻשְׁלָכִים בָּאָרֶץ, הֵם הַנִּקְרָאִים כֶּרֶם. אֲבָל הָעוֹשֶׂה כְּמוֹ מִטָּה אוֹ כְּמוֹ שְׂבָכָה גְּבוֹהָה מֵעַל הָאָרֶץ כְּדֵי שֶׁיִּהְיוּ הָאֶשְׁכּוֹלוֹת וְהַשָּׂרִיגִים נִמְשָׁכִים עָלֶיהָ, וְהִגְבִּיהַּ נוֹף הַגְּפָנִים מֵעַל הָאָרֶץ עַל אוֹתָהּ הַמִּטָּה וְהִדְלָה אוֹתָן, הֲרֵי זֶה נִקְרָא עָרִיס. וְאוֹתָן הַקָּנִים וְכַיּוֹצֵא בָהֶם שֶׁעָשָׂה מֵהֶם מִטָּה אוֹ כְּמוֹ שְׂבָכָה וְהִדְלָה עֲלֵיהֶן אֶת נוֹף הַגֶּפֶן, הֵן הַנִּקְרָאִים אֶפִּיפִירוֹת, וְדִינִין אֲחֵרִים יֵשׁ בְּעָרִיס.\nהַנּוֹטֵעַ שׁוּרָה אַחַת שֶׁל ה' גְּפָנִים אוֹ יוֹתֵר וְעֵרְסָן עַל גַּבֵּי כֹּתֶל גָּבוֹהַּ י' וְכַיּוֹצֵא בוֹ, אוֹ שֶׁנְּטָעָן בְּצַד חָרִיץ עָמֹק י' וְרָחָב ד', הֲרֵי אֵלּוּ נִקְרָאִים עָרִיס וְצָרִיךְ לְהַרְחִיק מִן הֶעָרִיס ד' אַמּוֹת וְאַחַר כָּךְ יִזְרַע, כְּדֶרֶךְ שֶׁמַּרְחִיק מִן הַכֶּרֶם. וּמֵהֵיכָן מוֹדְדִין מֵעִקַּר הַגָּדֵר שֶׁעֵרְסָן עָלָיו.\nכֵּיצַד, הִרְחִיק אֶת הַשּׁוּרָה שֶׁל גְּפָנִים מִן הַכֹּתֶל, אַמָּה, וְנִמְצָא הֶעָרִיס מִן הַגְּפָנִים וְלַכֹּתֶל, מוֹדֵד מִן הַכֹּתֶל ד' אַמּוֹת וְזוֹרֵעַ, וְנִמְצָא בֵּין הַזֶּרַע וּבֵין עִקְּרֵי הַגְּפָנִים חָמֵשׁ אַמּוֹת. וְאִם בָּא לִזְרֹעַ מִצַּד הַגְּפָנִים, מַרְחִיק מֵעִקְּרֵי הַגְּפָנִים ד' אַמּוֹת, שֶׁנִּמְצָא רָחוֹק מִן הַכֹּתֶל ה' אַמּוֹת. וְעַל דֶּרֶךְ זוֹ דָּנִין בְּכָל עָרִיס.\nאֶחָד הַבּוֹנֶה אֶת הַגָּדֵר וְאַחַר כָּךְ נָטַע, אוֹ שֶׁנָּטַע וְאַחַר כָּךְ עָשָׂה אֶת הַגָּדֵר, הוֹאִיל וְעֵרְסָן, הֲרֵי זֶה עָרִיס. נֶהֱרַס הַגָּדֵר, אוֹ נִסְתַּם הֶחָרִיץ, אֵין כָּאן עָרִיס, אֶלָּא הֲרֵי כָּל הַשּׁוּרָה כִּגְפָנִים יְחִידִים.\nעָרִיס שֶׁחָרַב אֶמְצָעוֹ, וְנִשְׁתַּיְּרוּ בּוֹ ה' גְּפָנִים בְּצַד הַגָּדֵר מִכָּאן וְה' גְּפָנִים בְּצַד הַגָּדֵר הָאַחֵר מִכְּנֶגְדָּן, זֶהוּ הַנִּקְרָא פִּסְקֵי עָרִיס; אִם יֵשׁ בֵּינֵיהֶם ח' אַמּוֹת וְאֶחָד מִס' בְּאַמָּה, הֲרֵי זֶה מַרְחִיק מִכָּל שׁוּרָה ו' טְפָחִים וְזוֹרֵעַ, וְהוּא שֶׁלֹּא יִזְרַע תַּחַת הָאֶפִּיפִירוֹת. הָיָה בֵּינֵיהֶם ח' אַמּוֹת בְּצִמְצוּם, הֲרֵי זֶה לֹא יִזְרַע לְשָׁם; וְאִם זָרַע, הוֹאִיל וְהִרְחִיק מִכָּל שׁוּרָה ו' טְפָחִים, הֲרֵי זֶה לֹא קִדֵּשׁ. וְאִם אֵין שָׁם גָּדֵר, מַרְחִיק מִכָּל שׁוּרָה ו' טְפָחִים וְזוֹרֵעַ, שֶׁאֵין כָּאן לֹא עָרִיס וְלֹא פִּסְקֵי עָרִיס. חָזַר וּבָנָה הַגָּדֵר, חָזַר הֶעָרִיס לִמְקוֹמוֹ וְחָזְרוּ פִּסְקֵי עָרִיס לִמְקוֹמָן.\nגִּנָּה קְטַנָּה שֶׁהִיא מֻקֶּפֶת גָּדֵר, וְעֵרַס אֶת הַגְּפָנִים סָבִיב לָהּ מִבַּחוּץ עַל כָּל כְּתָלֶיהָ, אִם יֵשׁ בָּהּ מְלֹא בּוֹצֵר וְסַלּוֹ מִכָּאן וּמְלֹא בּוֹצֵר וְסַלּוֹ מִכָּאן, הוֹאִיל וְהִיא מֻקֶּפֶת גָּדֵר, זוֹרְעִים בְּתוֹכָהּ יְרָקוֹת. וְאִם אֵין בָּהּ כַּשִּׁעוּר הַזֶּה, אֵין זוֹרְעִין בְּתוֹכָהּ, מִפְּנֵי שֶׁנִּרְאֶה הַכֹּל כְּעָרִיס אֶחָד וְיָרָק בְּתוֹכוֹ.\nגְּפָנִים שֶׁהָיוּ זְרוּעִים בְּמַדְרֵגָה גְּבוֹהָה וְהֶעָרִיס שֶׁלָּהֶן יוֹצֵא וּמְסַכֵּךְ עַל הַשָּׂדֶה, אִם עוֹמֵד בָּאָרֶץ וּבוֹצֵר אֶת כֻּלּוֹ, רוֹאִין כָּל הַמָּקוֹם שֶׁתַּחַת הֶעָרִיס כְּאִלּוּ הוּא מְקוֹם עִקְּרֵי הַגְּפָנִים, וְאוֹסֵר ד' אַמּוֹת בַּשָּׂדֶה לְכָל רוּחַ מִשְּׂפַת הֶעָרִיס. וְאִם אֵינוֹ יָכוֹל לִבְצֹר עַד שֶׁיַּעֲלֶה בְּמַדְרֵגָה אוֹ בְּסֻלָּם, אֵין אָסוּר לִזְרֹעַ אֶלָּא תַּחַת הֶעָרִיס בִּלְבַד.\nשְׁנֵי כְּתָלִים הַסְמוּכִים זֶה לָזֶה וְהַגְּפָנִים נְטוּעִים בַּזָּוִיּוֹת בֵּינֵיהֶם, וְהֶעָרִיס יוֹצֵא עִם הַכְּתָלִים מִתּוֹךְ הַקֶּרֶן וְכָלֶה, מַרְחִיק מֵעִקְּרֵי הַגְּפָנִים כַּשִּׁעוּר, וְזוֹרֵעַ בַּמָּקוֹם הַכָּלֶה שֶׁאֵין עָלָיו עָרִיס. וְאַף עַל פִּי שֶׁהַזֶּרַע מְכֻוָּן בֵּין שְׁנֵי הַכְּתָלִים שֶׁבֵּינֵיהֶם הֶעָרִיס, הוֹאִיל וְהִרְחִיק כַּשִּׁעוּר, הֲרֵי זֶה זוֹרֵעַ בֵּין הַכְּתָלִים.\nגֶּפֶן שֶׁעָלָה הָעֵץ שֶׁלָּהּ מִן הָאָרֶץ מְעַט, וְאַחַר כָּךְ נֶעֱקַם וְנִמְשַׁךְ עַל הָאָרֶץ וְחָזַר וְעָלָה כְּמוֹ אַרְכֻּבָּה \u0005(פי' כַּרְעָא דְּאָדָם דְּדָמֵי לְנוּ\"ן כְּפוּפָה)\u0006, כְּשֶׁמּוֹדְדִין בֵּין הַזֶּרַע וּבֵין הַגֶּפֶן שִׁשָּׁה טְפָחִים אוֹ אַרְבַּע אַמּוֹת, אֵין מוֹדְדִין אֶלָּא מִסוֹף הָאַרְכֻּבָּה, וְלֹא מֵעִקַּר הַגֶּפֶן הָרִאשׁוֹן.\nכְּבַר נִתְבָּאֵר שֶׁאַף עַל פִּי שֶׁמַּרְחִיק בֵּין הַזֶּרַע וּבֵין הַגֶּפֶן כַּשִּׁעוּר, צָרִיךְ לְהִזָּהֵר שֶׁלֹּא תְּסַכֵּךְ הַגֶּפֶן עַל הַיָּרָק אוֹ הַיָּרָק עַל הַגֶּפֶן.\nזָרַע יָרָק אוֹ תְּבוּאָה, וְצָמְחָה, וְאַחַר כָּךְ סִכֵּךְ עָלֶיהָ אֶת הַגֶּפֶן, הַקַּשִּׁין מֻתָּרִים וְהַדָּגָן יִדָּלֵק.\nהָיוּ שָׁרְשֵׁי הַגֶּפֶן יוֹצְאִים לְתוֹךְ הַד' אַמּוֹת שֶׁבֵּין הַכֶּרֶם וְהַתְּבוּאָה, יַעֲקֹר. הָיוּ שָׁרְשֵׁי הַתְּבוּאָה יוֹצְאִים לְתוֹךְ הַד' אַמּוֹת, מֻתָּר.\nכָּל הַהַרְחָקוֹת וְהַשִּׁעוּרִים הָאֲמוּרִים בְּכִלְאַיִם, בְּאַמָּה בַּת ו' טְפָחִים שׂוֹחֲקוֹת.\nכָּל הַשִּׁעוּרִים הָאֵלּוּ שֶׁמַּרְחִיקִים בֵּין הַגְּפָנִים וְהַתְּבוּאָה אוֹ הַיָּרָק, אֵינָם אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל אוֹ בְּסוּרְיָא. אֲבָל בְּחוּץ לָאָרֶץ, מֻתָּר לִזְרֹעַ בְּצַד הַגְּפָנִים בְּתוֹךְ הַכֶּרֶם, לְכַתְּחִלָּה. וְלֹא אָסְרוּ בְּחוּץ לָאָרֶץ אֶלָּא לִזְרֹעַ שְׁנֵי מִינֵי יָרָק אוֹ תְּבוּאָה עִם הַחַרְצָן בְּמַפֹּלֶת יָד. וְאִם \u0010c6\u0011 אָמַר לְתִינוֹק עוֹבֵד כּוֹכָבִים לִזְרֹעַ לוֹ בְּחוּץ לָאָרֶץ, מֻתָּר. אֲבָל לֹא יֹאמַר לְעוֹבֵד כּוֹכָבִים גָּדוֹל, שֶׁלֹּא יִתְחַלֵּף בְּיִשְׂרָאֵל. וְאַף עַל פִּי שֶׁמֻּתָּר לִזְרֹעַ הַיָּרָק בְּצַד הַכֶּרֶם בְּחוּצָה לָאָרֶץ, הֲרֵי אוֹתוֹ הַיָּרָק הַזָּרוּעַ שָׁם אָסוּר בַּאֲכִילָה, וַאֲפִלּוּ בְּחוּצָה לָאָרֶץ, וְהוּא שֶׁיִּרְאֶה אוֹתוֹ לוֹקֵט וּמוֹכֵר, אֲבָל סְפֵקוֹ מֻתָּר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהוֹאִיל וּמֻתָּר לִזְרֹעַ יָרָק בְּצַד הַגְּפָנִים בְּחוּץ לָאָרֶץ, מֻתָּר לֶאֱכֹל אוֹתוֹ יָרַק גַּם כֵּן (הַגָּהוֹת מַיְמוֹנִי פ\"י מֵהִלְכוֹת מ\"א ותה\"ד סִימָן קצ\"ד)\u0006. וְאֵין לָחוּשׁ אֶלָּא בְּמָקוֹם דְּאִכָּא לְמֵיחַשׁ שֶׁנִּזְרַע ב' מִינֵי יָרָק אוֹ ב' מִינֵי תְּבוּאָה עִם חַרְצָן בְּמַפֹּלֶת יָד \u0005(מָרְדְּכַי פֶּרֶק קַמָּא דְּקִדּוּשִׁין)\u0006 ; וְעַל כֵּן נָהֲגוּ לְהָקֵל בִּמְדִינוֹת אֵלּוּ בִּירָקוֹת הַנִּמְצָאִים זְרוּעוֹת בַּכְּרָמִים, כִּי לֹא שָׁכִיחַ שֶׁנִּזְרְעוּ בְּאִסּוּר.",[],["\u0003הרואה. \u0004 כתב הט\"ז דהטעם הוא משום קנס והיינו כשיש לו רשות לילך לכרם חבירו ואין מקפיד עליו דאז הוי כפועל ומשמע דאיירי ג\"כ במי שיש בידו לעקור או לקיימו עכ\"ל:","\u0003הקור. \u0004 כלומר שלא יבשה לגמרי וכ\"פ הרמב\"ם בפירוש המשנה:","\u0003בערב. \u0004 פי' שם מדינה:","\u0003מרובעות. \u0004 כ' הט\"ז דאלו מרובעות יש גפנים בזויות הריבוע נוסף על העיגול והם יותר על שיעור ט\"ז מן הירק שזרע בכרם שהוא מלא גפנים ואנן קי\"ל שאין האיסור מתפשט אלא עד ט\"ז אמה מן המקום שזרע שם הירק עכ\"ל:","\u0003מחול.. \u0004 \u0005(ר\"ל שדרך הבעלים למחול ולעזוב אותו בלא גפנים)\u0006 כ' הט\"ז הטעם בזה דבעינן י\"ב אמה לפי שד' אמות שייכים לעבודת הכרם וד' אמות שאצל הכרם שייכים לכותל שמניחים שם כדי לילך שם ולהחזיק הכותל ע\"י הליכה ע\"כ צריך שיהיה נשאר ד' אמות מקום חשוב לזרע והא דלא בעינן ח' אמות בנתיים כדלעיל לפי שאין כאן גפנים רק מצד אחד עכ\"ל:","\u0003שומירה. \u0004 הוא מקום גבוה שעומד שם הצופה לשמור הכרם. ט\"ז:","\u0003אמר. \u0004 כתב הט\"ז דהוא הדין לכתחילה מותר לומר כן דהא מדרבנן נינהו בחוץ לארץ ולא דמי לסירוס דאסור לעשות ע\"י עובד כוכבים כמ\"ש בא\"ע סימן כ' דהתם איסור דאורייתא הוא וע\"ל בסימן רצ\"ז סעיף ב' *): *) \u0003 ועיין בהגר\"א שיש להחמיר בזה \u0004"]],["הַזּוֹרֵעַ שְׁנֵי מִינֵי זְרָעִים כְּאֶחָד בְּאֶרֶץ יִשְׂרָאֵל, לוֹקֶה, שֶׁנֶּאֱמַר: שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם \u0005(וַיִּקְרָא יט, יט)\u0006 וְאֶחָד הַזּוֹרֵעַ \u0005(אוֹ הַמְּנַכֵּשׁ)\u0006 אוֹ הַמְּחַפֶּה, כְּגוֹן שֶׁהָיְתָה חִטָּה אַחַת וּשְׂעוֹרָה אַחַת, אוֹ פּוֹל אֶחָד וַעֲדָשָׁה אַחַת מֻנָּחִים עַל הָאָרֶץ וְחִפָּה אוֹתָם בְּעָפָר בֵּין בְּיָדוֹ בֵּין בְּרַגְלוֹ, לוֹקֶה. וְאֶחָד הַזּוֹרֵעַ בָּאָרֶץ אוֹ בְּעָצִיץ נָקוּב. אֲבָל הַזּוֹרֵעַ בְּעָצִיץ שֶׁאֵינוֹ נָקוּב, מַכִּין אוֹתוֹ מַכַּת מַרְדוּת.\nאָסוּר לִזְרֹעַ כִּלְאַיִם לְעוֹבֵד כּוֹכָבִים, וּמֻתָּר לוֹמַר לְעוֹבֵד כּוֹכָבִים לִזְרֹעַ לוֹ כִּלְאֵי זְרָעִים, וְאָסוּר לְקַיֵּם בְּשָׂדֵהוּ, אֶלָּא עוֹקְרָן. וְאִם קִיְּמָן, אֵינוֹ לוֹקֶה. וּמֻתָּר לְיִשְׂרָאֵל לִזְרֹעַ כִּלְאֵי זְרָעִים, בְּיָדוֹ, בְּחוּץ לָאָרֶץ, וַאֲפִלּוּ לְעָרֵב הַזְּרָעִים לְכַתְּחִלָּה וּלְזָרְעָם בְּחוּץ לָאָרֶץ, מֻתָּר. וּדְבָרִים אֵלּוּ דִּבְרֵי קַבָּלָה.\nאֵין אָסוּר מִשּׁוּם כִּלְאֵי זְרָעִים אֶלָּא הַזְּרָעִים הָרְאוּיִין לְמַאֲכַל אָדָם, אֲבָל עֲשָׂבִים הַמָּרִים וְכַיּוֹצֵא בָהֶם, מִן הָעִקָּרִים שֶׁאֵינָם רְאוּיִים אֶלָּא לִרְפוּאָה וְכַיּוֹצֵא בָהֶן, אֵין בָּהֶן מִשּׁוּם כִּלְאֵי זְרָעִים. הַזֵּרְעוֹנִים מִתְחַלְּקִים לְג' חֲלָקִים, הָאֶחָד נִקְרָא תְּבוּאָה וְהֵם חֲמֵשֶׁת מִינֵי דָּגָן. וְהַשֵּׁנִי נִקְרָא קִטְנִית, כְּגוֹן הַפּוֹל וְהָאֲפוּנִים וְהָעֲדָשִׁים וְהָאֹרֶז וְהַדֹּחַן וְהַשֻּׁמְשְׁמִין וְהַפַּרְגִין וְהַסַפִּיר \u0005(פי' כְּעֵין רִמּוֹן מָלֵא זְרָעִים פשאור\"ו בְּלַעַז וּפֵרוּשׁ סַפִּיר מִין קָטְנִית ציצירק\"ל בְּלַעַ\"ז)\u0006 וְכַיּוֹצֵא בָּהֶן, וְהַג' נִקְרָא זֵרְעוֹנֵי גִּנָּה, וְהֵם שְׁאָר זְרָעִים שֶׁאֵינָם רְאוּיִים לְמַאֲכַל אָדָם, וְהַפְּרִי שֶׁל אוֹתוֹ הַזֶּרַע מַאֲכַל אָדָם, כְּגוֹן זֶרַע הַבְּצָלִים וְהַשּׁוּמִין וְזֶרַע הֶחָצִיר וְזֶרַע לֶפֶת וְכַיּוֹצֵא בָּהֶן. וְזֶרַע הַפִּשְׁתָּן הֲרֵי הוּא בִּכְלַל זֵרְעוֹנֵי גִּנָּה.\nכְּשֶׁיִּזְרְעוּ כָּל מִינֵי זֵרְעוֹנִים אֵלּוּ וְיִצְמְחוּ, נִקְרָא הַצֶּמַח כֻּלּוֹ, כָּל זְמַן שֶׁלֹּא נִכָּר הַזֶּרַע, דֶּשֶׁא, וְנִקְרָא יָרָק. וְיֵשׁ מִזֶּרְעוֹנֵי גִּנָּה זֶרְעוֹנִים שֶׁדַּרְכָּן לִזְרֹעַ מֵהֶם שָׂדוֹת, כְּגוֹן הַפִּשְׁתָּן וְהַחַרְדָּל, וְאֵלּוּ נִקְרָאִים מִינֵי זְרָעִים. וְיֵשׁ מִזֵּרְעוֹנֵי גִּנָּה זְרָעִים שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶם אֶלָּא עֲרוּגוֹת עֲרוּגוֹת קְטַנּוֹת, כְּגוֹן הַלֶּפֶת וְהַצְּנוֹן וְהַתְּרָדִים וְהַבְּצָלִים וְהַכֻּסְבָּר \u0005(פי' כְּזֶרַע גָד (שְׁמוֹת טז, לא, בְּמִדְבָּר יא, ז)\u0006 ת\"י כֻּסְבָּרָא חֵיוַר קוליאנדר\"ו בְּלַעַ\"ז) וְהַכַּרְפַּס וְהַמָּרוֹר וְכַיּוֹצֵא בָּהֶם, וְאֵלּוּ נִקְרָאִים מִינֵי יְרָקוֹת.\nזֶרַע שֶׁנִּתְעָרֵב בּוֹ זֶרַע אַחֵר, אִם הָיָה אֶחָד מִכ\"ד, כְּגוֹן סְאָה שֶׁל חִטִּים שֶׁנִּתְעָרְבָה בְּכ\"ג סְאָה שֶׁל שְׂעוֹרִים, הֲרֵי זֶה אָסוּר לִזְרֹעַ אֶת הַמְעֹרָב עַד שֶׁיְּמַעֵט אֶת הַחִטִּים אוֹ יוֹסִיף עַל הַשְּׂעוֹרִים, וְאִם זָרַע לוֹקֶה. וְכָל שֶׁהוּא כִּלְאַיִם עִם הַזֶּרַע, מִצְטָרֵף לְאֶחָד מִכ\"ד. כֵּיצַד, כ\"ג סְאָה שֶׁל חִטִּים שֶׁנִּתְעָרְבוּ בָּם שְׁנֵי קַבִּין שְׂעוֹרִים וּשְׁנֵי קַבִּין עֲדָשִׁים וּשְׁנֵי קַבִּין פּוֹלִין, הֲרֵי זֶה לֹא יִזְרַע הַכֹּל עַד שֶׁיְּמַעֵט סְאָה שֶׁל תַּעֲרוֹבוֹת וְיָבֹר מִקְצָתָהּ אוֹ יוֹסִיף עַל הַחִטִּים, שֶׁהַשְּׂעוֹרִים וְהָעֲדָשִׁים וְהַפּוֹל כֻּלָּם כִּלְאַיִם עִם הַחִטִּים.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּתְעָרְבוּ מִינֵי תְּבוּאָה זֶה בָּזֶה, אוֹ מִינֵי קִטְנִיּוֹת זֶה בָּזֶה, אוֹ שֶׁנִּתְעָרְבָה תְּבוּאָה בְּקִטְנִיּוֹת אוֹ קִטְנִיּוֹת בִּתְבוּאָה. אֲבָל זֵרְעוֹנֵי גִּנָּה שֶׁנִּתְעָרֵב אֶחָד מֵהֶם בִּתְבוּאָה אוֹ בְּקִטְנִיּוֹת, שִׁעוּרָן אֶחָד מִכ\"ד מִמַּה שֶּׁזּוֹרְעִין בְּבֵית סְאָה מֵאוֹתוֹ הַמִּין, אִם נִתְעָרֵב בִּסְאָה שֶׁל תְּבוּאָה אוֹ קִטְנִיּוֹת, לֹא יִזְרַע עַד שֶׁיְּמַעֵט אוֹ יוֹסִיף עַל הַתְּבוּאָה. כֵּיצַד, חַרְדָּל שֶׁנִּתְעָרֵב בִּתְבוּאָה וַהֲרֵי הַחַרְדָּל זוֹרְעִים מִמֶּנּוּ קַב בְּכָל בֵּית סְאָה, אִם נִתְעָרֵב מִמֶּנּוּ אֶחָד מִכ\"ד מִן הַקַּב בִּסְאָה שֶׁל תְּבוּאָה אוֹ שֶׁל קִטְנִיּוֹת, חַיָּב לְמַעֵט, וְכֵן אִם הָיָה מִין זֶה מִזֵּרְעוֹנֵי גִּנָּה, זוֹרְעִים מִמֶּנּוּ סָאתַיִם בְּכָל בֵּית סְאָה, וְאִם נִתְעָרֵב מִמֶּנּוּ חֲצִי קַב בְּכָל סְאָה שֶׁל תְּבוּאָה אוֹ שֶׁל קִטְנִיּוֹת יְמַעֵט. לְפִיכָךְ תְּבוּאָה שֶׁנִּתְעָרֵב בָּהּ זֶרַע פִּשְׁתָּן, אִם הָיָה שְׁלֹשָׁה רְבִיעִיּוֹת בְּכָל סְאָה, הֲרֵי זֶה יְמַעֵט, וְאִם לָאו אֵינוֹ צָרִיךְ לְמַעֵט, לְפִי שֶׁבֵּית סְאָה זוֹרְעִין בּוֹ שְׁלֹשָׁה סְאִין זֶרַע פִּשְׁתָּן, וְעַל דֶּרֶךְ זֶה מְשַׁעֲרִים בְּכָל הַזְּרָעִים הָאֲחֵרִים.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁלֹּא נִתְכַּוֵּן לְעָרֵב וּבְשֶׁלֹּא נִתְכַּוֵּן לִזְרֹעַ הַב' מִינִים שֶׁנִּתְעָרְבוּ, אֲבָל אִם \u0010c0\u0011 נִתְכַּוֵּן לְעָרֵב זֶרַע בְּזֶרַע אַחֵר, אוֹ לִזְרֹעַ הַב' מִינִים, אֲפִלּוּ הָיְתָה חִטָּה אַחַת בְּתוֹךְ כֶּרִי שֶׁל שְׂעוֹרִים אָסוּר לְזָרְעָהּ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהַזּוֹרֵעַ מִין מִן הַמִּינִים, וּכְשֶׁצָּמַח רָאָה בּוֹ כִּלְאַיִם, אוֹ הָיָה הַמִּין הָאַחֵר אֶחָד מִכ\"ד בַּשָּׂדֶה, הֲרֵי זֶה יְלַקֵּט עַד שֶׁיְּמַעֲטֶנּוּ, \u0010c1\u0011 מִפְּנֵי מַרְאִית הָעַיִן, שֶׁמָּא יֹאמְרוּ: כִּלְאַיִם זָרַע בְּכַוָּנָה, בֵּין שֶׁהָיָה הַמִּין הָאַחֵר שֶׁצָּמַח תְּבוּאָה וְקִטְנִיּוֹת בִּתְבוּאָה \u0005(וְקִטְנִיּוֹת)\u0006, אוֹ זֵרְעוֹנֵי גִּנָּה בִּתְבוּאָה וְקִטְנִיּוֹת וּבְזֵרְעוֹנֵי גִּנָּה. וְאִם הָיָה הַצּוֹמֵחַ פָּחוֹת מִכָּאן, אֵינוֹ צָרִיךְ לְמַעֲטוֹ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּזְמַן שֶׁיֵּשׁ מָקוֹם לַחֲשָׁד. אֲבָל בִּזְמַן שֶׁהַדְּבָרִים מַרְאִים שֶׁאֵין זֶה מִדַּעְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה, אֶלָּא מֵאֲלֵיהֶם עָלוּ, אֵין מְחַיְּבִים אוֹתוֹ לְמַעֵט. כֵּיצַד, כְּגוֹן תְּבוּאָה שֶׁעָלוּ בָּהּ סְפִיחֵי אִסְטִיס \u0005(פֵּרוּשׁ מִין זֶרַע שֶׁצוֹבְעִין)\u0006, וְתִלְתָּן שֶׁזְּרָעָם לְמַאֲכַל אָדָם, שֶׁעָלוּ בָּהּ מִינֵי עֲשָׂבִים, שֶׁזֶּה מַפְסִיד הוּא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וּבַמֶּה יוֹדֵעַ שֶׁהַתִּלְתָּן זְרוּעָה לְמַאֲכַל אָדָם, כְּשֶׁהָיְתָה זְרוּעָה עֲרוּגוֹת עֲרוּגוֹת וְלָהּ גְּבוּל סָבִיב, וְכֵן מְקוֹם הַגְּרָנוֹת שֶׁעָלוּ בָּהּ מִינִים הַרְבֵּה, אֵין מְחַיְּבִין אוֹתָן לַעֲקֹר, שֶׁהֲרֵי הַדָּבָר יָדוּעַ שֶׁאֵינוֹ רוֹצֶה שֶׁיִּצְמַח צֶמַח בִּמְקוֹם הַגְּרָנוֹת. וְאִם הֵסִיר מִקְּצָתָן, אוֹמְרִים לוֹ: עֲקֹר הַכֹּל חוּץ מִמִּין אֶחָד, שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁרוֹצֶה בְּקִיּוּם הַשְּׁאָר.\nאֵין נוֹטְעִין יְרָקוֹת בְּתוֹךְ סַדָּן שֶׁל שִׁקְמָה \u0005(פֵּרוּשׁ סַדָּן, אִילָן שֶׁנִּקְצַץ וְנִשְׁאַר שָׁרָשָׁיו בָּאָרֶץ, וְשִׁקְמָה מִין תְּאֵנָה יְעָרִית)\u0006 וְכַיּוֹצֵא בָּזֶה.\nהַטּוֹמֵן אֲגוּדוֹת לֶפֶת וּצְנוֹן וְכַיּוֹצֵא בָּהּ תַּחַת הָאִילָן, אֲפִלּוּ תַּחַת הַגֶּפֶן, אִם הָיוּ מִקְצָת הֶעָלִים מְגֻלִּים אֵינוֹ חוֹשֵׁשׁ, שֶׁהֲרֵי אֵינוֹ רוֹצֶה בְּהַשְׁרָשָׁתָן. וְאִם אֵינָם אֲגֻדָּה, אוֹ שֶׁלֹּא הָיוּ הֶעָלִין מְגֻלִּין, חוֹשֵׁשׁ מִשּׁוּם כִּלְאַיִם.\nשָׂדֶה שֶׁהָיְתָה זְרוּעָה וְקָצַר הַזֶּרַע וְנִשְׁאֲרוּ הָעִקָּרִין בָּאָרֶץ, אַף עַל פִּי שֶׁאֵין מוֹצִיאִין צֶמַח אֶלָּא אַחַר כַּמָּה שָׁנִים, לֹא יִהְיֶה זוֹרֵעַ בְּאוֹתָהּ שָׂדֶה מִין אַחֵר עַד שֶׁיַּעֲקֹר הָעִקָּרִין.\nהָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים, וְנִמְלַךְ לְזָרְעָהּ שְׂעוֹרִים קֹדֶם שֶׁיִּצְמְחוּ הַחִטִּין, יַמְתִּין לָהּ עַד שֶׁיִּפָּסְדוּ וְיַתְלִיעוּ בָּאָרֶץ כְּמוֹ ג' יָמִים, אִם הָיְתָה שָׂדֵהוּ רָוָה, וְאַחַר כָּךְ יַהַפְכֵם בְּמַחֲרֵשָׁה וְיִזְרַע הַמִּין הָאַחֵר. וְאֵינוֹ צָרִיךְ לַהֲפֹךְ אֶת כֻּלָּהּ עַד שֶׁלֹּא תִּשָּׁאֵר חִטָּה שֶׁלֹּא נֶעֶקְרָה, אֶלָּא חוֹרֵשׁ הַשָּׂדֶה כְּדֶרֶךְ שֶׁחוֹרְשִׁין אוֹתָם קֹדֶם הַמָּטָר כְּדֵי שֶׁתִּרְוֶה. צָמְחוּ הַחִטִּים וְאַחַר כָּךְ נִמְלַךְ לְזָרְעָהּ שְׂעוֹרִים, יַהֲפֹךְ וְאַחַר כָּךְ יִזְרָעֵם. וְאִם הוֹרִיד בְּהֶמְתּוֹ לְתוֹכוֹ וְקִרְסְמָה אֶת הַצֶּמַח, הֲרֵי זֶה מֻתָּר לִזְרֹעַ מִין אַחֵר.\nיֵשׁ מִינִים בַּזְּרָעִים שֶׁיִּהְיֶה הַמִּין הָאֶחָד נִפְרָד לְצוּרוֹת הַרְבֵּה מִפְּנֵי שִׁנּוּי הַמְּקוֹמוֹת וְהָעֲבוֹדָה שֶׁעוֹבְדִים הָאָרֶץ, עַד שֶׁיֵּרָאֶה כִּשְׁנֵי מִינִים. וְאַף עַל פִּי שֶׁאֵין דּוֹמִין זֶה לָזֶה, הוֹאִיל וְהֵם מִין אֶחָד אֵינָם כִּלְאַיִם זֶה בָּזֶה. וְיֵשׁ בַּזְּרָעִים שְׁנֵי מִינִים שֶׁהֵם דּוֹמִין זֶה לָזֶה וְצוּרַת שְׁנֵיהֶם קְרוֹבָה לִהְיוֹת צוּרָה אַחַת, וְאַף עַל פִּי כֵן הוֹאִיל וְהֵם שְׁנֵי מִינִים הֲרֵי אֵלּוּ אֲסוּרִים זֶה עִם זֶה. כֵּיצַד, הַחֲזֶרֶת עִם חֲזֶרֶת גַּלִּים, וְהָעֻלָּשִׁים עִם עֻלְשֵׁי שָׂדֶה, וְהַכְּרֵישִׁין עִם כְּרֵישֵׁי שָׂדֶה, וְהַכֻּסְבָּר עִם כֻּסְבַּר הָרִים, וְהַחַרְדָּל עִם חַרְדָּל מִצְרִי. וּדְלַעַת מִצְרִית עִם דְּלַעַת הָרְמוּצָה \u0005(פי' מִין דְּלַעַת מַר שֶׁמְּמַתְּקִין אוֹתָהּ בְּרֶמֶץ שֶׁהוּא אֵפֶר חַם)\u0006 אֵינָם כִּלְאַיִם זֶה בָּזֶה. וְכֵן הַחִטִּים עִם הַזּוּנִין, וְהַשְּׂעוֹרִים עִם שִׁבֹּלֶת שׁוּעָל, וְהַכֻּסְמִין עִם הַשִּׁיפוֹן. הַפּוֹל עִם הַסַפִּיר, וְהַפֻּרְקְדָן עִם הַטֹּפַח \u0005(פי' פֻּרְקְדָן וְטֹפַח מִינֵי זֵרְעוֹנִים דַּקִים וּשְׁעוֹעוֹת, בְּעַרְבִי לנביא\"ה וּמְלָפְפוֹן, פי' בַּיְרוּשַׁלְמִי פְּרִי הַבָּא מִן הָאֲבַטִּיחַ וְהַקִשּׁוּת אוֹ מֵהָאֲבַטִּיחַ וְהַטֹּפַח וְיֵשׁ אוֹמְרִים שֶׁהוּא הַפְּרִי הַנִּקְרָא בְּלַעַ\"ז ציטרול\"ו וְהַתְּרוֹבְדוֹר, הוּא מִין כְּרוּב שֶׁעָלָיו קְטַנִּים, וְהַתְּרָדִין הֵם מִין יָרָק בוליט\"י בְּלַעַ\"ז, וְהַלְּעוֹנִים, הֵם מִמִּין הַתְּרָדִין, וְהַנָּפוּסִים, הֵם מִין צְנוֹן, וְהַלִּפְתָּן פי' הֶעָרוּךְ מארוי\"ו בְּלַעַ\"ז)\u0006 וּפוֹל הַלָּבָן עִם הַשְּׁעוּעִית, וְהַקִּשּׁוּת עִם הַמְּלָפְפוֹן, וְהַכְּרוּב עִם הַתְּרוֹבְדוֹר, וְהַתְּרָדִים עִם הַלְּעוֹנִים, אֵינָם כִּלְאַיִם זֶה בָּזֶה. אֲבָל הַצְּנוֹן עִם הַנָּפוּסִים, וְהַחַרְדָּל עִם הַלַּפְסָן, וּדְלַעַת יְוָנִית עִם דְּלַעַת מִצְרִית אוֹ עִם דְּלַעַת הָרְמוּצָה, אַף עַל פִּי שֶׁדּוֹמִים זֶה לָזֶה הֲרֵי אֵלּוּ כִּלְאַיִם זֶה בָּזֶה. וְכֵן בְּאִילָן, שֶׁיֵּשׁ שְׁנֵי מִינִים שֶׁדּוֹמִים זֶה לָזֶה בְּעָלִין אוֹ בְּפֵרוֹת, הוֹאִיל וְהֵם שְׁנֵי מִינִים הֲרֵי אֵלּוּ כִּלְאַיִם, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן רצ\"ה.\nיֵשׁ זְרָעִים וְאִילָנוֹת אֲחֵרִים, אַף עַל פִּי שֶׁהֵם שְׁנֵי מִינִים בְּטִבְעָם הוֹאִיל וְעָלִין שֶׁל זֶה דּוֹמִין לְעָלִין שֶׁל זֶה, אוֹ פְּרִי שֶׁל זֶה דּוֹמֶה לִפְרִי שֶׁל זֶה דִּמְיוֹן גָּדוֹל עַד שֶׁיֵּרָאֶה כִּשְׁנֵי גְּוָנִים מִמִּין אֶחָד, לֹא חָשְׁשׁוּ לָהֶם לְכִלְאַיִם זֶה עִם זֶה. כֵּיצַד, הַלֶּפֶת עִם הַצְּנוֹן אֵינָם כִּלְאַיִם זֶה בָּזֶה, מִפְּנֵי שֶׁפִּרְיֵהֶן שָׁוִים. וְהַלֶּפֶת עִם הַנָּפוּס אֵינָם כִּלְאַיִם זֶה בָּזֶה, מִפְּנֵי שֶׁהֶעָלִים שָׁוִים. אֲבָל צְנוֹן עִם הַנָּפוּס, אַף עַל פִּי שֶׁהֶעָלִים דּוֹמִים זֶה לָזֶה וְהַפְּרִי דּוֹמֶה לַפְּרִי, הֲרֵי אֵלּוּ כִּלְאַיִם, הוֹאִיל וְטַעַם פְּרִי זֶה רָחוֹק מִטַּעַם \u0005(פְּרִי)\u0006 זֶה בְּיוֹתֵר. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ.\nכַּמָּה מַרְחִיקִים בֵּין שְׁנֵי מִינֵי זְרָעִים שֶׁהֵם כִּלְאַיִם זֶה עִם זֶה, כְּדֵי שֶׁיִּהְיוּ מֻבְדָּלִים זֶה מִזֶּה. אֲבָל אִם נִרְאִים שֶׁנִּזְרְעוּ בְּעִרְבּוּבְיָא, הֲרֵי זֶה אָסוּר. וְשִׁעוּרִים רַבִּים יֵשׁ בְּהַרְחָקָה זוֹ, הַכֹּל לְפִי גֹּדֶל הַשָּׂדֶה הַנִּזְרַעַת וּלְפִי רֹב הֶעָלִין וְשִׁלּוּחַ הַיּוֹנְקוֹת. כֵּיצַד, שָׂדֵהוּ שֶׁהָיְתָה זְרוּעָה מִין תְּבוּאָה, וּבִקֵּשׁ לִזְרֹעַ בְּצִדָּהּ מִין תְּבוּאָה אַחֶרֶת בְּשָׂדֶה אַחֶרֶת, מַרְחִיק בֵּינֵיהֶם בֵּית רֹבַע, וְהוּא כְּעֶשֶׂר אַמּוֹת וְחֹמֶשׁ אַמָּה עַל עֶשֶׂר אַמּוֹת וְחֹמֶשׁ אַמָּה מְרֻבָּע, בֵּין מִן הָאֶמְצַע בֵּין מִן הַצַּד. וְאִם לֹא הָיָה בֵּינֵיהֶם כַּשִּׁעוּר הַזֶּה, אָסוּר, וְאֵינוֹ לוֹקֶה עַד שֶׁיִּהְיוּ קְרוֹבִים בְּתוֹךְ שִׁשָּׁה טְפָחִים.\nהָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק, וּבִקֵּשׁ לִזְרֹעַ בְּצִדָּהּ שְׂדֵה יָרַק אַחֵר, אֲפִלּוּ דְּלַעַת, מַרְחִיק בֵּין שְׁנֵי הַשָּׂדוֹת ו' טְפָחִים עַל ו' טְפָחִים מְרֻבָּע, בֵּין מִן הַצַּד בֵּין מִן הָאֶמְצַע. וּפָחוֹת מִשִּׁעוּר זֶה, אָסוּר, וְאֵינוֹ לוֹקֶה עַד שֶׁיִּהְיוּ קְרוֹבִים בְּתוֹךְ טֶפַח.\nהָיְתָה אַחַת מִשְּׁתֵּי הַשָּׂדוֹת זְרוּעָה תְּבוּאָה וְהַשְּׁנִיָּה שֶׁבְּצִדָּהּ יָרָק אוֹ דְּלַעַת, מַרְחִיק בֵּינֵיהֶם בֵּית רֹבַע.\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁצָּרִיךְ לְהַרְחִיק כַּשִּׁעוּרִים הָאֵלּוּ, בֵּין שְׁתֵּי שָׂדוֹת, אֲבָל אִם הָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק, וְרוֹצֶה לִזְרֹעַ בְּצִדָּהּ שׁוּרָה שֶׁל יָרָק מִמִּין אַחֵר, דַּיּוֹ לַעֲשׂוֹת בֵּין הַשָּׂדֶה וּבֵין הַשּׁוּרָה תֶּלֶם אֶחָד אָרְכּוֹ ו' טְפָחִים בִּלְבַד, וְרָחְבּוֹ כְּעֹמְקוֹ.\nהָיְתָה שָׂדֵהוּ זְרוּעָה תְּבוּאָה וְרוֹצָה לִזְרֹעַ בְּתוֹכָהּ שׁוּרָה שֶׁל יָרָק, אֲפִלּוּ שׁוּרָה שֶׁל דְּלוּעִין שֶׁהֶעָלִין שֶׁלָּהֶם אֲרֻכִּין וּמִסְתַּבְּכִין, מַרְחִיק בֵּינֵיהֶם ו' טְפָחִים. וְאִם נִמְשְׁכוּ הֶעָלִין שֶׁל דְּלַעַת וְנִכְנְסוּ לַתְּבוּאָה וְנִסְתַּבְּכוּ בָּהּ, יַעֲקֹר מִן הַתְּבוּאָה שֶׁלִּפְנֵי הַדְּלַעַת עַד שֶׁלֹּא יִתְעָרְבוּ הֶעָלִין. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם זָרַע שׁוּרָה מִמִּין זֶה וְשׁוּרָה מִמִּין אַחֵר, שֶׁדַּיּוֹ לִהְיוֹת בֵּינֵיהֶם תֶּלֶם אֶחָד \u0005(פֵּרוּשׁ בִּקְעֵי הַחֲרִישָׁה יִקָרְאוּ גְדוּדִים וְהַגָּבוֹהַּ נִקְרָא תֶּלֶם)\u0006.\nהִרְחִיק בֵּין ב' הַמִּינִים הַרְחָקָה הָרְאוּיָה לָהֶם, וְהָיָה מִין זֶה נוֹטֶה עַל גַּבֵּי מִין זֶה, בֵּין שֶׁנָּטְתָה תְּבוּאָה עַל הַתְּבוּאָה אוֹ יָרָק עַל הַתְּבוּאָה אוֹ תְּבוּאָה עַל הַיָּרָק, הַכֹּל מֻתָּר, שֶׁהֲרֵי הִרְחִיק כְּשִׁעוּר; חוּץ מִדְּלַעַת יְוָנִית שֶׁהִיא נִמְשֶׁכֶת הַרְבֵּה, לְפִיכָךְ אִם נָטְתָה יַעֲקֹר מִלְּפָנֶיהָ.\nהָיָה בֵּין שְׁנֵי הַמִּינִים בּוֹר אוֹ נִיר אוֹ גָּפָה \u0005(פֵּרוּשׁ גָּדֵר אֲבָנִים סְדוּרוֹת זוֹ עַל גַּב זוֹ בְּלֹא טִיט)\u0006 אוֹ דֶּרֶךְ אוֹ גָּדֵר שֶׁהוּא גָּבוֹהַּ עֲשָׂרָה טְפָחִים \u0005(אוֹ חָרִיץ שֶׁהוּא עָמֹק עֲשָׂרָה טְפָחִים)\u0006 וְרָחָב אַרְבָּעָה אוֹ אִילָן שֶׁהוּא מֵסֵךְ עַל הָאָרֶץ אוֹ סֶלַע שֶׁהוּא גָּבוֹהַּ י' טְפָחִים וְרָחָב אַרְבָּעָה, הֲרֵי זֶה מֻתָּר לִסְמֹךְ לְצַד א' מֵאֵלּוּ, וְהַמִּין הָאַחֵר לַצַּד הַשֵּׁנִי, הוֹאִיל וְאֶחָד מִכָּל אֵלּוּ מַבְדִּיל בֵּינֵיהֶם הֲרֵי הֵם נִרְאִים מֻבְדָּלִים זֶה מִזֶּה. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁצָּרִיךְ הַרְחָקָה אוֹ דָּבָר הַמַּבְדִּיל, כְּשֶׁזָּרַע בְּתוֹךְ שָׂדֵהוּ. אֲבָל אִם הָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים, מֻתָּר לַחֲבֵרוֹ לִזְרֹעַ בְּצִדָּהּ שְׂעוֹרִים, שֶׁנֶּאֱמַר: שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם \u0005(וַיִּקְרָא יט, יט)\u0006 אֵין הָאִסוּר אֶלָּא כְּשֶׁיִּזְרַע שָׂדֵהוּ כִּלְאַיִם, שֶׁלֹּא נֶאֱמַר: הָאָרֶץ \u0005(לֹא)\u0006 תִזְרַע כִּלְאָיִם. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ זָרַע בְּתוֹךְ שָׂדֵהוּ שְׂעוֹרִים סָמוּךְ לַחִטִּים, וּמָשַׁךְ זֶרַע שְׂעוֹרִים עַד שֶׁסְמָכוֹ לִשְׂדֵה חֲבֵרוֹ שֶׁהִיא זְרוּעָה שְׂעוֹרִים, הֲרֵי זֶה מֻתָּר, מִפְּנֵי שֶׁנִּרְאוּ הַשְּׂעוֹרִים שֶׁבְּתוֹךְ שָׂדֵהוּ שֶׁהֵם סוֹף שְׂדֵה חֲבֵרוֹ.\nהָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים, וּשְׂדֵה חֲבֵרוֹ בְּצִדָּהּ זְרוּעָה חִטִּים, מֻתָּר לוֹ לִזְרֹעַ תֶּלֶם אֶחָד שֶׁל פִּשְׁתָּן בְּצַד חִטִּים שֶׁלּוֹ הַסָמוּךְ לִשְׂדֵה חֲבֵרוֹ, שֶׁהָרוֹאֶה יוֹדֵעַ שֶׁאֵין דֶּרֶךְ לִזְרֹעַ תֶּלֶם אֶחָד שֶׁל פִּשְׁתָּן, וְלֹא נִתְכַּוֵּן זֶה אֶלָּא לִבְדֹּק שָׂדֵהוּ אִם הִיא רְאוּיָה לִזְרֹעַ פִּשְׁתָּן אִם לֹא, וְנִמְצָא כְּזוֹרֵעַ לְהַשְׁחָתָה. אֲבָל מִין אַחֵר אָסוּר לִזְרֹעַ בֵּין שְׁתֵּי שָׂדוֹת אֵלּוּ שֶׁהֵם מִמִּין אֶחָד, עַד שֶׁיַּרְחִיק בְּתוֹךְ שֶׁלּוֹ.\nהָיְתָה שָׂדֵהוּ וּשְׂדֵה חֲבֵרוֹ שֶׁבְּצִדּוֹ זְרוּעִים שְׁנֵי מִינֵי תְּבוּאָה, לֹא יִזְרַע בֵּינֵיהֶם חַרְדָּל וְחָרִיעַ, אֲפִלּוּ תֶּלֶם אֶחָד, מִפְּנֵי שֶׁהָעָם זוֹרְעִים מֵאֵלּוּ תֶּלֶם אֶחָד. אֲבָל אִם שְׁתֵּי הַשָּׂדוֹת זְרוּעִים שְׁנֵי מִינֵי יְרָקוֹת, מֻתָּר לִזְרֹעַ בֵּינֵיהֶם חַרְדָּל אוֹ חָרִיעַ, שֶׁמֻּתָּר לְהַקִּיף חַרְדָּל לְכָל מִין, חוּץ מִן הַתְּבוּאָה, מִפְּנֵי שֶׁאֵינָם מַזִּיקִים אוֹתָהּ.\nהָיְתָה זָוִית שֶׁל זֶרַע זֶה נוֹגַעַת בְּצֶלַע שֶׁל זֶרַע הָאַחֵר בְּתוֹךְ שָׂדֵהוּ, הֲרֵי זֶה מֻתָּר, מִפְּנֵי שֶׁהֵם נִרְאִים מֻבְדָּלִים זֶה מִזֶּה. וְאֵין צָרִיךְ לוֹמַר אִם הָיְתָה זָוִית שֶׁל זֶרַע נוֹגַעַת בְּזָוִית שֶׁל זֶרַע הָאֶחָד, מִפְּנֵי שֶׁהֵם נִרְאִים כְּסוֹף שָׂדֶה שֶׁהוּא מֻתָּר בְּלֹא הַרְחָקָה וּבְלֹא הַבְדָּלָה.\nמֻתָּר לִזְרֹעַ שְׁתֵּי שׁוּרוֹת זוֹ בְּצַד זוֹ שֶׁל קִשּׁוּאִין, וּשְׁתֵּי שׁוּרוֹת בְּצִדָּן שֶׁל דְּלוּעִין, וּשְׁתֵּי שׁוּרוֹת שֶׁל פּוֹל הַמִּצְרִי, וְתֶלֶם בֵּין כָּל מִין וָמִין. אֲבָל לֹא יִזְרַע שׁוּרָה אַחַת שֶׁל קִשּׁוּאִין וְשׁוּרָה אַחַת שֶׁל דְּלוּעִין וְשׁוּרָה אַחַת שֶׁל פּוֹל הַמִּצְרִי, אַף עַל פִּי שֶׁהַתֶּלֶם מַבְדִּיל בֵּין כָּל מִין וָמִין, מִפְּנֵי שֶׁמִּינִים אֵלּוּ עָלִים שֶׁלָּהֶם אֲרֻכִּים וְנִמְשָׁכִים וּמִסְתַּבְּכִים, וְאִם זְרָעָם שׁוּרָה בְּצַד שׁוּרָה יִתְעָרֵב הַכֹּל וְיֵרָאוּ כְּנִזְרָעִים בְּעִרְבּוּבְיָא.\nהָיְתָה שָׂדֵהוּ זְרוּעָה מִין מִמִּינֵי יְרָקוֹת, וּבִקֵּשׁ לִזְרֹעַ בְּתוֹכָהּ שׁוּרוֹת שׁוּרוֹת שֶׁל דְּלוּעִים, עוֹקֵר מֵהַיָּרָק מָקוֹם שֶׁזּוֹרֵעַ בּוֹ שׁוּרָה שֶׁל דְּלוּעִין, וּמַבְדִּיל בֵּינָהּ וּבֵין הַיָּרָק כְּתֶלֶם, וּמַנִּיחַ מִן הַיָּרָק רֹחַב שְׁתֵּים עֶשְׂרֵה אַמָּה, וְעוֹשֶׂה שׁוּרָה שְׁנִיָּה שֶׁל דְּלוּעִים, וּמַבְדִּיל בֵּינָהּ וּבֵין הַיָּרָק כְּתֶלֶם, וְכֵן עַד מָקוֹם שֶׁיִּרְצֶה. שֶׁנִּמְצָא בֵּין כָּל שְׁתֵּי שׁוּרוֹת שֶׁל דְּלוּעִין י\"ב אַמָּה. אֲבָל פָּחוֹת מִכָּאן, אָסוּר, מִפְּנֵי הֶעָלִין שֶׁמִּסְתַּבְּכִין מִכָּאן וּמִכָּאן בַּיָּרָק שֶׁבֵּינֵיהֶם וְנִרְאֶה הַכֹּל כְּאִלּוּ נִזְרַע בְּעִרְבּוּבְיָא.\nהָיְתָה שׁוּרָה שֶׁל דְּלַעַת זְרוּעָה, אֲפִלּוּ דְּלַעַת יְחִידִית, וּבָא לִזְרֹעַ בְּצִדָּהּ תְּבוּאָה, מַרְחִיק בֵּית רֹבַע, שֶׁהֲרֵי נִמְשְׁכוּ עָלֶיהָ וְהֶחֱזִיקָה מָקוֹם גָּדוֹל.\nכָּל דָּבָר שֶׁהָיָה בְּתוֹךְ בֵּית רֹבַע שֶׁמַּרְחִיקִין בֵּין שְׁנֵי הַמִּינִים עוֹלֶה מִן הַמִּדָּה, כְּגוֹן הַקֶּבֶר וְהַסְלָעִים וְכַיּוֹצֵא בָּהֶן.\nהַתֶּלֶם אוֹ אַמַּת הַמַּיִם שֶׁהֵם עֲמֻקִּים טֶפַח, זוֹרְעִים לְתוֹכוֹ שְׁלֹשָׁה מִינֵי זְרָעִים, אֶחָד עַל שְׂפַת הַתֶּלֶם מִכָּאן, וְאֶחָד מִכָּאן, וְאֶחָד בָּאֶמְצַע.\nמֻתָּר לִנְטֹעַ שְׁנֵי מִינִים בְּתוֹךְ גֻּמָּא אַחַת, וַאֲפִלּוּ קִשּׁוּת וּדְלַעַת, וְהוּא שֶׁיִּהְיֶה מִין זֶה נוֹטֶה מֵעַל שְׂפַת הַגֻּמָּא לְכָאן, וְהַמִּין הָאַחֵר נוֹטֶה לַצַּד הַשֵּׁנִי וְיֵרָאוּ נִבְדָּלִין זֶה מִזֶּה. וְכֵן אִם נָטַע אַרְבָּעָה מִינִים בְּתוֹךְ הַגֻּמָּא וַהֲפָכָן לְד' רוּחוֹתֶיהָ, הֲרֵי זֶה מֻתָּר.\nהָרוֹצֶה לִזְרֹעַ שָׂדֵהוּ מֵשָׁר מֵשָׁר \u0005(פי' עֲרוּגוֹת עֲרוּגוֹת)\u0006 מִכָּל מִין וָמִין, מַרְחִיק בֵּין כָּל מֵשָׁר וּמֵשָׁר שְׁתֵּי אַמּוֹת עַל שְׁתֵּי אַמּוֹת וּמֵצֵר וְהוֹלֵךְ, עַד שֶׁלֹּא יִשָּׁאֵר בֵּינֵיהֶם בְּסוֹף הַמֵּשָׁר אֶלָּא כָּל שֶׁהוּא, שֶׁהֲרֵי הֵם נִרְאִים שֶׁלֹּא נִזְרְעוּ בְּעִרְבּוּבְיָא.\nרָצָה לַעֲשׂוֹת שָׂדֵהוּ קָרַחַת קָרַחַת מִכָּל מִין וָמִין, לֹא יַעֲשֶׂה בְּתוֹךְ כָּל בֵּית סְאָה יוֹתֵר עַל תֵּשַׁע קָרָחוֹת, כָּל קָרַחַת מֵהֶן בֵּית רֹבַע, וְנִמְצָא רָחוֹק בֵּין קָרַחַת וְקָרַחַת קָרוֹב לְעֶשֶׂר אַמּוֹת פָּחוֹת רְבִיעַ, שֶׁכָּל בֵּית סְאָה חֲמִשִּׁים עַל חֲמִשִּׁים. וּמַה בֵּין הַמֵּשָׁר לַקָּרַחַת, שֶׁהַמֵּשָׁר אָרֹךְ וְהַקָּרַחַת מְרֻבַּעַת.\nמִינֵי יְרָקוֹת שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶם אֶלָּא מְעַט, מֻתָּר לִזְרֹעַ מֵהֶם אֲפִלּוּ חֲמִשָּׁה מִינִים בְּתוֹךְ עֲרוּגָה אַחַת, שֶׁהִיא שִׁשָּׁה עַל שִׁשָּׁה טְפָחִים, וְהוּא שֶׁיִּזְרַע ד' מִינִים עַל ד' רוּחוֹת הָעֲרוּגָה וְאַחַת בָּאֶמְצַע, וְיַרְחִיק בֵּין מִין וָמִין כְּמוֹ טֶפַח וּמֶחֱצָה, כְּדֵי שֶׁלֹּא יִינְקוּ זֶה מִזֶּה. אֲבָל יוֹתֵר עַל ה' מִינִים לֹא יִזְרַע, אַף עַל פִּי שֶׁמַּרְחִיק בֵּינֵיהֶם, לְפִי שֶׁמִּינִים הַרְבֵּה בַּעֲרוּגָה כָּזוֹ הֲרֵי הֵם כִּנְטוּעִים בְּעִרְבּוּבְיָא.\nבַּמֶּה דְבָרִים אֲמוּרִים, בַּעֲרוּגָה שֶׁהִיא בְּחֻרְבָה, וְאֵין שָׁם זֶרַע חוּצָה לָהּ. אֲבָל עֲרוּגָה בֵּין עֲרוּגוֹת, אָסוּר לִזְרֹעַ בָּהּ חֲמִשָּׁה מִינִים, שֶׁאִם יִזְרַע בְּכָל רוּחַ מֵעֲרוּגָה זוֹ וּבְכָל רוּחַ מֵעֲרוּגָה שֶׁסְבִיבוֹתֶיהָ, יֵרָאֶה הַכֹּל כִּמְעֹרָב. וְאִם הִטָּה עָלִין שֶׁבַּעֲרוּגָה זוֹ לְכָאן וְעָלִין שֶׁבָּעֲרוּגָה שֶׁבְּצִדָּהּ מִכָּאן עַד שֶׁיֵּרָאוּ מֻבְדָּלִין, מֻתָּר. וְכֵן אִם עָשָׂה תֶּלֶם בֵּין כָּל עֲרוּגָה וַעֲרוּגָה, מֻתָּר.\nאָסוּר לִזְרֹעַ חוּץ לָעֲרוּגָה בְּלֹא תֶּלֶם וּבְלֹא נְטִיָּה, וַאֲפִלּוּ כְּנֶגֶד הַקְּרָנוֹת שֶׁל עֲרוּגָה שֶׁאֵין בָּהּ זֶרַע, גְּזֵרָה שֶׁמָּא יִזְרַע ד' הַמִּינִים בְּד' זָוִיּוֹת הָעֲרוּגָה, וְיִזְרַע מִינִים אֲחֵרִים חוּצָה לָהּ כְּנֶגֶד הַזָּוִיּוֹת, וְנִמְצָא הַכֹּל כִּמְעֹרָב.\nהָיְתָה הָעֲרוּגָה שִׁשָּׁה עַל שִׁשָּׁה, וְהָיָה לָהּ גְּבוּל גָּבֹהַּ טֶפַח וְרָחָב טֶפַח סָבִיב, מֻתָּר לִזְרֹעַ בָּהּ אֲפִלּוּ שְׁמוֹנָה עָשָׂר מִינִים, שְׁלֹשָׁה עַל כָּל גְּבוּל וּגְבוּל וְשִׁשָּׁה בָּאֶמְצַע, וְיַרְחִיק בֵּין כָּל מִין וָמִין טֶפַח וּמֶחֱצָה. וְלֹא יִזְרַע רֹאשׁ הַלֶּפֶת בְּתוֹךְ הַגְּבוּל, שֶׁמָּא יְמַלְּאֵהוּ. יוֹתֵר עַל זֶה לֹא יִזְרַע. וְאָסוּר לִזְרֹעַ בַּעֲרוּגָה מִינֵי זְרָעִים בְּעִנְיָן זֶה, מִפְּנֵי שֶׁהֵם נִרְאִים כִּלְאַיִם. אֲבָל מִינֵי יְרָקוֹת, הוֹאִיל וְאֵין דֶּרֶךְ בְּנֵי אָדָם לִזְרֹעַ מֵהֶם אֶלָּא מְעַט מְעַט, הֲרֵי זֶה מֻתָּר, כְּמוֹ שֶׁנִּתְבָּאֵר.\nגְּבוּל שֶׁהָיָה גָּבוֹהַּ טֶפַח וְזָרְעוּ בּוֹ מִינִים הַרְבֵּה כְּמוֹ שֶׁנִּתְבָּאֵר, וְנִתְמַעֵט מִטֶּפַח, מֵאַחַר שֶׁנִּזְרַע בּוֹ, כָּשֵׁר, שֶׁהָיָה כָּשֵׁר מִתְּחִלָּתוֹ.\nהָרוֹצֶה לְמַלְּאוֹת כָּל גִּנָּתוֹ יְרָקוֹת רַבּוֹת וְלֹא יַרְחִיק בֵּינֵיהֶם, עוֹשֶׂה כָּל הַגִּנָּה עֲרוּגוֹת מְרֻבָּעוֹת, אֲפִלּוּ ו' עַל ו', וְעוֹשֶׂה בְּכָל עֲרוּגָה חֲמִשָּׁה עִגּוּלִין ד' בְּאַרְבַּע רוּחוֹתֶיהָ וְאֶחָד בָּאֶמְצַע, וְזוֹרֵעַ מִין בְּכָל עִגּוּל; וְזוֹרֵעַ ד' מִינִים אֲחֵרִים בְּד' קַרְנוֹת עֲרוּגָה, נִמְצְאוּ ט' מִינִים בְּכָל עֲרוּגָה וְהֵם נִרְאִים מֻבְדָּלִים זֶה מִזֶּה, וְאֵינוֹ מַפְסִיד אֶלָּא מַה שֶּׁבֵּין הָעִגּוּלִים בִּלְבַד שֶׁהוּא מַנִּיחוֹ חָרֵב כְּדֵי שֶׁיֵּרָאוּ הָעִגּוּלִים מֻבְדָּלִים מִן הַקְּרָנוֹת וּמֻבְדָּלִים זֶה מִזֶּה. וְאִם רָצָה שֶׁלֹּא יַפְסִיד כְּלוּם, אִם הָיוּ הָעִגּוּלִים זְרוּעִים שְׁתִי זוֹרֵעַ מַה שֶׁבֵּינֵיהֶם עֵרֶב, וְאִם הָיוּ זְרוּעִים עֵרֶב זוֹרֵעַ מַה שֶּׁבֵּינֵיהֶם שְׁתִי, כְּדֵי שֶׁיֵּרָאוּ מֻבְדָּלִים.\nמִכָּל אֵלּוּ הַדְּבָרִים נִתְבָּאֵר שֶׁבִּזְמַן שֶׁיֵּשׁ בֵּין ב' הַמִּינִים הַרְחָקָה הָרְאוּיָה לָהֶם כְּדֵי שֶׁלֹּא יִינְקוּ זֶה מִזֶּה, אֵין חוֹשְׁשִׁין לְמַרְאִית הָעַיִן. וּבִזְמַן שֶׁיֵּרָאוּ מֻבְדָּלִים זֶה מִזֶּה, אֵין חוֹשְׁשִׁין לִינִיקָתָן אֲפִלּוּ הֵם זֶה בְּצַד זֶה.\nסימן רצז \u0005(א)\u0006 - דיני הרבעת והנהגת כלאי בהמה\nהַמַּרְכִּיב זָכָר עַל נְקֵבָה שֶׁאֵינוֹ מִינוֹ, בֵּין בִּבְהֵמָה, בֵּין בְּחַיָּה וּבְעוֹפוֹת, אֲפִלּוּ בְּמִינֵי חַיָּה שֶׁבַּיָּם, הֲרֵי זֶה לוֹקֶה.\nאֵינוֹ לוֹקֶה, עַד שֶׁיַּכְנִיס בְּיָדוֹ כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת. אֲבָל אִם הֶעֱלָם זֶה עַל זֶה בִּלְבַד, אוֹ שֶׁעוֹרְרָם בְּקוֹל, הָיוּ מַכִּין אוֹתוֹ מַכַּת מַרְדוּת.\nמֻתָּר לְהַכְנִיס שְׁנֵי מִינִים לְדִיר אֶחָד, וְאִם רָאָה אוֹתָם רוֹבְעִים זֶה אֶת זֶה אֵינוֹ זָקוּק לְהַפְרִישָׁם. \u0005וּבְמָקוֹם דְּאִכָּא לְמֵיחַשׁ לִפְרִיצוּתָא, דְּעָבְדֵי אִסּוּרָא, אָסוּר לְהַכְנִיסָם אֲפִלּוּ לְדִיר (נ\"י פֶּרֶק הַשּׂוֹכֵר)\u0006. \u0010c2\u0011\nאָסוּר לְיִשְׂרָאֵל לִתֵּן בְּהֶמְתּוֹ לְעוֹבֵד כּוֹכָבִים לְהַרְבִּיעָהּ. \u0005וְכֵן כָּל אֲמִירָה לְעוֹבֵד כּוֹכָבִים, אֲפִלּוּ בְּאִסּוּר לָאו, אֲסוּרָה (שָׁם)\u0006, אִם לֹא שֶׁהָעוֹבֵד כּוֹכָבִים עוֹשֶׂה לַהֲנָאַת \u0010c3\u0011 עַצְמוֹ \u0005(הַגָּהוֹת מָרְדְּכַי דְּשַׁבָּת)\u0006.\nמִי שֶׁעָבַר וְהִרְכִּיב בְּהֶמְתּוֹ כִּלְאַיִם, הֲרֵי הַנּוֹלָד מֵהֶם מֻתָּר בַּהֲנָאָה. וְאִם הָיָה מִין טְהוֹרָה עִם מִין טְהוֹרָה, \u0010c4\u0011 מֻתָּר בַּאֲכִילָה.\nכָּל ב' מִינֵי בְּהֵמָה אוֹ חַיָּה, אַף עַל פִּי שֶׁדּוֹמִין זֶה לָזֶה וּגְדֵלִים זֶה עִם זֶה וּמִתְעַבְּרִין זֶה מִזֶּה, הוֹאִיל וְהֵם ב' מִינִים, אֲסוּרִים מִשּׁוּם כִּלְאַיִם, כֵּיצַד, הַזְּאֵב עִם הַכֶּלֶב וְכֶלֶב כָּפְרִי \u0005(פֵּרוּשׁ כֶּלֶב שֶׁמְּגַדְּלִין בְּנֵי הַכְּפָרִים וְהוּא קָטָן וְדוֹמֶה לְשׁוּעָל)\u0006 עִם הַשּׁוּעָל; הָעִזִּים עִם הַצְּבָאִים; הַיְּעֵלִים עִם הָרְחֵלִים; הַסוּס עִם הַפִּרְדָּה; הַפֶּרֶד עִם הַחֲמוֹר; הַחֲמוֹר עִם הֶעָרוֹד \u0005(פי' חֲמוֹר הַבַּר שֶׁגָּדֵל בַּמִּדְבָּר)\u0006, כִּלְאַיִם זֶה עִם זֶה.\nמִין שֶׁיֵּשׁ בּוֹ מִדְבָּרִי וְיִשּׁוּבִי, כְּגוֹן שׁוֹר \u0010c5\u0011 הַבַּר עִם הַשּׁוֹר; וְהָרַמָּךְ \u0005(פֵּרוּשׁ סוּס, מִן בְּנֵי הָרַמָּכִים)\u0006 \u0005(אֶסְתֵּר ח, י)\u0006 עִם הַסוּס מֻתָּרִים זֶה עִם זֶה. אֲבָל הָאַוָּז עִם אַוָּז הַבַּר, כִּלְאַיִם זֶה בָּזֶה, מִפְּנֵי שֶׁהָאַוָּז בֵּיצָיו מִבִּפְנִים, וְאַוַּז הַבַּר בֵּיצָיו מִבַּחוּץ, מִכְּלָל שֶׁהֵם ב' מִינִים.\nהַכּוֹי, כִּלְאַיִם עִם הַחַיָּה וְעִם הַבְּהֵמָה, וְאֵין לוֹקִין עָלָיו, מִפְּנֵי שֶׁהוּא סָפֵק.\nהַנּוֹלָדִים מִן הַכִּלְאַיִם, אִם הָיוּ אִמּוֹתֵיהֶן מִין אֶחָד, מֻתָּר לְהַרְכִּיבָן זֶה עַל זֶה. וְאִם הָיוּ אִמּוֹתֵיהֶן שְׁנֵי מִינִים, אָסוּר לְהַרְכִּיבָן זֶה עַל זֶה, אַף עַל פִּי שֶׁאֲבוֹתֵיהֶם מִין אֶחָד. וְאָסוּר לְהַרְכִּיב זֶה הַנּוֹלָד אֲפִלּוּ עַל מִין אִמּוֹ. כֵּיצַד, \u0010c6\u0011 פֶּרֶד שֶׁאִמּוֹ חֲמוֹרָה, מֻתָּר לְהַרְכִּיבוֹ עַל פִּרְדָּה שֶׁאִמָּהּ חֲמוֹרָה, וְאָסוּר לְהַרְכִּיבוֹ אֲפִלּוּ עַל הַחֲמוֹרָה. אֲבָל פֶּרֶד שֶׁאִמּוֹ סוּסְיָה, אָסוּר לְהַרְכִּיבוֹ עַל פִּרְדָּה שֶׁאִמָּהּ חֲמוֹרָה, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ הָרוֹצֶה לְהַרְכִּיב פֶּרֶד עַל פִּרְדָּה אוֹ לִמְשֹׁךְ בִּשְׁתֵּי פְּרָדוֹת, בּוֹדֵק בְּסִימָנֵי אָזְנַיִם וְזָנָב וְקוֹל, אִם דּוֹמִים זֶה לָזֶה, בְּיָדוּעַ שֶׁאִמָּן מִמִּין אֶחָד, וּמֻתָּרִים.\nאָסוּר לַעֲשׂוֹת מְלָאכָה בִּשְׁנֵי מִינִין, כְּגוֹן לַחֲרשׁ וְלִמְשֹׁךְ בְּקָרוֹן וְכַיּוֹצֵא בָּזֶה, בֵּין שֶׁאֶחָד טָמֵא וְאֶחָד טָהוֹר, בֵּין שֶׁשְּׁנֵיהֶם טְמֵאִים, בֵּין שֶׁשְּׁנֵיהֶם טְהוֹרִים, בֵּין בְּהֵמָה עִם בְּהֵמָה כַּחֲזִיר עִם הַכֶּבֶשׂ, אוֹ חַיָּה עִם חַיָּה כַּיַּחְמוּר עִם הַפִּיל, אוֹ חַיָּה עִם בְּהֵמָה כַּכֶּלֶב עִם הָעֵז, אוֹ צְבִי עִם הַחֲזִיר וְכַיּוֹצֵא בָּהֶן.\nאֶחָד הַחוֹרֵשׁ אוֹ הַזּוֹרֵעַ אוֹ הַמּוֹשֵׁךְ בָּהֶם עֲגָלָה אוֹ אֶבֶן כְּאֶחָד, אוֹ \u0010c7\u0011 הִנְהִיגָם כְּאֶחָד, וַאֲפִלּוּ בְּקוֹל, לוֹקֶה. \u0005הַגָּה: עוֹבֵד כּוֹכָבִים הַמַּנְהִיג בְּכִלְאַיִם, מֻתָּר לְיִשְׂרָאֵל לִפְרֹס לוֹ שָׁלוֹם אוֹ לְדַבֵּר עִמּוֹ בְּקוֹל רָם, דְּלֹא חַיְשִׁינָן שֶׁמָּא יֵלְכוּ הַבְּהֵמוֹת מִשּׁוּם קוֹלוֹ, דִּבְכָל הָאִסּוּרִין דָּבָר שֶׁאֵינוֹ מִתְכַּוֵּן שָׁרֵי, אִם אֵינוֹ פָּסִיק רֵישָׁא. אֲבָל אִם יִשְׂרָאֵל הוֹלֵךְ עִם הָעוֹבֵד כּוֹכָבִים בַּדֶּרֶךְ, וּמַשָּׁא שֶׁל \u0010c8\u0011 יִשְׂרָאֵל עַל הָעֲגָלָה שֶׁל עוֹבֵד כּוֹכָבִים שֶׁמַּנְהִיגָהּ כִּלְאַיִם, לֹא יֵלֵךְ הַיִּשְׂרָאֵל סָמוּךְ לָעֲגָלָה, דְּלִפְעָמִים הָעֲגָלָה נִכְבֶּשֶׁת וְהוּא יִצְעַק עַל הַבְּהֵמוֹת שֶׁיֵּלְכוּ בִּמְהֵרָה, וְזֶהוּ אָסוּר מִשּׁוּם מַנְהִיג בְּכִלְאַיִם (ת\"ה סי' רצ\"ח)\u0006. אֲבָל הַמְזַוְּגָן, פָּטוּר עַד שֶׁיִּמְשֹׁךְ אוֹ עַד שֶׁיַּנְהִיג. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ אָסוּר לְהַנְהִיגָן אוֹ לְהַמְשִׁיכָן, רַק בִּקְשׁוּרִין יַחַד (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006, וְלָכֵן מֻתָּר לָרוֹכֵב לִמְשֹׁךְ בְּחֶבֶל כֶּלֶב אֵצֶל הַסּוּס \u0005(שָׁם בְּשֵׁם אֲבִי הָעֶזְרִי)\u0006. וְיֵשׁ \u0010c9\u0011 חוֹלְקִים \u0005(שָׁם בְּשֵׁם ר' אֶפְרַיִם)\u0006.\nעֲגָלָה שֶׁהָיוּ מוֹשְׁכִין אוֹתָהּ כִּלְאַיִם, אָסוּר לֵישֵׁב בָּהּ אַף עַל פִּי שֶׁלֹּא הִנְהִיג, מִפְּנֵי שֶׁיְּשִׁיבָתוֹ גּוֹרֶמֶת לָהֶם שֶׁיִּמְשְׁכוּ הָעֲגָלָה. וְכֵן אָסוּר לִהְיוֹת אֶחָד יוֹשֵׁב בָּעֲגָלָה וְאֶחָד מַנְהִיג.\nאֲפִלּוּ מֵאָה שֶׁהִנְהִיגוּ כְּאֶחָד, לוֹקִים.\nקָשַׁר שְׁנֵי סוּסִים בְּקָרוֹן אֶחָד, אָסוּר לִקְשֹׁר עִמָּהֶם חֲמוֹר, אַף עַל פִּי שֶׁשְּׁנֵי הַסוּסִים יְכוֹלִין לְמָשְׁכוֹ בְּלֹא הַחֲמוֹר.\nעֲגָלָה הַמּוֹשֶׁכֶת \u0010c10\u0011 \u0010c11\u0011 \u0010c12\u0011 בְּקָרוֹן בְּמִין אֶחָד, לֹא יִקְשֹׁר מִין אַחֵר בְּחֶבֶל, לֹא בְּצִדֵּי הַקָּרוֹן וְלֹא אַחַר הַקָּרוֹן, \u0005מִפְּנֵי שֶׁדּוֹחֶה הַקָּרוֹן בַּהֲלִיכָתָה (טוּר)\u0006.\nמֻתָּר לַעֲשׂוֹת מְלָאכָה בְּאָדָם וּבִבְהֵמָה אוֹ חַיָּה כְּאֶחָד, כְּגוֹן אָדָם שֶׁחוֹרֵשׁ עִם שׁוֹר, אוֹ מוֹשֵׁךְ עֲגָלָה עִם חֲמוֹר, וְכַיּוֹצֵא בוֹ.",[],["\u0003נתכוין. \u0004 כ' הט\"ז וא\"ל ממ\"ש בס\"ה דאסור לזרוע את המעורב עד שימעט כו' וכי ממעט מיהו שפיר דמי דכבר פי' בכ\"מ דלעיל מיירי שנפל שלא במתכוין ונתערב ואח\"כ בשעת הזרע לא ניחא ליה שיצמח אותו המין שנתערב אבל אי הוה ניחא ליה בשעת נפילה או אח\"כ ודאי אסור אפילו בחטה אחת:","\u0003מפני מראית עין. \u0004 והא דאמרינן בס\"ב ואם קיימן אינו לוקה משמע דמ\"מ איסור מן התורה יש בדבר התם מיירי דניחא ליה בקיום והכא אמר אף דלא ניחא ליה בקיומן מ\"מ אחרים יאמרו דניחא ליה בכך עכ\"ל [הט\"ז]:","\u0003סימן רצז \u0005(א)\u0006\u0004 דיני הרבעת והנהגת כלאי בהמה\n\u0003בבהמה. \u0004 כ' הש\"ך משמע אפי' [טהורה] עם טהורה לוקה והוא דעת הרא\"ש והטור דלא כהרמב\"ם שסבירא ליה דאינו לוקה בזה אלא מדרבנן עכ\"ל:","\u0003דעבדי. \u0004 גירסת הש\"ך ובמקום וכו' לפריצותא דעבדי אסור ור\"ל במקום שאינם בני תורה או במקום דאיכא למיחש לפריצותא דעבדים שסתמן פרוצים הם ויש לחוש שירביעום בידים עכ\"ל:","\u0003אסור. \u0004 כתב הט\"ז ואם עבר ועשה כן א\"צ למכור בהמתו לעובד כוכבים ול\"ד לסירוס בהמה כמ\"ש בא\"ע סימן ה' דשם מצוי האיסור בכל יום גבי עובדי כוכבים אבל כאן הוא מילתא דלא שכיחא לא גזרו בו קנס:","\u0003עצמו. \u0004 והש\"ך כתב דמשמע מהרמב\"ם והרא\"ש ושאר פוסקים דאפילו העובד כוכבים עשה להנאת עצמו אסור בדבר של ישראל ע\"ש:","\u0003באכילה. \u0004 כ' הט\"ז נראה פשוט דכ\"ש הנרבעת עצמה דמותרת באכילה במין טהור \u0005(וע\"ל סימן קנ\"ג)\u0006 וכתבתי זה לפי שראיתי מורה א' שאסר תרנגולת אחת שנרבעה מאינה מינה ולא יפה עשה עכ\"ל:","\u0003הבר. \u0004 כ' הש\"ך תימה דלעיל סימן כ\"ח ס\"ד כתב הרב די\"א שור הבר מין חיה ואם כן פשיטא דאסור עם השור וצ\"ע:","\u0003פרד. \u0004 כלומר דכל פרד הוא בא מסוס וחמור דוקא וא\"כ פרד זה שאמו חמורה ע\"כ אביו סוס ולכך מותר להרכיבו על פרדה שאמה חמורה שאביה ג\"כ סוס וא\"כ יש בכל א' ב' צדדים אבל אסור להרכיבו על החמורה ומיהו אין לוקין עליו דדלמא אין חוששין לזרע האב עכ\"ל הש\"ך:","\u0003הנהיגם. \u0004 כתב הט\"ז לכאורה משמע שבשביל הנהגה לחוד חייב אפילו אין להם שום מלאכה ביחד או משאוי שום דבר אבל לא משמע כן מכל הפוסקים וצ\"ל דבאמת מיירי שעושים שום מלאכה או משא החבל שנושאים ביחד \u0005(שנמשכה על ידיהן)\u0006 וכיון שהאיסור הוא משום משאוי החבל נראה שאין לקשור שני מיני עופות בחד חבל כדי שלא יברחו דהא כשמנענעים עצמם כדרך העופות שמזיזים עצמם ממקום למקום אפילו כשהם כפותים ואז נושאים חוט המשיחה שנקשרים בהם דהא גם בב' מיני עופות יש כלאים והעולם אינם יודעים להזהר מזה עכ\"ל:","\u0003ישראל. \u0004 דכיון דמשא של הישראל יש לחוש שיצעק על הבהמות ש\"ך:","\u0003חולקים. \u0004 וכתב בס' ב\"ה בשם א\"ח היהודים הצדין בעוף הנקרא אשפרוי\"ר אין להם לקשור בחבל שהעוף נקשר בו בתפוס מן האוכף מן הסוס שהן כלאים עכ\"ל ובט\"ז כ' ונ\"ל שיש לאסור לישב בעגלה שהפרה קשורה בו והסוס מוליך את העגלה ויש למחות ביד הקצבים העושים כן. ובדרישה למד עליהם זכות שאין עושין כן אלא לפי שעה באקראי בעלמא וחס ליה לאותו צדיק לומר כן דכאן הוא איסור דאורייתא ומה לי לפי שעה או לזמן מרובה עכ\"ל:","\u0003בקרון. \u0004 הרמב\"ם פי' במשנה דהיינו עגלה קטנה שיושב בה אדם והיא נמשכת על ידי הקרון שנקשרה בו והסוסים מוליכים הקרון עכ\"ל וע\"ש:"]],["\u0003הלכות כלאי בגדים\u0004\nאֵין אָסוּר מִשּׁוּם כִּלְאַיִם, אֶלָּא צֶמֶר רְחֵלִים וְאַיָּלִים עִם פִּשְׁתָּן. אֲבָל צֶמֶר גְּמַלִּים וְצֶמֶר אַרְנָבִים וְנוֹצָה שֶׁל עִזִּים וְכָל שְׁאָר מִינִים, מֻתָּרִים בְּפִשְׁתָּן. וְכֵן קַנְּבּוֹס וְצֶמֶר גֶּפֶן וְכָל שְׁאָר מִינִים, מֻתָּרִים אֲפִלּוּ בְּצֶמֶר רְחֵלִים וְאַיָּלִים; וַחֲכָמִים אָסְרוּ מִפְּנֵי מַרְאִית הָעַיִן מֶשִׁי עִם צֶמֶר, לְפִי שֶׁדּוֹמֶה לְפִשְׁתִּים. וְכֵן כָּלָךְ, וְהוּא מִין שֶׁגָּדֵל בִּכְרַכֵּי הַיָּם עַל הָאֲבָנִים שֶׁבַּיָּם וְדוֹמֶה לְצֶמֶר, אֲסָרוּהוּ מִפְּנֵי מַרְאִית הָעַיִן עִם הַפִּשְׁתָּן. וְהָאִדָּנָא מֶשִׁי מָצוּי בֵּינֵינוּ וְהַכֹּל מַכִּירִים בּוֹ, לְפִיכָךְ אֵין בּוֹ מִשּׁוּם מַרְאִית הָעַיִן וּמֻתָּר עִם הַצֶּמֶר וְעִם הַפִּשְׁתָּן.\nרָחֵל בַּת עֵז, צִמְרָהּ אָסוּר עִם פִּשְׁתָּן, מִפְּנֵי מַרְאִית הָעַיִן. \u0005הַגָּה: וְאָסוּר לִתְפֹּר בֶּגֶד קַנַּבּוֹס תַּחַת בֶּגֶד צֶמֶר בְּמָקוֹם דְּלֹא שָׁכִיחַ קָנַבּוֹס, מִשּׁוּם מַרְאִית הָעַיִן (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006, וּבְמָקוֹם דְּשָׁכִיחַ \u0010c0\u0011 שָׁרֵי.",[],["\u0003שרי. \u0004 כ' הש\"ך ובמדינותינו נוהגין היתר בבגד קנבוס כי הוא מצוי לרוב וכתב הב\"ח דכיון שמצוי נוהגין היתר אע\"פ שלא נמצא מי שמכירו להבין שהוא בגד קנבוס כ\"א על המעט כו' ע\"ש שהאריך עכ\"ל:"]],["צֶמֶר רְחֵלִים וְצֶמֶר גְּמַלִּים וְכַיּוֹצֵא בוֹ, שֶׁטְּרָפָן זֶה בָּזֶה וְטוֹוֶה מֵהֶם טְוִוי, אִם הָיָה הַחֲצִי מֵהָרְחֵלִים הֲרֵי הַכֹּל כְּצֶמֶר וַהֲרֵי הוּא כִּלְאַיִם עִם הַפִּשְׁתָּן. וְאִם הָיָה הָרֹב מֵהַגְּמַלִּים, מֻתָּר לְעָרְבוֹ עִם הַפִּשְׁתָּן, מִפְּנֵי שֶׁצּוּרַת הַכֹּל צוּרַת צֶמֶר גְּמַלִּים, וְאֵין חוֹשְׁשִׁין לְנִימוֹת שֶׁל צֶמֶר הַמְעֹרָבִים בָּהֶם, מִפְּנֵי שֶׁאֵינָם חוּטֵי צֶמֶר. לְפִיכָךְ עוֹרוֹת הַכְּבָשִׂים שֶׁעוֹשִׂים מֵהֶם מַלְבּוּשִׁים, מֻתָּר לְתָפְרָן בְּחוּטֵי פִּשְׁתָּן, וְאֵין חוֹשְׁשִׁין לְנִימוֹת שֶׁל צֶמֶר, אַף עַל פִּי שֶׁנִּכְרְכוּ בִּכְלַל חוּט הַפִּשְׁתָּן שֶׁתָּפְרוּ בּוֹ, שֶׁהֲרֵי בָּטְלוּ בְּמִעוּטָן. וְכֵן הַקַּנַּבּוֹס וְהַפִּשְׁתָּן שֶׁטְּרָפָן זֶה בָּזֶה אִם רֹב מֵהַקַּנַּבּוֹס, מֻתָּר לֶאֱרֹג הַטָּווּי מֵהֶם עִם חוּטֵי צֶמֶר. וְאִם הָיוּ מֶחֱצָה לְמֶחֱצָה, אָסוּר. הִלְכָּךְ, מִי שֶׁנִּתְעָרֵב לוֹ צֶמֶר עִם פִּשְׁתָּן, מֵבִיא מִין אַחֵר \u0010c0\u0011 וּמְעָרְבוֹ עִמָּהֶם, וּמְבַטֵּל אֶחָד מֵהֶם. וְלֹא שַׁיָּךְ בְּהוּ בִּטּוּל אֶלָּא קֹדֶם שֶׁיֵּעָשׂוּ חוּטִים, אֲבָל אַחַר שֶׁנַּעֲשׂוּ חוּטִים אֵין לַכִּלְאַיִם שִׁעוּר, אֲפִלּוּ חוּט כָּל שֶׁהוּא שֶׁל צֶמֶר בְּבֶגֶד גָּדוֹל שֶׁל פִּשְׁתָּן אוֹ שֶׁל פִּשְׁתָּן בְּצֶמֶר, אָסוּר. \u0005הַגָּה: וַאֲפִלּוּ נֶאֱבַד הַחוּט וְלֹא יָדַעְנוּ מְקוֹמוֹ, לֹא שַׁיָּךְ בֵּיהּ \u0010c1\u0011 בִּטּוּל, וְאָסוּר (רַשְׁבָּ\"א סי' רנ\"ט וְכֵן כָּתַב הבֵּית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת וְהָרֹא\"שׁ וּסְמַ\"ג)\u0006. בֶּגֶד שֶׁהַשְּׁתִי שֶׁל מֶשִׁי וְהָעֵרֶב שֶׁל פִּשְׁתָּן, אָסוּר לְתָפְרוֹ עִם הַצֶּמֶר אַף עַל פִּי שֶׁרֻבּוֹ שֶׁל מֶשִׁי \u0005(טוּר)\u0006. וְלָכֵן אָסוּר לַעֲשׂוֹת טַלִּיתוֹת מִבְּגָדִים שֶׁקּוֹרִין פירכו\"ט, כִּי הָעֵרֶב שֶׁל פִּשְׁתָּן וְהָוֵי כִּלְאַיִם עִם הַצִּיצִית. \u0005(דַּעַת עַצְמוֹ)\u0006.\nהָעוֹשֶׂה בֶּגֶד כֻּלּוֹ צֶמֶר גְּמַלִּים אוֹ אַרְנָבִים אוֹ קַנַּבּוֹס, וְאָרַג בּוֹ חוּט שֶׁל צֶמֶר מִצַּד זֶה וְחוּט שֶׁל פִּשְׁתָּן מִצַּד זֶה, הֲרֵי זֶה \u0010c2\u0011 אָסוּר מִשּׁוּם כִּלְאַיִם. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּשָׁרֵי בִּכְהַאי גַּוְנָא, אֶלָּא אִם כֵּן אָרַג חוּט שֶׁל צֶמֶר אֵצֶל הַחוּט שֶׁל פִּשְׁתִּים. אֲבָל אִם אֵינָם נוֹגְעִים יַחַד, שָׁרֵי (בֵּית יוֹסֵף בְּשֵׁם הָרֹא\"שׁ ור\"ש)\u0006. וְעַיֵּן לְקַמָּן סִימָן ש' דְּנוֹהֲגִין לְהָקֵל.",[],["\u0003ומערבו. \u0004 פירש הט\"ז דאם נתערב צמר רחלים עם פשתים מביא צמר גמלים הרבה ומערב שם ממילא נתבטל הצמר רחלים ואין כאן איסור אבל בתרי מינים לחוד לא מהני ביטול ברוב מחמת מין א' על חבירו ובעורות כבשים הוה ג\"כ מין שלישי דהיינו העור עצמו שהוא מעורב עם קישור חוט התפירה של פשתן ועם הצמר של העור עכ\"ל:","\u0003בטול. \u0004 ולא אמרינן שיבטל ברוב מאחר שאין מקומו ניכר דלא שייך ביטול ברוב אלא איסור שנתערב בהיתר אבל היתר שנתערב בהיתר וע\"י תערובתם נאסר לא שייך בזה ביטול דאין כאן אלא חתיכה א' של איסור הרא\"ש והפוסקים ומביאם הב\"י וכתב הלבוש ול\"ד לבשר בחלב דקי\"ל שבטל דהתם טעם הבשר או החלב מתפשט ונתערב בכולו ואין כאן מקום מיוחד לאיסור אבל הכא האיסור יש לו מציאות במקומו ולא נתפשט לא שייך בו ביטול והש\"ך הקשה עליו דהא קי\"ל אפילו יש לאיסור מציאות במקומו כגון שנתערב יבש ביבש בטל אלא הטעם ברור ומבואר בדברי הפוסקים לפי שגבי בב\"ח אין האיסור אלא מחמת שיתן טעם והלכך כשבטל הטעם בטל האיסור משא\"כ גבי כלאים דהאיסור משום חיבור הוא וגזרת הכתוב כך הוא הלכך לא שייך בזה ביטול עכ\"ל:","\u0003אסור. \u0004 ובסימן ש' ס\"ה סתם המחבר כסברת המתירים בזה וצ\"ע מ\"ש המחבר כאן סברת האוסרים בסתם בלי חולק עכ\"ל הש\"ך:"]],["כֵּיוָן שֶׁנִּתְחַבֵּר הַצֶּמֶר עִם הַפִּשְׁתָּן צַד חִבּוּר בָּעוֹלָם, אָסוּר מִשּׁוּם כִּלְאַיִם. כֵּיצַד, צֶמֶר וּפִשְׁתִּים שֶׁטְּרָפָן זֶה עִם זֶה וְשַׁע אוֹתָם וְעָשָׂה מֵהֶם \u0010c0\u0011 לְבָדִים, אוֹ שֶׁטְּרָפָן וְטָוָה אוֹתָם כְּאֶחָד, וְאָרַג בֶּגֶד מִטִּוּוּי זֶה, אוֹ שֶׁתָּפַר בֶּגֶד צֶמֶר בְּשֶׁל פִּשְׁתָּן, אֲפִלּוּ תְּפָרָן בְּחוּטֵי מֶשִׁי וְקַנַּבּוֹס, אוֹ שֶׁתָּפַר בֶּגֶד צֶמֶר בְּחוּטֵי פִּשְׁתָּן אוֹ בֶּגֶד פִּשְׁתָּן בְּחוּטֵי צֶמֶר, אוֹ קָשַׁר חוּטֵי צֶמֶר בְּחוּטֵי פִּשְׁתָּן אוֹ גְּדָּלָן, הֲרֵי זֶה כִּלְאַיִם.\nבֶּגֶד צֶמֶר שֶׁחִבְּרוֹ עִם בֶּגֶד פִּשְׁתָּן בִּתְכִיפָה אַחַת \u0005(פי' בִּתְחִיבָה אַחַת שֶׁתָּחַב הַמַּחַט בַּבֶּגֶד)\u0006, אֵינוֹ חִבּוּר וְאֵין זֶה כִּלְאַיִם. קִבֵּץ שְׁנֵי רָאשֵׁי הַחוּט כְּאֶחָד, אוֹ שֶׁתָּכַף שְׁתֵּי תְּכִיפוֹת, הֲרֵי זֶה כִּלְאַיִם. \u0005וְיֵשׁ אוֹמְרִים דְּלֹא הָוֵי כִּלְאַיִם אֶלָּא בְּב' תְּכִיפוֹת \u0010c1\u0011 וְקָשַׁר ב' רָאשֵׁי הַחוּט (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nבֶּגֶד צֶמֶר שֶׁנִּפְרַם \u0005(פי' נִקְרַע)\u0006, מֻתָּר לִפְרֹף \u0005(פי' לְחַבֵּר)\u0006 אוֹתוֹ בְּחוּטֵי פִּשְׁתָּן, וְקוֹשֵׁר, \u0010c2\u0011 אֲבָל לֹא יִתְפֹּר. \u0005הַגָּה: וְכֵן מֻתָּר לִתֵּן צֶמֶר בְּכַר אוֹ כֶּסֶת שֶׁל פִּשְׁתָּן, אַף עַל פִּי שֶׁתּוֹפֵר כָּל סְבִיבָיו וְאֵינוֹ יָכוֹל לְהוֹצִיא הַצֶּמֶר, הָוֵי כְּשַׂק שֶׁל פִּשְׁתִּים שֶׁמְּמַלְּאוֹ צֶמֶר וְתָפַר פִּיו, שֶׁאֵין בָּזֶה מִשּׁוּם כִּלְאַיִם (כֵּן הוּא בַּטּוּר)\u0006. וַאֲפִלּוּ \u0005(תָּחַב)\u0006 הַתְּפִירָה בַּצֶּמֶר עַצְמוֹ, מֻתָּר, דַּהֲרֵי יָכוֹל לִקַּח הַצֶּמֶר מִשָּׁם בְּלֹא הַתָּרַת \u0010c3\u0011 הַתְּפִירָה. אֲבָל בִּבְלָאֵי בְּגָדִים שֶׁל צֶמֶר, אָסוּר \u0010c4\u0011 בִּכְהַאי גַּוְנָא, שֶׁהֲרֵי אִי אֶפְשָׁר לִקַּח מִשָּׁם הַבְּגָדִים בְּלֹא הַתָּרַת הַתְּפִירָה \u0005(ד\"ע וּמָרְדְּכַי פ' בַּמֶּה אִשָּׁה וְתּוֹס' ספ\"ק דְּבֵיצָה)\u0006. וְכֵן מֻתָּר לְחַבֵּר בָּתֵּי זְרוֹעוֹת שֶׁל צֶמֶר שֶׁיֵּשׁ בָּהֶם קְשָׁרִים, אוֹ קְרָסִים בְּבָתֵּי נֶפֶשׁ שֶׁל פִּשְׁתָּן שֶׁיֵּשׁ בּוֹ נְקָבִים, וּמַכְנִיסִים הַקְּשָׁרִים אוֹ הַקְּרָסִים תּוֹךְ הַנְּקָבִים, הוֹאִיל וְהֵם רְפוּיִים וְיָכוֹל לְהוֹצִיאָן מִשָּׁם בְּאֶצְבָּעוֹ וְאֵין צָרִיךְ לִקְרֹעַ הַנְּקָבִים, אַף עַל פִּי שֶׁמַּנִּיחָן כָּךְ תָּמִיד. אֲבָל אִם הֵם אֲדוּקִים כָּל כָּךְ שֶׁאִי אֶפְשָׁר לְהוֹצִיאָן מִשָּׁם בִּלְתִּי קְרִיעַת הַנְּקָבִים, הָוֵי חִבּוּר וְאָסוּר \u0005(ת\"ה סי' רנ\"ו)\u0006.\nמֻתָּר לִלְבֹּשׁ חָלוּק שֶׁל צֶמֶר עַל גַּבֵּי חָלוּק שֶׁל פִּשְׁתָּן וּלְקָשְׁרָם יַחַד, אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לְפָשְׁטָן בְּלֹא הַתָּרַת הַקֶּשֶׁר, וַאֲפִלּוּ הוּא קֶשֶׁר שֶׁל קַיָּמָא, וּבִלְבַד שֶׁלֹּא יְחַבְּרֵם זֶה לָזֶה עִם הַמְּשִׁיחָה בִּשְׁתֵּי תְּכִיפוֹת. וְיֵשׁ \u0010c5\u0011 אוֹסְרִים בְּקֶשֶׁר שֶׁל קַיָּמָא. \u0005הַגָּה: וְנִרְאֶה לִי דְּאוֹתָן בָּתֵּי \u0010c6\u0011 שׁוֹקַיִם שֶׁעוֹשִׂין בִּמְדִינוֹת אֵלּוּ וְקוֹרִין אוֹתוֹ פורטקי, דְּהַיְנוּ שֶׁעֲשׂוּיִן שֶׁל צֶמֶר וְעוֹשִׂים בָּהֶם מְשִׁיחָה שֶׁעוֹבֶרֶת בָּהֶן הֵנָּה וָהֵנָּה כְּמוֹ רְצוּעָה בְּמַעְבַּרְתָּא דִּתְפִילִּין, דְּמֻתָּר אֲפִלּוּ הַמְּשִׁיחָה שֶׁל פִּשְׁתָּן אוֹ אִפְּכָא, דְּמֵאַחַר דְּאֶפְשָׁר לְהוֹצִיא מִשָּׁם הַמְּשִׁיחָה בְּלֹא הַתָּרַת הַתְּפִירָה אֵינוֹ אֶלָּא כְּחוֹגֵר בִּמְשִׁיחָה שֶׁל פִּשְׁתָּן עַל גַּבֵּי חָלוּק שֶׁל צֶמֶר. וְאַף עַל פִּי שֶׁקּוֹשֵׁר הַמְּשִׁיחָה כְּשֶׁלְּבָשָׁן, לֹא מִקְרֵי קֶשֶׁר שֶׁל קַיָּמָא. אֲבָל אִם עוֹשֶׂה קְשָׁרִים בְּב' רָאשֵׁי הַמְּשִׁיחָה, נִרְאֶה דְּאָסוּר, דְּהָא אִי אֶפְשָׁר לְהוֹצִיא מִשָּׁם (הַכֹּל סְבָרַת הָרַב)\u0006. יֵשׁ אוֹמְרִים דְּאָסוּר לִלְבֹּשׁ ב' בָּתֵּי שׁוֹקַיִם, אֶחָד שֶׁל פִּשְׁתָּן וְאֶחָד שֶׁל צֶמֶר, זוֹ עַל זוֹ \u0005(הַגָּהַת אֲשֵׁרִ\"י פ\"ק דְּבֵיצָה)\u0006, דְּמֵאַחַר \u0010c7\u0011 דְּאִי אֶפְשָׁר לִפְשֹׁט הַתַּחְתּוֹנָה בְּלֹא הָעֶלְיוֹנָה הָוֵי כְּחִבּוּר, וְלֹא דָּמֵי לְב' חֲלוּקִים זוֹ עַל זוֹ עַל זוֹ דְּאֶפְשָׁר לִפְשֹׁט הַתַּחְתּוֹן בְּלֹא הָעֶלְיוֹן \u0005(כָּךְ מָצָא הַטַּעַם בְּאוֹר זָרוּעַ)\u0006 וְנָכוֹן לִזָּהֵר.\nרְצוּעָה אַחַת שֶׁל צֶמֶר וְהַשְּׁנִיָּה שֶׁל פִּשְׁתָּן, אָסוּר לַחֲגֹר בָּהּ אַף עַל פִּי שֶׁרְצוּעָה שֶׁל עוֹר בָּאֶמְצַע, מִפְּנֵי שֶׁקּוֹשֵׁר שְׁנֵי רָאשֶׁיהָ בְּיַחַד כְּשֶׁחוֹגֵר בָּהּ. אֲבָל אִם בְּאֶמְצָעִיתָהּ צֶמֶר בְּמָקוֹם אֶחָד וּפִשְׁתָּן בְּמָקוֹם אַחֵר, וְאֵינָם זֶה אֵצֶל זֶה, מֻתָּר. וּלְפִי זֶה מֻתָּר לְחַבֵּר עוֹרוֹת הַתְּפוּרוֹת בְּפִשְׁתָּן תַּחַת בִּגְדֵי צֶמֶר, וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁיַּכְנִיס חוּט הַקַּנַּבּוֹס שֶׁל הַתְּפִירָה, שֶׁמְּחַבֵּר הָעוֹר עִם הַבֶּגֶד בְּתוֹךְ חוּט שֶׁל תְּפִירַת הָעוֹר \u0005(ר' יְרוּחָם ות\"ה סי' רצ\"ז)\u0006 וּלְהָרַמְבַּ\"ם כָּל זֶה כִּלְאַיִם מִן הַתּוֹרָה, וַאֲפִלּוּ נָתַן צֶמֶר וּפִשְׁתִּים בְּשַׂק אוֹ קֻפָּה וּכְרָכָן, הָוֵי כִּלְאַיִם מִדְּאוֹרַיְתָא. \u0005וְהַמִּנְהָג כִּסְבָרָא רִאשׁוֹנָה (טוּר וְכֵן כָּתַב הָרַמְבַּ\"ן וְהָרַשְׁבָּ\"א סִימָן ש\"ס ות\"ה סִימָן רצ\"ז)\u0006.\nהַמַּנְהִיג בְּהֵמוֹת וּמַכְנִיס חֲבָלִים לְתוֹךְ יָדוֹ, מֵהֶם פִּשְׁתִּים וּמֵהֶם צֶמֶר, הֲרֵי זֶה מֻתָּר, וְאַף עַל פִּי שֶׁכּוֹרְכָן עַל יָדוֹ. אֲבָל אִם \u0010c8\u0011 קְשָׁרָם כֻּלָּם, נַעֲשׂוּ כִּלְאַיִם, וְאָסוּר לוֹ לְכָרְכָם עַל יָדוֹ. \u0005וְיֵשׁ מַתִּירִין, הוֹאִיל וְאֵינוֹ מִתְכַּוֵּן (הַגָּהוֹת אֲשֵׁרִ\"י וְרַבֵּנוּ יְרוּחָם ני\"ט)\u0006 וְעַיֵּן לְקַמָּן סִימָן ש\"א.\nהַשַּׂק וְהַקֻּפָּה מִצְטָרְפִין לְכִלְאַיִם. \u0005הַגָּה: וְכֵן אָב וּבְנוֹ מִצְטָרְפִים לְכִלְאַיִם, כֵּיצַד, הָיָה חֲתִיכַת צֶמֶר בְּאֶחָד מֵהֶם וַחֲתִיכַת פִּשְׁתָּן בַּשֵּׁנִי, \u0010c9\u0011 וּתְפָרָן בְּיַחַד, הָוֵי כִּלְאַיִם (טוּר)\u0006.",[],["\u0003לבדים. \u0004 כתב הש\"ך ורוב הפוסקים ס\"ל דלבדים אינן אסורין אלא מדרבנן ובקשין מותר לגמרי כדלקמן סימן ש\"א ס\"ב בהג\"ה:","\u0003וקשר. \u0004 תתכגון שמעביר המחט פעם אחד ואינו מעביר כל החוט ומעביר המחט פעם שני ונמצא שני ראשי החוטין ביחד וקושר שני ראשי החוטין. הרא\"ש וטור:","\u0003אבל. \u0004 כ' הט\"ז וקשה דמשע כאן דיש איסור בחבור ע\"י קשר אם היה בענין שאינו יכול להוציא ראשי הקרעים בלא התרת הקשר ולעיל בס\"ב כ' הרמ\"א דאפילו בשתי תכיפות לא הוה חיבור בלא קשר וכן להיפך וצ\"ל דהתם לא מחבר הצמר ופשתים עצמן רק ע\"י חוט התפירה ע\"כ בעינן תרתי ב' תפירות וגם קשרים משא\"כ כאן דאסור היינו שאם היה קושר הבגד צמר עם בגד פשתן עצמו ועכ\"פ כ\"ע מודו דאם עושה נקבים בבגד עצמו ומחברם בחוט על ידי קשירת קיום דאסור והרבה נכשלין בזה שקושרין הטלומ\"ק של בגד במשיחה של פשתן וקושרין בצד אחד קשר של קיום עכ\"ל:","\u0003התפירה. \u0004 רק ע\"י קרע קטן כדאיתא בתוספות:","\u0003בכה\"ג. \u0004 כלומר אפילו כשאינו תוחב התפירה בעצמם. ט\"ז וש\"ך:","\u0003אוסרים. \u0004 כ' הט\"ז ולדיעה זו אסור להדק חגורה אם לובש בגד צמר על החלוק של פשתן אבל בתשו' הרשב\"א מבואר שכבר נהגו כל ישראל בהיתר בחגורה עכ\"ל:","\u0003שוקיים. \u0004 וה\"ה אנפלאות שקורין שטרימ\"ף. ש\"ך:","\u0003לפשוט. \u0004 והלבוש השיג על דברי הר\"ב האלו דהא בשני חלוקות ודאי מיירי כשיש להם בתי זרועות והיאך אפשר לפשוט התחתון בלא העליון ואין דבריו נראין דמ\"מ יכול להכניס זרועותיו לפנים ולפשוט אח\"כ החלוק ואע\"ג דהשתא הוציא ידיו גם מחלוק העליון מ\"מ החלוק העליון נשאר עדיין על הגוף עצמו ודמי לדלעיל בצמר בכר וכסת דאע\"ג דמוכרח לעשות קרע קטן שרי עכ\"ל הש\"ך וכ' הט\"ז דהעיקר בזה דכל שצריך הפשטות העליון תחלה אפילו מקצת ממנו יש איסור כיון שא\"א להפשיט התחתון אא\"כ יתחיל להפשיט העליון והנך בתי שוקיים שהזכיר הרמ\"א היינו שיש להם למטה צורת מלבוש על הרגל נמצא שא\"א לזוז ממקומם את התחתונים כל זמן שהעליונים על מקומם אבל אם הבתי שוקיים עשוים באופן שאין למטה ע\"ג הרגל כלום ויכול להושיט שם ידו ולהוליך התחתון עד למעלה באופן שלא יהיו מכוסים מן העליונים ה\"נ דמותר עכ\"ל:","\u0003קשרם. \u0004 וחד קשר סגי כאן כיון שאח\"כ כורך אותו על ידו. ט\"ז. וכ' הש\"ך דהאוסרין ס\"ל דל\"ד לסי' ש\"א ס\"ו דהכא הוי פסיק רישיה דמחמת אחיזתן אי אפשר שלא תתחמם ידו כ\"כ הב\"ח ודלא כהפרישה שהניחו בצ\"ע עכ\"ל:","\u0003ותפרן. \u0004 כ' הש\"ך דמדברי הרב נראה שאפילו לא חגר חגורות אסור עכ\"ל:"]],["מֻתָּר מִן הַתּוֹרָה לֵישֵׁב עַל מַצָּעוֹת שֶׁל כִּלְאַיִם, שֶׁנֶּאֱמַר: לֹא יַעֲלֶה עָלֶיךָ \u0005(וַיִּקְרָא יט, יט)\u0006 אֲבָל אַתָּה מַצִּיעוֹ תַּחְתֶּיךָ. \u0005הַגָּה: וְכֵן \u0010c0\u0011 מֻתָּר לְהַעֲלוֹתָם עָלָיו שֶׁלֹּא בְּדֶרֶךְ חִמּוּם, כְּגוֹן לִפְרֹס עָלָיו אֹהֶל שֶׁל כִּלְאַיִם (טוּר)\u0006. וְכֵן לִפְרֹס בֶּגֶד כִּלְאַיִם עַל גִּיגִית שֶׁרוֹחֵץ בָּהּ, כְּדֵי לְהַעֲמִיד הַחֹם \u0005(מָרְדְּכַי פ\"ק דְּבֵיצָה וּבְהַגָּהוֹת אֲשֵׁרִי שָׁם)\u0006, דְּאֵינוֹ אָסוּר אֶלָּא דֶּרֶךְ לְבִישָׁה אוֹ לְהַעֲלוֹתָם עָלָיו דֶּרֶךְ חִמּוּם. וּמִדִּבְרֵי סוֹפְרִים, אֲפִלּוּ עֶשֶׂר מַצָּעוֹת זוֹ עַל גַּבֵּי זוֹ וְהַתַּחְתּוֹן שֶׁבָּהֶם כִּלְאַיִם, אָסוּר לֵישֵׁב עַל הָעֶלְיוֹן, שֶׁמָּא תִּכָּרֵךְ נִימָא עַל בְּשָׂרוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּרַכִּין, כְּגוֹן יְרִיעוֹת וּשְׂמָלוֹת אֲבָל כָּרִים וּכְסָתוֹת שֶׁהֵם קָשִׁים וְלֵיכָּא לְמֵיחַשׁ שֶׁמָּא תִּכָּרֵךְ נִימָא עָלָיו, מֻתָּר לִישַׁן עֲלֵיהֶם וּבִלְבַד שֶׁלֹּא יְהֵא בְּשָׂרוֹ נוֹגֵעַ בָּהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֵם רֵיקָנִים וּנְתוּנִים עַל גַּבֵּי אִצְטַבָּא שֶׁל עֵץ אוֹ שֶׁל אֶבֶן, אֲבָל אִם הֵם מְלֵאִים, אוֹ אֲפִלּוּ רֵיקָנִים אִם הֵם נְתוּנִים עַל גַּבֵּי מִטָּה אוֹ עַל גַּבֵּי תֶּבֶן, אָסוּר, לְפִי שֶׁנִּכְפָּף תַּחְתָּיו וְנִכְרָךְ עַל בְּשָׂרוֹ. \u0005הַגָּה: \u0010c1\u0011 וְיֵשׁ אוֹמְרִים דְּכָל זֶה מַיְרֵי בְּכִלְאַיִם דְּאוֹרַיְתָא, אֲבָל בְּכִלְאַיִם דְּרַבָּנָן וְהֵם קָשִׁים, מֻתָּר לֵישֵׁב עֲלֵיהֶם בְּכָל עִנְיָן, דְּהוֹאִיל וּכְשֶׁרַכִּים הֵם אֵינוֹ רַק דְּרַבָּנָן, בְּקָשִׁים לֹא גָּזְרוּ (רַשְׁבָּ\"א סי' תשס\"ב)\u0006. וּמִכָּל מָקוֹם לְכַתְּחִילָה לֹא יַעֲשֶׂה שֶׁל כִּלְאַיִם, \u0005(כָּל בּוֹ)\u0006.\nהָנֵי קאפאנאג\"ש דִּידָן, אִם הֵם תְּפוּרִין בְּפִשְׁתָּן, יֵשׁ לִזָּהֵר מִלְּהַעֲלוֹתָם עָלָיו וַאֲפִלּוּ מִלְּהַצִּיעָן תַּחְתָּיו, עַד שֶׁיִּתְפְּרֵם בְּמֶשִׁי אוֹ בְּקַנַּבּוֹס. \u0005הַגָּה: כָּל בְּגָדִים הַקָּשִׁים מֻתָּרִים בְּהַצָּעָה מִתַּחְתָּיו, וְאָסוּר לְלָבְשָׁן. וְהַלְּבַדִּים הַקָּשִׁים, מֻתָּרִים אֲפִלּוּ בִּלְבִישָׁה, הוֹאִיל וַאֲפִלּוּ רַכִּים אֵינָם אֶלָּא מִדְּרַבָּנָן (טוּר)\u0006. וְיֵשׁ מַחְמִירִין \u0010c2\u0011 בִּלְבִישַׁת הַלְּבַדִּים \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006.\nבֶּגֶד גָּדוֹל וְכִלְאַיִם מִצַּד אֶחָד, אָסוּר לְלָבְשׁוֹ אֲפִלּוּ מִצִּדּוֹ הַב', אַף עַל פִּי שֶׁהַצַּד שֶׁבּוֹ הַכִּלְאַיִם נִגְרָר עַל גַּבֵּי הַקַּרְקַע.\nאָסוּר לִלְבֹּשׁ כִּלְאַיִם אֲפִלּוּ דֶּרֶךְ עֲרַאי, כְּגוֹן טַלִּית שֶׁל קָטָן אַף עַל פִּי שֶׁאֵין הַגָּדוֹל יוֹצֵא בָּהּ \u0010c3\u0011 עֲרַאי.\nלֹא יִלְבַּשׁ אָדָם כִּלְאַיִם עֲרַאי, וַאֲפִלּוּ עַל גַּבֵּי עֲשָׂרָה בְּגָדִים שֶׁאֵינוֹ מְהַנֵּהוּ כְּלוּם; וַאֲפִלּוּ לִגְנֹב אֶת \u0010c4\u0011 הַמֶּכֶס.\nתּוֹפְרֵי כְּסוּת, תּוֹפְרִים \u0010c5\u0011 כְּדַרְכָּם וּבִלְבַד שֶׁלֹּא יִתְכַּוְּנוּ בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וְהַצְּנוּעִין, תּוֹפְרִין בָּאָרֶץ. וְכֵן מוֹכְרֵי כְּסוּת מוֹכְרִין כְּדַרְכָּן, וּבִלְבַד שֶׁלֹּא יִתְכַּוְּנוּ בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וְהַצְּנוּעִים מַפְשִׁילִין בְּמַקֵּל. \u0005הַגָּה: וְיֵשׁ מַתִּירִין אֲפִלּוּ לִלְבֹּשׁ כִּלְאַיִם, כָּל שֶׁאֵינוֹ מְכַוֵּן לַהֲנָאָתוֹ, כְּגוֹן שֶׁלּוֹבֵשׁ כִּלְאַיִם לְהַעֲבִיר בּוֹ הַמֶּכֶס אוֹ שֶׁלּוֹבְשָׁן כְּדֵי לְהַרְאוֹת מִדָּתָן אִם רוֹצֶה לְמָכְרָן וְכַדּוֹמֶה. (טוּר וְהָרֹא\"שׁ וְהַסְמַ\"ג)\u0006.\nתַּכְרִיכֵי הַמֵּת מֻתָּר לַעֲשׂוֹתָן מִכִּלְאַיִם, \u0010c6\u0011 אֲפִלּוּ לְקָבְרוֹ בָּהֶם.\nמַרְדַּעַת הַחֲמוֹר, מֻתָּר לַעֲשׂוֹתָהּ מִכִּלְאַיִם וְיוֹשֵׁב עָלֶיהָ, וְהוּא שֶׁלֹּא יִהְיֶה בְּשָׂרוֹ נוֹגֵעַ בָּהּ. וְלֹא יַנִּיחַ מַרְדַּעַת זוֹ עַל \u0010c7\u0011 כְּתֵפוֹ, אֲפִלּוּ לְהוֹצִיא עָלֶיהָ אֶת הַזֶּבֶל. וְדַוְקָא שֶׁכִּלְאַיִם נִכָּרִים וִידוּעִים בַּבֶּגֶד, אֲבָל בֶּגֶד שֶׁאָבַד בּוֹ כִּלְאַיִם וְאֵין מְקוֹמוֹ נִכָּר, אָסוּר לַעֲשׂוֹת מִמֶּנּוּ מַרְדַּעַת לַחֲמוֹר, דְּכֵיוָן שֶׁאֵין מְקוֹמוֹ נִכָּר שֶׁמָּא יִשְׁכַּח וְיִקַּח מִמֶּנּוּ טְלַאי לְתָפְרוֹ עַל גַּבֵּי בִּגְדּוֹ. וְלֹא יִמְכְּרֶנּוּ לְעוֹבֵד כּוֹכָבִים, שֶׁמָּא יַחֲזֹר וְיִמְכְּרֶנּוּ לְיִשְׂרָאֵל.\nמִטְפָּחוֹת שֶׁמְּקַנְּחִים בָּהֶם אֶת הַיָּדַיִם, וּמִטְפָּחוֹת שֶׁמִּסְתַּפְּגִים בָּהֶם הַכֵּלִים וְהַקַּרְקָעוֹת, וְשֶׁמִּסְתַּפְּגִים בָּהֶם אַחַר הָרְחִיצָה, וּמִטְפְּחוֹת סְפָרִים, אֲסוּרִים מִשּׁוּם כִּלְאַיִם, שֶׁהֲרֵי הַיָּדַיִם נוֹגְעוֹת בָּהֶם וְהֵם נִכְרָכִים עַל הַיָּד תָּמִיד וּמִתְחַמְּמִין. \u0005הַגָּה: וְכֵן אָסוּר לַעֲשׂוֹת מִטְפָּחוֹת שֶׁפּוֹרְסִים עַל הַשֻּׁלְחָן שֶׁאוֹכְלִין עָלָיו (הָרֹא\"שׁ כְּלָל ו' וְחִדּוּשֵׁי אֲגֻדָּה סוֹף בֵּיצָה)\u0006 אוֹ שֶׁקּוֹרִין עָלָיו בְּבֵית הַכְּנֶסֶת, מִכִּלְאַיִם \u0005(הַגָּהוֹת אֲשֵׁרִ\"י פ' בְּנֵי הָעִיר)\u0006, מִפְּנֵי שֶׁלִּפְעָמִים מְקַנֵּחַ בָּהֶם יָדָיו וּמִתְחַמֵּם בָּהֶם.\nמִטְפָּחוֹת שֶׁמִּסְתַּפְּרִין בָּהֶם, אִם יֵשׁ לוֹ בֵּית רֹאשׁ וְלוֹבְשִׁין אוֹתוֹ כְּדֶרֶךְ \u0010c8\u0011 לְבִישָׁה, אָסוּר מִשּׁוּם כִּלְאַיִם.\nוִילוֹן, אִם הוּא רַךְ, אָסוּר לַעֲשׂוֹתוֹ מִכִּלְאַיִם, מִפְּנֵי שֶׁהַשַּׁמָּשׁ מִתְחַמֵּם בּוֹ לִפְעָמִים. וְאִם הָיָה \u0010c9\u0011 קָשֶׁה, מֻתָּר. \u0005הַגָּה: אֲבָל פָּרֹכֶת שֶׁלִּפְנֵי אֲרוֹן הַקֹּדֶשׁ, אוֹ \u0010c10\u0011 הַמַּפּוֹת שֶׁפּוֹרְסִין בָּאָרוֹן אוֹ סְבִיב הַתּוֹרָה, מֻתָּר לִהְיוֹת מִכִּלְאַיִם. (שָׁם בְּהַגָּהוֹת אֲשֵׁרִ\"י)\u0006.\nלֹא יִקַּח אָדָם בֵּיצָה חַמָּה בְּבֶגֶד כִּלְאַיִם בְּיָדוֹ, שֶׁכֵּיוָן שֶׁהוּא נִצּוֹל מִלִּכָּווֹת בְּחֹם הַבֵּיצָה חֲשִׁיבָה הֲנָאָה כִּמְנִיעַת הַקֹּר.\nעַרְדִּילָרִין \u0005(פֵּרוּשׁ כְּלִי שֶׁלּוֹבְשִׁין אוֹתוֹ תַּחַת הַמִּנְעָל, וְיֵשׁ שֶׁעוֹשִׂין אוֹתוֹ שֶׁל צֶמֶר כְּנֶגֶד הֶעָקֵב, אֵין בָּהֶם מִשּׁוּם כִּלְאַיִם, דְּקָשִׁין הֵן)\u0006 \u0005(מִפי' רַשִׁ\"י בְּשֵׁם תְּשׁוּבַת הַגְּאוֹנִים)\u0006 אֵין בָּהֶם מִשּׁוּם \u0010c11\u0011 כִּלְאַיִם. \u0005הַגָּה: מִנְעָל שֶׁהוּא כִּלְאַיִם וְאֵין לוֹ עָקֵב, מֻתָּר לְלָבְשׁוֹ, שֶׁעוֹר הָרֶגֶל קָשֶׁה וְאֵינוֹ נֶהֱנֶה כִּשְׁאָר עוֹר הַגּוּף (טוּר)\u0006.\nאֵין אָסוּר מִשּׁוּם כִּלְאַיִם אֶלָּא בְּגָדִים שֶׁהֵן דֶּרֶךְ חִמּוּם, כְּגוֹן הַכְּתֹנֶת וְהַמִּצְנֶפֶת וְהַמִּכְנָסַיִם וְהָאַבְנֵט וְהַשִּׂמְלָה וּבְגָדִים שֶׁמְּחַפִּין בָּהֶם הַשּׁוֹקַיִם וְאֶת הַיָּדַיִם וְכַיּוֹצֵא בָּהֶם, אֲבָל צִלְצָלִים קְטַנִּים שֶׁעוֹשִׂים אוֹתָם הָעָם בְּבֵית יָד שֶׁלָּהֶם לִצְרֹר בָּהֶם מָעוֹת אוֹ תַּבְלִין, וּסְמַרְטוּט שֶׁמַּנִּיחִים עָלָיו רְטִיָּה, אוֹ מְלוֹגְמָא אוֹ אִסְפַּלְנִית וְכַיּוֹצֵא בָּהֶם, הֲרֵי אֵלּוּ מֻתָּרִים אַף עַל פִּי שֶׁבְּשָׂרוֹ נוֹגֵעַ בָּהֶם, שֶׁאֵין דֶּרֶךְ חִמּוּם בְּכָךְ. צִיץ שֶׁל עוֹר אוֹ מֶשִׁי וְכַיּוֹצֵא בָּהֶם שֶׁתָּלָה בָּהּ חוּטֵי צֶמֶר וְחוּטֵי פִּשְׁתָּן מְדֻלְדָּלִים עַל פְּנֵי הָאָדָם כְּדֵי לְהַפְרִיחַ הַזְּבוּבִים, אֵין בּוֹ מִשּׁוּם כִּלְאַיִם, שֶׁאֵין דֶּרֶךְ חִמּוּם בְּכָךְ.\nאוֹתוֹת שֶׁעוֹשִׂים הַכּוֹבְסִים וְהַגַּרְדִּים \u0005(פי' מַעֲשֵׂה אוֹרֵג (שְׁמוֹת כח, לב, לט, כב כז)\u0006 ת\"י גִּירְדִי) בַּבְּגָדִים כְּדֵי שֶׁיִּהְיֶה מַכִּיר כָּל א' אֶת שֶׁלּוֹ, אִם הָיְתָה אוֹת שֶׁל צֶמֶר בְּפִשְׁתָּן אוֹ פִּשְׁתָּן בְּצֶמֶר הֲרֵי זֶה אָסוּר, אַף עַל פִּי שֶׁאֵינוֹ חָשׁוּב אֶצְלוֹ.",[],["\u0003מותר. \u0004 כתב הש\"ך בכל אלו שהזכיר הרב מותר אפילו מדרבנן מיהו נראה דהיינו שלא יגע בהן:","\u0003וי\"א. \u0004 כ' הש\"ך דצ\"ע מאי וי\"א דהא ליכא מאן דפליג בהא דלכ\"ע כלאים דרבנן מותר לישב עליהם בקשים ואפילו ללבוש שרי בקשים וכתב הט\"ז דבפרישה מבואר דכובע של נשים של סמו\"ט שתופרין לבד בין הסמו\"ט מותר ע\"ש ולפי מ\"ש הרמ\"א שלכתחלה לא יעשה אותה כלאים היה ראוי למחות ביד האומנים בזה וכ\"ש לפי המחמירין שכתב הרמ\"א בס\"ב אלא דכבר כתב הרשב\"א על כיוצא בזה הנח להם מוטב שיהיו שוגגים וכו' וגם משמע לדעת הרמ\"א דאין איסור לישב על אותן העגלות שיש להם אוהל תפור בגד פשתן בבגד צמר וקורין אותן פאקלי\"ט אלא שקשה מ\"ש מוילון שעל הפתח בסי\"א שיש בו משום כלאים מפני שהשמש מתחמם בו לפעמים וה\"נ צידי זה הפאקלי\"ט היושב אצלו הוא מתחמם בזמן הקור והוא איסור גמור ואינו דומה לגיגית ששם אינו נוגע כלל מה שא\"כ כאן בצידי העגלה בפרט כשרבים יושבים שם ונדחק א' לצד הנ\"ל ובאמת שמעתי שקצת אנשי מעשה נזהרים לישב באותה עגלה אבל רוב העולם נוהגין היתר ונראה שהם סומכים שירחיקו עצמם מליגע באותן הצדדין ואף אם לפעמים נוגע בהן מקרי דבר שאינו מתכוין אבל עכ\"פ אזהרה בעינן בזה כל מה דאפשר עכ\"ל:","\u0003בלבישת. \u0004 וה\"ה להציען תחתיו כשבשרו נוגע בהן. ש\"ך:","\u0003עראי. \u0004 אם עכשיו לובשו דרך עראי אסור וכ' הט\"ז דאפי הוא בגד של קטן שאינו מתכסה ראשו ורובו אפילו הכי אסור לגדול לילך בו אפילו לשוק במקום שהוא מתבייש דבכל גווני אסרה תורה כלאים:","\u0003המכס. \u0004 היינו מכס שהוא גזל אפי' לדינא דמלכותא אבל מה שהוא לפי דינא דמלכותא ודאי אסור לגוזלו. ט\"ז:","\u0003כדרכה. \u0004 פירש הט\"ז אע\"פ שבשעת התפירה יש הבגד על ארכובתם כדרך התופרים והטעם דדבר שאינו מתכוין מותר וזה סותר מה שפסק בסמוך דלגנוב המכס אסור בכלאים והא הוי דבר שאינו מתכוין כדאמרינן בהדיא ר\"פ הגוזל בתרא וע\"כ צ\"ל דיש חילוק בדבר דבמכס יש לו הנאה מן הלבישה דבלא הלבישה היה חייב ליתן המכס והוי הנאה הזאת כמו הנאת שאר לובש כלאים משא\"כ במוכרי כסות שאין המכירה תלויה בזה אלא שעושה כן כדי להקל משאו או להראות מדתו והיה אפשר לעשות בדרך אחר וכיון שאינו מתכוין להנאתו מותר עכ\"ל והנה המדקדק בש\"ס בדף קי\"ג קשה דהא מ\"מ גם גבי מכס מקרי דבר שאינו מתכוין וצ\"ל שלא קאמר כן אלא לדעת המקשן אבל לדעת התרצן הוי דבר שמתכוין ואפ\"ה מותר להעביר המכס מאחר שהוא מכס שאין לו קצבה וע\"ש. ובפרישה כ' וצ\"ע היכא דלא עביד מחמת חימום כלל אלא שלא יקלקלו הגשמים את בגדיו אי שרי או לא והט\"ז תמה עליו וכתב דפשוט הוא שבודאי איסור גמור הוא ע\"ש:","\u0003לקברו. \u0004 כתב. הט\"ז וכ\"ש בבגדים שעושין לו להספד דבגדים שקוברין אותו הוא עתיד לעמוד בהם והטעם דכתיב במתים חפשי כיון שמת אדם נעשה חפשי מן המצות:","\u0003כתפו. \u0004 כתב הש\"ך וא\"ל הא בס\"ו מתיר הרמ\"א אפי' בלבישה דבר שאין מתכוין ואמאי אסור כאן במרדעת להוציא עליה זבל הא דבר שאין מתכוין הוא די\"ל דהוצאת זבל שאני דהא אינו נוטל המרדעת אלא כדי שלא ילכלך בגדיו ומתכוין להנאתו להציל בגדיו עכ\"ל:","\u0003לבישה. \u0004 כ' הט\"ז הכלל בזה דכל שהוא מלבוש והוא רך יש בו משום כלאים אף שאינו מתחמם וכל שאינו מלבוש לגוף כהנהו דמטפחות הידים וכו' יש בהם איסור משום דלפעמים יש בהם חימום לידים וכ\"ש בבגד גמור שנותנין עליו או על כתפו להצילו מגשמים פשיטא דאסור מן התורה:","\u0003קשה. \u0004 כ' הש\"ך משמע דאין איסור במה שהוא נהנה שפורסו מפני החמה והגשמים והרוח דדוקא גבי מלבוש הוא דאסרינן אפי' להגין מפני החמה והגשמים אבל לא בוילון:","\u0003המפות. \u0004 וכתב ט\"ז ונראה דודאי אסור לעשות המעיל של ס\"ת שקורין מענטל\"י או המפה שכורכין סביב הס\"ת עצמה מכלאים דהרי אנו רואים שהשמש אוחזם הרבה פעמים בידו ויש לחוש לחימום בעת הקור והרמ\"א לא מיירי מזה אלא מה שעושין בארון הקדש עצמו איזה מפה תחת הס\"ת או סביב התורה אבל אין אותן המפות נכנסות ויוצאות עם הס\"ת אלא נשארו באה\"ק לעולם עכ\"ל:","\u0003כלאים. \u0004 כתב הט\"ז דבדרישה הקשה הא בס\"ג כתב בגד גדול וכלאים מצד א' אסור אפי' צדו השני כו' ולמה מותר כאן ליהנות שאר הרגל מזה שיש כלאים בעקב והאריך בתירוצים ול\"נ דלק\"מ דגבי מלבוש שהוא רך דוקא אמרו כן דאסור אע\"פ שאינו מתחמם וכל שאינו מלבוש אינו אסור אלא דוקא במתחמם משא\"כ כאן אין שם מלבוש על זה כיון דלמטה מוטלת בעור רק שכנגד העקב יש צמר ואי הוה מחמם היה אסור מכח החימום ע\"כ התירו בזה שאין שם חימום ואינו בגד ובזה מתורץ נמי דברי הרמ\"א שכתב מנעל שהוא כלאים ואין לו עקב וכו' והקשו רבים למה כתב ואין לו עקב ולפי מ\"ש אתי שפיר דלפי הנראה הוא ממש כמנעלים שלנו שקורין פאנטאפלי\"ן דהיינו שסביב העקב של רגל אין שם עור מנעל כלל ע\"כ התירו לתת כלאים תחת העור המנעל ממעל לרגליו וכן תחתיו במקום שהרגל עומד עליו מפני שאין שם בגד על הכלאים שיש במנעל שהרי סביב העקב אין שם כלום דאלו היה שם ג\"כ בגד היה אסור מצד שהוא מלבוש אבל עכשיו אין איסור אלא מכח חימום וברגל כולו אין שום חימום וכן נהגו לצאת בפאנטאפלי\"ן שיש שם בגד מבפנים בכל צדדיו אף שתפרו העובד כוכבים בחוטי פשתן אבל אם עשה כן במנעל דהיינו שגם נגד העקב סביב יש עור המנעל וגם שם תפור בבגד אסור מטעם בגד כלאים דאנו חושבין הבגד שתפור מבפנים כאלו הוא בגד בפ\"ע בלא עור המנעל עכ\"ל \u0005(זאקי\"ן שיש שם חוטי פשתן צריך להוציא החוט קודם לבישה. וילון שקורין פארהאנ\"ג שעושין בביתם אסור לעשותן מכלאים. בה\"י)\u0006:"]],["בֶּגֶד צֶמֶר שֶׁאָבַד בּוֹ חוּט שֶׁל פִּשְׁתָּן אוֹ בֶּגֶד פִּשְׁתָּן שֶׁאָבַד בּוֹ חוּט שֶׁל צֶמֶר, צוֹבְעוֹ, שֶׁאֵין הַצֶּמֶר וְהַפִּשְׁתָּן עוֹלִים בְּצֶבַע אֶחָד וּמִיָּד הוּא נִכָּר לוֹ וְשׁוֹמְטוֹ, וְאִם לֹא נִכָּר, הֲרֵי זֶה \u0010c0\u0011 מֻתָּר, שֶׁמָּא נִשְׁמַט וְהָלַךְ לוֹ, שֶׁהֲרֵי בָּדַק וְלֹא מְצָאוֹ. \u0005בַּמֶּה דְּבָרִים אֲמוּרִים, בְּכִלְאַיִם דְּרַבָּנָן. אֲבָל בְּכִלְאַיִם \u0010c1\u0011 דְּאוֹרַיְתָא, אֵין הוֹלְכִין לְהָקֵל בִּסְפֵקָן (טוּר)\u0006.\nהַלּוֹקֵחַ כְּלֵי צֶמֶר מֵהַגּוֹיִים, צָרִיךְ לְבָדְקָן יָפֶה יָפֶה, שֶׁמָּא הֵם תְּפוּרִים בְּפִשְׁתָּן. \u0005וְהַקּוֹנֶה בְּגָדִים מִן הָעוֹבֵד כּוֹכָבִים, צָרִיךְ לְהַתִּיר תְּפִירָתָן וּלְתָפְרָן בְּקָנַבּוֹס (טוּר)\u0006 \u0010c2\u0011 וְאֲפִלּוּ אִם הָעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ שֶׁתְּפָרָן בְּקַנַּבּוֹס, אֵינוֹ נֶאֱמָן. וּבִמְקוֹמוֹת שֶׁהַפִּשְׁתָּן בְּיֹקֶר מִן הַקַנַּבּוֹס, יֵשׁ \u0010c3\u0011 לִסְמֹךְ לְהַתִּיר. \u0005הַגָּה: וְאָסוּר לוֹמַר לְעוֹבֵד כּוֹכָבִים לִתְפֹּר לוֹ בְּגָדִים בְּחוּטֵי קַנַּבּוֹס, אַף עַל פִּי שֶׁפִּשְׁתָּן יוֹתֵר בְּיֹקֶר, דְּנָקֵל לִתְפֹּר בְּפִשְׁתָּן מִבַּקַנַּבּוֹס (רַשְׁבָּ\"א סִימָן תשס\"א)\u0006. אֲבָל אִם נוֹתֵן לוֹ חוּטֵי קַנַּבּוֹס, שָׁרֵי, וְלֹא \u0010c4\u0011 חַיְשִׁינָן לְאַחְלוּפֵי, מֵאַחַר שֶׁיֵּשׁ לַעֲמֹד עַל הַדָּבָר, שֶׁחוּטֵי פִּשְׁתָּן כְּשֶׁמַּדְלִיק כָּבֵה מַהֵר, וְשֶׁל קַנַּבּוֹס הוֹלֵךְ \u0010c5\u0011 וְשׂוֹרֵף \u0005(כֵּן מַשְׁמָע במ\"מ פ\"ח דמ\"א)\u0006. וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מַחְמִירִין \u0005(רַשְׁבָּ\"א הַנַּ\"ל)\u0006. וְיִשְׂרָאֵל הֶחָשׁוּד לִתְפֹּר כִּלְאַיִם, דִּינוֹ כְּעוֹבֵד כּוֹכָבִים. יֵשׁ מַחְמִירִין דְּלֹא יִתְפֹּר בֶּגֶד צֶמֶר בְּקַנַּבּוֹס לָבָן, שֶׁלֹּא יַחְשְׁדוּהוּ שֶׁהוּא פִּשְׁתָּן, וְלָכֵן צוֹבְעִין הַקַנַּבּוֹס. \u0005(מהרי\"ל)\u0006.",[],["\u0003מותר. \u0004 וה\"ה אם ניתק ממנו חוט א' תולין להקל בכלאים דרבנן. ש\"ך:","\u0003דאורייתא. \u0004 והט\"ז כתב דהך בדיקה דצביעה מהני אף בדאורייתא וכן מוכח בש\"ס בהדיא ומ\"ש הטור חילוק זה בין דאורייתא לדרבנן קאי רק אחלוקה שניה שכתב שם או ינתק חוט א' ממנו והוא מותר דבזה שייך לחלק דאין תולין בספק מן התורה להקל. ע\"ש באורך:","\u0003ואפי'. \u0004 לפי שידוע שהישראל מבקש אחר קנבוס ויש לחוש דלהשביח מקחו אומר כן ולכן אפי' לא איתחזק איסורא אינו נאמן. עכ\"ל הש\"ך:","\u0003להתיר. \u0004 היינו דוקא בדיעבד אבל לכתחלה אסור. ש\"ך:","\u0003לאחלופי. \u0004 דכיון דהוא אומן לא מרעא אומנתיה מאחר שיש לעמוד על הדבר. כן הוא בהרב המגיד והר\"ן ושאר פוסקים טעמא דאומן והר\"ב קיצר במובן עכ\"ל הש\"ך:","\u0003ושורף. \u0004 ובס' מע\"מ כתב ושמעתי שחייטין ישראלים בודקים הקנבוס בענין זה שמושכין החוט עד שנמשכין כמין שערות ואם אותן שערות ארוכות הרבה בידוע שהוא קנבוס. עכ\"ל:"]],["הָרוֹאֶה כִּלְאַיִם שֶׁל תּוֹרָה עַל חֲבֵרוֹ, אֲפִלּוּ הָיָה מְהַלֵּךְ בַּשּׁוּק, הָיָה קוֹפֵץ לוֹ וְקוֹרְעוֹ מֵעָלָיו מִיָּד, וַאֲפִלּוּ הָיָה רַבּוֹ. \u0005וְיֵשׁ אוֹמְרִים דְּאִם הָיָה הַלּוֹבֵשׁ \u0010c0\u0011 שׁוֹגֵג, אֵין צָרִיךְ לוֹמַר בַּשּׁוּק, דְּמִשּׁוּם כְּבוֹד הַבְּרִיּוֹת יִשְׁתֹּק, וְאַל יַפְרִישֶׁנּוּ מִשּׁוֹגֵג (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְאִם הָיָה שֶׁל דִּבְרֵיהֶם, אֵינוֹ קוֹרְעוֹ מֵעָלָיו וְאֵינוֹ פּוֹשְׁטוֹ בַּשּׁוּק, עַד שֶׁמַּגִּיעַ לְבֵיתוֹ. \u0005וְכֵן בְּבֵית הַמִּדְרָשׁ אֵין צָרִיךְ לְמַהֵר לָצֵאת (טוּר)\u0006. וְאִם הָיָה שֶׁל תּוֹרָה, פּוֹשְׁטוֹ מִיָּד.\nאָסוּר לְהַלְבִּישׁ אֶת חֲבֵרוֹ כִּלְאַיִם.",[],["\u0003שוגג. \u0004 היינו שאינו יודע כלל שהוא כלאים אבל אם אחר שמצאו ישהנו עליו נמצא שהוא משהה אותו במזיד עליו כן משמע בטור וכ\"כ ב\"י. ש\"ך:"]],["כִּלְאֵי בְּגָדִים \u0010c0\u0011 מֻתָּר לַעֲשׂוֹתָם וּלְקַיְּמָם, וְאֵינָם אֲסוּרִים אֶלָּא בִּלְבִישָׁה.",[],["\u0003לעשותם. \u0004 כתב הש\"ך והא דכתב הרב לעיל סי' ש\"א דלכתחילה לא יעשה של כלאים היינו בדברים שיש לחוש שיתכסה בהן והיינו שעושין אותן לעצמן או לישראל אחר אבל הכא מיירי בענין שאין לחוש לזה כגון שהוא בגד של עובדי כוכבים ועושין אותו לעובדי כוכבים וכה\"ג עכ\"ל:"]],["\u0003הלכות פדיון בכור\u0004\nמִצְוַת עֲשֵׂה לִפְדּוֹת כָּל אִישׁ מִיִּשְׂרָאֵל בְּנוֹ, שֶׁהוּא בְּכוֹר לְאִמּוֹ הַיִּשְׂרְאֵלִית, בְּה' סְלָעִים שֶׁהֵם ק\"כ מָעִים שֶׁהֵם שְׁלֹשִׁים דֶּרְהַמִּים כֶּסֶף מְזֻקָּק. \u0005וְעַיֵּן לְעֵיל סי' רצ\"ד כַּמָּה הִיא הַמָעָה. וְיֵשׁ אוֹמְרִים שֶׁה' סְלָעִים הֵם \u0010c0\u0011 בְּעֵרֶךְ שְׁנֵי זְהוּבִים רייני\"ש, שֶׁהֵם ב' זְהוּבִים פולני\"ש (פִּסְקֵי מהרא\"י סי' מ\"ח)\u0006.\nאֵין הָאִשָּׁה חַיֶּבֶת לִפְדּוֹת אֶת בְּנָהּ \u0005(ל' רַמְבַּ\"ם פ' י\"א מֵהִלְכוֹת בְּכוֹרִים ד\"ב)\u0006.\nאֵלּוּ הַחֲמִשָּׁה סְלָעִים נוֹתְנָן לַכֹּהֵן בְּכֶסֶף אוֹ בִּשְׁוֵה כֶּסֶף מִכָּל דָּבָר שֶׁיִּרְצֶה, חוּץ מִקַּרְקָעוֹת וַעֲבָדִים \u0010c1\u0011 וּשְׁטָרוֹת; וְאִם פָּדָהוּ בָּהֶם, אֵינוֹ פָּדוּי.\nכָּתַב לַכֹּהֵן שֶׁהוּא חַיָּב לוֹ חֲמִשָּׁה סְלָעִים בִּשְׁבִיל פִּדְיוֹן בְּנוֹ, חַיָּב לִתְּנָם לוֹ וּבְנוֹ \u0010c2\u0011 אֵינוֹ פָּדוּי \u0005(טוּר בְּשֵׁם ה\"ג)\u0006. \u0005אָמַר לַכֹּהֵן שֶׁנּוֹתֵן לוֹ לִפְדּוֹת אֶת בְּנוֹ, אָסוּר לַחֲזֹר בּוֹ. מִיהוּ אִם חָזַר, הָוֵי חֲזָרָה\u0006 \u0005(מָרְדְּכַי ס\"פ כָּל הַגֵּט)\u0006 \u0005וְעַיֵּן לְעֵיל סי' רס\"ה.\u0006\nנָתַן לוֹ כְּלִי שֶׁאֵינוֹ שָׁוֶה בַּשּׁוּק חֲמִשָּׁה סְלָעִים, וְקִבְּלוֹ הַכֹּהֵן בַּחֲמִשָּׁה סְלָעִים, הֲרֵי בְּנוֹ פָּדוּי; \u0005(רַמְבַּ\"ם שָׁם)\u0006 וְהוּא \u0010c3\u0011 שֶׁיִּשְׁוֶה חֲמִשָּׁה סְלָעִים לְשׁוּם אָדָם.\nנָתַן לוֹ כְּלִי בְּפִדְיוֹן בְּנוֹ, סְתָם, אִם הוּא שָׁוֶה ה' סְלָעִים, אַף עַל פִּי שֶׁלֹּא שָׁמוּ אוֹתוֹ בִּתְחִלָּה, בְּנוֹ פָּדוּי. \u0005הַגָּה: וְאִם אֵינוֹ שָׁוֶה, אֵין בְּנוֹ פָּדוּי (טוּר)\u0006. וְאִם הַכֹּהֵן רוֹצֶה לְהַחֲזִיק בַּכְּלִי, אֵין צָרִיךְ לְהַחֲזִיר לוֹ, וְהוּא יַשְׁלִים לוֹ עַד ה' סְלָעִים \u0005(מהרי\"ל)\u0006.\nנָתַן ה' סְלָעִים, אֲפִלּוּ לַעֲשָׂרָה כֹּהֲנִים, בֵּין בְּבַת אַחַת בֵּין בָּזֶה אַחַר זֶה, בְּנוֹ פָּדוּי.\nאִם רָצָה הַכֹּהֵן לְהַחֲזִיר לוֹ הַפִּדְיוֹן, רַשַּׁאי \u0005(ל' רַמְבַּ\"ם שָׁם ד\"ח)\u0006 ; אֲבָל לֹא יִתֵּן הוּא לַכֹּהֵן \u0010c4\u0011 עַל מְנַת שֶׁיַּחֲזִיר לוֹ, וְאִם עָשָׂה כֵן \u0010c5\u0011 וְהֶחֱזִיר לוֹ \u0005וְדַעַת הַכֹּהֵן הָיְתָה מִתְּחִלָּה שֶׁלֹּא לְקַבְּלָהּ עַל מְנַת לְהַחֲזִיר (כָּךְ מַשְׁמָע בְּבֵית יוֹסֵף)\u0006, אֵין בְּנוֹ פָּדוּי עַד שֶׁיִּגְמֹר בְּלִבּוֹ לִתֵּן לוֹ מַתָּנָה גְּמוּרָה, וְאִם רָצָה הַכֹּהֵן אַחַר כָּךְ לְהַחֲזִיר יַחֲזִיר. וְלֹא יְהֵא הַכֹּהֵן רָגִיל לְהַחֲזִיר לַכֹּל, שֶׁלֹּא לְהַפְסִיד לִשְׁאָר כֹּהֲנִים, שֶׁמִּתּוֹךְ כָּךְ לֹא יִתְּנוּ הַכֹּל פִּדְיוֹנֵי בְּכוֹרֵיהֶם אֶלָּא לוֹ. אֲבָל לַעֲנִיִּים רַשַּׁאי לְהַחֲזִיר בְּכָל פַּעַם. וְכָל שֶׁכֵּן שֶׁמִּזֶּה הַטַּעַם לֹא יְקַבְּלֵם עַל מְנַת לְהַחֲזִיר; וּמִכָּל מָקוֹם אִם עָבַר וְקִבְּלָם, וּפֵרֵשׁ שֶׁנּוֹתֵן לוֹ עַל מְנַת לְהַחֲזִיר, הַבֵּן פָּדוּי, דְּמַתָּנָה עַל מְנַת לְהַחֲזִיר שְׁמָהּ מַתָּנָה. \u0010c6\u0011 \u0005וְדַוְקָא שֶׁאָמַר: עַל מְנַת לְהַחֲזִיר, אֲבָל אִי אָמַר: הֵא לְךָ ה' סְלָעִים וְתַחֲזִירֵם לִי, לֹא הָוֵי מַתָּנָה וְאֵין בְּנוֹ פָּדוּי (רַשְׁבָּ\"א סי' קצ\"ח ותשנ\"ט)\u0006.\nהִפְרִישׁ חֲמִשָּׁה סְלָעִים לְפִדְיוֹן בְּנוֹ, וְנֶאֶבְדוּ, חַיָּב בְּאַחֲרָיוּתָן עַד שֶׁיָּבוֹאוּ לְיַד כֹּהֵן.\nבְּשָׁעָה \u0010c7\u0011 שֶׁנּוֹתֵן הַפִּדְיוֹן לַכֹּהֵן מְבָרֵךְ: אקב\"ו עַל פִּדְיוֹן הַבֵּן, וְחוֹזֵר וּמְבָרֵךְ: \u0010c8\u0011 שֶׁהֶחֱיָנוּ, וְאַחַר כָּךְ נוֹתֵן הַפִּדְיוֹן לַכֹּהֵן, וְאִם פּוֹדֶה עַצְמוֹ, מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִפְדּוֹת הַבְּכוֹר, וּמְבָרֵךְ: שֶׁהֶחֱיָנוּ \u0005(רַמְבַּ\"ם שָׁם ד\"ה)\u0006. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף הַפּוֹדֶה עַצְמוֹ מְבָרֵךְ: עַל פִּדְיוֹן הַבְּכוֹר, וְכֵן נוֹהֲגִין\u0006 \u0005(טוּר וריב\"ש סי' קל\"א)\u0006. \u0005וְעַיֵּן לְעֵיל סי' רס\"ה. יֵשׁ אוֹמְרִים דְּמַיְיתֵי לֵיהּ לִבְכוֹר קָמֵיה כֹּהֵן וּמוֹדִיעַ לֵיהּ שֶׁהוּא בְּכוֹר פֶּטֶר רֶחֶם, וְהַכֹּהֵן שׁוֹאֵל אוֹתוֹ: בְּמַאי בָּעֵית טְפֵי, בְּבִנְךָ בְּכוֹרְךָ אוֹ חֲמִשָּׁה סְלָעִים דְּמִחְיַּבְתְּ לִפְדּוֹת בָּהֶן, וְהָאָב אוֹמֵר: בִּבְנִי בְּכוֹרִי וְהֵילָךְ חֲמִשָּׁה סְלָעִים בְּפִדְיוֹנוֹ, וּבַהֲדֵי שֶׁנּוֹתֵן לוֹ הַמָּעוֹת מְבָרֵךְ בְּרָכוֹת הַנִּזְכָּרוֹת\u0006 \u0005(טוּר ורא\"ש בְּשֵׁם הַגְּאוֹנִים)\u0006 \u0005וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ, אִם הָאָב אֵצֶל הַבֵּן. אֲבָל אִם אֵינוֹ אֶצְלוֹ, פּוֹדֶה אוֹתוֹ בְּלָאו הָכֵי, אֶלָּא אוֹמֵר לַכֹּהֵן שֶׁיֵּשׁ לוֹ בְּכוֹר לִפְדּוֹתוֹ, וְהוּא אוֹמֵר: בְּמַאי בָּעֵית טְפֵי וְכו'\u0006 \u0005(כֵּן הוּא בְּהַגָּהַת מָרְדְּכַי ס\"פ הָאִשָּׁה וְכֵן כָּתַב הבֵּית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006. \u0005וְאִם הָאָב הָיָה רוֹצֶה לְהַנִּיחַ הַבֵּן לַכֹּהֵן, אֵינוֹ יוֹצֵא, רַק צָרִיךְ לִפְדּוֹתוֹ\u0006 \u0005(פִּסְקֵי מהרא\"י סי' קל\"ה)\u0006. \u0005וְיֵשׁ שֶׁכָּתְבוּ שֶׁנָּהֲגוּ לַעֲשׂוֹת סְעֻדָּה בִּשְׁעַת הַפִּדְיוֹן\u0006 \u0005(שָׁם בְּהַגָּהוֹת מָרְדְּכַי ומהרי\"ל ות\"ה סי' רס\"ט)\u0006. \u0005וְאִם \u0010c9\u0011 יַיִן בָּעִיר, מְבָרֵךְ הַכֹּהֵן עַל הַיַּיִן מִיָּד אַחַר הַפִּדְיוֹן\u0006 \u0005(מהרי\"ל)\u0006. \u0005וְכֵן נוֹהֲגִין עַכְשָׁו כְּדֵי לְפִרְסוּמֵי מִלְּתָא. וְאֵין נוֹהֲגִין לְבָרֵךְ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ\u0006 \u0005(אַבּוּדַרְהַם)\u0006. \u0005וְאֵין הָאָב יָכוֹל לִפְדּוֹת עַל יְדֵי \u0010c10\u0011 שָׁלִיחַ. וְגַם אֵין בֵּית דִּין פּוֹדִין אוֹתוֹ בְּלֹא הָאָב\u0006 \u0005(ריב\"ש סי' קל\"א)\u0006.\nאֵין הַבְּכוֹר רָאוּי לְפִדְיוֹן עַד שֶׁיַּעַבְרוּ עָלָיו שְׁלֹשִׁים יוֹם; וְאַחַר שְׁלֹשִׁים יוֹם יִפְדֶּנּוּ מִיָּד, שֶׁלּא יַשְׁהֶה הַמִּצְוָה. וְאִם חָל יוֹם ל\" א לִהְיוֹת \u0010c11\u0011 בְּשַׁבָּת, אֵין פּוֹדִין אוֹתוֹ בְּשַׁבָּת, אֶלָּא יַמְתִּין עַד יוֹם א'. \u0005יֵשׁ אוֹמְרִים דְּאֵין לַעֲשׂוֹת פִּדְיוֹן הַבֵּן \u0010c12\u0011 בְּחֹל הַמּוֹעֵד (במהרי\"ו בְּשֵׁם סֵפֶר הַמִּצְוֹת מִצְוָה ר\"\u0006 ךָ), וְיֵשׁ מַתִּירִין. \u0005(תּוֹסָפוֹת פ\"ק דמ\"ק)\u0006, וְכֵן עִקָּר.\nמֵת הַבֵּן בְּתוֹךְ שְׁלֹשִׁים, וְאֲפִלּוּ בְּיוֹם שְׁלֹשִׁים, וְכֵן אִם נַעֲשָׂה \u0010c13\u0011 טְרֵפָה קֹדֶם שֶׁעָבְרוּ עָלָיו שְׁלֹשִׁים יוֹם, אֵינוֹ חַיָּב בְּפִדְיוֹן; וַאֲפִלּוּ הִקְדִּים וְנָתַן לַכֹּהֵן הַפִּדְיוֹן, יַחֲזִירֶנּוּ לוֹ. \u0005מֵת לְאַחַר שְׁלֹשִׁים, חַיָּב לִפְדּוֹתוֹ (טוּר)\u0006 וּלְבָרֵךְ עַל הַפִּדְיוֹן, אֲבָל לֹא יְבָרֵךְ שֶׁהֶחֱיָנוּ \u0005(ד\"ע וְכֵן הוּא במהרי\"ק סוֹף שֹׁרֶשׁ מ\"ט)\u0006.\nמִי שֶׁפָּדָה בְּנוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם, אִם אָמַר לֵיהּ: \u0010c14\u0011 מֵעַכְשָׁו, אֵין בְּנוֹ פָּדוּי. וְאִם אָמַר לֵיהּ: לְאַחַר שְׁלֹשִׁים יוֹם, בְּנוֹ \u0010c15\u0011 פָּדוּי וְאַף עַל פִּי שֶׁאֵין הַמָּעוֹת קַיָּמִים לְאַחַר ל' יוֹם. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם אֵין הַמָּעוֹת קַיָּמִים אוֹ שֶׁהֶחֱזִירָן לְאָב תּוֹךְ ל', אֲפִלּוּ בְּדִיעֲבַד אֵין בְּנוֹ פָּדוּי (מהרא\"י בת\"ה סִימָן רס\"ד וּבִכְתָבָיו סִימָן רל\"ד)\u0006 ; וְטוֹב לְהַחְמִיר \u0010c16\u0011 לַחֲזֹר לִפְדּוֹתוֹ. מִי שֶׁהוּא סָפֵק אִם הוּא חַיָּב בְּפִדְיוֹן, פָּטוּר, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nמֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם, הֲרֵי הַבֵּן בְּחֶזְקַת שֶׁלֹּא נִפְדָּה, עַד שֶׁיָּבִיא רְאָיָה שֶׁפְּדָאוֹ אָבִיו. וְאִם מֵת הָאָב לְאַחַר שְׁלֹשִׁים יוֹם, בְּחֶזְקַת שֶׁנִּפְדָּה עַד שֶׁיּוֹדִיעוּהוּ שֶׁצִּוָּה בִּשְׁעַת מִיתָה וְאָמַר שֶׁלֹּא נִפְדָּה.\nעָבַר הָאָב וְלֹא פָּדָה אֶת בְּנוֹ, כְּשֶׁיַּגְדִּיל, חַיָּב לִפְדּוֹת עַצְמוֹ. \u0005וְיֵשׁ מִי שֶׁכָּתַב דְּכוֹתְבִין לוֹ עַל \u0010c17\u0011 טָס שֶׁל כֶּסֶף שֶׁאֵינוֹ נִפְדֶּה וְתוֹלִין לוֹ בְּצַוָּארוֹ, כְּדֵי שֶׁיֵּדַע לִפְדּוֹת עַצְמוֹ כְּשֶׁיַּגְדִּיל (מהרי\"ל)\u0006. הָיָה הוּא לִפְדּוֹת וּבְנוֹ לִפְדּוֹת, יִפְדֶּה עַצְמוֹ תְּחִלָּה, וְאַחַר כָּךְ יִפְדֶּה אֶת בְּנוֹ. וְאִם אֵין לוֹ אֶלָּא כְּדֵי פִּדְיוֹן אֶחָד, יִפְדֶּה עַצְמוֹ.\nאִם אֵין לוֹ נְכָסִים בְּנֵי חוֹרִין כְּדֵי פִּדְיוֹן, אֵין הַכֹּהֵן גּוֹבֶה מֵהַמְשֻׁעְבָּדִים, אַף עַל פִּי שֶׁקָּדַם חוֹב הַפִּדְיוֹן לְחוֹב הַבַּעַל חוֹב.\nאֵין פִּדְיוֹן הַבְּכוֹר תָּלוּי אֶלָּא בְּפֶטֶר רֶחֶם, שֶׁאִם אֵינוֹ בְּכוֹר לְאֵם אַף עַל פִּי שֶׁהוּא בְּכוֹר לְאָב אֵינוֹ חַיָּב בְּפִדְיוֹן. וְאִם יֵשׁ לוֹ כַּמָּה נָשִׁים, וְיֵשׁ לוֹ בְּכוֹר מִכָּל אַחַת וְאַחַת, חַיָּב לִפְדּוֹת אֶת כֻּלָּם.\nכֹּהֲנִים וּלְוִיִּם פְּטוּרִים מִפִּדְיוֹן הַבֵּן. וַאֲפִלּוּ כֹּהֶנֶת וּלְוִיָּה נְשׂוּאָה לְיִשְׂרָאֵל, אֵין הַבֵּן חַיָּב בְּפִדְיוֹן, שֶׁאֵין הַדָּבָר תָּלוּי בָּאָב אֶלָּא בָּאֵם, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל \u0005(בַּמִּדְבָּר ג, יב)\u0006 וְאִם נִתְעַבְּרָה מֵעוֹבֵד כּוֹכָבִים, בֶּן הַלְוִיָּה פָּטוּר מִפִּדְיוֹן, וּבֶן הַכֹּהֶנֶת \u0010c18\u0011 חַיָּב בְּפִדְיוֹן, שֶׁהֲרֵי נִתְחַלְּלָה אִמּוֹ מִן הַכְּהֻנָּה בִּבְעִילַת הָעוֹבֵד כּוֹכָבִים. \u0005הַגָּה: וְאִם הִיא אוֹמֶרֶת שֶׁמִּיִּשְׂרָאֵל נִתְעַבְּרָה, וְהַיִּשְׂרָאֵל מַכְחִישָׁהּ וְאוֹמֵר שֶׁמֵּעוֹבֵד כּוֹכָבִים נִתְעַבְּרָה, הַבֵּן \u0010c19\u0011 פָּטוּר מִן הַפִּדְיוֹן (ת\"ה סִימָן רס\"ד)\u0006.\nכֹּהֵן שֶׁנוֹלַד לוֹ בֵּן חָלָל, מֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם חַיָּב הַבֵּן לִפְדּוֹת אֶת עַצְמוֹ, שֶׁלֹּא זָכָה הָאָב בְּפִדְיוֹנוֹ. וְאִם מֵת הָאָב לְאַחַר שְׁלֹשִׁים יוֹם, כְּבַר זָכָה הָאָב בְּפִדְיוֹנוֹ וִיְרָשׁוֹ בְּנוֹ מִמֶּנּוּ, הִלְכָּךְ יַפְרִישׁ הַפִּדְיוֹן וִיעַכְּבֶנּוּ לְעַצְמוֹ.\nהַשִּׁפְחָה שֶׁנִּשְׁתַּחְרְרָה וְכוּתִית שֶׁנִּתְגַיְּרָה כְּשֶׁהֵן מְעֻבָּרוֹת, וְיָלְדוּ, אַף עַל פִּי שֶׁהוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה, הוֹאִיל וְנוֹלַד בִּקְדֻשָּׁה חַיָּב, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל \u0005(בַּמִּדְבָּר ג, יב)\u0006 וַהֲרֵי פָּטְרוּ רֶחֶם בְּיִשְׂרָאֵל. אֵין יָדוּעַ אִם קֹדֶם שֶׁנִּתְגַיְּרָה אוֹ אַחַר שֶׁנִּתְגַיְּרָה, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nהָעוֹבֶדֶת כּוֹכָבִים וְהַשִּׁפְחָה שֶׁיָּלְדוּ וְאַחַר כָּךְ נִתְגַּיְּרָה וְנִשְׁתַּחְרְרוּ, וְיָלְדוּ אַחַר כָּךְ, פָּטוּר, שֶׁאֵין זֶה פֶּטֶר רֶחֶם.\nבֶּן ח' חֳדָשִׁים שֶׁהוֹצִיא רֹאשׁוֹ וְהוּא חַי, וְהֶחֱזִירוֹ וָמֵת, אוֹ בֶּן ט' שֶׁהוֹצִיא רֹאשׁוֹ, אֲפִלּוּ אַחַר שֶׁמֵּת, וְהֻחְזַר וְאַחַר כָּךְ יָצָא אָחִיו וְיָלְדָה וְלַד קַיָּמָא, אֵינוֹ פֶּטֶר רֶחֶם, שֶׁהֲרֵי נִפְטַר בְּרֹאשׁוֹ שֶׁל רִאשׁוֹן, וּמִשֶּׁתֵּצֵא פַּדַּחְתּוֹ פּוֹטֵר הַבָּא אַחֲרָיו. וְכֵן הַמַּפֶּלֶת כְּמִין בְּהֵמָה, חַיָּה וָעוֹף שֶׁחֲצִי פַּרְצוּף פְּנֵיהֶם דּוֹמֶה לְצוּרַת אָדָם, אוֹ סַנְדָּל אוֹ שִׁלְיָא אוֹ שָׁפִיר מְרֻקָּם \u0005(פי' חֲתִיכָה שֶׁל בָּשָׂר כְּצוּרַת סַנְדָּל וּפי' שִׁלְיָא, הַכִּיס שֶׁהָעֻבָּר מוּנָח בְּתוֹכוֹ וּפי' שַׁפִּיר מְרֻקָם, חֲתִיכָה שֶׁל בָּשָׂר וְיֵשׁ בָּהּ צוּרַת אָדָם, עָרוּךְ)\u0006 אוֹ שֶׁיָּצָא הַוָּלָד מְחֻתָּךְ אֵיבָרִים אֵיבָרִים, הַנּוֹלָד אַחַר כָּל אֶחָד מֵאֵלּוּ אֵינוֹ פֶּטֶר רֶחֶם \u0005(לְשׁוֹן טוּר)\u0006.\nבֶּן ח' חֳדָשִׁים שֶׁהוֹצִיא רֹאשׁוֹ מֵת, וְהַמַּפֶּלֶת שַׁפִּיר מָלֵא דָּם אוֹ מָלֵא מַיִם אוֹ מָלֵא גְּוָנִים, וְהַמַּפֶּלֶת כְּמִין דָּגִים וַחֲגָבִים, שְׁקָצִים וּרְמָשִׂים, וְהַמַּפֶּלֶת לְיוֹם אַרְבָּעִים, הַנּוֹלָד אַחַר כָּל אֵלּוּ בְּכוֹר לְפִדְיוֹן. \u0005וְכָל זְמַן שֶׁאֵין אֵיבָרָיו מְרֻקָּמִים, אֵין פּוֹטֵר הַבָּא אַחֲרָיו, וַאֲפִלּוּ בַּזְּמַן הַזֶּה סוֹמְכִין עַל זֶה (מהרי\"ק שֹׁרֶשׁ קמ\"ג)\u0006.\nיוֹצֵא דֹּפֶן וְהַנּוֹלָד אַחֲרָיו כְּדַרְכּוֹ, שְׁנֵיהֶם פְּטוּרִין. הָרִאשׁוֹן, מִפְּנֵי שֶׁלֹּא יָצָא מֵהָרֶחֶם; וְהַשֵּׁנִי, מִפְּנֵי שֶׁקְּדָמוֹ אַחֵר.\nמִי שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ, וְיָלְדָה זָכָר וּנְקֵבָה, וְאֵין יָדוּעַ אֵיזֶה מֵהֶם יָצָא רִאשׁוֹן, אֵין כָּאן לַכֹּהֵן כְּלוּם. יָלְדָה שְׁנֵי זְכָרִים, אַף עַל פִּי שֶׁאֵין יָדוּעַ אֵיזֶה מֵהֶם הַבְּכוֹר, נוֹתֵן חֲמִשָּׁה סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶם בְּתוֹךְ ל' יוֹם, פָּטוּר, דְּשֶׁמָּא הַבְּכוֹר מֵת וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nמֵת הָאָב קֹדֶם שֶׁפְּדָאָן, בֵּין מֵת תּוֹךְ ל' בֵּין מֵת לְאַחַר ל', וְהַבָּנִים קַיָּמִים, נוֹתְנִין בֵּין שְׁנֵיהֶם ה' סְלָעִים, \u0010c20\u0011 אֲפִלּוּ חָלְקוּ כְּבַר הַנְּכָסִים.\nשְׁתֵּי נָשָׁיו שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן עֶשֶׂר סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶם בְּתוֹךְ ל' יוֹם, אִם לְכֹהֵן אֶחָד נָתַן, יַחֲזִיר לוֹ ה' סְלָעִים; וְאִם לִשְׁנֵי כֹּהֲנִים נָתַן, אֵינוֹ יָכוֹל לְהוֹצִיא מֵהֶם, שֶׁהֲרֵי לֹא עִיֵּן פִּדְיוֹן זֶה עַל בֵּן זֶה, וְכָל אֶחָד יֹאמַר: אֲנִי תּוֹפֵס בִּשְׁבִיל הַחַי. יָלְדוּ זָכָר \u0010c21\u0011 וּנְקֵבָה, אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, נוֹתֵן ה' סְלָעִים לַכֹּהֵן. וְאִם מֵת אֶחָד מֵהַזְּכָרִים תּוֹךְ ל' יוֹם, אֵינוֹ נוֹתֵן לַכֹּהֵן כְּלוּם. יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, וְאֵין יָדוּעַ אֵיזֶה נוֹלַד רִאשׁוֹן, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁאֲנִי אוֹמֵר: נְקֵבָה נוֹלְדָה תְּחִלָּה וְאַחֲרֶיהָ זָכָר \u0005(לְשׁוֹן טוּר)\u0006.\nשְׁתֵּי נָשָׁיו, אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, נוֹתֵן ה' סְלָעִים לַכֹּהֵן, וְאִם מֵת אֶחָד מֵהֶם בְּתוֹךְ ל', אֵין כָּאן לַכֹּהֵן כְּלוּם. וְאִם מֵת \u0010c22\u0011 הָאָב, נוֹתְנִים בֵּין שְׁנֵיהֶם ה' סְלָעִים. זָכָר וּנְקֵבָה, אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם.\nשְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, זֶה נוֹתֵן ה' סְלָעִים וְזֶה נוֹתֵן ה' סְלָעִים. נָתְנוּ, וְאַחַר כָּךְ מֵת אֶחָד מֵהַבָּנִים בְּתוֹךְ ל' יוֹם, אִם לִשְׁנֵי כֹּהֲנִים נָתְנוּ, אֵינָם יְכוֹלִים לְהוֹצִיא מִיָּדָן. וְאִם לְכֹהֵן אֶחָד נָתְנוּ, כּוֹתֵב אֶחָד מֵהֶם הַרְשָׁאָה לַחֲבֵרוֹ, וְיֵלֵךְ זֶה בַּהַרְשָׁאָה וְיוֹצִיא מֵהַכֹּהֵן ה' סְלָעִים. וְאִם יָלְדוּ זָכָר וּנְקֵבָה, וְאֵין יָדוּעַ אֵיזוֹ יָלְדָה זָכָר וְאֵיזוֹ יָלְדָה נְקֵבָה, אוֹ שֶׁיָּלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, וּמֵת אֶחָד מֵהֶם, הָאָבוֹת פְּטוּרִים \u0010c23\u0011 וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ.\nוְכֵן מְבַכֶּרֶת שֶׁלֹּא שָׁהֲתָה אַחַר בַּעֲלָהּ ג' חֳדָשִׁים, וְנִשְּׂאָה וְיָלְדָה זָכָר, סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן, הָאָבוֹת פְּטוּרִים, וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ, וְאִם \u0010c24\u0011 יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שֵׁנִי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, אֵין כָּאן לַכֹּהֵן כְּלוּם.\nשְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים, אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, זֶה שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ, נוֹתֵן ה' סְלָעִים לַכֹּהֵן. זָכָר וּנְקֵבָה אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם.",[],["\u0003בערך. \u0004 כתב הש\"ך דבספר מע\"מ האריך בזה דבעינן ג' רייכ\"ש טאלי\"ר וכתב שאף לדברי הרב אינו עכשיו פחות משני ר\"ט ע\"ש ולכתחלה טוב לצאת ידי כולם עכ\"ל והט\"ז כתב שכל הרוצה לעשות ע\"צ המובחר יתן שוה משקל ה' לו\"ט וקווינ\"ט במשקל של מדינות קיסר ולא במשקל פולין כי זקוק של מדינות קיסר שהוא של ט\"ז לו\"ט הם גדולים הרבה משל פולין באופן אלא שי\"א לו\"ט וקווינ\"ט של קיסר הם זקוק במדינת פולין:","\u0003ושטרות. \u0004 היינו שט\"ח שיש לו על אחרים שאם נתן אותו שט\"ח אין בנו פדוי כיון דאין גופו ממון:","\u0003אינו. \u0004 גזירה שמא יאמרו שפודין בשטרות:","\u0003שישוה. \u0004 ודעת הט\"ז והש\"ך משמע שאפי' אינו שוה לשום אדם כיון שהכהן מקבלו בפירוש בעד ה' סלעים ה\"ז פדוי ע\"ש:","\u0003שיחזיר. \u0004 פי' שאינו גומר בדעתו כלל ליתנו לו לשם מתנה אלא מיד דעתו שנותנו לו עמ\"ל בכה\"ג לא יצא. ש\"ך:","\u0003והחזיר. \u0004 זה לשון הרמב\"ם ע\"פ לשון א' ברש\"י אבל בלשון ב' פירש\"י אפי' לא החזיר אין בנו פדוי וכ\"מ מהרשב\"א והרא\"ש עכ\"ל הש\"ך וכתב הט\"ז דאם היה הכהן ג\"כ חושב שיחזיר לו אז דעותיהם שוות לחזרה והוה פדוי אף אם יחזיר לו אח\"כ דהוי כאומר בפירוש ע\"מ שתחזיר לי וכן המנהג בכל יום שהאב מניח דמי הפדיון בסך הרבה והוא חושב שיחזיר לו והכהן נמי חושב כן ומחזיר לו אח\"כ לפעמים הכל או מחזיק לעצמו איזהו סך קטן. עכ\"ל:","\u0003ודוקא. \u0004 דבכה\"ג גומר בלבו שעה א' לשם מתנה ומה שאמר ע\"מ כאומר מעכשיו דמי כלומר מעכשיו תהא נתונה לך מיהו תחזירהו לי אח\"כ. ש\"ך:","\u0003שנותן. \u0004 כלומר בשעה שהאב מחזיק בידו החמש סלעים ומושיטן לכהן קודם שיוצא מידו ליד כהן מברך ואח\"כ נותנן לו כדי שיברך עובר לעשייחן כ\"כ ב\"י והאחרונים ודלא כמו שקצת נוהגים שכבר הניח המעות לפני הכהן ואח\"כ מברך. ט\"ז:","\u0003שהחיינו. \u0004 משמע דמברך שהחיינו לעולם וע\"ל סי' רס\"ה ס\"ו:","\u0003יין. \u0004 כתב הט\"ז ובעיר שאין בה יין מברכין על שכר שהכל ונראה דבאותן מקומות שאין יין צריך לעשות הפדיון קודם ברכת המוציא על הסעודה דאלו בתוך הסעודה אין מברכין על השכר משא\"כ במקום שיש יין פודין אחר ברכת המוציא:","\u0003שליח. \u0004 והש\"ך כתב בשם כמה גדולי הפוסקים שפסקו להלכה שהאב יכול לפדות ע\"י שליח וכן הב\"ד יכולים לפדותו אם עבר האב ולא פדאו או אם מת האב קודם שנפדה ובט\"ז כתב ונ\"ל דכל זמן שהאב חי יוכל לעשות שליח לפדות משלו במקומו ומטעם זה אבי אביו הרי הוא כאביו וכן אחר יכול לתת משלו במקום האב ולפדות הבכור דהוה כשלוחו אבל אם מת האב לא יפדה עד שיגדיל וכן איתא במהרי\"ל עכ\"ל \u0005(ובנה\"כ השיג באריכות על דבריו ומסקנתו דאם מת יכולין הב\"ד לפדותו וע\"ש)\u0006:","\u0003בשבת. \u0004 משום דהוי כמקח וממכר ומזה הטעם גם ביו\"ט אין פודין אותו ונראה דפודין נמי בלילה מיהו נוהגין לפדות ביום ואם חל יום ל\"א בתענית צבור יש לראות אם הגיע הבן לכ\"ט י\"ב תשצ\"ג קודם יום התענית שהוא יום ל' יש לפדותו ביום ל' אחר כ\"ט י\"ב תשצ\"ג \u0005(ואפשר לומר דמשום סעודה לחוד לא מקדמינן לפדות ביום ל')\u0006 ואם לאו אז יש לפדותו בליל ל\"א של יום התענית אבל אין לפדותו ביום התענית ולעשות סעודה בליל שאחר התענית דליכא פרסומא כה\"ג מיהו שמעתי שנוהגין לפדות ביום התענית ולעשות הסעודה בליל שאחר התענית. עכ\"ל:","\u0003המועד. \u0004 משום דאין מערבין שמחה בשמחה והיש מתירין סבירא להו דלא שייך זה אלא בשמחת אירוסין ונשואין בלבד:","\u0003טרפה. \u0004 כתב הש\"ך נראה דהיינו בודאי טרפות וכה\"ג אפי' חי אח\"כ זמן ארוך פטור מפדיון דלא אמרי' טרפה אינה חיה בודאי טרפה. ובספק טרפה פטור מפדיון דהמע\"ה מיהו אם חי אח\"כ י\"ב חדש חייב דיצא מידי ספק טרפה כיון דחי יב\"ח וע\"ל סי' נ\"ה:","\u0003מעכשיו. \u0004 דמתנה בעלמא היא דהא בתוך שלשים יום לא שייך פדייה כ\"כ רש\"י ואפילו המעות עדיין בעין. ש\"ך:","\u0003פדוי. \u0004 כתב הט\"ז וא\"ל א\"כ אמאי כתב בסי\"א דאם חל בשבת ימתין עד יום א' אמאי לא יפדה ביום ו' ויאמר יהא בני פדוי לאחר ל' תירץ בת\"ה סי' קס\"ט דא\"א לעשות אז הסעודה וברכת פדיון ומהרש\"ל בתשו' סי\"ז כתב באמת דיפדה ביום ו' ויאמר הילך פדיונו ויחול לאחר ל' יום ונוהגים העולם כדברי ת\"ה עכ\"ל:","\u0003לפדותו. \u0004 כ' הט\"ז ונ\"ל דהיינו בלא ברכה דודאי ספק ברכות להקל וה\"ה אם אמר סתם בשעת הפדיון שפדה ביום ל' או שטעה במספר הימים והמעות אינם בעין ביד הכהן דיפדם בלא ברכה אח\"כ ואם פדה ביום הל' סתם ולא אמר לו מעכשיו ולא לאחר ל' יום פסק רש\"ל בתשו' דאם המעות עדיין בעין ביד הכהן הוא פדוי ואם ליתנהו אינו פדוי ומדברי מהרא\"י בפסקיו משמע דאף בסתם הוה כאומר לאחר ל' יום עכ\"ל וגם הש\"ך השיג על מהרש\"ל בזה ע\"ש באורך:","\u0003טס. \u0004 וכ' הש\"ך ולפי מ\"ש לעיל דהב\"ד יכולים לפדותו א\"צ לטס של כסף וגם לרוב פעמים הטס של כסף יבא לאיבוד ע\"כ טוב יותר שיפדוהו הב\"ד \u0005(כשהוא קטן)\u0006:","\u0003חייב. \u0004 לכשיגדיל דהכהנת אינה חייבת לפדות את בנה כמו אשה דעלמא כמ\"ש בס\"ב והישראל בעל הכהנת פשיטא דאינו חייב שהרי אינו אביו שנתעברה מהעובד כוכבים ולפ\"ז אם לא נתעברה מהעובד כוכבים רק שנתחללה בביאת העובד כוכבים ואח\"כ נתעברה מישראל חייב בפדיונו עכ\"ל הש\"ך:","\u0003פטור. \u0004 אף לכשיגדיל דשמא הוא מכזב והיא אומרת אמת ולפ\"ז באשתו גמורה כיון דנאמן לומר דלאו בנו הוא אפי' מכחישתו ממילא ממזר הוא ונתחללה בביאת הבועל חייב הבן בפדיון לכשיגדיל ועדיין צ\"ע לדינא. עכ\"ל הש\"ך:","\u0003חלקו. \u0004 ודעת הטור דאם מת תוך ל' יום אפי' לא חלקו פטורים ואם מת לאחר ל' אפי' לאחר שחלקו חייבים ליתן ה' סלעים בין שניהם וכן דעת הרמב\"ם גופיה בפי' המשנה ותימא שהרב השמיט סברא זו ובפרט שכ\"נ עיקר בש\"ס וכ\"פ הב\"ח דבתוך ל' פטורים אפי' לא חלקו דהמע\"ה. עכ\"ל הש\"ך:","\u0003ונקבה. \u0004 כ' הש\"ך דהיינו שאחת ילדה זכר ואחת נקבה ונתערבו שלא נודע איזה מהן ילדה זכר הרי מ\"מ חייב ה' סלעים לכהן דהא שניהם לידה הראשונה היא להן וכן כשילדו ב' זכרים ונקבה אחת ונתערבו אינו חייב אלא ה' סלעים דהא נוכל לומר זו ילדה ב' זכרים וזו נקבה ואין כאן אלא בכור א' אע\"ג דיכול להיות ג\"כ שזו ילדה זכר וזו ילדה זכר תחלה ואח\"כ נקבה והרי כאן ב' בכורים מ\"מ המע\"ה הלכך כשמת א' מהם תוך ל' אינו נותן לכהן כלום שיכול האב לומר בכור מת. עכ\"ל:","\u0003האב. \u0004 היינו כשמת אחר ל' אבל אם מת האב תוך ל' פטורים כ\"כ ב\"י והאחרונים:","\u0003והבן. \u0004 שהרי בכור ודאי הוא:","\u0003ילדו. \u0004 כ' הט\"ז דזה קאי אסעיף כ\"ט בב' נשים של ב' אנשים ושניהם לא בכרו וקשה למה כתב כאן בב' זכרים וב' נקבות דאז אין כאן בכור ודאי דכל חד אומר נקבה יצאה קודם לו לימא רבותא אפי' בשני זכרים ונקבה אחת דאז הוי א' בכור ודאי ואפ\"ה פטורים שניהם דכל חד ידחה על חבירו לומר דהוא הבכור ובאמת כתב הטור גם בזה דפטורים ונראה דהמחבר אזיל לטעמיה שכתב בסכ\"ו דהבנים חייבים במת אביהם תוך ל' יום ולא מצי כל חד לדחות על חבירו ה\"נ כן הוא אלא דקשה הא ברייתא ערוכה היא כאן דאף בכה\"ג פטור וכו' ע\"ש:"]],["\u0003הלכות בכור בהמה טהורה\u0004\nבְּכוֹר בְּהֵמָה טְהוֹרָה נוֹהֵג בִּזְכָרִים וְלֹא בִּנְקֵבוֹת. וְנוֹהֵג אֲפִלּוּ שֶׁלֹּא בִּזְמַן הַבַּיִת, בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּמִצְוָה לְהַקְדִּישׁוֹ וְלוֹמַר: הֲרֵי זֶה קֹדֶשׁ, שֶׁנֶּאֱמַר: תַּקְדִּישׁ לַה' אֱלֹהֱיךָ \u0005(דְּבָרִים טו, יט)\u0006 וְאִם לֹא הִקְדִּישׁוֹ, מִתְקַדֵּשׁ מֵאֵלָיו מֵרֶחֶם. \u0005נוֹתְנִין אוֹתוֹ לְכֹהֵן, וְלֹא לְכֹהֶנֶת (טוּר)\u0006.\nאֵין נוֹתְנִין הַבְּכוֹר לְכֹהֵן כְּשֶׁיִּוָּלֵד, שֶׁאֵין זוֹ גְּדֻלָּה לַכֹּהֵן, אֶלָּא יְטַפֵּל בּוֹ בְּעָלָיו עַד שֶׁיַּגְדִּיל מְעַט. וְעַד כַּמָּה יִשְׂרָאֵל חַיָּבִים לְהִטָּפֵל בּוֹ, בְּדַקָּה ל' יוֹם; וּבְגַסָה, חֲמִשִּׁים יוֹם. וְאִם אֵין לוֹ כֹּהֵן מָצוּי, חַיָּב לְהִטָּפֵל בּוֹ עַד שֶׁיִּזְדַּמֵּן לוֹ כֹּהֵן.\nאָמַר לֵיהּ הַכֹּהֵן: תְּנֵהוּ לִי תּוֹךְ זְמַן זֶה, וַאֲנִי אֲטַפֵּל לְעַצְמִי, אֵינוֹ רַשַּׁאי לִתְּנוֹ לוֹ, שֶׁזֶּה כְּמוֹ \u0010c0\u0011 מְסַיֵּעַ עַל מַתְּנוֹתָיו. וְאִם הָיָה בַּעַל מוּם וְאָמַר לֵיהּ תּוֹךְ זְמַן זֶה: תְּנֵהוּ לִי שֶׁאוֹכְלֶנּוּ עַתָּה, רַשַּׁאי לִתְּנוֹ לוֹ.\nאִם הַכֹּהֵן מְסָרֵב מִלְּקַבְּלוֹ, מִפְּנֵי שֶׁיֵּשׁ בּוֹ טֹרַח גָּדוֹל בַּזְּמַן הַזֶּה לְהִטָּפֵל בּוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם, אֵינוֹ רַשַּׁאי, מִפְּנֵי שֶׁנִּרְאֶה כִּמְבַזֶּה מַתְּנוֹת כְּהֻנָּה. \u0005הַגָּה: וַאֲפִלּוּ סְפֵק בְּכוֹר, צָרִיךְ הַכֹּהֵן \u0010c1\u0011 לְקַבְּלוֹ מִיַּד יִשְׂרָאֵל הַנּוֹתֵן לוֹ (פִּסְקֵי מהרא\"י סִימָן קס\"ז ומהרי\"ל סִימָן ר\"ד)\u0006. וְדַוְקָא בְּסָפֵק שֶׁבָּא מֵעַצְמוֹ, אֲבָל בְּמָקוֹם שֶׁפָּשַׁע הַיִּשְׂרָאֵל, כְּגוֹן שֶׁקָּנָה פָּרָה חוֹלֶבֶת מִן הָעוֹבֵד כּוֹכָבִים, אוֹ שֶׁהָיָה יָכוֹל לִמְכֹּר הַבְּכוֹר לְעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁנּוֹלַד, וְלֹא עָשָׂה, אֵין הַכֹּהֵן צָרִיךְ לְקַבְּלוֹ \u0005(שָׁם)\u0006. וַאֲפִלּוּ בְּמָקוֹם שֶׁצָּרִיךְ לְקַבְּלוֹ, אָסוּר לְיִשְׂרָאֵל לִתֵּן לוֹ \u0010c2\u0011 לְהַקְנִיטוֹ אוֹ לִנְקֹם מִמֶּנּוּ. \u0005(ג\"ז שָׁם בְּשֵׁם מוֹהֲרַ\"ם)\u0006.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, יַשְׁהֶנּוּ עַד שֶׁיִּפֹּל בּוֹ מוּם, וְשׁוֹחֲטוֹ עַל פִּי \u0010c3\u0011 מֻמְחֶה, וְאוֹכְלוֹ \u0005(בְּכָל מָקוֹם)\u0006, וּמַאֲכִילוֹ אֲפִלּוּ לְעוֹבֵד כּוֹכָבִים \u0005אוֹ \u0010c4\u0011 לִכְלָבִים. (הַגָּהוֹת מָרְדְּכַי פֶּרֶק הָאִשָּׁה שֶׁהָלְכָה)\u0006.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, מוֹכֵר אוֹתוֹ הַכֹּהֵן אֲפִלּוּ לְיִשְׂרָאֵל, תָּמִים חַי, וּבַעַל מוּם חַי וְשָׁחוּט, וּמְקַדֵּשׁ בּוֹ אֶת הָאִשָּׁה, שֶׁהוּא כִּשְׁאָר מָמוֹנוֹ. אֲבָל אֵינוֹ נִמְכָּר בְּמָקוֹלִין, וְאֵינוֹ נִשְׁקָל בְּלִטְרָא. וּמִכָּל מָקוֹם מֻתָּר לִשְׁקֹל בּוֹ \u0010c5\u0011 מָנָה כְּנֶגֶד מָנָה, וּכְנֶגֶד כְּלִי וְקוֹפִיץ \u0005(פִּי' כְּמוֹ סַכִּין גָּדוֹל וְרָחָב וְחִדּוּדוֹ בּוֹלֵט בְּאֶמְצָעִיתוֹ)\u0006. וְהָנֵי מִלֵּי, בְּשָׂרוֹ, אֲבָל חֶלְבּוֹ וְדָמוֹ וְגִידוֹ וְקַרְנָיו, נִמְכָּרִים בְּמָקוֹלִין וְנִשְׁקָלִין בְּלִטְרָא. וְשַׁמְנוֹ שֶׁל גִּיד דִּינוֹ כְּבָשָׂר, כֵּיוָן שֶׁהוּא מֻתָּר מִן הַתּוֹרָה.\nהַבְּכוֹר, \u0010c6\u0011 אֲפִלּוּ בַּעַל מוּם, נֶאֱכָל תּוֹךְ שְׁנָתוֹ. וּמֵאֵימָתַי מוֹנֶה לוֹ, אִם נוֹלַד בַּעַל מוּם מוֹנֶה לוֹ מִיּוֹם שֶׁנּוֹלַד, וְהוּא שֶׁיּוֹדֵעַ שֶׁכָּלוּ לוֹ \u0010c7\u0011 חֳדָשָׁיו, שֶׁהֲרֵי נִרְאֶה לַאֲכִילָה בְּיוֹם לֵידָתוֹ. אֲבָל אִם לֹא יָדַע בְּוַדַּאי שֶׁכָּלוּ לוֹ חֳדָשָׁיו, מוֹנֶה לוֹ מִיּוֹם שְׁמִינִי.\nנוֹלַד לוֹ מוּם תּוֹךְ שְׁנָתוֹ, רַשַּׁאי \u0010c8\u0011 לְקַיְּמוֹ כָּל י\"ב חֹדֶשׁ. נוֹלַד לוֹ מוּם בְּסוֹף שְׁנָתוֹ, מֻתָּר לְקַיְּמוֹ ל' יוֹם מִיּוֹם שֶׁנָּפַל בּוֹ הַמּוּם, וְאַף עַל פִּי שֶׁהוּא מִתְּאַחֵר לְאַחַר שְׁנָתוֹ. כֵּיצַד, כְּגוֹן שֶׁנָּפַל בּוֹ מוּם בְּט\"ו יוֹם לִפְנֵי גְּמַר שְׁנָתוֹ, מַשְׁלִימִים לוֹ ט\"ו יוֹם אַחַר שְׁנָתוֹ. נוֹלַד לוֹ מוּם אַחַר שְׁנָתוֹ, אֵינוֹ רַשַּׁאי לְקַיְּמוֹ אֶלָּא עַד ל' יוֹם, וְיֹאכַל.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, עַד שֶׁלֹּא נִרְאֶה לְהַרְאוֹתוֹ \u0010c9\u0011 לְחָכָם, מְקַיְּמוֹ שְׁתַּיִם וְשָׁלֹשׁ שָׁנִים, וּמִשֶּׁנִּרְאֶה לְהַרְאוֹתוֹ לְחָכָם, אִם נוֹלַד בּוֹ מוּם בְּתוֹךְ שְׁנָתוֹ רַשַּׁאי לְקַיְּמוֹ כָּל י\"ב חֹדֶשׁ. וְאִם נוֹלַד בּוֹ מוּם לְאַחַר שְׁנָתוֹ, מְקַיְּמוֹ ל' יוֹם.\nשָׁנָה שֶׁל בְּכוֹר הִיא שְׁנַת לְבָנָה תְּמִימָה, י\"ב חֹדֶשׁ מִיּוֹם לְיוֹם. וְאִם הָיְתָה שָׁנָה מְעֻבֶּרֶת, נִתְעַבְּרָה לוֹ, וּמוֹנֶה לוֹ י\"ג חֳדָשִׁים.\nנוֹלְדוּ לוֹ שְׁנֵי טְלָאִים, אֶחָד בְּט\"ו שֶׁל \u0010c10\u0011 אֲדָר הָרִאשׁוֹן וְאֶחָד בְּרֹאשׁ חֹדֶשׁ אֲדָר הַשֵּׁנִי, זֶה שֶׁנּוֹלַד בְּרֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי, כֵּיוָן שֶׁהִגִּיעַ יוֹם רִאשׁוֹן בַּאֲדָר שֶׁל שָׁנָה הַבָּאָה עָלְתָה לוֹ שָׁנָה, וְזֶה שֶׁנּוֹלַד בַּחֲצִי אֲדָר הָרִאשׁוֹן לֹא עָלְתָה לוֹ שָׁנָה עַד חֲצִי אֲדָר שֶׁל שָׁנָה הַבָּאָה, הוֹאִיל וְנוֹלַד בְּחֹדֶשׁ הָעִבּוּר מוֹנִים אוֹתוֹ לוֹ.\nעָבַר וְשָׁהָה אוֹתוֹ לְאַחַר זְמַנּוֹ, אֵינוֹ נִפְסָל.",[],["\u0003מסייע. \u0004 בשביל שיתן לו כל מתנותיו והוי כגוזל אחרים. ט\"ז:","\u0003לקבלו. \u0004 היינו שהכהן עושה איסור אם אינו מקבלו אבל מ\"מ לא כייפינן ליה דיכול הכהן לומר לנותן אייתי ראיה דבכור הוא ואטפל בו. ש\"ך:","\u0003להקניטו. \u0004 ואם נראה שעושה כן א\"צ הכהן לקבלו מהרי\"ו וכ' הש\"ך דלא ידע ליישב דברי הרב אם לא שנגיה בדבריו וכצ\"ל ודוקא בספק שבא מעצמו אבל בספק שבא בפלוגתא דרבוותא כגון שקנה פרה חולבת מן העובד כוכבים או שפשע הישראל שהיה יכול למכור הבכור וכו' ומ\"מ צ\"ע לדינא במה שחילק בין ספק מעצמו לספק פלוגתא דרבוותא דבתשובת מהרי\"ל לא משמע הכי דבקנה פרה חולבת מן העובד כוכבים כתב דצריך הכהן לקבלה ולמד מספק בכור אע\"ג שהביא שם סברת הפוסקים אי חלב פוטר בבכורה או לאו אלא נראה דצ\"ל משום דהתם היו כמה ספיקות בפלוגתא דרבוותא שמכר לעובד כוכבים בכסף דהוי מכירה ליש פוסקים כדלקמן סי' ש\"כ ס\"ו וכן בהיתה חולבת דפטור בבכור ליש פוסקים לכך היקל בדבר אבל בספק א' דפלוגתא דרבוותא לבד אין להקל אם לא שמדינא נראה עיקר כמאן דמיקל אלא שמחמירין דבכה\"ג אפשר דאין הכהן צריך לקבלו גם פסק מהרי\"ו דאם כהן עני יש לו בכור ונותנו לכהן עשיר א\"צ לקבלו עכ\"ל:","\u0003מומחה. \u0004 והאידנא ליכא מומחין ובעינן ג' כדלקמן סי' ש\"ט ס\"ב:","\u0003לכלבים. \u0004 כ' הש\"ך דהרבה פוסקים אוסרים ליתנו לכלבים \u0005(דכתיב ואכלת ולא לכלביך)\u0006 לכן יש ליזהר בדבר וגם בעובד כוכבים כתב מהרש\"ל דמ\"מ איסור דרבנן איכא משום בזיון קדשים ואינו רשאי להאכילו אלא דרך זימון שיאכל העובד כוכבים עמו אבל לא למכרו לו אפי' ליתן לו חתיכה חיה וכשהוא טריפה אסור ליהנות ממנו כדלקמן סי' ש\"ז עכ\"ל:","\u0003מנה. \u0004 פירש\"י אם יש לו חתיכת בשר חולין שנשקלה בליטרא יכול לשקול בשר בכור כנגדו והרמב\"ם פי' חלק כחלק כגון שיחלקו אותו לכמה חלקים ונותנין חלק א' בכף מאזנים זה וחלק בכף מאזנים הב' לראות אם מכוונים במשקל:","\u0003אפי'. \u0004 כלומר לא מיבעיא אם בזמן הבית שאינו קרב אלא תוך שנתו אלא אפי' בעל מום בזה\"ז לא ישהנו יותר משנתו. ש\"ך:","\u0003חדשיו. \u0004 דהיינו ט' לגסה וה' לדקה אבל אם לא כלו מונין מיום ח' דאז ראוי לאכילה ואין מונין אלא מעת שנראה לאכילה. ט\"ז:","\u0003לקיימו. \u0004 כ' הש\"ך ומונין לו מיום ח' ללידתו דכיון דלא נולד בעל מום אע\"ג דידוע שכלו לו חדשיו מ\"מ הרי לא נראה לאכילה ביום לידתו דהוה תם וכ\"כ רש\"י ותוס' דלא כהלבוש שהעתיק דברי הב\"י וע\"ש:","\u0003לחכם. \u0004 היינו שלא נזדמן לו חכם ואין זקוק להוליכו במקום שהחכם שם. ש\"ך:","\u0003אדר. \u0004 ה\"ה בשאר דברים דינא הכי כמ\"ש בא\"ח סי' נ\"ה ס\"י לענין שני נערים \u0005(שנולד אחד בט\"ו באדר ראשון והשני נולד בר\"ח אדר שני ובשנת י\"ג אין עיבור דנעשה השני בר מצוה קודם לראשון)\u0006 וע\"ש:"]],["אֵין מַרְגִּילִין בִּבְכוֹר, \u0010c0\u0011 דְּהַיְנוּ לְהַפְשִׁיט עוֹרוֹ שָׁלֵם דֶּרֶךְ מַרְגְּלוֹתָיו.\nשְׁחָטוֹ וְנִמְצָא טְרֵפָה, עוֹרוֹ עִם בְּשָׂרוֹ אָסוּר בַּהֲנָאָה וְטָעוּן קְבוּרָה. \u0005וְלָכֵן טוֹב \u0010c1\u0011 לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים קֹדֶם שְׁחִיטָה. (הַגָּהוֹת מָרְדְּכַי פ' הָאִשָּׁה וְכֵן כָּתַב הַבֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבָה אַשְׁכְּנַזִּית וְהִיא בִּתְשׁוּבַת מהרי\"ל)\u0006.\nצָרִיךְ הַכֹּהֵן לְהַשְׁהוֹתוֹ וּלְגַדְּלוֹ לְעוֹלָם, עַד שֶׁיִּפֹּל בּוֹ מוּם. וְיָכוֹל לְמָכְרוֹ \u0010c2\u0011 אֲפִלּוּ לְיִשְׂרָאֵל, אַף עַל פִּי שֶׁהוּא תָּמִים, וְהַלּוֹקֵחַ יִנְהֹג בּוֹ קְדֻשַּׁת בְּכוֹר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁהַלּוֹקֵחַ קוֹנֶה אוֹתוֹ לְצָרְכּוֹ. אֲבָל אָסוּר לַעֲשׂוֹת בּוֹ \u0010c3\u0011 סְחוֹרָה, דְּהַיְנוּ לִקְנוֹתוֹ כְּדֵי לְהַרְוִיחַ. וְאִם קְנָאוֹ לְצָרְכּוֹ וְלֹא נִצְטָרֵךְ לוֹ, יָכוֹל לַחֲזֹר וּלְמָכְרוֹ.",[],["\u0003להפשיט. \u0004 אפי' בעל מום דנראה כבזיון כאלו מוכרן לצורך מפוח בעודם על הקדשים. ט\"ז:","\u0003למכרו. \u0004 דשמא יהיה טרפה אח\"כ ומהרש\"ל אוסר למכור לעובד כוכבים וכן מסיק בתשובת מהרי\"ל בשם מהרי\"א וכ\"כ מהר\"מ מטיקאטי\"ן עכ\"ל הש\"ך \u0005(ואם מת הבכור נוהגין לקבור בסדין בבה\"ק וצריך לקברן מעט בעומק פן יבא לחטט אחריהם)\u0006:","\u0003אפי'. \u0004 פי' לא מיבעיא לכהן אלא אפי' לישראל אבל לעובד כוכבים אסור. ש\"ך:","\u0003סחורה. \u0004 וע\"ל סי' קי\"ז מדברים האסורים לעשות בהם סחורה:"]],["הַבְּכוֹר אָסוּר \u0010c0\u0011 בְּגִזָּה וַעֲבוֹדָה. וַאֲפִלּוּ אִם עָבַר וּגְזָזוֹ, אוֹ תְּלָשׁוֹ בְּיָדוֹ, אוֹ אֲפִלּוּ נָשַׁר הַצֶּמֶר מֵעַצְמוֹ, אָסוּר בַּהֲנָאָה לְעוֹלָם, לֹא שְׁנָא מֵת מֵעַצְמוֹ לֹא שְׁנָא שְׁחָטוֹ אַחַר כָּךְ, וַאֲפִלּוּ עַל יְדֵי מֻמְחֶה, אֵין הַשְּׁחִיטָה מַתֶּרֶת הַצֶּמֶר שֶׁנִּתְלַשׁ מֵחַיִּים. אֲבָל צֶמֶר הַמְחֻבָּר, הַשְּׁחִיטָה מַתִּירָתוֹ כִּבְשָׂרוֹ.\nאִם נִתְלַשׁ מֵחַיִּים וְעוֹדֶנּוּ מְסֻבָּךְ בִּשְׁאָר הַצֶּמֶר, אֶת שֶׁנִּרְאֶה כִּשְׁאָר צֶמֶר נִתָּר בַּשְּׁחִיטָה, וְאֶת שֶׁאֵינוֹ נִרְאֶה כִּשְׁאָר הַצֶּמֶר, וְהוּא שֶׁעִקָּרוֹ הָפוּךְ כְּלַפֵּי רֹאשׁוֹ, אֵין הַשְּׁחִיטָה מַתִּירָתוֹ.\nכְּשֶׁבָּא לְשָׁחֲטוֹ אוֹ לִרְאוֹת מוּמוֹ, \u0010c1\u0011 \u0005מֻתָּר \u0006 לִתְלֹשׁ הַצֶּמֶר שֶׁל מְקוֹם שְׁחִיטָה, כְּדֵי לַעֲשׂוֹת מָקוֹם לַשְּׁחִיטָה. \u0005וְהַצֶּמֶר שֶׁתָּלַשׁ אָסוּר בַּהֲנָאָה (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006. וְדַוְקָא בַּיָּד, אֲבָל לֹא בִּכְלִי, כְּדֵי שֶׁלֹּא יְהֵא נִרְאֶה כְּגוֹזֵז.\nגִּזַּת בְּכוֹר, אֲפִלּוּ גִּזַּת בַּעַל מוּם, שֶׁנִּתְעָרֵב בְּגִזֵּי חֻלִּין אֲפִלּוּ אַחַת בְּכַמָּה אֲלָפִים, \u0010c2\u0011 כֻּלָּן אֲסוּרוֹת, שֶׁהֲרֵי הוּא דָּבָר חָשׁוּב וּמְקַדֵּשׁ בְּכָל שֶׁהוּא.\nהָאוֹרֵג מְלֹא הַסִיט מִצֶּמֶר בְּכוֹר בְּבֶגֶד, יִדָּלֵק הַבֶּגֶד \u0005הַגָּה: אוֹ יִקָּבֵר (טוּר)\u0006. וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁאָרַג דָּבָר חָשׁוּב, כְּגוֹן צִיּוּר בְּבֶגֶד; אֲבָל אִם אֵינוֹ דָּבָר חָשׁוּב, בָּטֵל \u0010c3\u0011 בְּרֹב \u0005(ג\"ז בַּטּוּר וְרֹא\"שׁ)\u0006.",[],["\u0003בגיזה. \u0004 בין תם בין בעל מום ואפי' הצמר מסובך כן מוכח בסי' שכ\"א ס\"ט. ט\"ז:","\u0003לתלוש. \u0004 בש\"ס איתא ובלבד שלא יזיזנו ממקומו ופירש\"י הטעם מפני שלא יאמרו מום עביד בקדשים אלא יניחנו מסובך עם הצמר מכאן ומכאן:","\u0003אסורות. \u0004 בהנאה וע\"ל סי' ק\"מ:","\u0003ברוב. \u0004 כתב רש\"י סוף תמורה ואי קשיא הא דאמרי' במס' נדה בגד שארג בו כלאים הרי זה לא ימכרנו לעובד כוכבים ואמאי לא ליבטל האי חוט ברוב לאו פירכא היא דבכלאים לא אמרי' בטל ברוב דעיקר האיסור ע\"י תערובות הוא ולא שייך בהו ביטול ברוב ע\"כ ואין להקשות ממ\"ש הטור בסי' ש\"ג בכלאים דרבנן דינתק חוט א' ואמאי לא בטיל ברוב דהא דרבנן היא י\"ל דלענין ביטול ברוב שוינהו רבנן כדאורייתא דכל שישנו בעין אוסר כמו מן התורה דמה דתיקון רבנן כעין דאורייתא תיקון משא\"כ כשמסיר א' דאפשר דאינו בעולם בזה הקילו. עכ\"ל הט\"ז:"]],["בְּכוֹר, בַּזְּמַן הַזֶּה, אֵין בּוֹ הֶתֵּר אֶלָּא עַל יְדֵי מוּם. וַאֲפִלּוּ אִם יִרְצוּ הַבְּעָלִים אוֹ הַכֹּהֵן לְכָנְסוֹ לְכִפָּה עַד שֶׁיָּמוּת מֵעַצְמוֹ, \u0010c0\u0011 אֵינָם רַשָּׁאִים, אֶלָּא צָרִיךְ הַכֹּהֵן לְגַדְּלוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם.\nאֲפִלּוּ כְּשֶׁיִּפֹּל בּוֹ מוּם בְּגָלוּי וְנִכָּר לַכֹּל, כְּגוֹן שֶׁנִּקְטְעָה יָדוֹ אוֹ רַגְלוֹ וְכַיּוֹצֵא בוֹ, אֵינוֹ רַשַּׁאי לְשָׁחֲטוֹ אֶלָּא עַל פִּי מֻמְחֶה, שֶׁיּוֹרֶה לוֹ שֶׁהוּא מוּם הָרָאוּי לִשָּׁחֵט עָלָיו. וְאִם אֵין חָכָם מֻמְחֶה, נִתָּר עַל פִּי ג' בְּנֵי הַכְּנֶסֶת, דְּהַיְנוּ חֲכָמִים קְצָת וְאֵינָם בְּקִיאִים כָּל כָּךְ. וְהָאִדָּנָא דְּלֵיכָּא מֻמְחִין, אֵינוֹ נִשְׁחָט עַל פִּי ג' בְּנֵי הַכְּנֶסֶת אֶלָּא בְּמוּמִין מֻבְהָקִים, כְּגוֹן נִסְמֵית עֵינוֹ וְנִקְטְעָה יָדוֹ וְכַיּוֹצֵא בָּהֶן. וּצְרִימַת הָאֹזֶן הוּא מוּם מֻבְהָק הֵיכָא דְּמִנְכָּר שַׁפִּיר וְנִרְאֶה לָעֵינַיִם שֶׁהוּא יוֹתֵר מֵחֲגִירַת הַצִּפֹּרֶן. וְכֵיצַד צְרִימַת הָאֹזֶן, שֶׁנִּפְגְּמָה בְּחִסָרוֹן מִן \u0010c1\u0011 הַתְּנוּךְ, וְלֹא הָעוֹר שֶׁבִּשְׂפַת הָאֹזֶן, בֵּין שֶׁנִּפְגְּמָה בִּידֵי אָדָם בֵּין שֶׁנִּפְגְּמָה בִּידֵי שָׁמַיִם. \u0005הַגָּה: נֶחְתַּךְ הַזָּנָב לְמַעְלָה מִן הַחוּלְיָא, הָוֵי מוּם (פִּסְקֵי מהרא\"י סי' רמ\"ו)\u0006. וְעוֹד מָנָה בַּעַל הַטּוּר כַּמָּה \u0010c2\u0011 מוּמִין שֶׁשּׁוֹחֲטִין עֲלֵיהֶן בַּזְּמַן הַזֶּה, וְהָרַב שֶׁחִבֵּר סֵפֶר הַזֶּה נִמְשַׁךְ אַחַר דִּבְרֵי הַרַמְבַּ\"ם; וְלִי נִרְאֶה דְּהַסּוֹמֵךְ עַל דִּבְרֵי הַטּוּר הַבְּנוּיִין עַל דַּעַת הָרֹא\"שׁ לֹא הִפְסִיד.",[],["\u0003אינם רשאים. \u0004 משום הפסד קדשים שהרי יש לו היתר ע\"י נפילת מום. כ\"כ הרא\"ש:","\u0003התנוך. \u0004 בפ' מצורע מפרש רש\"י גדר האמצעי שבאוזן ר\"ל הוא הגבוה שבאמצע האוזן שהוא עשוי כעין גדר בפני נקב האוזן. ט\"ז. ובשפת האוזן פירושו אליה הרכה שבאוזן שנקראת עור ששם הדר בריא. כ\"כ רש\"י:","\u0003מומין. \u0004 עיין בלבוש שהביא כל המומין שהם מומין אליבא דכ\"ע וביאורן:"]],["הַשּׁוֹחֵט אֶת הַבְּכוֹר שֶׁלֹּא עַל פִּי חָכָם, \u0010c0\u0011 אֲפִלּוּ הֶרְאָהוּ לְחָכָם אַחַר כָּךְ וּמָצָא בּוֹ מוּם, אָסוּר. וְהוּא הַדִּין בַּזְּמַן הַזֶּה, אִם לֹא הֶרְאָהוּ לִשְׁלֹשָׁה בְּנֵי הַכְּנֶסֶת.\nהַשּׁוֹחֵט הַבְּכוֹר שֶׁלֹּא עַל פִּי מֻמְחֶה, וּמְכָרוֹ וַאֲכָלוּהוּ, מַחֲזִיר לָהֶם הַדָּמִים; לֹא אֲכָלוּהוּ, יִקָּבֵר וְיַחֲזִיר לָהֶם הַדָּמִים.\nמִי שֶׁאֵינוֹ מֻמְחֶה, וְרָאָה אֶת הַבְּכוֹר, וְנִשְׁחַט עַל פִּיו, יִקָּבֵר וִישַׁלֵּם מִבֵּיתוֹ. וְכַמָּה יְשַׁלֵּם, אִם הוּא בְּאֶרֶץ יִשְׂרָאֵל \u0010c1\u0011 מְשַׁלֵּם בְּגַסָה חֲצִי דָּמָיו, וּבְדַקָּה רְבִיעַ דָּמָיו; וּבְחוּץ לָאָרֶץ, בֵּין בְּדַקָּה בֵּין בְּגַסָה חֲצִי דָּמָיו. וְהָאִדָּנָא, שֶׁאַף בְּאֶרֶץ יִשְׂרָאֵל אֵין רֹב שָׂדוֹת שֶׁל יִשְׂרָאֵל, מֻתָּר לְגַדֵּל בְּהֵמָה דַּקָּה אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל, הִלְכָּךְ אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אַף בְּדַקָּה מִשַּׁלֵּם חֲצִי דָּמִים.",[],["\u0003הראהו. \u0004 ובכל מומין אסור גזרה אטו מום המשתנה לאחר מיתה. ט\"ז:","\u0003משלם. \u0004 שאסור לגדל בהמה דקה בא\"י וכמ\"ש בח\"מ סי' תי\"ט הלכך קנסינן ליה דלא לשקול אלא פלגא א\"נ כיון שאסור לגדל בהמה דקה בא\"י א\"כ היה לו טורח גדול בחורשים ובמדברות במקום שאין ישוב לכך די לו בחצי דמים של בהמה גסה. ש\"ך. וכתב הט\"ז ונ\"ל דיחזיר למוכר והמוכר יקברנו לא מיבעיא אם המוכר חפץ בכך פשיטא דחייב לתת לו דהוא רוצה לקיים המצוה ואם אינו חפץ בכך מ\"מ הטירדא עליו מוטלת כיון שהוא הגורם לזה וא\"ל לא יתננו לו כיון שהוא נחשד על כך דלא נחשד לאכלו כמ\"ש בסי' קי\"ט ס\"ב עכ\"ל:"]],["הֶחָשׁוּד לִמְכֹּר בְּכוֹר לְשֵׁם חֻלִּין, אֵין קוֹנִים מִמֶּנּוּ בְּשַׂר צְבָאִים, \u0010c0\u0011 שֶׁדּוֹמֶה לִבְשַׂר עֲגָלִים. וְאֵין לוֹקְחִים מִמֶּנּוּ עוֹרוֹת שֶׁאֵינָם עֲבוּדִים, אֲפִלּוּ שֶׁל נְקֵבָה, שֶׁמָּא יַחְתֹּךְ זִכְרוּתוֹ וְיֹאמַר: שֶׁל נְקֵבָה הוּא. וְאֵין לוֹקְחִין מִמֶּנּוּ צֶמֶר, אֲפִלּוּ מְלֻבָּן. אֲבָל לוֹקְחִין מִמֶּנּוּ צֶמֶר \u0010c1\u0011 טָווּי וּלְבָדִים וְעוֹרוֹת עֲבוּדִים.",[],["\u0003שדומה. \u0004 ויש לחוש שימכור בשר עגל בכור תם ויאמר של צבי הוא:","\u0003טווי. \u0004 וכ\"ש אם הוא אריג שיש טירחא יותר וזהו הטעם בעורות עבודים שאינו מטריח לעבוד עור בכור תם. ט\"ז:"]],["הַנּוֹטֵל שָׂכָר לִהְיוֹת רוֹאֶה בְּכוֹרוֹת, אֵין שׁוֹחֲטִין עַל פִּיו אֶלָּא אִם כֵּן הָיָה מֻמְחֶה גָּדוֹל וְיָדְעוּ בּוֹ חֲכָמִים שֶׁאֵין כְּמוֹתוֹ, וּפָסְקוּ לוֹ \u0010c0\u0011 שָׂכָר עַל הָרְאִיָּה וְהַבִּקּוּר. וְצָרִיךְ שֶׁיִּתְּנוּ לוֹ שְׂכָרוֹ, בֵּין יִהְיֶה הַמּוּם קָבוּעַ וְיַתִּירֶנּוּ, בֵּין אִם לֹא יִהְיֶה קָבוּעַ. וְלֹא יִתְּנוּ לוֹ שָׂכָר עַל הַבְּהֵמָה אֶלָּא פַּעַם אַחַת, וְרוֹאֶה אוֹתָהּ לְעוֹלָם, כָּל זְמַן שֶׁמְּבִיאִין אוֹתָהּ, כְּדֵי שֶׁלֹּא יָבֹא לִידֵי חֲשָׁד.\nאֵין הֶחָכָם רוֹאֶה בְּכוֹר \u0010c1\u0011 לְעַצְמוֹ.\nאֵין רוֹאִין מוּמִין בְּיוֹם טוֹב. אֲבָל אִם רָאָהוּ מֵעֶרֶב יוֹם טוֹב, יָכוֹל לַחֲקֹר עָלָיו בְּיוֹם טוֹב הֵיאָךְ נָפַל בּוֹ הַמּוּם.",[],["\u0003שכר. \u0004 בטור כתב והוא שיהא שכר בטילתו ניכר ואם הוא פועל ומבטל ממלאכתו נותן לו שכרו כפועל דהיינו כמה רוצה ליקח מי שיש לו מלאכה כזו כדי לישב בטל. וכתב הט\"ז דעל ההליכה שהולך לראות נראה פשוט שהיתר גמור הוא ליקח שכר עליה:","\u0003לעצמו. \u0004 כתב הט\"ז הטעם מפני החשד וקשה לי ממ\"ש הרמ\"א סי' י\"ח סעיף י\"ח שנהגו בקצת מקומות שאין אדם שוחט ובודק לעצמו משמע דמדינא מותר שוב ראיתי שבפ\"ב דנגעים הקשה הר\"ש כן וחילק בין היכא דאיתחזק איסורא וכו' ובזה מתורץ נמי במה שבודק לעצמו דנשחטה הותרה וכי תימא א\"כ על השחיטה לא יהיה נאמן על עצמו דהא בהמה בחייה בחזקת איסור עומדת בזה סמכינן על רוב מצויין אצל שחיטה מומחים הם עכ\"ל ובענין ראיית מומין בי\"ט עיין מדינים אלו בא\"ח סי' תצ\"ח סעיף ט':"]],["אָסוּר לְהַטִּיל מוּם בִּבְכוֹר; אֲפִלּוּ לִגְרֹם לוֹ מוּם, כְּגוֹן לִתֵּן דְּבֵלָה עַל גַּבֵּי אָזְנוֹ כְּדֵי שֶׁיִּטְּלֶנָּה הַכֶּלֶב מִשָּׁם וְיִקְטַע אָזְנוֹ עִמָּהּ וְכַיּוֹצֵא בָּזֶה, אוֹ שֶׁאוֹמֵר לְעוֹבֵד כּוֹכָבִים לְהַטִּיל בּוֹ מוּם. וְאִם עָשָׂה מוּם בְּיָדַיִם אוֹ בִּגְרָמָתוֹ, אֵין שׁוֹחֲטִין אוֹתוֹ עַל יָדוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם אַחֵר מֵעַצְמוֹ. וְאִם מֵת, אֵין קוֹנְסִין בְּנוֹ \u0010c0\u0011 אַחֲרָיו, אֶלָּא שׁוֹחֲטִין אוֹתוֹ עַל יָדוֹ.\nאִם עוֹבֵד כּוֹכָבִים אוֹ תִּינוֹק מַטִּיל בּוֹ מוּם מֵעַצְמוֹ, אִם לֹא כִּוֵּן לְהַתִּירוֹ, מֻתָּר, אֲפִלּוּ אִם שָׁאַל: לָמָּה אֵין שׁוֹחֲטִין אוֹתוֹ, וְהֵשִׁיבוּ לוֹ לְפִי תֻּמָּם שֶׁאָסוּר לְשָׁחֲטוֹ עַד \u0010c1\u0011 שֶׁיִּפֹּל בּוֹ מוּם. אֲבָל אִם כִּוֵּן לְהַתִּירוֹ, כְּגוֹן לְאַחַר שֶׁרוֹאֶה שֶׁהִתִּירוּהוּ עַל יְדֵי כָּךְ עוֹשֶׂה כֵּן לַאֲחֵרִים, אָסוּר. \u0005סָפֵק אִם כִּוֵּן לְהַתִּירוֹ אוֹ לֹא, אַזְלִינָן לְקֻלָּא (הַגָּהוֹת מָרְדְּכַי דְּחֻלִּין)\u0006. וְאִם עוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ וְאוֹמֵר שֶׁהַיִּשְׂרָאֵל צִוָּהוּ, \u0010c2\u0011 אָסוּר \u0005(ת\"ה סי' קס\"ט)\u0006.\nאִם אָמְרוּ לְעוֹבֶדֶת כּוֹכָבִים הַמְשָׁרֶתֶת בְּבֵית יְהוּדִי, עַל הַבְּכוֹר, שֶׁאֵין לְאָכְלוֹ בְּלֹא מוּם, וְהָלְכָה וְחָתְכָה אָזְנוֹ, חָשׁוּב לָדַעַת וְאֵין שׁוֹחֲטִין אוֹתוֹ עָלָיו, מִפְּנֵי שֶׁעוֹבֶדֶת כּוֹכָבִים זוֹ \u0010c3\u0011 כִּוְּנָה לְהַתִּירוֹ, וְגַם הָאוֹמְרִים לָהּ שֶׁאֵינוֹ נֶאֱכָל בְּלֹא מוּם כִּוְּנוּ לְכָךְ שֶׁתַּטִּיל בּוֹ מוּם. \u0005הַגָּה: מֻתָּר לִתֵּן בְּכוֹר לְעוֹבֵד כּוֹכָבִים כְּדֵי לְגַדְּלוֹ, וְאִם הִטִּיל הַשּׁוֹמֵר בּוֹ מוּם, מֻתָּר, וְלֹא אַמְרִינָן דְּכִוֵּן לְהַתִּירוֹ, \u0010c4\u0011 אַף עַל פִּי שֶׁיּוֹדֵעַ שֶׁנִּתָּר בְּמוּמוֹ וְשֶׁהוּא בְּכוֹר (פִּסְקֵי מהרא\"י סי' קס\"ח)\u0006.\nהָיָה הַבְּכוֹר רוֹדְפוֹ, וּבָעַט בּוֹ וְעַל יְדֵי כֵן עָשָׂה בּוֹ מוּם, מֻתָּר לְשָׁחֲטוֹ עָלָיו. וַאֲפִלּוּ בָּעַט בּוֹ לְאַחַר \u0010c5\u0011 שֶׁנִּצַּל מִמֶּנּוּ.\nדְּבַר תּוֹרָה, בְּכוֹר שֶׁנָּפַל בּוֹ מוּם עוֹבֵר, מֻתָּר לְהַטִּיל בּוֹ מוּם קָבוּעַ, אֲבָל חֲכָמִים אֲסָרוּהוּ.\nבְּכוֹר שֶׁאָחֲזוֹ דָּם, יַקִּיז וּבִלְבָד שֶׁלֹּא יִתְכַּוֵּן לַעֲשׂוֹת מוּם. וְאִם נַעֲשָׂה בּוֹ מוּם בְּהַקָּזָה זוֹ, הֲרֵי זֶה נִשְׁחָט עָלָיו.\nמֻתָּר לְהַטִּיל מוּם בִּבְכוֹר בַּזְּמַן הַזֶּה \u0010c6\u0011 קֹדֶם שֶׁיָּצָא לַאֲוִיר הָעוֹלָם.",[],["\u0003אחריו. \u0004 דחכמים קנסוהו לדידיה ולא לבנו ולפ\"ז נראה דאם שחטוהו בדיעבד הבשר מותר לאחרים. ש\"ך:","\u0003שיפול. \u0004 בש\"ס איתא דאפי' אמר עד שנעשה בו מום מותר ולא אמרי' דמשמעותו שאתה תעשה בו מום דאזלינן לקולא כיון דאינו אלא קנס דרבנן אפי' בודאי. עכ\"ל הט\"ז:","\u0003אסור. \u0004 כתב הש\"ך ואע\"ג דלעיל סי' ט\"ז סי\"א אמרי' דאין עובד כוכבים מסל\"ת נאמן לעדות אפי' לאיסור וי\"ל דשאני הכא דכיון דאזלינן בתר אומדנא היכא דחזינן דמתכוין העובד כוכבים להתיר האסור א\"כ אומדן דעת הוא דהעובד כוכבים מסל\"ת אומר אמת דאל\"כ למה הטיל בו מום וכ' הט\"ז וע\"כ צ\"ל דמיירי שאין הישראל לפנינו שיוכל להכחישו אבל אם הישראל מכחישו אין העובד כוכבים נאמן:","\u0003כוונה. \u0004 פי' הב\"ח דכיון שהעובדת כוכבים משרתת בבית עליה מוטל לשרת לבעה\"ב בכל מה שהוא להנאתו וטובתו אבל הט\"ז כתב דאין לחלק בין משרתת או לאו והא ראיה שבתשובת הרא\"ש לא הוזכר כלל שהיתה משרתת אלא דהחילוק הוא בין דין זה ובין הדין שנזכר בס\"ב באופן זה דכאן שחתכה האוזן ומחוסר אבר גלוי להם דהוי מומא שהוא דוכתא דאפי' לדידהו הוי מום ובודאי כיוונה להתיר אבל שם שהוא מעשה דקסדור בש\"ס לא חיסר שום אבר אלא ניקבו ברומח לאוזן והוא לא ידע שע\"י כך יתירוהו ע\"כ לא אסרו רק עד אחר שראה שהתירו בכך עכ\"ל:","\u0003שיודע. \u0004 והטעם כ' הש\"ך דהא ודאי לא כוון להתירו דאדרבה הוא רוצה שלא ישחטוהו שהרי היה מקבל שכרו אם יגדלו יותר והט\"ז כ' דמשמע אפי' בכהן מותר בזה וצ\"ע למה יהא נאמן בזה והלא הוא חשוד להטיל בו מום בעצמו ק\"ו שיאמר לעובד כוכבים להטיל בו ובפסקי מהרא\"י כתב דין *) [והמעיין באור זרוע יראה שאין כאן ט\"ס]. זה בישראל שיש לו ספק בכור ע\"כ צ\"ע גבי כהן בזה ובד\"מ כתב בשם א\"ז על בכור שמסרו ישראל לשומר עובד כוכבים והודיעו שהוא בכור ולו משפט מות לקברו שלם בעורו ועובדי כוכבים חוקרים הענין ומודיעים כי במומו כשר וסופו מוכיח כי בא העובד כוכבים במרמה לבעל הבכור וא\"ל דע כי סרסתי העגל ושתק היהודי והבין העובד כוכבים שאמת הדבר ולא עוד אלא שבא היהודי וראה שאינו מסורס ושתק וכראות העובד כוכבים זה הלך וסרסו אח\"כ מיד מותר גמור הוא אותו הבכור וכ\"מ במתני' דבכורות עכ\"ל:","\u0003שניצל. \u0004 ולא אמרי' כדי להתירו נתכוין להטיל בו מום אלא אמרי' צעריה הוא דקמדכר. ש\"ס:","\u0003שיצא. \u0004 דאינו נעשה קודש אלא ביציאתו מרחם ובזמן הבית היה אסור משום הפסד קדשים. ט\"ז. וכ' הש\"ך דמבואר בש\"ס דאע\"פ שיצא מקצת אבריו כל זמן שלא יצא רובו או ראשו בענין דהוי כילוד כמ\"ש לעיל סי' י\"ד ולקמן שי\"ט מותר לעשות בו מום כגון גדי שאזניו ארוכים ונראים בחוץ קודם שיצא כל ראשו שעדיין אינו כילוד יכול לצרום אזנו קודם שיצא רוב ראשו וכן כל כיוצא בזה עכ\"ל:"]],["הַכֹּהֲנִים \u0010c0\u0011 חֲשׁוּדִים לְהַטִּיל מוּם בִּבְכוֹר. אֲפִלּוּ אִם הוּא חָכָם וְיוֹשֵׁב בִּישִׁיבָה, אִם עָשָׂה דָּבָר שֶׁנִּרְאֶה כְּמַעֲרִים, כְּגוֹן שֶׁנָּתַן לִבְכוֹר שְׂעוֹרִים בְּסַל בְּעִנְיָן שֶׁכְּשֶׁיָּבֹא לְאָכְלָם נִפְגָּם שְׂפָתוֹ אוֹ כַּיּוֹצֵא בָּזֶה, אֵין לְשָׁחֲטוֹ עַל אוֹתוֹ הַמּוּם. \u0005וּלְפִיכָךְ כָּל מוּם שֶׁרָאוּי לְבֹא בִּידֵי אָדָם, אֵין שׁוֹחֲטִין אוֹתוֹ עָלָיו, עַד שֶׁיָּעִידוּ שֶׁמֵּעַצְמוֹ נָפַל בּוֹ. (טוּר)\u0006.\nכָּל הַמּוּמִין הָרְאוּיִם לָבוֹא בִּידֵי אָדָם, נֶאֱמָן הָרוֹעֶה עֲלֵיהֶם לוֹמַר: מֵאֲלֵיהֶם נָפְלוּ וְלֹא נַעֲשׂוּ בְּכַוָּנָה, וְיִשְׁחַט עֲלֵיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה הָרוֹעֶה \u0010c1\u0011 יִשְׂרָאֵל וְהַבְּכוֹר בְּיַד הַכֹּהֵן; אֲבָל אִם הָיָה הָרוֹעֶה כֹּהֵן וְהַבְּכוֹר עֲדַיִן הוּא בְּיַד בְּעָלָיו הַיִּשְׂרָאֵל, הֲרֵי זֶה אֵינוֹ נֶאֱמָן, וְחוֹשְׁדִין אוֹתוֹ שֶׁמָּא הוּא הִטִּיל בּוֹ כְּדֵי שֶׁיִּתְּנֶנּוּ לוֹ. \u0005וְיֵשׁ אוֹמְרִים דְּרוֹעֶה כֹּהֵן נֶאֱמָן עַל בְּכוֹר שֶׁל יִשְׂרָאֵל, וְיֵשׁ לְהָקֵל (טוּר בְּשֵׁם הָרֹא\"שׁ וְהָרַמְבַּ\"ן)\u0006.\nכֹּהֵן שֶׁהֵעִיד לְכֹהֵן אַחֵר שֶׁמּוּם זֶה מֵאֵלָיו נָפַל, נֶאֱמָן, וְאֵין חוֹשְׁשִׁין לָהֶם שֶׁמָּא הֵם גּוֹמְלִים זֶה אֶת זֶה. \u0010c2\u0011\nאֲפִלּוּ בָּנָיו וּבְנֵי בֵּיתוֹ שֶׁל כֹּהֵן, מְעִידִין לוֹ עַל הַבְּכוֹר; אֲבָל לֹא אִשְׁתּוֹ, מִפְּנֵי שֶׁהִיא כְּגוּפוֹ.\nעֵד שֶׁהֵעִיד מִפִּי עֵד אַחֵר שֶׁמּוּם זֶה נָפַל שֶׁלֹּא לְדַעַת, נֶאֱמָן. אֲפִלּוּ אִשָּׁה נֶאֱמֶנֶת לוֹמַר: בְּפָנַי נָפַל מוּם זֶה מֵאֵלָיו, וְיִשָּׁחֵט עָלָיו.\nלֹא הָיוּ מֻחְזָקִים בּוֹ שֶׁהוּא בְּכוֹר, וְאָמַר הַכֹּהֵן: בְּכוֹר הוּא זֶה וּמוּם זֶה נָפַל בּוֹ מֵעַצְמוֹ, \u0010c3\u0011 נֶאֱמָן.\nבְּכוֹר שֶׁהָיָה בְּיַד כֹּהֵן, וְנָפַל בּוֹ מוּם, וְהֵעִיד עָלָיו עֵד אֶחָד שֶׁזֶּה הַמּוּם מֵאֵלָיו נָפַל, וְאֵין אָנוּ יוֹדְעִים אִם מוּם זֶה שׁוֹחֲטִין עָלָיו אֶת הַבְּכוֹר, וּבָא הַכֹּהֵן שֶׁהוּא בְּיָדוֹ וְאָמַר: הֶרְאֵיתִי מוּם זֶה \u0010c4\u0011 \u0005 (לְמֻמְחֶה)\u0006 וְהִתִּירוֹ לִשְׁחִיטָה, הֲרֵי זֶה נֶאֱמָן, וְאֵין חוֹשְׁשִׁין שֶׁמָּא לֹא הֶרְאָהוּ.\nוְכֵן נֶאֱמָן הַכֹּהֵן לוֹמַר עַל בְּכוֹר בַּעַל מוּם: בְּכוֹר זֶה נְתָנוֹ לִי \u0010c5\u0011 יִשְׂרָאֵל בְּמוּמוֹ, וְאֵין חוֹשְׁשִׁין שֶׁמָּא הוּא הִטִּילוֹ, דְּמִלְּתָא דַּעֲבִידָא לְגַלּוֹיֵי לָא מְשַׁקְּרֵי בַּה אִנְשֵׁי.\nנֶאֱמָן יִשְׂרָאֵל לוֹמַר: נָתַתִּי בְּכוֹר זֶה לְכֹהֵן בְּמוּמוֹ, אֲפִלּוּ הָיָה טָלֶה וְהִגְדִּיל וְלֹא חַיְשִׁינָן שֶׁמָּא אֵינוֹ מַכִּירוֹ.\nיִשְׂרָאֵל לֹא נֶחְשְׁדוּ עַל הַבְּכוֹרוֹת, אֲפִלּוּ שֶׁלָּהֶם. לְפִיכָךְ יִשְׂרָאֵל שֶׁיֵּשׁ לוֹ סְפֵק בְּכוֹר שֶׁנֶּאֱכַל בְּמוּמוֹ לַבְּעָלִים, \u0010c6\u0011 נֶאֱמָן לוֹמַר שֶׁנָּפַל בּוֹ מוּם מֵעַצְמוֹ.\nאֵין רוֹאִין אֶת הַבְּכוֹר לְיִשְׂרָאֵל עַד שֶׁיְּהֵא כֹּהֵן עִמּוֹ, שֶׁמָּא יֹאמַר לוֹ הַמֻּמְחֶה: מוּם הוּא וּמֻתָּר לִשְׁחֹט עָלָיו, וְיֵלֵךְ וְיִשְׁחֲטֶנּוּ לְעַצְמוֹ וְלֹא יִתְּנֶנּוּ לַכֹּהֵן, שֶׁאַף עַל פִּי שֶׁאֵינוֹ חָשׁוּד לֶאֱכֹל קָדָשִׁים בַּחוּץ, חָשׁוּד הוּא לִגְזֹל מַתְּנוֹת כְּהֻנָּה. לְפִיכָךְ אִם הָיָה חָכָם וְיָדוּעַ שֶׁהוּא מְדַקְדֵּק עַל עַצְמוֹ, רוֹאִים לוֹ. \u0005וְכֵן אִם\u0006 הָיָה הַמּוּם גָּלוּי לַכֹּל, כְּגוֹן שֶׁנִּקְטְעָה יָדוֹ אוֹ רַגְלוֹ, הוֹאִיל וֶהֱבִיאוֹ לְחָכָם הַמֻּמְחֶה הֲרֵי זֶה בְּחֶזְקַת מְדַקְדֵּק עַל עַצְמוֹ, לְפִיכָךְ רוֹאִים לוֹ אַף עַל פִּי שֶׁאֵין עִמּוֹ כֹּהֵן.",[],["\u0003חשודים. \u0004 מפני שיש להם טורח גדול לטפלותו עד שימות. ש\"ך:","\u0003ישראל. \u0004 ולא חיישינן שאומר כן כדי שיאכלנו ממנו. ש\"ך:","\u0003בניו. \u0004 כ' הט\"ז והיינו בדליכא ריעותא דהערמה לפנינו אבל אי איכא ריעותא כהאי שהולך עם כל בני ביתו לחוץ ודוקא באותו פעם נכנס הבכור ויצא חבול אם היינו יודעים שאחד מבני ביתו נשאר שם ודאי חשדינן שע\"כ הוציא השאר והשאיר זה כדי שיטיל בו מום דהערמה גדולה יש כאן אלא דאם אין אנו יודעים בבירור שנשאר שם לא חיישינן שמא נטמן עכ\"ל:","\u0003נאמן. \u0004 דהפה שאסר הוא הפה שהתיר:","\u0003למומחה. \u0004 ואע\"פ שאינו מזכיר שם החכם נאמן ודוקא במומין שאינן מובהקין דלא חיישינן שיתיר מעצמו ויאמר החכם התיר לי דקדשים בחוץ לא אכיל ולמיסמך עילויה במומין שאינן מובהקים לא עבדי אינשי ובודאי הראהו לחכם ושרי ניהליה ולא הוה שרי ליה החכם אא\"כ העידו לפניו דהאי מום נפל בו מאליו. הרא\"ש. אבל במומין מובהקין יש לחוש שמא לא הראהו לחכם דודאי קדשים בחוץ לא אכיל דהא יודע שאינו קדשים כיון דמום מובהק הוא אבל כשמזכיר שם החכם נאמן דלא משקר ומלתא דעבידא לגלויי הוא שהרי יכולים לשואלו ומיהו להמחבר לקמן ס\"ח וסייעתו דבישראל א\"צ לומר ישראל פלוני א\"כ ה\"ה בכל ענין נאמן אפי' אינו מזכיר שם החכם עכ\"ל הש\"ך:","\u0003ישראל. \u0004 והט\"ז כ' דלדעת הרמב\"ם מיירי שידוע לנו מי הוא אותו ישראל שנתן הבכור לכהן אלא שהספק הוא אם נתנו לו בתמימות או במומו ובזה שפיר מירתת שמא ישאלוהו \u0005(ובנה\"כ כ' שאין דבריו נכונים ואדרבה דעת הרמב\"ם דאצ\"ל ישראל פלוני ואפי' אין ידוע לנו מי הוא הישראל דמירתת שמא ישאלו איזה ישראל וישאלו לו וע\"ש)\u0006:","\u0003נאמן. \u0004 כ' הט\"ז והיינו במקום שלא פשע בו אבל אם פשע בו באופן שכתב הרמ\"א סי' ש\"ז ס\"ד דאז א\"צ הכהן לקבלו וצריך הישראל ליטפל בו אז הוי כעם ככהן ואפי' הישראל אינו נאמן לומר מום נפל כמו הכהן:"]],["סָפֵק בְּכוֹר, אֵין הַבְּעָלִים צְרִיכִים לִתְּנוֹ לַכֹּהֵן, אֶלָּא יַשְׁהֶנּוּ עַד שֶׁיִּפֹּל בּוֹ מוּם, \u0010c0\u0011 וְיֹאכְלֶנּוּ. וְאָסוּר בְּגִזָּה וַעֲבוֹדָה. וְאִם תְּקָפוֹ כֹּהֵן, אֵין מוֹצִיאִין אוֹתוֹ \u0010c1\u0011 מִיָּדוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּמוֹצִיאִין אוֹתוֹ מִיַּד הַכֹּהֵן (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006 וְכֵן הִלְכְתָא. וַאֲפִלּוּ אִם נְתָנוֹ לוֹ הַיִּשְׂרָאֵל בַּטָּעוּת, שֶׁהָיָה סָבוּר שֶׁצָּרִיךְ לִתְּנוֹ לוֹ, וְאַחַר כָּךְ נוֹדַע לוֹ, צָרִיךְ הַכֹּהֵן לְהַחֲזִיר לוֹ \u0005(פִּסְקֵי מהרא\"י סִימָן קס\"ו)\u0006.\nיוֹצֵא דֹּפֶן וְשֶׁנּוֹלַד אַחֲרָיו דֶּרֶךְ רֶחֶם, שְׁנֵיהֶם אֵינָם בְּכוֹר; אֲפִלּוּ יָלְדָה נְקֵבָה תְּחִלָּה דֶּרֶךְ דֹּפֶן, וְזָכָר אַחֲרֶיהָ דֶּרֶךְ רֶחֶם, כֵּיוָן שֶׁקְּדָמוֹ אַחֵר. בְּכוֹר שֶׁהוּא טֻמְטוּם, הֲרֵי זֶה סְפֵק בְּכוֹר וְיֵאָכֵל בְּמוּמוֹ לִבְעָלָיו. וְדַוְקָא בְּמֵטִיל מַיִם בִּמְקוֹם נַקְבוּת, אֲבָל אִם מֵטִיל מַיִם בִּמְקוֹם זַכְרוּת, בְּכוֹר וַדַּאי הוּא וְצָרִיךְ לִתְּנוֹ לַכֹּהֵן \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ וְלֹא כְּרַמְבַּ\"ם)\u0006.\nאַנְדְּרוֹגִינוּס הוּא סָפֵק בְּכוֹר, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים.\nמְבַכֶּרֶת שֶׁיָּצְאָה מְלֵאָה וְחָזְרָה רֵיקָנִית, הַבָּא אַחֲרֶיהָ בְּכוֹר, מִסָפֵק, שֶׁמָּא הִפִּילָה דָּבָר שֶׁאֵינוֹ פּוֹטֵר מֵהַבְּכוֹרָה.\nרָחֵל שֶׁיָּלְדָה כְּמִין עֵז, אוֹ עֵז שֶׁיָּלְדָה כְּמִין רָחֵל, פְּטוּרָה מֵהַבְּכוֹרָה, שֶׁנֶּאֱמַר: אַךְ בְּכוֹר שׁוֹר \u0005(וַיִּקְרָא כז, כו)\u0006 עַד שֶׁיִּהְיֶה הוּא שׁוֹר וּבְכוֹרוֹ שׁוֹר. וְאִם הָיָה בּוֹ מִקְצָת סִימָנֵי אִמּוֹ, הֲרֵי זֶה בְּכוֹר וְהוּא בַּעַל מוּם קָבוּעַ, שֶׁאֵין לְךָ מוּם גָּדוֹל מִשִּׁנּוּי בְּרִיָּתוֹ \u0005(לְשׁוֹן רַמְבַּ\"ם פ\"ה מהל' בְּכוֹרוֹת ד\"ו)\u0006.\nפָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹר, וְיֵשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה, הֲרֵי זֶה בְּכוֹר לַכֹּהֵן, הוֹאִיל וּמִין הַחֲמוֹר יֵשׁ בּוֹ דִּין בְּכוֹר. אֲבָל אִם יָלְדָה מִין סוּס אוֹ גָּמָל, אַף עַל פִּי שֶׁיֵּשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה, הֲרֵי הוּא סְפֵק בְּכוֹר; לְפִיכָךְ יֵאָכֵל לִבְעָלָיו, וְאִם תְּפָסוֹ כֹּהֵן אֵין מוֹצִיאִין מִיָּדוֹ. וְהוּא הַדִּין לַחֲמוֹר שֶׁיָּלְדָה כְּמִין סוּס, וְיֵשׁ בּוֹ מִקְצָת סִימָנֵי חֲמוֹר, הֲרֵי זֶה סְפֵק בְּכוֹר. \u0005וּכְבָר נִתְבָּאֵר דְּנָקְטִינַן דְּאִם תְּקָפוֹ כֹּהֵן מוֹצִיאִין מִיָּדוֹ.\u0006\nבְּהֵמָה דַּקָּה שֶׁטִּנְּפָה, דְּהַיְנוּ שֶׁנִּמּוֹחַ הָעֻבָּר וְיָצָא הַמִּחוּי, פְּטוּרָה מֵהַבְּכוֹרָה. וְצָרִיךְ לְהַרְאוֹתוֹ לְרוֹעֶה חָכָם שֶׁיִּרְאֶה אִם הוּא מִחוּי וָלָד. וּבְהֵמָה גַּסָה שֶׁהִפִּילָה \u0010c2\u0011 שִׁלְיָא, פְּטוּרָה מֵהַבְּכוֹרָה; וְהַשִּׁלְיָא עַצְמָהּ אֵין בָּהּ קְדֻשָּׁה, וּמֻתָּר לְהַאֲכִילָהּ לִכְלָבִים. שָׁפְעָה חֲרָרַת דָּם, פְּטוּרָה מֵהַבְּכוֹרָה. וְהַחֲרָרָה תִּקָּבֵר, לְפַרְסְמָהּ שֶׁהִיא פְּטוּרָה מֵהַבְּכוֹרָה.",[],["\u0003ויאכלנו. \u0004 מיהו חייב במתנות כהונה ממ\"נ וע\"ל סי' ס\"א ס\"ב:","\u0003מידו. \u0004 דהשתא ה\"ל הישראל המע\"ה וי\"א דמוציאין דכיון שהישראל יש לו עכ\"פ חזקה דטובת הנאה ליתנו למי שירצה הרי הוא בחזקתו והכהן לעולם נקרא המוציא. ש\"ך. והט\"ז כ' דהטעם הוא הואיל ומתחלה לא בא ליד הכהן בהיתר והוא עצמו היה לו ספק בשעת תפיסה לכך מוציאין מידו וע\"ל סי' ס\"א סכ\"ג:","\u0003שליא. \u0004 שאין שליא בלא ולד וכן חררת דם והחררה תקבר אבל השליא א\"צ לקברה שהכל יודעים שאין שליא בלא ולד לכך אין צריך פרסום. ט\"ז וש\"ך:"]],["הַלּוֹקֵחַ בְּהֵמָה מֵהָעוֹבֵד כּוֹכָבִים, וְאֵין יָדוּעַ אִם בִּכְּרָה וְיָלְדָה, הֲרֵי זֶה סְפֵק בְּכוֹר, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים, וְאֵינוֹ לַכֹּהֵן, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. בֵּין אִם לְקָחָהּ תּוֹךְ שָׁנְתָה, אוֹ אַחַר שְׁנָתָהּ, \u0010c0\u0011 וַאֲפִלּוּ אִם הָעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ שֶׁכְּבָר בִּכְּרָה, אֵינוֹ נֶאֱמָן. \u0005וְסִימָנִים שֶׁבְּחִדְקֵי קַרְנֶיהָ אֵין מַעֲלֶה וְלֹא מוֹרִיד לִסְמֹךְ עֲלֵיהֶם (הַגָּהוֹת מָרְדְּכַי פ' הָאִשָּׁה)\u0006.\nלָקַח בְּהֵמָה \u0010c1\u0011 מֵינִיקָה מֵהָעוֹבֵד כּוֹכָבִים, אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל אַחֶרֶת הִיא מֵינִיקָה, אֶלָּא הֲרֵי זוֹ בְּחֶזְקָת שֶׁיָּלְדָה. וַאֲפִלּוּ הָיָה זֶה שֶׁמֵּינִיקָה כְּמוֹ מִין אַחֵר, וַאֲפִלּוּ כְּמִין חֲזִיר, פְּטוּרָה מֵהַבְּכוֹרָה.\nוְכֵן בְּהֵמָה שֶׁהִיא חוֹלֶבֶת, פְּטוּרָה מֵהַבְּכוֹרָה, שֶׁרֹב הַבְּהֵמוֹת אֵינָן חוֹלְבוֹת אֶלָּא אִם כֵּן יָלְדוּ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין סוֹמְכִין עַל מַה שֶּׁהִיא חוֹלֶבֶת (טוּר בְּשֵׁם ה\"ג וְהַגָּהוֹת מָרְדְּכַי פֶּרֶק הָאִשָּׁה)\u0006, וְכֵן פָּסְקוּ הָאַחֲרוֹנִים \u0005(מהרא\"י בִּפְסָקָיו סִימָן קס\"ו ובת\"ה סִימָן רע\"א ומהרי\"ו סִימָן קע\"ד)\u0006, וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ. מִיהוּ אִם יֵשׁ עוֹד צַד הֶתֵּר לָזֶה, אוֹ שֶׁעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ שֶׁלֹּא לְהַשְׁבִּיחַ מִקְּחוֹ, וְאוֹמֵר שֶׁיָּלְדָה, סוֹמְכִין לְהַתִּיר. וְדַוְקָא בְּפָרוֹת, וּבְמָקוֹם שֶׁלֹּא נִשְׁמַע שֶׁחוֹלְבוֹת בְּלֹא וָלָד; אֲבָל בְּעִזִּים, שֶׁדֶּרֶךְ שֶׁחוֹלְבוֹת בְּלֹא וָלָד, לֹא סָמְכִינַן עַל כָּךְ אֲפִלּוּ בְּמָקוֹם דְּאִכָּא סְפֵק \u0010c2\u0011 סְפֵקָא, כְּגוֹן שֶׁיָּלְדָה ב' וְאִכָּא לְמֵימַר אָכַל אֶחָד דְּאֵינוֹ בְּכוֹר, אֲפִלּוּ הָכִי אָסוּר \u0005(פִּסְקֵי מהרא\"י סִימָן ק\"ל)\u0006. ונ\"ל דִּבְמָקוֹם דְּאֵין דֶּרֶךְ הָעִזִּים בְּכָךְ, אוֹ שֶׁדֶּרֶךְ הַפָּרוֹת בְּכָךְ, אֵין לְחַלֵּק, וְיֵשׁ לַחֲקֹר אַחַר זֶה.\nבְּהֵמָה שֶׁרְאִינוּהָ חוֹלֶבֶת, וְיָדַעְנוּ שֶׁלֹּא יָלְדָה, אִם אַחַר כָּךְ רְאִינוּהָ מֵינִיקָה וְלֹא יָדַעְנוּ אִם יָלְדָה אוֹתוֹ וָלָד אִם לֹא, הֲרֵי זֶה בְּחֶזְקָת \u0010c3\u0011 שֶׁיְּלָדַתּוּ.\nמִי שֶׁיֵּשׁ לוֹ בְּעֶדְרוֹ מַבְכִּירוֹת, וְשֶׁאֵין מַבְכִּירוֹת, וְיָלְדוּ, וְלֹא הָיָה שָׁם אָדָם, וּמוֹצֵא מַבְכִּירוֹת מֵינִיקוֹת נְקֵבוֹת וְשֶׁאֵינָן מַבְכִּירוֹת מֵינִיקוֹת זְכָרִים, אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל זוֹ בָּא לוֹ אֵצֶל זוֹ וְשֶׁל זוֹ אֵצֶל זוֹ, אֶלָּא הַדָּבָר \u0010c4\u0011 בְּחֶזְקָתוֹ שֶׁכָּל אַחַת מֵינִיקָה אֶת בְּנָהּ.\nהַלּוֹקֵחַ בְּהֵמָה מִיִּשְׂרָאֵל, הֲרֵי זֶה בְּחֶזְקַת שֶׁבִּכְּרָה, עַד שֶׁיּוֹדִיעוֹ הַמּוֹכֵר שֶׁעֲדַיִן לֹא יָלְדָה. \u0005וְיֵשׁ אוֹמְרִים שֶׁהוּא \u0010c5\u0011 סְפֵק בְּכוֹר (טוּר בְּשֵׁם הָרֹא\"שׁ והר\"ר יוֹנָה)\u0006.",[],["\u0003ואפי'. \u0004 כתב הש\"ך דמשמע מדברי הרב בס\"ג דאפילו מסל\"ת שלא להשבית מקחו לא מהני אי לאו דחולבת:","\u0003מניקה. \u0004 היינו שידענו שהיתה חולבת אע\"פ שלא ילדה כבר דאל\"כ כיון דחולבת פוטר בבכורה לדעת המחבר בס\"ג א\"כ בלא\"ה פטור מבכורה וגם זה שמניקתו היה פטור מבכורה אפי' אי הוה נולד בבית ישראל אלא ודאי כדאמרן. ש\"ך:","\u0003ספקא. \u0004 כתב הש\"ך לאו למימרא דס\"ס גמור לא מהני דהא ודאי ס\"ס שרי בכל דוכתי אלא ר\"ל ס\"ס כי האי דלא הוי ס\"ס גמור לא סמכינן אמה שהיא חולבת ובט\"ז כתב דצ\"ע למעשה באם ילדה ב' גדיים א' זכר וא' נקבה דאיכא ס\"ס גמור ספק שמא ילדה כבר קודם שנולדו אלו ואת\"ל לא ילדה מ\"מ שמא הזכר נולד אחרון וליכא כאן בכור כלל וכו' ע\"ש וכ' עוד מעשה בא' שהיה לו חוב אצל עובד כוכבים ותבעו ואמר שאין לו מעות לשלם רק פרה א' והוליכו לחצר והראה לו פרה א' ועגל עומד אצלה אבל לא הניקה אותו ואמר העובד כוכבים פרה זו בלא ולד אתן לך \u0005(בעד ח' זהובים)\u0006 כי אגדל לעצמי הולד ואמר הישראל אני חושב שפרה זאת זקנה היא וזה ולד ששי או שביעי שלה ואני חפץ בפרה ילדה וכל שהיא ילדה ביותר אוסיף בדמיה השיבו העובד כוכבים מה אומר לך שהיא ילדה ביותר זה אינו אבל מ\"מ אינה זקנה כ\"כ כמו שתאמר ותאמין לי שזהו ולד רביעי שלה לא יותר וקבלה ממנו ואח\"כ ילדה אצל הישראל מה דינו והאריך בדין זה ומסיק מאחר שראה העובד כוכבים שהישראל חפץ יותר בפרה ילדה ואף שיכולים לומר שחשב העובד כוכבים שמא אינה רוצה הישראל בפרה שלא בכרה עדיין מחמת שיש עליה סכנת לידה ונתכוין דוקא להיות לו פרה שכבר ילדה מ\"מ היה לו לעובד כוכבים לומר שזה ולד הראשון שלה ואז אשתבוחי הוי משתבח ולמה הפסיד נפשיה לומר שהוא ולד ד' שלה אלא ודאי דקושטא קאמר וסמכינן עליו שכבר ילדה אצלו וזה הולד שילדה אצל הישראל אינו בכור כלל עכ\"ל:","\u0003שילדתו. \u0004 כתב הש\"ך לאו למימרא דודאי ילדתו דליתא אלא אשמועינן דאותו ולד שילדה אח\"כ בבית ישראל חייב בבכורה דהרי הוא בחזקת שילדתו כלומר שמא ילדתו והוי ספק בכור ויאכל במומו לבעלים והבא אחריו פטור מבכורה ממ\"נ דאפי' תימא לא ילדתו מ\"מ אינה מרחמת עליו אא\"כ ילדה וכדלעיל ס\"ב עכ\"ל:","\u0003בחזקתו. \u0004 כתב הש\"ך בכאן אמרינן ודאי הוא כן ולא הוי אפי' ספק בכור ואע\"פ דאמרינן שמרחמת ולד אחר מ\"מ במקום דידה לא שבקת דידה ומרחמת דלאו דידה וכן אמרי' בש\"ס עכ\"ל:","\u0003ספק. \u0004 הטעם דשמא קא סבר המוכר דלשחיטה בעי לה לכך לא הודיעו ובזה אתי שפיר הא דלעיל סי' ט\"ז ס\"ז גבי אותו ואת בנו דאמרינן דמסתמא שרי דאל\"כ היה מודיע שעל המוכר להודיע משום דהתם נמי כי נימא דלשחיטה קבעי לה אסור משום או\"ב עכ\"ל הש\"ך ובט\"ז מתרץ בענין אחר דהתם אמרינן שפיר אם יש איסור היה מודיע שאין שום סברא כנגדו משא\"כ כאן שיש ב' סברות מכחישות זא\"ז דהיינו אם איתא שבכרה כבר אשבוחי הוי משבח וסברא כנגדה אם איתא דלא בכרה עדיין ה\"ל להודיע לאפרושי מאיסורא ע\"כ נשאר הדבר בספק עכ\"ל:"]],["שְׁנַיִם שֶׁהִפְקִידוּ אֵצֶל אֶחָד שְׁנֵי זְכָרִים, אֶחָד בְּכוֹר וְאֶחָד פָּשׁוּט, וּמֵת אֶחָד מֵהֶם וְאֵינוֹ יוֹדֵעַ אֵיזֶה \u0005(מֵת)\u0006, מַנִּיחַ הַנִּשְׁאָר בֵּינֵיהֶם, וְהוּא בֵּין \u0010c0\u0011 שְׁנֵיהֶם, וְדִינוֹ כִּסְפֵק בְּכוֹר.\nמִי שֶׁהִפְקִיד בְּכוֹר אֵצֶל חֲבֵרוֹ, וְלַחֲבֵרוֹ פָּשׁוּט \u0005(פי' שֶׁאֵינוֹ בְּכוֹר)\u0006, וּמֵת אֶחָד מֵהֶם, הַמּוֹצִיא מֵחֲבֵירוֹ עָלָיו הָרְאָיָה; וְכֵיוָן שֶׁהַנִּפְקָד מֻחְזָק, יַחֲזִיקֶנּוּ וְיֹאכְלֶנּוּ מִמּוּמוֹ.\nרוֹעֶה כֹּהֵן שֶׁנָּתַן בְּהֵמוֹת בַּחֲצַר בַּעַל הַבַּיִת, וְיָלְדָה אַחַת מֵהֶן בְּכוֹר, וְנִתְעָרְבוּ עִם שֶׁל בַּעַל הַבַּיִת, וּמֵת אֶחָד מֵהֶם, הָוֵי לֵיהּ בַּעַל הַבַּיִת \u0010c1\u0011 מֻחְזָק וְיֹאכְלֶנּוּ בְּמוּמוֹ.",[],["\u0003שניהם. \u0004 ר\"ל בין הכהן ובין מי שהפקיד הפשוט וכשיפול בו מום יחלקו בין שניהם אלו. ט\"ז:","\u0003מוחזק. \u0004 ולא אמרינן כיון שהכהן הוא רועה שלו ודאי הקנה לו חצרו כדי שיקנה הכהן את הבכור מיד כשיולד כי ניחא ליה למיעבד מצוה זו גם בממונו שיגדלו בכורותיו של כהן בחצרו וה\"ל כשנים שהפקידו דלעיל בס\"א אלא במקום פסידא לא אמרינן דניחא ליה למיעבד מצוה וכו' והבעה\"ב עדיין מוחזק בו והמע\"ה עכ\"ל הש\"ך:"]],["רָחֵל שֶׁלֹּא בִּכְּרָה וְיָלְדָה שְׁנֵי זְכָרִים, אֲפִלּוּ יָצְאוּ שְׁנֵי רָאשֵׁיהֶם כְּאֶחָד, אִי אֶפְשָׁר שֶׁלֹּא קָדַם אֶחָד, הוֹאִיל וְאֵין יָדוּעַ אֵיזֶה יָצָא רִאשׁוֹן, הַכֹּהֵן נוֹטֵל אֶת הַכָּחוּשׁ וְהַשֵּׁנִי \u0010c0\u0011 סְפֵק בְּכוֹר. מֵת אֶחָד מֵהֶם, אֵין לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סָפֵק הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְכֵן אִם יָלְדָה זָכָר וּנְקֵבָה, הֲרֵי הַזָּכָר סָפֵק שֶׁמָּא הַנְּקֵבָה יָצְאָה תְּחִלָּה, לְפִיכָךְ אֵין לַכֹּהֵן כְּלוּם שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nשְׁתֵּי רְחֵלוֹת שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים, שְׁנֵיהֶם לַכֹּהֵן, זָכָר וּנְקֵבָה, הַזָּכָר לַכֹּהֵן; שְׁנֵי זְכָרִים וּנְקֵבָה, הַכֹּהֵן נוֹטֵל אֶת \u0010c1\u0011 הַכָּחוּשׁ וְהַשֵּׁנִי סְפֵק בְּכוֹר; וְאִם מֵת אֶחָד מֵהֶם, אֵין לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סְפֵק בְּכוֹר הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nיָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, הֲרֵי הַזְּכָרִים סָפֵק, שֶׁאֲנִי אוֹמֵר: שֶׁמָּא הַנְּקֵבָה נוֹלְדָה תְּחִלָּה וְאַחַר כָּךְ הַזָּכָר, לְפִיכָךְ אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nאַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, אֶחָד לוֹ וְאֶחָד לַכֹּהֵן, וְכָל אֶחָד מֵהֶם סְפֵק בְּכוֹר, וְהַכֹּהֵן נוֹטֵל הַכָּחוּשׁ. מֵת אֶחָד מֵהֶם, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סָפֵק הוּא. וְכֵן אִם יָלְדוּ זָכָר וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַזָּכָר סָפֵק בְּכוֹר הוּא.\nגֵּר שֶׁנִּתְגַּיֵּר, סָפֵק בִּכְּרָה בְּהֶמְתּוֹ קֹדֶם שֶׁנִּתְגַּיֵּר סָפֵק אַחַר כָּךְ, הָוֵי סָפֵק, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים.\nכָּל שֶׁהוּא סְפֵק בְּכוֹר, יִרְעֶה עַד שֶׁיִּפֹּל בּוֹ מוּם, וְיֵאָכֵל לִבְעָלָיו. וְאִם תְּפָשׂוֹ הַכֹּהֵן, אֵין מוֹצִיאִים אוֹתוֹ מִיָּדוֹ, וְאוֹכֵל אוֹתוֹ בְּמוּמוֹ. \u0005וְעַיֵּן לְעֵיל סי' שט\"ו דקי\"ל דְּמוֹצִיאִין אוֹתוֹ מִיַּד הַכֹּהֵן.\u0006",[],["\u0003ספק. \u0004 בטור כ' ויאכל במומו לבעלים וחייב במתנות כהונה והטעם דאמר הכהן ממ\"נ אם בכור הוא כולו שלי ואם לאו הב לי מתנות וכן בכל הני דאמרינן יאכל במומו לבעלים דינא הכי עכ\"ל הט\"ז וע\"ל סימן ס\"א ס\"ב בש\"ך שם דדעת הרמב\"ם דבכה\"ג פטור מהמתנות כיון שחליפיו ביד כהן וכ\"כ הש\"ך כאן וכתב עוד מיהו גם הכחוש הוא ספק בכור ואסור בגיזה ועבודה ויאכלנו הכהן במומו:","\u0003הכחוש. \u0004 והוא ג\"כ ספק בכור אצל הכהן ודינו כמ\"ש בס\"ק א'. ש\"ך:"]],["מְבַכֶּרֶת הַמַּקְשֶׁה לֵילֵד, יָכוֹל לַחְתֹּךְ אוֹתוֹ אֵבֶר אֵבֶר וּמַשְׁלִיךְ לַכְּלָבִים. \u0010c0\u0011 \u0005וּמֵרֻבּוֹ וָאֵילָךְ, צָרִיךְ קְבוּרָה (בֵּית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת)\u0006. וְהַבָּא אַחֲרָיו, בְּכוֹר. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ בְּכוֹר, (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. יָצָא רֻבּוֹ, הֲרֵי זֶה יִקָּבֵר וְנִפְטְרָה מֵהַבְּכוֹרָה. וְאִם חָתַךְ אֵבֶר וְהִנִּיחוֹ, אֵבֶר וְהִנִּיחוֹ, עַד שֶׁהִשְׁלִים רֻבּוֹ, הֲרֵי כָּל הָאֵבָרִים צְרִיכִין קְבוּרָה וְנִפְטְרָה מֵהַבְּכוֹרָה, כֵּיוָן שֶׁיָּצָא רֻבּוֹ, בֵּין שָׁלֵם בֵּין מְחֻתָּךְ \u0005(וַהֲרֵי הוּא לְפָנֵינוּ)\u0006, נִתְקַדֵּשׁ לְמַפְרֵעַ. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ קָדוֹשׁ \u0010c1\u0011 לְמַפְרֵעַ (טוּר)\u0006.\nיָצָא שְׁלִישׁ וּמְכָרוֹ לְעוֹבֵד כּוֹכָבִים, וְחָזַר וְיָצָא שְׁלִישׁ אַחֵר, \u0010c2\u0011 נִתְקַדֵּשׁ לְמַפְרֵעַ. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ קָדוֹשׁ לְמַפְרֵעַ. (טוּר)\u0006.\nיָצָא שְׁלִישׁ דֶּרֶךְ דֹּפֶן וּשְׁנֵי שְׁלִישִׁים דֶּרֶךְ רֶחֶם, אֵינוֹ קָדוֹשׁ. \u0005וְיֵשׁ אוֹמְרִים \u0010c3\u0011 דְּקָדוֹשׁ (ג\"ז טוּר)\u0006.\nיָצָא רֹב הָעֻבָּר עַל יְדֵי מִעוּט אֶחָד מֵהָאֵבָרִים שֶׁמַּשְׁלִימוֹ לְרֹב, חֲשֹׁב כְּיִלּוֹד אַף עַל פִּי שֶׁרֹב הָאֵבֶר מִבִּפְנִים, וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים וּלְהַשְׁלִיכוֹ לַכְּלָבִים, וּפוֹטֵר הַבָּא אַחֲרָיו. וְאִם יָצָא חֶצְיוֹ שֶׁל עֻבָּר עַל יְדֵי רֹב אֶחָד מֵהָאֵבָרִים שֶׁעַל יָדוֹ נִשְׁלַם יְצִיאַת חֲצִי הָעֻבָּר, הֲרֵי זֶה סָפֵק וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים וּלְהַשְׁלִיכוֹ לַכְּלָבִים, וְהַבָּא \u0010c4\u0011 אַחֲרָיו סְפֵק בְּכוֹר.",[],["\u0003ומרובו. \u0004 פי' הש\"ך דאף כשחתך אבר אבר והשליך לכלבים מ\"מ מה שיוצא אח\"כ מרובו ואילך חייב קבורה אבל מה שיצא כבר אף שיצא אח\"כ רובו א\"צ קבורה למ\"ד להבא הוא קדוש וכ\"מ בתוס' עכ\"ל:","\u0003למפרע. \u0004 ומה שמחתך קודם שיצא הרוב השליך לכלבים ומרוב ואילך צריך קבורה. ש\"ך:","\u0003נתקדש. \u0004 והמכירה לעובד כוכבים אינה מכירה:","\u0003דקדוש. \u0004 לטעמייהו אזלי דס\"ל להבא קדוש. ש\"ך:","\u0003אחריו. \u0004 כתב הש\"ך דלדעת הרב צ\"ל דכאן מיירי שלא נולד אח\"כ כולו אלא שחציו הנשאר יצא דרך דופן כו' אבל אם אחר שיצא חציו ברוב אבר יצא כולו ואחר זמן ילדה ולד פשיטא שהוא פטור מבכורה דמה בכך שמתחלה יצא חציו ברוב אבר ס\"ס אח\"כ נולד כולו וזה פשוט עכ\"ל:"]],["כֹּהֲנִים \u0010c0\u0011 וּלְוִיִּם חַיָּבִים בִּבְכוֹר בְּהֵמָה טְהוֹרָה, וְיַפְרִישֶׁנּוּ הַכֹּהֵן \u0010c1\u0011 וִיעַכְּבֶנּוּ לְעַצְמוֹ.\nבֶּהֱמַת הַשֻּׁתָּפִין חַיֶּבֶת בִּבְכוֹרָה.\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים פּוֹטֵר, שֶׁאִם הָיָה הָעוֹבֵד כּוֹכָבִים שֻׁתָּף בַּפָּרָה אוֹ בָּעֻבָּר, אֲפִלּוּ הָיָה לוֹ אֶחָד \u0010c2\u0011 מֵאֶלֶף בָּאֵם אוֹ בַּוָּלָד, הֲרֵי זֶה פָּטוּר מֵהַבְּכוֹרָה. לְפִיכָךְ הַמְקַבֵּל בְּהֵמָה מִן הָעוֹבֵד כּוֹכָבִים לִהְיוֹת מְטַפֵּל בָּהּ וְהַוְּלָדוֹת בֵּינֵיהֶם, אוֹ עוֹבֵד כּוֹכָבִים שֶׁקִּבֵּל מִיִּשְׂרָאֵל כָּזֶה, הֲרֵי אֵלּוּ פְּטוּרִים מֵהַבְּכוֹרָה, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בִּבְנֵי יִשְׂרָאֵל \u0005(שְׁמוֹת יג, ב)\u0006 עַד שֶׁיִּהְיֶה הַכֹּל מִיִּשְׂרָאֵל.\nהָיָה לוֹ בְּאֶחָד מִשְּׁנֵיהֶם \u0010c3\u0011 אֵבֶר אֶחָד, כְּגוֹן יָד אוֹ רֶגֶל, רוֹאִים כָּל שֶׁאִלּוּ יַחְתֹּךְ יִהְיֶה בַּעַל מוּם, הֲרֵי זֶה פָּטוּר; וְאִם אֶפְשָׁר שֶׁהָעוֹבֵד כּוֹכָבִים \u0010c4\u0011 יַחְתֹּךְ אֵבֶר וְלֹא יִפָּסֵל, חַיָּב בִּבְכוֹרָה.\nעֵדֶר שֶׁהַמֶּלֶךְ נוֹטֵל מִמֶּנָּהּ מַעֲשֵׁר, כֵּיוָן שֶׁעִשּׂוּר שֶׁל מֶלֶךְ בְּתוֹכוֹ, חֲשִׁיבָא יַד עוֹבֵד כּוֹכָבִים בָּאֶמְצַע וּפָטוּר מֵהַבְּכוֹרָה. \u0005הַגָּה: וַאֲפִלּוּ יָכוֹל לְסַלֵּק הָעוֹבֵד כּוֹכָבִים בְּמָעוֹת, חָשׁוּב יַד עוֹבֵד כּוֹכָבִים בָּאֶמְצַע, מֵאַחַר שֶׁעִקַּר שִׁעְבּוּד הָעוֹבֵד כּוֹכָבִים עַל הַבְּהֵמוֹת. (בֵּית יוֹסֵף לְהָרִי\"ף וְרֹא\"שׁ וּפִסְקֵי מהאר\"י סי' ק\"ל)\u0006 אֲבָל אִם הִתְנוּ מִתְּחִלָּה שֶׁיִּתְּנוּ לוֹ דָּמִים בְּעַד הַוְּלָדוֹת, חַיָּב בִּבְכוֹרָה \u0005(גַּם זֶה שָׁם)\u0006.\nבַּזְּמַן הַזֶּה, מִצְוָה לְשַׁתֵּף עִם הָעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁיֵּצֵא לַאֲוִיר הָעוֹלָם, כְּדֵי לְפָטְרוֹ מֵהַבְּכוֹרָה, אַף עַל פִּי שֶׁמַּפְקִיעַ קְדֻשָּׁתוֹ, הָכִי עָדִיף טְפֵי כְּדֵי שֶׁלֹּא יָבֹא לִידֵי מִכְשׁוֹל לֵהָנוֹת מִמֶּנּוּ בְּגִזָּה וּבַעֲבוֹדָה. וְאִם יַקְנֶה לְעוֹבֵד כּוֹכָבִים חֵלֶק בָּעֻבָּר, אֵין הַקִּנְיָן חָל, לְפִי שֶׁהוּא דָּבָר שֶׁלֹּא בָּא לָעוֹלָם, לְכָךְ יַקְנֶה לוֹ חֵלֶק בָּאֵם, \u0005אוֹ יַקְנֶה לוֹ הָאֵם כְּדֵי \u0010c5\u0011 לְהַקְנוֹת לוֹ חֵלֶק בָּעֻבָּר\u0006 וְהַקִּנְיָן יִהְיֶה שֶׁיְּקַבֵּל פְּרוּטָה מֵהָעוֹבֵד כּוֹכָבִים וְיַקְנֶה לוֹ הַמָּקוֹם שֶׁהַבְּהֵמָה עוֹמֶדֶת שָׁם וְהַמָּקוֹם יַקְנֶה לוֹ חֵלֶק בָּאֵם. \u0005אוֹ שֶׁיְּקַבֵּל מָעוֹת מִן הָעוֹבֵד כּוֹכָבִים, וְיִמְשֹׁךְ הַבְּהֵמָה לִרְשׁוּתוֹ אוֹ \u0010c6\u0011 לְסִמְטָא דְּאָז מְשִׁיכָה קוֹנָה לוֹ עִם הַמָּעוֹת (טוּר לְדַעַת רַשִׁ\"י וְרַבֵּנוּ תָּם)\u0006.\nהַמְקַבֵּל צֹאן מִן הָעוֹבֵד כּוֹכָבִים \u0005(בְּמָמוֹן קָצוּב)\u0006, וּפָסַק עִמּוֹ שֶׁיִּהְיֶה הַשָּׂכָר בֵּינֵיהֶם וְאִם פָּחֲתוּ פָּחֲתוּ לַיִּשְׂרָאֵל, אַף עַל פִּי שֶׁבִּרְשׁוּת יִשְׂרָאֵל הֵם וַהֲרֵי הֵם כְּקִנְיָנוֹ, הוֹאִיל וְאִם לֹא יִמְצָא הָעוֹבֵד כּוֹכָבִים אֶצְלוֹ מָמוֹן לִגְבּוֹת מִמֶּנּוּ יִגְבֶּה מֵהַבְּהֵמוֹת הָאֵלּוּ וּמִוַּלְדוֹתֵיהֶם, נַעֲשָׂה כְּמִי שֶׁיֵּשׁ לוֹ אַחֲרָיוּת עֲלֵיהֶם וְעַל וַלְדוֹתֵיהֶן, וַהֲרֵי יַד הָעוֹבֵד כּוֹכָבִים בָּאֶמְצַע וּפְטוּרִים מֵהַבְּכוֹרָה הֵם וּוַלְדוֹתֵיהֶן. אֲבָל וַלְדֵי וְלָדוֹת, חַיָּבִים, שֶׁהֲרֵי שֶׁל יִשְׂרָאֵל הֵם וְאֵין לָעוֹבֵד כּוֹכָבִים רְשׁוּת עֲלֵיהֶם. וְאִם הֶעֱמִיד וְלָדוֹת תַּחַת אִמּוֹתֵיהֶן, וַלְדֵי וְלָדוֹת פְּטוּרִים. וַלְדֵי וַלְדֵי וְלָדוֹת, חַיָּבִים. \u0005הַגָּה: וְעוֹבֵד כּוֹכָבִים בַּעַל חוֹב שֶׁקִּבֵּל בְּהֵמָה מִיִּשְׂרָאֵל לְגַדְּלָהּ, וְהָיָה חָפֵץ חֵלֶק בַּוְּלָדוֹת, וְהַיִּשְׂרָאֵל אָמַר לִתֵּן לוֹ דָּמִים, וּמֵאַחֵר שֶׁיָּדוֹ הָיְתָה תַּקִּיפָה עַל בַּעַל חוֹבוֹ בֶּטַח שֶׁעַל כָּרְחוֹ שֶׁל עוֹבֵד כּוֹכָבִים יִצְטָרֵךְ לִקַּח מָעוֹת, מִכָּל מָקוֹם פְּטוּרָה מֵהַבְּכוֹרָה \u0010c7\u0011 הוֹאִיל וְהָעוֹבֵד כּוֹכָבִים לֹא רָצָה לְטַפֵּל בָּהּ רַק בְּחֵלֶק וְלָדוֹת (פִּסְקֵי מהרא\"י סִימָן ק\"ל)\u0006. עוֹבֵד כּוֹכָבִים שֶׁקִּבֵּל בֶּהֱמַת יִשְׂרָאֵל לְטַפֵּל בָּהּ, וְאֵין לוֹ חֵלֶק בָּהּ רַק קִבֵּל עָלָיו אַחֲרָיוּת שֶׁלָּהּ, חַיֶּבֶת בִּבְכוֹרָה \u0005(מהרי\"ו סִימָן קע\"ד)\u0006.",[],["\u0003ולוים. \u0004 והלוים צריכים ליתנו לכהן. כ\"כ הלבוש:","\u0003ויעכבנו. \u0004 ואסור בגיזה ועבודה אלא ימתין עד שיפול בו מום ויאכלנו במומו. ש\"ך:","\u0003מאלף. \u0004 בב\"י כתב בשם תוספות דבכורות דסגי אפי' באזנה אכן בתוס' פרק בתרא דעבודת כוכבים כתבו שיש להחמיר להקנות לעובד כוכבים דבר שעושה אותה טריפה כגון הריאה והראש אמנם א\"צ שיתן העובד כוכבים מעות שוה הראש או הריאה אלא שיקנה בפרוטה אע\"פ ששוה יותר כפלים אפ\"ה אין לחוש משום ביטול מקח דאנן סהדי שהישראל גמר ומקני לעובד כוכבים כדי להפטר והקשה בפרישה מאי שנא מסי' ס\"א גבי מתנות כהונה שצריך שיהיה לעובד כוכבים חלק בכולה ואם אין שותף עמו אלא בראש אינו פטור רק מן הלחיים וכו' וא\"כ קשה לדעת התוס' דבעינן דוקא דבר חשוב כמו הראש ובו סגי ונראה דלק\"מ דדוקא הכא גבי בכור דכתיב פטר רחם בישראל ילפינן מינה שיהיה הכל בבני ישראל ואם ניטל דבר חשוב ממנו בטל הכל משא\"כ לענין מתנות דאין לימוד מקרא על זה אלא דכל שיש לעובד כוכבים חלק באותו חלק פטור ממתנות ותו לא דאין א' תלוי בחבירו כלל עכ\"ל הט\"ז:","\u0003אבר. \u0004 פי' שאין לעובד כוכבים שותפות בסתם אלא באבר מיוחד:","\u0003יחתוך. \u0004 כגון שיש לו יתרת אבר או דהכי פירושו שאלו יחתוך מאותו אבר עצמו חלק העובד כוכבים שבו ולא יהיה מום מחמת אותו החיתוך. ט\"ז:","\u0003להקנות. \u0004 כתב הש\"ך דצ\"ע דהא מהתוס' והרא\"ש משמע איפכא דאין לעשות כן משום דאתי למטעי דיקנה לו אוזן העובר לחוד עכ\"ל:","\u0003דאז. \u0004 כ' הש\"ך משום דיש מחלוקת בין הפוסקים אם משיכה קונה ולא מעות או מעות ולא משיכה הלכך לצאת ידי ספק צריך לעשות קנין דמשיכה ומעות משמע דאפי' דיעבד אם לא עשה אלא קנין א' משיכה או מעות לא נפטר מבכורה וכתב הב\"ח דאפי' עביד תרוייהו משיכה ומעות אלא דלא נתן העובד כוכבים המעות מיד בשעת קנין אלא שהבטיחו ליתן לו מעות כך וכך והאמין לו אע\"פ שנתן לו העובד כוכבים אח\"כ מה שהבטיח לו אין אלו המעות קונות ואצ\"ל אם הישראל היה חייב לעובד כוכבים וא\"ל העובד כוכבים פרתך קנויה לי במעות שאתה חייב לי והקנה לו הישראל דפשיטא דאין זה קנין מעות ע\"כ ומשמע דה\"ה בקנה פרה מעובד כוכבים דלר\"ת משיכה דוקא קונה ולרש\"י מעות וא\"כ אם עשה הישראל משיכה או נתן מעות וילדה חייב בבכורה מספיקא וכ\"מ בתשובת הרב סי' פ\"ז וכתב עוד שם שאם קנה פרה מעובדי כוכבים במעות ונגנבה ונתרצה העובד כוכבים לשלם הפרה להישראל ואח\"כ הוכר הגנב וילדה הפרה דפטור מבכורה כיון דנתרצה העובד כוכבים לשלם נקנה לו הפרה בכל מקום שהיא עכ\"ל ובפסקי מהרא\"י כתב דאע\"ג דאין מועיל מה שמקנה העובר לעובד כוכבים מחמת שלא בא לעולם מ\"מ יש סברא לומר דמהני אם הפרה מעוברת ודמיא להא דריש המפקיד נעשה כאומר פרתי קנויה לך סמוך לגנבתי ואם יש עוד צד להתיר כההיא דראוה חולבת מקודם מהני בצירוף ומה שמתנה עם העובד כוכבים שיאכיל הפרה בעד העגל הוה כנותן מעות בעדו עכ\"ל:","\u0003הואיל והיה כאן משיכה ומעות. \u0004 דכיון דברשות העובד כוכבים הוי בשעת התנאי וקנה לו רשותו במקום משיכה ומעות נמי נתן במה שקבל עליו להאכילה וליטפל בהן מאי אית לך למימר דבר שלא בא לעולם הוא יש להביא ראיה על זה מפרק המפקיד דאמרינן נעשה כאומר לו קנה בהמה לולדותיה כו' עכ\"ל מהרא\"י:"]],["\u0003הלכות פטר חמור\u0004\nבְּכוֹר בְּהֵמָה טְמֵאָה נוֹהֵג בְּכָל מָקוֹם וּבְכָל זְמַן. וְאֵינוֹ נוֹהֵג אֶלָּא בַּחֲמוֹרִים. וְזֶה מִצְוָתוֹ, שֶׁכָּל יִשְׂרָאֵל שֶׁיֵּשׁ לוֹ חֲמוֹרָה שֶׁבִּכְּרָה פּוֹדֵהוּ בְּשֶׂה מִן הַכְּבָשִׂים אוֹ מִן הָעִזִּים, בֵּין זָכָר בֵּין נְקֵבָה, בֵין תָּם בֵּין בַּעַל מוּם, בֵּין גָּדוֹל בֵּין קָטָן, וְיִתְּנֶנּוּ לְכֹהֵן. וּמֵאֵימָתַי חַיָּב לִפְדּוֹתוֹ, מִשֶּׁיִּוָּלֵד עַד שֶׁיָּמוּת, אֶלָּא שֶׁמִּצְוָה לִפְדּוֹתוֹ מִיָּד, שֶׁלֹּא לְהַשְׁהוֹת הַמִּצְוָה. וּלְאַחֵר שֶׁיִּפְדֶּנּוּ הוּא חֻלִּין גְּמוּרִים, וּמֻתָּר בְּגִזָּה וַעֲבוֹדָה כִּשְׁאָר חֻלִּין. וְהַכֹּהֵן יַעֲשֶׂה גַּם כֵּן בַּשֶּׂה כְּמוֹ בִּשְׁאָר חֻלִּין.\nאֵין פּוֹדִין לֹא \u0010c0\u0011 בְּעֵגֶל וְלֹא בְּחַיָּה וְלֹא בְּשֶׂה שָׁחוּט וְלֹא בִּטְרֵפָה וְלֹא בְּכִלְאַיִם וְלֹא בְּכוֹי.\nאֵין פּוֹדִין בְּשֶׂה הַדּוֹמֶה לְמִין אַחֵר; וְאִם פָּדָה, פָּדוּי \u0005וְיֵשׁ אוֹמְרִים דְּאִם פָּדָה בּוֹ הָוֵי \u0010c1\u0011 סָפֵק (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nפּוֹדִין בְּבֶן פְּקוּעָה. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵין פּוֹדִין בְּבֶן פְּקוּעָה (ג\"ז בִּשְׁמוֹ)\u0006.\nאִם אֵין לוֹ שֶׂה לִפְדּוֹתוֹ, פּוֹדֶהוּ בְּשָׁוְיוֹ. \u0005וְאָז יָכוֹל לִפְדּוֹת בְּכָל דָּבָר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006, וְנוֹתֵן דָּמָיו לַכֹּהֵן. לֹא אָמְרָה תּוֹרָה \u0010c2\u0011 לְהַחְמִיר עָלָיו, אֶלָּא לְהָקֵל עָלָיו שֶׁאִם הָיָה לוֹ פֶּטֶר חֲמוֹר שֶׁשָּׁוֶה עֲשָׂרָה סְלָעִים, יֵשׁ לוֹ לִפְדּוֹתוֹ בְּשֶׂה שְׁוֵה דִּינָר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיוּ דְּמֵי פֶּטֶר חֲמוֹר מִג' זוּזִין וָמַעְלָה, אֲבָל אִם הָיוּ דָּמָיו פָּחוֹת מִג' זוּזִין, אֵין פּוֹדִין אוֹתוֹ אֶלָּא בְּשֶׂה אוֹ בְּג' זוּזִין; וְעַיִן יָפָה לֹא יִפְחֹת מִסֶלַע, וְעַיִן רָעָה בַּחֲצִי סֶלַע, וּבֵינוֹנִית בְּג' זוּזִים. \u0005הַגָּה: וּפוֹדִין בְּשֵׂה אֶחָד כַּמָּה פְּעָמִים, כְּגוֹן אִם חָזַר וּקְנָאוֹ מִן הַכֹּהֵן, אוֹ בְּמָקוֹם שֶׁיֵּשׁ לוֹ סְפֵק פֶּטֶר חֲמוֹר, שֶׁדִּינוֹ שֶׁמַּפְרִישׁ עָלָיו טָלֶה וְהוּא \u0010c3\u0011 שֶׁלּוֹ (טוּר)\u0006.\nמִיָּד כְּשֶׁהִפְרִישׁ הַטָּלֶה תַּחַת פֶּטֶר חֲמוֹר, חָזַר הַפֶּטֶר חֲמוֹר חֻלִּין, אֲפִלּוּ קֹדֶם שֶׁנְּתָנוֹ לַכֹּהֵן, וּמֻתָּר לֵהָנוֹת בּוֹ. וְאִם מֵת, לֹא יִקָּבֵר. וְהַכֹּהֵן זָכָה בַּשֶּׂה מִיָּד, וְהוּא בְּאַחֲרָיוּתוֹ, שֶׁאִם מֵת מִיָּד הַבְּעָלִים קֹדֶם שֶׁנְּתָנוּהוּ לַכֹּהֵן, פְּטוּרִים. לְפִיכָךְ מִיָּד כְּשֶׁמַּפְרִישׁוֹ \u0010c4\u0011 מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן פֶּטֶר חֲמוֹר.\nיִשְׂרָאֵל שֶׁפָּדָה פָּטַר חֲמוֹר שֶׁל חֲבֵרוֹ, הוּא פָּדוּי, וּפֶטֶר חֲמוֹר הוּא לִבְעָלָיו.\nפֶּטֶר חֲמוֹר אָסוּר בַּהֲנָאָה עַד שֶׁיִּפָּדֶה; וְאִם מְכָרוֹ קֹדֶם פִּדְיוֹן, \u0010c5\u0011 דָּמָיו אֲסוּרִין. \u0005הַגָּה: וְדַוְקָא שֶׁמְּכָרוֹ סְתָמָא, אֲבָל אִם הוֹדִיעוּ לַלּוֹקֵחַ שֶׁהוּא פֶּטֶר חֲמוֹר וְהוּא מוֹכֵר לוֹ מַה שֶּׁשָּׁוֶה יוֹתֵר מֵהַשֶּׂה שֶׁיִּפְדֶּה, דָּמָיו מֻתָּרִים, וַאֲפִלּוּ לְכַתְּחַלָּה מֻתָּר לְמָכְרוֹ בִּכְהַאי גַּוְנָא (כָּךְ מַשְׁמָע בַּטּוּר)\u0006. וְאִם מֵת קֹדֶם פִּדְיוֹן, אוֹ שֶׁעֲרָפוֹ, יִקָּבֵר, מִפְּנֵי שֶׁהוּא אָסוּר בַּהֲנָאָה אַף לְאַחַר עֲרִיפָתוֹ, הוֹאִיל וְלֹא נִפְדָּה. לְפִיכָךְ, אִם לֹא פָּדָהוּ וְנָתַן פֶּטֶר הַחֲמוֹר בְּעַצְמוֹ לַכֹּהֵן, אָסוּר לַכֹּהֵן לְהִשְׁתַּמֵּשׁ בּוֹ עַד שֶׁיִּפְדֵּהוּ בְּשֶׂה וְיִקַּח הַשֶּׂה לְעַצְמוֹ, אוֹ יַעַרְפֶנּוּ וְיִקָּבֵר. וְהַכֹּהֲנִים \u0010c6\u0011 חֲשׁוּדִים עַל דָּבָר זֶה, לְפִיכָךְ אָסוּר לְיִשְׂרָאֵל לִתֵּן פֶּטֶר חֲמוֹר לַכֹּהֵן, אֶלָּא אִם כֵּן פָּדָה הַחֲמוֹר בְּפָנָיו אוֹ יַעַרְפֶנּוּ לְפָנָיו.\nפֶּטֶר חֲמוֹר, קֹדֶם שֶׁיִּפָּדֶה, אָסוּר לַעֲבֹד בּוֹ וּלְגָזְזוֹ כְּדֵי לֵהָנוֹת בִּשְׂעָרוֹ. אֲבָל אִם הָיָה שְׂעָרוֹ מְסֻבָּךְ, אוֹ שֶׁיֵּשׁ לוֹ מַכָּה בִּמְקוֹם הַשֵּׂעָר, מֻתָּר לְגָזְזוֹ לַהֲנָאָתוֹ, וְהַשֵּׂעָר אָסוּר בַּהֲנָאָה, וְיִקָּבֵר.\nיִשְׂרָאֵל שֶּׁיֵּשׁ לוֹ סָפֵק פֶּטֶר חֲמוֹר, יַפְרִישׁ עָלָיו טָלֶה לְהַפְקִיעַ אִסוּרוֹ, וּמְעַכֵּב הַטָּלֶה \u0010c7\u0011 לְעַצְמוֹ. \u0005הַגָּה: לֹא רָצָה לִפְדּוֹתוֹ וְלֹא לִתְּנוֹ לַכֹּהֵן, מַכֵּהוּ בְּקוֹפִיץ בְּעָרְפּוֹ עַד שֶׁיָּמוּת, וְיִקְבְּרֶנּוּ (טוּר)\u0006.\nפֶּטֶר חֲמוֹר אֵין מְמִיתִין אוֹתוֹ לֹא בְּמַקֵּל וְלֹא בְּקָנֶה וְלֹא בְּמַגָּל וְלֹא בִּמְגֵרָה וְלֹא בְּקַרְדֹּם, אֶלָּא \u0010c8\u0011 בְּקוֹפִיץ. וְלֹא יַכְנִיסֶנּוּ בְּחֵדֶר וְיִנְעֹל בְּפָנָיו עַד שֶׁיָּמוּת, שֶׁנֶּאֱמַר: וַעֲרַפְתּוֹ. \u0005(שְׁמוֹת יג, יג, לד, כ)\u0006.\nמִצְוַת פְּדִיָּה קוֹדֶמֶת לְמִצְוַת עֲרִיפָה.\nחֲמוֹרָה שֶׁלֹּא בִּכְּרָה, וְיָלְדָה \u0010c9\u0011 שְׁנֵי זְכָרִים נוֹתֵן טָלֶה \u0010c10\u0011 אֶחָד לַכֹּהֵן. זָכָר וּנְקֵבָה, סָפֵק, וּמַפְרִישׁ טָלֶה אֶחָד כְּדֵי לְהַפְקִיעַ קְדֻשָּׁה מִמֶּנּוּ עַד שֶׁיִּהְיֶה מֻתָּר בַּהֲנָאָה, שֶׁמָּא הַזָּכָר נוֹלַד תְּחַלָּה וְטָלֶה זֶה שֶׁהִפְרִישׁ, לַבְּעָלִים וְאֵינוֹ לַכֹּהֵן, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nשְׁתֵּי חֲמוֹרוֹת שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן שְׁנֵי טְלָאִים לַכֹּהֵן. זָכָר וּנְקֵבָה, הַזָּכָר לַכֹּהֵן. שְׁנֵי זְכָרִים וּנְקֵבָה, אֶחָד לַכֹּהֵן, וְעַל הַשֵּׁנִי מַפְרִישׁ טָלֶה אֶחָד וְהוּא לְעַצְמוֹ. שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, אוֹ שְׁתֵּי נְקֵבוֹת וְזָכָר, אֵין לַכֹּהֵן כְּלוּם. \u0005וְיֵשׁ אוֹמְרִים דְּצָרִיךְ \u0010c11\u0011 לְהַפְרִישׁ, וְהֵם לְעַצְמוֹ (טוּר)\u0006.\nאַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן טָלֶה אֶחָד לַכֹּהֵן. זָכָר וּנְקֵבָה, מַפְרִישׁ טָלֶה וְהוּא לְעַצְמוֹ.\nהַלּוֹקֵחַ חֲמוֹרָה מֵעוֹבֵד כּוֹכָבִים, וְאֵין יָדוּעַ אִם בִּכְּרָה, וְיָלְדָה זָכָר, פּוֹדֶה אוֹתוֹ בְּשֶׂה וְהוּא לַבְּעָלִים, מִפְּנֵי שֶׁהוּא סָפֵק.\nיִשְׂרָאֵל שֶׁיָּרַשׁ מֵאֲבִי אִמּוֹ כֹּהֵן פֶּטֶר חֲמוֹר וַדַּאי, וְאוֹתוֹ הַכֹּהֵן \u0010c12\u0011 יְרָשׁוֹ מֵאֲבִי אִמּוֹ יִשְׂרָאֵל, מַפְרִישׁ טָלֶה וְהוּא שֶׁלּוֹ.\nגֵּר שֶׁבִּכְּרָה חֲמוֹרָתוֹ, סָפֵק קֹדֶם שֶׁנִּתְגַּיֵּר אוֹ אַחַר כָּךְ, מַפְרִישׁ עָלָיו טָלֶה וְהוּא שֶׁלּוֹ.\nכֹּהֲנִים וּלְוִיִּים פְּטוּרִים מִבְּכוֹר בְּהֵמָה טְמֵאָה. \u0005וְהוּא הַדִּין כֹּהֶנֶת וּלְוִיָּה, אֲבָל בַּעֲלֵיהֶם חַיָּבִים בְּפֶטֶר חֲמוֹר שֶׁלָּהֶם. אֲבָל בְּנִכְסֵי מְלוֹג שֶׁלָּהּ פְּטוּרִים, שֶׁהֲרֵי יֵשׁ לָהּ שֻׁתָּפוּת בַּהֲדֵיה (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן שס\"ו)\u0006.\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים, פּוֹטֵר בּוֹ. וְכָל דִּינֵי שֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים בִּטְהוֹרָה, כֵּן דִּינוֹ בִּטְמֵאָה, אֶלָּא שֶׁאָסוּר לְהִשְׁתַּתֵּף עִמּוֹ כְּדֵי לְהַפְקִיעַ קְדֻשָּׁתוֹ, כֵּיוָן שֶׁאֶפְשָׁר בִּפְדִיָּה אוֹ בַּעֲרִיפָה.\nשֻׁתָּפוּת כֹּהֵן אוֹ לֵוִי, פּוֹטֵר בּוֹ.\nעוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ פֶּטֶר חֲמוֹר, מוֹדִיעִין אוֹתוֹ שֶׁאֵינוֹ חַיָּב וַהֲרֵי הוּא \u0010c13\u0011 מֻתָּר בְּגִזָּה וַעֲבוֹדָה.\nפָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹרָה, וַחֲמוֹרָה שֶׁיָּלְדָה כְּמִין פָּרָה, נִתְבָּאֵר בְּסִימָן שט\"ו.",[],["\u0003בעגל. \u0004 בכל אלו אין פודין בסתמא \u0005(פי' בתורת פדיון שיש בשה)\u0006 אלא בשויו כן הוא בטור והוא פשוט וזה שכ' הרב בס\"ה ואז יכול לפדותו בכל דבר. ש\"ך:","\u0003ספק. \u0004 פי' אם אח\"כ מת הפטר חמור קודם שנתן זה הפדיון לכהן אינו חייב ליתן אותו להכהן דיכול הישראל לומר שמא לא חל עליו הפדיון ואם אחר שנתנו לכהן מת הפטר חמור ישאר הפדיון לכהן כיון שהוא מוחזק דהא הוא עצמו נתנו לו ואין זה דומה לתקפו כהן דמוציאין מידו כדלעיל סי' שט\"ו וא\"ל ממ\"ש הרמ\"א שם שאם נתן לו הישראל בטעות דצריך הכהן להחזיר לו דשאני הכא דבשעת הפדיון היה לכהן עכ\"פ חיוב עליו ליתן לו פדיון טוב אלא שטעה וסבור שזהו פדיון טוב ע\"כ יחזיקנו הכהן משא\"כ בספק בכור דיש ספק אם חייב לו כלל עכ\"ל הט\"ז:","\u0003להחמיר. \u0004 כלומר שהקדש ושאר דברים נפדין בכל דבר ופטר חמור לא יהא נפדה רק בשה ולא בשויו. ש\"ך:","\u0003שלו. \u0004 ורשאי אח\"כ לחזור ולפדות עליו ודאי פטר חמור וכן כשיש לו כמה ספיקות פטרי חמור מפריש עליהן טלה א' בשביל כולן והוא שלו. ש\"ך:","\u0003מברך. \u0004 כתב הט\"ז והא דאין מברכין ג\"כ אנתינת בכור לכהן כמו בפדיון פטר חמור ובכור אדם משום דיש לחלק דבכור מעולם לא היה לישראל זכות בו דרחמנא זכהו להכהן תיכף משנולד וה\"ל כאילו נולד בבית הכהן מפרתו ע\"כ אין שייך לברך כי הישראל אינו עושה כלום משא\"כ בפדיון פטר חמור ובכור אדם שהוא נותן ממונו בזה מברך שפיר על מצוה הזאת עכ\"ל:","\u0003דמיו. \u0004 אפי' מה ששוה יותר על השה דכיון שלא הודיע ללוקח שהוא פטר חמור לא יפדנו וכולו אסור. ש\"ך:","\u0003חשודים. \u0004 מפני שאומרים מה אני צריך להפריש עליו טלה כיון שהוא לעצמי:","\u0003לעצמו. \u0004 מפני שהמע\"ה:","\u0003בקופיץ. \u0004 הוא סכין גדול ודרך לערוף בו. כ\"כ רש\"י:","\u0003שני. \u0004 ואינו מכיר הבכור:","\u0003אחד. \u0004 משום שאחד מהם ודאי בכור ושניהם אסורים בהנאה עד שיפדה. ש\"ך:","\u0003להפריש\u0004 לאפקועי איסורייהו הלכך בב' זכרים וב' נקבות מפריש ב' טלאים והם לעצמו ובזכר וב' נקבות מפריש טלה אחת והוא לעצמו. ש\"ך:","\u0003ירשו. \u0004 דאלו פטר חמור של הכהן עצמו הוא פטור. כן כתב רש\"ל:","\u0003מותר. \u0004 אפי' לישראל וכדי שלא יאמר העובד כוכבים ישראל מזלזל בקדשים לכך מודיעין אותו שאין זה הקדש:"]],["\u0003הלכות חלה\u0004\nמִצְוַת עֲשֵׂה לְהַפְרִישׁ תְּרוּמָה מֵהָעִסָה וְלִתְּנָהּ לְכֹהֵן, שֶׁנֶּאֱמַר: רֵאשִׁית עֲרִסֹתֵכֶם תָּרִימוּ תְרוּמָה \u0005(בַּמִּדְבָּר טו, כ)\u0006 וְרֵאשִׁית זֶה אֵין לוֹ שִׁעוּר מִן הַתּוֹרָה, אֲפִלּוּ הִפְרִישׁ כִּשְׂעוֹרָה, פָּטַר אֶת הָעִסָה. וְהָעוֹשֶׂה כָּל עִסָתוֹ חַלָּה, לֹא עָשָׂה כְּלוּם, עַד שֶׁיְּשַׁיֵּר מִקְצָת. וּמִדִּבְרֵי סוֹפְרִים מַפְרִישִׁין אֶחָד מִכ\"ד מִן \u0010c0\u0011 הָעִסָה. וְהַנַּחְתּוֹם הָעוֹשֶׂה לִמְכֹּר בַּשּׁוּק, מַפְרִישׁ אֶחָד מִמ\"ח. וְאִם \u0010c1\u0011 נִטְמְאָה הָעִסָה בְּשׁוֹגֵג אוֹ בְּאֹנֶס, אַף בַּעַל הַבַּיִת מַפְרִישׁ אֶחָד מִמ\"ח.\nאֵין חַיָּבִים בְּחַלָּה מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד, שֶׁנֶּאֱמַר: וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ \u0005(בַּמִּדְבָּר טו, יט)\u0006 וּבִזְמַן שֶׁכָּל יִשְׂרָאֵל שָׁם שֶׁנֶּאֱמַר בְּבֹאֲכֶם \u0005(בַּמִּדְבָּר טו, יח)\u0006 בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְצַתְכֶם. לְפִיכָךְ חַלָּה בַּזְּמַן הַזֶּה אֲפִלּוּ בִּימֵי \u0010c2\u0011 עֶזְרָא בְּאֶרֶץ יִשְׂרָאֵל, אֵינָהּ אֶלָּא מִדִּבְרֵיהֶם.\nמַפְרִישִׁין חַלָּה בְּחוּצָה לָאָרֶץ מִדִּבְרֵי סוֹפְרִים, כְּדֵי שֶׁלֹּא תִּשָּׁכַח תּוֹרַת חַלָּה מִיִּשְׂרָאֵל.\nג' דִּינִים לְחַלָּה בְּשָׁלֹשׁ אֲרָצוֹת: כָּל הָאֶרֶץ שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי בָּבֶל עַד כְּזִיב, מַפְרִישִׁין בָּהּ חַלָּה אַחַת, כַּשִּׁעוּר, וְהִיא נֶאֱכֶלֶת לַכֹּהֲנִים; וּשְׁאָר אֶרֶץ יִשְׂרָאֵל, שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי מִצְרַיִם וְלֹא עוֹלֵי בָּבֶל, שֶׁהוּא מִכְּזִיב וְעַד \u0010c3\u0011 אֲמָנָה, מַפְרִישִׁין בָּהּ שְׁתֵּי חַלּוֹת, הָרִאשׁוֹנָה אֶחָד מִמ\"ח וְהִיא נִשְׂרֶפֶת; וְהַשְּׁנִיָּה אֵין לָהּ שִׁעוּר, וְנוֹתְנִים אוֹתָהּ לַכֹּהֵן לְאָכְלָהּ. וְכָל הָאָרֶץ מֵאֲמָנָה \u0010c4\u0011 וְלַחוּץ, בֵּין בְּסוּרְיָא בֵּין בִּשְׁאָר אֲרָצוֹת, מַפְרִישִׁין שְׁתֵּי חַלּוֹת, הָרִאשׁוֹנָה אֵין לָהּ שִׁעוּר, וְהִיא נִשְׂרֶפֶת; וְהַשְּׁנִיָּה, א' מִמ\"ח, וְנֶאֱכֶלֶת, וּמֻתֶּרֶת לִטְמֵאִים אֲפִלּוּ לְזָבִים וְזָבוֹת. וּבַזְּמַן הַזֶּה, שֶׁאֵין עִסָה טְהוֹרָה, מִפְּנֵי טֻמְאַת הַמֵּת, מַפְרִישִׁין חַלָּה אַחַת בְּכָל אֶרֶץ יִשְׂרָאֵל, אֶחָד מִמ\"ח, \u0010c5\u0011 וְשׂוֹרְפִין אוֹתָהּ, מִפְּנֵי שֶׁהִיא טְמֵאָה. וּמִכְּזִיב וְעַד אֲמָנָה, מַפְרִישִׁין שְׁנִיָּה לְכֹהֵן לַאֲכִילָה, וְאֵין לָהּ שִׁעוּר, כְּשֶׁהָיָה הַדָּבָר מִקֹּדֶם.\nחַלַּת חוּצָה לָאָרֶץ, אַף עַל פִּי שֶׁהִיא טְמֵאָה, הוֹאִיל וְעִקַּר חִיּוּבָהּ מִדִּבְרֵיהֶם, אֵינָהּ אֲסוּרָה בַּאֲכִילָה אֶלָּא עַל כֹּהֵן שֶׁטֻּמְאָה יוֹצְאָה עָלָיו מִגּוּפוֹ, וְהֵם בַּעֲלֵי קְרָיִים וְזָבִים וְזָבוֹת וְנִדּוֹת וְיוֹלְדוֹת. אֲבָל שְׁאָר הַטְּמֵאִים בְּמַגַּע הַטֻּמְאוֹת, אֲפִלּוּ טִמְאֵי מֵת, מֻתָּרִים לְאָכְלָהּ. לְפִיכָךְ, בֵּין בְּסוּרְיָא בֵּין בְּחוּצָה לָאָרֶץ, אִם רָצָה לְהַפְרִישׁ חַלָּה אַחַת, מַפְרִישׁ אֶחָד מִמ\"ח וְנֶאֱכֶלֶת לְקָטָן שֶׁעֲדַיִן לֹא רָאָה קֶרִי, אוֹ לִקְטַנָּה שֶׁעֲדַיִן לֹא רָאֲתָה נִדָּה, וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה. וְכֵן אִם הָיָה שָׁם כֹּהֵן גָּדוֹל שֶׁטָּבַל מִשִּׁכְבַת זַרְעוֹ אוֹ מִזִּיבָתוֹ, אַף עַל פִּי שֶׁלֹּא הֶעֱרִיב שִׁמְשׁוֹ \u0005וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ הַעֲרֵב שֶׁמֶשׁ (הר\"ן פ' אֵלּוּ עוֹבְרִין)\u0006, הֲרֵי זֶה מֻתָּר לֶאֱכֹל חַלָּה הָרִאשׁוֹנָה, וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה בְּחוּצָה לָאָרֶץ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים כֵּיוָן שֶׁאֵין חַלָּה נֶאֱכֶלֶת בַּזְּמַן הַזֶּה בְּאֶרֶץ יִשְׂרָאֵל, גַּם בִּשְׁאָר מְקוֹמוֹת אֵין צְרִיכִין לְהַפְרִישׁ רַק חַלָּה אַחַת, וּלְשָׂרְפָהּ (טוּר בְּשֵׁם י\"א וּשְׁאָר פּוֹסְקִים)\u0006. וְכֵן \u0010c6\u0011 הַמִּנְהָג פָּשׁוּט בְּכָל מְדִינוֹת אֵלּוּ, שֶׁאֵין מַפְרִישִׁין רַק חַלָּה אַחַת בְּלֹא שִׁעוּר, וְשׂוֹרְפִין אוֹתָהּ כְּמוֹ שֶׁהָיוּ עוֹשִׂין כְּשֶׁמַּפְרִישִׁין שְׁתֵּי חַלּוֹת, שֶׁחַלַּת הָאוּר לֹא הָיָה לָהּ שִׁעוּר. וּמִכָּל מָקוֹם נוֹהֲגִין לִטֹּל כַּזַּיִת \u0005(מהרי\"ל)\u0006. וְהָאוֹכֵל חַלָּה, אֲפִלּוּ בְּחוּצָה לָאָרֶץ, מְבָרֵךְ תְּחַלָּה עַל הַמִּין שֶׁרוֹצֶה לֶאֱכֹל, וְאַחַר כָּךְ מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לֶאֱכֹל תְּרוּמָה \u0005(כָּל בּוֹ וְהוּא מל' הַרַמְבַּ\"ם סוֹף הִלְכוֹת תְּרוּמָה)\u0006. וְיֵשׁ אוֹמְרִים כְּשֶׁשּׂוֹרְפִין הַחַלָּה עוֹשִׂין לָהּ הֶסֵּק בִּפְנֵי עַצְמָהּ, דְּיִשְׂרָאֵל אָסוּר לֵהָנוֹת מִמֶּנָּהּ \u0005(מהרי\"ק וְכֵן הוּא בְּתוֹסָפוֹת פ' כָּל שָׁעָה)\u0006. וְנוֹהֲגִין לְהַשְׁלִיכָהּ לַתַּנּוּר קֹדֶם שֶׁאוֹפִין הַפַּת.",[],["\u0003והנחתום. \u0004 ואף אם עושה עיסה קטנה מפריש א' ממ\"ח וכן בעה\"ב אפי' עושה עיסה מרובה כגון למשתה בנו וכה\"ג מפריש א' מכ\"ד שלא לחלק בעיסות כ\"כ הרמב\"ם והוא מהירושלמי וע\"ל ר\"ס שכ\"ח:","\u0003נטמאה. \u0004 וכתב הב\"י לקמן ר\"ס שכ\"ח דבזה\"ז דליכא טהרות וכל עיסה טמאה א\"כ אף של בעל הבית לעולם הוי א' ממ\"ח ואפי' במקום שנותנין חלה לכהן:","\u0003עזרא. \u0004 שהרי לא עלו כל ישראל עמו:","\u0003אמנה. \u0004 שהיא קרובה לארץ העמים ואין יכולין לשמור עצמן ופירותיהן בטהרה וחלותיהן טמאות וטעונין שריפה כתרומה טמאה ולכך מפרישין ב' חלות א' שהיא מן התורה צריך להפריש כשיעור ולפי שהיא טמאה נשרפת והשניה אין לה שיעור דכיון דלא תקנום אלא כדי שלא תשתכח תורת חלה אוקמוה אדאורייתא. עכ\"ל הש\"ך:","\u0003ולחוץ. \u0004 שאינו שייך לא\"י כלל ואין שם אפי' א' מן התורה גזרו בהם משום א\"י ותקנו גם כן להפריש ב' חלות \u0005(והראשונה שנשרפה אין לה שיעור הואיל ואינה מן התורה והשניה אחת ממ\"ח כיון שהיא נאכלת לכהנים ומותרת לטמאים כיון שאינה אלא מדרבנן לגמרי ועיין לבוש)\u0006:","\u0003ושורפין. \u0004 כתב מהרי\"ל בהל' פסח וצריך לשרפה במדורת כהן או כהנת ונכון לעשות לה מדורה לעצמה במקום שאין מבשלין שם או בתנור שאופין בו המצות טרם הורדו לתוכו המצות שאז ידוע לו שלא תבא לידי הנאת ישראל טרם כלייא איסוריה וכו' ונ\"ל דוקא הנאה דשרפה אסור לזר אבל שאר הנאה מותר לזר כדאמרינן לגבי תרומה ובסי' של\"א סי\"ט בהג\"ה עכ\"ל הש\"ך:","\u0003המנהג. \u0004 כ' רש\"ל מה שאין אנו נוהגים עכשיו ליתן החלה לכהן קטן משום דלא מחזקינן בזה\"ז בכהן ודאי ואין אנו יודעין איזה כהן אמיתי עכ\"ל מיהו במצות נוהגין קצת ליתנה לכהן קטן ולא בשאר ימות השנה וצריך לחלק בין פסח לשאר ימות השנה. ש\"ך \u0005(וכ\"כ מהרי\"ו בדיני פסח וכן כתבו אחרונים)\u0006:"]],["חַלַּת חוּצָה לָאָרֶץ שֶׁמֻּתֶּרֶת לְכֹהֵן טָהוֹר מִקֶּרִי, רַשַּׁאי לְאָכְלָהּ עִם זָר עַל שֻׁלְחָן אֶחָד, לְפִי שֶׁאֵינָהּ \u0010c0\u0011 מְדַמַּעַת \u0005(פֵּרוּשׁ עִנְיָן דָּמוּעַ הוּא תְּרוּמָה שֶׁנָּפְלָה בְּחֻלִּין)\u0006. וַאֲפִלּוּ נִתְעָרְבָה שָׁוֶה בְּשָׁוֶה. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין, וּסְבִירָא לְהוּ \u0010c1\u0011 דְּאוֹסֶרֶת תַּעֲרָבְתָּהּ עַד מֵאָה וְאֶחָד, אִם הוּא בְּמִינָהּ, וְשֶׁלֹּא בְּמִינָהּ עַד ס' (טוּר בְּשֵׁם ר\"י וְסֵפֶר הַתְּרוּמָה וְרֹא\"שׁ וְרוֹקֵחַ סי' שנ\"ט ומהרי\"ו סמ\"ח וְר' שִׁמְשׁוֹן)\u0006. וְאִם חָזְרָה וְנִתְעָרְבָה בָּעִסָּה, וְאֵין ק\"א לְבַטְלָה, אִם לֹא אָכַל הָעִסָּה יִשְׁאַל לְחָכָם עָלֶיהָ \u0010c2\u0011 וְיַתִּיר לוֹ כְּנֶדֶר, דְּנִשְׁאָלִין עַל הַהֶקְדֵּשׁוֹת, וְיַחֲזֹר וְיִטֹּל חַלָּה אַחֶרֶת \u0005(תְּשׁוּבַת מַיְמוֹנִי סוֹף הִלְכוֹת זְרָעִים וב\"ה בְּשֵׁם א\"ח)\u0006. וּמֻתָּר לְבַטְּלָהּ בְּרֹב. וְאוֹכְלָהּ בִּימֵי \u0010c3\u0011 טֻמְאָתוֹ. וִיכוֹלִין לִתְּנָהּ לְכֹהֵן עַם הָאָרֶץ. וְאֵין בָּהּ מִשּׁוּם כֹּהֵן הַמְסַיֵּעַ בְּמַתְּנוֹתָיו, שֶׁהוּא אָסוּר. וְאִם רָצָה לֶאֱכֹל תְּחִלָּה וְאַחַר כָּךְ יַפְרִישׁ הַחַלָּה, בְּחוּץ לָאָרֶץ מֻתָּר, מִפְּנֵי שֶׁאֵין עִקָּרָהּ אֶלָּא מִדִּבְרֵיהֶם. \u0005הַגָּה: וְצָרִיךְ לְשַׁיֵּר מְעַט יוֹתֵר מִשִּׁעוּר חַלָּה שֶׁמַּפְרִישׁ, כְּדֵי שֶׁיְּהֵא שִׁירַיִם בְּשָׁעָה שֶׁמַּפְרִישׁ (בֵּית יוֹסֵף בְּשֵׁם הָרֹא\"שׁ וּסְמַ\"ג ובהר\"ן דְּבֵיצָה)\u0006. וְדַוְקָא לְעִסָּה שֶׁנִּתְחַיֵּב עִם חַלָּה זוֹ יָכוֹל לִפְטֹר שֶׁלֹּא מִן הַמֻּקָּף, אֲבָל עִסָּה שֶׁנִּלּוֹשָׁה בִּפְנֵי עַצְמָהּ, אֵין מַפְרִישִׁין חַלָּה מֵעִסָּה אַחֶרֶת שֶׁלֹּא מִן \u0010c4\u0011 הַמֻּקָּף \u0005(בֵּית יוֹסֵף בְּשֵׁם סמ\"ק וְכָל בּוֹ)\u0006. אֲבָל חַלַּת אֶרֶץ יִשְׂרָאֵל לֹא יֹאכַל עַד שֶׁיַּפְרִישׁ. וְאֵינָהּ נִטֶּלֶת אֶלָּא מִן הַמֻּקָּף \u0005(פִּי' מִמַּה שֶּׁהוּא קָרוֹב וְסָמוּךְ)\u0006, כִּתְרוּמָה. וְאֵינָהּ נִטֶּלֶת מִן הַטָּהוֹר עַל הַטָּמֵא, לְכַתְּחִלָּה. וְכָל שֶׁבִּתְרוּמָה לֹא יִתְרֹם וְאִם תָּרַם אֵינָהּ תְּרוּמָה, כָּךְ בְּחַלָּה. וְכָל שֶׁבִּתְרוּמָה לֹא יִתְרֹם מִזֶּה עַל זֶה, כָּךְ בְּחַלָּה. וְכָל שֶׁאֵינוֹ אוֹכֵל תְּרוּמָה אֵינוֹ אוֹכֵל חַלָּה. וְכָל הָאוֹכֵל תְּרוּמָה אוֹכֵל חַלָּה.",[],["\u0003מדמעת. \u0004 כתב הש\"ך ונראה דדוקא בחלה כיון דלחם הוא שכיח ביה תערובות להכי אי לאו דאינה מדמעת הוה גזרינן אבל בשאר איסורים לא חיישינן שמא יתערבו וכמ\"ש בסימן פ\"ח ע\"ש:","\u0003דאוסרת. \u0004 וכתב סה\"ת וצריך ליזהר בה שלא יאכלנה כהן בקערה במרק רותח שלא יאסר הזר מלאכול באותה קערה וכתב הב\"ח ולפ\"ז צריך ליזהר כשנפלה חלה בתבשיל ואין בקדרה כדי לבטל החלה ימכור התבשיל או ינתן לכהן בדאיכא רוב חולין והכלי צריך הכשר ואם כלי חרס הוא ישבר עכ\"ל וכתב עליו הש\"ך דאגב שיטפא כתב כן דודאי כלי חרס נכשר ג\"כ בהגעלה ג\"פ בחלת ח\"ל כדלעיל סי' קכ\"א כיון שאין לה עיקר בדאורייתא וכ\"ש הכא דאיכא רוב חולין ובט\"ז חולק על גוף הדין של הב\"ח וכתב שכבר נתבאר דאין אנו נותנין חלה עכשיו לכהן ומה שהחמירו בזה לא ידעתי למה לא נסמוך להקל במילתא דרבנן לבטל ברוב עכ\"ל:","\u0003ויתיר. \u0004 כ' הש\"ך והא דלא אסור אפי' ביש ק\"א משום דהוה דשיל\"מ על ידי היתר החכם דהכא בנדרי הקדש כיון דאין מצוה לישאל עליהן אלא מדוחק לא הוי דשיל\"מ והכי אמרינן בש\"ס נדרים ואם נתבשלה עיסה שלא ניטלה חלה יש ליטול עדיין וא\"צ לשייר כ\"כ שלא יהא בחלה יותר משיעור ק\"א נגד העיסה דלא מחמירין בחלת ח\"ל שהיא מדרבנן רק אם נתערבה אחר שהופרשה אבל בכה\"ג שלא היה עליה שם חלה מעולם אין להחמיר ולהכי נקט הרמ\"א לישנא דאם חזרה ונתערבה דר\"ל לאחר ההפרשה לאפוקי אם עדיין לא הפריש עכ\"ל \u0005(ועוד נ\"ל דאם היו במים שנתבשל בהן העיסה ס' דשרי מטעם דסלק את מינו כמי שאינו ושא\"מ רבה עליו ומבטלו וא\"כ יוכל ליקח מעט עד שיהיה במים ס' נגדן ושרי. ד\"מ ב\"ח ש\"ך)\u0006:","\u0003טומאתו. \u0004 בזה גם החולקים מודים דדוקא לענין זר האוכלה הוא דצריך ק\"א אבל לכהן בימי טומאתו מודו דסגי ברוב ונראה דלאכלה לזרים אין לערבה לכתחלה לבטלה ברוב וכן למאן דאוסר אפי' דיעבד עד ק\"א אין לערבה לכתחלה לבטלה בק\"א מיהו אם עשה כן במזיד אע\"ג דקי\"ל לעיל בסימן צ\"ט דקנסינן ליה הכא שרי כיון דבלאו הכי יש פוסקים מתירים לערב אפילו לכתחלה עכ\"ל הש\"ך:","\u0003המוקף. \u0004 אלא צריך להקיפן יחד. ש\"ך:"]],["אֵין חַיָּב בְּחַלָּה אֶלָּא חֲמֵשֶׁת מִינֵי תְּבוּאָה. וְאֵין חַיָּב אֶלָּא חֲמֵשֶׁת רְבָעִים. וּמִדָּה שֶׁמַּחֲזֶקֶת מ\"ג בֵּיצִים וְחֹמֶשׁ בֵּיצָה, מְמַלְּאִים אוֹתָה קֶמַח, וְאוֹתוֹ קֶמַח הוּא שִׁעוּר חַלָּה. וּכְשֶׁמְּמַלְּאִים הַמִּדָּה קֶמַח, תִּהְיֶה מְחוּקָה וְלֹא גְּדוּשָׁה. וְהֵיאַךְ יְשַׁעֲרוּ לָדַעַת שֶׁהִיא מַחֲזֶקֶת מ\"ג בֵּיצִים \u0010c0\u0011 וְחֹמֶשׁ, נִתְבָּאֵר בַּטּוּר א\"ח \u0005וְעַיֵּן בא\"ח סי' תנ\"ו\u0006 וּמִשְׁקַל חֲמֵשֶׁת רְבָעִים קֶמַח הוּא תק\"כ דרה\"ם מִקֶּמַח חִטִּים שֶׁבְּמִצְרַיִם. \u0005הַגָּה: כְּלִי הַמַּחֲזִיק עֶשֶׂר אֶצְבָּעוֹת עַל עֶשֶׂר אֶצְבָּעוֹת, בְּרוּם שָׁלֹשׁ אֶצְבָּעוֹת וּתְשִׁיעִית אֶצְבַּע בְּקֵרוּב, הוּא שִׁעוּר הַחַלָּה. וְכֵן מִדָּה שֶׁיֵּשׁ בָּהּ ז' אֶצְבָּעוֹת פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע (עַל ז' פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע)\u0006, בְּרוּם ז' אֶצְבָּעוֹת פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע, הוּא \u0010c1\u0011 הָעֹמֶר. וְכָל הָאֶצְבָּעוֹת אֵלּוּ הֵם רֹחַב גּוּדָל שֶׁל יָד \u0005(רַמְבַּ\"ם פֶּרֶק ו' דְּבִכּוּרִים)\u0006.\nחֲמֵשֶׁת מִינֵי תְּבוּאָה מִצְטָרְפִין, שֶׁאִם אֵין בָּעִסָה אֶלָּא חֲמֵשֶׁת רְבָעִים מֵחֲמִשְׁתָּן, מִצְטָרְפִין. בַּמֶּה דְבָרִים אֲמוּרִים, כְּשֶׁעֵרְבָן \u0010c2\u0011 קֶמַח. אֲבָל אִם לָשׁ כָּל אֶחָד לְבַדּוֹ, וְאֵין בּוֹ כַּשִּׁעוּר, וּמְדַבְּקוֹ לְמִין אַחֵר, אֵין מִצְטָרְפִין אֶלָּא בְּזֶה הַסֵדֶר: הַחִטִּים אֵין מִצְטָרְפִין אֶלָּא עִם הַכֻּסְמִין, וְהַכֻּסְמִין מִצְטָרְפִין עִם כָּל אֶחָד וְאֶחָד. הַשְּׂעוֹרִים מִצְטָרְפִין עִם הַכֹּל חוּץ מֵעִם הַחִטִּים. שִׁיפוֹן מִצְטָרֵף עִם שְׂעוֹרִים וְכֻסְמִין, וְלֹא עִם שִׁבֹּלֶת שׁוּעָל וְחִטִּים. שִׁבֹּלֶת שׁוּעָל מִצְטָרֵף עִם שְׂעוֹרִים וְכֻסְמִים, וְלֹא עִם חִטִּים וְשִׁיפוֹן. וּלְהָרַמְבַּ\"ם, כֻּסְמִין וְשִׁבֹּלֶת שׁוּעָל וְשִׁיפוֹן מִצְטָרְפִים. וְאִם לָשׁ כָּל מִין וָמִין לְבַדּוֹ, וְיֵשׁ בּוֹ כַּשִּׁעוּר, וְרוֹצֶה לְהַפְרִישׁ מִמִּין זֶה עַל זֶה, אֵין מַפְרִישִׁין אֶלָּא עַל מִינוֹ. כֵּיצַד, אֵין מַפְרִישִׁין חִטִּים עַל שׁוּם אֶחָד מֵהֶם, וְלֹא מִשּׁוּם אֶחָד מֵהֶם עֲלֵיהֶם. וְכֻסְמִין וְשִׁיפוֹן מַפְרִישִׁין מִזֶּה עַל זֶה, וְכֵן שִׁבֹּלֶת שׁוּעָל וּשְׂעוֹרִים \u0010c3\u0011 מַפְרִישִׁים מִזֶּה עַל זֶה. \u0005הַגָּה: עֵרַב קַב מֵעִסָּה עִם קַב אַחֵר מֵעִסָּה שֶׁאֵינוֹ מִינוֹ, וְחִלְּקוֹ אַחַר כָּךְ וְהוֹסִיף עַל כָּל אֶחָד רֹבַע הַקַּב מִמִּינוֹ, חַיָּב בְּחַלָּה כֵּיוָן שֶׁלֹּא נִצְטָרְפוּ כְּשֶׁהָיוּ \u0010c4\u0011 מְעֹרָבִים. אֲבָל אִם עֵרַב קַב קֶמַח עִם קַב קֶמַח מִמִּין אַחֵר עַל דַּעַת לְחַלְּקוֹ וְחִלְּקָם וְהוֹסִיף עַל כָּל אֶחָד רֹבַע הַקַּב מִמִּינוֹ, \u0010c5\u0011 פָּטוּר (טוּר)\u0006.\nחָמֵשׁ רְבָעִים הַלָּלוּ, הַשְּׂאוֹר וְהַסֻבִּין וְהַמֻּרְסָן מִצְטָרְפִין לְהַשְׁלִים, אִם לָשָׁן בְּלֹא הַרְקָדָה, אֲבָל אִם רִקֵּד וְהִפְרִישׁ מֻרְסָן מִתּוֹכָם, \u0010c6\u0011 וְחָזַר וְעֵרְבָן עִמּוֹ, אֵינוֹ מִצְטָרֵף.\nקַב חִטִּים מִצַּד זֶה וְקַב שְׂעוֹרִים מִצַּד זֶה, וְקַב כֻּסְמִין בָּאֶמְצַע, מְחַבְּרָן וַהֲרֵי אֵלּוּ מִצְטָרְפִין. וְצָרִיךְ לְהַפְרִישׁ מִכָּל \u0010c7\u0011 מִין וָמִין.\nחֲצִי קַב חִטִּים מִצַּד זֶה, וַחֲצִי קַב שְׂעוֹרִים מִצַּד זֶה, \u0010c8\u0011 וַחֲצִי קַב כֻּסְמִין בָּאֶמְצַע, מִצְטָרְפִים, וְתוֹרֵם מִן הַכֻּסְמִין עַל שְׁלָשְׁתָּן.\nקַב חִטִּים מִצַּד זֶה וְקַב חִטִּים מִצַּד זֶה וְקַב אֹרֶז בָּאֶמְצַע, אוֹ קַב שֶׁל עוֹבֵד כּוֹכָבִים אוֹ קַב שֶׁל חַלָּה, \u0010c9\u0011 אֵינָם מִצְטָרְפִים. \u0005אֲבָל אִם הָיָה בֵּינֵיהֶם עִסָּה שֶׁכְּבָר הוּרְמָה חַלָּתָהּ, מִצְטָרְפִין (הָרֹא\"שׁ כְּלָל ב')\u0006.\nהָיָה בֵּינֵיהֶם קַב שֶׁל מִין אַחֵר מֵחֲמֵשֶׁת הַמִּינִים, אוֹ קַב מִשֶּׁל אִשָּׁה אַחֶרֶת, \u0010c10\u0011 מִצְטָרְפִין.\nקַב שֶׁל תְּבוּאָה חֲדָשָׁה וְקַב שֶׁל \u0010c11\u0011 יְשָׁנָה, אֵינָם מִצְטָרְפִים. הָיָה קַב שֶׁל יָשָׁן מִצַּד זֶה וְקַב יָשָׁן מִצַּד זֶה, וְחָדָשׁ בָּאֶמְצַע, מִצְטָרְפִין. \u0005וְהוּא הַדִּין אִפְּכָא, חָדָשׁ מִשְּׁנֵי הַצְּדָדִים וְיָשָׁן בָּאֶמְצַע (בֵּית יוֹסֵף וְטוּר)\u0006.\nהָעוֹשֶׂה עִסָה מֵהַחִטִּים וּמֵהָאֹרֶז, אִם יֵשׁ בָּהּ טַעַם דָּגָן, חַיֶּבֶת בְּחַלָּה \u0010c12\u0011 אַף עַל פִּי שֶׁרֻבָּהּ אֹרֶז; וְאִם לָאו, פְּטוּרָה.\nנָתַן שְׂאוֹר מֵעִסַת חִטִּים לְתוֹךְ עִסַת אֹרֶז, אִם יֵשׁ בָּהּ טַעַם דָּגָן חַיֶּבֶת בְּחַלָּה.\nנָתַן שְׂאוֹר מֵעִסָה שֶׁלֹּא הֻרְמָה חַלָּתָהּ לְתוֹךְ עִסָה שֶׁהֻרְמָה חַלָּתָהּ, וְהַכֹּל מִמִּין אֶחָד, אִם יֵשׁ לוֹ קֶמַח אוֹ עִסָה שֶׁלֹּא נִטַּל מִמֶּנָּהּ חַלָּה מַפְרִישׁ מִמֶּנּוּ עַל זֶה הַשְּׂאוֹר לְפִי חֶשְׁבּוֹן, דְּהַיְנוּ אֶחָד ממ\"ח \u0010c13\u0011 בַּשְּׂאוֹר \u0005וַאֲפִלּוּ אֵין בָּזֶה שִׁעוּר חַלָּה, וּבִלְבַד שֶׁיַּנִּיחֵנוּ אֵצֶל הָעִסָּה הַגְּדוֹלָה (כֵּן מַשְׁמָע בת\"ה סִימָן ק')\u0006. וְאִם לָאו, מַפְרִישׁ אֶחָד ממ\"ח בְּכָל הָעִסָה, לְפִי שֶׁנַּעֲשֵׂית כֻּלָּהּ טֶבֶל. וְהוּא הַדִּין אִם הַשְּׂאוֹר שֶׁל \u0010c14\u0011 פָּטוּר וְהָעִסָה שֶׁל חִיּוּב. \u0005הַגָּה: וּמִכָּל מָקוֹם לְכַתְּחַלָּה לֹא יִסְמֹךְ עַל זֶה, וְלֹא יִתֵּן שְׂאוֹר שֶׁל פְּטוּר בְּעִיסָה שֶׁל חִיּוּב (מָרְדְּכַי פ' מָקוֹם שֶׁנָּהֲגוּ)\u0006. אֲבָל אִם כְּבַר עָבַר וְעָשָׂה, מֻתָּר לְכַתְּחִילָה לִקַּח מֵאוֹתָהּ \u0010c15\u0011 עִסָּה וְלִתֵּן בְּעִסָּה אַחֶרֶת שֶׁיִּהְיֶה בּוֹ לַשְּׂאוֹר. \u0005(ת\"ה סי' ק')\u0006.\nמִי שֶׁנִּתְעָרֵב לוֹ פַּת שֶׁהִפְרִישׁ מִמֶּנּוּ חַלָּה עִם פַּת שֶׁלֹּא הֻפְרַשׁ מִמֶּנּוּ, אִם יֵשׁ לוֹ קֶמַח יַעֲשֶׂה עִסָה מֵחֲמִשָּׁה רְבָעִים וִיצָרְפֶנָּה עִם הַכִּכָּרוֹת בִּכְלִי, וְיַפְרִישׁ מִמֶנָּה עַל אוֹתָם כִּכָּרוֹת שֶׁנִּתְעָרְבוּ. וְאִם רוֹצֶה לְהַפְרִישׁ מִנֵּהּ וּבֵהּ, צָרִיךְ לְהַפְרִישׁ מְעַט מִכָּל כִּכָּר וְכִכָּר, אוֹ יְצָרְפֵם כֻּלָּם בִּכְלִי אֶחָד וְיַפְרִישׁ מִכָּל אֶחָד עַל כֻּלָּם, עַד שֶׁיַּפְרִישׁ מִכְּדֵי חֶשְׁבּוֹן הַכִּכָּרוֹת, וּמֵאֶחָד \u0010c16\u0011 יוֹתֵר, כְּגוֹן אִם חָמֵשׁ שֶׁהֻפְרַשׁ עֲלֵיהֶם נִתְעָרְבוּ בְּעֶשֶׂר שֶׁלֹּא הֻפְרַשׁ עֲלֵיהֶם, יַפְרִישׁ מִשִּׁשָּׁה, שֶׁאָז וַדַּאי הִפְרִישׁ מֵאֶחָד שֶׁלֹּא הֻפְרַשׁ עָלָיו. \u0005הַגָּה: הָאוֹפֶה פַּשְׁטִידָ\"א מֵעִסָּה שֶׁלֹּא הֻרְמָה חַלָּתָהּ, וּבְתוֹכוֹ בָּשָׂר, מֻתָּר לְהַפְרִישׁ \u0010c17\u0011 מֵעִסָּה אַחֶרֶת הַחַיֶּבֶת בְּחַלָּה עַל זוֹ, וְנִפְטַר גַּם כֵּן טַעַם הָעִסָּה הַנִּכְנָס בַּבָּשָׂר (בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבָה)\u0006.\nעִסָה שֶׁאֵין בָּהּ כַּשִּׁעוּר, וּבְעֵת אֲפִיָּתָהּ תָּפְחָה וְגָדְלָה עַד שֶׁנִּרְאֶה כְּאִלּוּ יֵשׁ בָּהּ \u0010c18\u0011 כַּשִּׁעוּר, פְּטוּרָה. \u0005וְהוּא הַדִּין אִם תָּפְחָה קֹדֶם אֲפִיָּה (בֵּית יוֹסֵף וּתְשׁוּבַת הָרֹא\"שׁ כְּלָל ב' וְרַשְׁבָּ\"א סִימָן תס\"א)\u0006.\nאָסוּר לַעֲשׂוֹת עִסָתוֹ פָּחוֹת מִכַּשִּׁעוּר כְּדֵי \u0010c19\u0011 לְהַפְקִיעַ מִמֶּנּוּ חִיּוּב חַלָּה.",[],["\u0003נתבאר. \u0004 כ' הש\"ך וע\"פ אותו השיעור שיערתי והוא ג' קווארט פחות מעט \u0005(ובמדינות פיהם נקרא פינ\"ט ובשאר מדינות נקרא זייד\"ל)\u0006 וכן נהגו עכ\"ל:","\u0003העומר. \u0004 והוא שיעור החלה והדבר פשוט שאלו המדות הם מרובעות שהרי למד מרביעית של תורה של פסח שהוא במרובע. ש\"ך \u0005(והלבוש נסתפק אם מרובעות או עגולות)\u0006:","\u0003קמח. \u0004 ולש אותן יחד דאז כל העיסה נראה שוה כאלו הוא ממין אחד וכתב הט\"ז נראה דה\"ה אם עשה מכל א' עיסה בפני עצמה ועירב העיסות עד שנעשו גוף אחד מצטרפין \u0005(כשאין בכל א' כשיעור)\u0006 דדוקא בדיבוק ע\"י נשיכה בעלמא הוא דאין מצטרפין \u0005(דמ\"ש רמ\"א בסמוך עירב קב מעיסה כו' מיירי כדרך נשיכה בעלמא ולא נעשין בלול כאחד אבל אם עירב העיסות ממש הוי כמו קמח בקמח)\u0006 עכ\"ל:","\u0003מפרישים. \u0004 כ' הט\"ז ונראה דאם יש מעיסה אחת כשיעור ובאחת אין שיעור ורוצה לצרפה לעיסה הגדולה הוה דינו כמו ברישא לצירוף חלה ונ\"מ אם יוסיף אח\"כ עיסת חיוב על אותו שעשה שאין בה שיעור אין לחייבו בחלה כי כבר נפטר מחמת צירוף:","\u0003מעורבים. \u0004 ולא היה להם שעת חובה עד עתה:","\u0003פטור. \u0004 כיון דבאו לידי חובה פעם אחת ונפטרו כשחלקם שוב אין חוזרין לידי חיוב חלה כדלקמן סי' שכ\"ו ומהרש\"ל כ' דיפריש בלא ברכה:.","\u0003וחזר. \u0004 דעריסותיכם אמר רחמנא ואין זה דרך עריסה לערב בו מורסין וסובין לאחר שהפרישן מן הקמח. ש\"ך:","\u0003מין. \u0004 פי' הש\"ך דר\"ל מכל מין בפני עצמו וצריך להפריש ג' חלות אבל הט\"ז כ' איך יפריש ג' חלות הא אין כאן שיעור שלש חלות אלא ברור דהכוסמין עושה החיוב ומכח זה יחייב החטים והשעורים ותו לא דהוה פטור עמהם עכ\"ל:","\u0003וחצי. \u0004 וכ' הט\"ז דאם יש חצי קב חטים מצד זה וחצי קב שעורים מצד זה וקב כוסמין באמצע ממילא אף עם הכוסמין לית שיעור ב' חלות וכיון שמפריש מן החטים נצטרפו הכוסמין עמהם ונפטרו הכוסמין כולן וא\"צ להפריש אח\"כ על השעורים שהרי אין בהם שיעור וכן להיפך:","\u0003אינם. \u0004 כיון דהאמצע אינו בדין חלה:","\u0003מצטרפין. \u0004 ואע\"פ שאינם מצטרפין לחיוב חלה מ\"מ לא חשיב כאן הפסק:","\u0003ישנה. \u0004 זהו מדרבנן מטעם גזרה שמא יבא להפריש מזה על זה כיון שהם מין א' ומבואר בב\"י דצריך להפריש לכל א' וא' מעיסה אחרת שלא הופרש חלתה וכן בדין דהא כיון דמן התורה חייבים לא אתי גזרה דרבנן לאפקועי איסורא לפטרה מחלה. ש\"ך:","\u0003אורז. \u0004 וכ' ב\"י בשם הרשב\"א דוקא באורז אמרו כן לפי שנגררים אחר החטין אבל שאר המינים לא אבל מהטור משמע להדיא דה\"ה לכל מיני דגן. ש\"ך:","\u0003בשאור. \u0004 לפי שאין השאור בטל ועושה הכל טבל ע\"כ אם מפריש ממקום אחר די בהפרשה לפי שיעור השאור לחוד משא\"כ אם אין לו קמח ממקום אחר וצריך להפריש מיניה גופיה כיון שאינו מפריש ממקום שחייב בחלה רק מחמת שקבלה העיסה טעם מהשאור ונעשה כולה חייבת יפריש כשיעור מן העיסה כולה דאזלינן בתר מעשה הפרשתו. ובטור כתב אם ירצה יביא רובע הקב מקמחו ויערבנו עם זו העיסה ויפריש ממנה וכתב הרש\"ל דאין צריך שיערבנו עם העיסה אלא אף נותן אותו בצד העיסה אם ירצה עכ\"ל הט\"ז וכתב הש\"ך דה\"ה אם נתערב עיסה שאינה של שאור שלא הורמה חלתה לתוך עיסה שהורמה חלתה דינא הכי וגם סגי בדינים אלו כשהם סמוכות אע\"פ שאין נוגעים וליכא נמי צירוף כלי כדלקמן סי' שכ\"ה עכ\"ל:","\u0003פטור. \u0004 כגון אחר הפסח שלוקחין שאור של עובדי כוכבים ונותנין אותו בעיסה יכול להפריש מיניה וביה ולא חיישינן דמתרמי בידו שאור של פטור אלא אמרינן דכולו נעשה חיוב ע\"י שנבלל וצריך ליזהר אחר הפסח שיקח חלה יותר משיעור השאור של עובד כוכבים עכ\"ל הט\"ז ובש\"ך כ' שיש להחמיר כמ\"ש מהרי\"ל שמוהר\"ש היה מורה ללוש ב' עיסות א' בשאור של עובדי כוכבים וא' כשיעור חלה בלא שאור ולקרב העיסות להדדי ויקח חלה מאותה שלא נתחמצה בשאור של עובדי כוכבים על הכל עכ\"ל:","\u0003אחרת. \u0004 כלומר שבעיסה אחרת ישאיר שאר עיסות ולא חיישינן דילמא בעיסה ראשונה שלקח ממנה לא לקח רק שאור של פטור והשתא נמי בבצק שני דילמא איתרמי רק אותו שאור פטור דכולי האי לא חיישינן דמיתרמי תרי זימני ממש אותו של פטור עכ\"ל הש\"ך:","\u0003יותר. \u0004 דאל\"כ יש לחוש נמי שיפריש מהפטור על החיוב:","\u0003מעיסה. \u0004 אבל מעיסת הפשטיד\"א עצמה לא כיון שיש בה טעם בשר וראוי לנהוג במי ששכח להפריש חלה דדינו שאוכל ואח\"כ מפריש שיפריש אח\"כ חלק קטן מאד עד שתהיה באותה עיסה שאפה ק\"א נגדה ואע\"פ שהרמ\"א לא הביא זה מ\"מ הלכה היא ודברים נכונים הם עכ\"ל הט\"ז וע\"ל בס\"ק ג' מ\"ש בשם הש\"ך:","\u0003פטורה. \u0004 דבתר שעת הגלגול אזלינן דאז עיקר החיוב. ט\"ז:","\u0003להפקיע. \u0004 אבל אם נתכוין לטעם אחר כגון בפסח שעושין עיסות קטנות כמ\"ש בא\"ח ומצטרפין ב' עיסות להדדי או שאין לו רק עיסה קטנה ודאי שרי ומ\"מ נהגו הנשים להדר בכל ע\"ש אחר שיעור חלה עכ\"ל הש\"ך: \u0003.. \u0004"]],["שְׁתֵּי עִסוֹת שֶׁאֵין בְּשׁוּם אַחַת כַּשִּׁעוּר, אִם נוֹגְעוֹת זוֹ בְּזוֹ עַד \u0010c0\u0011 שֶׁנִּדְבָּקִים מְעַט זוֹ בְּזוֹ, מִצְטָרְפִים, אִם הֵם מִמִּין הָרָאוּי לְהִצְטָרֵף, כְּפִי מַה שֶּׁנִּתְבָּאֵר בְּסִימָן שכ\"ד. וְאִם אֵינָם נִדְבָּקִים, וְהֵם בְּסַל אֶחָד, הַסַל מְצָרְפָן וַאֲפִלּוּ אַחַר שֶׁנֶּאֱפָה וְנַעֲשָׂה פַּת. וְאִם נְתָנָם עַל \u0010c1\u0011 טַבְלָא שֶׁאֵין לָהּ לְבַזְבָּז, אֵינָם מִצְטָרְפִים. \u0005הַגָּה: וְלָכֵן כְּשֶׁמְּצָרְפָם בִּכְלִי יִזָּהֵר שֶׁלֹּא יֵצֵא שׁוּם דָּבָר לְמַעְלָה מִדָּפְנֵי הַכְּלִי, דְּהַיְנוּ שֶׁיְּהֵא כָּל כִּכָּר אֶחָד אוֹ \u0010c2\u0011 עִסָּה לְמַעְלָה מִדָּפְנֵי הַכְּלִי (טוּר)\u0006. וְיֵשׁ מִי \u0010c3\u0011 שֶׁאוֹמֵר שֶׁאִם מְכַסֶה הַפַּת בְּמַפָּה חָשׁוּב כְּמוֹ כְּלִי לְצָרְפָן.\nאִם יֵשׁ \u0010c4\u0011 בְּכָל עִסָה כַּשִּׁעוּר, וְרוֹצֶה לְהַפְרִישׁ מִזּוֹ עַל זוֹ, אֵין צָרִיךְ לֹא צֵרוּף כְּלִי וְלֹא נְגִיעָה, אֶלָּא כֵּיוָן שֶׁשְּׁתֵּיהֶן לְפָנָיו מַפְרִישִׁין מִזּוֹ עַל זוֹ.",[],["\u0003שנדבקים. \u0004 בת\"ה כ' דנשיכה היינו שמודבק כ\"כ שכשיפרדו יתלשו אחת מחברתה מעט מצטרפים ודוקא אם הם של אדם אחד אבל לא של ב' נשים כדבסימן שאחר זה:","\u0003טבלא. \u0004 זהו בעיא בש\"ס ולא איפשטא וכיון דבזה\"ז כל חלה דרבנן אזלינן לקולא. ש\"ך:","\u0003למעלה. \u0004 הא אם מקצתו בפנים מצטרף דלא הוי דומיא דטבלא והב\"ח חולק בדבר עכ\"ל הש\"ך:","\u0003שאומר. \u0004 כ' הש\"ך לא ידעתי למה כתבו בשם יש מי שאומר שהרי אין חולק בדבר:","\u0003בכל. \u0004 כתב הש\"ך ונראה דה\"ה ב' עיסות שבא' יש כשיעור ובא' אין כשיעור דאפי' נגיעה לא בעי אלא שיהיו סמוכות ומפריש מן העיסה שיש בה כשיעור שיעור חלה וגם מפריש עוד ממנה אחד ממ\"ח על העיסה שאין בה כשיעור וא\"צ צירוף סל וכיסוי וכדלעיל סימן שכ\"ד סי\"א עכ\"ל:"]],["שְׁתֵּי עִסוֹת שֶׁיֵּשׁ בִּשְׁתֵּיהֶן שִׁעוּר הַחַיָּב בְּחַלָּה, וְאֵין בְּאַחַת מֵהֶן כַּשִּׁעוּר, וְנָגְעוּ זוֹ בְּזוֹ וְנָשְׁכוּ זוֹ אֶת זוֹ, אִם הָיוּ שֶׁל \u0010c0\u0011 שְׁנַיִם, אֲפִלּוּ הֵם מִמִּין אֶחָד, פְּטוּרִים מִן הַחַלָּה, שֶׁסְתָם שְׁנַיִם מַקְפִּידִים. וְאִם יָדוּעַ שֶׁאֵינָם מַקְפִּידִים עַל עֵרוּב הָעִסוֹת, הֲרֵי אֵלּוּ מִצְטָרְפוֹת. \u0005וְתַלְמִידִים הַלּוֹמְדִים לִפְנֵי רַב, סְתָמָא אֵינָם מַקְפִּידִים (מָרְדְּכַי פֶּרֶק כָּל הַבָּשָׂר)\u0006, הָיוּ שְׁנֵיהֶם שֶׁל אִישׁ אֶחָד, אִם הָיוּ מִמִּין אֶחָד כְּפִי מַה שֶּׁנִּתְבָּאֵר בְּסִימָן שכ\"ד, מִצְטָרְפִין וְחַיָּבִים בְּחַלָּה. וְאִם מִשְּׁנֵי מִינִים הָיוּ, אֵין מִצְטָרְפִין, שֶׁסְתָם אֶחָד אֵינוֹ מַקְפִּיד. וְאִם הָיָה מַקְפִּיד שֶׁלֹּא תִּגַּע עִסָה זוֹ בְּזוֹ וְלֹא תִּתְעָרֵב, אֲפִלּוּ הָיוּ מִין אֶחָד אֵין מִצְטָרְפוֹת. וְאִם הָאַחַת פַּת קִבָּר וְהָאַחַת פַּת נָאָה, אֲפִלּוּ הֵן שֶׁל אָדָם אֶחָד, מִסְתָמָא מַקְפִּיד וְאֵינוֹ מִצְטָרֵף. \u0005הַגָּה: וְהוּא הַדִּין שְׁתֵּי עִסּוֹת שֶׁיֵּשׁ בְּאַחַת כַּרְכֹּם וּבַשֵּׁנִית אֵין בָּהּ. וְכָל זֶה שֶׁאֵין שִׁעוּר בְּכָל אַחַת, אֲבָל אִם יֵשׁ בָּהֶן \u0010c1\u0011 שִׁעוּר, מַפְרִישׁ מֵאַחַת עַל חֲבֶרְתָּהּ אִם הֵן שֶׁל אָדָם אֶחָד (ת\"ה סִימָן קכ\"ט)\u0006.\nנַחְתּוֹם שֶׁעָשָׂה עִסָה לַעֲשׂוֹתָהּ שְׂאוֹר לְחַלְּקָהּ, חַיֶּבֶת בְּחַלָּה, שֶׁאִם לֹא תִּמָּכֵר יַעֲשֶׂנָּה פַּת. אֲבָל \u0005שְׁאָר אָדָם\u0006 הָעוֹשֶׂה \u0010c2\u0011 עִסָה לְחַלְּקָהּ בְּבָצֵק, פְּטוּרָה.\nשְׁנַיִם שֶׁנָּתְנוּ קֶמַח לְנַחְתּוֹם לַעֲשׂוֹת לָהֶן שְׂאוֹר, אִם אֵין בְּשֶׁל אֶחָד מֵהֶן כַּשִּׁעוּר, אַף עַל פִּי שֶׁיֵּשׁ בִּכְלָלָן כַּשִּׁעוּר, פְּטוּרָה. \u0005הַגָּה: וְדַוְקָא שֶׁעֵרְבָן שֶׁלֹּא מִדַּעְתָּן, אֲבָל מִדַּעְתָּן חַיָּב שֶׁהֲרֵי אֵינָן מַקְפִּידִין (בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006.\nשְׁנַיִם שֶׁעָשׂוּ \u0010c3\u0011 עִסָה כַּשִּׁעוּר וְחִלְּקוּהָ, וְאַחַר כָּךְ הוֹסִיף כָּל אֶחָד עַל חֶלְקוֹ עַד שֶׁהִשְׁלִימוֹ לְכַשִּׁעוּר, הֲרֵי זֶה פְּטוּרָה, שֶׁכְּבָר הָיְתָה לָהֶם שְׁעַת חוֹבָה, וְהֵם הָיוּ פְּטוּרִים בְּאוֹתָהּ שָׁעָה מִפְּנֵי שֶׁעֲשָׂאוּהָ לְחַלֵּק \u0005הַגָּה: וְהוּא הַדִּין בְּאָדָם אֶחָד שֶׁעָשָׂה ב' קַבִּין וְדַעְתּוֹ לְחַלְּקָם, וְחִלְּקָם. אֲבָל אִם לֹא עֲשָׂאָם עַל מְנַת לְחַלְּקָם, לֹא \u0010c4\u0011 מְהָנֵי הַחֲלוּקָה אַחַר כָּךְ (טוּר)\u0006.\nהַמַּפְרִישׁ חַלָּה מֵעִסָה שֶׁאֵין בָּהּ שִׁעוּר, אֵינָהּ חַלָּה. לְפִיכָךְ שְׁתֵּי עִסוֹת שֶׁאֵין בְּשׁוּם \u0005אַחַת\u0006 מֵהֶן כַּשִּׁעוּר, וְהִפְרִישׁ מִכָּל אַחַת חַלָּה וְאַחַר כָּךְ עֵרַב הָעִסוֹת וַעֲשָׂאָן עִסָה אַחַת, חַיֶּבֶת בְּחַלָּה.",[],["\u0003שנים. \u0004 ודוקא שאינם שותפים אבל אם הם שותפים חייב בחלה כדלקמן סי' ש\"ל ס\"ב וכב\"י שכל שאין דעתו לחלק הבצק אע\"פ שדעתו לחלק אחר שנאפה מצטרפין עכ\"ל הש\"ך:","\u0003מפריש. \u0004 פי' הט\"ז דהיינו ע\"י נגיעה בנשיכה ואע\"ג דבסי' שכ\"ה פסק כיון ששתיהם לפניו מפריש מזו על זו וא\"צ נשיכה ואפי' צירוף סל שאני הכא דהוי דבר שמקפיד עליו אבל הש\"ך פסק שא\"צ נגיעה ונשיכה אלא כשהם לפניו סגי ודמיא לדלעיל ס\"ס שכ\"ה וגם בנה\"כ השיג על הט\"ז בדין זה באריכות ע\"ש:","\u0003לחלקה. \u0004 פי' לכל אחד פחות משיעור חלה וכתב בתשו' מ\"ב שהמנהג בקצת מקומות שנחתום ישראל עושה עיסה גדולה ובאות הנשים ולוקחות ממנו כל אחת כשיעור חלה וכל אחת נוטלת חלה מעיסה שלקחה מהנחתום דשפיר עבדי הכי והב\"ח חולק ע\"ז וכתב שקבל מרבותיו שאיסור גמור הוא דכיון דהעיסה חייבת בחלה ביד הנחתום בגלגולו ובהפרשתו כבר פטר כל העיסה והיאך יברכו אח\"כ כל א' בפ\"ע הא הוי ברכה שאינה צריכה והט\"ז טרח ליישב המנהג דהיינו אם הוא באופן שהנשים רגילין ליקח בכל ע\"ש מזה הנחתום אבל לא באופן אחר \u0005(וע\"ש שכ' ליישב דהאי נחתום איירי שיש לו מכירין שרגילין לקנות ע\"מ כן שהם יפרישו חלה וה\"ל כאילו קנו ממנו קודם שעושה העיסה ואתי לידייהו בשעת חיוב דהיינו הגלגול וא\"א להנחתום ליטול חלה דהוי כאינו שלו)\u0006 וכתב עוד בתשו' מ\"ב אמנם מה שנוהגים בחתונה שעושים לחם גדול מה שמניחים בשעת הדרשה על השלחן וממנו לוקחים חלה הרבה נשים כל א' בפ\"ע אע\"פ שכל אשה נוטלת עיסה כדי שיעור מ\"מ לפי שמתחלה לשין הכל בבת א' אין להפריש רק חלה א' ולכן יש למחות ביד הנשים שלא יטלו מאותו לחם רק חלה א' וכתב הש\"ך שדברים פשוטים הם וכן ראיתי מהגבירה אמי הרבנית ומשאר נשים צדקניות חכמניות שנזהרו בזה עכ\"ל ובנחתום עובד כוכבים פשיטא דדינים אלו לא שייכי כלל דאינו מקנה רק אחר החלוקה. ט\"ז וע\"ל ר\"ס ש\"ל:","\u0003וחלקוה. \u0004 בעודה בצק בענין שלא היה בשום חלק כשיעור ואח\"כ הוסיפו ונראה דדוקא שאין שיעור חלה במה שהוסיף אח\"כ אלא ע\"י הצטרפות עם מה שנחלק אבל אם יש במה שהוסיף לבד כשיעור פשיטא שהוא חייב בלא\"ה ואין זה שנחלק ונפטר פוטר מה שהוסיף עכ\"ל הש\"ך:","\u0003מהני. \u0004 כתב הט\"ז נ\"ל דאף שיחלוק אח\"כ א\"צ ליטול כי אם חלה א' דבתר מעיקרא אזלינן כשהיה עיסה א' אע\"פ שיש אחר החלוקה שיעור שתי חלות עכ\"ל:"]],["הַמַּפְרִישׁ חַלָּתוֹ קֶמַח, אֵינָהּ חַלָּה, \u0010c0\u0011 וְגֶזֶל בְּיַד כֹּהֵן, וּשְׁאָר הָעִסָה חַיֶּבֶת בְּחַלָּה. וְאוֹתוֹ הַקֶּמַח שֶׁהִפְרִישׁ לְשֵׁם חַלָּה, אִם יֵשׁ בּוֹ עֹמֶר וְעָשָׂהוּ עִסָה, הֲרֵי זֶה מַפְרִישׁ מִמֶּנָּהּ חַלָּה. וְדַוְקָא בְּאוֹמֵר שֶׁיָּחוּל עָלֶיהָ שֵׁם חַלָּה בְּעוֹדוֹ קֶמַח, אֲבָל הַמַּפְרִישׁ קֶמַח וְאוֹמֵר: כְּשֶׁתֵּעָשָׂה עִסָה יָחוּל עָלֶיהָ שֵׁם חַלָּה, דְּבָרָיו קַיָּמִים.\nאֵימָתַי מַפְרִישִׁין חַלָּה, כְּשֶׁיִּתֵּן הַמַּיִם וִיעָרֵב הַקֶּמַח בַּמַּיִם. וְהוּא שֶׁלֹּא \u0010c1\u0011 יִשָּׁאֵר שָׁם בָּעֲרֵבָה קֶמַח שֶׁלֹּא נִתְעָרֵב בַּמַּיִם שִׁעוּר עֹמֶר. וְאִם אָמַר: הֲרֵי זוֹ חַלָּה עַל הָעִסָה וְעַל הַשְּׂאוֹר וְעַל הַקֶּמַח שֶׁנִּשְׁתַּיֵּר, וְלִכְשֶׁתֵּעָשֶׂה כֻּלָּהּ עִסָה אַחַת תִּתְקַדֵּשׁ זוֹ שֶׁבְּיָדִי לְשֵׁם חַלָּה, הֲרֵי זֶה מֻתָּר. וְכֵן אִם מַתְנֶה שֶׁתָּחוּל הַחַלָּה אַף עַל הַקֶּמַח שֶׁיִּתְעָרֵב אַחַר כָּךְ בִּשְׁעַת עֲרִיכָה. וְטוֹב לְלַמֵּד לַנָּשִׁים לְהַתְנוֹת כֵּן \u0005אִם יֵשׁ לָחוּשׁ שֶׁיִּתְעָרְבוּ שִׁעוּר חַלָּה אַחַר כָּךְ (בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006. וְצָרִיךְ לִזָּהֵר שֶׁלֹּא לִשְׂרֹף הַחַלָּה עַד אַחַר כָּל \u0010c2\u0011 הָעֲרִיכָה.\nהָאִדָּנָא טוֹב \u0010c3\u0011 לְהַמְתִּין מִלְּהַפְרִישׁ חַלָּה עַד אַחֵר גְּמַר לִישָׁה, שֶׁתֵּעָשָׂה כָּל הָעִסָה גּוּף אֶחָד.\nאוֹכְלִים עֲרַאי מִן הָעִסָה עַד שֶׁתִּתְגַּלְגֵּל \u0010c4\u0011 בַּחִטִּים, וְיִתְעָרֵב הַקֶּמַח בַּמַּיִם, וְתִטַּמְטֵם בַּשְּׂעוֹרִים וְתֵעָשֶׂה כָּל הָעִסָה גּוּף אֶחָד.\nאִם לֹא הִפְרִישׁ הַחַלָּה בָּצֵק, אֶלָּא אָפָה הַכֹּל, הֲרֵי זֶה מַפְרִישׁ מִן הַפַּת.",[],["\u0003וגזל. \u0004 כלומר שצריך להחזירה אם טעו ונתנו לו והט\"ז כתב דבש\"ס מוכח אפי' יודע הנותן שאין מפרישין חלה מקמח לא אמרינן דודאי גמר ונתן לשם מתנה דגזרינן זמנין דלא ידע כהן הדין על בוריו ויבא לידי איסור:","\u0003ישאר. \u0004 שאז אין החלה פוטרת מה שיתערב אח\"כ אא\"כ התנה כדמפ' ואזיל:","\u0003העריכה. \u0004 דאל\"כ אינה חלה על המתגבל אח\"כ אע\"פ שהתנה. ט\"ז:","\u0003להמתין. \u0004 דדוקא בזמן הש\"ש שהיו עושין עיסתן בטהרה חששו שמא תטמאה העיסה ויצטרכו להפריש חלה טמאה ולא תהיה ראויה לכהן אבל האידנא שכל העיסות טמאות טוב להמתין עד אחר גמר הלישה. ש\"ך:","\u0003בחטים. \u0004 פירוש דרך החטים ללוש ולגלגל יפה אבל השעורים כשילוש אותם עיסתו מתפרדת ואינו יכול לגלגל יפה ע\"כ מטמטמו ביד עד שידבקו יחד ויעשו גוף אחד עכ\"ל הט\"ז:"]],["בְּשָׁעָה שֶׁיַּפְרִישׁ חַלָּה יְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַפְרִישׁ תְּרוּמָה, \u0010c0\u0011 \u0005אוֹ לְהַפְרִישׁ חַלָּה (טוּר)\u0006. לְפִיכָךְ אָסוּר לְאִישׁ לְהַפְרִישׁ חַלָּתוֹ עָרֹם, מִפְּנֵי שֶׁאִי אֶפְשָׁר לוֹ לְבָרֵךְ כְּשֶׁהוּא \u0010c1\u0011 עָרֹם. אֲבָל הָאִשָּׁה מֻתֶּרֶת, וְהוּא שֶׁיְּהוּ פָּנֶיהָ שֶׁלְּמַטָּה טוּחוֹת בַּקַּרְקַע. \u0005וּבְמָקוֹם שֶׁמַּפְרִישִׁין ב' חַלּוֹת, לֹא יְבָרֵךְ רַק כְּשֶׁמַּפְרִישִׁין הָרִאשׁוֹנָה (כָּל בּוֹ)\u0006.\nהַסוּמָא וְהַשִּׁכּוֹר, מַפְרִישִׁין חַלָּה לְכַתְּחַלָּה.\nאֵין מַפְרִישִׁין חַלָּה בְּלֹא רְשׁוּת בַּעַל הָעִסָה. \u0005הַגָּה: מִיהוּ אִם יָדְעִינַן דִּזְכוּת הוּא לְבַעַל הָעִסָּה, כְּגוֹן שֶׁהָיְתָה הָעִסָּה מִתְקַלְקֶלֶת, מֻתָּר לִטֹּל חַלָּה בְּלֹא רְשׁוּתוֹ, דְּזָכִין לָאָדָם שֶׁלֹּא בְּפָנָיו. וְכֵן \u0010c2\u0011 מְשָׁרֶתֶת שֶׁבַּבַּיִת יְכוֹלָה לִטֹּל חַלָּה בְּלֹא רְשׁוּתוֹ, כֵּיוָן שֶׁרְגִילָה הִיא לִפְעָמִים שֶׁבַּעֲלַת הַבַּיִת נוֹתֶנֶת לָהּ רְשׁוּת (ת\"ה סי' קפ\"ח)\u0006. ב' שֻׁתָּפִין אֵין צְרִיכִין לִטֹּל רְשׁוּת זֶה מִזֶּה \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם פ\"ד דִּתְרוּמוֹת)\u0006, אֲבָל אַחֵר צָרִיךְ לִטֹּל רְשׁוּת מִשְּׁנֵיהֶם \u0005(בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006. וּמִיהוּ אִם נָתַן רְשׁוּת לְאַחֵר לְהַפְרִישׁ, אֲפִלּוּ בְּעוֹדוֹ קֶמַח, מוֹעִיל, \u0010c3\u0011 אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְחַיֵּב. וְהָאוֹרֵחַ יֹאמַר לְבַעֲלַת הַבַּיִת לְהַפְרִישׁ לוֹ חַלָּה מִכָּל עִסוֹת שֶׁתַּעֲשֶׂה לוֹ בְּעוֹד שֶׁיִּהְיֶה בְּבֵיתָהּ, כְּדֵי שֶׁלֹּא תִּצְטָרֵךְ לִטֹּל רְשׁוּת בְּכָל פַּעַם.",[],["\u0003או. \u0004 וכתב רש\"ל ע\"כ נוהגים לומר שניהם תרומה חלה עכ\"ל ומשמע דא\"צ לומר מן העיסה ואע\"ג דהדין הוא כן מ\"מ א\"צ להזכיר פרטי הדינים בברכה וע\"ל סימן כ\"ח שכתבתי הטעם למה אומרים בברכת כיסוי בעפר עכ\"ל הט\"ז:","\u0003ערום. \u0004 אע\"פ שהוא יושב מפני שערותו בולטת משא\"כ באשה. טור:","\u0003משרתת. \u0004 והב\"ח השיג על הרב בזה דמהרא\"י לא התיר לכתחילה במשרתת אפי' רגילה היא ליתן לה רשות אא\"כ היכא דאיכא חשש קלקול ואז ודאי אפי' אשה שאינה משרתת נעשית שלוחה שלא מדעתה ומשמע כל שאינה משרתת ואין כאן קלקול אסור להפריש שלא מדעתה אע\"פ שהיא מגבלת העיסה מיהו כתב דמ\"מ בדיעבד אם הפריש הגבל בלא רשות וניחא ליה לבעה\"ב שהפריש הוי חלה וא\"צ לחזור ולהפריש אבל אחר שאינו גבל אפי' דיעבד לא הוי חלה וצריך לחזור ולהפריש עכ\"ל הש\"ך ובט\"ז מאריך בדין זה ומסיק שנ\"ל להלכה דבע\"ש שמנהג הנשים להקפיד ע\"ז שכל א' תטול חלה בעצמה אז לא תפריש שום משרתת בלא צווי בעלת הבית אם לא שיש חשש קלקול עיסה \u0005(וב\"ה כ' אף שהעיסה מקולקל בע\"ש אין רשות למשרתת לפרוש חלה אבל בשאר ימי השבוע מותרת המשרתת או א' מבני ביתה להפריש חלה כיון שרגילה לתת להם להפריש דאינה מקפדת ע\"ז. עכ\"ל)\u0006:","\u0003שעדיין. \u0004 משום דמ\"מ יש בידו להביא עיסה ולומר עיסה זו תהא חלה על קמח לכשיהיה נילוש. כ\"כ התוספות:"]],["אֵין חִיּוּב חַלָּה אֶלָּא \u0010c0\u0011 בְּלֶחֶם. לְפִיכָךְ הַסֻפְגָּנִין, דְּהַיְנוּ רַכִּים הָעֲשׂוּיִים כִּסְפוֹג, וְהַדֻּבְשָׁנִין וְהָאִסְקָרֵיטִים, וְהֵם מְטֻגָּנִים בִּדְבַשׁ, פְּטוּרִים מִן הַחַלָּה.\nעִסָה שֶׁבְּלִילָתָהּ רַכָּה וַאֲפָאָהּ בְּתַנּוּר אוֹ בְּמַחֲבַת, בֵּין שֶׁהִרְתִּיחַ וְאַחַר כָּךְ הִדְבִּיק, בֵּין שֶׁהִדְבִּיק וְאַחַר כָּךְ הִרְתִּיחַ, חַיֶּבֶת בְּחַלָּה וּבִלְבַד שֶׁלֹּא עַל יְדֵי \u0010c1\u0011 מַשְׁקֶה.\nעִסָה שֶׁבְּלִילָתָהּ \u0005(רַכָּה)\u0006 עָבָה, וְגִלְגְּלָהּ עַל דַּעַת לְבַשְּׁלָהּ אוֹ לְטַגְּנָהּ אוֹ לַעֲשׂוֹתָהּ סֻפְגָּנִין אוֹ לְיַבְּשָׁהּ בַּחַמָּה, וְעָשָׂה כֵּן, \u0010c2\u0011 פְּטוּרָה. גִּלְגְּלָהּ לַעֲשׂוֹת מִמֶּנָּהּ לֶחֶם, וְנִמְלַךְ לְבַשְּׁלָהּ אוֹ לְטַגְּנָהּ אוֹ לַעֲשׂוֹתָהּ סֻפְגָּנִין אוֹ לְיַבְּשָׁהּ בַּחַמָּה, חַיֶּבֶת, שֶׁכְּבָר נִתְחַיְּבָה מִשְּׁעַת גִּלְגּוּל. גִּלְגְּלָהּ עַל דַּעַת סֻפְגָּנִין וְכַיּוֹצֵא בָּהֶן, וְנִמְלַךְ לַעֲשׂוֹתָהּ לֶחֶם, חַיֶּבֶת.\nאֲפִלּוּ כְּשֶׁעוֹשֶׂה אוֹתָהּ עַל דַּעַת לְבַשְּׁלָהּ וְכַיּוֹצֵא בוֹ, אִם דַּעְתּוֹ לֶאֱפוֹת מִמֶּנָּהּ מְעַט, \u0010c3\u0011 וַאֲפָאוֹ, אֲפִלּוּ אֵין בְּאוֹתוֹ מְעַט שִׁעוּר חַלָּה, כֻּלָּהּ מִתְחַיֶּבֶת עַל יָדוֹ.\nטְרִיתָא, דְּהַיְינוּ עִסָה שֶׁבְּלִילָתָהּ רַכָּה וְשׁוֹפְכִין אוֹתָהּ עַל הַכִּירָה וּמִתְפַּשֵּׁט עָלֶיהָ וְנֶאֱפֵית, פְּטוּרָה. אֲבָל אִם יֵשׁ בַּכִּירָה גֻּמָּא וְשׁוֹפְכִין אוֹתָהּ לְתוֹכָהּ, חָשׁוּב לֶחֶם וְחַיָּב. \u0005הַגָּה: בָּצֵק שֶׁאוֹפִין אוֹתוֹ בְּשִׁפּוּד וּמוֹשְׁחִים אוֹתוֹ בְּבֵיצִים אוֹ בְּשֶׁמֶן אוֹ בְּמֵי פֵּרוֹת, פָּטוּר (טוּר)\u0006.\nהָעוֹשֶׂה עִסָה לְיַבְּשָׁהּ בַּחַמָּה \u0010c4\u0011 בִּלְבַד, פְּטוּרָה. וְכֵן קָלִי שֶׁלָּשִׁין אוֹתוֹ בְּמַיִם אוֹ בִּדְבַשׁ, וְאוֹכְלִין אוֹתוֹ בְּלֹא אֲפִיָּה, פָּטוּר. וְקָלִי שֶׁלָּשׁוֹ כְּדֵי לֶאֱפוֹתוֹ, חַיָּב.\nלֶחֶם הֶעָשׂוּי לְכוּתָח, מַעֲשֶׂיהָ מוֹכִיחִים עָלֶיהָ. עֲשָׂאָהּ כְּעָבִין, דְּהַיְנוּ שֶׁעֲרָכוֹ וַעֲשָׂאוֹ כְּצוּרַת לֶחֶם, \u0010c5\u0011 חַיָּב. וְאִם לָאו, פָּטוּר.\nעִסָה שֶׁנִּלּוֹשָׁה בְּמַיִם רוֹתְחִין, בֵּין שֶׁנָּתַן רוֹתְחִין עַל גַּבֵּי קֶמַח בֵּין שֶׁנָּתַן קֶמַח בְּרוֹתְחִין, חַיֶּבֶת, בֵּין שֶׁאָפָה בְּתַנּוּר אוֹ בְּאִלְפָּס בְּלֹא מַשְׁקִין.\nעִסָה שֶׁנִּלּוֹשָׁה בְּמֵי פֵּרוֹת, אֲפִלּוּ בְּלֹא שׁוּם מַיִם, \u0010c6\u0011 חַיֶּבֶת בְּחַלָּה.\nיֵשׁ לִזָּהֵר מִלָּלוּשׁ בְּמֵי \u0010c7\u0011 פֵּרוֹת שֶׁאֵינָם מִשִּׁבְעָה מַשְׁקִים, אֶלָּא אִם כֵּן יְעָרֵב עִמָּהֶם אַחַת מִשִּׁבְעָה מַשְׁקִים \u0005(סמ\"ק סִימָן רי\"ח)\u0006. \u0005הַגָּה: וְעַיֵּן בא\"ח סִי' קצ\"ח בֵּאַרְתִּי מַה הֵם הַשִּׁבְעָה מַשְׁקִין. וְאִם עָבַר וְלָשׁ בְּלֹא ז' מַשְׁקִין, לֹא יִשְׂרֹף הַחַלָּה, אֶלָּא יִתֵּן אוֹתָהּ לְכֹהֵן קָטָן\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006, \u0005כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שכ\"ב.\u0006",[],["\u0003בלחם. \u0004 כלומר בעיסה שראויה לבא לידי לחם \u0005(וסתם לחם אינה אלא העשוי מקמח ומים. ש\"ך)\u0006:","\u0003משקה. \u0004 פירש הש\"ך שאפאה שלא ע\"י משקה דאילו טגנה במשקה פטורה:","\u0003פטורה. \u0004 דכיון דגלגלה ע\"ד לבשלה לא חל עליה חובת חלה דבתר דעתו אזלינן מיהו הרבה פוסקים חולקים דהיכא דבלילתה עבה אפי' גלגלה ע\"ד לבשלה נתחייבה מיד בשעת גלגול לכן יש להחמיר להפריש חלה בלא ברכה או לאפות מעט ממנה שע\"י כן תתחייב כולה בחלה עכ\"ל הש\"ך:","\u0003ואפאו. \u0004 והב\"ח כ' דאפי' לא אפאו אלא לעולם כל שנמלך לאפות מקצתו בין לקחו ממנו ואפאו או לא מתחייב בכולו ומסיק דלענין הלכה יש לדקדק דלכתחלה יפריש חלה ואח\"כ יקח אותו מעט ויאפנו מיהו אם לקח תחלה אותו מעט ואפאו צריך להפריש אח\"כ חלה מכל העיסה ג\"כ אלא שיניח אותה העיסה אפויה אצל העיסה ויפריש ממנו ומן העיסה כו' וע\"ש שהאריך. עכ\"ל הש\"ך. ובט\"ז האריך להשיג על הב\"ח ופסק דלא כוותיה ע\"ש \u0005(שמחלק אם היה כונתו תחלה לאפות ממנו נתחייב כולה תכף אבל אם כונתו היתה תחלה לבשל כולה ואח\"כ נמלך לאפות צריך דוקא לאפות תחלה אע\"ג דבנמלך לעשותה לחם חייבת בחלה תכף היינו בנמלכה לעשות מכולה לחם משא\"כ כאן שכולה יהיה מבושל רק קצת יהיה אפויה והעיקר חיוב משום גזירה צריך לאפות תחלה)\u0006 \u0005(ובנה\"כ דחה דבריו והסכים עם הב\"ח ע\"ש)\u0006:","\u0003בלבד. \u0004 מסיק הב\"י לאפוקי היכא דהתחיל ליבשה בחמה וגמר לאפותה כתקנה או איפכא דההוא ודאי לחם איקרי:","\u0003חייב. \u0004 כתב הט\"ז והאי חיוב פשוט הוא דחייב לברך עליה ככל סתם חיוב בש\"ס:","\u0003חייבת. \u0004 והש\"ך כתב דיש להפריש בלא ברכה או אם יש לו עיסה שלא הורמה יניח עיסה זו שנלושה במי פירות אצל עיסה שלא הורמה חלתה ויפריש מעיסה שלא הורמה חלתה גם על זו שנלושה במי פירות:","\u0003פירות. \u0004 או במי ביצים ואע\"ג דפסק המחבר בסמוך דחייבת בחלה מ\"מ לא ידענו מה יעשה בחלתה דאע\"פ שעכשיו כלנו טמאי מתים מ\"מ חלה זו טהורה דלא הוכשרה לקבל טומאה שמי פירות אינם נחשבים משקה להכשיר וא\"כ חלה זו טהורה היא ואסור לשרפה ולאכלה ג\"כ א\"א שאנו רובן טמאים וטמא אסור לאכול תרומה טהורה ויצטרך ליתנה לכהן קטן הלכך לכתחלה אסור ללוש רק שיערב בהן אחד מז' משקין שסימנם י\"ד שח\"ט ד\"ם ואז יהיה מוכשר לקבל טומאה ויכול לשרפה \u0005(ודוקא שיערב בשעת לישה קודם שחל חיוב חלה אבל אחר שלש ונתחייב בחלה אין לערב בו שאר משקין)\u0006 עכ\"ל הש\"ך:"]],["עִסַת עוֹבֵד כּוֹכָבִים פְּטוּרָה, אֲפִלּוּ לָשָׁהּ יִשְׂרָאֵל. וְשֶׁל יִשְׂרָאֵל, \u0010c0\u0011 חַיֶּבֶת, אֲפִלּוּ לָשָׁהּ לוֹ עוֹבֵד כּוֹכָבִים. נְתָנָהּ לְיִשְׂרָאֵל בְּמַתָּנָה, אִם עַד שֶׁלֹּא גִּלְגְּלָהּ נִתְּנָה לוֹ, חַיֶּבֶת. וְאִם לְאַחַר שֶׁגִּלְגְּלָהּ נְתָנָהּ לוֹ, פְּטוּרָה. \u0005עוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ חַלָּה, אֵינוֹ \u0010c1\u0011 כְּלוּם, וְתֵאָכֵל לְזָר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006.\nעִסַת הַשֻּׁתָּפִין חַיֶּבֶת.\nיִשְׂרָאֵל שֶׁהוּא \u0010c2\u0011 שֻׁתָּף עִם הָעוֹבֵד כּוֹכָבִים, אִם אֵין בְּחֵלֶק הַיִּשְׂרָאֵל כַּשִּׁעוּר, פְּטוּרָה. וְאִם יֵשׁ בָּהּ \u0010c3\u0011 כַּשִּׁעוּר, חַיֶּבֶת, וְיָכוֹל לְהַפְרִישׁ \u0010c4\u0011 מִנֵּיהּ וּבֵיהּ.\nעוֹבֵד כּוֹכָבִים שֶׁהָיְתָה לוֹ עִסָה, וְנִתְגַּיֵּר. גִּלְגְּלָהּ קֹדֶם שֶׁנִּתְגַּיֵּר, פָּטוּר. אַחַר שֶׁנִּתְגַּיֵּר, חַיָּב. אִם \u0010c5\u0011 סָפֵק, חַיָּב.\nשְׁנֵי עוֹבְדֵי כּוֹכָבִים שֶׁעָשׂוּ עִסָה כַּשִּׁעוּר וְחִלְּקוּהָ, וְאַחַר כָּךְ נִתְגַּיְּרוּ, וְהוֹסִיף כָּל אֶחָד עַל חֶלְקוֹ אַחַר שֶׁנִּתְגַּיֵּר עַד שֶׁהִשְׁלִימוֹ לְכַשִּׁעוּר, הֲרֵי זוֹ חַיֶּבֶת.\nהָיְתָה הָעִסָה בֵּין עוֹבֵד כּוֹכָבִים וְיִשְׂרָאֵל בְּשֻׁתָּפוּת, וְחָלְקוּ וְאַחַר כָּךְ נִתְגַּיֵּר וְהוֹסִיף כָּל אֶחָד עַל שֶׁלּוֹ עַד שֶׁהִשְׁלִים וְהוֹסִיף לְכַשִּׁעוּר, שֶׁל יִשְׂרָאֵל \u0010c6\u0011 חַיֶּבֶת, וְשֶׁל עוֹבֵד כּוֹכָבִים פְּטוּרָה. \u0005הַגָּה: וְדַוְקָא שֶׁעֲשָׂאוּהָ מִתְּחִלָּה בְּשֻׁתָּפוּת עַל מְנַת שֶׁלֹּא לְחַלְּקוֹ, וְנִמְלְכוּ לְחַלְּקָהּ אַחַר כָּךְ, אֲבָל אִם עֲשָׂאוּהָ מִתְּחִלָּה עַל מְנַת לְחַלְּקָהּ, אַף שֶׁל עוֹבֵד כּוֹכָבִים חַיֶּבֶת.\u0006\nהִפְקִיר עִסָתוֹ קֹדֶם שֶׁנִּתְגַּלְגְּלָה, וְזָכָה בָּהּ וְאַחַר כָּךְ גִּלְגְּלָהּ, אוֹ הִפְקִירָהּ אַחַר שֶׁגִּלְגְּלָהּ וְחָזַר וְזָכָה בָּהּ, חַיֶּבֶת. הִפְקִירָהּ וְנִתְגַּלְגְּלָה בְּעוֹדָהּ הֶפְקֵר, וְאַחַר כָּךְ זָכָה בָּהּ, פְּטוּרָה.\nהָעוֹשֶׂה עִסָה לִבְהֵמָה וּלְחַיָּה, פָּטוּר.\nעִסַת הַכְּלָבִים, בִּזְמַן שֶׁהָרוֹעִים אוֹכְלִים מִמֶּנָּהּ, חַיֶּבֶת. וְאִם לָאו, פְּטוּרָה. וְדַוְקָא שֶׁנִּכָּר בָּהּ שֶׁהִיא לִכְלָבִים, כְּגוֹן שֶׁאֵינָהּ עֲרוּכָה וַעֲשׂוּיָה כְּצוּרַת לֶחֶם, הָא לָאו הָכִי חַיֶּבֶת.",[],["\u0003לשה. \u0004 דלא אזלינן בתר המגלגל לא לחיוב ולא לפטור רק מי שהיתה העיסה שלו בשעת הגלגול וכתב הדרישה ויש מקומות שהנשים קונות בצק מאופה עובד כוכבים ולוקחות ממנה חלה נראה דאסור אם לא שנאמר שיש לסמוך ע\"ז הואיל ומדאורייתא מעות קונות והן נותנין המעות קודם הגלגול ועוד כיון דדרכן בכך אפשר דבלא נתינת המעות קודם לכן מותר כיון דהעובד כוכבים יודע מנהג ישראל ואדעתא דהכי לש מתחלה דינו כאלו נתנו לישראל במתנה קודם שגלגלו ובתשובות מ\"ב כתב דלאו שפיר עבדי ויש לבטל המנהג עכ\"ל הש\"ך וע\"ל סי' שכ\"ו ס\"ק ג' מ\"ש שם:","\u0003כלום. \u0004 כתב הש\"ך ומודיעין אותו שאינו צריך כדי שלא יחשוב העובד כוכבים שהזר אוכל חלה וע\"ל סי' שכ\"א סכ\"ב:","\u0003שותף. \u0004 דוקא ביש לו שותפות אבל עיסת ארנונית חייבת בחלה אע\"ג דלא מצי מסלק ליה בזוזי ואפי' אין שיעור חלה בשל ישראל דשמא ימלוך העובד כוכבים שלא ליטלה. כ\"פ הב\"ח:","\u0003חייבת. \u0004 ומשמע דאפי' העובד כוכבים עומד עליו ומפורסם שיד העובד כוכבים באמצע ואפי' קנו הקמח ביחד אפ\"ה חייבת. ש\"ך וכ\"פ הב\"ח:","\u0003וביה. \u0004 דיש בילה בדבר לח ובשיעור חלה שיפריש א\"א שלא יהיה בו משל ישראל והחלה אין לה שיעור מן התורה עכ\"ל הרא\"ש:","\u0003ספק. \u0004 כתב הש\"ך היינו משום דספק איסור לחומרא וצ\"ל היינו דוקא מדינא אבל האידנא דכל חלה היא מדרבנן ע\"כ פטור מספק וצ\"ע למה כתבו האחרונים בסתם דין זה ועכ\"פ נראה דהיכא דאיכא ספק בדבר בחלה כיון דבזה\"ז הוי דרבנן יש להפרישה בלא ברכה עכ\"ל:","\u0003חייבת. \u0004 לפי שעיסה של ישראל כשהיתה מחוברת בחלקו של עובד כוכבים לא בא לידי חיוב מעולם עד שמוסיף אח\"כ וע\"כ חייב כשמוסיף מה שאין כן חלק של עובד כוכבים שהיה מחובר לחלק ישראל שהוא בר חיוב והוי כאלו לש העובד כוכבים שיעור חלה אלא שעיקר מפני שהוא עובד כוכבים בשעת החיוב שוב אינו מועיל שום דבר להתחייב עכ\"ל הט\"ז:"]],["\u0003הלכות תרומות ומעשרות ומתנות עניים וראשית הגז\u0004\nהַתְּרוּמוֹת וּמַעַשְׂרוֹת אֵינָם נוֹהֲגִים מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל, בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת, וּנְבִיאִים הִתְקִינוּ שֶׁיִּהְיוּ נוֹהֲגִים אֲפִלּוּ בְּאֶרֶץ שִׁנְעָר, מִפְּנֵי שֶׁהִיא סְמוּכָה לְאֶרֶץ יִשְׂרָאֵל, וְרֹב יִשְׂרָאֵל הוֹלְכִים וְשָׁבִים שָׁם. וַחֲכָמִים הָרִאשׁוֹנִים הִתְקִינוּ שֶׁיִּהְיוּ נוֹהֲגִים אַף בְּאֶרֶץ מִצְרַיִם וּבְאֶרֶץ עַמּוֹן וּמוֹאָב, מִפְּנֵי שֶׁהֵם סְבִיבוֹת לְאֶרֶץ יִשְׂרָאֵל. סוּרְיָא, הַקּוֹנֶה בָּהּ שָׂדֶה חַיֶּבֶת בִּתְרוּמוֹת וּמַעַשְׂרוֹת מִדִּבְרֵי סוֹפְרִים. וּשְׁאָר הָאֲרָצוֹת, אֵין תְּרוּמוֹת וּמַעַשְׂרוֹת נוֹהֲגוֹת בָּהֶן.\nבַּזְּמַן הַזֶּה, אֲפִלּוּ בְּמָקוֹם שֶׁהֶחֱזִיקוּ בּוֹ עוֹלֵי בָּבֶל, וַאֲפִלּוּ בִּימֵי עֶזְרָא, אֵין חִיּוּב תְּרוּמוֹת וּמַעַשְׂרוֹת מִן הַתּוֹרָה, אֶלָּא מִדִּבְרֵיהֶם. מִפְּנֵי שֶׁנֶּאֱמַר: כִּי תָבֹאוּ, מַשְׁמָע בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְּצָתָן, כְּמוֹ שֶׁהָיְתָה בִּימֵי עֶזְרָא. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין, וּסְבִירָא לְהוּ דְּחַיָּבִין עַכְשָׁו בְּאֶרֶץ יִשְׂרָאֵל בִּתְרוּמוֹת וּמַעַשְׂרוֹת מִדְּאוֹרַיְתָא, אַךְ לֹא נָהֲגוּ כֵּן (טוּר בְּשֵׁם ר\"י)\u0006.\nעוֹבֵד כּוֹכָבִים שֶׁקָּנָה קַרְקַע בְּאֶרֶץ יִשְׂרָאֵל, וְחָזַר יִשְׂרָאֵל וּלְקָחָהּ מִמֶּנּוּ, מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת. מַה שֶּׁאֵין כֵּן בְּסוּרְיָא.\nפֵּרוֹת הָעוֹבֵד כּוֹכָבִים שֶׁגָּדְלוּ בְּקַרְקַע שֶׁקָּנָה בְּאֶרֶץ יִשְׂרָאֵל, אִם נִגְמְרָה מְלַאכְתָּן בְּיַד הָעוֹבֵד כּוֹכָבִים, וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים, פְּטוּרִין מִכֻּלָּם. וְאִם לְקָחָן יִשְׂרָאֵל אַחַר שֶׁנִּתְלְשׁוּ, קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן, וּגְמָרָן יִשְׂרָאֵל, חַיָּבִים וּמַפְרִישׁ תְּרוּמָה וּמַעֲשֵׂר רִאשׁוֹן וּתְרוּמַת מַעֲשֵׂר, וּמְשַׁיֵּר לְעַצְמוֹ מַעֲשֵׂר רִאשׁוֹן, וְהוּא שֶׁלּוֹ, מִפְּנֵי שֶׁהוּא אוֹמֵר לַלֵּוִי: אֲנִי בָּאתִי מִכֹּחַ אִישׁ שֶׁאֵין אַתָּה יָכוֹל לִטֹּל מִמֶּנּוּ. \u0005וְהַתְּרוּמַת מַעֲשֵׂר מוֹכֵר \u0010c0\u0011 לַכֹּהֵן וְנוֹטֵל דָּמֶיהָ (טוּר)\u0006.\nמָכַר הָעוֹבֵד כּוֹכָבִים הַפֵּרוֹת שֶׁלּוֹ לְיִשְׂרָאֵל כְּשֶׁהֵן מְחֻבָּרִים לַקַּרְקַע, אִם עַד שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, וְנִגְמְרוּ בְּיַד יִשְׂרָאֵל, חַיָּב בַּכֹּל וְנוֹתֵן כָּל מַעֲשֵׂר רִאשׁוֹן לַלֵּוִי. וְאִם מְכָרָן אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת וְנוֹתֵן הַמַּעֲשֵׂר לַלֵּוִי לְפִי חֶשְׁבּוֹן. כֵּיצַד, לָקַח תְּבוּאָה זְרוּעָה מִעוֹבֵד כּוֹכָבִים אַחַר שֶׁהֵבִיאָה שְׁלִישׁ, וְנִגְמְרָה בְּיַד יִשְׂרָאֵל, מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת וְנוֹתֵן לַלֵּוִי שְׁנֵי שְׁלִישֵׁי הַמַּעֲשֵׂר \u0010c1\u0011 רִאשׁוֹן.\nיִשְׂרָאֵל שֶׁמָּכַר פֵּרוֹתָיו לְעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁיָּבוֹאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, וּגְמָרָן הָעוֹבֵד כּוֹכָבִים, פְּטוּרִין מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. וְאִם אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, אַף עַל פִּי שֶׁגְּמָרָן הָעוֹבֵד כּוֹכָבִים, \u0010c2\u0011 חַיָּב בַּכֹּל.\nמָכַר עוֹבֵד כּוֹכָבִים לְיִשְׂרָאֵל פֵּרוֹת מְחֻבָּרִים, אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים בִּרְשׁוּת יִשְׂרָאֵל, אֵינָם חַיָּבִים בִּתְרוּמָה וּמַעַשְׂרוֹת, הוֹאִיל וּבָאוּ לְעוֹנַת הַמַּעַשְׂרוֹת בִּרְשׁוּת עוֹבֵד כּוֹכָבִים וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים, אַף עַל פִּי שֶׁהֵם בִּרְשׁוּת יִשְׂרָאֵל. הַקּוֹנֶה פֵּרוֹת מֵעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, בֵּין תְּלוּשִׁים בֵּין מְחֻבָּרִים, אֲפִלּוּ קֹדֶם שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, אַף עַל פִּי שֶׁמֵּרְחָן יִשְׂרָאֵל, פְּטוּרִים. וְאִם עֲדַיִן לֹא \u0010c3\u0011 הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת, הוֹאִיל וְקָנָה אוֹתָם עִם הַקַּרְקַע, חַיָּב לְעַשֵּׂר.\nיִשְׂרָאֵל שֶׁהָיָה אָרִיס לְעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, פֵּרוֹתָיו פְּטוּרִים, לְפִי שֶׁאֵין לוֹ \u0010c4\u0011 בְּגוּף הַקַּרְקַע כְּלוּם. וְכֵן הַחוֹכֵר וְהַמְקַבֵּל וְהַשּׂוֹכֵר שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, פֵּרוֹתָיו פְּטוּרִין.\nיִשְׂרָאֵל שֶׁלָּקַח בְּסוּרְיָא שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים עַד שֶׁלֹּא הֵבִיאָה שְׁלִישׁ, וְחָזַר וּמְכָרָהּ לְעוֹבֵד כּוֹכָבִים אַחַר שֶׁהֵבִיאָה שְׁלִישׁ, אִם חָזַר יִשְׂרָאֵל וּלְקָחָהּ פַּעַם שְׁנִיָּה, חַיָּב, שֶׁהֲרֵי נִתְחַיֵּב בְּיַד יִשְׂרָאֵל.\nיִשְׂרָאֵל שֶׁהָיָה לוֹ קַרְקַע בְּסוּרְיָא, וְהוֹרִיד לָהּ אָרִיס וְשָׁלַח לוֹ הָאָרִיס פֵּרוֹת, הֲרֵי אֵלּוּ פְּטוּרִים, שֶׁאֲנִי אוֹמֵר: מֵהַשּׁוּק לְקָחָן; וְהוּא שֶׁיִּהְיֶה אוֹתוֹ הַמִּין מָצוּי בַּשּׁוּק.\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים חַיֶּבֶת בִּתְרוּמָה וּמַעַשְׂרוֹת. כֵּיצַד, יִשְׂרָאֵל וְעוֹבֵד כּוֹכָבִים שֶׁלָּקְחוּ שָׂדֶה בְּשֻׁתָּפוּת, אֲפִלּוּ חִלְּקוּ שָׂדֶה בְּקָמָתָהּ, וְאֵין צָרִיךְ לוֹמַר אִם חִלְּקוּ גָּדִישׁ, הֲרֵי טֶבֶל וְחֻלִּין מְעֹרָבִים בְּכָל קֶלַח וְקֶלַח מֵחֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים, אַף עַל פִּי שֶׁמֵּרְחָן הָעוֹבֵד כּוֹכָבִים, וְחַיָּבִים מִדִּבְרֵיהֶם. בַּמֶּה דְבָרִים אֲמוּרִים, בְּאֶרֶץ יִשְׂרָאֵל, שֶׁהַמַּעַשְׂרוֹת שֶׁל תּוֹרָה, וּבְשֶׁל תּוֹרָה אֵין בְּרֵירָה. אֲבָל אִם לָקְחוּ שָׂדֶה בְּסוּרְיָא, הוֹאִיל וְהַמַּעַשְׂרוֹת שָׁם מִדִּבְרֵיהֶם, אֲפִלּוּ חִלְּקוּ הַגָּדִישׁ, חֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים פָּטוּר מִכְּלוּם. וְנִרְאֶה לִי דְּהָאִדָּנָא שֶׁאֵין חִיּוּב תְּרוּמוֹת וּמַעַשְׂרוֹת בְּאֶרֶץ יִשְׂרָאֵל, אֶלָּא מִדִּבְרֵיהֶם, גַּם בְּאֶרֶץ יִשְׂרָאֵל חֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים פָּטוּר מִכְּלוּם.\nפֵּרוֹת אֶרֶץ יִשְׂרָאֵל שֶׁיָּצְאוּ חוּצָה לָאָרֶץ, פְּטוּרִים מִתְּרוּמוֹת וּמַעַשְׂרוֹת. וְאִם יָצְאוּ לְסוּרְיָא, חַיָּבִים. וּפֵרוֹת חוּצָה לָאָרֶץ שֶׁנִּכְנְסוּ לָאָרֶץ, חַיָּבִים, אִם \u0010c5\u0011 נִקְבְּעוּ לְמַעֲשֵׁר \u0005(בְּיָד יִשְׂרָאֵל)\u0006 אַחֵר שֶׁנִּכְנְסוּ לְאֶרֶץ.\nכָּל אֹכֶל אָדָם, הַנִּשְׁמָר, שֶׁגִּדּוּלָיו מִן הָאֶרֶץ, \u0010c6\u0011 חַיָּב בִּתְרוּמָה.\nאֵין מַפְרִישִׁין תְּרוּמוֹת וּמַעַשְׂרוֹת \u0010c7\u0011 מֵהַיָּרָק בְּחוּץ לָאָרֶץ, אֲפִלּוּ בִּמְקוֹמוֹת שֶׁאָמַרְנוּ שֶׁחִיְּבוּם חֲכָמִים. וְכֵן יָרָק הַבָּא מֵחוּצָה לָאָרֶץ לָאָרֶץ, אַף עַל פִּי שֶׁיֵּשׁ עָפָר בְּעִקְּרֵיהֶן, הֲרֵי זֶה פָּטוּר.\nהַתְּבוּאָה וְהַזֵּיתִים שֶׁלֹּא הֵבִיאוּ \u0010c8\u0011 שְׁלִישׁ, פְּטוּרִים מִתְּרוּמָה וּמַעַשְׂרוֹת. וּמִנַּיִן יוֹדֵעַ, כָּל שֶׁזּוֹרְעָהּ וּמַצְמַחַת, בְּיָדוּעַ שֶׁהֵבִיאָה שְׁלִישׁ. \u0010c9\u0011\nהַהֶפְקֵר פָּטוּר מִתְּרוּמָה וּמַעַשְׂרוֹת. אֲבָל הַזּוֹרֵעַ שְׂדֵה הֶפְקֵר, חַיָּב בִּתְרוּמָה וּמַעַשְׂרוֹת.\nדְּבָרִים שֶׁאֵין דֶּרֶךְ רֹב בְּנֵי אָדָם לְזָרְעָם בַּגַּנּוֹת וּבַשָּׂדוֹת, אֶלָּא חֶזְקָתָן מִן הַהֶפְקֵר, פְּטוּרִין מִתְּרוּמָה וּמַעַשְׂרוֹת.\nנִתְעָרְבוּ פֵּרוֹת הַחַיָּבִים בִּתְרוּמָה וּמַעֲשֵׂר בְּפֵרוֹת הַפְּטוּרִים, אִם יֵשׁ לוֹ פֵּרוֹת אֲחֵרִים הַחַיָּבִים, מוֹצִיא \u0010c10\u0011 מֵהֶם, לְפִי חֶשְׁבּוֹן פֵּרוֹת חַיָּבִים שֶׁבַּתַּעֲרוֹבוֹת. וְאִם לָאו, מוֹצִיא תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר עַל הַכֹּל, וּמַפְרִישׁ מַעֲשֵׁר רִאשׁוֹן וְשֵׁנִי, לְפִי \u0010c11\u0011 חֶשְׁבּוֹן פֵּרוֹת חַיָּבִים שֶׁבַּתַּעֲרוֹבוֹת.\nתְּרוּמָה גְּדוֹלָה, בַּזְּמַן הַזֶּה שֶׁהִיא עוֹמֶדֶת לִשְׂרֵפָה מִפְּנֵי הַטֻּמְאָה, שִׁעוּרָהּ כָּל \u0010c12\u0011 שֶׁהוּא. \u0005הַגָּה: וְנוֹתְנָה בַּזְּמַן הַזֶּה לְכָל כֹּהֵן שֶׁיִּרְצֶה, בֵּין חָבֵר בֵּין עַם הָאָרֶץ, וַאֲפִלּוּ אֵינוֹ מְיֻחָס רַק שֶׁמֻּחְזָק בְּכֹהֵן, וְהוּא שׂוֹרְפָהּ, וְיָכוֹל \u0010c13\u0011 לְהַנִּיחָהּ וּלְשָׂרְפָהּ, עַד שֶׁיָּכוֹל לֵהָנוֹת מִמֶּנָּהּ בִּשְׁעַת שְׂרֵפָתָהּ. אֲבָל זָר אָסוּר לֵהָנוֹת מִמֶּנָּהּ בִּשְׁעַת שְׂרֵפָתָהּ, אִם לֹא שֶׁכֹּהֵן נֶהֱנֶה עִמּוֹ. אֲבָל שְׁאָר הֲנָאוֹת שֶׁאֵינוֹ מְכַלֶּה אוֹתָהּ, מֻתֶּרֶת אֲפִלּוּ לְזָרִים (טוּר)\u0006. כֹּהֵן שֶׁאוֹכֵל אֵצֶל יִשְׂרָאֵל, נוֹתֵן \u0010c14\u0011 בַּנֵּר שֶׁמֶן שֶׁל תְּרוּמָה, וְאַף עַל פִּי שֶׁעוֹמֵד הַכֹּהֵן וְהוֹלֵךְ לוֹ, אֵין צָרִיךְ לְכַבּוֹתוֹ עַד שֶׁיִּכְבֶּה מֵעַצְמוֹ \u0005(מָרְדְּכַי פ' אַלְמָנָה לכה\"ג)\u0006. וְכָל זֶה מַיְרֵי בִּתְרוּמָה \u0010c15\u0011 שֶׁהֻכְשְׁרָה, דְּאָז נִטְמֵאת וּמֻתָּר לְשָׂרְפָהּ. אֲבָל אִם לֹא הֻכְשְׁרָה, שֶׁלֹּא נִטְמֵאת, אָסוּר לְשָׂרְפָהּ. וְטוֹב לְהַכְשִׁיר \u0010c16\u0011 אוֹתָם קֹדֶם מֵרוּחַ, כְּדֵי שֶׁתְּקַבֵּל טֻמְאָה וִיהֵא מֻתָּר לְשָׂרְפָהּ \u0005(טוּר)\u0006. וְאַחַר כָּךְ מַפְרִישׁ מִן הַשְּׁאָר אֶחָד מֵעֲשָׂרָה, וְהוּא נִקְרָא מַעֲשֵׁר רִאשׁוֹן וְנוֹתְנוֹ לְלֵוִי. \u0005וְיֵשׁ אוֹמְרִים אַף \u0010c17\u0011 לְכֹהֵן (טוּר)\u0006. וְעַל זֶה נֶאֱמַר בְּתוֹרָה: כִּי אֶת מַעְשַּׂר בְּנֵי יִשְׂרָאֵל וְגו' \u0005(בַּמִּדְבָּר יח, כד)\u0006 וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי אֶת כָּל מַעֲשֵׁר בְּיִשְׂרָאֵל וְגו' \u0005(בְּמִדְבָּר יח, כא)\u0006 וְאַחַר כָּךְ מַפְרִישׁ מֵהַשְּׁאָר אֶחָד מֵעֲשָׂרָה, וְהוּא נִקְרָא מַעֲשֵׂר שֵׁנִי, וְהוּא לִבְעָלָיו, וּבְסִימָן זֶה יִתְבָּאֲרוּ מִשְׁפָּטָיו, וְעָלָיו נֶאֱמַר: עַשֵּׂר תְּעַשֵּׂר \u0005(דְּבָרִים יד, כב)\u0006 וְעַל הַסֵדֶר הַזֶּה מַפְרִישִׁין בְּשָׁנָה רִאשׁוֹנָה מֵהַשָּׁבוּעַ, וּבַשְּׁנִיָּה וּבָרְבִיעִית וּבַחֲמִישִׁית. אֲבָל בַּשְּׁלִישִׁית וּבַשִּׁשִּׁית מֵהַשָּׁבוּעַ, אַחַר שֶׁמַּפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן, מַפְרִישִׁין מֵהַשְּׁאָר מַעֲשֵׂר אַחֵר, וְנוֹתְנִים לַעֲנִיִּים, וְהוּא נִקְרָא מַעֲשֵׂר עָנִי. וְאֵין בִּשְׁתֵּי שָׁנִים אֵלּוּ מַעֲשֵׂר שֵׁנִי אֶלָּא מַעֲשַׂר עָנִי, וְעָלָיו נֶאֱמַר: מִקְצֵה שָׁלֹשׁ שָׁנִים תּוֹצִיא אֶת כָּל מַעְשַּׂר תְּבוּאָתְךָ וגו' וּבָא הַלֵּוִי \u0010c18\u0011 וגו' \u0005(דְּבָרִים יד, כח כט)\u0006 שְׁנַת הַשְּׁמִטָּה כֻּלָּהּ הֶפְקֵר וְאֵין בָּהּ לֹא תְּרוּמָה וְלֹא מַעַשְׂרוֹת כְּלָל. וּבְחוּצָה לָאָרֶץ שֶׁאֵין בָּהּ שְׁמִטַּת קַרְקַע, מַפְרִישִׁין בִּשְׁנַת הַשְּׁמִטָּה בְּאֶרֶץ מִצְרַיִם וּבְעַמּוֹן \u0010c19\u0011 וּמוֹאָב מַעֲשֵׂר רִאשׁוֹן וּמַעֲשַׂר עָנִי. וּבְאֶרֶץ שִׁנְעָר, מַפְרִישִׁין בָּהּ מַעֲשֵׂר שֵׁנִי, כְּמוֹ בְּרֹב הַשָּׁנִים. וּשְׁנַת הַשְּׁמִטָּה הָאֲמִתִּית הָיְתָה שְׁנַת \u0010c20\u0011 השי\"ג \u0005וְיֵשׁ אוֹמְרִים אִם עוֹבֵד כּוֹכָבִים מָכַר פֵּרוֹת בַּשְּׁבִיעִית לְיִשְׂרָאֵל, וּגְמַר מְלַאכְתּוֹ בְּיַד יִשְׂרָאֵל, חַיָּבִים בִּתְרוּמָה וּמַעֲשֵׂר, וּמַפְרִישׁ מַעֲשַׂר עָנִי כְּדִין עַמּוֹן וּמוֹאָב (בֵּית יוֹסֵף וְכֵן כָּתַב כַּפְתּוֹר וָפֶרַח)\u0006.\nמַעֲשֵׂר רִאשׁוֹן שֶׁלּוֹקֵחַ הַלֵּוִי, מַפְרִישׁ מִמֶּנּוּ אֶחָד מֵעֲשָׂרָה וְנוֹתְנוֹ לַכֹּהֵן, וְהוּא נִקְרָא תְּרוּמַת מַעֲשֵׂר, וְעָלָיו נֶאֱמַר: וְאֶל הַלְוִיִּם תְּדַבֵּר וגו' \u0005(בַּמִּדְבָּר יח, כו)\u0006 \u0005וְדִין תְּרוּמַת מַעֲשֵׂר כְּדִין תְּרוּמָה גְּדוֹלָה; מִיהוּ אֲפִלּוּ הָאִדָּנָא בָּעֵינָן לִתֵּן כַּשִּׁעוּר\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006.\nהַמַּרְבֶּה בִּתְרוּמָה, הוֹאִיל וְשִׁיֵּר מִקְצָת חֻלִּין, הֲרֵי זֶה תְּרוּמָה. אֲבָל אִם אָמַר: כָּל הַפֵּרוֹת הָאֵלּוּ תְּרוּמָה, לֹא אָמַר \u0010c21\u0011 כְּלוּם.\nהָאוֹמֵר: תְּרוּמַת הַכֶּרִי לְתוֹכוֹ, אִם אָמַר: בִּצְפוֹנוֹ, אוֹ בִּדְרוֹמוֹ, קָרָא שֵׁם וְחַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָתוֹ; וְאִם \u0010c22\u0011 לֹא צִיֵּן הַמָּקוֹם, לֹא אָמַר כְּלוּם.\nאָמַר: תְּרוּמַת הַכֶּרִי הַזֶּה בָּזֶה וְהַכֶּרִי הַזֶּה בָּזֶה, מָקוֹם שֶׁנִּסְתַּיְּמָה תְּרוּמָתוֹ שֶׁל הָרִאשׁוֹן שָׁם נִסְתַּיְּמָה תְּרוּמָתוֹ שֶׁל שֵׁנִי.\nתְּרוּמַת מַעֲשֵׂר אֵין מַפְרִישִׁין אוֹתָהּ בְּאֹמֶד, אֶלָּא מְדַקְדֵּק בְּשִׁעוּרָהּ, וַאֲפִלּוּ בַּזְּמַן הַזֶּה; דָּבָר שֶׁדַּרְכּוֹ לִמְדֹּד, מוֹדֵד. וְדָבָר הַנִּשְׁקָל, שׁוֹקֵל. וְדָבָר שֶׁאֶפְשָׁר לִמְנוֹתוֹ, מוֹנֶה. הָיָה אֶפְשָׁר לִמְנוֹתוֹ וּלְשָׁקְלוֹ וְלִמְדָדוֹ, הַמּוֹנֶה מְשֻׁבָּח, וְהַמּוֹדֵד מְשֻׁבָּח מִמֶּנּוּ, וְהַשּׁוֹקֵל מְשֻׁבָּח מִשְּׁנֵיהֶם. \u0005וְנִטֶּלֶת שֶׁלֹּא מִן הַמֻּקָּף. וְתַלְמִידֵי חֲכָמִים אֵין תּוֹרְמִין אֶלָּא מִן הַמֻּקָּף (הַרַמְבַּ\"ם פ\"ג)\u0006.\nאֵין תּוֹרְמִין תְּרוּמָה גְּדוֹלָה אֶלָּא מִן \u0010c23\u0011 הַמֻּקָּף. כֵּיצַד, הָיוּ לוֹ חֲמִשִּׁים סְאָה בְּבַיִת זֶה וַחֲמִשִּׁים סְאָה בְּבַיִת אַחֵר, לֹא יַפְרִישׁ מֵאֶחָד מֵהֶם עַל שְׁנֵיהֶם, וְאִם הִפְרִישׁ שֶׁלֹּא מִן הַמֻּקָּף, תְּרוּמָתוֹ תְּרוּמָה, וְהוּא שֶׁיִּהְיֶה הַמֻּפְרָשׁ שָׁמוּר. אֲבָל אִם הָיָה טָעוּן כַּדֵּי יַיִן אוֹ שֶׁמֶן, וְרָאָה \u0010c24\u0011 שֶׁמִּשְׁתַּבְּרִין, וְאָמַר: הֲרֵי הֵם תְּרוּמָה עַל פֵּרוֹת שֶׁבְּבֵיתִי, לֹא אָמַר כְּלוּם. ונ\"ל דְּבַזְּמַן הַזֶּה לְאִבּוּד אָזְלָא מִפְּנֵי הַטֻּמְאָה, תְּרוּמָתוֹ תְּרוּמָה.\nפֵּרוֹת הַמְפֻזָּרִים בְּתוֹךְ הַבַּיִת, אוֹ שְׁתֵּי מְגוּרוֹת \u0005(פי' מְקוֹמוֹת שֶׁמַּכְנִיסִים בָּהֶן פֵּרוֹת מֵעִנְיַן יְגֹרֵהוּ בְחֶרְמוֹ)\u0006 \u0005(חֲבַקוּק א, טו)\u0006 שֶׁבְּבַיִת אֶחָד, תּוֹרֵם מֵאֶחָד עַל \u0010c25\u0011 הַכֹּל. \u0005(שַׂקֵי תְּבוּאָה וְעִגּוּלֵי דְּבֵלָה וְחָבִיּוֹת שֶׁל גְּרוֹגָרוֹת, אִם הָיוּ בְּהֶקֵפָה אַחַת, תּוֹרֵם מֵאֶחָד עַל הַכֹּל)\u0006. חָבִיּוֹת שֶׁלֹּא סָתַם אֶת פִּיהֶם, תּוֹרֵם מֵאֶחָד עַל הַכֹּל; מִשֶּׁיִּסָתֵם, תּוֹרֵם מִכָּל אֶחָד וְאֶחָד.\nהַמַּקְדִּים מַעֲשֵׂר שֵׁנִי לְרִאשׁוֹן, אוֹ מַעֲשֵׂר רִאשׁוֹן לִתְרוּמָה, אַף עַל פִּי שֶׁעָבַר בְּלֹא תַּעֲשֶׂה, מַה שֶּׁעָשָׂה עָשׂוּי.\nהָרוֹצֶה לְהַפְרִישׁ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר כְּאֶחָד, מַפְרִישׁ אֶחָד מִמֵּאָה וּמְעַט יוֹתֵר, וְאוֹמֵר: אֶחָד מִמֵּאָה שֶׁיֵּשׁ כָּאן, הֲרֵי הוּא בְּצַד זֶה שֶׁהִפְרַשְׁתִּי וַהֲרֵי הוּא \u0010c26\u0011 חֻלִּין; וְהַנִּשְׁאָר מִזֶּה שֶׁהִפְרַשְׁתִּי, שֶׁהוּא הַמְּעַט הַיָּתֵר עַל אֶחָד מִמֵּאָה, הוּא תְּרוּמָה עַל הַכֹּל; וְהַמַּעֲשֵׂר שֶׁרָאוּי לִהְיוֹת לְמֵאָה חֻלִּין אֵלּוּ, הֲרֵי הוּא \u0010c27\u0011 בְּצַד זֶה שֶׁהִפְרַשְׁתִּי; וְזֶה הַנִּשְׁאָר יוֹתֵר עַל הַתְּרוּמָה מִמַּה שֶּׁהִפְרַשְׁתִּי הֲרֵי הוּא תְּרוּמַת מַעֲשֵׂר עַל הַכֹּל.\nעוֹשֶׂה אָדָם \u0010c28\u0011 שָׁלִיחַ לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת.\nחֲמִשָּׁה אִם תָּרְמוּ, אֵין תְּרוּמָתָן תְּרוּמָה; חֵרֵשׁ, שׁוֹטֶה וְקָטָן וְעוֹבֵד כּוֹכָבִים שֶׁתָּרַם שֶׁל יִשְׂרָאֵל, אֲפִלּוּ בִּרְשׁוּתוֹ, וְהַתּוֹרֵם שֶׁאֵינוֹ שֶׁלּוֹ שֶׁלֹּא בִּרְשׁוּת הַבְּעָלִים; אֲבָל הַתּוֹרֵם מִשֶּׁלוֹ עַל שֶׁל אֲחֵרִים, הֲרֵי זֶה תְּרוּמָה וְתִקֵּן פֵּרוֹתֵיהֶם, וְטוֹבַת הֲנָאָה שֶׁלּוֹ שֶׁנּוֹתְנָהּ לְכָל כֹּהֵן שֶׁיִּרְצֶה.\nהַתּוֹרֵם שֶׁלֹּא בִּרְשׁוּת, אוֹ שֶׁיָּרַד לְתוֹךְ שְׂדֵה חֲבֵרוֹ וְלִקֵּט פֵּרוֹת שֶׁלֹּא בִּרְשׁוּת, כְּדֵי שֶׁיִּקָּחֵם, וְתָרַם; אִם בָּא בַּעַל הַבַּיִת וְאָמַר לֵיהּ: כַּלֵּךְ אֵצֶל יָפוֹת, אִם הָיוּ שָׁם יָפוֹת מִמַּה שֶּׁתָּרַם, תְּרוּמָתוֹ \u0010c29\u0011 תְּרוּמָה. וְאִם לָאו, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְאִם לִקֵּט בַּעַל הַבַּיִת וְהוֹסִיף, בֵּין כָּךְ וּבֵין כָּךְ תְּרוּמָתוֹ תְּרוּמָה.\nהַמְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ, אוֹ שֶׁשּׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר, וְהֶעָרֹם, וְהַשִּׁכּוֹר, וְהַסוּמָא, לֹא יִתְרְמוּ; וְאִם תָּרְמוּ, תְּרוּמָתָן תְּרוּמָה. וּבַזְּמַן הַזֶּה, דְּלִשְׂרֵפָה אָזְלָא מִפְּנֵי הַטֻּמְאָה, תּוֹרְמִים שִׁכּוֹר וְסוּמָא וַאֲפִלּוּ לְכַתְּחַלָּה, תְּרוּמָה, אֲבָל לֹא מַעֲשַׂר \u0010c30\u0011 לֵוִי.\nקָטָן שֶׁהִגִּיעַ לְעוֹנַת נְדָרִים, אַף עַל פִּי שֶׁלֹּא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְלֹא נַעֲשָׂה גָּדוֹל, אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה.\nהָאוֹמֵר לִשְׁלוּחוֹ: צֵא וּתְרֹם לִי, וְהָלַךְ לִתְרֹם, וְאֵינוֹ יוֹדֵעַ אִם תָּרַם, וּבָא וּמָצָא כֶּרִי תָּרוּם, אֵין חֶזְקָתוֹ תָּרוּם; חוֹשְׁשִׁין, שֶׁמָּא אַחֵר תָּרַם בְּלֹא רְשׁוּת. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּבִכְהַאי גַּוְנָא חֶזְקָתוֹ תָּרוּם, דְּאָמְרִינַן: חֲזָקָה שָׁלִיחַ עוֹשֶׂה שְׁלִיחוּתוֹ, אֲפִלּוּ בְּאִסּוּר דְּאוֹרַיְתָא. אֲבָל אִם אֵינוֹ יוֹדֵעַ אִם כֶּרִי תָּרוּם אוֹ לֹא, אָסוּר לֶאֱכֹל מִמֶּנּוּ, דְּהַשָּׁלִיחַ אוֹמֵר: וַדַּאי לֹא יִגַּע בּוֹ עַד שֶׁיֵּדַע שֶׁהוּא תָּרוּם. (טוּר בְּשֵׁם הָרֹא\"שׁ והר\"ש)\u0006.\nפֵּרוֹת הַשֻּׁתָּפִין חַיָּבִים בִּתְרוּמָה וּמַעַשְׂרוֹת, וְאֵינָם צְרִיכִים לִטֹּל רְשׁוּת זֶה מִזֶּה, אֶלָּא כָּל הַתּוֹרֵם מֵהֶם תְּרוּמָתוֹ תְּרוּמָה. תָּרַם אֶחָד מֵהֶם וְלֹא יָדַע חֲבֵרוֹ, וּבָא הוּא וְתָרַם, אִם הָיוּ מְמַחִין זֶה עַל זֶה, אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה; וְאִם לָאו, אִם תָּרַם הָרִאשׁוֹן כַּשִּׁעוּר, אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה. וְאִם לֹא תָּרַם הָרִאשׁוֹן כַּשִּׁעוּר, תְּרוּמַת שְׁנֵיהֶם תְּרוּמָה. וְנִרְאֶה לִי שֶׁבַּזְּמַן \u0010c31\u0011 הַזֶּה, ה\"ה בְּמַעֲשֵׂר. אֲבָל לִתְרוּמָה, כֵּיוָן שֶׁאֵין לִתְרוּמָה שִׁעוּר, בֵּין כָּךְ וּבֵין כָּךְ אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה.\nהָאוֹמֵר לְאֶחָד לִתְרֹם, וְהָלַךְ לִתְרֹם, וּבִטֵּל שְׁלִיחוּתוֹ קֹדֶם שֶׁיִּתְרֹם, אִם שִׁנָּה הַשָּׁלִיחַ שְׁלִיחוּתוֹ כְּגוֹן שֶׁאָמַר לוֹ: תְּרֹם מִן הַצָּפוֹן, וְתָרַם מִן הַדָּרוֹם, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְאִם לָאו, תְּרוּמָתוֹ תְּרוּמָה. \u0005וְיֵשׁ חוֹלְקִין וס\"ל דְּכָל שֶׁבִּטֵּל הַשְּׁלִיחוּת, אֲפִלּוּ לֹא שִׁנָּה, לֹא הָוֵי תְּרוּמָתוֹ תְּרוּמָה (טוּר)\u0006.\nאָרִיס שֶׁתָּרַם, וּבָא בַּעַל הַבַּיִת וְעִכֵּב, אִם עַד שֶׁלֹּא תָּרַם עִכֵּב, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְאִם מִשֶּׁתָּרַם עִכֵּב, תְּרוּמָתוֹ תְּרוּמָה.\nאַפּוֹטְרוֹפְּסִין \u0010c32\u0011 תּוֹרְמִין נִכְסֵי יְתוֹמִים.\nהַגַּנָּב וְהַגַּזְלָן \u0010c33\u0011 וְהָאַנָּס, תְּרוּמָתָן תְּרוּמָה. וְאִם הָיוּ הַבְּעָלִים רוֹדְפִין אַחֲרֵיהֶם, אֵין תְּרוּמָתָן תְּרוּמָה.\nהַבֵּן וְהַשָּׂכִיר וְהָעֶבֶד וְהָאִשָּׁה, תּוֹרְמִין עַל מַה שֶּׁהֵם אוֹכְלִין, אֲבָל לֹא עַל הַשְּׁאָר.\nהַבֵּן, כְּשֶׁאוֹכֵל אִם אָבִיו, וְהָאִשָּׁה בְּעִסָתָהּ, תּוֹרְמִין, מִפְּנֵי שֶׁהֵן בִּרְשׁוּת.\nהַפּוֹעֲלִים, אֵין לָהֶם רְשׁוּת לִתְרֹם שֶׁלֹּא מִדַּעַת בַּעַל הַבַּיִת.\nפּוֹעֵל שֶׁאָמַר לֵיהּ בַּעַל הַבַּיִת: כְּנֹס לִי גָּרְנִי וּתְרֹם, וְתָרַם, וְאַחַר כָּךְ \u0010c34\u0011 כָּנַס, תְּרוּמָתוֹ תְּרוּמָה.\nעוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ תְּרוּמָה מִשֶּׁלּוֹ, \u0010c35\u0011 גָּזְרוּ חֲכָמִים שֶׁתְּהֵא תְּרוּמָתוֹ תְּרוּמָה אִם הוּא בְּאֶרֶץ יִשְׂרָאֵל. \u0005הַגָּה: וּבוֹדְקִין אוֹתוֹ, אִם אָמַר: בְּדַעַת יִשְׂרָאֵל הִפְרַשְׁתִּי, תִּנָּתֵן לַכֹּהֵן; וְאִם לָאו, טְעוּנָה \u0010c36\u0011 גְּנִיזָה (טוּר)\u0006.\nהַמִּתְכַּוֵּן לוֹמַר: תְּרוּמָה, וְאָמַר: מַעֲשֵׂר; מַעֲשֵׂר, וְאָמַר: תְּרוּמָה, לֹא אָמַר כְּלוּם, עַד שֶׁיִּהְיוּ פִּיו וְלִבּוֹ שָׁוִים.\nהִפְרִישׁ תְּרוּמָה בְּמַחֲשַׁבְתּוֹ וְלֹא הוֹצִיא בִּשְׂפָתָיו כְּלוּם, הֲרֵי זֶה תְּרוּמָה, שֶׁנֶּאֱמַר וְנֶחְשַׁב לָכֶם תְּרוּמַתְכֶם \u0005(בַּמִּדְבָּר יח, כז)\u0006.\nהַמַּפְרִישׁ תְּרוּמָה עַל תְּנַאי, אִם \u0010c37\u0011 נִתְקַיֵּם הַתְּנַאי הֲרֵי זֶה תְּרוּמָה.\nהַמַּפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת, וְנִחַם עֲלֵיהֶם, הֲרֵי זֶה נִשְׁאָל לְחָכָם וּמַתִּיר לוֹ, כְּדֶרֶךְ שֶׁמַּתִּירִין שְׁאָר נְדָרִים, וְתַחֲזֹר חֻלִּין כְּמוֹ שֶׁהָיְתָה.\nהָאוֹמֵר: שֶׁל מַעְלָה תְּרוּמָה וְשֶׁל מַטָּה חֻלִּין, אוֹ בְּהֶפֶךְ, דְּבָרָיו \u0010c38\u0011 קַיָּמִים.\nהַתּוֹרֵם אֶת הַגֹּרֶן, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ שֶׁתִּהְיֶה תְּרוּמָה עַל הַכֶּרִי וְעַל מַה שֶׁבַּקֻּטָּעִין \u0005(פי' שִׁבֳּלִים קְטוּעִים שֶׁלֹּא נִדּוֹשׁוּ)\u0006 וְעַל מַה שֶּׁבַּצְּדָדִים וְעַל מַה שֶּׁבְּתוֹךְ הַתֶּבֶן. הַתּוֹרֵם אֶת הַיֶּקֶב, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ לִתְרֹם עַל מַה שֶׁבַּחַרְצַנִּים וְעַל מַה שֶּׁבַּזַּגִּים. הַתּוֹרֵם אֶת הַבּוֹר שֶׁל שֶׁמֶן, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ עַל מַה שֶּׁבַּגֶּפֶת \u0005(פי' פְּסֹלֶת שֶׁל זֵיתִים)\u0006 ; וְאִם לֹא נִתְכַּוֵּן, אֶלָּא תָּרַם סְתָם, נִפְטָר הַכֹּל, שֶׁתְּנַאי בֵּית דִּין הוּא שֶׁתְּרוּמָה עַל הַכֹּל.\nהַתּוֹרֵם כַּלְכָּלָה שֶׁל תְּאֵנִים, וְנִמְצְאוּ תְּאֵנִים בְּצַד הַכַּלְכָּלָה, הֲרֵי אֵלּוּ פְּטוּרִים, מִפְּנֵי שֶׁבְּלִבּוֹ לִתְרֹם עַל הַכֹּל.\nאֵין תּוֹרְמִין אֶלָּא מִן הַיָּפֶה. וְנִרְאֶה לִי דְּהַשְׁתָּא דִּלְאִבּוּד אָזְלָא מִפְּנֵי הַטֻּמְאָה, אֵין לְהַקְפִּיד בְּכָךְ; וּמִיהוּ בְּמַעֲשֵׂר הַנִּתָּן לְלֵוִי וּלְעָנִי, יֵשׁ לְהַקְפִּיד בְּכָךְ.\nאֵין תּוֹרְמִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ; וְאִם תָּרַם, אֵין תְּרוּמָתוֹ תְּרוּמָה. הַקִּשּׁוּת וְהַמְּלָפְפוֹת מִין אֶחָד. כָּל מִין חִטִּים מִין אֶחָד. כָּל מִין תְּאֵנִים וּגְרוֹגָרוֹת וּדְבֵלָה מִין אֶחָד, וְתוֹרֵם מִזֶּה עַל זֶה. וְכָל שֶׁהוּא כִּלְאַיִם בַּחֲבֵרוֹ לֹא יִתְרֹם מִזֶּה עַל זֶה, אֲפִלּוּ מִן הַיָּפָה עַל הָרָעָה; וְאִם תָּרַם, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְכָל שֶׁאֵינוֹ כִּלְאַיִם בַּחֲבֵרוֹ, תּוֹרֵם מִן הַיָּפֶה עַל הָרַע, אֲבָל לֹא מִן הָרַע עַל הַיָּפֶה, וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, חוּץ מִן הַזּוֹנִין \u0005(פי' זֶרְעוֹנִים שְׁחֹרִים הַנִּמְצָא בֵּין הַחִטִּים)\u0006 עַל הַחִטִּים, מִפְּנֵי שֶׁאֵינָם אֹכֶל אָדָם.\nאֵין תּוֹרְמִין מִדָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ; וְלֹא מִדָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ; וְאִם תָּרַם, תְּרוּמָתוֹ תְּרוּמָה.\nאֵין תּוֹרְמִין מֵהַמְחֻבָּר עַל הַתָּלוּשׁ וְלֹא מִן הַתָּלוּשׁ עַל הַמְחֻבָּר, וְאִם תָּרַם, אֵין תְּרוּמָתוֹ תְּרוּמָה. אֲבָל אִם אָמַר: פֵּרוֹת עֲרוּגָה זוֹ תְּלוּשִׁים יִהְיוּ תְּרוּמָה עַל פֵּרוֹת עֲרוּגָה זֶה לִכְשֶׁיִּתָּלְשׁוּ, \u0010c39\u0011 וְנִתְלְשׁוּ, דְּבָרָיו קַיָּמִין. וְהוּא שֶׁהֵבִיאוּ שְׁנֵיהֶם שְׁלִישׁ בְּעֵת שֶׁאָמַר.\nאֵין תּוֹרְמִין מִן הַלַּח עַל הַיָּבֵשׁ, וְלֹא מִן הַיָּבֵשׁ עַל הַלַּח; וְאִם תָּרַם, תְּרוּמָתוֹ תְּרוּמָה.\nאֵין תּוֹרְמִין מִפֵּרוֹת שָׁנָה זוֹ עַל פֵּרוֹת שָׁנָה שֶׁעָבְרָה, וְלֹא מִפֵּרוֹת שָׁנָה שֶׁעָבְרָה עַל פֵּרוֹת שָׁנָה זוֹ; וְאִם תָּרַם, אֵינָהּ תְּרוּמָה, שֶׁנֶּאֱמַר: שָׁנָה שָׁנָה \u0005(דְּבָרִים יד, כב)\u0006. לִקֵּט יָרָק עֶרֶב רֹאשׁ הַשָּׁנָה עַד שֶׁלֹּא בָּא הַשֶּׁמֶשׁ, וְחָזַר וְלִקֵּט אַחַר שֶׁבָּא הַשֶּׁמֶשׁ, אֵין תּוֹרְמִין מִזֶּה עַל זֶה, שֶׁזֶּה חָדָשׁ וְזֶה יָשָׁן. וְכֵן אִם לִקֵּט אֶתְרוֹג בְּעֶרֶב ט\"וּ בִּשְׁבָט עַד שֶׁלֹּא בָּא הַשֶּׁמֶשׁ, וְחָזַר וְלִקֵּט אֶתְרוֹג אַחֵר מִשֶּׁבָּאָה הַשֶּׁמֶשׁ, אֵין תּוֹרְמִין מִזֶּה עַל זֶה, מִפְּנֵי שֶׁאֶחָד בְּתִשְׁרֵי רֹאשׁ הַשָּׁנָה לַמַּעַשְׂרוֹת תְּבוּאָה וְקִטְנִיּוֹת וִירָקוֹת, וְט\"וּ בִּשְׁבָט רֹאשׁ הַשָּׁנָה לְמַעַשְׂרוֹת הָאִילָן.\nאֵין תּוֹרְמִין מִפֵּרוֹת הָאָרֶץ עַל פֵּרוֹת חוּצָה לָאָרֶץ, וְלֹא מִפֵּרוֹת חוּצָה לָאָרֶץ עַל פֵּרוֹת הָאָרֶץ, וְלֹא מִפֵּרוֹת הַפְּטוּרִים עַל הַחַיָּבִים, וְלֹא מֵהַחַיָּבִים עַל הַפְּטוּרִים; וְאִם תָּרְמוּ, אֵין תְּרוּמָתָן תְּרוּמָה.\nתָּרַם מִדְּמַאי \u0005(פי' דָּא מַאי, כְּלוֹמַר פֵּרוֹת אוֹ תְּבוּאָה שֶׁנִּלְקְחָה מֵעַם הָאָרֶץ שֶׁאֵין יָדוּעַ אִם הֵרִים הַמַּעֲשֵׂר כָּרָאוּי, וְחַיָּב בְּמַעַשְׂרוֹת מִדְּרַבָּנָן)\u0006. עַל דְּמַאי, אוֹ עַל וַדַּאי, תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם מִכָּל אֶחָד מִפְּנֵי עַצְמוֹ.\nתָּרַם מִוַּדַּאי עַל דְּמַאי, תְּרוּמָתוֹ \u0010c40\u0011 תְּרוּמָה, וְלֹא תֵּאָכֵל עַד שֶׁיּוֹצִיא עָלֶיהָ תְּרוּמָה וּמַעַשְׂרוֹת.\nאֵין תּוֹרְמִין מִן \u0010c41\u0011 הַלָּקוּחַ עַל מַה שֶּׁגָּדַל בְּתוֹךְ שָׂדֵהוּ, וְלֹא הַלָּקוּחַ מֵעוֹבֵד כּוֹכָבִים עַל הַלָּקוּחַ מִיִּשְׂרָאֵל, אוֹ בְּהֶפֶךְ.\nאֵין תּוֹרְמִין שִׁבֳּלִים עַל חִטִּים, וְזֵיתִים עַל שֶׁמֶן, וַעֲנָבִים עַל יַיִן; אֲבָל תּוֹרְמִים שֶׁמֶן עַל זֵיתִים הַנִּכְבָּשִׁים, וְיַיִן עַל עֲנָבִים לַעֲשׂוֹת צִמּוּקִים.\nתּוֹרְמִים זֵיתֵי שֶׁמֶן עַל זֵיתֵי כֶּבֶשׁ, אֲבָל לֹא מִזֵּיתֵי כֶּבֶשׁ עַל זֵּיתֵי שֶׁמֶן; מִיַּיִן שֶׁאֵינוֹ מְבֻשָּׁל עַל הַמְּבֻשָּׁל, אֲבָל לֹא מִן הַמְּבֻשָּׁל עַל שֶׁאֵינוֹ מְבֻשָּׁל; מִן הַצָּלוּל עַל שֶׁאֵינוֹ צָלוּל, אֲבָל לֹא מִשֶּׁאֵינוֹ צָלוּל עַל הַצָּלוּל; מִתְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִנְיָן מִגְּרוֹגָרוֹת עַל תְּאֵנִים בְּמִדָּה, אֲבָל לֹא תְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִדָּה וְלֹא גְּרוֹגָרוֹת עַל תְּאֵנִים בְּמִנְיָן, כְּדֵי שֶׁיִּתְרֹם לְעוֹלָם בְּעַיִן יָפָה. וְתוֹרְמִים חִטִּים עַל הַפַּת, אֲבָל לֹא מִן הַפַּת עַל חִטִּים לְפִי חֶשְׁבּוֹן; וּבְכָל אֵלּוּ אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה. ונ\"ל דְּהָאִידָּנָא דִּתְרוּמָה לְאִבּוּד אָזְלָא, אֵין לְהַקְפִּיד בְּכָךְ וְכֵן בִּשְׁאָר דְּבָרִים כַּיּוֹצֵא בָּהֶם; וּמִיהוּ בְּמַעֲשֵׂר הַנִּתָּן לְלֵוִי וּלְעָנִי, יֵשׁ לְהַקְפִּיד בְּכָךְ.\nאֵין תּוֹרְמִין חֹמֶץ עַל יַיִן, אֲבָל תּוֹרְמִין יַיִן עַל חֹמֶץ.\nהַתּוֹרֵם חָבִית שֶׁל יַיִן עַל הַיַיִן, וְנִמְצֵאת חֹמֶץ, אִם יָדוּעַ שֶׁהָיְתָה שֶׁל חֹמֶץ עַד שֶׁלֹּא תְּרָמָהּ, אֵינָהּ תְּרוּמָה; וְאִם אַחַר שֶׁתְּרָמָהּ הֶחְמִיצָה, הֲרֵי זוֹ תְּרוּמָה. אִם סָפֵק, \u0010c42\u0011 תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם. וְכֵן הַתּוֹרֵם קִשּׁוּת וְנִמְצֵאת מָרָה, אֲבַטִּיחַ וְנִמְצָא סָרוּחַ.\nאַחַר שֶׁמַּפְרִישִׁין תְּרוּמָה גְּדוֹלָה מַפְרִישׁ אֶחָד \u0010c43\u0011 מֵעֲשָׂרָה מֵהַנִּשְׁאָר, וְהוּא הַנִּקְרָא מַעֲשֵׂר רִאשׁוֹן.\nמַעֲשֵׂר רִאשׁוֹן מֻתָּר בַּאֲכִילָה לְיִשְׂרָאֵל, וּמֻתָּר לְאָכְלוֹ \u0010c44\u0011 בְּטֻמְאָה. לְפִיכָךְ בַּת לֵוִי שֶׁנִּבְעֲלָה בְּעִילַת זְנוּת, נוֹתְנִין לָהּ מַעֲשֵׂר וְאוֹכֶלֶת. אֲבָל מִי שֶׁשָּׁמְעָה שֶׁמֵּת בַּעֲלָהּ, אוֹ הֵעִיד לָהּ עֵד אֶחָד, וְנִשֵּׂאת וְאַחַר כָּךְ בָּא בַּעֲלָהּ, קָנְסוּ אוֹתָהּ חֲכָמִים שֶׁתִּהְיֶה אֲסוּרָה בְּמַעֲשֵׂר.\nלְוִיִּם וְכֹהֲנִים \u0010c45\u0011 מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן כְּדֵי לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר, וְכֵן הַכֹּהֲנִים מַפְרִישִׁין שְׁאָר תְּרוּמוֹת וּמַעַשְׂרוֹת וְהֵם לְעַצְמָם.\nאֵין מוֹצִיאִין מַעֲשֵׂר מִיַּד הַכֹּהֲנִים. וְכֵן כָּל מַתְּנוֹת כְּהֻנָּה אֵין מוֹצִיאִין אוֹתָם מִכֹּהֵן לְכֹהֵן.\nהָאוֹכֵל פֵּירוֹתָיו טְבָלִים, וְכֵן לֵוִי שֶׁאָכַל הַמַּעֲשֵׂר בְּטִבְלוֹ, אַף עַל פִּי שֶׁהֵם חַיָּבִים מִיתָה בִּידֵי שָׁמַיִם, אֵין מְשַׁלְּמִין הַמַּתָּנוֹת לְבַעֲלֵיהֶם, שֶׁנֶּאֱמַר: אֲשֶׁר יָרִימוּ לַה' \u0005(בַּמִּדְבָּר יח, כד)\u0006 אֵין לְךָ בָּהֶם כְּלוּם עַד שֶׁיָּרִימוּ אוֹתָם. וּבְחוּץ לָאָרֶץ מֻתָּר לְאָדָם לִהְיוֹת אוֹכֵל וְהוֹלֵךְ תְּחִלָּה וְאַחַר כָּךְ מַפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת.\nמְעַשְּׂרִין מִמָּקוֹם זֶה עַל מָקוֹם אַחֵר, וְאֵינוֹ צָרִיךְ לְעַשֵּׂר מִן הַמֻּקָּף. אֲבָל אֵין מְעַשְּׂרִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ; וְלֹא מִן הַחִיּוּב עַל הַפְּטוּר; וְלֹא מִן הַפְּטוּר עַל הַחִיּוּב; וְאִם עִשֵּׂר, אֵינוֹ מַעֲשֵׂר.\nכָּל שֶׁאָמַרְנוּ בִּתְרוּמָה אֵין תּוֹרְמִין מִזֶּה עַל זֶה, כָּךְ בְּמַעֲשֵׂר אֵין מְעַשְּׂרִין מִזֶּה עַל זֶה וְכָל שֶׁאָמַרְנוּ בִּתְרוּמָה אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, כָּךְ בְּמַעֲשֵׂר אִם הִפְרִישׁ מַעַשְׂרוֹתָיו מַעַשְׂרוֹת. וְכָל שֶׁהוּא פָּטוּר מִן הַתְּרוּמָה פָּטוּר מִן הַמַּעֲשֵׂר. וְכָל הַתּוֹרֵם מְעַשֵּׂר.\nכָּל שֶׁאָמַרְנוּ בָּהֶם לֹא יִתְרֹמוּ וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה, כָּךְ אִם עִשְּׂרוּ מַעַשְׂרוֹתֵיהֶם מַעַשְׂרוֹת. וְכָל שֶׁאֵין תְּרוּמָתָן תְּרוּמָה, כָּךְ אֵין מַעַשְׂרוֹתֵיהֶן מַעַשְׂרוֹת.\nהַשְּׁקֵדִים הַמָּרִים, בֵּין בְּגָדְלָן בֵּין בְּקָטְנָן, פְּטוּרִים, לְפִי שֶׁאֵינָן אֹכֶל.\nאֵין מְעַשְּׂרִין אֶלָּא מִן הַמֻּבְחָר.\nאֵין מְעַשְּׂרִין בְּאֹמֶד, אֶלָּא בְּמִדָּה אוֹ בְּמִשְׁקָל אוֹ בְּמִנְיָן. וְכָל הַמְדַקְדֵּק בַּשִּׁעוּר מְשֻׁבָּח. וְהַמַּרְבֶּה בְּמַעַשְׂרוֹת, מַעַשְׂרוֹתָיו מְקֻלְקָלִין שֶׁהֲרֵי הַטֶּבֶל מְעֹרָב בָּהֶן, וּפֵירוֹתָיו מְתֻקָּנִין.\nהַמַּפְרִישׁ מִקְצָת מַעֲשֵׂר, אֵינוֹ מַעֲשֵׂר אֶלָּא כְּמוֹ שֶׁחִלֵּק אֶת הָעֲרֵמָה, אֲבָל צָרִיךְ מִזֶּה הַחֵלֶק שֶׁיּוֹצִיא מַעֲשֵׂר שֶׁלּוֹ. כֵּיצַד, הָיוּ לוֹ מֵאָה סְאָה, הִפְרִישׁ מֵהֶם חֲמִשָּׁה לְשֵׁם מַעֲשֵׂר, \u0010c46\u0011 אֵינוֹ מַעֲשֵׂר, וְאֵינוֹ יָכוֹל לְהַפְרִישׁ עַל הַחֲמֵשׁ סְאִין מַעֲשֵׂר בְּמָקוֹם אַחֵר, אֶלָּא מֵהֶם, חֲצִי סְאָה, שֶׁהוּא הַמַּעֲשֵׂר שֶׁלָּהֶם.\nהַמַּפְרִישׁ תְּרוּמָה גְּדוֹלָה אוֹ תְּרוּמַת מַעֲשֵׂר, מְבָרֵךְ קֹדֶם שֶׁיַּפְרִישׁ: אקב\"ו לְהַפְרִישׁ תְּרוּמָה. וְכֵן הַמַּפְרִישׁ מַעֲשֵׂר רִאשׁוֹן, מְבָרֵךְ קֹדֶם: לְהַפְרִישׁ מַעֲשֵׂר, וְכֵן מְבָרֵךְ עַל מַעֲשֵׂר שֵׁנִי. וְאִם הִפְרִישׁ הַכֹּל זֶה אַחַר זֶה מִיָּד, וְלֹא סָח בֵּינֵיהֶם, כּוֹלְלָן בִּבְרָכָה אַחַת וּמְבָרֵךְ: לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת.\nכָּל פְּרִי שֶׁמִּקַּטְנוּתוֹ הוּא רָאוּי לַאֲכִילָה וְאֵינוֹ מַנִּיחַ אוֹתוֹ אֶלָּא כְּדֵי לְהוֹסִיף בְּגוּפוֹ, מִיָּד הוּא חַיָּב בְּמַעַשְׂרוֹת. וְכָל פְּרִי שֶׁאֵינוֹ רָאוּי לַאֲכִילָה בְּקָטְנוֹ, אֵינוֹ חַיָּב בְּמַעַשְׂרוֹת עַד שֶׁיַּגִּיעַ \u0010c47\u0011 לְעוֹנַת הַמַּעַשְׂרוֹת.\nאֶשְׁכּוֹל שֶׁהִגִּיעַ בּוֹ אֲפִלּוּ גַּרְגִּיר יְחִידִי, כֻּלּוֹ חִבּוּר לְמַעַשְׂרוֹת, וּכְאִלּוּ הִגִּיעַ כֻּלּוֹ, וְלֹא אוֹתוֹ אֶשְׁכּוֹל בִּלְבַד, אֶלָּא כָּל הָרוּחַ שֶׁיֵּשׁ בָּהּ אוֹתָהּ הַגֶּפֶן שֶׁיֵּשׁ בָּהּ הָאֶשְׁכּוֹל. וְכֵן רִמּוֹן שֶׁהִגִּיעַ בָּהּ אֲפִלּוּ פְּרִידָה אַחַת, כֻּלָּהּ חִבּוּר.\nשִׁמְרֵי יַיִן שֶׁנָּתַן עֲלֵיהֶם מַיִם וְסִנְּנָן, אִם נָתַן ג' וּמָצָא ד', מוֹצִיא מַעֲשֵׂר מִזֶּה הַיָּתֵר \u0010c48\u0011 מִמָּקוֹם אַחֵר, וְאֵינוֹ מַפְרִישׁ עָלָיו תְּרוּמָה, שֶׁהַתּוֹרֵם מִתְּחִלָּה בְּלִבּוֹ עַל \u0010c49\u0011 הַכֹּל. וְאִם מָצָא פָּחוֹת מֵאַרְבַּע, אַף עַל פִּי שֶׁמָּצָא יָתֵר עַל מִדָּתוֹ, וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶם טַעַם יַיִן, \u0010c50\u0011 פָּטוּר.\nפֵּרוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת וְנִתְלְשׁוּ, וַעֲדַיִן לֹא נִגְמְרָה מְלָאכְתָן, כְּגוֹן תְּבוּאָה שֶׁקְּצָרָהּ וְדָשָׁהּ, וַעֲדַיִן לֹא זָרָה אוֹתָהּ וְלֹא מֵרְחָהּ, מֻתָּר לֶאֱכֹל מֵהֶם אֲכִילַת עֲרַאי עַד שֶׁתִּגָּמֵר מְלָאכְתָן, וּמִשֶּׁתִּגָּמֵר מְלָאכְתָן אָסוּר לֶאֱכֹל מֵהֶם עֲרַאי. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּגוֹמֶר פֵּירוֹתָיו לְמָכְרָן בַּשּׁוּק. אֲבָל אִם הָיְתָה כַּוָנָתוֹ לְהוֹלִיכָן לַבַּיִת, הֲרֵי זֶה מֻתָּר לֶאֱכֹל מֵהֶם עֲרַאי אַחַר שֶׁנִּגְמְרָה מְלָאכְתָן, עַד שֶׁיִּקָּבְעוּ לְמַעֲשֵׂר.\nאֶחָד מִו' דְּבָרִים קוֹבֵעַ הַפֵּרוֹת לְמַעַשְׂרוֹת: \u0010c51\u0011 הֶחָצֵר, וְהַמִּקָּח, וְהָאֵשׁ, וְהַמֶּלַח, וְהַתְּרוּמָה, וְהַשַּׁבָּת. וְכֻלָּם אֵין קוֹבְעִין אֶלָּא בְּדָבָר שֶׁנִּגְמְרָה מְלַאכְתָּם. כֵּיצַד, פֵּרוֹת שֶׁדַּעְתּוֹ לְהוֹלִיכָן לַבַּיִת, אַף עַל פִּי שֶׁנִּגְמְרָה מְלָאכְתָן, אוֹכֵל מֵהֶם אֲכִילַת עֲרַאי עַד שֶׁיִּכָּנְסוּ לַבַּיִת שֶׁלּוֹ. נִכְנְסוּ לַבַּיִת שֶׁלּוֹ, נִקְבְּעוּ לְמַעַשְׂרוֹת וְאָסוּר לֶאֱכֹל מֵהֶם עַד שֶׁיְּעַשֵּׂר. וּכְשֵׁם שֶׁהַבַּיִת קוֹבֵעַ לְמַעֲשֵׂר, כָּךְ הֶחָצֵר קוֹבֵעַ לְמַעֲשֵׂר, שֶׁאִם נִכְנְסוּ הַפֵּרוֹת לֶחָצֵר דֶּרֶךְ הַשַּׁעַר, נִקְבְּעוּ אַף עַל פִּי שֶׁלֹּא נִכְנְסוּ לְתוֹךְ הַבַּיִת. וְכֵן אִם מְכָרָן, אוֹ בִּשְּׁלָן בְּאוּר, אוֹ כְּבָשָׁן בְּמֶלַח, אוֹ הִפְרִישׁ בָּהֶם תְּרוּמָה, אוֹ נִכְנְסָה שַׁבָּת עֲלֵיהֶם, לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר, אַף עַל פִּי שֶׁלֹּא הִגִּיעוּ לַבַּיִת. הִכְנִיסָן לַבַּיִת קֹדֶם שֶׁתִּגָּמֵר מְלָאכְתָן, הֲרֵי זֶה אוֹכֵל מֵהֶם עֲרַאי. הִתְחִיל \u0005(לִגְמֹר)\u0006 מְלָאכְתָן, מֵאַחַר שֶׁנִּכְנְסוּ לַבַּיִת, חַיָּב לְעַשֵּׂר הַכֹּל. כֵּיצַד, הִכְנִיס קִשּׁוּאִין וְדִילוּעִין קֹדֶם שֶׁיְּשַׁפְשֵׁף, מִשֶּׁיַּתְחִיל לְשַׁפְשֵׁף אַחַת נִקְבְּעוּ הַכֹּל לְמַעֲשֵׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הַתּוֹרֵם פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, מֻתָּר לֶאֱכֹל מֵהֶם עֲרַאי, חוּץ מִכַּלְכָּלַת תְּאֵנִים, שֶׁאִם תְּרָמָהּ קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּהּ נִקְבְּעָה לְמַעֲשֵׂר.\nמֻתָּר לְהַעֲרִים עַל הַתְּבוּאָה לְהַכְנִיסָהּ \u0010c52\u0011 בְּמוֹץ, כְּדֵי שֶׁתִּהְיֶה בְּהֶמְתּוֹ אוֹכֶלֶת וּפְטוּרָה מִן הַמַּעֲשֵׂר. וְזוֹרֶה מְעַט מְעַט אַחַר שֶׁהִכְנִיס לַבַּיִת, וּפָטוּר לְעוֹלָם מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת, שֶׁהֲרֵי אֵינוֹ מַתְחִיל לִגְמֹר הַכֹּל. \u0010c53\u0011\nהַגּוֹמֵר פֵּירוֹתָיו שֶׁל חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ, הֲרֵי אֵלּוּ טָבְלוּ לְמַעֲשֵׂר.\nאֵיזֶהוּ גְּמַר מְלֶאכֶת הַיַּיִן, מִשֶּׁיַּנִּיחֶנּוּ בְּחָבִית וְיִשְׁלֶה הַחַרְצַנִּין וְהַזַּגִּין מֵעַל פִּי הֶחָבִית. אֲבָל כְּשֶׁהוּא בְּתוֹךְ הַבּוֹר, כְּשֶׁיַּגְבִּיהֶנּוּ לְהַעֲמִידוֹ בֶּחָבִית, שׁוֹתֶה עֲרַאי וְקוֹלֵט מִן הַגַּת הַעֶלְיוֹנָה וּמִן הַצִּנּוֹר וּמִכָּל מָקוֹם, וְשׁוֹתֶה.\nכֵּיצַד הִיא אֲכִילַת עֲרַאי, כְּגוֹן שֶׁהָיָה מְקַלֵּף שְׂעוֹרִים וְאוֹכֵל, מְקַלֵּף אַחַת אַחַת וְאִם קִלֵּף וְכִנֵּס לְתוֹךְ יָדוֹ, חַיָּב לְעַשֵּׂר. \u0005(הָיָה מוֹלֵל מְלִילוֹת שֶׁל חִטִּים, מְנַפֶּה מִיָּד לְיָד וְאוֹכֵל וְאִם נִפָּה לְתוֹךְ חֵיקוֹ, חַיָּב לְעַשֵּׂר)\u0006. וְכֵן נוֹטֵל מִן הַיַּיִן וְנוֹתֵן לִקְעָרָה לְתוֹךְ תַּבְשִׁיל צוֹנֵן, וְאוֹכֵל; אֲבָל לֹא לְתוֹךְ הַקְּדֵרָה, אַף עַל פִּי שֶׁהִיא צוֹנֶנֶת, מִפְּנֵי שֶׁהִיא כְּבוֹר קָטָן. וְכֵן סוֹחֵט זֵיתִים עַל בְּשָׂרוֹ, אֲבָל לֹא לְתוֹךְ יָדוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nכְּשֵׁם שֶׁמֻּתָּר לֶאֱכֹל עֲרַאי מִפֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, כָּךְ מֻתָּר לְהַאֲכִיל מֵהֶם לְחַיָּה, לִבְהֵמָה וּלְעוֹפוֹת, כָּל מַה שֶּׁיִּרְצֶה, וּמַפְקִיר מֵהֶם כָּל מַה שֶּׁיִּרְצֶה, קֹדֶם שֶׁיְּעַשֵּׂר. וְאִם גָּמְרוּ, אַף עַל פִּי שֶׁלֹּא נִקְבְּעוּ לְמַעֲשֵׂר, לֹא \u0010c54\u0011 יַפְקִיר וְלֹא יַאֲכִיל לִבְהֵמָה וּלְחַיָּה וּלְעוֹפוֹת אֲכִילַת קֶבַע, עַד שֶׁיְּעַשֵּׂר. וּמֻתָּר לְהַאֲכִיל לִבְהֵמָה עֲרַאי מִן הַטֶּבֶל, וַאֲפִלּוּ בְּתוֹךְ הַבַּיִת, וּמַאֲכִילָה פְּקִיעֵי \u0005(פֵּרוּשׁ עֳמָרִים שֶׁל תְּבוּאָה הַמֻּנָּחִים בְּקַשׁ)\u0006 עָמִיר עַד שֶׁיַּעֲשֵׂם חֲבִילוֹת.\nתְּאֵנָה הָעוֹמֶדֶת בְּחָצֵר, אוֹכֵל מִמֶּנָּהּ אַחַת אַחַת, וּפָטוּר. וְאִם צֵרֵף, חַיָּב בְּמַעֲשֵׂר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה עוֹמֵד בַּקַּרְקַע. אֲבָל אִם עָלָה לְרֹאשׁ הַתְּאֵנָה, מְמַלֵּא חֵיקוֹ וְאוֹכֵל שָׁם, שֶׁאֵין אֲוִיר חָצֵר קוֹבֵעַ לְמַעֲשֵׂר.\nהָיְתָה עוֹמֶדֶת בֶּחָצֵר וְנוֹטָה לַגִּנָּה, הֲרֵי זֶה אוֹכֵל מִמֶּנָּהּ בַּגִּנָּה כְּדַרְכּוֹ, כְּאִלּוּ הָיְתָה נְטוּעָה בַּגִּנָּה. הָיְתָה נְטוּעָה בַּגִּנָּה וְנוֹטָה לֶחָצֵר, הֲרֵי זֶה כִּנְטוּעָה בְּחָצֵר שֶׁאֵינוֹ אוֹכֵל שָׁם אֶלָּא אַחַת אַחַת.\nגֶּפֶן שֶׁנְּטוּעָה בֶּחָצֵר, לֹא יִטֹּל אֶת כָּל הָאֶשְׁכּוֹל כְּאֶחָד וְיֹאכַל, אֶלָּא מְגַרְגֵּר אַחַת אַחַת. וְכֵן בְּרִמּוֹן, לֹא יִטֹּל אֶת כָּל הָרִמּוֹן, אֶלָּא פּוֹרֵט אֶת הָרִמּוֹן בָּאִילָן, וְאוֹכֵל הַפֶּרֶט מִשָּׁם. וְכֵן בַּאֲבַטִּיחַ, סוֹפְתוֹ \u0005(פי' חוֹתְכוֹ)\u0006 בַּקַּרְקַע, וְאוֹכְלוֹ שָׁם.\nהָיָה אוֹכֵל בְּאֶשְׁכּוֹל בַּגִּנָּה, וְנִכְנַס מִן הַגִּנָּה לֶחָצֵר, אַף עַל פִּי שֶׁיָּצָא מִן הֶחָצֵר לֹא יִגְמֹר עַד שֶׁיְּעַשֵּׂר.\nכֻּסְבָּר הַזָּרוּעַ בְּחָצֵר, מְקַרְסֵם עָלֶה עָלֶה וְאוֹכְלוֹ; וְאִם צֵרֵף, חַיָּב לְעַשֵּׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהַלּוֹקֵחַ פֵּרוֹת תְּלוּשִׁין לְאָכְלָן, נִקְבְּעוּ לְמַעֲשֵׂר, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמֵאֵימָתַי יִקָּבְעוּ, מִשֶּׁיִּתֵּן \u0010c55\u0011 דָּמִים, אַף עַל פִּי שֶׁלֹּא מָשַׁךְ.\nהֲרֵי שֶׁלֹּא נָתַן דָּמִים וְהָיָה בּוֹרֵר וּמַנִּיחַ, בּוֹרֵר וּמַנִּיחַ, אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ, וְאַף עַל פִּי שֶׁגָּמַר בְּלִבּוֹ לִקַּח, לֹא נִתְחַיֵּב לְעַשֵּׂר. וְאִם הָיָה יְרֵא שָׁמַיִם, מִשֶּׁגָּמַר בְּלִבּוֹ מְעַשֵּׂר וְאַחַר כָּךְ יַחֲזִיר לַמּוֹכֵר, אִם רָצָה לְהַחֲזִיר.\nהַלּוֹקֵחַ \u0010c56\u0011 בִּמְחֻבָּר לַקַּרְקַע, אוֹ שֶׁלָּקַח תָּלוּשׁ לִשְׁלֹחַ לַחֲבֵרוֹ, לֹא נִקְבְּעוּ, וְיֵשׁ לוֹ לֶאֱכֹל מֵהֶם עֲרַאי.\nהָאוֹמֵר לַחֲבֵרוֹ: הֵא לְךָ אִיסָר זֶה וְתֵן לִי בּוֹ ה' תְּאֵנִים, הֲרֵי זֶה אוֹכֵל אַחַת אַחַת, וּפָטוּר. וְאִם צֵרֵף, חַיָּב לְעַשֵּׂר. הֵא לְךָ אִיסָר זֶה בְּעֶשְׂרִים תְּאֵנִים שֶׁאָבֹר לִי, בּוֹרֵר אַחַת אַחַת, וְאוֹכֵל. בְּאֶשְׁכּוֹל שֶׁאָבֹר לִי, מְגֻרְגָּר מִמֶּנּוּ בָּאִילָן, וְאוֹכֵל. בְּרִמּוֹן שֶׁאָבֹר לִי, פּוֹרְטוֹ בָּאִילָן, וְאוֹכֵל. בַּאֲבַטִּיחַ שֶׁאָבֹר לִי, סוֹפֵת בַּקַּרְקַע, וְאוֹכֵל. וְאִם קָצַץ אֶת הַתְּאֵנִים וְצֵרְפָם, אוֹ שֶׁקָּצַץ הָאֶשְׁכּוֹל אוֹ הָאֲבַטִּיחַ, חַיָּב לְעַשֵּׂר, שֶׁהֲרֵי לֹא קָנָה אֶלָּא הַנִּתְלָשׁ. אֲבָל אִם אָמַר לֵיהּ: הֵא לְךָ אִיסָר בְּעֶשְׂרִים תְּאֵנִים אֵלּוּ, בִּשְׁנֵי אֶשְׁכּוֹלוֹת אֵלּוּ, בִּשְׁנֵי רִמּוֹנִים אֵלּוּ, בִּשְׁנֵי אֲבַטִּיחִים אֵלּוּ קוֹצֵץ כְּדַרְכּוֹ, וְאוֹכֵל עֲרַאי, וּפָטוּר; שֶׁלֹּא נִקְבְּעוּ בַּמִּקָּח, שֶׁהֲרֵי לְקָחָן בִּמְחֻבָּר.\nהַמַּחֲלִיף עִם חֲבֵרוֹ, זֶה לֶאֱכֹל וְזֶה לֶאֱכֹל, שְׁנֵיהֶם נִקְבְּעוּ לְמַעַשְׂרוֹת, שֶׁהֲרֵי לָקְחוּ בְּתָלוּשׁ. זֶה \u0010c57\u0011 לַקְצוֹת וְזֶה לַקְצוֹת, שְׁנֵיהֶם לֹא נִקְבְּעוּ, שֶׁאֵין הַמֶּכֶר קוֹבֵעַ דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. לָקַח הָאֶחָד פֵּרוֹת שֶׁהֶחֱלִיף, לַאֲכִילָה, וְלָקַח הָאֶחָד חֲלִיפֵיהֶן לְהַקְצוֹתָן, זֶה שֶׁלָּקַח לַאֲכִילָה חַיָּב לְעַשֵּׂר, וְזֶה שֶׁלָּקַח לְהַקְצוֹת לֹא נִקְבַּע לְמַעֲשֵׂר.\nעַם הָאֶרֶץ שֶׁהָיָה עוֹבֵר בַּשּׁוּק וְאָמַר: טְלוּ לָכֶם תְּאֵנִים, אוֹכְלִים \u0010c58\u0011 וּפְטוּרִים, שֶׁאֵין הַמַּתָּנָה קוֹבַעַת.\nהַשּׂוֹכֵר אֶת הַפּוֹעֲלִים לַעֲשׂוֹת עִמּוֹ בַּפֵּרוֹת, בֵּין בִּתְלוּשִׁין בֵּין בִּמְחֻבָּרִין, הוֹאִיל וְיֵשׁ לָהֶם לֶאֱכֹל מִן הַתּוֹרָה בַּמֶּה שֶׁהֵם עוֹשִׂים, הֲרֵי אֵלּוּ אוֹכְלִים וּפְטוּרִין מִן הַמַּעֲשֵׂר. וְאִם הִתְנָה עִמָּהֶם שֶׁיֹּאכְלוּ מַה שֶּׁלֹּא זִכְּתָה לָהֶם תּוֹרָה, כְּגוֹן שֶׁהִתְנָה הַפּוֹעֵל שֶׁיֹּאכְלוּ בָּנָיו עִמּוֹ, אוֹ שֶׁיֹּאכַל בְּנוֹ בִּשְׂכָרוֹ, אוֹ שֶׁיֹּאכַל אַחַר גְּמַר מְלַאכְתּוֹ בְּתָלוּשׁ, הֲרֵי זֶה אָסוּר לֶאֱכֹל עַד שֶׁיְּעַשֵּׂר, הוֹאִיל וְאוֹכֵל מִפְּנֵי הַתְּנַאי הֲרֵי זֶה כְּלוֹקֵחַ.\nהַמּוֹצִיא פּוֹעֲלִים לַעֲשׂוֹת לוֹ מְלָאכָה בַּשָּׂדֶה, בִּזְמַן שֶׁאֵין לָהֶם עָלָיו \u0010c59\u0011 מְזוֹנוֹת, אוֹכְלִים מִפֵּרוֹת שֶׁבַּשָּׂדֶה וּפְטוּרִים מִן הַמַּעֲשֵׂר. וְהוּא שֶׁלֹּא נִגְמְרָה מְלָאכְתָן. אֲבָל אִם יֵשׁ לָהֶם עָלָיו מְזוֹנוֹת, לֹא יֹאכְלוּ, וְאַף עַל פִּי שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, שֶׁאֵין פּוֹרְעִין חוֹב מִן הַטֶּבֶל. \u0005(אֲבָל)\u0006 אוֹכְלִים אַחַת אַחַת מֵהַתְּאֵנָה, אֲבָל לֹא מִן הַסַל וְלֹא מִן הַקֻּפָּה וְלֹא מִן הַמֻּקְצֶה.\nאֶחָד הַמְבַשֵּׁל וְאֶחָד הַשּׁוֹלֵק וְאֶחָד הַכּוֹבֵשׁ, קוֹבֵעַ לְמַעֲשֵׂר. אֲבָל הַמְעַשֵּׁן אֶת הַפֵּרוֹת עַד שֶׁהִכְשִׁירָן, הֲרֵי זֶה \u0010c60\u0011 סָפֵק.\nהַטּוֹמֵן פֵּרוֹת בָּאֲדָמָה, אוֹ בַּזֶּבֶל, אוֹ בַּתֶּבֶן, עַד שֶׁהִכְשִׁירָם לַאֲכִילָה לֹא נִקְבְּעוּ לְמַעֲשֵׂר.\nהַנּוֹתֵן יַיִן לְתַבְשִׁיל חַם, אוֹ שֶׁנָּתַן שֶׁמֶן לִקְדֵרָה בְּאִלְפָּס, כְּשֶׁהֵן מְרֻתָּחִין, נִקְבְּעוּ לְמַעֲשֵׂר.\nמָזַג יַיִן בְּמַיִם חַמִּין, נִקְבַּע. וְאֵין צָרִיךְ לוֹמַר אִם בִּשֵּׁל הַיַּיִן. וַאֲפִלּוּ בְּגַת אָסוּר לִשְׁתּוֹת מִמֶּנּוּ עַד שֶׁיְּעַשֵּׂר.\nהַסוֹחֵט אֶשְׁכּוֹל לְתוֹךְ הַכּוֹס, נִקְבָּע. לְתוֹךְ הַתַּמְחוּי, אֵינוֹ נִקְבָּע.\nהַמּוֹלֵחַ פֵּרוֹת בַּשָּׂדֶה, נִקְבְּעוּ. טָבַל הַזֵּיתִים אַחַת אַחַת בְּמֶלַח וְאָכַל, פָּטוּר.\nהַפּוֹצֵעַ זֵיתִים כְּדֵי שֶׁיֵּצֵא הַשָּׂרָף מֵהֶם, פָּטוּר.\nהַנּוֹטֵל זֵיתִים מֵהַמַּעֲטָן, טוֹבֵל אַחַת אַחַת בְּמֶלַח וְאוֹכֵל. וְאִם מָלַח וְנָתַן לְפָנָיו, חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהַתּוֹרֵם פֵּרוֹת תְּרוּמָה שֶׁצָּרִיךְ לִתְרֹם אַחֲרֶיהָ שְׁנִיָּה, נִקְבָּע לְמַעֲשֵׂר, וְלֹא יֹאכַל מֵהֶם עֲרַאי עַד שֶׁיּוֹצִיא הַתְּרוּמָה שְׁנִיָּה וִיעַשֵּׂר.\nפֵּרוֹת שֶׁנִּגְמְרָה מְלָאכְתָן וְחָשְׁכָה עֲלֵיהֶם לֵיל שַׁבָּת, נִקְבְּעוּ, וְלֹא יֹאכַל מֵהֶם, אֲפִלּוּ לְאַחַר הַשַּׁבָּת, עַד שֶׁיְּעַשֵּׂר.\nתִּינוֹקוֹת שֶׁטָּמְנוּ תְּאֵנִים לְשַׁבָּת וְשָׁכְחוּ לְעַשְּׂרָן, לֹא יֹאכְלוּ לְמוֹצָאֵי שַׁבָּת עַד שֶׁיְּעַשְּׂרוּ.\nתְּאֵנָה שֶׁהָיְתָה מְיֻחֶדֶת לוֹ לֶאֱכֹל פֵּירוֹתֶיהָ בְּשַׁבָּת, וְלִקֵּט מִמֶּנָּהּ כַּלְכָּלָה, לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר, הוֹאִיל וּפֵרוֹת אֵלּוּ מְיֻחָדִים לְשַׁבָּת וְהַשַּׁבָּת קוֹבַעַת.\nהָיָה אוֹכֵל בָּאֶשְׁכּוֹל וְחָשְׁכָה עָלָיו לֵיל שַׁבָּת, לֹא יִגְמֹר אֲכִילָתוֹ בְּשַׁבָּת עַד שֶׁיְּעַשֵּׂר. וְאִם הִנִּחָן לְאַחַר הַשַּׁבָּת, הֲרֵי זֶה \u0010c61\u0011 גּוֹמְרוֹ.\nכָּל שֶׁאָסוּר לְזָרִים לֶאֱכֹל בִּתְרוּמָה, כְּגוֹן הַגַּרְעִינִין וְכַיּוֹצֵא בָּהֶן, כָּךְ אָסוּר לְאָכְלוֹ מֵהַטֶּבֶל וְהַמַּעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ. וְכָל שֶׁמֻּתָּר לְזָרִים לְאָכְלוֹ בִּתְרוּמָה, מִדְּבָרִים אֵלּוּ, כָּךְ מֻתָּר בְּטֶבֶל וּמַעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ.\nאֵין \u0010c62\u0011 מַּדְלִיקִין בְּטֶבֶל טָמֵא. אֵין מְחַפִּין בַּטֶּבֶל. וְאֵין זוֹרְעִין אֶת הַטֶּבֶל. וַאֲפִלּוּ פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן אָסוּר לִזְרֹעַ מֵהֶם עַד שֶׁיְּעַשֵּׂר. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּתְבוּאָה וְקִטְנִיּוֹת וְכַיּוֹצֵא בָּהֶן, אֲבָל הָעוֹקֵר שְׁתָלִים שֶׁיֵּשׁ בָּהֶם פֵּרוֹת מִמָּקוֹם לְמָקוֹם בְּתוֹךְ שָׂדֵהוּ, הֲרֵי זֶה מֻתָּר, וְאֵינוֹ כְּזוֹרֵעַ טֶבֶל, שֶׁהֲרֵי לֹא אָסַף הַפֵּרוֹת. וְכֵן הָעוֹקֵר לֶפֶת וּצְנוֹנוֹת וּשְׁתָלָם בְּמָקוֹם אַחֵר, אִם נִתְכַּוֵּן לְהוֹסִיף \u0010c63\u0011 בְּגוּפָן, מֻתָּר. וְאִם שְׁתָלָם כְּדֵי שֶׁיִּקְשׁוּ וְיִקַּח הַזֶּרַע שֶׁלָּהֶם, אָסוּר, מִפְּנֵי שֶׁהוּא \u0010c64\u0011 כְּזוֹרֵעַ חִטִּים אוֹ שְׂעוֹרִים שֶׁל טֶבֶל.\nאֵין מוֹכְרִין טֶבֶל אֶלָּא \u0010c65\u0011 לְצֹרֶךְ, וּלְחָבֵר. וְאָסוּר לִשְׁלֹח טֶבֶל, וַאֲפִלּוּ חָבֵר לְחָבֵר, שֶׁמָּא יִסְמְכוּ זֶה עַל זֶה וְיֹאכַל טֶבֶל.\nהַמּוֹכֵר פֵּרוֹת לַחֲבֵרוֹ, מוֹכֵר אוֹמֵר: עַל מְנַת שֶׁהֵם טֶבֶל מָכַרְתִּי, וְלוֹקֵחַ אָמַר: לֹא לָקַחְתִּי מִמְּךָ אֶלָּא מְעֻשָּׂרוֹת, כּוֹפִין אֶת \u0010c66\u0011 הַמּוֹכֵר לְתַקֵּן; קְנָס הוּא לוֹ, מִפְּנֵי שֶׁמָּכַר טֶבֶל.\nאֵין פּוֹרְעִין חוֹב מֵהַטֶּבֶל, מִפְּנֵי שֶׁהוּא כְּמוֹכְרוֹ.\nהַלּוֹקֵחַ טֶבֶל מִשְּׁנֵי מְקוֹמוֹת, מְעַשֵּׂר מִזֶּה עַל זֶה.\nהַחוֹכֵר שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים, מְעַשֵּׂר וְנוֹתֵן לוֹ. וְהַמְקַבֵּל שְׂדֵה אֲבוֹתָיו מֵהָעוֹבֵד כּוֹכָבִים, מְעַשֵּׂר וְנוֹתֵן לוֹ.\nכֹּהֵן אוֹ לֵוִי שֶׁלָּקְחוּ פֵּרוֹת מִיִּשְׂרָאֵל אַחֵר שֶׁנִּגְמְרָה מְלָאכְתָן, \u0010c67\u0011 מוֹצִיאִין הַתְּרוּמָה וְהַמַּעַשְׂרוֹת מִידֵיהֶם וְנוֹתְנִים אוֹתָם לְכֹהֲנִים וְלִלְוִיִּם אֲחֵרִים.\nכֹּהֵן אוֹ לֵוִי שֶׁמָּכְרוּ פֵּרוֹת תְּלוּשִׁים, קֹדֶם שֶׁתִּגָּמֵר מְלָאכְתָן, וְאֵין צָרִיךְ לוֹמַר אִם מָכַר בִּמְחֻבָּר, הֲרֵי הַתְּרוּמָה וְהַמַּעֲשֵׂר \u0010c68\u0011 שֶׁלָּהֶם.\nהַנּוֹתֵן שָׂדֵהוּ \u0010c69\u0011 בְּקַבָּלָה לְעוֹבֵד כּוֹכָבִים אוֹ לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת, אַף עַל פִּי שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת צָרִיךְ \u0010c70\u0011 לְעַשֵּׂר עַל יָדָם. נְתָנָהּ לְעַם הָאָרֶץ, עַד שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אֵינוֹ צָרִיךְ לְעַשֵּׂר עַל יָדָם. וּמִשֶּׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, צָרִיךְ לְעַשֵּׂר עַל יָדָם. כֵּיצַד הוּא עוֹשֶׂה, עוֹמֵד עַל הַגֹּרֶן וְנוֹטֵל, וְאֵינוֹ חוֹשֵׁשׁ לְמַה שֶּׁאָכְלוּ, שֶׁאֵין אָנוּ אַחְרָאִים לָהֶם.\nבְּאֶחָד בְּתִשְׁרֵי הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר תְּבוּאָה וְקִטְנִיּוֹת וִירָקוֹת. וּבְט\"וּ בִּשְׁבָט, הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר הָאִילָנוֹת. כֵּיצַד, תְּבוּאָה וְקִטְנִיּוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בַּשְּׁלִישִׁית, מַפְרִישִׁין מֵהֶן מַעֲשֵׂר שֵׁנִי. וְכֵן פֵּרוֹת הָאִילָן שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"וּ בִּשְׁבָט שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ אַחַר כָּךְ בְּסוֹף שָׁנָה שְׁלִישִׁית, מִתְעַשְּׂרִין לְשֶׁעָבַר וּמַפְרִישִׁין מֵהֶם מַעֲשֵׂר שֵׁנִי. וְכֵן אִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"וּ בִּשְׁבָט שֶׁל רְבִיעִית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בָּרְבִיעִית, מַפְרִישִׁין מֵהֶם מַעֲשֵׂר עָנִי. וְאִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אַחַר ט\"וּ בִּשְׁבָט, מִתְעַשְּׂרִין לְהַבָּא.\nהַיָּרָק, בִּשְׁעַת \u0010c71\u0011 לְקִיטָתוֹ עִשּׂוּרוֹ, כֵּיצַד, אִם נִלְקַט בְּיוֹם רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁבָּא לְעוֹנַת הַמַּעַשְׂרוֹת וְנִגְמַר בַּשְּׁנִיָּה, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. וְאִם נִלְקַט בָּרְבִיעִית, מַעֲשֵׂר שֵׁנִי. וְכֵן \u0010c72\u0011 הָאֶתְרוֹג, בִּלְבַד מִשְּׁאָר פֵּרוֹת הָאִילָן, הֲרֵי הוּא כְּיָרָק וְהוֹלְכִין אַחַר לְקִיטָתוֹ, בֵּין לְמַעֲשֵׂר בֵּין לִשְׁבִיעִית. כֵּיצַד, אִם נִלְקַט בַּשְּׁלִישִׁית אַחַר ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי אַף עַל פִּי שֶׁנִּגְמְרָה בַּשְּׁנִיָּה. וְכֵן אִם נִלְקַט בָּרְבִיעִית קֹדֶם ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. נִלְקַט בָּהּ אַחַר ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשֵׂר שֵׁנִי. וְאַף עַל פִּי שֶׁהוֹלְכִין אַחַר לְקִיטָתוֹ, אֶתְרוֹג בַּת שִׁשִּׁית שֶׁנִּכְנְסָה לַשְּׁבִיעִית, אֲפִלּוּ הָיְתָה כַּזַּיִת וְנַעֲשֵׂית כַּכִּכָּר, חַיֶּבֶת בְּמַעַשְׂרוֹת. \u0010c73\u0011\nהָאֶבְיוֹנוֹת שֶׁל צָלָף נוֹתְנִין עֲלֵיהֶם חָמְרֵי הָאִילָן וְחָמְרֵי זְרָעִים, שֶׁאִם הָיוּ מִשָּׁנָה שְׁנִיָּה שֶׁנִּכְנְסָה לַשְּׁלִישִׁית וְנִלְקְטוּ קֹדֶם ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן וְאַחַר כָּךְ מַפְרִישׁ מַעֲשֵׂר אַחֵר \u0010c74\u0011 וּפוֹדֶהוּ, וְאַחֵר שֶׁפּוֹדֶהוּ נוֹתְנוֹ לַעֲנִיִּים.\nפֵּרוֹת שָׁנָה שְׁנִיָּה שֶׁנִּתְעָרְבוּ בְּפֵרוֹת שְׁלִישִׁית, אוֹ שֶׁל שְׁלִישִׁית בָּרְבִיעִית, הוֹלְכִים אַחַר הָרֹב. מֶחֱצָה לְמֶחֱצָה, מַפְרִישִׁין מַעֲשֵׂר שֵׁנִי מִן הַכֹּל, אֲבָל לֹא מַעֲשַׂר עָנִי, שֶׁמַּעֲשֵׂר שֵׁנִי חָמוּר, שֶׁהֲרֵי הוּא קָדוֹשׁ, וּמַעֲשַׂר עָנִי חֹל. וְכֵן פֵּרוֹת שֶׁהֵן סָפֵק אִם פֵּרוֹת שְׁנִיָּה הֵם אוֹ פֵּרוֹת שְׁלִישִׁית, מַפְרִישׁ מֵהֶם מַעֲשֵׂר שֵׁנִי.\nכָּל הַפָּטוּר מִמַּעֲשֵׂר רִאשׁוֹן, פָּטוּר מִמַּעֲשֵׂר שֵׁנִי וּמִן הֶעָנִי. וְכָל שֶׁחַיָּב בָּרִאשׁוֹן, חַיָּב בִּשְׁנֵיהֶם. וְכָל הַתּוֹרֵם מוֹצִיא מַעֲשֵׂר. וְכָל שֶׁאֵינוֹ תּוֹרֵם, אֵינוֹ מוֹצִיא מַעֲשֵׂר. וְכָל מִי שֶׁאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, כָּךְ אִם עִשֵּׂר הֲרֵי הוּא מַעֲשֵׂר. וְכָל מִי שֶׁאֵין תְּרוּמָתוֹ תְּרוּמָה, כָּךְ אִם הוֹצִיא מַעֲשֵׂר אֵינוֹ מַעֲשֵׂר.\nפֵּרוֹת שֶׁהוֹצִיא מֵהֶם מַעֲשֵׂר רִאשׁוֹן קֹדֶם שֶׁיִּקָּבְעוּ לְמַעֲשֵׂר, הֲרֵי זֶה אוֹכֵל מֵהֶם עֲרַאי קֹדֶם שֶׁיּוֹצִיא מַעֲשֵׂר שֵׁנִי, שֶׁאֵין הָרִאשׁוֹן קוֹבֵעַ לַשֵּׁנִי. אֲבָל מִשֶּׁנִּקְבְּעוּ לְמַעֲשֵׂר, אַף עַל פִּי שֶׁהוֹצִיא אֶת הָרִאשׁוֹן, אָסוּר לֶאֱכֹל מֵהֶם עֲרַאי עַד שֶׁיּוֹצִיא אֶת הַשֵּׁנִי אוֹ אֶת מַעֲשַׂר עָנִי.\nלֹא חִיְּבוּ לְהַפְרִישׁ מַעֲשֵׂר שֵׁנִי \u0010c75\u0011 בְּסוּרְיָא.\nמַעֲשֵׂר שֵׁנִי נֶאֱכָל לִבְעָלָיו לִפְנִים מֵחוֹמַת יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר: וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ בַּמָּקוֹם אֲשֶׁר יִבְחַר וגו' \u0005(דְּבָרִים יד, כג)\u0006 וְנוֹהֵג בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת, אֲבָל אֵינוֹ נֶאֱכָל בִּירוּשָׁלַיִם אֶלָּא בִּפְנֵי הַבַּיִת, שֶׁנֶּאֱמַר: מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ \u0005(דְּבָרִים יד, כג)\u0006. מִפִּי הַשְּׁמוּעָה לָמְדוּ, מַה בְּכוֹר אֵינוֹ נֶאֱכָל אֶלָּא בִּפְנֵי הַבַּיִת, אַף מַעֲשֵׂר שֵׁנִי לֹא יֵאָכֵל אֶלָּא בִּפְנֵי הַבַּיִת.\nבַּזְּמַן הַזֶּה, אִם רָצָה לִפְדּוֹת מַעֲשֵׂר שֵׁנִי שְׁוֵה מָנֶה בִּפְרוּטָה, לְכַתְּחִלָּה, פּוֹדֶה וּמַשְׁלִיךְ הַפְּרוּטָה לַיָּם הַגָּדוֹל; אֲבָל לִשְׁאָר נְהָרוֹת צָרִיךְ לְשָׁחֲקָהּ תְּחִלָּה. וְכֵן אִם חִלֵּל \u0005(פֵּרוּשׁ אִם עֲשָׂאוֹ חֻלִּין עַל יְדֵי פִּדְיוֹן)\u0006 מַעֲשֵׂר שְׁוֵה מָנֶה עַל שְׁוֵה פְּרוּטָה מִפֵּרוֹת אֲחֵרוֹת, הֲרֵי זֶה מְחֻלָּל, וְשׂוֹרֵף אֶת הַפֵּרוֹת שֶׁחִלֵּל עֲלֵיהֶם, כְּדֵי שֶׁלֹּא יִהְיוּ תַּקָּלָה לַאֲחֵרִים.\nוְשִׁעוּר פְּרוּטָה, כַּחֲצִי שְׂעוֹרָה כֶּסֶף מְזֻקָּק, שֶׁהוּא חֵלֶק מִל\"ב בְּמָעָה כֶּסֶף שֶׁהוּא אשפיר\"ו עוטומאני שֶׁמִּשְׁקָלוֹ רְבִיעִית דִּרְהֶ\"ם, נִמְצָא שֶׁהַפְּרוּטָה חֵלֶק מִמ\"ח בְּקִטְעָא וְיוֹתֵר מְעַט. וְצָרִיךְ לְדַקְדֵּק שֶׁהַפֵּרוֹת שֶׁמְּחַלֵּל עֲלֵיהֶם מַעֲשֵׂר שֵׁנִי שֶׁיִּשְׁווּ כָּךְ לְפָחוֹת. \u0005וְעַיֵּן לְעֵיל סִימָן \u0010c76\u0011 רצ\"ד (סָעִיף ו')\u0006.\nכְּשֵׁם שֶׁאֵין אוֹכְלִים מַעֲשֵׂר שֵׁנִי בַּזְּמַן הַזֶּה בִּירוּשָׁלַיִם, כָּךְ אֵין פּוֹדִין אוֹתוֹ שָׁם, וְאֵין מְחַלְּלִין אוֹתוֹ, וְאֵין מוֹכְרִים אוֹתוֹ. וְאִם נִכְנָס בִּירוּשָׁלַיִם, אַף בַּזְּמַן הַזֶּה, אֵין מוֹצִיאִין אוֹתוֹ מִשָּׁם וּמַנִּיחִים אוֹתוֹ שָׁם עַד שֶׁיֵּרָקֵב. \u0005(וְכֵן אִם עָבַר וְהוֹצִיאוֹ מִשָּׁם, מַנִּיחִין אוֹתוֹ עַד שֶׁיֵּרָקֵב)\u0006. לְפִיכָךְ אֵין מַפְרִישִׁין מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם בַּזְּמַן הַזֶּה, אֶלָּא מוֹצִיאִין אֶת הַפֵּרוֹת בְּטִבְלָן חוּץ לָעִיר, וּמַפְרִישִׁין אוֹתוֹ שָׁם, וּפוֹדֶהוּ. וְאִם הִפְרִישָׁן שָׁם בַּזְּמַן הַזֶּה, יֵרָקֵב. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמַעֲשֵׂר שֵׁנִי שֶׁלֹּא נִטְמָא. אֲבָל אִם נִטְמָא, פּוֹדִין אוֹתוֹ בִּירוּשָׁלַיִם. \u0005וְיֵשׁ לְהַכְשִׁירוֹ כְּדֵי שֶׁיְּקַבֵּל טֻמְאָה וִיהֵא לוֹ הֶתֵּר בַּפִּדְיוֹן (טוּר)\u0006.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי אוֹמֵר: הַפֵּרוֹת הָאֵלּוּ מְחֻלָּלוֹת עַל מָעוֹת אֵלּוּ. וְאִם לֹא פֵּרֵשׁ, אֶלָּא הִפְרִישׁ מָעוֹת בִּלְבַד כְּנֶגֶד הַפֵּרוֹת, דַּיּוֹ, וְאֵינוֹ צָרִיךְ \u0010c77\u0011 לְפָרֵשׁ, וְיֵצְאוּ הַפֵּרוֹת לְחֻלִּין.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי, מְבָרֵךְ: אקב\"ו עַל פִּדְיוֹן מַעֲשֵׂר שֵׁנִי. וְאִם חִלְּלָן עַל פֵּרוֹת אֲחֵרוֹת, מְבָרֵךְ: עַל חִלּוּל מַעֲשֵׂר שֵׁנִי. וְהַפּוֹדֶה אוֹ מְחַלֵּל מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי, אֵינוֹ צָרִיךְ בְּרָכָה.\nאֵין פּוֹדִין מַעֲשֵׂר שֵׁנִי אֶלָּא בְּכֶסֶף. וְכֵן אִם פָּדָה מַעֲשֵׂר שֵׁנִי שֶׁלּוֹ, שֶׁהוּא מוֹסִיף חֹמֶשׁ, לֹא יִהְיֶה הַחֹמֶשׁ אֶלָּא כֶּסֶף, כְּקֶרֶן. וְאֵין פּוֹדֶה בְּכֶסֶף שֶׁאֵינוֹ מַטְבֵּעַ, אֶלָּא בְּכֶסֶף מְפֻתָּח שֶׁיֵּשׁ עָלָיו צוּרָה אוֹ כְּתָב; וְאִם פָּדָה בְּלָשׁוֹן שֶׁל כֶּסֶף וְכַיּוֹצֵא בוֹ, וְהוּא הַנִּקְרָא אֲסִימוֹן, לֹא עָשָׂה כְּלוּם. וְאֵין פּוֹדִין בְּפָחוֹת מִפְּרוּטָה, מִפְּנֵי שֶׁהוּא כְּפוֹדֶה בַּאֲסִימוֹן. וְאֵין פּוֹדִין בְּמַטְבֵּעַ שֶׁאֵינוֹ יוֹצֵא בְּאוֹתוֹ זְמַן וּבְאוֹתוֹ מָקוֹם. וְאֵינוֹ פּוֹדֶה בְּמָעוֹת שֶׁאֵינָם בִּרְשׁוּתוֹ. וְאֶפְשָׁר שֶׁאֵין דְּבָרִים אֵלּוּ אֲמוּרִים אֶלָּא בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, אֲבָל עַכְשָׁו שֶׁאֵין מַעֲשֵׂר שֵׁנִי נֶאֱכָל, אֵין לְהַקְפִּיד בְּכָךְ. וּמִכָּל מָקוֹם יֵשׁ לָחוּשׁ בַּדָּבָר, וְאַף בַּזְּמַן הַזֶּה לֹא יִפְדֶּה מַעֲשֵׂר שֵׁנִי אֶלָּא עַל כֶּסֶף שֶׁיֵּשׁ בּוֹ מַטְבֵּעַ הַיּוֹצֵא, וְהוּא בִּרְשׁוּתוֹ, אוֹ יְחַלֵּל עַל פֵּרוֹת אֲחֵרִים.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי קֹדֶם שֶׁיַּפְרִישֶׁנּוּ, כְּגוֹן שֶׁאָמַר: מַעֲשֵׂר שֵׁנִי שֶׁל פֵּרוֹת פָּדוּי בְּמָעוֹת אֵלּוּ, לֹא אָמַר כְּלוּם, וְלֹא קָבַע מַעֲשֵׂר. אֲבָל אִם קָבַע וְאָמַר: מַעֲשֵׂר שֶׁהוּא בַּצָּפוֹן, אוֹ בַּדָּרוֹם, מְחֻלָּל עַל מָעוֹת אֵלּוּ, הֲרֵי זֶה פָּדוּי.\nמִצְוַת עֲשֵׂה לְהִתְוַדּוֹת לִפְנֵי ה' אַחַר שֶׁמּוֹצִיאִין כָּל הַמַּתָּנוֹת שֶׁבְּזֶרַע הָאֶרֶץ, וְזֶהוּ הַנִּקְרָא וִדּוּי מַעֲשֵׂר. וְאֵין מִתְוַדִּין וִדּוּי זֶה אֶלָּא אַחַר הַשָּׁנָה שֶׁמַּפְרִישִׁין בָּהּ מַעֲשַׂר עָנִי.\nאֵימָתַי מִתְוַדִּין, בְּמִנְחָה, בְּיוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח שֶׁל רְבִיעִית, וּשְּׁבִיעִית.\nאֵין מִתְוַדִּין אֶלָּא בַּיּוֹם. וְכָל הַיּוֹם כָּשֵׁר לְוִדּוּי הַמַּעֲשֵׂר. וּבֵין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת חַיָּב לְבַעֵר וּלְהִתְוַדּוֹת.\nוִדּוּי זֶה נֶאֱמָר בְּכָל לָשׁוֹן. וְאִם רָצוּ רַבִּים לְהִתְוַדּוֹת כְּאֶחָד, מִתְוַּדִּים.\nאֵינוֹ מִתְוַדֶּה עַד שֶׁלֹּא יִשָּׁאֵר אֶצְלוֹ אַחַת מֵהַמַּתָּנוֹת. וְעֶרֶב יוֹם טוֹב הָאַחֲרוֹן הָיָה הַבִּעוּר, וּלְמָחָר מִתְוַדִּין, וּפֵרוֹת שֶׁלֹּא הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת בִּשְׁעַת הַבִּעוּר, אֵין מְעַכְּבִין אוֹתוֹ לְהִתְוַדּוֹת, וְאֵינוֹ \u0010c78\u0011 חַיָּב לְבַעֲרָן.\nמִי שֶׁהָיוּ פֵּירוֹתָיו רְחוֹקִים מִמֶּנּוּ, וְהִגִּיעַ יוֹם הַבִּעוּר, הֲרֵי זֶה קוֹרֵא שֵׁם לַמַּתָּנוֹת וּמְזַכֶּה לָהֶן לְבַעֲלֵיהֶן עַל גַּבֵּי קַרְקַע, אוֹ לְמִי שֶׁזּוֹכֶה לָהֶן לְבַעֲלֵיהֶן, וּמִתְוַדֶּה לְמָחָר.\nאִם הִפְרִישׁ הַמַּתָּנוֹת שֶׁלֹּא עַל הַסֵדֶר, אוֹ אִם נִשְׂרַף טִבְלוֹ, אוֹ אִם הִפְרִישׁ מַעֲשֵׂר בְּטֻמְאָה, אֵינוֹ מִתְוַדֶּה. \u0005הַגָּה: הָרַב הַמְחַבֵּר הַזֶּה הִשְׁמִיט כָּל דִּינֵי מַעֲשַׂר עָנִי, שֶׁכָּתַב הַטּוּר שֶׁיֵּשׁ לִלְמֹד מֵהֶם הַרְבֵּה דִּינֵי \u0010c79\u0011 צְדָקָה הַנּוֹהֲגִים הָאִדָּנָא, וְאֶפְשָׁר שֶׁסָּמַךְ עַצְמוֹ עַל מַה שֶּׁנִּתְבָּאֵר בְּדִינֵי צְדָקָה. אַךְ גַּם בְּדִינֵי תְּרוּמוֹת וּמַעַשְׂרוֹת הִשְׁמִיט כַּמָּה דִּינִים שֶׁכָּתַב הַטּוּר, וְהִכְנִיס אֲחֵרִים תַּחְתֵּיהֶם, וְכָל זֶה גָּרַם לוֹ שֶׁהֶעְתִּיק דִּבְרֵי הַרַמְבַּ\"ם הִלְכוֹת תְּרוּמוֹת וּמַעַשְׂרוֹת כִּכְתָבָם וְכִלְשׁוֹנָם, וְלֹא שָׁת לִבּוֹ לִדְבָרִים אֲחֵרִים, וְהָרוֹצֶה לַעֲמֹד עַל עִקְּרֵי הַדִּינִים יְעַיֵּן בִּפְנִים. \u0006",[],["\u0003לכהן. \u0004 משום דיש בה קדושה ואסורה לזרים לכך מוכרה לכהן:","\u0003הראשון. \u0004 ושני שלישי תרומת מעשר נותן לכהן ומותר השליש של מעשר ראשון הוא שלו ותרומת מעשר מאותו השליש מוכר לכהן מטעם הנ\"ל. ש\"ך:","\u0003בכל. \u0004 היינו מדרבנן אם העובד כוכבים שומר פירות הישראל מה דינו עיין בהרמב\"ם ובכסף משנה באריכות עכ\"ל הש\"ך:","\u0003הגיעו. \u0004 כתב הש\"ך כלומר אם קנה קרקע מהעובד כוכבים בסוריא ופירות מחוברים אז יש חילוק בין הגיעו לעונת המעשרות ביד עובד כוכבים או לא:","\u0003בגוף. \u0004 ויש קנין לעובד כוכבים בסוריא להפקיע מן המעשרות כמו שנתבאר:","\u0003נקבעו. \u0004 וכתב הכ\"מ דפירות ח\"ל כשנכנסו לארץ קודם שנקבעו למעשר חייבים בתרומות ומעשרות מן התורה ואם בשעת קביעותם למעשרות היו בח\"ל פרח מהן חיוב תרומות ומעשרות ואין חייבים אלא מדבריהם וכ\"כ הלבוש:","\u0003חייב. \u0004 ומשמע מדברי הרמב\"ם שמן התורה חייב אבל רש\"י פי' בפ\"ק דקידושין דמעשר אילן הוא מדרבנן \u0005(דדוקא דגן תירוש ויצהר חייבין מדאורייתא)\u0006 והכי אמרינן להדיא בפ' כיצד מברכין דמעשר אילן בארץ גופיה הוא מדרבנן וכ\"כ הראב\"ד עכ\"ל הט\"ז:","\u0003מהירק. \u0004 לפי שגם בא\"י אינו אלא מדבריהם שנאמר תבואת זרעך וירק לאו תבואה היא וה\"ה שאין חייבין בתרומה שהרי נאמר בה דגנך וגו' והתבואה והקטנית שזרעם לירק בטלה דעתו אצל כל אדם והירק שלהם פטור והזרע חייב בתרומה ומעשרות:","\u0003שליש. \u0004 שעדיין אינו נקרא תבואה:","\u0003ההפקר פטור. \u0004 כיון דאין לו בעלים אבל שדה הפקר מ\"מ הדגן אינו הפקר דהא יש לו בעלים לכך חייב:","\u0003מהם. \u0004 ולא יפריש מיניה וביה מן העירוב שמא יפריש מן הפטור על החיוב:","\u0003חשבון. \u0004 פי' שבתחלה מפריש כל המעשרות על הכל כאלו כולן חייבים אבל א\"צ ליתן ללוי ולעני אלא לפי חשבון והשאר חוזר ומערב עם פירותיו אבל תרומה ותרומת מעשר דאסור לזרים נותן הכל לכהן או מוכר לו המותר לפי חשבון. ש\"ך:","\u0003שהוא. \u0004 לפי שגם מן התורה אין לה שיעור ואפי' חטה א' פוטרת כל הכרי וחכמים נתנו שיעור עין יפה א' ממ' ועין רעה א' מס' ובינונית א' מנ' ודוקא בתרומה הנאכלת לכהנים אבל לא בתרומה טמאה העומדת לשריפה דאוקמוה אדאורייתא ושיעורה בכל שהוא:","\u0003להניחה. \u0004 ואפי' הניחה בכלי שאינו מאוס דאין חשש תקלה עכשיו כיון שאין שום תרומה נאכלת לא חיישינן שמא יסבור שהיא טהורה. ט\"ז:","\u0003בנר. \u0004 שנהנה הוא עם הכהן:","\u0003שהוכשרה. \u0004 לקבל טומאה שבאו עליה מים שעכשיו ודאי טמאה היא ומותר לשרפה:","\u0003קודם. \u0004 אבל אחר מירוח שכבר נתחייב בתרומה אסור לגרום טומאה לתרומה טהורה:","\u0003לכהן. \u0004 שקנסו הלוים בימי עזרא על שלא עלו:","\u0003וגו'. \u0004 והגר והיתום והאלמנה דסתמן עניים הם:","\u0003ומואב. \u0004 לפי שהם סמוכים לא\"י תקנו במקום מע\"ש מעשר עני כדי שיבואו עניי א\"י ויתפרנסו ממנו \u0005(ובארץ שנער שהיא רחוקה מא\"י ואין עניי א\"י יכולין לבא לשם מפרישין מע\"ש כמו ברוב שנים)\u0006:","\u0003השי\"ג. \u0004 וכן ימנה לעולם ז' שנים אחר ז' דקי\"ל שנת חמשים עולה לכאן ולכאן. ש\"ך:","\u0003כלום. \u0004 דכתיב ראשית דגנך בעינן ראשית ששיריה ניכרים:","\u0003ציין. \u0004 שלא פירש הראשית:","\u0003המוקף. \u0004 דכיון שמפרישין אותה לא יוכל לכוין השיעור ולמוד אלא במוקף יחד. ש\"ך:","\u0003שמשתברין. \u0004 שהרי אינו יכול לקיים מתנות כהונה:","\u0003הכל. \u0004 חשוב כמוקף וכן חביות שלא סתם פיהם חשיבי כמוקפים אבל משסתמן אינן כמוקפין ואפי' הן בבית א' תורם מכל א' וא'. ש\"ך:","\u0003חולין. \u0004 כלומר עכשיו עד שיפריש התרומה:","\u0003בצד. \u0004 פי' בכרי הגדול שהנחתי:","\u0003שליח. \u0004 שנאמר כן תרימו גם אתם לרבות שלוחכם:","\u0003תרומה. \u0004 דגילה דעתו דניחא ליה במה שזה עושה ואינו מקפיד והרי זה כשלוחו אבל אם אין שם יפות והוא אומר כלך אצל יפות משמעות לשונו הוא הקפדה כאלו מוחה בו ולא ניחא ליה ואינו שלוחו:","\u0003לוי. \u0004 שצריך שיעור ומדידה ואלו אינם יכולין לכוין המדידה:","\u0003הזה. \u0004 כתב הש\"ך תמיהני דבשלמא בתרומה טהורה איכא למימר עין רעה ועין יפה ושייך לומר אם תרם הראשון כשיעור שתרם חבירו אבל במעשר מאי כשיעור שתרם חבירו כו' הלא לעולם צריך להפריש המעשר במדה לכך נ\"ל דבזה\"ז בין במעשר בין בתרומה תרומת השני אינה תרומה עכ\"ל:","\u0003תורמין. \u0004 ודוקא להאכיל אבל לא להניח שלא נעשו אפוטרופסים לעשות שליחות היתומים אלא לפרנסה הכי אמרי' בש\"ס דגיטין:","\u0003והאנס. \u0004 לפי שקנאו בייאוש הבעלים כל שאין מרדפין אחריהם:","\u0003כנס. \u0004 דאין בזה שינוי דגם בעה\"ב נתכוין לכך שהרי אין דרך להכניס אא\"כ תרם תחלה:","\u0003גזרו. \u0004 משום בעלי כיסים שיתלו פירותיהם בעובדי כוכבים כדי לפטרם מתרומה:","\u0003גניזה. \u0004 שמא בלבו לשמים וכתב הרמב\"ם בד\"א בא\"י אבל עובד כוכבים שהפריש תרומה בח\"ל לא גזרו עליהן ומודיעין אותו שא\"צ לתרום ואינה תרומה כלל:","\u0003נתקיים. \u0004 ואם לאו אינה תרומה. ש\"ך:","\u0003קיימים. \u0004 שהדבר תלוי בדעת התורם:","\u0003ונתלשו. \u0004 דהואיל ובידו לתלוש אין מחוסר מעשה:","\u0003תרומה. \u0004 מספק ולא תאכל תרומה זו עד שיוציא כו' דשמא הדמאי כבר נתרם וה\"ל תרומה זו עדיין טבל:","\u0003הלקוח. \u0004 מפני שהלקוח אפי' מישראל אינו חייב מן התורה אלא מדרבנן והגדל בתוך שדהו חייב מן התורה \u0005(שנאמר תבואת זרעך ולא הלקוח)\u0006 וה\"ל כמו מהפטור על החיוב או איפכא \u0005(וכן הלקוח מעובד כוכבים אין חיובו כמו הלקוח מישראל)\u0006:","\u0003תרומה. \u0004 שאסור לזרים והתורם חבית של חומץ על חומץ ונמצא החומץ שתרם יין תרומתו תרומה אף ע\"ג דתרומה בטעות הוי כיון דהטעות הוא לעלויה שעלה בידו מן היפה על הרע הוי תרומה. ש\"ך:","\u0003מעשרה. \u0004 והמעשר הזה הוא ללוים זכרים ונקבות שנאמר ולבני לוי הנה נתתי וגו' וע\"ל ריש הסימן:","\u0003בטומאה. \u0004 וכ\"מ שנאמר במעשר קודש או פדיה אינו אלא מעשר שני:","\u0003מפרישין. \u0004 מתבואה שלהם ונותנין התרומת מעשר של הלוים לכהנים והכהנים מפרישין תרומות ומעשרות כדי שלא יאכלו בטבלים:","\u0003אינו. \u0004 שיחול על נ' סאה שבכרי אלא הכל עודנו בטבלו כיון שלא הוציא ממנו מעשרותיו:","\u0003לעונת. \u0004 דהיינו שיגדלו ויעשו פרי שנאמר מזרע הארץ מפרי העץ עד שיהיה פרי וכן התבואה והקטניות שנאמר את כל תבואת זרעך עד שתעשה תבואה וקודם שתגיע התבואה לעונה זו מותר לאכול מהן כל מה שירצה ובכל דרך שירצה עכ\"ל הש\"ך:","\u0003ממקום. \u0004 ולא מיניה ובי' שמא יפריש מים ולא יין:","\u0003הכל. \u0004 וממילא נפטרו גם השמרים:","\u0003פטור. \u0004 דבטל הוא במים:","\u0003החצר. \u0004 ובית קובע מן התורה והשאר מדרבנן ואסור לאכול אפי' עראי עד שיעשר:","\u0003במוץ. \u0004 שאין הבית קובע מן התורה אלא משנגמרה בכרי אבל לפני מירוח אין ראיית הבית קובעתו דגבי תרומה ומעשר כתיב דגן והוא המירוח ורבנן הוא דאסרו באכילת קבע אבל אכילת עראי לא אסרו מ\"מ אסור להערים להכניס במוץ כדי שיאכל הרבה פעמים מעט מעט כדי שתפטר תבואה זו לעולם מן התרומה ומעשרות אבל להאכיל לבהמתו עראי אפי' כמה פעמים לא גזרו עכ\"ל הש\"ך:","\u0003הגומר. \u0004 וכן הקובע פירותיו של חבירו בא' מן הששה דברים שקובע למעשר שלא מדעתו הרי אלו טבלו למעשר:","\u0003יפקיר. \u0004 להפקיע מהם תרומות ומעשרות שגוזל השבט:","\u0003דמים. \u0004 שהרי דמים קונות מן התורה:","\u0003במחובר. \u0004 ואין המקח קובע אלא בתלושים כמ\"ש בסצ\"ד:","\u0003לקצות. \u0004 פירוש ששניהם אינם מחליפין לאכול אלא לעשות מהם קציעות:","\u0003ופטורים. \u0004 ולא חיישינן שמא הע\"ה כבר הכניסם לביתו ונתחייבו בידו דכיון שנמצאו בשוק מחזקינן להו שלא ראו פני הבית מעולם:","\u0003מזונות. \u0004 כגון שאינו שוכרן ללקט תאנים אלא לחרישה וכה\"ג:","\u0003ספק. \u0004 דמספקינן בש\"ס אי הוי בכלל מבשל שאמרו חכמים שקובע למעשר:","\u0003גומרו. \u0004 באכילת עראי ואינו מעשר דכיון שהניחו מידו ופסק מן האכילה כדי שלא לאכלו בשבת היאך יקבענו שבת שהרי גילה דעתו שלא לאכול ממנו בשבת ש\"ך:","\u0003מדליקין. \u0004 בחול ואצ\"ל בשבת:","\u0003מותר. \u0004 שהרי יעשר מהם לכשיגדלו:","\u0003כזורע. \u0004 שהרי מפקיעין מידי מעשר מכל וכל:","\u0003ולחבר. \u0004 שמא יבא הלוקחו לידי מכשול שלא ידע שטבל הוא:","\u0003המוכר. \u0004 וישלם ללוקח החולין:","\u0003מוציאין. \u0004 אבל אם קנו אותם קודם שתגמר מלאכתן אין מוציאין מידם:","\u0003שלהם. \u0004 אבל אם מכרוהו אחר גמר מלאכתן הרשות ביד הישראל ליתנם לכל כהן שירצה:","\u0003בקבלה. \u0004 שקבל עליו העובדי כוכבי' לעבדה וליתן לישראל ממה שתעשה תבואה חצי או שליש או מה שיתנו ביניהם:","\u0003לעשר. \u0004 דהא הם ודאי לא עשרו:","\u0003לקיטתו. \u0004 שהוא גדל על כל מים ויונק לחות בכל עת עד שלוקטין אותו:","\u0003האתרוג. \u0004 שהרי הוא דר באילן משנה לשנה ויונק בכל עת:","\u0003האביונות. \u0004 הם דומין קצת לאילן וקצת לירק:","\u0003ופודהו. \u0004 ואוכל פדיונו בתורת מעשר שני ונמצא כמי שהפריש מעשר שני ומעשר עני:","\u0003בסוריא. \u0004 לפי שמעשר שני טעון הבאת מקום ואין מביאין אותו מח\"ל שאינו נוהג שם ואינו קדוש אם הפריש הלכך לא חייבו להפרישו בסוריא:","\u0003רצ\"ד. \u0004 שם נתבאר כמה היא הפרוטה:","\u0003לפרש. \u0004 דהא אנו רואין שעוסק בפדיון:","\u0003לבערן. \u0004 כיון שלא הגיע זמנם:","\u0003צדקה. \u0004 וכתב הט\"ז נראה דיש לדמות מעשר שמפרישין מן הריוח ממון לדין מעשר עני של תבואה ופירות והב\"ח כתב שהמעשר של ממון שלנו אין בו חיוב לא מן התורה ולא מדרבנן ותמהתי שהרי ר\"ס רמ\"ט מבואר שחיוב גמור הוא כמ\"ש כל הפוסקים. ונעתיק דברי הטור בקיצור לענין מעשר עני וז\"ל באו איש ואשה לשאול כו' \u0005(כמ\"ש בסי' רנ\"א ס\"ט)\u0006 וכשהוא מחלקו בשדה אין בו טובת הנאה לבעלים אבל המתחלק בבית יש לו טובת הנאה לבעלים ונותנו לכל עני שירצה. ומזה נ\"ל סמך למה שנוהגין לכוף החתן בשעת קבלת הנדוניא שלו ליתן מעשר כדאשכחן כן גבי מעשר עני שמוציאין מידו בע\"כ אלא שמחלקין את המעשר לקרובי החתן והכלה דהם קודמין לשאר עניים בזה. וראיתי קצת אומרים דדוקא מהנדן שהכלה נותנת להחתן מפריש מעשר אבל לא ממה שאבי החתן נותן לבנו ותמהתי מהיכא תיתי לחלק דאטו יש חיוב על הממון והלא חובת גברא הוא ומה לי שנותן לו אביו או חותנו ודאי דעת משובש הוא מי שאומר כן. ואם אב ובנו או שני אחים ושותפים שא' מהן עני נותן לו השני מעשר עני שלו ושני עניים שקבלו שדה באריסות זה מפריש מעשר עני על חלקו ונותן לחבירו וכן להיפך. ואין פורעין בו המלוה ולא משלמין בו את תגמולין כגון שחבירו עשה לו טובה של דבר הרשות אסור לשלם גמולו במעשר עני אבל משלמין ממנו דבר של גמילות חסדים כגון סעודת הבראה של אבל וצריך להודיעו שהוא מעשר עני ואין פודין בו את השבויים והיינו שיש בלא\"ה חיוב עליו כגון שפסקו עליו לפדותו אבל אם אינו חייב לפדותו בלא\"ה ודאי יכול לתת מעשר עני שלו לזה דאין לך צדקה גדולה מזו דשבי כולהו איתנהו ביה ואין נותנין ממנו צדקה שפסקו עליו בני העיר שכבר נתחייב בה דה\"ל פורע חובו ונותנין אותו לחבר עיר המתעסק בצרכי הצבור ומפרנסין אותו ושולחים לו המעשר עני דרך כבוד ודורון אע\"ג דאין שולחין לו צדקה מן הכיס של צדקה היינו משום דגנאי הוא לבני העיר לפרנס חכם שלהם מן הצדקה אבל מעשר עני ששולחין לו מהגורן לא מינכר דמ\"ע הוא אלא מיחזי כמנחה ודורון דרך כבוד. וכל זה נראה ששייך ג\"כ במעשר שמפרישין מן הריוח שנתן הש\"י לבני האדם: ולעיל סי' רנ\"א כתב הב\"י בשם המרדכי דמ\"ע דומה למפריש צדקה עכ\"ל הט\"ז והש\"ך:"]],["לֶקֶט, שִׁכְחָה וּפֵאָה, אִם אֵין עֲנִיֵּי יִשְׂרָאֵל מְצוּיִים שָׁם לִטְּלָם, אֵין צָרִיךְ לְהַנִּיחָם. \u0005הַגָּה: וְהָאִדָּנָא אֵין נוֹהֲגִין בָּהֶם, לְפִי שֶׁהָרֹב עוֹבְדֵי כּוֹכָבִים, וְאִם יַנִּיחוּם, יָבוֹאוּ עוֹבְדֵי כּוֹכָבִים \u0010c0\u0011 וְיִטְּלוּם (טוּר)\u0006.",[],["\u0003ויטלום. \u0004 כב\"י עוד אפשר לומר דע\"כ לא אמרו דבח\"ל חייבים אלא בסמוכה לארץ דכשם שחייבת בתרומה ומעשרות חייבת במתנות אבל במקומות דרחוקים כשם שפטורים מתרומות ומעשרות פטורים ממתנות עכ\"ל:"]],["רֵאשִׁית הַגֵּז אֵינוֹ נוֹהֵג אֶלָּא בָּאָרֶץ, בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת. \u0005וְיֵשׁ אוֹמְרִים דְּבַר תּוֹרָה רֵאשִׁית הַגֵּז נוֹהֵג אֲפִלּוּ בְּחוּץ לָאָרֶץ, אֶלָּא שֶׁלֹּא נָהֲגוּ כֵן (טוּר)\u0006.\nאֵין חַיָּבִים בְּרֵאשִׁית הַגֵּז אֶלָּא \u0010c0\u0011 הַכְּבָשִׁים בִּלְבַד, זְכָרִים וּנְקֵבוֹת. וְאִם הָיָה צִמְרָן קָשֶׁה וְאֵינוֹ רָאוּי לִלְבִישָׁה, פָּטוּר.\nגָּזַז הַצֶּמֶר וְלִבְּנוֹ, חַיָּב. אֲבָל אִם צְבָעוֹ, \u0010c1\u0011 פָּטוּר.\nהַגּוֹזֵז אֶת הַמֵּתָה, פָּטוּר. \u0005הַתּוֹלֵשׁ צֶמֶר רְחֵלִים בְּיָדוֹ, וְלֹא גָּזַז, חַיָּב.\u0006\nהַמַּפְרִישׁ רֵאשִׁית הַגֵּז, וְאָבַד, חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיִּתְּנֶנּוּ לְכֹהֵן.\nהָאוֹמֵר: כָּל גִּזָּתִי רֵאשִׁית, דְּבָרָיו קַיָּמִים.\nהַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל עוֹבֵד כּוֹכָבִים, אַחַר שֶׁגְּזָזָן הָעוֹבֵד כּוֹכָבִים, פָּטוּר מֵרֵאשִׁית הַגֵּז. וְאִם לָקַח הַצֹּאן \u0010c2\u0011 לְגִזָּתָן, חַיָּב, אַף עַל פִּי שֶׁגָּדְלָה הַגִּזָּה בִּרְשׁוּת הָעוֹבֵד כּוֹכָבִים, וְאַף עַל פִּי שֶׁחוֹזְרִים הַצֹּאן לָעוֹבֵד כּוֹכָבִים אַחַר גְּזִיזָה, חַיָּב. \u0005וְיֵשׁ חוֹלְקִין וְאוֹמְרִים דְּפָטוּר, אִם לֹא קָנָה הַצֹּאן לְגִזָּתָן (דַּעַת רַשִׁ\"י וְטוּר)\u0006.\nהַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל \u0010c3\u0011 חֲבֵרוֹ, אִם שִׁיֵּר הַמּוֹכֵר מְעַט מִצֹּאנוֹ לְהִגָּזֵז, חַיָּב לְהַפְרִישׁ מֵהַנִּשְׁאָר עַל הַכֹּל. וְאַף עַל פִּי שֶׁלֹּא \u0010c4\u0011 הִתְחִיל הַמּוֹכֵר לִגְזֹז. וְאִם לֹא שִׁיֵּר כְּלוּם, \u0010c5\u0011 הַלּוֹקֵחַ חַיָּב לְהַפְרִישׁ. וְאִם הָיוּ שְׁנֵי מִינִים, כְּגוֹן גִּזָּה לְבָנָה וְגִזָּה שְׁחוּמָה \u0005(פי' אֲדֻמָּה)\u0006 וּמָכַר מִין זֶה וְהִנִּיחַ הַמִּין הָאַחֵר, זֶה נוֹתֵן לְעַצְמוֹ עַל מַה שֶּׁלָּקַח וְזֶה נוֹתֵן לְעַצְמוֹ עַל מַה שֶׁמָּכַר. \u0005הַגָּה: קָנָה גֵּז צֹאנוֹ שֶׁל חֲבֵרוֹ, אִם שִׁיֵּר הַמּוֹכֵר קְצָת גִּזָּה לְעַצְמוֹ, הוּא חַיָּב. לֹא שִׁיֵּר מֵהֶם כְּלוּם, הַלּוֹקֵחַ חַיָּב לִתֵּן. וְאִם \u0010c6\u0011 פֵּרֵשׁ לוֹ: אֲנִי מוֹכֵר לְךָ הַכֹּל, שְׁנֵיהֶם פְּטוּרִים (טוּר)\u0006.\nכַּמָּה צֹאן יִהְיוּ לוֹ וְיִהְיוּ חַיָּבוֹת בְּרֵאשִׁית הַגֵּז, אֵין פָּחוֹת \u0010c7\u0011 מֵחָמֵשׁ; וְהוּא שֶׁיִּהְיֶה בַּגִּזָּה שֶׁלָּהֶם אֵין פָּחוֹת מִמִּשְׁקַל שִׁשִּׁים סֶלַע; וְתִהְיֶה גִּזַּת כָּל אֶחָד מֵחֲמִשְׁתָּן אֵין פָּחוֹת מִי\"ב סֶלַע; וְאִם הָיְתָה אַחַת מֵהֶן גּוֹזֶזֶת פָּחוֹת מִי\"ב, אַף עַל פִּי שֶׁחֲמִשְׁתָּן גּוֹזְזוֹת שִׁשִּׁים סֶלַע אוֹ יוֹתֵר, פָּטוּר.\nהַשֻּׁתָּפִים, חַיָּבִים. וְהוּא שֶׁיִּהְיֶה בְּחֵלֶק כָּל אֶחָד כַּשִּׁעוּר. אֲבָל חֲמִשָּׁה צֹאן בִּלְבַד שֶׁל שְׁנֵי שֻׁתָּפִין, פְּטוּרִין.\nרֵאשִׁית הַגֵּז, מִצְוָתָהּ בַּתְּחִלָּה. וְאִם הִפְרִישׁ, בֵּין בָּאֶמְצַע בֵּין בַּסוֹף, יָצָא.\nהָיוּ לוֹ ה' צֹאן וְגָזַז אַחַת מֵהֶן בִּלְבַד, וּמָכַר גִּזָּתָהּ, וְאַחַר כָּךְ גָּזַז שְׁנִיָּה וּמָכַר גִּזָּתָהּ, וְאַחַר כָּךְ גָּזַז שְׁלִישִׁית וּמָכַר גִּזָּתָהּ, הַכֹּל מִצְטָרְפוֹת לְרֵאשִׁית הַגֵּז וְחַיָּב לְאַחַר כַּמָּה שָׁנִים. \u0005וְהוּא הַדִּין אִם מָכַר קְצָת הַצֹּאן לְאַחַר שֶׁהִתְחִיל לִגְזֹז.\u0006 וְיֵשׁ לוֹ לְהַפְרִישׁ מִן הֶחָדָשׁ עַל הַיָּשָׁן וּמִזֶּה עַל זֶה. \u0005הָיוּ לוֹ שְׁנֵי מִינִים, רַע וְטוֹב, לֹא יִתֵּן מִן הָרַע עַל הַטּוֹב, אֶלָּא יִתֵּן מִכָּל אֶחָד לְפִי שִׁעוּרוֹ (טוּר)\u0006. אֲבָל אִם הָיְתָה רָחֵל אַחַת וּגְזָזָהּ, וְאַחַר כָּךְ קָנָה שְׁנִיָּה וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ, וְאַחַר כָּךְ קָנָה שְׁלִישִׁית וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ, אֵינָם מִצְטָרְפִין.\nמִי שֶׁהָיוֹ לוֹ גִּזּוֹת רַבּוֹת שֶׁל רֵאשִׁית הַגֵּז, וְרוֹצֶה לְחַלֵּק לַכֹּהֲנִים, לֹא יִתֵּן לְכָל אֶחָד פָּחוֹת מִמִּשְׁקַל חֲמִשָּׁה סְלָעִים מְלֻבָּן, כְּדֵי בֶּגֶד קָטָן. לֹא שֶׁיְּלַבְּנוֹ וְאַחַר כָּךְ יִתֵּן, אֶלָּא יִתֵּן לוֹ מִצֶּמֶר הַגִּזָּה כְּשֶׁהוּא צוֹאִי \u0005(פי' מְטֻנָּף)\u0006 כְּדֵי שֶׁיִּהְיֶה בּוֹ אַחַר הַלִּבּוּן חֲמִשָּׁה סְלָעִים אוֹ יוֹתֵר, שֶׁנֶּאֱמַר: תִּתֶּן לוֹ, \u0005(דְּבָרִים יח, ד)\u0006 שֶׁיִּהְיֶה בּוֹ כְּדֵי מַתָּנָה הַמּוֹעֶלֶת. \u0005אֲבָל אֵינוֹ חַיָּב לִתֵּן רַק חֲמִשָּׁה סְלָעִים \u0010c8\u0011 מֵהַכֹּל (טוּר)\u0006.\nרֵאשִׁית הַגֵּז חֻלִּין לְכָל דָּבָר. לְפִיכָךְ נוֹתְנִין אוֹתוֹ לַכֹּהֶנֶת, אַף עַל פִּי שֶׁהִיא נְשׂוּאָה לְיִשְׂרָאֵל.",[],["\u0003הכבשים. \u0004 דכיון דתלה רחמנא טעמא דראשית הגז בשירות כהונה ראשית גז צאנך תתן לו וגו' לעמוד לשרת דבר הראוי לשרת דהיינו רחלים שצמרן ראוי לעשות ממנו תכלת לבגדי כהונה. ש\"ך:","\u0003פטור. \u0004 שקנאו בשינוי והוי כמזיק מתנות כהונה או שאכלן דפטור כמ\"ש בסימן ס\"א סל\"א:","\u0003לגיזתן. \u0004 פי' שלקח הגיזה בעודה במחובר אע\"פ שלא לקח גוף הצאן אלא הגיזה בלבד חייב אע\"פ שגדלה הגיזה ברשות העובד כוכבים ואף ע\"ג שעיקר הצאן של עובד כוכבים הוא. והיש חולקים סוברים שאינו חייב אא\"כ שגוף הצאן יהיו שלו בשעת הגיזה. עכ\"ל הש\"ך:","\u0003חבירו. \u0004 בעודו במחובר:","\u0003התחיל. \u0004 דחזקה אין אדם מוכר מתנות כהונה ומתנה דכהן גבי מוכר היא:","\u0003הלוקח חייב. \u0004 שאומר לו המוכר מתנה דכהן לא מכרתי לך ומה שלקחתי ממך מעות לא לקחתי אלא בעד צמרי חוץ מחלקו של כהן:","\u0003פירש. \u0004 כתב הש\"ך דהיינו אם אחר גיזה מכרה המוכר חייב דהא משעת גזיזה חל עליו ליתן ולמה מכרה. והלוקח פטור דלאו גז צאנך הוא. ואם בעודו מחובר מכרה לו ופי' לו הכל אני מוכר לך שניהם פטורים המוכר פטור דבעודו מחובר לא חל עליו ראשית הגז ובשעת גזיזה לאו גז צאנך הוא דגיזה לאו שלו והלוקח ג\"כ פטור דהצאן אינו שלו ומ\"מ לכתחלה אסור לעשות כן למכור הצמר במחובר ולהפקיע ממונו מיד מצוה עכ\"ל:","\u0003מה'. \u0004 דכתיב חמש צאן עשויות. ודרשו בו שמעשות את בעליהן למצוה:","\u0003מהכל. \u0004 ומדרבנן דמן התורה בכל דהו סגי:"]],["\u0003הלכות נידוי וחרם\u0004\nהָעוֹבֵר עַל דְּבַר אִסוּר, מְנַדִּין אוֹתוֹ \u0010c0\u0011 לְאַלְתַּר. \u0005הַגָּה: אֲבָל מִכֹּחַ מָמוֹן, אֵין מְנַדִּין אוֹתוֹ, עַד שֶׁיַּתְרוּ בּוֹ ג' פְּעָמִים, דְּהַיְנוּ ב' ה' ב' (טוּר)\u0006 מִן הַבֵּית דִּין, כְּמוֹ שֶׁיִּתְבָּאֵר בְּחשֶׁן מִשְׁפָּט סִימָן י\"א. וְאֵין נִדּוּי פָּחוֹת \u0010c1\u0011 מִשְּׁלֹשִׁים יוֹם; וְאִם אֵינוֹ חוֹזֵר בּוֹ, שׁוֹנִים לְנַדּוֹתוֹ לְאַחַר שְׁלֹשִׁים יוֹם. וְאִם אֵינוֹ חוֹזֵר בּוֹ, מַמְתִּינִים לוֹ עוֹד שְׁלֹשִׁים וּמַחֲרִימִין אוֹתוֹ. אֲפִלּוּ פָּגַע הָרֶגֶל בְּתוֹךְ שְׁלֹשִׁים יוֹם, אֵינוֹ מְבַטֵּל אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, דְּנִדּוּי שְׁלֹשִׁים יוֹם, בְּנִדּוּי דִּידְהוּ, אֲבָל נִדּוּי דִּידָן כִּנְזִיפָה דִּידְהוּ, שֶׁהִיא ז' יָמִים; וּנְזִיפָה דִּידָן, חַד יוֹמָא. \u0005הַגָּה: וּמְנַדִּין לְמִי שֶׁהוּא חַיָּב נִדּוּי, וַאֲפִלּוּ יֵשׁ \u0010c2\u0011 לָחוּשׁ שֶׁעַל יְדֵי כֵן יֵצֵא לְתַרְבּוּת רָעָה, אֵין לָחוּשׁ בְּכָךְ (פִּסְקֵי מהרא\"י סִימָן קל\"ח)\u0006.\nהַמְנֻדֶּה, אֵין יוֹשְׁבִין בְּד' \u0010c3\u0011 אַמּוֹתָיו, חוּץ מֵאִשְׁתּוֹ וּבָנָיו. \u0005(ר\"ן)\u0006 \u0005וְיֵשׁ אוֹמְרִים אַף בְּנֵי בֵּיתוֹ, שָׁרֵי\u0006 \u0005(טוּר ובת\"ה סִימָן רע\"ו)\u0006 \u0005וְיֵשׁ לְהָקֵל.\u0006 וְאֵין אוֹכְלִין \u0005וְשׁוֹתִין\u0006 עִמּוֹ \u0005(טוּר)\u0006. וְאֵין \u0010c4\u0011 מְזַמְּנִין עָלָיו. וְאֵין כּוֹלְלִין אוֹתוֹ לְכָל דָּבָר שֶׁצָּרִיךְ עֲשָׂרָה. \u0005הַגָּה: אֲבָל אִם לֹא \u0010c5\u0011 נִדּוּהוּ בְּפֵרוּשׁ, אַף עַל גַּב שֶׁהוּא עֲבַרְיָן אוֹ שֶׁעָבַר עַל גְּזֵרַת צִבּוּר, מְצָרְפִין אוֹתוֹ לְמִנְיַן י' לְהִתְפַּלֵּל עִמּוֹ (ריב\"ש סִימָן קע\"ב וּמָרְדְּכַי רֵישׁ שְׁבוּעוֹת שְׁתַּיִם וְהַגָּהוֹת אַלְפָסִי פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. וַאֲפִלּוּ מְנֻדֶּה מַמָּשׁ שֶׁאֵין מְצָרְפִין אוֹתוֹ לְמִנְיָן, מִכָּל מָקוֹם מֻתָּר לְהִתְפַּלֵּל בְּעוֹדוֹ בְּבֵית הַכְּנֶסֶת \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א וריב\"ש סי' קע\"ב)\u0006. וּמָה שֶׁנָּהֲגוּ לְגָרְשׁוֹ מִבֵּית הַכְּנֶסֶת, שֶׁלֹּא יִדְחֹק יְחִידִים שֶׁצְּרִיכִים \u0010c6\u0011 לְהִתְרַחֵק מֵאַרְבַּע אַמּוֹתָיו. \u0005(שָׁם בריב\"ש)\u0006. וְאָסוּר בְּתִכְבֹּסֶת וּבְתִסְפֹּרֶת וּבִנְעִילַת \u0010c7\u0011 הַסַנְדָּל, \u0005(ראב\"ד ורא\"ש)\u0006 כְּאָבֵל. וּמֻתָּר בְּדִבְרֵי תּוֹרָה. שׁוֹנֶה, וְשׁוֹנִין לוֹ. נִשְׂכָּר, וְנִשְׂכָּרִין לוֹ. וְהַמֻּחְרָם, לֹא שׁוֹנֶה וְלֹא שׁוֹנִין לוֹ; לֹא נִשְׂכָּר וְלֹא נִשְׂכָּרִין לוֹ; וְכֵן אָסוּר לְהַנּוֹתוֹ יוֹתֵר מִכְּדֵי חַיָּיו \u0005(תְּשׁוּבַת רַשְׁבָּ\"א)\u0006. אֲבָל שׁוֹנֶה הוּא לְעַצְמוֹ, שֶׁלֹּא יִשְׁכַּח תַּלְמוּדוֹ, וְעוֹשֶׂה לוֹ חֲנוּת קְטַנָּה כְּדֵי פַּרְנָסָתוֹ; וּמֻתָּר לְדַבֵּר עִם הַמְּנֻדֶּה וְעִם הַמֻּחְרָם, אֶלָּא אִם כֵּן הֶחְמִירוּ עָלָיו בֵּית דִּין בְּפֵרוּשׁ. \u0005הַגָּה: וּמִכָּל מָקוֹם לֹא יַרְבֶּה עִמּוֹ בִּדְבָרִים, וְלֹא יְדַבֵּר עִמּוֹ אֶלָּא לְצֹרֶךְ, כְּמוֹ שֶׁמְּדַבֵּר עִם הָאָבֵל (הַגָּהוֹת אַלְפָסִי וריב\"ש הַנַּ\"ל)\u0006. בְּמָקוֹם שֶׁאָסוּר לֵישֵׁב בְּד' אַמּוֹתָיו, כָּל שֶׁאָדָם יוֹשֵׁב תְּחִלָּה וְהַמְנֻדֶּה בָּא לְשָׁם, אֵין צָרִיךְ לְהִתְרַחֵק מִשָּׁם \u0005(בֵּית יוֹסֵף בְּשֵׁם הַקוּנְטְרֵס)\u0006. וְאָסוּר לִכָּנֵס לְבֵיתוֹ, דְּהָוֵי כְּד' אַמּוֹתָיו, וְאֵין חִלּוּק בֵּין \u0010c8\u0011 עוֹמֵד לְיוֹשֵׁב \u0005(שָׁם)\u0006.\nמְנֻדֶּה שֶׁמֵּת, בֵּית דִּין שׁוֹלְחִין וּמַנִּיחִין \u0010c9\u0011 אֶבֶן עַל אֲרוֹנוֹ, וְאֵין קוֹרְעִין עָלָיו, וְלֹא חוֹלְצִין, וְלֹא \u0010c10\u0011 מַסְפִּידִין. וְהָנֵי מִלֵּי לְאַפְקִירוּתָא וְעוֹבֵר עַל דִּבְרֵי חֲכָמִים; אֲבָל לְמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם וְאֵין סוֹקְלִין אֲרוֹנוֹ, וּמַסְפִּידִין אוֹתוֹ כָּרָאוּי.\nאֲפִלּוּ נִדּוּהוּ מִשּׁוּם עוֹבֵר עַל דִּבְרֵי חֲכָמִים, אִם חָזַר בּוֹ, אַף עַל פִּי שֶׁלֹּא הִתִּירוּ נִדּוּיוֹ, מִתְעַסְקִין עִמּוֹ לְכָל דָּבָר.\nאַף עַל פִּי שֶׁאָסוּר לֶאֱכֹל וְלִשְׁתּוֹת עִם הַמְּנֻדֶּה אוֹ הַמֻּחְרָם, מִכָּל מָקוֹם הָאוֹכֵל וְשׁוֹתֶה עִמּוֹ אֵין לוֹ דִּין מְנֻדֶּה.\nאִם רָצוּ בֵּית דִּין לְמַעֵט הַנִּדּוּי מִל' יוֹם, אוֹ לְהוֹסִיף, הָרְשׁוּת בְּיָדָם. \u0005הַגָּה: וְיֵשׁ רְשׁוּת לְבֵית דִּין לְהַחְמִיר עָלָיו שֶׁלֹּא יָמוּלוּ בָּנָיו, וְשֶׁלֹּא יִקָּבֵר אִם יָמוּת (בִּנְיָמִין זְאֵב סי' רפ\"ט וְכֵן כָּתַב הַבֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן סי' רמ\"ד)\u0006, וּלְגָרֵשׁ אֶת בָּנָיו מִבֵּית \u0010c11\u0011 הַסֵּפֶר וְאִשְׁתּוֹ מִבֵּית הַכְּנֶסֶת, עַד שֶׁיְּקַבֵּל עָלָיו הַדִּין \u0005(נ\"י פֶּרֶק הַגּוֹזֵל)\u0006.\nכְּשֶׁיַּגִּיעַ הַזְּמַן, מַתִּירִין לוֹ אִם יִרְצוּ, אַף אִם לֹא יַחֲזֹר בּוֹ. וּמִכָּל מָקוֹם טוֹב, הוּא, שֶׁלֹּא יַתִּירוּ לוֹ אִם לֹא יַחֲזֹר בּוֹ, שֶׁלֹּא תִּתְמַעֵט \u0010c12\u0011 יִרְאָתָם.\nאִם יִרְצוּ בֵּית דִּין לְהַחְמִיר עָלָיו עוֹד וּלְהַחֲרִימוֹ, הָרְשׁוּת בְּיָדָם.\nאִם רָאוּ בֵּית דִּין קֹשִׁי הָאִסוּר וְהָעֲבֵרָה, מַחֲרִימִין גַּם הָאוֹכֵל וְשׁוֹתֶה עִמּוֹ וְהַיּוֹשֵׁב בְּד' אַמּוֹתָיו.\nאִם רָאוּ בֵּית דִּין לְנַדּוֹת, שֶׁלֹּא יְזַמֵּן בִּשְׁלֹשָׁה, וְלֹא יִתְפַּלֵּל בַּעֲשָׂרָה, וְלֹא יִקְבְּרוּ לוֹ מֵת, וְלֹא יָמוּלוּ לוֹ בֵּן, \u0010c13\u0011 רַשָּׁאִים הֵם.\nאִם נִתְנַדָּה עַל \u0010c14\u0011 עֲבֵרָה, אֵינוֹ מִצְטָרֵף לַעֲשָׂרָה.\nהָא דְּאָמְרִינַן בִּמְנֻדֶּה סְתָם שֶׁהוּא אָסוּר בְּדִינֵי הַמְּנֻדֶּה, דַּוְקָא מְנֻדֶּה לְבֵית דִּין שֶׁהוּא מְנֻדֶּה לְכָל אָדָם, בֵּין דְּלֹא אָתֵי לְבֵית דִּין אוֹ דְּלֹא צָיֵת דִּינָא אוֹ לְאַפְקִירוּתָא אוֹ לִדְבַר עֲבֵרָה, בֵּין נִדּוּהוּ בֵּית דִּין, בֵּין שֶׁנִּדָּהוּ כָּל אָדָם, דִּינוֹ שָׁוֶה; בֵּין לְעִירוֹ, בֵּין לְעִיר אַחֶרֶת. אֲבָל מְנֻדֶּה לַחֲצָאִין, כְּגוֹן תַּלְמִיד שֶׁנִּדָּה לִכְבוֹדוֹ, וְכֵן מְנֻדֶּה לְעִיר אַחֶרֶת שֶׁנִּדּוּהוּ לִכְבוֹדָם, אֵינוֹ אָסוּר בְּכָל דִּין הַמְּנֻדֶּה, אֶלָּא שֶׁבְּנֵי אָדָם מַרְחִיקִין אוֹתוֹ כְּדֵי לְבַיְּשׁוֹ, אֲבָל אֲבֵלוּת אֵין \u0010c15\u0011 עָלָיו.\nהָא דְּאָמְרִינַן סְתָם נִדּוּי ל', הַיִנוּ לְעִנְיָן כְּשֶׁמְּנַדִּין אוֹתוֹ \u0010c16\u0011 אוֹמְרִים: פְּלוֹנִי יְהֵא בְּנִדּוּי שְׁלֹשִׁים יוֹם; וּמִכָּל מָקוֹם אִם חָזַר בּוֹ, אִם הָיָה הַנִּדּוּי בִּשְׁבִיל מָמוֹן אוֹ אַפְקִירוּתָא וּפִיֵּס לְבַעַל דִּינוֹ, מַתִּירִין אוֹתוֹ לְאַלְתַּר. וַאֲפִלּוּ אִם לֹא חָזַר בּוֹ, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּתִּירִין לוֹ לְאַחַר שְׁלֹשִׁים יוֹם, וְהוּא שֶׁיָּבֹא לְבֵית דִּין וּמְבַקֵּשׁ שֶׁיַּתִּירוּ לוֹ. אֲבָל אִם מְזַלְזֵל בַּנִּדּוּי וְאֵינוֹ מְבַקֵּשׁ שֶׁיַּתִּירוּ לוֹ, מַנִּיחִין אוֹתוֹ בְּנִדּוּי עַד שֶׁיָּמוּת. וְיֵשׁ מִי שֶׁחוֹלֵק בָּזֶה \u0010c17\u0011 \u0005וְסוֹבֵר דְּאַף לְאַחַר שְׁלֹשִׁים אֵין מַתִּירִין לוֹ עַד שֶׁיַּחֲזֹר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006 ; וְתוֹךְ שְׁלֹשִׁים אֵין מַתִּירִין לוֹ אֲפִלּוּ חָזַר מִמַּה שֶּׁעָשָׂה \u0005(מַשְׁמָע בְּבֵית יוֹסֵף לְדַעַת הַרַמְבַּ\"ם)\u0006.\nנְזִיפָה הִיא שֶׁאָדָם גָּדוֹל גּוֹעֵר בּוֹ לוֹמַר: כַּמָּה פְּלוֹנִי חָצוּף, וְכַיּוֹצֵא בוֹ. וְזֶה \u0010c18\u0011 מִשְׁפָּטוֹ, שֶׁיְּהֵא מִתְחַבֵּא וְיוֹשֵׁב בְּבֵיתוֹ, וִיהֵא נִכְלָם, וְלֹא יַרְאֶה פָּנִים לְמִי שֶׁהִכְלִימוֹ, וִימַעֵט בִּשְׂחוֹק וּבְדִבּוּר וּבַעֲסָקָיו, וִיצַעֵר עַצְמוֹ לְעֵינֵי כָּל רוֹאָיו. אֲבָל אֵין צָרִיךְ לְהִתְרַחֵק מִבְּנֵי אָדָם, לֹא בַּאֲכִילָה וּשְׁתִיָּה, וְלֹא בִּשְׁאֵלַת שְׁלוֹם, וְאֵין צָרִיךְ לִנְהֹג בְּאַחַת מִכָּל דִּינֵי הָאֵבֶל, וְאֵין צָרִיךְ לְפַיֵּס לְמִי שֶׁהֶחֱצִיף כְּנֶגְדּוֹ, וְאֵין צָרִיךְ שֶׁיַּתִּירוּ לוֹ, אֶלָּא כֵּיוָן שֶׁנָּהַג כְּנָזוּף, \u0010c19\u0011 זְמַן נְזִיפָה, מֻתָּר מִמֵּילָא. \u0005הַגָּה: וַאֲפִלּוּ לֹא אָמַר לוֹ הַגָּדוֹל כְּלוּם, אֶלָּא שֶׁיּוֹדֵעַ בְּעַצְמוֹ שֶׁאָדָם גָּדוֹל נָקַט בְּלִבּוֹ עָלָיו, צָרִיךְ לִנְהֹג נְזִיפָה בְּעַצְמוֹ (תְּשׁוּבַת ר' דָּוִד כֹּהֵן סי' כ\"ב)\u0006.\nמְנֻדֶּה לָרַב, מְנֻדֶּה לַתַּלְמִיד. \u0005אֲבָל אֵינוֹ \u0010c20\u0011 מְנֻדֶּה לִשְׁאָר הַחֲכָמִים (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006. מְנֻדֶּה לַתַּלְמִיד שֶׁנִּדָּה לִכְבוֹדוֹ, אֵינוֹ מְנֻדֶּה לָרַב, אֲבָל מְנֻדֶּה הוּא לִשְׁאָר הָעָם \u0005שֶׁאֵינָן חֲכָמִים. אֲבָל לֹא \u0010c21\u0011 לַחֲכָמִים, אֲפִלּוּ קְטַנִּים מִמֶּנּוּ (בֵּית יוֹסֵף מִמַּשְׁמָעוּת לְשׁוֹן הַרַמְבַּ\"ם)\u0006. וְדַוְקָא בִּמְנֻדֶּה שֶׁלֹּא בִּפְנֵי הָרַב, אֲבָל בִּפְנֵי הָרַב, \u0010c22\u0011 אַפְקִירוּתָא הִיא, וְאִי פָּלִיג לֵיהּ רַבֵּיהּ יְקָרָא, שַׁפִּיר דָּמִי. \u0005רַב שֶׁגָּזַר חֵרֶם וְנִדּוּי בְּאֵיזֶה דָּבָר, וְאֵין תַּלְמִידָיו יְכוֹלִין לַעֲמֹד בִּגְזֵרוֹתָיו, אֵין צְרִיכִין \u0010c23\u0011 לְקַיֵּם (פִּסְקֵי מהרא\"י סי' רכ\"ב)\u0006.\nתַּלְמִיד יָכוֹל לְנַדּוֹת לְמִי \u0010c24\u0011 שֶׁבִּזָּה בְּפָנָיו רַבּוֹ אוֹ אָבִיו, וּמִכָּל מָקוֹם כֵּיוָן שֶׁלֹּא נִדָּהוּ הָרַב, וְגַם לֹא נִדּוּהוּ בֵּית דִּין, אֵינוֹ \u0010c25\u0011 מְנֻדֶּה לָרַב.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּמִי שֶׁנִּדּוּהוּ מִפְּנֵי שֶׁבִּזָּה תַּלְמִיד חָכָם. אֲבָל מִי שֶׁנִּדּוּהוּ עַל שְׁאָר דְּבָרִים שֶׁחַיָּב עֲלֵיהֶם נִדּוּי, אֲפִלּוּ נִדָּהוּ קָטָן שֶׁבְּיִשְׂרָאֵל, חַיָּב הַנָּשִׂיא וְכָל יִשְׂרָאֵל לִנְהֹג בּוֹ נִדּוּי, עַד שֶׁיַּחֲזֹר בִּתְשׁוּבָה מִדָּבָר שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ וְיַתִּירוּ לוֹ.\nרַב מִצַּד הַשִּׁלְטוֹן וְאֵינוֹ רַב בַּתּוֹרָה, אֵינוֹ יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ. \u0005הַגָּה: וְכָל שֶׁכֵּן מִי שֶׁנּוֹהֵג שְׂרָרָה אוֹ רַבָּנוּת מִצַּד מָמוֹנוֹ אוֹ יִחוּסוֹ, שֶׁאֵינוֹ יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ (בֵּית יוֹסֵף בְּשֵׁם קֻנְטְרֵסִין)\u0006. וְדַוְקָא מְנַדִּין לִכְבוֹד הָרַב, אֲבָל לֹא \u0010c26\u0011 מַחֲרִימִין \u0005(בֵּית יוֹסֵף וריב\"ש סי' קע\"ג)\u0006, אִם לֹא שֶׁמַּחֲזִיק בְּמַחֲלֹקֶת יוֹתֵר מִדַּאי \u0005(שָׁם בריב\"ש)\u0006. וְהָא דְּאָמְרִינַן הָרַב שֶׁנִּדָּה לִכְבוֹדוֹ הָוֵי מְנֻדֶּה לְתַלְמִידָיו, הַיְנוּ אִם לֹא חָזַר בּוֹ הַמְּנֻדֶּה קֹדֶם שֶׁנִּדָּה אוֹתוֹ, אֲפִלּוּ אִם הִבְטִיחַ אֶת הָרַב לְפַיְּסוֹ אַחַר כָּךְ, לֹא מְהָנֵי עַד \u0010c27\u0011 שֶׁיַּעֲשֶׂה. אֲבָל אִם קֹדֶם שֶׁנִּתְנַדָּה אָמַר לְפַיֵּס הָרַב, וְלֹא הִשְׁגִּיחַ עָלָיו, וְנִדָּהוּ, אֵינוֹ מְנֻדֶּה כְּלָל לְתַלְמִידָיו. וּמִיָּד שֶׁאוֹמֵר שֶׁיְּתַקֵּן אֲשֶׁר עִוֵּת כְּפִי מַה שֶּׁיַּגִּידוּ לוֹ חֲכָמִים, אֵין נִדּוּי עָלָיו \u0005(מהרי\"ק שֹׁרֶשׁ קס\"ט)\u0006. קָהָל שֶׁתִּקְּנוּ שֶׁאֵין אָדָם יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ, אֵין בְּתַקָּנָתָם כְּלוּם, וְאִם עָמַד רַב וְנִדָּה לִכְבוֹדוֹ, נִדּוּיוֹ נִדּוּי \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן ת\"ס)\u0006.\nזָקֵן שֶׁנִּדָּה לְצֹרֶךְ עַצְמוֹ, אֲפִלּוּ כַּהֲלָכָה, אֵינוֹ נִדּוּי. \u0005הַגָּה: פֵּרוּשׁ שֶׁלֹּא \u0010c28\u0011 נִתְכַּוֵּן לִכְבוֹד תּוֹרָה, רַק לְהַרְוִיחַ מָמוֹן שֶׁיִּתֵּן לוֹ שֶׁיַּתִּיר לוֹ נִדּוּיוֹ (טוּר בְּשֵׁם אֲבִי הָעֶזְרִי)\u0006, אוֹ שֶׁעָשָׂה לוֹ מִשּׁוּם שִׂנְאָה, כְּגוֹן שֶׁאָנוּ רוֹאִים שֶׁנִּדָּה לְאֶחָד, וַאֲחֵרִים שֶׁעָשׂוּ כְּמוֹתוֹ לֹא נִדָּה \u0005(ת\"ה סי' רע\"ד)\u0006 וְכָל כַּיּוֹצֵא בָּזֶה. \u0010c29\u0011\nמְנֻדֶּה לְעִירוֹ, מְנֻדֶּה לְעִיר אַחֶרֶת. \u0005אֲפִלּוּ גְּדוֹלָה מִמֶּנָּהּ (טוּר)\u0006. מְנֻדֶּה לְעִיר אַחֶרֶת, אֵינוֹ מְנֻדֶּה לְעִירוֹ. \u0005הַגָּה: אֲבָל מְנֻדֶּה לִשְׁאָר \u0010c30\u0011 הָעֲיָרוֹת כַּיּוֹצֵא בְּעִיר שֶׁנִּדּוּהוּ (טוּר)\u0006. בְּנֵי הָעִיר שֶׁעָשׂוּ חֵרֶם עַל כָּל מִי שֶׁיָּבֹא לָדוּר בְּעִירָם, אֵינוֹ חָל עַל הַבָּא לָדוּר שָׁם, אֶלָּא אִם כֵּן יֵשׁ לוֹ רַב בָּעִיר דְּאָז צָרִיךְ לְקַיֵּם נִדּוּי רַבּוֹ. אֲבָל הֵם יְכוֹלִין לְתַקֵּן בֵּינֵיהֶם וְלִגְדֹּר עַל עַצְמָן שֶׁלֹּא יִשְׂאוּ וְיִתְּנוּ עִמּוֹ \u0005(מָרְדְּכַי פֶּרֶק לֹא \u0010c31\u0011 יַחְפֹּר)\u0006.\nמְנֻדֶּה לַנָּשִׂיא, מְנֻדֶּה לְכָל יִשְׂרָאֵל. מְנֻדֶּה לְכָל יִשְׂרָאֵל, אֵינוֹ מְנֻדֶּה לַנָּשִׂיא.\nנָהֲגוּ שֶׁלֹּא לִנְהֹג נִדּוּי בְּעוֹבֵר עַל גְּזֵרַת הַקָּהָל בְּחֵרֶם וְנִדּוּי, עַד שֶׁיַּכְרִיזוּ עָלָיו. \u0005הַגָּה: מִי שֶׁעָבַר עַל גְּזֵרַת רַבֵּנוּ גֵרְשׁוֹם מְאוֹר הַגּוֹלָה, אִם עָבַר בְּשׁוֹגֵג, אֵין צָרִיךְ הַתָּרָה. וְאִם הִתְרוּ בּוֹ וְעָבַר בְּמֵזִיד, כָּל בֵּי עֲשָׂרָה שְׁלוּחֵי רַבֵּנוּ גֵרְשׁוֹם הֵם לְהַתִּיר לוֹ כְּשֶׁחוֹזֵר מִדַּעְתּוֹ, דְּאַמְדִּינָן דַּעַת רַבֵּנוּ גֵרְשׁוֹם שֶׁכָּךְ הָיְתָה דַּעְתּוֹ מִתְּחִלָּה לִנְהֹג בּוֹ נְזִיפָה וְנִדּוּי לְפִי דַּעְתָּם (הַגָּהוֹת מָרְדְּכַי דב\"ק בְּשֵׁם תְּשׁוּבַת רַשִׁ\"י)\u0006. אֲבָל בְּדָבָר שֶׁגָּזַר בְּפֵרוּשׁ שֶׁיְּהֵא בְּנִדּוּי לְעוֹלָם, אָז הוּא בְּנִדּוּי לְעוֹלָם אִם עָבַר בְּמֵזִיד \u0005(ג\"ז שָׁם)\u0006.\nכֵּיצַד \u0010c32\u0011 הַתָּרַת נִדּוּי, אוֹמְרִים לוֹ: שָׁרוּי לְךָ, מָחוּל לְךָ, וְאִם הוּא שֶׁלֹּא בְּפָנָיו, אוֹמְרִים: \u0005(פְּלוֹנִי)\u0006 שָׁרוּי לוֹ.\nמַתִּירִין הַנִּדּוּי בִּשְׁלֹשָׁה הֶדְיוֹטוֹת, אוֹ בְּיָחִיד \u0010c33\u0011 מֻמְחֶה. וְתַלְמִיד מַתִּיר הַחֵרֶם וְהַנִּדּוּי, אֲפִלּוּ בִּמְקוֹם הָרַב. \u0005הַגָּה: וְכָל חֵרֶם וְנִדּוּי שֶׁלֹּא הֻתַּר, אֲפִלּוּ הָיָה זְמַן רַב בְּנִדּוּי וְחָזַר בּוֹ, אֲפִלּוּ הָכֵי אֵינוֹ מֻתָּר עַד שֶׁיַּתִּירוּ לוֹ בְּפֵרוּשׁ (בֵּית יוֹסֵף בְּשֵׁם קוּנְטְרֵס שכ\"כ בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nג' שֶׁנִּדּוּ וְהָלְכוּ לָהֶם, וְחָזַר בּוֹ מֵהַדָּבָר שֶׁנִּדּוּהוּ בִּגְלָלוֹ, מַתִּירִין לוֹ ג' אֲחֵרִים. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁצָּרִיךְ שֶׁיִּהְיוּ \u0010c34\u0011 גְּדוֹלִים כְּמוֹתָם \u0005בְּחָכְמָה וְיִרְאָה וּגְדֻלָּה וְשָׁנִים (כֵּן מַשְׁמָע מֵהַטּוּר)\u0006.\nנִדּוּהוּ ג', אֵין הַשְּׁנַיִם יְכוֹלִין לְהַתִּירוֹ אֶלָּא אִם כֵּן יִתֵּן לָהֶם הַשְּׁלִישִׁי רְשׁוּת. אֲבָל שְׁלָשְׁתָּן מַתִּירִין לוֹ, וְאֲפִלּוּ זֶה שֶׁלֹּא בִּפְנֵי זֶה, אַף עַל פִּי שֶׁהָיוּ בְּיַחַד בִּשְׁעַת הַנִּדּוּי. וְאִם הָיוּ רַבִּים בִּשְׁעַת שֶׁנִּדּוּהוּ, צָרִיךְ שֶׁיַּתִּירוּ כְּלוּם. וְכָל אוֹתָם שֶׁנִּמְלְכוּ בָּהֶם בִּשְׁעַת הַנִּדּוּי, חֲשׁוּבִים מֵהַמְנַדִּים וְצָרִיךְ שֶׁיַּתִּירוּ גַּם \u0010c35\u0011 הֵם.\nנִדּוּהוּ סְתָם, אַף עַל פִּי שֶׁעָבְרוּ עָלָיו ל' יוֹם, לְעוֹלָם עוֹמֵד בְּנִּדּוּיוֹ עַד שֶׁיַּתִּירוּהוּ.\nאִם זִלְזֵל בְּנִדּוּיוֹ וּבְחֶרְמוֹ, צָרִיךְ לִנְהֹג אִסוּר כַּיָּמִים שֶׁנָּהַג הֶתֵּר קֹדֶם שֶׁיַּתִּירוּהוּ.\nנִדּוּהוּ בְּפָנָיו, אֵין מַתִּירִין לוֹ אֶלָּא \u0010c36\u0011 בְּפָנָיו. \u0005וְאִם הִתִּירוּ לוֹ שֶׁלֹּא בְּפָנָיו, יֵשׁ אוֹמְרִים דִּבְדִיעֲבַד הָוֵי הֶתֵּר. (הר\"ן פ\"ק דִּנְדָרִים וְכֵן מַשְׁמָע מִתְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן תש\"ג)\u0006. נִדּוּהוּ שֶׁלֹּא בְּפָנָיו, מַתִּירִין לוֹ אֲפִלּוּ שֶׁלֹּא בְּפָנָיו.\nנִדּוּהוּ עַל תְּנַאי, חָל הַנִּדּוּי, וְצָרִיךְ הַתָּרָה אַף עַל פִּי שֶׁמְּקַיֵּם הַתְּנַאי. וַאֲפִלּוּ אִם נִדָּה אֶת עַצְמוֹ עַל תְּנַאי. וְדַוְקָא שֶׁהַמְנֻדֶּה מְסֻפָּק בִּשְׁעַת הַתְּנַאי אִם יָכוֹל לְקַיְּמוֹ, אֲבָל אִם בָּרוּר לוֹ שֶׁיָּכוֹל לְקַיְּמוֹ, אֵין צָרִיךְ הַתָּרָה.\nאֲפִלּוּ אִם קָבַע זְמַן, שֶׁאָמַר: יְהֵא בְּנִדּוּי, אִם לֹא יַעֲשֶׂה דָּבָר פְּלוֹנִי לִזְמַן פְּלוֹנִי, יְכוֹלִין לְהַתִּירוֹ מִיָּד אַף עַל פִּי שֶׁלֹּא \u0010c37\u0011 הִגִּיעַ הַזְּמַן.\nהַמְנַדֶּה עַצְמוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, \u0010c38\u0011 יֵשׁ אוֹמְרִים שֶׁאֵין לוֹ הַתָּרָה; לָכֵן שׁוֹמֵר נַפְשׁוֹ יִרְחַק מִמֶּנּוּ \u0005וְעַיֵּן לְעֵיל סִימָן רכ\"ח סָעִיף מ\"ה.\u0006\nתַּלְמִיד חָכָם שֶׁנִּדָּה לְעַצְמוֹ, מַתִּיר לְעַצְמוֹ אֲפִלּוּ נִדָּה עַל דַּעַת פְּלוֹנִי, וַאֲפִלּוּ עַל דָּבָר שֶׁחַיָּב עָלָיו נִדּוּי. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הָיָה חַיָּב נִדּוּי אֵינוֹ יָכוֹל לְהַתִּיר לְעַצְמוֹ. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הָיָה דֶּרֶךְ \u0010c39\u0011 שְׁבוּעָה, אֵינוֹ יָכוֹל לְהַתִּיר לְעַצְמוֹ.\nמִי שֶׁאֵינוֹ תַּלְמִיד חָכָם, שֶׁנִּדָּה לְעַצְמוֹ, יֵשׁ מִי שֶׁאוֹמֵר שֶׁצָּרִיךְ \u0010c40\u0011 עֲשָׂרָה שֶׁיַּתִּירוּ לוֹ.\nנִדּוּהוּ בַּחֲלוֹם, הָוֵי נִדּוּי וְצָרִיךְ הַתָּרָה, וְאֲפִלּוּ הִתִּירוּ לוֹ בַּחֲלוֹם אֵינוֹ כְּלוּם. וַאֲפִלּוּ יוֹדֵעַ מִי נִדָּהוּ, אֵינוֹ יָכוֹל לְהַתִּירוֹ וְצָרִיךְ עֲשָׂרָה בְּנֵי אָדָם שֶׁשּׁוֹנִים הֲלָכוֹת לְהַתִּירוֹ. לֹא מָצָא, טוֹרֵחַ אַחֲרֵיהֶם עַד פַּרְסָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁשּׁוֹנִים מִשְׁנָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁיּוֹדְעִים לִקְרוֹת בַּתּוֹרָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁאֵינָם יוֹדְעִים לִקְרוֹת; לֹא מָצָא \u0010c41\u0011 בִּמְקוֹמוֹ עֲשָׂרָה, מַתִּירִין לוֹ אֲפִלּוּ שְׁלֹשָׁה. \u0005וְיֵשׁ אוֹמְרִים דְּאֵין לוֹ הַתָּרָה רַק עַל יְדֵי עֲשָׂרָה שֶׁשָּׁנוּ הֲלָכוֹת אוֹ מִשְׁנָיוֹת (תּוֹסָפוֹת)\u0006, וּמִיהוּ סָגֵי אִם יַתִּירוּ לוֹ בָּזֶה אַחַר זֶה \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nיֵשׁ אוֹמְרִים מִי שֶׁנִּדּוּהוּ בַּחֲלוֹם, וְשָׁלַח שָׁלִיחַ לְהַתִּיר לוֹ שֶׁלֹּא בְּפָנָיו, אִם מָצָא הַשָּׁלִיחַ הַעֲשָׁרָה \u0010c42\u0011 מְכֻנָּסִים, מַתִּירִין לוֹ; וְאִי לֹא, לֹא.\nהַשּׁוֹמֵעַ הַזְכָּרַת הַשֵּׁם מִפִּי חֲבֵרוֹ לַשָּׁוְא, אוֹ שֶׁנִּשְׁבָּע בְּפָנָיו לַשֶּׁקֶר, אוֹ שֶׁבֵּרַךְ בְּרָכָה שֶׁאֵינָהּ צְרִיכָה, חַיָּב לְנַדּוֹתוֹ; וְאִם לֹא נִדָּהוּ, הוּא עַצְמוֹ חַיָּב נִדּוּי, וְצָרִיךְ לְהַתִּיר לוֹ מִיָּד, כְּדֵי שֶׁלֹּא יְהֵא \u0010c43\u0011 מִכְשׁוֹל לַאֲחֵרִים.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה הַנִּשְׁבָּע הַזֶּה, אוֹ הַמְבָרֵךְ לְבַטָּלָה, מֵזִיד. אֲבָל אִם הָיָה שׁוֹגֵג, וְלֹא יָדַע שֶׁזֶּה אָסוּר, אָסוּר לְנַדּוֹתוֹ.\nהַמְנַדֶּה אֶת חֲבֵרוֹ שֶׁלֹּא כַּדִּין, וְאָמַר לֵיהּ הַלָּה: אַדְּרַבָּה, נִדּוּי שֶׁל שֵׁנִי נִדּוּי. וְהָנֵי מִלֵּי, שֶׁזֶּה הַשֵּׁנִי הוּא גַּבְרָא רַבָּא \u0005אַף עַל פִּי שֶׁאֵינוֹ נִסְמָךְ (מהרי\"ק שֹׁרֶשׁ קנ\"ח)\u0006, אוֹ שֶׁאֵינוֹ יָדוּעַ מִי הוּא, דְּחַיְשִׁינָן שֶׁמָּא הוּא יוֹתֵר גָּדוֹל מֵהַמְנַדֶּה. אֲבָל אִם הַמְנַדֶּה שֶׁלֹּא כַּדִּין תַּלְמִיד חָכָם, וְהָאַחֵר אֵינוֹ תַּלְמִיד חָכָם, לֹא. \u0005הַגָּה: וְהוּא הַדִּין תַּלְמִיד נֶגֶד רַבּוֹ לֹא יוּכַל לוֹמַר: אַדְּרַבָּה, אֶלָּא אִם נָטַל רְשׁוּת מִבֵּית דִּין (מהרי\"ק שֹׁרֶשׁ ק\"ע)\u0006. מִי שֶׁאָמַר לַחֲבֵרוֹ: אַל תַּעֲשֶׂה דָּבָר זֶה בְּנִדּוּי, וְזֶה אוֹמֵר לוֹ: אַדְּרַבָּה, אַף עַל פִּי שֶׁעוֹשֶׂה שֶׁלֹּא כַּדִּין, מִכָּל מָקוֹם נִדּוּי הַשֵּׁנִי גַּם כֵּן אֵינוֹ כְּלוּם, הוֹאִיל וְלֹא נִדָּהוּ סְתָם, רַק שֶׁאָמַר לוֹ שֶׁאַל יַעֲשֶׂה הַדָּבָר בְּנִדּוּי \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת ריב\"ש)\u0006.\nתַּלְמִיד חָכָם, שֶׁבִּזָּהוּ רָשָׁע עַד שֶׁנִּדָּהוּ, וְאָמַר לֵיהּ הָרָשָׁע; אַדְּרַבָּה, יַכְרִיזוּ עַל הָרָשָׁע שֶׁהוּא מְנֻדֶּה, וְיַעֲמֹד בְּנִּדּוּיוֹ ל' יוֹם, וְאַחַר כָּךְ יְבַקֵּשׁ מְחִילָה בָּרַבִּים. כָּךְ הוֹרָה הָרֹא\"שׁ.\nאָח גָּדוֹל בְּשָׁנִים שֶׁבִּזָּה לְאָחִיו הַקָּטָן בַּשָּׁנִים וְהוּא תַּלְמִיד חָכָם, וְנִדָּה הַקָּטָן בְּשָׁנִים לַגָּדוֹל בְּשָׁנִים, נִדּוּיוֹ נִדּוּי.\nחָכָם, זָקֵן בְּחָכְמָה, אוֹ אַב בֵּית דִּין שֶׁסָרַח, אֵין מְנַדִּין אוֹתוֹ בְּפַרְהֶסְיָא לְעוֹלָם, אֶלָּא אִם כֵּן עָשָׂה כִּירָבְעָם בֶּן נְבָט וַחֲבֵרָיו. אֲבָל כְּשֶׁחָטָא שְׁאָר חֲטָאוֹת, מַלְקִין אוֹתוֹ בְּצִנְעָא. וְכֵן כָּל תַּלְמִיד חָכָם שֶׁנִּתְחַיֵּב נִדּוּי, אָסוּר לְבֵית דִּין לִקְפֹּץ וּלְנַדּוֹתוֹ בִּמְהֵרָה, אֶלָּא בּוֹרְחִים וְנִשְׁמָטִים מִמֶּנּוּ. וַחֲסִידֵי הַחֲכָמִים הָיוּ מִשְׁתַּבְּחִים שֶׁלֹּא נִמְנוּ מֵעוֹלָם לְנַדּוֹת תַּלְמִיד חָכָם, וְאַף עַל פִּי שֶׁנִּמְנִים לְהַלְקוֹתוֹ אִם נִתְחַיֵּב מַלְקוֹת אוֹ מַכַּת מַרְדוּת. וְאִי סָנֵי שׁוּמְעָנֵיהּ, כְּגוֹן שֶׁמִּתְעַסֵק בְּסִפְרֵי אֶפִּיקוֹרוֹסִין וְשׁוֹתֶה בְּמִינֵי זֶמֶר, אוֹ שֶׁחֲבֵרָיו מִתְבַּיְּשִׁין מִמֶּנּוּ, וְשֵׁם שָׁמַיִם מִתְחַלֵּל עַל יָדוֹ, מְשַׁמְּתִינָן לֵהּ.\nעַל כ\"ד דְּבָרִים מְנַדִּין אֶת הָאָדָם, וְאֵלּוּ הֵן: \u0005(א)\u0006 הַמְבַזֶּה אֶת \u0010c44\u0011 הֶחָכָם, אֲפִלּוּ לְאַחַר מוֹתוֹ. \u0005(ב)\u0006 הַמְבַזֶּה שְׁלִיחַ בֵּית דִּין. \u0005(ג)\u0006 הַקּוֹרֵא לַחֲבֵרוֹ עֶבֶד. \u0005(ד)\u0006 הַמְזַלְזֵל בְּדָבָר אֶחָד מִדִּבְרֵי סוֹפְרִים, וְאֵין צָרִיךְ לוֹמַר מִדִּבְרֵי תּוֹרָה. \u0005(ה)\u0006 מִי שֶׁשָּׁלְחוּ לוֹ בֵּית דִּין וְקָבְעוּ לוֹ זְמַן, וְלֹא בָּא. \u0005(ו)\u0006 מִי שֶׁלֹּא קִבֵּל עָלָיו אֶת הַדִּין, מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. \u0005(ז)\u0006 מִי שֶׁיֵּשׁ בִּרְשׁוּתוֹ דָּבָר הַמַּזִּיק, מְנַדִּין אוֹתוֹ עַד שֶׁיָּסִיר הַנֵּזֶק. \u0005(ח)\u0006 הַמּוֹכֵר קַרְקַע שֶׁלּוֹ לְגוֹי, מְנַדִּין אוֹתוֹ עַד שֶׁיְּקַבֵּל עָלָיו כָּל אֹנֶס שֶׁיָּבֹא מֵהַגּוֹי לְיִשְׂרָאֵל חֲבֵרוֹ בַּעַל הַמֶּצֶר. \u0005(ט)\u0006 הַמֵּעִיד עַל יִשְׂרָאֵל בְּעֶרְכָּאוֹת שֶׁל גּוֹיִים, וְהוֹצִיא מִמֶּנּוּ מָמוֹן בְּעֵדוּתוֹ, שֶׁלֹּא כַּדִּין, מְנַדִּין אוֹתוֹ עַד שֶׁיְּשַׁלֵּם. \u0005(י)\u0006 טַבָּח כֹּהֵן שֶׁאֵינוֹ מַפְרִישׁ הַמַּתָּנוֹת, וְנוֹתְנָם לְכֹהֵן אַחֵר, מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. \u0005(י\"א)\u0006 הַמְחַלֵּל יוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת, אַף עַל פִּי שֶׁהוּא מִנְהָג. \u0005(י\"ב)\u0006 הָעוֹשֶׂה מְלָאכָה בְּעֶרֶב פֶּסַח אַחַר חֲצוֹת. \u0005(י\"ג)\u0006 הַמַּזְכִּיר שֵׁם שָׁמַיִם לְבַטָּלָה, אוֹ לִשְׁבוּעָה בְּדִבְרֵי הֲבַאי. \u0005(י\"ד)\u0006 הַמֵּבִיא אֶת הָרַבִּים לִידֵי אֲכִילַת קָדָשִׁים בַּחוּץ. \u0005(ט\"ו)\u0006 הַמֵּבִיא רַבִּים לִידֵי חִלּוּל הַשֵּׁם. \u0005(ט\"ז)\u0006 \u0010c45\u0011 הַמְחַשֵּׁב שָׁנִים וְקוֹבֵעַ חֳדָשִׁים בְּחוּצָה לָאָרֶץ. \u0005(י\"ז)\u0006 הַמַּכְשִׁיל אֶת הָעִוֵּר. \u0005(י\"ח)\u0006 הַמְעַכֵּב אֶת הָרַבִּים מִלַּעֲשׂוֹת מִצְוָה. \u0005(י\"ט)\u0006 טַבָּח שֶׁיָּצְתָה טְרֵפָה מִתַּחַת יָדוֹ. \u0005(כ)\u0006 טַבָּח שֶׁלֹּא הֶרְאָה בְּדִיקַת סַכִּינוֹ לְחָכָם. \u0005(כ\"א)\u0006 הַמַּקְשֶׁה עַצְמוֹ לָדַעַת. \u0005(כ\"ב)\u0006 הַמְגָרֵשׁ אֶת אִשְׁתּוֹ, וְעָשׂוּ בֵּינוֹ וּבֵינָהּ שֻׁתָּפוּת אוֹ מַשָּׁא וּמַתָּן הַמְּבִיאָן לְהִזָּקֵק זֶה לָזֶה, כְּשֶׁיָּבוֹאוּ לְבֵית דִּין, מְנַדִּין אוֹתָם. \u0005(כ\"ג)\u0006 חָכָם שֶׁשְּׁמוּעָתוֹ רָעָה. \u0005(כ\"ד)\u0006 הַמְנַדֶּה \u0010c46\u0011 לְמִי שֶׁאֵינוֹ חַיָּב נִדּוּי. \u0005הַגָּה: וְאֵין צְרִיכִין לְעִנְיַן נִדּוּי עֵדוּת וּרְאָיָה בְּרוּרָה, אֶלָּא אֹמֶד הַדַּעַת בַּאֲמִתּוּת הַדְּבָרִים, שֶׁהַתּוֹבֵעַ טוֹעֵן בָּרִי וְאָז אֲפִלּוּ אִשָּׁה אֲפִלּוּ קָטָן נֶאֱמָן, אִם הַדַּעַת נוֹתֵן שֶׁאֱמֶת הַדָּבָר (מהרי\"ק שֹׁרֶשׁ ק\"כ)\u0006.\nחָכָם שֶׁהוֹרָה לְהַתִּיר בְּמַיִם שֶׁאֵין לָהֶם סוֹף, חַיָּב נִדּוּי. וְכֵן מִי שֶׁעוֹבֵר עַל נִדְרוֹ, וְכָל בֵּית דִּין שֶׁנִּזְקָק לוֹ \u0010c47\u0011 לִשְׁאֵלָה, בַּר שַׁמְתָּא הוּא. וְכֵן הָעוֹשִׂים מְלָאכָה בְּעוֹד שֶׁיֵּשׁ מֵת בָּעִיר, וַעֲדַיִן לֹא נִקְבַּר, חַיָּבִים נִדּוּי, אֶלָּא אִם כֵּן יֵשׁ חֲבוּרוֹת בָּעִיר. וְכֵן מִי שֶׁעוֹשֶׂה קַלִּים וַחֲמוּרִים, אוֹ גְּזֵרָה שָׁוָה לַעֲקֹר דָּבָר מִן הַתּוֹרָה, אוֹ שׁוֹאֵל דָּבָר שֶׁאִי אֶפְשָׁר. וְכֵן מִי שֶׁיֵּשׁ לוֹ עִרְעוּר עַל חֲבֵרוֹ בְּדָבָר אֶחָד, וּמוֹסֵר אוֹתוֹ לְמֶלֶךְ אוֹ לְשׁוֹפֵט גּוֹי, מְשַׁמְּתִין לֵיהּ עַד דְּמַיְתֵי לֵיהּ וְקַיְימֵי בְּבֵית דִּין. וְכֵן תַּלְמִיד חָכָם הַמַּחֲזִיק בְּמַחֲלֹקֶת כְּנֶגֶד הָרַבִּים. וְכֵן הַמּוֹרֶה הוֹרָאָה בִּמְקוֹם רַבּוֹ.\nצוֹרְבָא מִדְּרַבָּנָן, יָכוֹל לְנַדּוֹת לְמִי שֶׁהִפְקִיר כְּנֶגְדּוֹ. וְאִם דִּינוֹ פָּסוּק, כְּגוֹן שֶׁקְּרָאוֹ: עֶבֶד, הוּא מְנֻדָּה לְכָל יִשְׂרָאֵל; וְאִם אֵין דִּינוֹ פָּסוּק, אֵינוֹ מְנֻדֶּה אֶלָּא לִקְטַנִּים מִמֶּנּוּ. \u0005וַאֲפִלּוּ לֹא בִּזָּהוּ בְּפֵרוּשׁ, רַק שֶׁכִּוֵּן לְבַזּוֹתוֹ לְפִי אֻמְדָּנָא הַמּוּכָח (מהרי\"ק ש\"א)\u0006.\nרְאוּבֵן שֶׁחַיָּב לְשִׁמְעוֹן מָמוֹן, וּמְסָרֵב מִלְּפָרְעוֹ, אִם נִדָּה שִׁמְעוֹן לִרְאוּבֵן שֶׁיִּפְרָעֶנּוּ, \u0010c48\u0011 נִדּוּיוֹ נִדּוּי. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּלֹא עָבִיד אֱינָשׁ דִּינָא לְנַפְשֵׁיהּ לְנַדּוֹת חֲבֵרוֹ עַל דְּבַר מָמוֹן (שָׁם שֹׁרֶשׁ כ\"ה בְּשֵׁם מהר\"מ וְרַאֲבַ\"ד)\u0006, וְכֵן עִקָּר; כָּל שֶׁכֵּן אִם חֲבֵרוֹ אוֹמֵר לִהְיוֹת לוֹ צָיֵת דִּין \u0005(מהרי\"ו סִימָן רכ\"ט)\u0006.\nהַמְבַזֶּה אֶת הֶחָכָם, אֲפִלּוּ בִּדְבָרִים, וַאֲפִלּוּ לְאַחַר מִיתָה, אִם יֵשׁ \u0010c49\u0011 עֵדִים בַּדָּבָר, בֵּית דִּין מְנַדִּין אוֹתוֹ בָּרַבִּים, וְהֵם מַתִּירִין לוֹ כְּשֶׁיַּחֲזֹר בִּתְשׁוּבָה. אֲבָל אִם הֶחָכָם חַי, אֵין מַתִּירִין לוֹ עַד שֶׁיְּרַצֶּה הֶחָכָם שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ. \u0005מִיהוּ אִם עָשָׂה הַמֻּטָּל עָלָיו, וְאֵין הֶחָכָם רוֹצֶה לִמְחֹל, מַתִּירִין לוֹ נִדּוּיוֹ (בֵּית יוֹסֵף)\u0006. וְכֵן הֶחָכָם בְּעַצְמוֹ מְנַדֶּה לִכְבוֹדוֹ לְעַם הָאֶרֶץ שֶׁהִפְקִיר כְּנֶגְדּוֹ, וְאֵין צָרִיךְ לֹא עֵדִים וְלֹא הַתְרָאָה, וְאֵין מַתִּירִין לוֹ עַד שֶׁיְּרַצֶּה הֶחָכָם; וְאִם מֵת הֶחָכָם, בָּאִים שְׁלֹשָׁה וּמַתִּירִין לוֹ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סוֹף סי' רמ\"ג (בהג\"ה)\u0006, אִם דָּנִין בַּזְּמַן הַזֶּה דִּין תַּלְמִיד חָכָם. הַקּוֹרֵא לְחָכָם: מַלְשִׁין, אוֹ מַסוּר, אֵין לְךָ בִּזּוּי גָּדוֹל מִזֶּה, וּמְנַדִּין עַל זֶה \u0005(מהרי\"ק שֹׁרֶשׁ ק\"פ)\u0006.\nאִם נִדּוּ לְאָדָם אֶחָד עַל שֶׁעָבַר עֲבֵרָה, וְגָזַר הַשַּׂר עֹנֶשׁ עַל מִי שֶׁיַּחֲזִיק הַנִּדּוּי, חַיָּבִים לִכָּנֵס בְּסָפֵק עֹנֶשׁ כְּדֵי לְהַחֲזִיק דָּתֵנוּ. אֲבָל אִם נִדּוּהוּ עַל דְּבָרִים שֶׁבֵּינוֹ לַחֲבֵרוֹ, כְּגוֹן שֶׁהוֹלִיכוֹ לְעֶרְכָּאוֹת, אֵין אָנוּ חַיָּבִים לִכָּנֵס בְּסַכָּנַת הָעֹנֶשׁ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סי' רכ\"ח סָעִיף מ\"ז וְגַם בְּסִימָן רל\"ב סָעִיף י\"ב. אַף עַל פִּי שֶׁחַיָּב אָדָם לִמְחוֹת בְּעוֹבְרֵי עֲבֵרָה, וְכָל מִי שֶׁאֵינוֹ מוֹחֶה, וּבְיָדוֹ לִמְחוֹת, נִתְפָּס בְּאוֹתוֹ עָוֹן, מִכָּל מָקוֹם אֵין אָדָם חַיָּב לְהוֹצִיא מָמוֹנוֹ עַל זֶה. וְלָכֵן נָהֲגוּ לְהָקֵל מִלִּמְחוֹת בְּעוֹבְרֵי עֲבֵרָה, שֶׁיֵּשׁ לָחוּשׁ שֶׁיִּהְיוּ עוֹמְדִין עַל גּוּפֵנוּ וּמְאֹדֵנוּ (מהרי\"ו סִימָן קנ\"ז)\u0006.",[],["\u0003לאלתר. \u0004 משמע אפי' בלא התראה מיהו בב\"י משמע דאפי' לדבר איסור לא נהגו לנדות אלא לאחר התראה. ש\"ך:","\u0003משלשים. \u0004 כתב ב\"י בשם הקונטרסים דנ\"מ אם חכם נדהו משום כבודו והלך לו אין מתירין לו עד אחר ל' יום לדידהו ולדידן ז' ימים דכיון דהלך לו מסתמא ניחא ליה שיתירוהו אחר זמן זה עכ\"ל. ור\"ל דאין לפ' דאין ביד הב\"ד למעט הנידוי פחות מל' יום דהא ליתא כדלקמן ס\"ו. ש\"ך:","\u0003לחוש. \u0004 והט\"ז כ' שאין לעשות מעשה כהג\"ה זאת ומביא כמה ראיות והוכחות על זה ע\"ש \u0005(ובנה\"כ כתב דיש לדחות כל ראיותיו כיון דדין ב\"ד הוא שמנדין אותו אין לחוש דאל\"כ בטלה דין ישראל עכ\"ל)\u0006:","\u0003אמותיו. \u0004 כ' הש\"ך וד' אמות אלו הן לכל צד ד' אמות והוא באמצען והן ח' אמות וגם תפסי אפי' בר\"ה או בסמטא ובשדה הפקר אבל לא בבית אחר:","\u0003מזמנין. \u0004 דוקא בנתנדה מחמת עבירה אבל לא שנתנדה מחמת ממון. כ\"כ בתשובת הרשב\"א:","\u0003בפירוש. \u0004 שלא פירשו בנידוי שלא יצרפוהו למנין. ט\"ז:","\u0003להתרחק. \u0004 היינו אותן שבאו לארבע אמותיו אבל אותן שהיו תחלה שם ובא אצלן א\"צ להתרחק כדלקמן בהג\"ה. ש\"ך:","\u0003הסנדל. \u0004 וכ\"פ בא\"ח סי' תקנ\"ד סי\"ז ולקמן סי' שפ\"ב ס\"ד. וכ' הש\"ך ותימה דבב\"י פסק כאן דמותר בנעילת הסנדל וכ\"כ הריב\"ש ס\"ס קע\"ג בשם הרשב\"א והכי נהוג גם א\"צ קריעה ועטיפת ראש וכפיית המטה כאבל ומותר ברחיצה וסיכה ותשמיש המטה ובתפילין ושאלת שלום כן הסכמת רוב הפוסקים. עכ\"ל:","\u0003עומד. \u0004 וצ\"ע אי מהלך תופס ארבע אמות. ש\"ך:","\u0003אבן. \u0004 וא\"צ לעשות עליו גל כגלו של עכן. ש\"ך:","\u0003מספידין. \u0004 אבל כבוד החיים עושים לאבלים עומדים בשורה ומנחמים. הרמב\"ן. וגם לענין קבורה ותכריכי המת הוא כשאר בני אדם ואפי' מוחרם נקבר בקברי אבותיו. תשובת הרשב\"א:","\u0003הספר. \u0004 ומהרש\"ל כתב חלילה לבטלם שהעולם אינו מתקיים אלא בהבל פיהם של תינוקות. גם מ\"ש להוציא אשתו מבהכ\"נ לא נהירא אם הוא חטא היא מה חטאה וכו' וכתב הט\"ז דיש לתמוה עליו יותר דלפי דעתו כ\"ש שהיה לו לתמוה על שלא יקברו לו מתו דמה חטאה הנפש ההיא שתהא מוטלת בבזיון וכמ\"ש הטור סי' שמ\"א דבזיוני דכולי חיי הוא אלא ע\"כ דכל זה לא מיירי רק בבניו הקטנים שאין בהם זכות מצד עצמן עדיין אלא תלויים ועומדים בזכות אביהם אותם יש רשות לעכב הקבורה אבל לא גדולים \u0005(שהם בני קיבולי שכר או עונש מצד עצמן)\u0006 ומזה הטעם יש ג\"כ רשות לגרש בניו הקטנים מבית הספר אבל באשתו ודאי אין שום טעם לבזותה דהיא עולה עמו ואינו יורדת עמו עכ\"ל:","\u0003יראתם. \u0004 וכ' הט\"ז ואם הוא מוסיף ועושה זה החטא פשיטא שאין זה תלוי בזמן וזה נ\"ל פשוט עכ\"ל:","\u0003רשאים. \u0004 כתב הש\"ך אלא לעולם נחשב לו כאילו אותו היום עשה מחדש דצ\"ע הא בזמון ובתפלה בי' בלא\"ה מנודה אסור כדלעיל ס\"ב ולפי מ\"ש לעיל דדוקא בנתנדה מחמת עבירה אינו מצטרף לזימון ולעשרה אבל לא בנתנדה מחמת ממון י\"ל דהמחבר אשמועינן דאף בנתנדה מחמת ממון הרשות ביד ב\"ד לנדות שלא יזמן בג' ולא יתפלל בי' עכ\"ל:","\u0003עבירה. \u0004 ודוקא נתנדה אבל עבר עבירה לחוד אע\"פ שהוא עבריין מצטרף כדלעיל ס\"ב בהג\"ה ובממון אפי' נתנדה מצטרף. ש\"ך:","\u0003עליו. \u0004 כתב הש\"ך ונראה דלצירוף זימון ומנין מ\"מ אסור אם נתנדה מחמת עבירה שהרי אין זה מטעם אבילות דהא אבל עצמו מצטרף לזימון ומנין כדלקמן ס\"ס שע\"ט:","\u0003אומרים. \u0004 ר\"ל כשמנדים אוחו סתם אמרינן שיהא בנידוי ל' יום. ש\"ך:","\u0003וסובר. \u0004 והט\"ז חולק ע\"ז ומאריך בראיותיו ומסיק שדברי רמ\"א כאן שתוך ל' יום לא מועיל חזרה הוא דלא כמאן ולית מאן דחש לה וע\"ש:","\u0003משפטו. \u0004 וכתוב בקונטרסים משמע לי שאסור בתספורת אותו היום דאין למתאנח ועצב לספר ולגלח. עכ\"ל ב\"י:","\u0003זמן. \u0004 היינו ז' לבני א\"י ויום א' לבני בבל כדלעיל בריש הסימן:","\u0003לשאר. \u0004 אפי' הם קטנים ממנו. ב\"י וד\"מ:","\u0003לחכמים. \u0004 והש\"ך מביא הרבה פוסקים דסברי דמנודה לשאר החכמים שהם כמותו כל שאינן גדולים ממנו ולפ\"ז כ\"ש ברב שנידה שמנודה לשאר החכמים מיהו נראה שכ\"ז אם התלמיד הוא ת\"ח שראוי לנדות לכבודו וכדלקמן סי\"ח עכ\"ל:","\u0003אפקירותא. \u0004 הוא מן התלמיד והתלמיד עצמו צריך נידוי:","\u0003לקיים. \u0004 וכ\"כ הרב לעיל ס\"ס רכ\"ח לענין גזירת הקהל:","\u0003בפניו. \u0004 אע\"פ שאינו בפני רבו:","\u0003לרב. \u0004 וה\"ה לגדול מן התלמיד בחכמה. הריב\"ש. ונראה דאפי' אותו גדול הוא התלמיד של אותו הרב שנידוהו לכבודו מ\"מ כיון דאינו מנודה לרב אינו חייב לנהוג בו נידוי עכ\"ל הש\"ך:","\u0003מחרימין. \u0004 מיהו היינו דוקא יחיד אבל ב\"ד פשיטא שיכולים להחרים. ש\"ך:","\u0003שיעשה. \u0004 פי' שכבר נידהו הרב ובא זה המנודה ומבטיחו לפייסו לא מהני עד שיעשה הפיוס \u0005(משא\"כ במבטיחו קודם הנידוי לא ינדה אע\"פ שעדיין לא עשה)\u0006. ט\"ז. וע\"ל סי' רמ\"ג ס\"ח אם ת\"ח בזה\"ז יכול לנדות לעצמו:","\u0003נתכוין. \u0004 ובהג\"מ בשם הרמ\"ך פי' דהיינו כשלא ביזהו כלל אלא שאינו מכבדו כמו שהוא חייב לכבדו בקימה והידור אין נידויו נידוי. ומהרי\"ק בשם מהר\"מ פי' דמיירי שנידה אותו בשביל שמעכב ממונו שלא כדין אף ע\"פ שכהלכה נידהו אין נידויו נידוי וכ\"כ הרא\"ש בתשו' עכ\"ל הש\"ך:","\u0003לעירו. \u0004 כתב הש\"ך דהב\"ח פירש דהיינו במנודה מחמת כבוד דאפקיר כנגדם אע\"פ שלא הפקיר בבי דינא אבל במנודה לב\"ד מחמת דלא ציית דינא או באפקירותא דב\"ד לדבר עבירה דינו שוה בין לעירו ובין לעיר אחרת דלכל ישראל הוא מנודה וחייבים לנהוג בו נידוי וכ\"פ הלבוש עכ\"ל:","\u0003כיוצא. \u0004 אבל לא לעדיפי מינה כמ\"ש ב\"י:","\u0003לנשיא. \u0004 שנידהו לכבודו:","\u0003התרת. \u0004 כתב הט\"ז דמי שהוא בחרם ומתירין לו יכריז השמש שאינו בחרם עוד משום חשדא שמא לא ישמע אחד הפטור מהחרם וכשיראה שאין נוהגים בו דין מוחרם יזלזל בנידוי וחרם ולא יחוש אח\"כ לגזרת חכמים:","\u0003מומחה. \u0004 כתב הש\"ך נראה דהאידנא ליכא יחיד מומחה כמו לענין נדרים לעיל ר\"ס רכ\"ח. אבל מדברי הב\"ח משמע דאף בזה\"ז מותר ביחיד מומחה וצריך לחלק דהתם בעינן גמיר וסביר בדיני נדרים משא\"כ הכא עכ\"ל:","\u0003גדולים. \u0004 כתב הראב\"ד והיינו כשבאין להתיר תוך זמן הנדר אבל כשישלים הזמן כל ג' או יחיד מומחה מתירין לו. א\"נ כשנידהו יחיד אפי' אינו מומחה על דבר עבירה כשישלים לו הזמן מתירין לו כל ג' או יחיד מומחה אבל נידוהו רבים צריכים רבים כמותן להתירו עכ\"ל:","\u0003הם. \u0004 או בני אדם כנגדם חשובים כמותם. וכ' הטור בשם הראב\"ד אם נידוהו ואינו יודע מי נידהו אין אחרים יכולים להתירו אלא הנשיא:","\u0003בפניו. \u0004 הטעם כ' הר\"ן משום חשדא שלא יזלזל הוא בעצמו בגזרת חכמים כמ\"ש בס\"ק ל\"ג ע\"ש וכ' הש\"ך דלפ\"ז כל שהודיעוהו דליכא חשדא מתירין לו שלא בפניו אפי' לכתחילה מיהו מדברי הרא\"ש משמע דלכתחלה לכ\"ע אין להתיר לו שלא בפניו אפי' ע\"י שיודיעוהו עכ\"ל:","\u0003הגיע. \u0004 וכתב הש\"ך דבב\"י משמע אפי' אם נידוהו אחרים דינא הכי ותימה דלעיל סי' רכ\"ח סי\"ז פסקו המחבר והלבוש והב\"ח דה\"ה דהמנדה עצמו על תנאי שאין מתירין לו עד שיחול כמו נדר ולענין הלכה נראה עיקר וכ\"פ הט\"ז. וכתב הש\"ך דנראה מדברי הריב\"ש שלא נאמר זה אלא ביחיד הנודר אבל בחרמי תקנות הקהל לא והוי כאלו התנו כן בפירוש בשעת הנדר והחרם וכ\"נ עיקר עכ\"ל:","\u0003שאין. \u0004 שכיון שנידה עצמו בעה\"ב הכניס עצמו בנידוי שלמעלה ומי יתירנו לו. ש\"ך:","\u0003שבועה. \u0004 שאמר אני נשבע להיות בנידוי אם אעשה דבר פלוני. ב\"י ופרישה:","\u0003עשרה. \u0004 כתב הש\"ך דמדברי הב\"ח נראה דה\"ה לעיל סל\"ג בת\"ח דאינו יכול להתיר לעצמו צריך י' שיתירו לו וע\"ש עכ\"ל:","\u0003במקומו. \u0004 כתב הט\"ז בזה א\"צ לטרוח עד פרסה שאין להם מעלה גדולה כ\"כ יתר על ג' כנ\"ל עכ\"ל. וכתב הר\"ן צ\"ע במי שנידוהו בחלומו אם צריך לנהוג בכל דיני המנודה ומסתימת דברי הפוסקים משמע דשוה למנודה בכל דבר. ש\"ך:","\u0003מכונסים. \u0004 דהוי כנידוהו בפניו שאין מתירין לו אלא בפניו רק דאם מצאם מכונסים אמרינן דמסתייע מילתא והוי כבפניו אבל ע\"י מנודה עצמו ודאי מועיל אפילו ע\"י חיזור בני אדם. תוספות:","\u0003מכשול. \u0004 שאחרים אינם יודעים שנידה את זה:","\u0003החכם. \u0004 והוא שראוי להורות ויגע בתורה. ב\"י בשם הקונטרסים:","\u0003המחשב. \u0004 כ' הש\"ך נראה דהיינו דוקא כשמחשב וקובע ע\"פ שהיו רגילים לקבוע בא\"י בזמן שהיה ב\"ה קיים אבל לחשב בתקופות ומזלות כמו שנהגו האידנא אדרבה מצוה היא כדאמרי' כל היודע לחשב תקופות ומזלות ואינו חושב עליו הכתוב אומר ואת פועל ה' לא יביטו וגו':","\u0003למי. \u0004 ובא לב\"ד להתרעם עליו שנידהו שלא כדין ב\"ד מנדין אותו כ\"כ הלבוש ומשמע דכל שלא בא לב\"ד לקבול עליו אין ב\"ד נזקקין לנדותו. ובכסף משנה כתב בשם הרשב\"ץ בתשובה דהכא מיירי במי שרגיל בכך שב\"ד נזקקין לנדותו ומשמע דברגיל אפי' אינו קובל עליו הב\"ד נזקקין לנדותו עכ\"ל הש\"ך:","\u0003לשאלה. \u0004 וע\"ל סי' רכ\"ח ס\"כ וסי' רל\"ח ס\"כ וצ\"ע דנראין דברי המחבר כסתרי אהדדי וע\"ש וק\"ל ונ\"ל לתרץ דמ\"ש המחבר כאן שכל ב\"ד שנזקק לשאלה בר שמתא הוא איירי בדבר שעדיין לא נהג איסור כימים שנהג בהם היתר כדלעיל סי' ר\"ח וכן הוא בש\"ס. אבל אח\"כ אע\"פ שעבר במזיד נשאל עליו. וכל זה בדבר ששייך לנהוג איסור וכו' אבל בדבר שאינו שייך כגון שנשבע שלא יאכל ככר ועבר ואכל מתירין לו מיד ומזה מיירי בסימן רכ\"ח ורל\"ח וכן מבואר חילוק זה להדיא בסימן ר\"ח ס\"ה ע\"ש:","\u0003נידוי. \u0004 אפי' אין שמעון ת\"ח. ודוקא אם מסרב אבל אם דוחהו איזה דחיה כגון אין לי מעות עכשיו וכה\"ג לא הוי נידוי. מהרי\"ק. וכן כשכופהו לצורך המס ולא נתחייב לגמרי אין נידויו נידוי. כ\"כ בהגהת אשר\"י:","\u0003עדים. \u0004 ולפעמים א\"צ עדים כשרים אלא אפילו אשה או קטן או קרובים נאמנים בדבר של קטטות. כ\"כ מהרי\"ק וכן כתב הרב בח\"מ ס\"ס ל\"ז עכ\"ל הש\"ך:"]],["\u0003הלכות ביקור חולים ורפואה ונוטה למות וגוסס\u0004\nמִצְוָה לְבַקֵּר חוֹלִים. הַקְּרוֹבִים וְהַחֲבֵרִים נִכְנָסִים מִיָּד; וְהָרְחוֹקִים, אַחַר ג' \u0010c0\u0011 יָמִים. וְאִם קָפַץ עָלָיו הַחֹלִי, אֵלּוּ וָאֵלּוּ נִכְנָסִים מִיָּד. \u0005(טוּר בְּקִצוּר מס' ת\"ה לְהָרַמְבַּ\"ן)\u0006.\nאֲפִלּוּ הַגָּדוֹל יֵלֵךְ לְבַקֵּר הַקָּטָן, וַאֲפִלּוּ כַּמָּה פְּעָמִים בַּיּוֹם, וַאֲפִלּוּ בֶּן גִּילוֹ. וְכָל הַמּוֹסִיף הֲרֵי זֶה מְשֻׁבָּח, וּבִלְבַד שֶׁלֹּא יַטְרִיחַ לוֹ. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּשׂוֹנֵא יָכוֹל לֵילֵךְ לְבַקֵּר חוֹלֶה (מהרי\"ל קצ\"ז)\u0006, וְלֹא נִרְאֶה לִי, אֶלָּא לֹא יְבַקֵּר חוֹלֶה, וְלֹא יְנַחֵם הָאָבֵל שֶׁהוּא שׂוֹנְאוֹ, שֶׁלֹּא יַחֲשֹׁב שֶׁשָּׂמֵחַ לְאֵידוֹ, וְאֵינוֹ לוֹ אֶלָּא צַעַר, כֵּן נִרְאֶה לִי \u0005(ש\"ס פ' כ\"ג)\u0006.\nהַמְבַקֵּר אֶת הַחוֹלֶה, לֹא יֵשֵׁב עַל גַּבֵּי מִטָּה, וְלֹא עַל גַּבֵּי כִּסֵא, וְלֹא עַל גַּבֵּי סַפְסָל, אֶלָּא מִתְעַטֵּף וְיוֹשֵׁב לְפָנָיו, שֶׁהַשְּׁכִינָה לְמַעְלָה מֵרַאֲשׁוֹתָיו. \u0005הַגָּה: וְדַוְקָא כְּשֶׁהַחוֹלֶה שׁוֹכֵב עַל הָאָרֶץ, דְּהַיּוֹשֵׁב גָּבוֹהַּ מִמֶּנּוּ, אֲבָל כְּשֶׁשּׁוֹכֵב עַל הַמִּטָּה מֻתָּר לֵישֵׁב עַל כִּסֵּא וְסַפְסָל (בֵּית יוֹסֵף בְּשֵׁם הר\"ן, וְכֵן נוֹהֲגִין)\u0006.\nאֵין מְבַקְּרִין הַחוֹלֶה בְּג' שָׁעוֹת רִאשׁוֹנוֹת שֶׁל יוֹם, מִפְּנֵי שֶׁכָּל חוֹלֶה, מֵקֵל עָלָיו חָלְיוֹ בַּבֹּקֶר, וְלֹא יָחוּשׁ לְבַקֵּשׁ עָלָיו רַחֲמִים. וְלֹא בְּג' שָׁעוֹת אַחֲרוֹנוֹת שֶׁל יוֹם, שֶׁאָז מַכְבִּיד עָלָיו חָלְיוֹ, וְיִתְיָאֵשׁ מִלְּבַקֵּשׁ עָלָיו רַחֲמִים. \u0005וְכָל שֶׁבִּקֵּר וְלֹא בִּקֵּשׁ עָלָיו רַחֲמִים, לֹא קִיֵּם הַמִּצְוָה (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006.\nכְּשֶׁמְּבַקֵּשׁ עָלָיו רַחֲמִים, אִם מְבַקֵּשׁ לְפָנָיו, יָכוֹל לְבַקֵּשׁ בְּכָל לָשׁוֹן שֶׁיִּרְצֶה. וְאִם מְבַקֵּשׁ שֶׁלֹּא בְּפָנָיו, לֹא יְבַקֵּשׁ אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ.\nיִכְלֹל אוֹתוֹ בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל, שֶׁיֹּאמַר: הַמָּקוֹם יְרַחֵם עָלֶיךָ בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל. וּבְשַׁבָּת אוֹמֵר: שַׁבָּת הִיא מִלִּזְעֹק, וּרְפוּאָה קְרוֹבָה \u0010c1\u0011 לָבוֹא.\nאוֹמְרִים לוֹ שֶׁיִּתֵּן דַּעְתּוֹ עַל עִנְיָנָיו, אִם הִלְוָה אוֹ הִפְקִיד אֵצֶל אֲחֵרִים, אוֹ אֲחֵרִים הִלְווּ אוֹ הִפְקִידוּ אֶצְלוֹ, וְאַל יִפְחַד מִפְּנֵי זֶה מֵהַמָּוֶת.\nאֵין מְבַקְּרִין לֹא לְחֹלִי מֵעַיִם וְלֹא לְחֹלִי הָעַיִן וְלֹא לְחֹלִי הָרֹאשׁ. וְכֵן כָּל חֹלִי דְּתָקִיף לֵיהּ עָלְמָא וְקָשֶׁה לֵיהּ דִּבּוּרָא אֵין מְבַקְּרִין אוֹתוֹ בְּפָנָיו, אֶלָּא נִכְנָסִין בַּבַּיִת הַחִיצוֹן וְשׁוֹאֲלִין וְדוֹרְשִׁין בּוֹ אִם צְרִיכִין לְכַבֵּד וְלִרְבֹּץ לְפָנָיו, וְכַיּוֹצֵא בוֹ, וְשׁוֹמְעִין צַעֲרוֹ וּמְבַקְּשִׁים עָלָיו רַחֲמִים.\nמְבַקְּרִין חוֹלֵי עוֹבְדֵי כּוֹכָבִים, מִפְּנֵי דַּרְכֵי שָׁלוֹם.\nבְּחוֹלֵי מֵעַיִם אֵין הָאִישׁ מְשַׁמֵּשׁ אֶת הָאִשָּׁה, אֲבָל הָאִשָּׁה מְשַׁמֶּשֶׁת אֶת הָאִישׁ. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁמִּי שֶׁיֵּשׁ לוֹ חוֹלֶה בְּבֵיתוֹ, יֵלֵךְ אֵצֶל חָכָם שֶׁבָּעִיר שֶׁיְּבַקֵּשׁ עָלָיו רַחֲמִים (נ\"י פֶּרֶק י\"נ)\u0006, וְכֶן נָהֲגוּ לְבָרֵךְ חוֹלִים בְּבֵית הַכְּנֶסֶת, לִקְרֹא לָהֶם שֵׁם חָדָשׁ, כִּי שִׁנּוּי הַשֵּׁם קוֹרֵעַ גְּזַר דִּינוֹ. נִחוּם אֲבֵלִים, קוֹדֵם לְבִקּוּר חוֹלִים \u0005(כָּל בּוֹ)\u0006.",[],["\u0003ימים. \u0004 פירש הב\"ח הטעם כי היכי דלא ליתרע מזליה להטיל עליו שם חולה \u0005(כדאיתא בנדרים דף מ')\u0006 אבל קרובים וחברים שנכנסים תמיד בביתו ליכא הרגשה כ\"כ ומ\"ה כשקפץ עליו החולי נכנסים גם הרחוקים מיד:","\u0003לבא. \u0004 ובא\"ח סימן רפ\"ז מסיים המחבר ורחמיו מרובים ושבתו בשלום וכ\"פ הב\"ח ע\"ש:"]],["נָתְנָה הַתּוֹרָה רְשׁוּת לָרוֹפֵא לְרַפְּאוֹת. וּמִצְוָה הִיא. וּבִכְלַל פִּקּוּחַ נֶפֶשׁ הוּא. וְאִם מוֹנֵעַ עַצְמוֹ, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים, וַאֲפִלּוּ יֵשׁ לוֹ מִי שֶׁיְּרַפְּאֶנּוּ, שֶׁלֹּא מִן הַכֹּל אָדָם זוֹכֶה לִהִתְרַפְּאוֹת. וּמִיהוּ לֹא יִתְעַסֵק בִּרְפוּאָה אֶלָּא אִם כֵּן הוּא בָּקִי, וְלֹא יְהֵא שָׁם גָּדוֹל מִמֶּנּוּ, שֶׁאִם לֹא כֵן, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים. וְאִם רִפֵּא שֶׁלֹּא בִּרְשׁוּת בֵּית דִּין, חַיָּב בְּתַשְׁלוּמִין, אֲפִלּוּ אִם הוּא בָּקִי. וְאִם רִפֵּא בִּרְשׁוּת \u0010c0\u0011 בֵּית דִּין, וְטָעָה וְהִזִּיק, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. וְאִם הֵמִית, וְנוֹדַע לוֹ שֶׁשָּׁגַג, \u0010c1\u0011 גּוֹלֶה עַל יָדוֹ.\nהָרוֹפֵא, אָסוּר לִטֹּל שְׂכַר הַחָכְמָה \u0010c2\u0011 וְלִמּוּד, אֲבָל שְׂכַר הַטֹּרַח וְהַבַּטָּלָה, מֻתָּר.\nמִי שֶׁיֵּשׁ לוֹ סַמָּנִים, וַחֲבֵרוֹ חוֹלֶה וְצָרִיךְ לָהֶם, אָסוּר לוֹ לְהַעֲלוֹת בִּדְמֵיהֶם יוֹתֵר מִן הָרָאוּי. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ פָּסְקוּ לוֹ בִּדְמֵיהֶם הַרְבֵּה, מִפְּנֵי צֹרֶךְ הַשָּׁעָה שֶׁלֹּא מָצְאוּ סַמָּנִין אֶלָּא בְּיָדוֹ, אֵין לוֹ אֶלָּא דְּמֵיהֶן. אֲבָל אִם הִתְנָה בִּשְׂכַר הָרוֹפֵא הַרְבֵּה, חַיָּב לִתֵּן לוֹ, שֶׁחָכְמָתוֹ מָכַר לוֹ וְאֵין לוֹ דָּמִים. \u0005הַגָּה: וְאַף עַל פִּי שֶׁיֵּשׁ מִצְוָה עָלָיו לְרַפְּאוֹתוֹ; שֶׁכָּל מִצְוֹת עֲשֵׂה דְּרַמְיָא אַכֻּלֵּי עָלְמָא, אִם נִזְדַּמְּנָה לְאֶחָד וְלֹא רָצָה לְקַיְּמָהּ אֶלָּא בְּמָמוֹן, אֵין מוֹצִיאִין הַמָּמוֹן מִיָּדוֹ, וְלֹא מַפְקִיעִין מִיָּדוֹ חִיּוּב \u0010c3\u0011 שֶׁלָּהֶן (טוּר)\u0006.",[],["\u0003וטעה. \u0004 אבל אם הזיק במזיד אפי' ריפא ברשות בית דין חייב בדיני אדם. ש\"ך:","\u0003גולה. \u0004 כתב הש\"ך מ\"מ א\"צ למנוע בשביל חשש טעות ומצוה היא:","\u0003והלימוד. \u0004 כלומר שלומד הרופא לחולה או להמתעסק עמו שיעשה לרפואתו כך וכך מזה אסור ליקח שכר דאבדת גופו היא ורחמנא אמר והשבותו לו לרבות אבדת גופו. ש\"ך:","\u0003שלהן. \u0004 והב\"ח כתב דצ\"ל חיוב שלו ה\"פ ל\"מ שאם כבר קבל הרופא שכר שקצבו לו שאין מוציאין מידו אלא אפי' לא קבל כלום אלא שקצבו ונתחייבו לו בכך ובכך צריכין לשלם כל מה שנתחייבו לו. וכתב הט\"ז ואע\"ג דבבורח מבית האסורים והיתה מעברות לפניו ואמר ליה העבירני ואתן לך דינר אין צריך ליתן לו אלא שכרו כמו שכתב בח\"מ סי' רס\"ד שאני התם דיש קצבה לאותה פעולה מה שאין כן בחכמת הרפואה שאין לה שיעור ומתחלה לא היה חיוב עליו ללמד זה ע\"כ מהני תנאי דוקא בזה. עכ\"ל:"]],["חוֹלֶה שֶׁמֵּת לוֹ מֵת, אֵין \u0010c0\u0011 מוֹדִיעִין אוֹתוֹ, שֶׁמָּא תִּטָּרֵף דַּעְתּוֹ עָלָיו. וְאֵין קוֹרְעִין חֲלוּקוֹ, וְאֵין בּוֹכִין, וְאֵין \u0010c1\u0011 מַסְפִּידִין בְּפָנָיו, שֶׁלֹּא יִשָּׁבֵר לִבּוֹ; וּמַשְׁתִּיקִין אֶת הַמְנַחֲמִין מִפָּנָיו.",[],["\u0003מודיעין. \u0004 ואפי' נודע לו אין מצווים לו לקרוע שמא תגדל דאגתו כ\"כ הב\"ח בשם הר\"ן:","\u0003מספידין. \u0004 אפי' על מת שאינו קרובו של חולה דכיון שרואה החולה שזה הפלוני מת ובוכין ומספידין עליו בפניו נשבר לבו מפחדו שמא ימות גם הוא עכ\"ל הש\"ך בשם הב\"ח:"]],["\u0010c0\u0011 נָטָה לָמוּת, אוֹמְרִים לוֹ: הִתְוַדֶּה, וְאוֹמְרִים לוֹ: הַרְבֵּה הִתְוַדּוּ וְלֹא מֵתוּ, וְהַרְבֵּה שֶׁלֹּא הִתְוַדּוּ, מֵתוּ, וּבְשָׂכָר שֶׁאַתָּה מִתְוַדֶּה אַתָּה חַי, וְכָל הַמִּתְוַדֶּה יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְאִם אֵינוֹ יָכוֹל לְהִתְוַדּוֹת בְּפִיו, יִתְוַדֶּה בְּלִבּוֹ. \u0005וְאִם אֵינוֹ יוֹדֵעַ לְהִתְוַדּוֹת, אוֹמְרִים לוֹ: אֱמֹר: מִיתָתִי תְּהֵא כַּפָּרָה עַל כָּל עֲוֹנוֹתַי (טוּר)\u0006. וְכָל אֵלּוּ הַדְּבָרִים אֵין אוֹמְרִין לוֹ בִּפְנֵי עַמֵּי הָאָרֶץ, וְלֹא בִּפְנֵי נָשִׁים, וְלֹא בִּפְנֵי קְטַנִּים, שֶׁמָּא יִבְכּוּ וְיִשְׁבְּרוּ לִבּוֹ.\nסֵדֶר וִדּוּי שְׁכִיב מֵרַע: מוֹדֶה אֲנִי לְפָנֶיךָ ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי שֶׁרְפוּאָתִי וּמִיתָתִי בְּיָדְךָ, יְהִי רָצוֹן מִלְּפָנֶיךָ שֶׁתְּרַפְּאֵנִי רְפוּאָה שְׁלֵמָה, וְאִם אָמוּת, תְּהֵא מִיתָתִי כַּפָּרָה עַל כָּל חֲטָאִים וַעֲוֹנוֹת וּפְשָׁעִים, שֶׁחָטָאתִי וְשֶׁעָוִיתִי וְשֶׁפָּשַׁעְתִּי לְפָנֶיךָ, וְתֵן חֶלְקִי בְּגַן עֵדֶן, וְזַכֵּנִי לָעוֹלָם הַבָּא הַצָּפוֹן לַצַּדִּיקִים. \u0005וְאִם רוֹצֶה לְהַאֲרִיךְ כְּוִדּוּי יוֹם כִּפּוּר, הָרְשׁות בְּיָדוֹ (כָּל בּוֹ)\u0006.",[],["\u0003נטה. \u0004 כתב הב\"ח ומשמע דוקא בנטה למות אבל בלא נטה למות אין אומרים לו התודה דאע\"פ שאומרים לו הרבה הולכים בשוק וכו' מ\"מ כשאומרים לו שכן דרך כל המומתים מתודים ידע שמסוכן הוא דאל\"כ לא היו מזכירין מיתתו בפניו וישבר לבו עכ\"ל. ונראה מדבריו שלשון זה אומרים להחולה שכן דרך וכו' אבל הפרישה כתב דהאי שכן דרך כל המומתין מתודים הוא לשון הטור ולא שיאמרו כך להחולה וא\"כ אפי' בנטה למות אין אומרים לו כך ומ\"מ נראה דבלא נטה למות א\"א לו התודה דיחשוב שמסוכן הוא. ועוד הרי עדיין יש לו שהות שיוכל להתודות אבל בנטה למות יש לחוש שימות פתאום בלא וידוי עכ\"ל הש\"ך:"]],["הַגּוֹסֵס, הֲרֵי הוּא כְּחַי לְכָל \u0010c0\u0011 דְּבָרָיו. אֵין קוֹשְׁרִין לְחָיָיו, וְאֵין סָכִין אוֹתוֹ, וְאֵין מְדִיחִין אוֹתוֹ, וְאֵין פּוֹקְקִין אֶת נְקָבָיו, וְאֵין שׁוֹמְטִין הַכַּר מִתַּחְתָּיו, וְאֵין נוֹתְנִין אוֹתוֹ עַל גַּבֵּי חוֹל, וְלֹא עַל גַּבֵּי חַרְסִית וְלֹא עַל גַּבֵּי אֲדָמָה, וְאֵין נוֹתְנִין עַל כְּרֵסוֹ, לֹא קְעָרָה, וְלֹא מַגְרֵפָה, וְלֹא צְלוֹחִית שֶׁל מַיִם, וְלֹא גַּרְגִּיר שֶׁל מֶלַח, וְאֵין מַשְׁמִיעִין עָלָיו עֲיָרוֹת, וְאֵין שׂוֹכְרִין חֲלִילִין וּמְקוֹנְנוֹת, וְאֵין מְעַמְּצִין עֵינָיו עַד שֶׁתֵּצֵא נַפְשׁוֹ. וְכָל הַמְּעַמֵּץ עִם יְצִיאַת \u0010c1\u0011 הַנֶּפֶשׁ, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים. וְאֵין קוֹרְעִין, וְלֹא חוֹלְצִין, וְלֹא מַסְפִּידִין עָלָיו, וְלֹא מַכְנִיסִין עִמּוֹ אָרוֹן לַבַּיִת, עַד שֶׁיָּמוּת. וְאֵין פּוֹתְחִין עָלָיו בְּצִדּוּק הדִּין, עַד שֶׁתֵּצֵא נַפְשׁוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין חוֹצְבִין לוֹ \u0010c2\u0011 קֶבֶר אַף עַל פִּי שֶׁאֵינוֹ עִמּוֹ בַּבַּיִת, עַד אַחַר שֶׁיָּמוּת (ריב\"ש סִימָן קי\"ד)\u0006. אָסוּר לַחֲצֹב שׁוּם קֶבֶר לִהְיוֹת פָּתוּחַ עַד לְמָחָר שֶׁלֹּא יִקְבְּרוּ בּוֹ הַמֵּת בְּאוֹתוֹ הַיּוֹם, וְיֵשׁ סַכָּנָה בַּדָּבָר \u0005(רַבֵּנוּ יְרוּחָם בְּשֵׁם הר\"י הֶחָסִיד זַ\"ל)\u0006. וְכֵן אָסוּר לִגְרֹם לַמֵּת שֶׁיָּמוּת מְהֵרָה, כְּגוֹן מִי שֶׁהוּא גּוֹסֵס זְמַן אָרֹךְ וְלֹא יוּכַל לְהִפָּרֵד, אָסוּר לְהִשָּׁמֵט הַכַּר וְהַכֶּסֶת מִתַּחְתָּיו, מִכֹּחַ שֶׁאוֹמְרִין שֶׁיֵּשׁ נוֹצוֹת מִקְצָת עוֹפוֹת שֶׁגּוֹרְמִים זֶה וְכֵן לֹא יְזִיזֶנּוּ מִמְּקוֹמוֹ. וְכֵן אָסוּר לָשׂוּם מַפְתְּחוֹת ב\"ה תַּחַת רֹאשׁוֹ, כְּדֵי שֶׁיִּפָּרֵד. אֲבָל אִם יֵשׁ שָׁם דָּבָר שֶׁגּוֹרֵם עִכּוּב יְצִיאַת הַנֶּפֶשׁ, כְּגוֹן שֶׁיֵּשׁ סָמוּךְ לְאוֹתוֹ בַּיִת קוֹל דּוֹפֵק, כְּגוֹן חוֹטֵב עֵצִים, אוֹ שֶׁיֵּשׁ \u0010c3\u0011 מֶלַח עַל לְשׁוֹנוֹ וְאֵלּוּ מְעַכְּבִים יְצִיאַת הַנֶּפֶשׁ, מֻתָּר לַהֲסִירוֹ מִשָּׁם, דְּאֵין בָּזֶה מַעֲשֶׂה כְּלָל, אֶלָּא שֶׁמֵּסִיר הַמּוֹנֵעַ \u0005(הַכֹּל בְּהַגָּהַת אַלְפָסִי פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006.\nמִי שֶׁאָמְרוּ לוֹ: רָאִינוּ קְרוֹבְךָ גּוֹסֵס הַיּוֹם שְׁלֹשָׁה יָמִים, צָרִיךְ לְהִתְאַבֵּל עָלָיו. \u0005דְּוַדַּאי כְּבָר מֵת.\u0006\nאוֹמְרִים צִדּוּק הַדִּין עִם יְצִיאַת נְשָׁמָה, וּכְשֶׁמַּגִּיעַ לְדַיַּן אֱמֶת, קוֹרֵעַ הָאָבֵל.\nכֵּיוָן שֶׁנָּטָה אָדָם לָמוּת, אֵין רַשָּׁאִין לִפָּרֵד מִמֶּנּוּ, כְּדֵי שֶׁלֹּא תֵּצֵא נַפְשׁוֹ וְהוּא יְחִידִי. \u0005וּמִצְוָה לַעֲמֹד עַל הָאָדָם יְצִיאַת נְשָׁמָה, שֶׁנֶּאֱמַר: וִיחִי עוֹד לָנֶצַח לֹא יִרְאֶה הַשָּׁחַת, כִּי יִרְאֶה חֲכָמִים יָמוּתוּ וְגו' (תְּהִלִּים מ\"ט, יא)\u0006 \u0005(הַגָּהוֹת אַלְפָסִי שָׁם)\u0006.\nמִנְהָג \u0010c4\u0011 לִשְׁפֹּךְ כָּל הַמַּיִם שְׁאוּבִים שֶׁבִּשְׁכוּנַת הַמֵּת.",[],["\u0003דבריו. \u0004 כתב הר\"ן פי' ליתן גט ולמתנה וכהן רשאי ליכנס לבית שהוא עומד בו ואף ע\"פ שרוב גוססים למיתה עכ\"ל: ולקמן סי' ש\"ע יתבאר דאסור ליכנס לבית שיש בו גוסס ע\"ש. ש\"ך. וכל מה דחשב כאן שאין עושין לגוסס הטעם דאין מקרבין מיתתו וכל אלו הם קירוב מיתה. ט\"ז:","\u0003הנפש. \u0004 אלא ישהה מעט שמא נתעלף. הרמב\"ם \u0005(ובמס' שמחות מסיים למה הדבר דומה לנר המטפטף כיון שנוגע בו האדם מיד נכבה)\u0006:","\u0003קבר. \u0004 והב\"ח כתב דמותר מדינא כל שאין החולה מרגיש בדבר מיהו צריך ליזהר בערב שבת סמוך לשבת שמא לא יספיקו לקברו אם לא בחלול שבת ואם לא יקברוהו א\"כ יצטרכו להניחו פתוח הלכך לא שרינן להו אא\"כ משערינן שאם ימות סמוך לשבת ממש ולא יהא אפשר לקברו שעל כל פנים יספיק לחזור ולמלאות החפירה בריוח קודם שיכנס שבת עכ\"ל. ועיין בא\"ח סי' תקמ\"ו סי\"א:","\u0003מלח. \u0004 כתב הט\"ז וקשה לי מה שהתירו בהסרת המלח דהלא ע\"י זה מזיז את פיו. ע\"כ נראה שאין לנהוג היתר בהסרת המלח עכ\"ל:","\u0003לשפוך. \u0004 מפני שמלאך המות מפיל במים טיפת דם המות. ובתשב\"ץ כתב שראה א' ששתה מהמים \u0005(שהיו בבית בשעת פטירת המת וכשראה החכם גער בו שלא לשתות מהם ולאחר שעה קלה ששתה המים יצאה נשמתו של אותו ששתה ושאלו לחכם מה ראית שגערת בו אמר אני ראיתי את מלאך המות ששפשף את סכינו במים שהיו באותו הבית לאחר פטירת המת)\u0006 ועיין בא\"ח סי' תנ\"ה ושם כתוב שאין לשפוך המים השאובים למצוה דשומר מצוה לא ידע דבר רע ע\"ש בט\"ז וכתב דהך שכונה לא נתבאר כאן שיעורה אלא דבכתובות כתבו התוס' דשכונה היינו שלשה בתים כדאמרי' ספ\"ק דע\"א עכ\"ל \u0005(ובנה\"כ כתב ומיהו י\"ל דהכא קרי שכונה מי שהוא שכן ממש וכן נוהגין עכ\"ל)\u0006 בראקנט\"י פ' ויחי כתב דבשעת מיתה יזהר שלא יצא שום אבר חוץ להמטה והפליג על מי שאינו נזהר בזה:"]],["\u0003הלכות קריעה\u0004\nמִי שֶׁמֵּת לוֹ מֵת, וְהוּא מֵהַמֵּתִים \u0010c0\u0011 שֶׁרָאוּי לְהִתְאַבֵּל עֲלֵיהֶם, חַיָּב לִקְרֹעַ עָלָיו. וְצָרִיךְ שֶׁיִּקְרַע מְעֻמָּד; וְאִם קָרַע מְיֻשָּׁב, לֹא יָצָא, \u0005וְצָרִיךְ לַחֲזֹר וְלִקְרֹעַ (טוּר בְּשֵׁם רי\"ץ גֵּאוּת וְהָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּבֵית יוֹסֵף לְדַעַת ראב\"ד ורי\"ף וְרַמְבַּ\"ן וּמָרְדְּכַי פא\"מ)\u0006. וּלְכַתְּחִלָּה צָרִיךְ \u0010c1\u0011 לִקְרֹעַ קֹדֶם שֶׁיִּסְתֹּם פְּנֵי הַמֵּת. \u0005(בֵּית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006.\nמְקוֹם הַקְּרִיעָה, בְּכָל מָקוֹם בְּבֵית הַצַּוָּאר לְפָנָיו; אֲבָל אִם קָרַע לְאַחֲרָיו, \u0005אוֹ בְּשׁוּלֵי הַבֶּגֶד (טוּר)\u0006 אוֹ מִן הַצְּדָדִין, לֹא יָצָא. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁיּוֹצֵא אִם קוֹרֵעַ בְּשׁוּלֵי הַבֶּגֶד, וְכֵן נָהֲגוּ לְהָקֵל לִקְרֹעַ בְּשׁוּלֵי הַבֶּגֶד, (אֵלּוּ מִנְהָגִים תִּמְצָא בִּסְמַ\"ק ובמהרי\"ו וּבְחִדּוּשֵׁי אֲגֻדָּה וּבְכָל בּוֹ)\u0006, כְּשֶׁקּוֹרְעִין עַל \u0010c2\u0011 שְׁאָר מֵתִים שֶׁאֵינָן מִתְאַבְּלִין עֲלֵיהֶם; אֲבָל עַל הַמֵּתִים שֶׁהֵם קְרוֹבָיו, וּמִתְאַבְּלִים עֲלֵיהֶם, אֵינוֹ יוֹצֵא בִּקְרִיעָה זוֹ וְצָרִיךְ לִקְרֹעַ בְּבֵית הַצַּוָּאר, וְכֵן נָהֲגוּ.\nשִׁעוּר קְרִיעָה, טֶפַח. וְאִם קָרַע עַל מֵת, וּבָא לְהוֹסִיף בְּאוֹתָהּ קְרִיעָה עַל מֵת אַחֵר, אִם \u0010c3\u0011 אַחַר ז', סָגֵי בְּכָל שֶׁהוּא. וְאִם הוּא בְּתוֹךְ ז', צָרִיךְ טֶפַח. וְעַל אָבִיו וְאִמּוֹ, אֲפִלּוּ אַחַר ז', קוֹרֵעַ עַד שֶׁיְּגַלֶּה אֶת לִבּוֹ.\nכְּשֵׁם שֶׁקּוֹרֵעַ עַל קְרוֹבוֹ שֶׁמִּתְאַבֵּל עָלָיו, כָּךְ קוֹרֵעַ בִּפְנֵי קְרוֹבוֹ עַל מֵת שֶׁמֵּת לִקְרוֹבוֹ, כֵּיצַד, הֲרֵי שֶׁמֵּת בֶּן בְּנוֹ אוֹ אֲחִי בְּנוֹ אוֹ אֵם בְּנוֹ, חַיָּב לִקְרֹעַ בִּפְנֵי בְּנוֹ. וְכֵן קוֹרֵעַ עַל חָמִיו וַחֲמוֹתוֹ. וְהָאִשָּׁה קוֹרַעַת עַל חָמִיהָ וַחֲמוֹתָהּ. \u0005וְאֵין נוֹהֲגִין עַכְשָׁו כֵּן, וּכְמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סי' שע\"ד לְעִנְיַן אֲבֵלוּת.\u0006\nהָעוֹמֵד בִּשְׁעַת יְצִיאַת נְשָׁמָה שֶׁל אִישׁ, אוֹ \u0010c4\u0011 אִשָּׁה מִיִּשְׂרָאֵל, חַיָּב לִקְרֹעַ \u0005(טוּר בְּשֵׁם רַמְבַּ\"ן וּבֵית יוֹסֵף אַף לְדַעַת רַשִׁ\"י)\u0006. וַאֲפִלּוּ אִם לִפְעָמִים עָשָׂה עֲבֵרָה לְתֵאָבוֹן, אוֹ שֶׁמַּנִּיחַ לַעֲשׂוֹת מִצְוָה בִּשְׁבִיל טֹרַח. \u0005הַגָּה: אֲבָל רָגִיל לַעֲשׂוֹת \u0010c5\u0011 עֲבֵרָה, אֵין מִתְאַבְּלִין עָלָיו (מָרְדְּכַי סוֹף מ\"ק)\u0006. וְכָל שֶׁכֵּן עַל מוּמָר \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006 \u0005(שָׁם וּפוֹסְקִים וְכֵן מוּכָח מִשַּׁ\"ס פי' נִגְמַר הַדִּין וְכַמָּה דּוּכְתֵי)\u0006. וְיֵשׁ אוֹמְרִים שֶׁמּוּמָר \u0010c6\u0011 שֶׁנֶּהֱרַג בִּידֵי עוֹבֵד כּוֹכָבִים, מִתְאַבְּלִין עָלָיו \u0005(הַגָּהַת אֲשֵׁרִ\"י פֶּרֶק א\"מ ואוֹר זָרוּעַ)\u0006. וְכֵן מוּמָר קָטָן שֶׁהֵמִיר עִם אָבִיו אוֹ אִמּוֹ, דְּהָוֵי כְּאָנוּס \u0005(מָרְדְּכַי ה\"א בְּשֵׁם ר\"י וּמְבִיאוֹ בֵּית יוֹסֵף סִימָן שמ\"ה)\u0006 וְיֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין, וְכֵן עִקָּר \u0005(שָׁם בְּשֵׁם ר\"ח)\u0006. הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, אַף עַל פִּי שֶׁאֵין מִתְאַבְּלִין עֲלֵיהֶם, מִתְאַבְּלִין עַל בְּנֵיהֶם \u0005(אוֹר זָרוּעַ)\u0006. וְע\"ל סִימָן שמ\"ה.\nעַל אָדָם כָּשֵׁר, שֶׁאֵינוֹ חָשׁוּד עַל שׁוּם עֲבֵרָה וְלֹא עַל שׁוּם בִּטּוּל מִצְוָה, וְלֹא סַנֵי שׁוּמְעָנֵיהּ, אַף עַל פִּי שֶׁאֵינוֹ גָּדוֹל בַּתּוֹרָה, וְאַף עַל פִּי שֶׁלֹּא עָמַד בִּשְׁעַת יְצִיאַת נְשָׁמָה, חַיָּב לִקְרֹעַ עָלָיו; וְהוּא שֶׁעוֹמֵד שָׁם בֵּין מִיתָה לִקְבוּרָה; וְתַלְמִידֵי חֲכָמִים פְּטוּרִים מִקְּרִיעָה זוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין חַיָּב לִקְרֹעַ עַל אָדָם כָּשֵׁר, אֶלָּא אִם כֵּן עוֹמֵד עָלָיו בִּשְׁעַת יְצִיאַת נְשָׁמָה; אֲבָל חַיָּב לִבְכּוֹת וּלְהִתְאַבֵּל עָלָיו (ר\"ן פ' הָאוֹרֵג וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק י\"א בְּשֵׁם רַאַבִיָ\"ה)\u0006, וְכֵן נָהֲגוּ לְהָקֵל.\nעַל חָכָם וְעַל תַּלְמִיד חָכָם שֶׁשּׁוֹאֲלִין אוֹתוֹ דְּבַר הֲלָכָה בְּכָל מָקוֹם וְאוֹמְרָהּ, קוֹרְעִין עָלָיו אֲפִלּוּ לְאַחַר קְבוּרָה, בְּיוֹם שְׁמוּעָה, אִם הוּא תּוֹךְ ל' יוֹם. וְקוֹרֵעַ עָלָיו \u0010c7\u0011 בִּשְׁעַת הֶסְפְּדוֹ. \u0005לֹא קָרַע בְּיוֹם שְׁמוּעָה, וּכְבָר עָבַר זְמַן הֶסְפְּדוֹ, וְלֹא קָרַע, שׁוּב אֵינוֹ קוֹרֵעַ (כָּךְ מַשְׁמָע בַּטּוּר וּבְבֵית יוֹסֵף)\u0006. וְקוֹרְעִין עָלָיו עַד שֶׁמְּגַלִּין אֶת לִבָּם. וּכְבָר נָהֲגוּ תַּלְמִידֵי חֲכָמִים בְּכָל מָקוֹם לִקְרֹעַ זֶה עַל זֶה טֶפַח, אַף עַל פִּי שֶׁהֵם שָׁוִים, וְאֵין אֶחָד מֵהֶם מְלַמֵּד אֶת חֲבֵרוֹ. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁאֵין קוֹרְעִין עַל חָכָם, אֶלָּא אִם כֵּן הוּא רַבּוֹ אוֹ שֶׁיּוֹדְעִין מִשְּׁמוּעוֹתָיו \u0010c8\u0011 שֶׁחִדֵּשׁ, דְּהַיְנוּ רַבּוֹ, (הָרֹא\"שׁ והגמי\"י בְּשֵׁם הר\"מ)\u0006, וְכֵן נָהֲגוּ לְהָקֵל בִּמְדִינוֹת אֵלּוּ.\nעַל \u0010c9\u0011 רַבּוֹ שֶׁרֹב חָכְמָתוֹ מִמֶּנּוּ; אִם מִקְרָא, מִקְרָא; וְאִם מִשְׁנָה, מִשְׁנָה; אִם גְּמָרָא, גְּמָרָא; קוֹרֵעַ כָּל בְּגָדָיו עַד שֶׁמְּגַלֶּה לִבּוֹ. וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ קוֹרֵעַ אֶלָּא טֶפַח, וְאֵינוֹ מְאַחֶה לְעוֹלָם. וַאֲפִלּוּ מִשְּׁמוּעָה רְחוֹקָה, קוֹרֵעַ עָלָיו לְעוֹלָם. וְאִם לֹא לָמַד רֹב חָכְמָתוֹ מִמֶּנּוּ, אֵינוֹ קוֹרֵעַ עָלָיו, אֶלָּא כְּדִין שְׁאָר מֵתִים שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם. וַאֲפִלּוּ לֹא לָמַד מִמֶּנּוּ אֶלָּא דָּבָר אֶחָד, בֵּין קָטָן בֵּין גָּדוֹל, קוֹרֵעַ עָלָיו. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּקֶרַע שֶׁעַל רַבּוֹ שֶׁאֵינוֹ מֻבְהָק, נָמֵי אֵינוֹ מִתְאַחֶה (טוּר בְּשֵׁם הָרֹא\"שׁ וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י וְתוֹסָפוֹת והר\"ן)\u0006. תַּלְמִידֵי חֲכָמִים שֶׁיּוֹשְׁבִים בְּיַחַד וּמַקְשִׁים וּמְפָרְקִין זֶה לָזֶה וְלוֹמְדִים בְּיַחַד, יֵשׁ אוֹמְרִים שֶׁדִּינָן כְּרַב שֶׁאֵינוֹ מֻבְהָק, וְיֵשׁ אוֹמְרִים שֶׁדִּינָן כְּרַב מֻבְהָק \u0005(אֵלּוּ שֵׁנִי הַסְבָרוֹת בַּטּוּר)\u0006. וְיֵשׁ אוֹמְרִים דְּאֵין צְרִיכִין לִקְרֹעַ אֶלָּא עַל רַבּוֹ שֶׁלִּמְּדוֹ רֹב חָכְמָתוֹ, אֲבָל חֲבֵרִים הַלּוֹמְדִים זֶה עִם זֶה, אוֹ שֶׁהֵאִיר עֵינָיו בְּדָבָר אֶחָד, אֵינוֹ אֶלָּא חֻמְרָא בְּעָלְמָא, וְהֵיכָא דְּנָהוּג נָהוּג, וְהֵיכָא דְּלֹא נָהוּג לֹא נָהוּג, וְאֵין מוֹרִין כֵּן. \u0005(מָרְדְּכַי ה\"א בְּשֵׁם הַשְּׁאִלְתּוֹת והגמ\"יי בְּשֵׁם הר\"מ)\u0006, וְלָכֵן נָהֲגוּ לְהָקֵל בִּמְדִינוֹת אֵלּוּ.\nעַל כָּל הַמֵּתִים, קוֹרֵעַ עָלָיו טֶפַח בַּבֶּגֶד הָעֶלְיוֹן, וְדַיּוֹ. וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ כָּל \u0010c10\u0011 בְּגָדָיו, אֲפִלּוּ הוּא לָבוּשׁ י', עַד שֶׁמְּגַלֶּה לִבּוֹ. וְאִם לֹא קָרַע כָּל בְּגָדָיו, לֹא יָצָא, וְגוֹעֲרִים בּוֹ, וְכָל זְמַן שֶׁאוֹתוֹ הַבֶּגֶד עָלָיו, אוֹמְרִים לוֹ: קְרַע, אֲפִלּוּ לְאַחַר שְׁלֹשִׁים.\nאֲפַרְקְסוּתוֹ, אֵינוֹ צָרִיךְ לִקְרֹעַ, יֵשׁ מְפָרְשִׁין שֶׁהוּא בֶּגֶד הַזֵּעָה הַדָּבוּק לִבְשָׂרוֹ, וְיֵשׁ מְפָרְשִׁים דְּהַיְנוּ בֶּגֶד הָעֶלְיוֹן שֶׁקּוֹרִין קאפ\"ה; וּפָשַׁט הַמִּנְהָג שֶׁלֹּא לִקְרֹעַ הקאפ\"ה עַל שׁוּם מֵת, אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְלִקְרֹעַ עַל אָבִיו וְאִמּוֹ גַּם הֶחָלוּק שֶׁקּוֹרִין קאמיז\"ה \u0005(כָּל בּוֹ בְּשֵׁם רַבּוֹתָיו הַפּוֹסְקִים וסמ\"ק לְפי' הֶעָרוּךְ)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ אֵין נוֹהֲגִין כֵּן, אֶלָּא אֵין קוֹרְעִין הֶחָלוּק שֶׁל פִּשְׁתָּן שֶׁהוּא בֶּגֶד הַזֵּעָה, וְלֹא \u0010c11\u0011 הַסַּרְבָּל הָעֶלְיוֹן; אֲבָל שְׁאָר בְּגָדָיו, קוֹרֵעַ בְּאָבִיו וְאִמּוֹ; וּבִשְׁאָר מֵתִים, הַמַּלְבּוּשׁ הָעֶלְיוֹן תַּחַת הַסַּרְבָּל\u0006 \u0005(סמ\"ג בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006.\nאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שָׁוִים לְעִנְיַן קְרִיעָה, אֶלָּא שֶׁהָאִשָּׁה קוֹרַעַת \u0010c12\u0011 הַתַּחְתּוֹן וּמַחֲזִירָתוֹ לְאַחֲרֶיהָ, וְחוֹזֶרֶת וְקוֹרַעַת הָעֶלְיוֹן.\nעַל כָּל הַמֵּתִים, אִם רָצָה מַנִּיחַ שְׂפַת הַבֶּגֶד שְׁלֵמָה, וְקוֹרֵעַ מֵהַשָּׂפָה וּלְמַטָּה. וְעַל אָבִיו וְאִמּוֹ, צָרִיךְ לִקְרֹעַ כָּל הַשָּׂפָה. \u0005(וְיֵשׁ אוֹמְרִים אַף עַל שְׁאָר מֵתִים צָרִיךְ לִקְרֹעַ הַשָּׂפָה (מָרְדְּכַי)\u0006, וְכֵן נוֹהֲגִין \u0005(מהרי\"ו סִימָן ו')\u0006.\nעַל כָּל הַמֵּתִים יֵשׁ לוֹ לִקְרֹעַ בִּפְנִים, שֶׁלֹּא בִּפְנֵי אָדָם, לְפִיכָךְ יֵשׁ לוֹ לְהַכְנִיס יָדוֹ בִּפְנִים, וְקוֹרֵעַ בְּצִנְעָא. אֲבָל עַל אָבִיו \u0005(וְאִמּוֹ)\u0006, אֵינוֹ קוֹרֵעַ אֶלָּא מִבַּחוּץ, בִּפְנֵי כָּל אָדָם.\nעַל כָּל הַמֵּתִים, רָצָה קוֹרֵעַ בַּיָּד, רָצָה קוֹרֵעַ בִּכְלִי. עַל אָבִיו וְאִמּוֹ, בַּיָּד. עַל כָּל הַמֵּתִים, אִם בָּא \u0010c13\u0011 לְהַחֲלִיף תּוֹךְ ז' יָמִים, מַחֲלִיף וְאֵינוֹ קוֹרֵעַ. עַל אָבִיו וְאִמּוֹ, אִם מַחֲלִיף תּוֹךְ ז', קוֹרֵעַ כָּל הַבְּגָדִים שֶׁהוּא מַחֲלִיף, וְאֵינוֹ מְאַחֶה לְעוֹלָם, כְּמוֹ בַּפַּעַם הָרִאשׁוֹן. \u0005עַל כָּל הַמֵּתִים יָכוֹל לְהַחֲזִיר קִרְעוֹ לְאַחֲרָיו תּוֹךְ שִׁבְעָה, אֲבָל לֹא בְּאָבִיו וְאִמּוֹ (רַבֵּנוּ יְרוּחָם בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nעַל כָּל הַמֵתִים, שׁוֹלֵל \u0005(פי' תּוֹפֵר תְּפִירָה בִּלְתִּי שָׁוָה)\u0006 לְאַחַר ז', וּמְאַחֶה לְאַחַר שְׁלֹשִׁים יוֹם. \u0005וְאֵין חִלּוּק אִם פָּגַע בָּהֶם \u0010c14\u0011 הָרֶגֶל אוֹ לֹא (הגמ\"יי בְּשֵׁם רַאַבִיָ\"ה)\u0006. עַל אָבִיו וְאִמּוֹ, שׁוֹלֵל לְאַחַר ל' יוֹם, וְאֵינוֹ מְאַחֶה לְעוֹלָם. וְהָאִשָּׁה שׁוֹלֶלֶת לְאַלְתַּר, מִפְּנֵי כְּבוֹדָהּ. \u0005הַגָּה: וְכָל זְמַן שֶׁאָסוּר לִשְׁלֹל, אֲפִלּוּ לְחַבֵּר רֹאשׁ הַקְּרִיעָה עַל יְדֵי מַחַט, אָסוּר. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהַחְמִיר אֲפִלּוּ עַל שְׁאָר מֵתִים, שֶׁלֹּא לִשְׁלֹל תּוֹךְ ל', וְאָז אֲפִלּוּ רֹאשׁ הַקְּרִיעָה אָסוּר לְחַבֵּר עַל יְדֵי מַחַט (מהרי\"ו סִימָן ו')\u0006.\nעַל כָּל הַמֵּתִים, אִם רָצָה חוֹלֵץ כָּתֵף. עַל אָבִיו וְאִמּוֹ, \u0010c15\u0011 חַיָּב לַחֲלֹץ כָּתֵף וְהוֹלֵךְ כָּךְ לִפְנֵי הַמִּטָּה, עַד שֶׁיִּקָּבֵר. וְאִם הַבֵּן אָדָם גָּדוֹל, וְאֵין כְּבוֹדוֹ שֶׁיֵּלֵךְ חֲלוּץ כָּתֵף, אֵין צָרִיךְ לַחֲלֹץ.\nנָשִׂיא דּוֹמֶה לְאָב, לַחֲלִיצַת כָּתֵף, וְלִקְרֹעַ מִבַּחוּץ, וּלְאִחוּי. כָּל הַקּוֹרְעִים עַל חָכָם שֶׁמֵּת, כֵּיוָן שֶׁהֶחֱזִירוּ פְּנֵיהֶם מֵאֲחוֹרֵי הַמִּטָּה, שׁוֹלְלִין וּמְאַחִין לְמָחָר. וְחָכָם שֶׁבָּאָה שְׁמוּעָתוֹ, שׁוֹלֵל בּוֹ בַּיּוֹם, וּמְאַחֶה לְמָחָר. וְעַל נָשִׂיא וְעַל רַבּוֹ מֻבְהָק, שׁוֹלֵל לְמָחָר וְאֵינוֹ מְאַחֶה לְעוֹלָם. עַל חָכָם, חוֹלֵץ מִיָּמִין. וְעַל אַב בֵּית דִּין, מִשְּׂמֹאל. וְעַל נָשִׂיא, מִכָּאן וּמִכָּאן. וְעַל אָבִיו וְאִמּוֹ וְעַל רַבּוֹ מֻבְהָק, רָצָה מִכָּאן רָצָה מִכָּאן, וְאִם רָצָה, חוֹלֵץ שְׁתֵּיהֶן. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו בַּזְּמַן הַזֶּה לֹא נָהֲגוּ לַחֲלֹץ כָּתֵף כְּלָל (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, וְכֵן נוֹהֲגִין הָאִדָּנָא.\nעַל כָּל הַמֵּתִים, אִם לֹא שָׁמַע אֶלָּא לְאַחַר ל' יוֹם, אֵינוֹ קוֹרֵעַ. וּמִי שֶׁאֵין לוֹ חָלוּק וְנִזְדַּמֵּן לוֹ תּוֹךְ שִׁבְעָה, קוֹרֵעַ; אַחַר ז' אֵינוֹ קוֹרֵעַ. עַל אָבִיו וְעַל אִמּוֹ, קוֹרֵעַ וְהוֹלֵךְ לְעוֹלָם \u0005כָּל \u0010c16\u0011 בְּגָדָיו (מהרי\"ו סִימָן יג)\u0006.\nכְּשֵׁם שֶׁאָסוּר לְאַחוֹת קֶרַע שֶׁאֵינוֹ מִתְאַחֶה, כָּךְ אָסוּר \u0010c17\u0011 לַהֲפֹךְ צַד עֶלְיוֹן שֶׁל בֶּגֶד לְמַטָּה, וּלְאַחוֹתוֹ; וַאֲפִלּוּ הַלּוֹקֵחַ אוֹתוֹ, אָסוּר לְאַחוֹתוֹ. לְפִיכָךְ אִם בָּא לְמָכְרוֹ, צָרִיךְ \u0010c18\u0011 לְהוֹדִיעוֹ. וְאִם מְכָרוֹ לוֹ סְתָם, וְלֹא הוֹדִיעוֹ, אָסוּר לְאַחוֹתוֹ עַד שֶׁיֵּדַע שֶׁאֵינוֹ מֵהַקְּרָעִים שֶׁאֵינָם מִתְאַחִים. וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים.\nהַקּוֹרֵעַ מִתּוֹךְ הַמְּלָל, וּמִתּוֹךְ הַשְּׁלָל, וּמִתּוֹךְ הַלִּקּוּט, וּמִתּוֹךְ הַסֻלָּמוֹת, לֹא יָצָא. אֲבָל מִתּוֹךְ אִחוּי אֲלֶכְּסַנְדְּרִי, \u0010c19\u0011 דְּהַיְנוּ תְּפִירָה שֶׁהִיא שָׁוָה לְמַעְלָה וּבוֹלֶטֶת מִלְּמַטָּה, יָצָא.\nקָרַע עַל הַמֵּת, וּמֵת לוֹ מֵת אַחֵר תּוֹךְ ז', קוֹרֵעַ קֶרַע \u0010c20\u0011 אַחֵר; לְאַחַר ז', מוֹסִיף עַל קֶרַע הָרִאשׁוֹן כָּל שֶׁהוּא. מֵת לוֹ מֵת שְׁלִישִׁי אַחַר ז' שֶׁל שֵׁנִי, מוֹסִיף עָלָיו כָּל \u0010c21\u0011 שֶׁהוּא. וְכֵן מוֹסִיף וְהוֹלֵךְ עַד טַבּוּרוֹ. הִגִּיעַ לַטַּבּוּר, מַרְחִיק ג' אֶצְבָּעוֹת, וְקוֹרֵעַ. נִתְמַלֵּא לְפָנָיו, מַחֲזִירוֹ \u0010c22\u0011 לַאֲחוֹרָיו. נִתְמַלֵּא מִלְּמַעְלָה, הוֹפְכוֹ \u0010c23\u0011 לְמַטָּה. נִתְמַלֵּא מִכָּאן וּמִכָּאן, נַעֲשָׂה כְּמִי שֶׁאֵין לוֹ חָלוּק, שֶׁאֵינוֹ קוֹרֵעַ.\nאָמְרוּ לוֹ: מֵת אָבִיו וְקָרַע, וְאַחַר שִׁבְעָה מֵת בְּנוֹ, וְהוֹסִיף. מִתְאַחֶה הַתַּחְתּוֹן וְלֹא הָעֶלְיוֹן. אָמְרוּ לוֹ: מֵת בְּנוֹ, וְקָרַע, וְאַחַר ז' מֵת אָבִיו, אֵינוֹ מוֹסִיף, אֶלָּא קוֹרֵעַ קְרִיעָה \u0010c24\u0011 אַחֶרֶת, שֶׁאֵין אָבִיו וְאִמּוֹ בְּתוֹסֶפֶת.\nמִי שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, אוֹ שֶׁבָּאָה לוֹ שְׁמוּעָה מִשְּׁנַיִם כְּאֶחָד, קוֹרֵעַ קְרִיעָה אַחַת עַל שְׁנֵיהֶם. קָרַע, וְאַחַר כָּךְ מֵת לוֹ מֵת אַחֵר \u0005תּוֹךְ שִׁבְעָה (טוּר)\u0006, קוֹרֵעַ קֶרַע בִּפְנֵי עַצְמוֹ, בֵּין בְּאוֹתוֹ קֶרַע עַצְמוֹ שֶׁמּוֹסִיף בּוֹ וְקוֹרֵעַ עוֹד טֶפַח, אוֹ מַרְחִיק ג' אֶצְבָּעוֹת וְקוֹרֵעַ טֶפַח. לְאַחַר ז', מוֹסִיף עַל קֶרַע רִאשׁוֹן כָּל שֶׁהוּא. מֵת אָבִיו אוֹ אִמּוֹ וְאֶחָד מִשְּׁאָר קְרוֹבָיו, קוֹרֵעַ תְּחִלָּה עַל אָבִיו אוֹ עַל אִמּוֹ עַד לִבּוֹ, וּמַרְחִיק שָׁלֹשׁ אֶצְבָּעוֹת, וְקוֹרֵעַ טֶפַח עַל הַמֵּת הָאַחֵר. מֵת אָבִיו, וְקָרַע, וְאַחַר ז' מֵת אֶחָד מֵהַקְּרוֹבִים, מוֹסִיף עַל קֶרַע הָרִאשׁוֹן, וְתַחְתּוֹן מִתְאַחֶה וְעֶלְיוֹן אֵינוֹ מִתְאַחֶה. מֵת אֶחָד מֵהַקְּרוֹבִים, וְקָרַע, וְאַחַר כָּךְ מֵת אָבִיו אוֹ אִמּוֹ, בֵּין בְּתוֹךְ ז' בֵּין לְאַחַר ז', מַרְחִיק ג' אֶצְבָּעוֹת וְקוֹרֵעַ מִן הַצַּד בִּשְׂפַת הַבֶּגֶד, שֶׁהֲרֵי צָרִיךְ לְהַבְדִּיל קָמֵי שָׂפָה, וְקוֹרֵעַ עַד שֶׁמַּגִּיעַ לְלִבּוֹ. מֵתוּ אָבִיו וְאִמּוֹ כְּאֶחָד, קוֹרֵעַ קֶרַע אֶחָד עַל שְׁנֵיהֶם.\nאָמְרוּ לוֹ: מֵת אָבִיו, וְקָרַע, וְאַחַר כָּךְ נִמְצָא שֶׁהוּא בְּנוֹ, יָצָא יְדֵי קְרִיעָה. וְהוּא שֶׁנּוֹדַע לוֹ תּוֹךְ כְּדֵי דִּבּוּר. וְאִם לֹא נוֹדַע לוֹ עַד אַחַר כְּדֵי דִּבּוּר, לֹא יָצָא. \u0010c25\u0011 אֲבָל אִם אָמְרוּ לוֹ: מֵת לְךָ מֵת, וּכְסָבוּר אָבִיו הוּא, וְקָרַע, וְאַחַר כָּךְ נִמְצָא שֶׁהוּא בְּנוֹ, יָצָא, אֲפִלּוּ לֹא נוֹדַע לוֹ עַד אַחַר כְּדֵי דִּבּוּר.\nהָיָה לוֹ חוֹלֶה, וְנִתְעַלֵּף, וְקָרַע עָלָיו, וְאַחַר כָּךְ מֵת; אִם מֵת תּוֹךְ כְּדֵי דִּבּוּר שֶׁל קְרִיעָה, אֵין צָרִיךְ קְרִיעָה אַחֶרֶת. וְאִם לָאו, צָרִיךְ קְרִיעָה אַחֶרֶת.\nאָמְרוּ לוֹ: מֵת אָבִיו, וְקָרַע וְנָהַג קְצָת יְמֵי אֲבֵלוּת, וְאַחַר כָּךְ אָמְרוּ לוֹ: לֹא מֵת, וְהִפְסִיק, וְחָזְרוּ וְאָמְרוּ לוֹ: בַּפַּעַם \u0010c26\u0011 הָרִאשׁוֹן מֵת, כְּמוֹ שֶׁאָמְרוּ הָרִאשׁוֹנִים, יָצָא יְדֵי קְרִיעָה.\nקָטָן שֶׁמֵּת לוֹ מֵת, \u0010c27\u0011 מְקָרְעִין לוֹ.\nהַקּוֹרֵעַ בְּשַׁבָּת עַל מֵתוֹ, אַף עַל פִּי שֶׁחִלֵּל שַׁבָּת, יָצָא יְדֵי קְרִיעָה.\nהַקּוֹרֵעַ בְּחָלוּק גָּזוּל, לֹא יָצָא יְדֵי קְרִיעָה.\nקָטָן דְּלֹא קִים לָן בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, שֶׁמֵּת בְּתוֹךְ ל' אוֹ אֲפִלּוּ בְּיוֹם שְׁלֹשִׁים, אֵין קוֹרְעִין \u0010c28\u0011 עָלָיו.\nאֵין קוֹרְעִין בְּיוֹם טוֹב, אֲפִלּוּ בְּיוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת, אֲפִלּוּ קְרוֹבִים שֶׁל מֵת. אֲבָל בְּחֹל הַמּוֹעֵד, קוֹרְעִין עַל כָּל אֶחָד כְּפִי מַה שֶּׁהוּא, אִם עוֹמֵד בִּשְׁעַת יְצִיאַת נְשָׁמָה, אוֹ אִם הוּא אָדָם כָּשֵׁר אוֹ חָכָם עַל כָּל אֶחָד, כְּדִינוֹ שֶׁנִּתְבָּאֵר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּנוֹהֲגִין שֶׁאֵין לִקְרֹעַ בְּחֹל הַמּוֹעֵד, רַק עַל \u0010c29\u0011 אָבִיו וְאִמּוֹ; וְעַל שְׁאָר מֵתִים קוֹרְעִין לְאַחַר הַמּוֹעֵד (ת\"ה סִימָן רפ\"ח)\u0006, וּבְמָקוֹם שֶׁאֵין \u0010c30\u0011 מִנְהָג, יֵשׁ לִקְרֹעַ עַל כֻּלָּם.\nשָׁמַע בָּרֶגֶל שְׁמוּעָה קְרוֹבָה, קוֹרֵעַ, וַאֲפִלּוּ אִם אַחַר הָרֶגֶל תִּהְיֶה רְחוֹקָה.\nהַהוֹלֵךְ בְּבֶגֶד קָרוּעַ לִפְנֵי הַמֵּת, שֶׁמַּרְאֶה עַצְמוֹ שֶׁקָּרַע, וְלֹא קָרַע, הֲרֵי זֶה גּוֹזֵל אֶת הַחַיִּים וְאֶת הַמֵּתִים.\nהָאוֹמֵר לַחֲבֵרוֹ: הַשְׁאִילֵנִי חֲלוּקְךָ שֶׁאֲבַקֵּר אֶת אַבָּא שֶׁהוּא חוֹלֶה, וְהָלַךְ וּמְצָאוֹ שֶׁמֵּת, קוֹרְעוֹ, וּמְאַחֶהוּ וּמַחֲזִיר לוֹ חֲלוּקוֹ, וּמְשַׁלֵּם לוֹ דְּמֵי קִרְעוֹ. וְאִם לֹא \u0010c31\u0011 הוֹדִיעוֹ, הֲרֵי זֶה לֹא יִגַּע בּוֹ.\nהַמַּשְׁאִיל לַחֲבֵרוֹ חָלוּק לֵילֵךְ בּוֹ לְבֵית הָאָבֵל, אֵינוֹ רַשַּׁאי לִטֹּל מִמֶּנּוּ עַד שֶׁיַּעַבְרוּ יְמֵי הָאֵבֶל. \u0010c32\u0011 \u0005וּבְחֹשֶׁן הַמִּשְׁפָּט סִימָן שמ\"א סָעִיף ב' לֹא פָּסַק כֵּן.\u0006\nקוֹרְעִין עַל שְׁמוּעוֹת רָעוֹת, \u0010c33\u0011 כְּגוֹן שֶׁנִּקְבְּצוּ רֹב הַצִּבּוּר לַמִּלְחָמָה וְשָׁמְעוּ שֶׁנִּגְּפוּ לִפְנֵי אוֹיְבֵיהֶם, אֲפִלּוּ לֹא נֶהֶרְגוּ אֶלָּא הַמִּעוּט מֵהֶם. \u0005וְהוּא הַדִּין אִם הָלְכוּ בַּשֶּׁבִי (נ\"י פא\"מ)\u0006.\nהַשּׁוֹמֵעַ בִּרְכַּת הַשֵּׁם, וַאֲפִלּוּ בִּרְכַּת הַכִּנּוּי \u0005(רַמְבַּ\"ם פ\"ב מֵהִלְכוֹת עֲבוֹדַת כּוֹכָבִים ד\"י)\u0006 \u0005אֲפִלּוּ אָמְרוּ בִּלְשׁוֹן לַעַז הָוֵי כְּכִנּוּי\u0006 \u0005(נ\"י פֶּרֶק אַרְבַּע מִיתוֹת)\u0006, חַיָּב לִקְרֹעַ, וְהוּא שֶׁיִּשְׁמָעֶנָּה מִיִּשְׂרָאֵל. \u0005וְיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה מוּמָר דִּינוֹ כְּעוֹבֵד כּוֹכָבִים (ג\"ז שָׁם)\u0006. וַאֲפִלּוּ הַשּׁוֹמֵעַ מֵהָעֵדִים הֵיאָךְ בֵּרַךְ פְּלוֹנִי, חַיָּב לִקְרֹעַ. וְהָעֵדִים אֵינָם צְרִיכִים לִקְרֹעַ פַּעַם אַחֶרֶת. הָרוֹאָה \u0010c34\u0011 סֵפֶר תּוֹרָה שֶׁנִּשְׂרַף, אוֹ תְּפִלִּין, אוֹ אֲפִלּוּ מְגִלָּה אַחַת מֵהַנְּבִיאִים אוֹ מֵהַכְּתוּבִים, קוֹרֵעַ \u0010c35\u0011 שְׁתֵּי קְרִיעוֹת. וְדַוְקָא שֶׁשּׂוֹרְפִין אוֹתָהּ בִּזְרוֹעַ, וּכְמַעֲשֶׂה שֶׁהָיָה.\nהָרוֹאֶה עָרֵי יְהוּדָה בְּחֻרְבָּנָן, אוֹ יְרוּשָׁלַיִם אוֹ בֵּית הַמִּקְדָּשׁ, חַיָּב לִקְרֹעַ. \u0005וְעַיֵּן בא\"ח סי' תקס\"א.\u0006\nכָּל אֵלּוּ הַקְּרָעִים רַשַּׁאי \u0010c36\u0011 לְמָלְלָן, לְשָׁלְלָן, לְלַקְּטָן, לַעֲשׂוֹתָן כְּמִין \u0010c37\u0011 סֻלָּמוֹת, לְמָחֳרָתוֹ; אֲבָל אֵין מִתְאַחִין לְעוֹלָם.",[],["\u0003שראוי. \u0004 כאשר יתבאר לקמן סי' שע\"ד:","\u0003שיסתום\u0004 פני המת בקבר. ולעיל סי' של\"ט ס\"ג נתבאר דכשמגיע לדיין האמת קורע האבל \u0005(דהיינו במקום שנהגו לומר צידוק הדין עם יציאת נשמה)\u0006:","\u0003שאר. \u0004 כשעומדין שם בשעת יציאת נשמה כדלקמן ס\"ה:","\u0003אחר. \u0004 כלו' אם מת לו מת אחר ז' סגי כדלקמן סכ\"א:","\u0003אשה. \u0004 כתב רש\"ל שלפרש\"י משמע דקורעין על קטן אבל בפ' האורג פרש\"י והרא\"ש שאין לך ריק בישראל שאין בו תורה ומצוה ומ\"ה קורעין נמי על אשה ולא על קטן. וכתב הב\"ח מיהו בקטן שלומד מקרא צריך לקרוע עליו לכ\"ע \u0005(ובספר ערך לחם כתב בשם הרדב\"ז סימן תק\"ח שקורעין אפי' על הקטן אבל לא על הקטנה וכתב עוד בשם הנ\"ל סי' אלף קצ\"ג עמד בשעת יציאת נשמה בשבת פטור מלקרוע במ\"ש)\u0006:","\u0003עבירה. \u0004 אפילו לתיאבון אין קורעין ואין מתאבלין עליו. ש\"ך:","\u0003שנהרג. \u0004 כיון דלא מיקטל כדין ה\"ל מיתתו כפרה כשנהרג ומתאבלים עליו ש\"ס פרק נגמר הדין וכ\"מ מדברי הר\"מ שהביא הרא\"ש פ' אלו מגלחין עכ\"ל הש\"ך:","\u0003בשעת. \u0004 וכתב הב\"ח מיהו דוקא כשהספדו תוך ל' אבל לאחר ל' אין קורעין אפי' בשעת הספדו וכ\"כ הרא\"ש בשם הראב\"ד. ש\"ך:","\u0003שחדש. \u0004 כתב הש\"ך ואני תמה שלא נהגו לקרוע אפי' על חכם שיודעין משמועותיו שחדש ואפי' על גדול ממנו ואין להם על מה שיסמכו. ואולי ס\"ל דלא נקרא ת\"ח אלא כשיודע דבר הלכה בכל מקום ואפי' במסכת כלה כדאיתא בש\"ס. וכבר כ' האגודה פ\"ק דחולין דעתה בעונותינו אין ת\"ח דהא אין יודע אפי' במסכת כלה וצ\"ע עכ\"ל:","\u0003רבו. \u0004 כתב ברוקח על רבו שלמדו חכמה יושב עליו יום א' או שעה אחת אבילות. ט\"ז:","\u0003בגדיו. \u0004 כתב מהרש\"ל דעל אב ואם קורעין מצד שמאל ועל שאר קרובים מצד ימין. וכתב הב\"ח דהכי מסתברא דכיון שעל אביו ואמו צריך לקרוע עד שיגלה את לבו והלב משמאלו ע\"כ צריך לקרוע משמאל לגלות לבו וכן נוהגין בקהלות. ומ\"מ היינו מצד המנהג אבל מדינא משמע דמצד שקורעין על אביו ואמו קורעין גם על שאר קרובים כדמשמע בש\"ס ופוסקים והט\"ו לקמן סכ\"ב ע\"ש ואפשר דהתם כיון שכבר קרע מצד א' לא נהגו להחמיר בכך ולקרוע בצד השני אלא סגי בהוספה עכ\"ל הש\"ך:","\u0003הסרבל. \u0004 כתב בתשו' מ\"ב דהיינו מה שקורין מנטי\"ל אבל הרא\"ק חייבין לקרוע בין על אביו ואמו בין על שאר מתים והט\"ז כתב שדבריו תמוהים ואין ראוי אפי' להחמיר ולקרוע הרא\"ק דהוי חומרא דאתי לידי קולא דהיינו בשאר מתים שדין הוא לקרוע רק בגד העליון לחוד זה ודאי אינו נכון שלא לקרוע רק הרא\"ק ולצאת בו ידי קריעה בבגד שאינו חייב ודאי בקריעה \u0005(ובנה\"כ הסכים לדעת המשאת בנימין ע\"ש)\u0006:","\u0003התחתון. \u0004 כלומר בקריעת אב ואם שצריכה לקרוע כל הבגדים לא תקרע העליון תחלה כדי שלא תגלה את לבה ואע\"ג דאין נוהגין לקרוע החלוק מ\"מ כשתגלה החלוק נמי איכא פריצותא כמו מגלה לבה כ\"כ הב\"ח:","\u0003להחליף. \u0004 כ' הש\"ך דהיינו בחול אבל בשבת אף על אביו ואמו מחליף ואינו קורע ואם אין לו להחליף מחזיר הקרע לאחוריו וע\"ל סי' שפ\"ט ס\"ג \u0005(מיהו היינו דוקא כשמחליף בגדים של חול אבל בבגדי שבת נוהגים איסור)\u0006 וכתב הב\"ח בשם מהר\"ר מנחם מ\"ץ דבגדים ישנים שהיו יודעים שלבש אותם קודם מיתת אביו יכול ללובשן [אחר ז'] בלא קריעה עכ\"ל:","\u0003הרגל. \u0004 ואע\"ג דרגל מבטל גזרת ז' ול' היינו דוקא לענין אבלות אבל לענין כל מילי דקריעה בעינן ז' ול' ממש כ\"כ ב\"י בשם הגמי\"י מיהו האידנא נהגו לאחות הקרע כל שפסק האבלות וכן לקמן סי' שצ\"ט שכתבו הפוסקים סתמא שהרגל מבטל גזירת ז' ול' משמע דכל הגזרה ששייך בז' ול' מבטל מכל דבר עכ\"ל הש\"ך:","\u0003כתף. \u0004 בספ\"ק דב\"ק פרש\"י על חלוצי כתף שקרעו בגדיהם עד שנראה כתפיהם:","\u0003בגדיו. \u0004 היינו אותן שעליו בשעת שמועה אבל לא אותן שמחליף. ש\"ך:","\u0003להפוך. \u0004 כ' הט\"ז נראה דאם בא לחתוך סביב הקריעה ולהשליכו ולהושיב שם חתיכת בגד אחר שרי לאחר י\"ב חודש לאביו ולאמו דאין זה בכלל איחוי קריעה כלל וכן הסכים הב\"ח בזה עכ\"ל:","\u0003להודיעו. \u0004 משום מקח טעות אבל משום איסורא א\"צ להודיעו דהא אפי' בסתם אסור לאחותו כדלעיל סי' ט\"ז באותו ואת בנו כ\"כ הרמב\"ן. והב\"ח כ' דל\"ד לאו\"ב דהתם הכל יודעים הדין משא\"כ כאן דלא כ\"ע דינא דקריעה גמירי:","\u0003תפירה. \u0004 והוא שקורין בל\"א אוב\"ר נא\"ט כמו שעושין בתפירת הכתונת וי\"מ כמו התפירה שעושין החייטים בבתי שוקיים שחוזרין וכופפין בבגד היוצא מהתפירה ותופרין אותה מן ב' צדדיו ומותחין אותו עד שאינו ניכר התפירה. כ\"כ הפרישה:","\u0003אחר. \u0004 היינו שבאותו קרע מוסיף וקורע עוד טפח:","\u0003שהוא. \u0004 משמע דבתוך ז' של שני צריך להוסיף טפח. ש\"ך:","\u0003לאחוריו. \u0004 וקורע מלפניו:","\u0003למטה. \u0004 וישים לו בית צואר מאחריו ויקרענו:","\u0003אחרת. \u0004 והב\"ח כתב דאם בקריעה הראשונה שקרע על בנו הבדיל קמי שפה א\"צ קריעה אחרת וסגי במה שמוסיף על הקרע הראשון. ואין זה נראה לדינא דמוכח מדברי הפוסקים דאפי' הבדיל כן צריך קריעה אחרת וע\"ל סכ\"ג עכ\"ל הש\"ך:","\u0003אבל. \u0004 והב\"ח פסק דבכה\"ג לא יצא ולא מיקרי סתם אלא הקורע על מתו [לשם] מי שהוא א\"צ לחזור ולקרוע אפי' לא נודע לו מי הוא עד אחר \u0005(כ\"ד חדש)\u0006 [כדי דיבור]. ורמ\"א כ' דאם א\"ל מת לו מת סתם ואינו יודע איזהו וקרע סתם ואח\"כ נודע לו מי הוא יצא ידי קריעה דיש ברירה. עכ\"ל:","\u0003הראשון. \u0004 אבל אם היה חי בפעם הראשון לא יצא ידי קריעה דהא אחר כדי דיבור הוא. ט\"ז. וכתב הש\"ך ולענין ז' ימי אבילות קרוב היה לומר כיון שחלה עליו אבילות ונהגו אע\"פ שבטל מקצת הימים בשוגג עולין לו ואין תשלומין לאבילות ודבר זה צריך תלמוד הרמב\"ן ומביאו הטור \u0005(ועיין רדב\"ז ח\"א סימן קצ\"ה ועיין כנ\"ג)\u0006:","\u0003מקרעין. \u0004 בטור כתב מפני עג\"נ פי' כדי להרבות בהספד וכתב הרי\"ץ גאות וקטן שהגיע לחינוך קורעין לו כדרך שמחנכין אותו בשאר מצות ופי' הב\"י דהיינו אפי' היכא דלית ביה משום עגמת נפש וכתב בדרישה מכאן ראיה קצת דקטן שהגיע לחינוך צריך לנהוג כל דיני אבילות ע\"כ ונ\"ל דאף ביום שמועה קרובה נמי דינא הכי ויש מי שחולק בזה ואין בדבריו ממש עכ\"ל הט\"ז \u0005(ובנה\"כ חולק ע\"ז ופסק דאין קטן צריך לנהוג אבילות אף שהגיע לחינוך ע\"ש)\u0006:","\u0003עליו. \u0004 לפי שקריעה היא דרבנן וספיקא לקולא אבל אם קים לן דכלו חדשיו כגון שבעל ופירש אפי' מת בתוך ל' קורע ומתאבל עליו. ש\"ך:","\u0003אביו. \u0004 ואין חילוק בין יום קבורה ליום שמועה רק בין אביו ואמו לשאר קרובים. ב\"ח. ועל שאר מתים היינו קרוביו אבל על שאר אדם כשר נהגו להקל שאין לקרוע כלל. ש\"ך:","\u0003מנהג. \u0004 כתב בתשו' משאת בנימין דהיינו בכל מלכות פולין יש לקרוע על כולם אבל באשכנז נהגו שלא לקרוע כ\"א על אב ואם וכמ\"ש הרב בא\"ח סי' תקמ\"ד ס\"ו. וכתב הב\"ח אע\"פ דנהיגין שלא לקרוע בח\"ה על שאר מתים היינו אם אפשר לקרוע אחר המועד אבל היכא דשמע שמועה קרובה ברגל ולאחר הרגל נעשית רחוקה דאינו יכול לקרוע אחר הרגל בזה ליכא מנהג ויש לתפוס כהלכה דקורעין בח\"ה. וכ' עוד בשם מהרש\"ל ונראה היכא ששמע שמועה רחוקה אין קורעין במועד אפי' על אב ואם אלא קורע אחר הרגל דמאחר שנפסק ממנו האבילות לא חמירא הקריעה לדחות הרגל עכ\"ל:","\u0003הודיעו. \u0004 להמשאיל שהולך לבקר החולה לא יגע בו ונראה דאף אם קרע לא יצא דהוי שואל שלא מדעת וגזלן הוי ובחלוק הגזול לא יצא כדלעיל סכ\"ט עכ\"ל הש\"ך:","\u0003ובחשן. \u0004 ובש\"ך כתב דלק\"מ דשם ר\"ל דהשואל ביקש מהמשאיל א\"כ לא נתכוין אלא לטובת השואל למלאות בקשתו ויכול לומר לו לא השאלתי לך אלא שתלך ותחזור אבל הכא כ' המשאיל לחבירו וכו' פי' שהמשאיל בא מעצמו לזכות לשואל שיקיים מצות ניחום אבלים א\"כ כל יומא ויומא רמיא מצוה עליה עכ\"ל:","\u0003כגון. \u0004 וכב\"י בשם ר' ירוחם דנראה שחייב להתאבל כל היום ולפיכך אינו שולל עד למחר ע\"כ ונראה דה\"ה דמאחין למחר. ש\"ך:","\u0003שנשרף. \u0004 וה\"ה נקרע ונחתך ונמחק בזרוע בין מישראל בין מעובד כוכבים דהכל תלוי כשרואה חלול השם בזרוע. ב\"ח \u0005(אבל אם היה דליקה ולא יוכל להציל ונשרפה או כיוצא בזה בלא חילול השם א\"צ קריעה. שו\"ת ח\"צ שאלה מ\"ז ותשו' ש\"י שאלה פ\"ד)\u0006:","\u0003שתי. \u0004 א' על הכתב וא' על הגויל: [\u0005(לו)\u0006] וכמעשה שהיה. היינו כששרף יהויקים את המגילה:","\u0003למוללן. \u0004 שאוחז ב' ראשי הקרע בין האצבעות וכורכן יחד ותוחב ב' או שלש תפירות ולשללן פי' תפירה רחבה שתופר הרבה במשיחה אחת. וללקטן ר\"ל שאורג כל הקרע ראשו על סופו ותוחב במחט ב' או ג\"פ:","\u0003סולמות. \u0004 פי' כמעלות הסולם שתופר ב' תפירות וחוזר ותופר למטה ומניח בין תפירה לתפירה הפסק. כל זה מדברי רבינו ירוחם שהביא ב\"י. עכ\"ל הש\"ך:"]],["\u0003הלכות אנינות\u0004\nמִי שֶׁמֵּת לוֹ מֵת שֶׁהוּא חַיָּב לְהִתְאַבֵּל \u0010c0\u0011 עָלָיו, קֹדֶם קְבוּרָה אוֹכֵל בְּבַיִת אַחֵר. אֵין לוֹ בַּיִת אַחֵר, אוֹכֵל בְּבֵית חֲבֵרוֹ. אֵין בַּיִת \u0010c1\u0011 לַחֲבֵרוֹ, עוֹשֶׂה לוֹ מְחִצָּה וְאוֹכֵל; וַאֲפִלּוּ מְחִצָּה שֶׁל סָדִין סָגֵי, אִם תָּקַע שׁוּלֵי הַסָדִין בְּעִנְיָן שֶׁאֵינוֹ נִטָּל בָּרוּחַ. וְאִם אֵין לוֹ דָּבָר לַעֲשׂוֹת מְחִצָּה, מַחֲזִיר פָּנָיו וְאוֹכֵל. וּבֵין כָּךְ וּבֵין כָּךְ, וַאֲפִלּוּ הוּא \u0010c2\u0011 בְּעִיר אַחֶרֶת, אֵינוֹ \u0010c3\u0011 מֵסֵב וְאוֹכֵל, וְאֵינוֹ אוֹכֵל בָּשָׂר וְאֵינוֹ שׁוֹתֶה יַיִן, וְאֵינוֹ מְבָרֵךְ בִּרְכַּת הַמּוֹצִיא וְלֹא בִּרְכַּת הַמָּזוֹן, וְאֵין מְבָרְכִים עָלָיו וְלֹא מְזַמְּנִין עָלָיו, אֲפִלּוּ אִם אוֹכֵל עִם אֲחֵרִים שֶׁמְּבָרְכִים, לֹא יַעֲנֶה אַחֲרֵיהֶם אָמֵן. וּפָטוּר מִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, וַאֲפִלּוּ אִם אֵינוֹ צָרִיךְ לַעֲסֹק בְּצָרְכֵי הַמֵּת, כְּגוֹן שֶׁיֵּשׁ לוֹ אֲחֵרִים שֶׁעוֹסְקִים בִּשְׁבִילוֹ. וְיֵשׁ אוֹמְרִים שֶׁאֲפִלּוּ אִם יִרְצֶה לְהַחְמִיר עַל עַצְמוֹ לְבָרֵךְ אוֹ לַעֲנוֹת אָמֵן אַחַר הַמְּבָרְכִין, אֵינוֹ רַשַּׁאי \u0005וְעַיֵּן בא\"ח סי' ע\"א.\u0006 וּבְשַׁבָּת וְיוֹם טוֹב, אוֹכֵל בָּשָׂר וְשׁוֹתֶה יַיִן, \u0005אִם יִרְצֶה (רַבֵּנוּ יוֹנָה פ' מִי שֶׁמֵּתוֹ)\u0006. \u0010c4\u0011 וּמְבָרֵךְ, וְחַיָּב בְּכָל הַמִּצְוֹת, חוּץ מִתַּשְׁמִישׁ הַמִּטָּה שֶׁאָסוּר בּוֹ. \u0005וּמֻתָּר לֵילֵךְ לְבֵית הַכְּנֶסֶת בְּשַׁבָּת, וְאַף בְּחֹל אֵין בּוֹ אִסּוּר, רַק מֵאַחַר שֶׁאָסוּר לְהִתְפַּלֵּל, מַה יַּעֲשֶׂה שָׁם (כָּל בּוֹ)\u0006 וְאִם צָרִיךְ לְהַחְשִׁיךְ עַל הַתְּחוּם כְּדֵי לַעֲסֹק בְּצָרְכֵי הַמֵּת, חָל עָלָיו אֲנִינוּת לֵיאָסֵר בְּכֻלָּן מִשָּׁעָה שֶׁמַּתְחִיל לָלֶכֶת כְּדֵי \u0010c5\u0011 לְהַחְשִׁיךְ עַל הַתְּחוּם. וְאִם רוֹצֶה לְקָבְרוֹ בְּיוֹם טוֹב רִאשׁוֹן עַל יְדֵי עֲמָמִין, אָסוּר \u0010c6\u0011 בְּכֻלָּן. וְכָל שֶׁכֵּן בְּיוֹם טוֹב שֵׁנִי, שֶׁהוּא בְּעַצְמוֹ יָכוֹל לְקָבְרוֹ, שֶׁחָלוּ עָלָיו כָּל דִּינֵי אֲנִינוּת. \u0005יֵשׁ אוֹמְרִים דְּתַלְמִיד עַל רַבּוֹ מֻבְהָק אָסוּר לֶאֱכֹל בָּשָׂר וְיַיִן כָּל זְמַן \u0010c7\u0011 שֶׁמֻּטָּל לִפְנֵיהֶם (הַגָּהוֹת אֲשֵׁרִי פ' א\"מ)\u0006.\nמִי שֶׁמֵּת לוֹ מֵת, יֹאכַל בְּמוֹצָאֵי שַׁבָּת בְּלֹא הַבְדָּלָה, וְלֹא יִתְפַּלֵּל, וְלֹא בַּבֹּקֶר קֹדֶם קְבוּרָה, וּלְאַחַר קְבוּרָה יִתְפַּלֵּל תְּפִלַּת שַׁחֲרִית, אִם לֹא עָבַר זְמַנָּהּ. אֲבָל תְּפִלַּת הָעֶרֶב לֹא יִתְפַּלֵּל, שֶׁכְּבָר עָבַר זְמַנָּהּ. וְלֹא דָּמִי לְשָׁכַח וְלֹא הִתְפַּלֵּל עַרְבִית שֶׁמִּתְפַּלֵּל שַׁחֲרִית שְׁתַּיִם, כֵּיוָן \u0010c8\u0011 שֶׁבַּלַּיְלָה לֹא הָיָה חַיָּב לְהִתְפַּלֵּל. וּלְעִנְיַן הַהַבְדָּלָה, \u0010c9\u0011 יַבְדִּיל אַחַר שֶׁיִּקָּבֵר הַמֵּת \u0005(מהר\"מ וּמָרְדְּכַי והג\"מ)\u0006.\nמָקוֹם שֶׁנּוֹהֲגִים שֶׁכַּתָּפִים מְיֻחָדִים לְהוֹצִיא הַמֵּת, וּלְאַחַר שֶׁנִּתְעַסְקוּ הַקְּרוֹבִים בְּצָרְכֵי הַקְּבוּרָה יִמְסְרוּהוּ לָהֶם וְהֵם יִקְבְּרוּהוּ, מִשֶּׁמְּסָרוּהוּ לָהֶם, מֻתָּרִים הַקְּרוֹבִים בְּבָשָׂר וְיַיִן, \u0010c10\u0011 אֲפִלּוּ קֹדֶם שֶׁהוֹצִיאוּהוּ מֵהַבַּיִת, שֶׁשּׁוּב אֵינוֹ מֻטָּל עֲלֵיהֶם. \u0005הַגָּה: מָקוֹם שֶׁנּוֹשְׂאִין הַמֵּת מֵעִיר לְעִיר, אִם מָקוֹם קָרוֹב הוּא הָוֵי כְּאִלּוּ מֻטָּל לְפָנָיו. אֲבָל אִם הוּא מָקוֹם רָחוֹק, כְּגוֹן מַהֲלַךְ שֵׁנִי יָמִים, מֻתָּר עַד שֶׁיָּבוֹאוּ לְעִיר קְבוּרָתוֹ (רַבֵּנוּ יוֹנָה פ' מִי שֶׁמֵּתוֹ)\u0006.\nמִי שֶׁמֵּת בִּתְפִיסָה, וְלֹא נִתַּן לִקְבוּרָה, לֹא \u0010c11\u0011 חָל עַל הַקְּרוֹבִים אֲנִינוּת, וְגַם אֲבֵלוּת לֹא חָל עֲלֵיהֶם, כֵּיוָן שֶׁלֹּא \u0010c12\u0011 נִתְיָאֲשׁוּ מִלְּקָבְרוֹ. וְכֵן אִם קְרוֹבֵי הַמֵּת בִּתְפִיסָה, אֵין אֲנִינוּת חָל עֲלֵיהֶם. וְכֵן מִי שֶׁנֶּהֱרַג בַּדֶּרֶךְ אוֹ גְּרָרַתּוּ חַיָּה אוֹ שְׁטָפוֹ נָהָר, וְלֹא נִתְיָאֲשׁוּ מִלְּקָבְרוֹ, אֵין עַל הַקְּרוֹבִים לֹא דִּין אֲנִינוּת וְלֹא דִּין אֲבֵלוּת, וּמוֹנִים לוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁנִּתְיָאֲשׁוּ מִלְּקָבְרוֹ.\nכָּל זְמַן שֶׁלֹּא נִקְבַּר הַמֵּת, אֵינוֹ חוֹלֵץ מִנְעָל וְסַנְדָּל, וְאֵינוֹ חַיָּב בַּעֲטִיפַת הָרֹאשׁ וּכְפִיַּת הַמִּטָּה, אֲבָל אָסוּר לֵישֵׁב אוֹ לִישַׁן עַל גַּבֵּי מִטָּה, אֲפִלּוּ כְּפוּיָה. \u0005הַגָּה: וְכָל שֶׁכֵּן שֶׁאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה (טוּר בְּשֵׁם הָרַמְבַּ\"ן וּבְשֵׁם הַתּוֹסָפוֹת וּבְמָרְדְּכַי פ\"ק דִּכְתֻבּוֹת בְּשֵׁם י\"א)\u0006. וְיֵשׁ אוֹמְרִים דְּאָסוּר בִּרְחִיצָה וְסִיכָה וְשִׂמְחָה וּשְׁאֵלַת שָׁלוֹם וְתִסְפֹּרֶת וּבִמְלָאכָה \u0005(טוּר)\u0006, אֲבָל מֻתָּר לָצֵאת מִפֶּתַח בֵּיתוֹ. \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ד בְּשֵׁם סמ\"ק)\u0006.\nהַמְשַׁמֵּר אֶת הַמֵּת, אֲפִלּוּ שֶׁאֵינוֹ מֵתוֹ, \u0010c13\u0011 פָּטוּר מִקְּרִיאַת שְׁמַע, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. הָיוּ שְׁנַיִם, זֶה מְשַׁמֵּר וְזֶה קוֹרֵא.",[],["\u0003עליו. \u0004 אפי' אינו מוטל לפניו אלא מוטל עליו לקוברו כל דין אונן עליו עד הקבורה אבל לאחר הקבורה אפילו באותו יום שמת אין דין אונן עליו. כ\"כ בסמ\"ג ושאר פוסקים וכ\"פ הב\"ח:","\u0003לחבירו. \u0004 כגון שהוא שרוי בין העובדי כוכבים:","\u0003בעיר. \u0004 משמע אפי' יש לו מי שיתעסק עמו בעירו שמת דין אונן עליו אבל הב\"ח פסק דקרובים שבעיר אחרת אין דין אונן עליהם אא\"כ אין למת קרובים בעירו שמוטל עליהם לקברו עכ\"ל הש\"ך:","\u0003מיסב. \u0004 פי' על השלחן או על המטה *):","\u0003ומברך. \u0004 משמע דברכות ותפלה חייב בשבת וי\"ט. ש\"ך:","\u0003להחשיך. \u0004 עיין בא\"ח סימן ע\"א וסי' תקמ\"ח ס\"ד:","\u0003שני. \u0004 של גליות כמ\"ש בא\"ח סי' תצ\"ו ס\"ב ובמהרי\"ל כתב בשם מהר\"ש דאם מת בשמיני עצרת לעת ערב שמותר להאבל לקדש בליל שמחת תורה שלאחריו משום דאין אנינות בי\"ט והש\"ך כ' דלדידן דקי\"ל דאנינות נוהג בי\"ט שני א\"כ ה\"ה בלילה אסור לקדש והט\"ז מסכים לדעת מהרי\"ל ע\"ש:","\u0003שמוטל. \u0004 והיינו בימות החול. ט\"ז:","\u0003שבלילה. \u0004 כתוב בדרישה מכאן היה משמע דה\"ה למתעסק בצרכי צבור וכיוצא בזה בזמן התפלה שפטור מלהתפלל כמ\"ש הטור א\"ח סי' צ\"ג שאין צריך להשלימה מטעם זה שכיון שבשעת העסק היה פטור וכו' והט\"ז חולק ע\"ז וכ' דהא זה לא מיקרי רק אונס ובהדיא אמרו באונס דמתפלל אח\"כ שתים כמ\"ש בא\"ח סימן ק\"ח. ול\"ד לאבילות דדוקא אם הפטור בא מחמת דבר אחר והוא עצמו יכול להתפלל בלי שום מניעה אלא שהאבילות פוטרתו בזה אין תשלומין אח\"כ משא\"כ אם הפטור מכח טירדא זה מיקרי אונס והוה כמו חולה שאינו יכול להתפלל וע\"ז תיקנו תשלומין עכ\"ל \u0005(ובנה\"כ כתב דדברי הדרישה נכונים דדוקא באונס שחייב מן הדין אלא משום דאונסו פוטרו דינא הכי אבל העוסק בצרכי צבור דמן הדין אינו חייב כלל דהעוסק במצוה וכו' ע\"ש)\u0006:","\u0003יבדיל. \u0004 עד סוף יום ג' בשבת כמ\"ש בא\"ח סי' רצ\"ט ס\"ו וכ' רש\"ל בתשובה דאם יש לאונן בן לימול ועדיין לא נקבר המת דמ\"מ ימול הבן בבהכ\"נ קודם עלינו כמו בשאר פעמים והט\"ז כתב שמצא בשם רמ\"א כת\"י דיש לקבור קודם דאל\"כ הוי אונן וא\"א לו לברך להכניסו בברית דאונן פטור מכל המצות ונראה שיש לחוש לזה אם אפשר לקברו קודם שיצאו מבהכ\"נ בשחרית דאין דוחין זריזות המצוה אבל אם א\"א יברך הסנדק וימול אותו בשחרית דהא אי' בסי' ש\"ס מת ומילה המילה קודמת עכ\"ל:","\u0003שהוציאוהו. \u0004 אע\"פ שהאבילות עדיין לא חל. ש\"ך:","\u0003חל. \u0004 דכיון דלא ניתן לקבורה לא קרי מוטל לפניו. ש\"ך:","\u0003נתייאשו. \u0004 כתב הש\"ך ואפי' המושל רוצה ממון הרבה מ\"מ כיון דבממון תלוי הדבר ואפשר שאח\"כ יתפייס בדמים מועטים לכך לא חלה האבילות עדיין אבל אם לא ניתן לקבורה מחמת שנאה ולא מחמת ממון ושנאה אינה עשויה ליבטל חלה האבילות מיד עכ\"ל:","\u0003פטור. \u0004 דעוסק במצוה הוא ופטור משאר המצות. ש\"ך:"]],["\u0003הלכות אבילות\u0004\nמִי \u0010c0\u0011 שֶׁהֵכִין כָּל צָרְכֵי חֻפָּתוֹ, שֶׁאָפָה פִּתּוֹ וְטָבַח טִבְחוֹ וּמָזַג יֵינוֹ, וּמֵת אָבִיו שֶׁל חָתָן, וְהוּא בְּמָקוֹם שֶׁאֵינוֹ מָצוּי לִמְכֹּר, וְאִם תִּדָּחֶה הַחֻפָּה יַפְסִיד מַה שֶּׁהֵכִין; אוֹ שֶׁמֵּתָה אִמָּהּ שֶׁל כַּלָּה, וְאִכָּא תַּמְרוּקֵי נָשִׁים וְקִשּׁוּטִין שֶׁאֵינָם מִתְקַיְּמִים, \u0005מֵאַחַר שֶׁאֵין לָהֶם מִי שֶׁיִּטְרַח בַּעֲבוּרָם בְּפַעַם אַחֶרֶת (כָּךְ מַשְׁמָע מִגְּמָרָא)\u0006, מַכְנִיסִין אֶת הַמֵּת לְחֶדֶר, וְאֶת הֶחָתָן וְאֶת הַכַּלָּה לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ, וְכֵיוָן שֶׁחָלָה עָלָיו הַחֻפָּה הַוְיָא לְדִידֵיהּ כְּרֶגֶל, וְנוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה וְאַחַר כָּךְ נוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת. וְכָל שִׁבְעַת יְמֵי הַמִּשְׁתֶּה נוֹהֵג בָּהֶם דְּבָרִים שֶׁבְּצִנְעָא, וְאָסוּר בְּתַשְׁמִישׁ \u0010c1\u0011 הַמִּטָּה, הִלְכָּךְ כָּל ז' יְמֵי הַמִּשְׁתֶּה וְז' יְמֵי הָאֵבֶל הוּא יָשֵׁן בֵּין הָאֲנָשִׁים, וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁאֲסוּרָה לְיַחֵד עִמּוֹ בַּיּוֹם כְּמוֹ בַּלַּיְלָה, וְאֵין צָרִיךְ לִהְיוֹת לָהֶם שְׁתֵּי שְׁמִירוֹת רַק הוּא בֵּין הָאֲנָשִׁים אוֹ הִיא בֵּין הַנָּשִׁים (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְאִם אֵינָם יְשֵׁנִים בְּחֶדֶר אֶחָד, אֵין צְרִיכִין שִׁמּוּר כְּלָל \u0005(כ\"כ הָרַשְׁבָּ\"א בְּכַלָּה שֶׁפֵּרְסָה וְכו')\u0006. וְיֵשׁ אוֹמְרִים דְּבַלַּיְלָה צָרִיךְ שְׁתֵּי שְׁמִירוֹת, וּבַיּוֹם מֻתָּר לְהִתְיַחֵד עִמָּהּ \u0005(טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. וְהַמִּנְהָג \u0010c2\u0011 לִקַּח קָטָן אֵצֶל הֶחָתָן וּקְטַנָּה אֵצֶל הַכַּלָּה, וְאֵין מִתְיַחֲדִין בַּיּוֹם בְּלֹא קָטָן אוֹ קְטַנָּה. וּלְעִנְיַן שְׁלֹשִׁים, אֵינוֹ מוֹנֶה אֶלָּא מִז' יְמֵי \u0010c3\u0011 אֲבֵלוּת וָאֵילָךְ, וְכָל שִׁבְעַת יְמֵי \u0010c4\u0011 הַחֻפָּה מֻתָּר בְּגִהוּץ וְתִסְפֹּרֶת. וְאִם אֵין לוֹ פְּסֵידָא, כְּגוֹן בְּמָקוֹם שֶׁמָּצוּי לִמְכֹּר מַה שֶּׁהֵכִין, אוֹ אֲפִלּוּ אִית לֵיהּ פְּסֵידָא, וּמֵתָה אִמּוֹ שֶׁל חָתָן אוֹ אָבִיהָ שֶׁל כַּלָּה אוֹ אֶחָד מִשְּׁאָר קְרוֹבֵיהֶם, שֶׁנִּשְׁאַר מִי שֶׁיָּכִין לָהֶם לְפַעַם אַחֶרֶת, לֹא הִתִּירוּ לִדְחוֹת הָאֲבֵלוּת אֶלָּא קוֹבֵר אוֹתוֹ מִיָּד, וְנוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת, וְאַחַר כָּךְ מַכְנִיסִין אֶת הֶחָתָן וְאֶת הַכַּלָּה לַחֻפָּה מִיָּד, וְנוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה.",[],["\u0003שהכין. \u0004 כתב הב\"ח אבל אם לא הכין הכל כגון שאפה פתו וטבח טבחו ולא מזג יינו או איפכא דהשתא בע\"כ צריך להשתדל להכין לו יין תדחה החופה ויכין פעם אחרת גם הפת והבשר והש\"ך כתב שאין דבריו מוכרחין דהא עכ\"פ יפסיד מה שהכין כבר וכו' ע\"ש:","\u0003המטה. \u0004 וכתב הטור בשם הראב\"ד דדוקא בתשמיש וביחוד אסור אבל במיני פרישות כמזיגת הכוס והצעת המטה והרחצת פניו ידיו ורגליו מותר ולא עוד אלא אפי' בחיבוק ונישוק יש להתיר ואין כן דעת הש\"ך ומביא כמה ראיות מש\"ס ופוסקים לסתור דברי הראב\"ד ע\"ש ומסיק ששוב מצא במהרש\"א ריש כתובות שהניח דברי הראב\"ד בצ\"ע:","\u0003קטן. \u0004 כ' הב\"ח דהאי קטן וקטנה צריכים שיהיו יודעים טעם ביאה ושאינה מוסרת עצמה לביאה כמ\"ש בא\"ע סי' כ\"ב וכתב הט\"ז אע\"ג דאם יש איסור נדה עליו א\"צ שמירה אם בעל כבר שבודאי לא נחשד על הנדה וא\"כ לדידן שפורשין אחר בעילת מצוה כמו בשאר נדה למה הצריכו שמירה די\"ל כיון שבזמן הש\"ס היה חיוב בשמירה אין לנו להקל בזה \u0005(ובנה\"כ כתב דאשתמיט ליה דברי הרא\"ש דכתב להדיא דלמשנה אחרונה שאמרו דם בתולים כדם נדה מותרת לישן עמו בלא שמירה אלא דכאן מיירי בבעולה וכ\"כ הב\"ח עכ\"ל וע\"ש)\u0006 וכ' עוד הט\"ז מעשה אירע בבתולה שניסת בליל שבת ועדיין לא נבעלה וביום השבת מתה אמה של הכלה ונשאלתי כדת מה לעשות באבילות דידה שקצת לומדים רצו לדמות דין זה לכאן ואני אמרתי שטעו דע\"כ לא התירו כאן לבעול אלא משום פסידא דסעודה אבל היכא שכבר נעשית החופה אין כאן פסידא דשוב לא יכינו שנית ע\"כ אסור לבעול דהא תשמיש המטה אסור גם קודם קבורה אך נ\"ל דלענין אבילות דכלה זאת תתחיל מיד ביום א' ותמנה ז' ימים ואח\"כ תבעל עיין שם באורך. ובדרישה כתוב דמה שמכסין ראש הכלה בשחרית מיקרי חופה ויש לסמוך על זה דאם חלילה אירע אבילות לחתן או לכלה אחר שכיסו ראשה דא\"צ לפסוק ז' ימי המשתה אלא קוברין המת מיד ונדחו ז' ימי אבילות עד אחר ימי המשתה והט\"ז חולק עליו ומסיק דאם הוא אבילות שלא על אב ואם יש לדחות עשיית החופה עד אחר שבעת ימי אבילות ואע\"פ שכבר כיסו פני הכלה בהינומא \u0005(ובנה\"כ כ' דמבואר כן בהרא\"ש דהורה הלכה למעשה שינהוג אבילות תחלה מאחר שאינו אב או אם אלא שאר קרובים וכ\"כ ר' ירוחם בשמו ע\"ש שכתב עוד שנראה דבזה\"ז אפי' במת אב או אם דין שאר קרובים יש להם דהא שכיח הרבה ששאר קרובים מטריחין עצמם ומכינים צרכי סעודה ותכשיטין לכלה הלכך בכל ענין נוהג אבילות תחלה ואינו בועל עד שיעברו ז' ימי אבילות ואחר כך נוהג ז' ימי המשתה עכ\"ל)\u0006:","\u0003ואילך. \u0004 ואע\"ג דברגל קי\"ל דעולה לו למנין שאני התם דנהג בו מצות ל' משא\"כ הכא דמותר אפי' בגיהוץ ותספורת הרמב\"ן ושאר פוסקים ודין חתן שאירעו אבל ברגל אי ז' ימי המשתה עולים לו כתבתי בסי' שצ\"ט ע\"ש עכ\"ל הש\"ך:","\u0003ותספורת. \u0004 והב\"ח כתב דנראה לאסור בגיהוץ ותספורת דאינו מפורסם שעושה משום אבל והוי דברים שבצנעה וכו' והש\"ך השיג עליו וכ' דהפריז על המדה לחלוק על הרמב\"ן והטור בסברא בעלמא וע\"ש: \u0003.. \u0004"]],["מֵת בָּעִיר, כָּל בְּנֵי הָעִיר אֲסוּרִין בִּמְלָאכָה, שֶׁכָּל הָרוֹאֶה מֵת וְאֵינוֹ מְלַוֵּהוּ עַד שֶׁיְּהֵא לוֹ כָּל צָרְכּוֹ, בַּר נִדּוּי הוּא. וְאִם יֵשׁ חֲבוּרוֹת בָּעִיר, שֶׁכָּל אַחַת מִתְעַסֶקֶת בְּמֵתִים בְּיוֹמָהּ, מֻתָּר בְּיוֹם שֶׁאֵינָהּ יוֹמָהּ. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁלֹּא בִּשְׁעַת הוֹצָאָתוֹ, אֲבָל בִּשְׁעַת הוֹצָאָתוֹ הַכֹּל בְּטֵלִים, כְּדִלְקַמָּן.\nבִּכְפָר קָטָן, אֵין שׁוֹאֲלִים שָׁלוֹם זֶה לָזֶה כְּשֶׁהַמֵּת בָּעִיר. \u0005הַגָּה: וְכָל שֶׁכֵּן שֶׁאֵין שׁוֹאֲלִים בְּשָׁלוֹם כְּשֶׁיֵּשׁ מֵת עַל בֵּית \u0010c0\u0011 הַקְּבָרוֹת. (כִּתְבֵי מהר\"ר אִסֶרְלָן סִימָן כ\"ה בְּשֵׁם סֵפֶר חֲסִידִים)\u0006, אֲבָל כְּשֶׁאֵין מֵת שָׁם, שׁוֹאֲלִין. בְּרִחוּק אַרְבַּע אַמּוֹת מִן הַקֶּבֶר \u0005(בתוס' דְּאִלְפָס פֶּרֶק ג' דמ\"ק וְהַכֹּל בּוֹ בְּשֵׁם הר\"מ)\u0006.",[],["\u0003הקברות. \u0004 אפילו בעיר גדולה. ש\"ך:"]],["מִצְוָה גְּדוֹלָה לְהַסְפִּיד עַל הַמֵּת כָּרָאוּי. וּמִצְוָתוֹ שֶׁיָּרִים קוֹלוֹ לוֹמַר עָלָיו דְּבָרִים הַמְּשַׁבְּרִים אֶת הַלֵּב, כְּדֵי לְהַרְבּוֹת בְּכִיָּה וּלְהַזְכִּיר שִׁבְחוֹ. וְאָסוּר לְהַפְלִיג בְּשִׁבְחוֹ יוֹתֵר מִדַּאי, אֶלָּא מַזְכִּירִין מִדּוֹת טוֹבוֹת שֶׁבּוֹ, וּמוֹסִיפִין בָּהֶם \u0010c0\u0011 קְצָת, רַק שֶׁלֹּא יַפְלִיג. וְאִם לֹא הָיוּ בּוֹ מִדּוֹת טוֹבוֹת כְּלָל, לֹא יַזְכִּיר עָלָיו. וְחָכָם וְחָסִיד, מַזְכִּירִים לָהֶם חָכְמָתָם וַחֲסִידוּתָם. וְכָל הַמַּזְכִּיר עַל מִי שֶׁלֹּא הָיָה בּוֹ כְּלָל, אוֹ שֶׁמּוֹסִיף לְהַפְלִיג יוֹתֵר מִדַּאי עַל מַה שֶּׁהָיָה בּוֹ, גּוֹרֵם רָעָה לְעַצְמוֹ וְלַמֵּת.\nכְּשֵׁם שֶׁמַּסְפִּידִין עַל הָאֲנָשִׁים כָּךְ מַסְפִּידִין עַל הַנָּשִׁים כָּרָאוּי לָהֶן, \u0005וְנִסְפָּדוֹת בֵּין הָאֲנָשִׁים וַחֲכָמִים (טוּר)\u0006.\nבְּמָקוֹם שֶׁרְגִילִין לְהַשְׂכִּיר מְקוֹנְנוֹת לְהַסְפִּיד, חַיָּב לְהַשְׂכִּיר מְקוֹנְנוֹת לְהַסְפִּיד עַל אִשְׁתּוֹ. וְאִם לֹא רָצָה, בָּא אָבִיהָ וּמַשְׂכִּיר, וּמוֹצִיא מִמֶּנּוּ בְּעַל כָּרְחוֹ.\nקָטָן, בֶּן כַּמָּה שָׁנִים יִהְיֶה כְּשֶׁמַּסְפִּידִין עָלָיו, \u0010c1\u0011 עֲנִיִּים בְּנֵי חֲמִשָּׁה, עֲשִׁירִים בְּנֵי שִׁשָּׁה; בְּנֵי זְקֵנִים כִּבְנֵי עֲנִיִּים. אֲבָל צִדּוּק הַדִּין וְקַדִּישׁ, אוֹמְרִים עַל תִּינוֹק מִשֶּׁעָבְרוּ עָלָיו שְׁלֹשִׁים יוֹם. \u0005הַגָּה: וְאֵין \u0010c2\u0011 נוֹהֲגִים כֵּן, אֶלָּא עַד שֶׁיִּהְיֶה בֶּן י\"ב חֹדֶשׁ שֶׁיּוֹצֵא בְּמִטָּה, כְּדִלְקַמָּן סִימָן שנ\"ג סָעִיף ה'.\u0006\nבְּנֵי עֲשִׁירִים וּבְנֵי חֲכָמִים, \u0010c3\u0011 מוֹסִיפִין קְצָת עַל שֶׁבַח מַעֲשֵׂיהֶם.\nתִּינוֹק שֶׁיּוֹדֵעַ לִשָּׂא וְלִתֵּן, מַסְפִּידִין אוֹתוֹ בְּמַעֲשֵׂה עַצְמוֹ; וְאִם אֵין לוֹ מַעֲשִׂים, מַסְפִּידִין אוֹתוֹ בְּמַעֲשֵׂה אֲבוֹתָיו; וְאִם אֵין לָהֶם מַעֲשִׂים, מַסְפִּידִין לָהֶם בְּמַעֲשֵׂה קְרוֹבָיו.\nהַכַּלָּה, מַסְפִּידִין אוֹתָהּ בֵּין בְּמַעֲשֵׂה אָבִיהָ בֵּין בְּמַעֲשֵׂה \u0010c4\u0011 בַּעֲלָהּ.\nהַמְּחֻתָּךְ וְהַמְסֹרָס וְהַנְּפָלִים, וּבֶן ח', וְכֵן בֶּן ט' מֵת, וְהָעוֹבֵד כּוֹכָבִים וְהָעֲבָדִים, אֵין מִתְעַסְקִין לְהֶסְפֵּד וּלְלַוּוֹת.\nיוֹרְשִׁים שֶׁאֵינָם רוֹצִים לִפְרֹעַ שְׂכַר הַסַפְדָן, \u0010c5\u0011 מוֹצִיאִים מֵהֶם בְּעַל כֹּרְחָם.\nמִי שֶׁצִּוָּה שֶׁלּא יִסְפְּדוּהוּ, שׁוֹמְעִין לוֹ. \u0010c6\u0011 \u0005אֲבָל אִם צִוָּה שֶׁלּא לִנְהֹג עָלָיו ז' וּגְזֵרַת שְׁלֹשִׁים, אֵין שׁוֹמְעִין לוֹ (מהרי\"ו סִימָן ד')\u0006.\nאִסוּר תְּלִישַׁת שֵׂעָר, וְכֵן שְׂרִיטָה עַל מֵת, בְּסִימָן ק\"פ.\nהָעָם הָעוֹסְקִים בַּהֶסְפֵּד, כָּל זְמַן שֶׁהַמֵּת מֻטָּל לִפְנֵיהֶם, נִשְׁמָטִים אֶחָד אֶחָד וְקוֹרִין אֶת שְׁמַע וּמִתְפַּלְּלִין. אֵין הַמֵּת מֻטָּל לִפְנֵיהֶם, הֵם יוֹשְׁבִים וְקוֹרִים, וְהָאוֹנֵן יוֹשֵׁב וְדוֹמֵם; הֵם עוֹמְדִים וּמִתְפַּלְּלִים, וְהוּא מַצְדִּיק עָלָיו אֶת הַדִּין וְאוֹמֵר: יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהַי שֶׁתִּגְדֹּר פִּרְצוֹתֵינוּ וּפִרְצוֹת עַמְּךָ בֵּית יִשְׂרָאֵל. \u0005[בְּרַחֲמִים]\u0006\nלְאַחַר קְבוּרָה מַפְסִיקִין הַהֶסְפֵּד, בֵּין בִּקְרִיאַת שְׁמַע בֵּין בִּתְפִלָּה. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן ע\"ב.\u0006\nאֵין עוֹשִׂין שְׁנֵי הֶסְפֵּדִים בְּעִיר אַחַת, אֶלָּא אִם כֵּן יֵשׁ שָׁם רֹב עַם לְחַלֵּק לִשְׁנַיִם וְיִהְיֶה בְּכָל הֶסְפֵּד עַם כְּדֵי צָרְכּוֹ.\nאֵין עוֹשִׂים שְׁנֵי הֶסְפֵּדִים בְּעִיר אַחַת, אֶלָּא אִם כֵּן יֵשׁ כְּדֵי לְסַפֵּר שְׁבָחָיו שֶׁל זֶה וּשְׁבָחָיו שֶׁל זֶה.\nאֵין אוֹמְרִים בִּפְנֵי הַמֵּת אֶלָּא דְּבָרִים שֶׁל מֵת, כְּגוֹן צָרְכֵי קְבוּרָתוֹ וְהֶסְפֵּד; אֲבָל שְׁאָר כָּל דָּבָר, אָסוּר. וְהָנֵי מִלֵּי בְּדִבְרֵי \u0010c7\u0011 תּוֹרָה, אֲבָל בְּמִלֵּי דְּעַלְמָא לֵית לָן בָּהּ.\nמֻתָּר לוֹמַר פְּסוּקִים וּדְרָשָׁה לִכְבוֹד הַמֵּת, בְּתוֹךְ אַרְבַּע אַמּוֹתָיו אוֹ בְּבֵית הַקְּבָרוֹת \u0005(מהרא\"י בְּבֵאוּר מא\"ח לְדַעַת רמ\"ה)\u0006.\nחָכָם שֶׁמֵּת, בֵּית מִדְרָשׁוֹ בָּטֵל, שֶׁסוֹפְדִין אוֹתוֹ כָּל שִׁבְעָה. אֲבָל שְׁאָר מִדְרָשׁוֹת, עוֹסְקִין בַּתּוֹרָה אֲפִלּוּ בִּשְׁעַת הֶסְפֵּד; וְאַחַר הַהֶסְפֵּד אֵין תַּלְמִידָיו מִתְקַבְּצִים בְּבֵית מִדְרָשׁוֹ, אֶלָּא מִתְחַבְּרִים שְׁנַיִם שְׁנַיִם וְלוֹמְדִים בְּבָתֵּיהֶם. אַב בֵּית דִּין שֶׁמֵּת, כָּל מִדְּרָשׁוֹת שֶׁבָּעִיר בְּטֵלִין, וְהָרְגִילִין לְהִתְפַּלֵּל בב\"ה מְשַׁנִּים מְקוֹמָם. נָשִׂיא שֶׁמֵּת, כָּל בָּתֵּי מִדְרָשׁוֹת שֶׁבְּכָל מָקוֹם שֶׁמַּסְפִּידִין אוֹתוֹ בְּטֵלִים, וְאַחַר הַהֶסְפֵּד אֵין נִכְנָסִים לְבֵית הַמִּדְרָשׁ, אֶלָּא מִתְחַבְּרִים שְׁנַיִם שְׁנַיִם וְלוֹמְדִין בְּבָתֵּיהֶם. וְכָל בְּנֵי הָעִיר מִתְפַּלְּלִים בְּבֵית הָאָבֵל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת, חוּץ מִקְּרִיאַת הַתּוֹרָה בְּשַׁבָּת וְשֵׁנִי וַחֲמִישִׁי, שֶׁקּוֹרִין בב\"ה. וְלֹא יְטַיְּלוּ בַּשּׁוּק, אֶלָּא יוֹשְׁבִים מִשְׁפָּחוֹת מִשְׁפָּחוֹת וְדָוִים כָּל הַיּוֹם.\nמַסְפִּידִין תַּלְמִידֵי חֲכָמִים וּנְשׁוֹתֵיהֶם בב\"ה וּבְבֵית הַמִּדְרָשׁ, אֲבָל לֹא שְׁאָר הָעָם.\nחָכָם וְאַלּוּף וְגָאוֹן, מַכְנִיסִין אוֹתוֹ לְבֵית הַמִּדְרָשׁ, וּמַנִּיחִין הַמִּטָּה בַּמָּקוֹם שֶׁהָיָה דּוֹרֵשׁ, וְסוֹפְדִין אוֹתוֹ שָׁם; וּכְשֶׁמּוֹצִיאִים הַמִּטָּה, סוֹפְדִים אוֹתוֹ עַד בֵּית הַקְּבָרוֹת, וּבַיּוֹם הַז' עוֹלִים לְבֵית הַקְּבָרוֹת וּמְבַקְּרִין אוֹתוֹ, וְכֵן בְּיוֹם שְׁלֹשִׁים \u0010c8\u0011 וְתַכְלִית י\"ב חֹדֶשׁ, מְבַקְּרִין וּמַשְׁכִּיבִין אוֹתוֹ.",[],["\u0003קצת. \u0004 כ' הט\"ז ונראה לתת טעם לזה דדבר מסתבר הוא שכל מי שעושה איזה מצוה כגון צדקה וכיוצא בה באיזה שיעור בודאי אם היה בא לידו דבר הצורך קצת יותר לא היה מניח מלעשות גם אותו השיעור ולא היה משחית בעבור דבר מועט ע\"כ נחשב לו כאלו עשאו ואין כאן עדות שקר עליו עכ\"ל:","\u0003עניים. \u0004 שהעני מצטער על בניו יותר מהעשיר לפי שאין לו שמחה אחרת:","\u0003נוהגים. \u0004 כ' הש\"ך ובכאן ק\"ק לובלין נוהגין שעל בן ל' אומרים צדוק הדין וקדיש וכמדומה לי שגם בשאר קהלות נוהגים כן וכן ראוי לנהוג עכ\"ל:","\u0003מוסיפין. \u0004 משום כבוד אבותם וכ' הט\"ז דיש בירושלמי שהמת יודע ושומע קילוסו כמתוך החלום וכל שאומרים בפניו יודע עד שיסתום הגולל:","\u0003בעלה. \u0004 שעולה עמו ואינה יורדת עמו:","\u0003מוציאים. \u0004 כ' הש\"ך ודוקא אם ירשו ממון המת דאל\"כ אפי' בניו אין מוציאים מהם בע\"כ כדלקמן סימן שמ\"ח ס\"ב:","\u0003אבל. \u0004 וכ' מהרי\"ו דאם צוה האב או האם שלא לנהוג בהם י\"ב חדש כיון דאינו שייך בשאר מתים אלא בכבוד אב ואם מצוה לקיים דבריהם:","\u0003תורה. \u0004 והב\"ח פסק דד\"ת אסור אפי' חוץ לד' אמות ומילי דעלמא אינו אסור אלא תוך ד\"א ודבריו של מת מותר אפי' בד\"ת ואפי' תוך ד\"א וכן נהגו לדרוש באגדות ופסוקים אפי' תוך ד' אמות של מת ויוצאין מענין לענין עד שמגיעין לספר שבחיו של מת מעסק תורתו וחסידותו ושאר מדות טובות שהיו בו. וכ' הט\"ז ודלא כיש מכוונין להראות מעלתם בדרוש שעל המת מה שאינו לכבודו ולא שפיר קעבדי. ושמעתי הרבה גדולים שהיו מקפידין על זה. וכ' המרדכי דכל אותו החדר שהמת מונח בו חשוב כד\"א וכ\"פ הב\"ח. וע\"ל סימן שס\"ו:","\u0003ותכלית. \u0004 כ' הט\"ז בשם ספר תורת האדם דאין מנהג ולא דרך ארץ להזכיר המת אחר י\"ב חדש. וכל שאין מגעת השמועה אלא לאחר י\"ב חדש פטורים מהספד ואין חדש העיבור בכלל כי לא הוזכר שנה רק י\"ב חדש. עכ\"ל:"]],["הַמְאַבֵּד עַצְמוֹ לָדַעַת, אֵין מִתְעַסְקִים עִמּוֹ לְכָל דָּבָר, וְאֵין מִתְאַבְּלִין עָלָיו, וְאֵין מַסְפִּידִין אוֹתוֹ, וְלֹא \u0010c0\u0011 קוֹרְעִין וְלֹא חוֹלְצִין, אֲבָל עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְכָל דָּבָר שֶׁהוּא כָּבוֹד לַחַיִּים.\nאֵיזֶהוּ מְאַבֵּד עַצְמוֹ לָדַעַת, כְּגוֹן \u0010c1\u0011 שֶׁאָמַר: הֲרֵי הוּא עוֹלֶה לְרֹאשׁ הַגַּג, וְרָאוּהוּ שֶׁעָלָה מִיָּד דֶּרֶךְ כַּעַס, אוֹ שֶׁהָיָה מֵצֵר, וְנָפַל וָמֵת, הֲרֵי זֶה בְּחֶזְקַת שֶׁאִבֵּד עַצְמוֹ לָדַעַת. אֲבָל אִם רָאוּהוּ חָנוּק וְתָלוּי בָּאִילָן, אוֹ הָרוּג וּמֻשְׁלָךְ עַל גַּבֵּי סֵיפוֹ, הֲרֵי הוּא בְּחֶזְקַת כָּל הַמֵּתִים, וּמִתְעַסְקִים עִמּוֹ וְאֵין מוֹנְעִין מִמֶּנּוּ דָּבָר. \u0005הַגָּה: מִי \u0010c2\u0011 שֶׁגָּנַב וְגָזַל וְעַל יְדֵי זֶה נֶהֱרַג בְּדִין מַלְכוּת, מִתְאַבְּלִים עָלָיו, אִם אֵין בּוֹ סַכָּנָה מִפְּנֵי אֵימַת הַמַּלְכוּת, וְלֹא מִקְרֵי מְאַבֵּד לָדַעַת (מהרי\"ו סִימָן קי\"ד)\u0006.\nקָטָן הַמְאַבֵּד עַצְמוֹ לָדַעַת, חָשׁוּב כְּשֶׁלֹּא לָדַעַת. וְכֵן גָּדוֹל הַמְאַבֵּד עַצְמוֹ לָדַעַת, וְהוּא אָנוּס \u0010c3\u0011 כְּשָׁאוּל הַמֶּלֶךְ, אֵין מוֹנְעִין מִמֶּנּוּ כָּל דָּבָר.\nמְנֻדֶּה שֶׁמֵּת, דִּינוֹ כִּמְאַבֵּד עַצְמוֹ לָדַעַת; אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַסְפִּידִין עָלָיו, וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ. וְהָנֵי מִלֵּי בְּאַפְקִירוּתָא, כְּשֶׁעוֹבֵר עַל דִּבְרֵי תּוֹרָה; אֲבָל בְּמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם, וְאֵין מַנִּיחִים אֶבֶן עַל אֲרוֹנוֹ, ומַסְפִּידִין אוֹתוֹ כָּרָאוּי.\nכָּל הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, וְהֵם הָאֲנָשִׁים שֶׁפָּרְקוּ עֹל הַמִּצְוֹת מֵעַל צַוָּארָם, וְאֵין נִּכְלָלִים בִּכְלַל יִשְׂרָאֵל בַּעֲשִׂיָּתָם, וּבִכְבוֹד הַמּוֹעֲדוֹת וִישִׁיבַת בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, אֶלָּא הֲרֵי הֵם כִּבְנֵי חֹרִין לְעַצְמָן כִּשְׁאָר הָאֻמּוֹת, וְכֵן הַמּוּמָרִים וְהַמּוֹסְרִים, כָּל אֵלּוּ אֵין אוֹנְנִים וּמִתְאַבְּלִים עֲלֵיהֶם, אֶלָּא אֲחֵיהֶם וּשְׁאָר קְרוֹבֵיהֶם לוֹבְשִׁים לְבָנִים וּמִתְעַטְּפִים לְבָנִים וְאוֹכְלִים וְשׁוֹתִים \u0010c4\u0011 וּשְׂמֵחִים. \u0005הַגָּה: הַפּוֹרֵשׁ מִן הַצִּבּוּר וְלֹא רָצָה לָשֵׂאת עִמָּהֶם בְּמִסִּים וְאַרְנוֹנִיּוֹת, מִתְאַבְּלִים עָלָיו (תשו' רַשְׁבָּ\"א סי' תשס\"ג)\u0006 אֲבָל אֵין שְׁאָר בְּנֵי הָעִיר צְרִיכִים לְבַטֵּל מִמְּלָאכְתָן בִּשְׁבִילוֹ לַעֲסֹק עִמּוֹ \u0005(כֵּן מַשְׁמָע בנ\"י סוֹף מ\"ק)\u0006.\nקָטָן בֶּן שָׁנָה אוֹ שְׁנָתַיִם שֶׁהֵמִיר עִם \u0010c5\u0011 אִמּוֹ, וָמֵת, אֵין מִתְאַבְּלִין עָלָיו \u0005וְעַיֵּן לְעֵיל סִימָן ש\"מ (סָעִיף ה')\u0006.\nמִי שֶׁנָּפַל בַּיָּם, אוֹ טָבַע בַּנָּהָר, אוֹ אֲכָלַתּוּ חַיָּה, אֵין מוֹנְעִין מִמֶּנּוּ דָּבָר.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ \u0005(פֵּרוּשׁ הַשִּׁדְרָה וְצַלְעוֹתֶיהָ)\u0006 קַיֶּמֶת, עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, אִם יֵשׁ אֲבֵלִים שֶׁמִּתְאַבְּלִין עָלָיו; וְאִם אֵין שִׁלְדּוֹ קַיֶּמֶת, אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים.",[],["\u0003קורעין. \u0004 משמע שאין קורעין עליו כלל אפי' האבלים אבל דעת הרמב\"ן והטור שהאבלים קורעין עליו והאי אין קורעין פי' לרחוקים עכ\"ל הש\"ך. וכ' בתשובת הרשב\"א דבכל מקום שאמרו אין מתעסקין עמו לכל דבר מ\"מ לא לענין קבורה ותכריכים אמרו וכו':","\u0003שאמר. \u0004 וכ' מהרש\"ל דאם לא ראוהו עולה אדיבוריה לא סמכינן ואינו בחזקת מאבד עצמו לדעת וכ' הב\"ח שדבריו נכונים:","\u0003שגנב. \u0004 כ' הש\"ך משמע דמשום עבירה דגנבה וגזלה לא חשיב כפורש מדרכי הצבור ומתאבלים עליו ולפ\"ז בגנב וגזלן שמתו על מטתן יש להתאבל עליהן וכתב הב\"ח שכן נוהגין והיינו כשהתודה קודם מיתתו ומ\"ש הרב בסימן ש\"מ ס\"ה דברגיל לעשות עבירה אין מתאבלין עליו נראה דהיינו כשלא התודה קודם מיתתו. עכ\"ל:","\u0003כשאול. \u0004 שהרג את עצמו לפי שראה שהפלשתים יעשו בו כרצונם ויהרגוהו:","\u0003ושמחים. \u0004 על שאבדו שונאיו של מקום דכתיב באבוד רשעים רנה:","\u0003אמו. \u0004 או אם אביו כדלעיל סימן ש\"מ ס\"ה בהג\"ה:"]],["מִי שֶׁהָיָה בַּעֲלָהּ עִמָּהּ צָלוּב \u0010c0\u0011 בָּעִיר, אוֹ שֶׁאִשְׁתּוֹ עִמּוֹ צְלוּבָה בָּעִיר, אוֹ אָבִיו וְאִמּוֹ, וַעֲדַיִן לֹא כָּלָה הַבָּשָׂר כֻּלּוֹ, לֹא יִשְׁהֶה בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיְתָה גְּדוֹלָה כְּאַנְטוֹכְיָא, שֶׁאֵין אֵלּוּ מַכִּירִין אֶת אֵלּוּ, וְלֹא יִשְׁהֶה בְּצַד זֶה אֶלָּא בְּצַד זֶה.",[],["\u0003בעיר. \u0004 כ' הב\"ח דוקא צלוב בעיר אבל במלכותינו שצולבין חוץ לעיר על פני השדה מותר להשהות בכל העיירות וע\"כ אין דין זה נוהג עכשיו כלל. ש\"ך:"]],["מִי שֶׁמֵּת לוֹ מֵת לִפִנֵי שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, לֹא יִסְפְּדֶנּוּ מִשֶּׁיִּכָּנְסוּ שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, וַאֲפִלּוּ יֵשׁ לוֹ הֶסְפֵּד בְּלֹא זֶה, כְּגוֹן שֶׁמֵּת לוֹ מֵת בְּתוֹךְ שְׁלֹשִׁים שֶׁמֻּתָּר לְסָפְדוֹ, וַאֲפִלּוּ מֵת עֶרֶב הָרֶגֶל, אָסוּר לְהַסְפִּיד עִמּוֹ עַל הַמֵּת שֶׁמֵּת לוֹ לִפְנֵי שְׁלֹשִׁים יוֹם קֹדֶם הַמּוֹעֵד.\nמִי שֶׁבָּאָה לוֹ שְׁמוּעָה בְּתוֹךְ שְׁלֹשִׁים יוֹם קֹדֶם הָרֶגֶל, נִרְאֶה לִי שֶׁמֻּתָּר לְסָפְדוֹ, אַף עַל פִּי שֶׁהִיא רְחוֹקָה.\nמַה שֶּׁאָנוּ נוֹהֲגִין \u0010c0\u0011 בְּתַשְׁלוּם הַשָּׁנָה לְקוֹנֵן וּלְהַזְכִּיר נְשָׁמוֹת, נִרְאֶה לִי אֵינוֹ בִּכְלַל זֶה וּמֻתָּר לַעֲשׂוֹתוֹ סָמוּךְ לָרֶגֶל.",[],["\u0003בתשלום. \u0004 כתב הלבוש ואנו נוהגין להזכיר אפילו פעם הראשון אפילו בתוך הרגל עכ\"ל:"]],["שׂוֹרְפִין עַל הַמְּלָכִים \u0005אוֹ עַל הַנְּשִׂיאִים (טוּר בְּשֵׁם תּוֹסֶפְתָּא)\u0006, מִטָּתָן וּכְלֵי \u0010c0\u0011 תַּשְׁמִישָׁן, אֲבָל עַל הַהֶדְיוֹטוֹת אָסוּר.\nהָאוֹמֵר: אַל תִּקְבְּרוּהוּ מִנְּכָסָיו, אֵין שׁוֹמְעִין לוֹ, אֶלָּא מוֹצִיאִין מִיּוֹרְשָׁיו כָּל צָרְכֵי קְבוּרָתוֹ בְּעַל כָּרְחוֹ, וְכֵן כָּל מַה שֶּׁרְגִילִין לַעֲשׂוֹת לִבְנֵי מִשְׁפַּחְתּוֹ, וַאֲפִלּוּ הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר; וְהוּא שֶׁיָּרְשׁוּ \u0010c1\u0011 מָמוֹן מֵאֲבִיהֶם.\nאֲפִלּוּ מִי שֶׁאֵין לוֹ מָמוֹן שֶׁצִּוָּה וְאָמַר: אַל תִּקְבְּרוּהוּ, אֵין \u0010c2\u0011 שׁוֹמְעִין לוֹ.",[],["\u0003תשמישן. \u0004 ואין בו משום דרכי האמורי ולא משום בל תשחית שזהו כבודן שלא ישתמשו אחרים בכלי תשמישן ובהדיוטות אסור דאיכא יוהרא והשחתה:","\u0003ממון. \u0004 דאל\"כ אין כופין הקרובים אלא על הכל מוטל לקברו ועיין בח\"מ סימן רנ\"ג סל\"א:","\u0003שומעין. \u0004 משום דאיכא בזיוני דחיי. ש\"ך:"]],["מֵת, בֵּין עוֹבֵד כּוֹכָבִים בֵּין יִשְׂרָאֵל, תַּכְרִיכָיו אֲסוּרִים בַּהֲנָאָה. וְדַוְקָא שֶׁהִזְמִינָם לְצָרְכּוֹ וּנְתָנָם עָלָיו, אֲבָל בְּהַזְמָנָה לְבַד, אֲפִלּוּ עֲשָׂאָם לְצָרְכּוֹ לְאַחַר שֶׁמֵּת, לֹא נֶאֶסְרוּ, דְּהַזְמָנָה לָאו מִלְּתָא. וְכֵן אִם נְתָנָם עָלָיו וְלֹא הִזְמִינָם לְכָךְ בִּתְחִלָּה, עֲדַיִן לֹא נֶאֶסְרוּ.\nנוֹיֵי הַמֵּת הַמְחֻבָּרִים בְּגוּפוֹ, כְּגוֹן פֵּאָה נָכְרִית וְכַיּוֹצֵא בָהּ, אֲסוּרִים כְּמוֹ הַמֵּת עַצְמוֹ. \u0005וְדַוְקָא כְּשֶׁהֵם \u0010c0\u0011 קְשׁוּרִים בְּשַׂעֲרוֹת גּוּפָן, אֲבָל אֵינָן קְשׁוּרִים, מֻתָּר (כָּךְ מַשְׁמָע מִפֵּרוּשׁ רַשִׁ\"י פ\"ק דַּעֲרָכִין)\u0006 ; וְלָכֵן מֻתָּר לִטֹּל טַבָּעוֹת שֶׁבְּיָדָם שֶׁל מֵתִים, וְכַיּוֹצֵא בָּזֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּסְתָם, אֲבָל אִם צִוָּה שֶׁיִּתְּנוּ נוֹי גּוּפוֹ הַמְחֻבָּרִים בּוֹ לִבְנוֹ אוֹ לְבִתּוֹ אוֹ לְצֹרֶךְ דָּבָר אַחֵר, מֻתָּרִים. אֲבָל שְׂעָרוֹ מַמָּשׁ, אֲפִלּוּ אִם צִוָּה עָלָיו, אָסוּר בַּהֲנָאָה. \u0005הַגָּה: אִשָּׁה שֶׁיּוֹצֵאת לֵהָרֵג, נֶהֱנִין בִּשְׂעָרָהּ, אַף עַל פִּי שֶׁנִּגְמַר דִּינָה, אֵין שַׂעֲרוֹתֶיהָ נֶאֱסָרִים עַד שֶׁתִּקָּטֵל (טוּר)\u0006.\nאִם הָיוּ אָבִיו וְאִמּוֹ מְזָרְקִים עָלָיו כֵּלִים, מִצְוָה לַאֲחֵרִים לְהַצִּילָן, אִם לֹא נָגְעוּ בַּמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ. \u0005הַגָּה: וְאִם הִצִּילָן, חַיָּב בִּשְׁמִירָתָן; וְאִם הֶחֱזִירָן לְאָבִיו וּלְאִמּוֹ, וְחָזְרוּ וּזְרָקוּם, וְנֶאֶסְרוּ, חַיָּב הַמַּחֲזִיר לְשַׁלֵּם, דְּהָוֵי כִּזְרָקָן לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים (בְּמָרְדְּכַי פֶּרֶק הַמּוֹכֵר אֶת הַסְפִינָה תְּשׁוּבַת מהר\"מ)\u0006. אֲבָל אִם נָגְעוּ בָּהּ, אֲסוּרִים, אִם הֵם שֶׁל אוֹתוֹ שֶׁזְּרָקָן עָלָיו, וְהוּא שֶׁיִּזְרְקֵם עַל דַּעַת שֶׁיִּקְבְּרֵם עִמּוֹ \u0005(טוּר בְּשֵׁם רֹא\"שׁ וְהוּא סוֹף מ\"ק)\u0006. \u0005הַגָּה: הַדַּף שֶׁטִּהֲרוּ עָלָיו, וְכָל הַכֵּלִים שֶׁמּוֹלִיכִין הַמֵּת עֲלֵיהֶם לִקְבוּרָה, לֹא נֶאֶסְרוּ, דַּהֲרֵי לֹא נְתָנָם שָׁם עַל מְנָת לִקְבֹּר עִמּוֹ.\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן נ\"ה, וְכָךְ מַשְׁמָע מִדִּבְרֵי הָרֹא\"שׁ שֶׁהֵבִיא הַטּוּר)\u0006.\nכָּל הַמַּרְבֶּה כֵּלִים עַל הַמֵּת, הֲרֵי זֶה עוֹבֵר מִשּׁוּם בַּל תַּשְׁחִית. \u0005(וַיִּקְרָא כ, יט)\u0006.",[],["\u0003קשורים. \u0004 והב\"ח פסק דאפי' קלועים בתוכם ואינם קשורים אסורים אלא כשאינן קשורים בה כלל דהיינו דתלי בסיכתא מותרים:"]],["אִם רָצוּ, מַתִּירִין שְׂעָרוֹת לְכַלּוֹת, וּמְגַלִּים פְּנֵי חֲתָנִים, וְנוֹתְנִין דְּיוֹ וְקֻלְמוֹס בְּצִדּוֹ, \u0010c0\u0011 וְתוֹלִין מַפְתְּחוֹ שֶׁל מֵת וּפִנְקָסוֹ בָּאֲרוֹנוֹ, מִשּׁוּם עָגְמַת נֶפֶשׁ. וְעוֹשִׂים חֻפּוֹת לַחֲתָנִים וְכַלּוֹת, וְתוֹלִין בָּהֶם דְּבָרִים שֶׁלֹּא הֵבִיאוּ אֹכֶל נֶפֶשׁ; אֲבָל דְּבָרִים שֶׁהֵבִיאוּ אוֹכֵל נֶפֶשׁ, אָסוּר, מִפְּנֵי שֶׁהֵם נֶאֱסָרִים בַּהֲנָאָה.",[],["\u0003ותולין. \u0004 וכתב הב\"ח ועכשיו לא נהגו כן ומעכבין על מי שבא לשנות המנהג:"]],["תַּכְרִיכֵי הַמֵּת, מֻתָּר לַעֲשׂוֹתָן מִכִּלְאַיִם.\nאֵין קוֹבְרִין אֶת הַמֵּת אֶלָּא בְּטַלִּית שֶׁיֵּשׁ בּוֹ צִיצִית. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין צָרִיךְ צִיצִית (טוּר בְּשֵׁם י\"א)\u0006. וְנָהֲגוּ לְקָבְרוֹ בְּצִיצִית, אַךְ \u0010c0\u0011 שֶׁפּוֹסְלִין תְּחִלָּה הַצִּיצִית, אוֹ כּוֹרְכִין אֶחָד מִן הַכַּנְפוֹת.",[],["\u0003שפוסלין. \u0004 והב\"ח כתב דאין לפוסלן אלא יש לקושרן זה עם זה או לכסותם תחת הכנפות וכתב הט\"ז כשנפטר רבינו גרשום אמר ציצית חוץ ונחלקו בפירוש דבריו י\"א דרצונו לומר יסירו הציצית מהטלית ויש אומרים דה\"ק שישימו אותן חוץ לארון עכ\"ל:"]],["אֵין קוֹבְרִין הַמֵּת בְּתַכְרִיכִים \u0010c0\u0011 יְקָרִים, אֲפִלּוּ לְנָשִׂיא שֶׁבְּיִשְׂרָאֵל.\nנָהֲגוּ לִקְבֹּר בִּבְגָדִים לְבָנִים.\nהָאִישׁ אֵינוֹ כּוֹרֵךְ וּמְקַשֵּׁר הָאִשָּׁה, אֲבָל הָאִשָּׁה כּוֹרֶכֶת וּמְקַשֶּׁרֶת הָאִישׁ.\nמַעֲצִימִין עֵינָיו שֶׁל מֵת; וְאִם נִפְתַּח פִּיו, קוֹשְׁרִין לְחַיָּיו. וּפוֹקְקִין נְקָבָיו אַחַר שֶׁמְּדִיחִין אוֹתוֹ בְּמִינֵי בְּשָׂמִים. וְגוֹזְזִין שְׂעָרוֹ. \u0005הַגָּה: וְצִפָּרְנָיו. וּמְדִיחִים אוֹתוֹ הֵיטֵב בְּכָל מָקוֹם, שֶׁיְּהֵא נָקִי מִכָּל טֻמְאָה (בִּנְיָמִין זְאֵב)\u0006, וְטָחִין רֹאשׁוֹ בְּבֵיצִים טְרוּפִים בִּקְלִפָּתָן, שֶׁגַּלְגַּל הוּא שֶׁחוֹזֵר בָּעוֹלָם \u0005(כָּל בּוֹ)\u0006.",[],["\u0003יקרים. \u0004 ובד\"מ כתוב כל העושה תכריכין נאים למת מכירין בו שהוא מודה בתחיית המתים ותע\"ב עכ\"ל ומיירי שהבגד פשתן יהא נאה וע\"כ נהגו קצת לחזור אחר היפה אבל חשובים יותר מדאי ודאי אסור ש\"ך \u0005(ומיהו נראה הכל לפי מה שהוא אדם אם הוא משופע בעושר אין איסור להלבישו בפשתן חשוב דר\"י קרא למנא מכבדותא א\"כ מה שהוא כבוד למת ודאי מותר. ובפרט מה שכתבו המקובלים שמלבישין הנשמה בבגדי חופש כמו שמלבישין להגוף וראיה משתי רוחות דגמרא ברכות. ועוד כמה ראיות לזה וע\"כ יזהרו שלא לשנות בלבישת המתים מן הנהוג כי מצינו שהמתים מקפידין ע\"ז כדאיתא בס\"ח ובס' החיים. ובס' מעבר יבק כ' אפי' ירקבו התכריכים לעולם הנפש תתלבש ברוחניותם ויש בני אדם שמצוים איזה דברים בעניני תכריכין ומצוה לקיים דברי המת אם אפשר ואם אינו נגד הדין. מעשה שחפרו המתים בבה\"ק שלנו והפשיטום ערומים והיינו נוהגים כמ\"ש בש\"י ח\"ב שאלה ק\"ג ע\"ש. אם שכחו להלביש איזה דבר מבגדי המת יניחו אותו על הארון ועיין בשו\"ת ח\"צ סימן מ\"ז וכנ\"י ס\"ד. ובס\"ח סימן תנ\"א כ' כשיש דבר בעיר ב\"מ מחפשין על אותן המתים שמא יש בהם שבלה הבגד פי' שנקברים בבגדים בלוים והוא סכנה או ידיו פשוטות וכו' וכל דבר שהוא משום פקוח נפש יכול לעשות למת עכ\"ל)\u0006:"]],["בָּרִאשׁוֹנָה הָיוּ מְגַלִּים פְּנֵי עֲשִׁירִים וּמְכַסִים פְּנֵי עֲנִיִּים, מִפְּנֵי שֶׁמַּשְׁחִירִים בִּשְׁנַת בַּצֹּרֶת, וְהָיוּ עֲנִיִּים חַיִּים מִתְבַּיְּשִׁים. הִתְקִינוּ שֶׁיִּהְיוּ מְכַסִים פְּנֵי הַכֹּל.\nאֵין מַנִּיחִין סֵפֶר תּוֹרָה עַל \u0010c0\u0011 מִטָּתוֹ שֶׁל חָכָם.\nכְּבוֹדוֹ שֶׁל חָכָם לְהוֹצִיאוֹ דֶּרֶךְ הַפֶּתַח, וְלֹא לְשַׁלְשְׁלוֹ דֶּרֶךְ גַּגּוֹת; וּבְמִטָּה רִאשׁוֹנָה, וְלֹא לְשַׁנּוֹתוֹ מִמִּטָּה לְמִטָּה.\nתִּינוֹק בֶּן ל' יוֹם, מוֹצִיאִים אוֹתוֹ \u0010c1\u0011 בְּחֵיק לְבֵית הַקְּבָרוֹת, וְלֹא בְּאָרוֹן, וְנִקְבָּר בְּאִשָּׁה אַחַת וּשְׁנֵי אֲנָשִׁים; אֲבָל לֹא בְּאִישׁ אֶחָד וּשְׁתֵּי נָשִׁים, מִשּׁוּם יִחוּד. וְאֵין עוֹמְדִים עָלָיו בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, וַאֲפִלּוּ אִם קִים לָן שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nבֶּן ל' יוֹם גְּמוּרוֹת, יוֹצֵא בִּגְלוּסְקָמָא \u0005(פי' אָרוֹן וַיִּישֶׂם בָּאָרוֹן (בְּרֵאשִׁית נ, כו)\u0006, ת\"י וְשַׁוּוּן יָתֵהּ בִּגְלוּסְקָמָא נ\"י) הַנִּטֶּלֶת בַּאֲגַפַּיִם \u0005(פי' נֶסֶר רָחָב, וּפי' אֲגַפַּיִם, זְרוֹעוֹת)\u0006, וְעוֹמְדִין עָלָיו בְּשׁוּרָה, וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן י\"ב חֹדֶשׁ, יוֹצֵא בְּמִטָּה. וְכָל הַיּוֹצֵא בְּמַטָּה, רַבִּים מַצְהִיבִים עָלָיו; וְשֶׁאֵינוֹ יוֹצֵא בְּמִטָּה, אֵין רַבִּים מַצְהִיבִים עָלָיו. וְכָל הַנִּכָּר לָרַבִּים, רַבִּים מִתְעַסְקִין בּוֹ; וְכָל שֶׁאֵינוֹ נִכָּר לָרַבִּים, אֵין רַבִּים חַיָּבִים לְהִתְעַסֵק בּוֹ.\nתִּינוֹק שֶׁמֵּת קֹדֶם שֶׁנִּמּוֹל, מוֹהֲלִין אוֹתוֹ עַל קִבְרוֹ, בְּלֹא בְּרָכָה, וְקוֹרִין לוֹ שֵׁם.\nאֵין מוֹצִיאִין מֵת בְּמִטָּה, אֶלָּא אִם כֵּן הָיָה רֹאשׁוֹ וְרֻבּוֹ קַיָּם.",[],["\u0003מטתו. \u0004 אבל לפניו ע\"ג קרקע או ספסל משמע בטור לעיל סימן שמ\"ד מתשובת רב האי שמותר וכ\"כ בפרישה עד כאן לשון הש\"ך:","\u0003בחיק. \u0004 וכתב בא\"ז דאם רצו להוציאו במטה הרשות בידן:"]],["עִיר שֶׁיֵּשׁ בָּהּ שְׁנֵי מֵתִים, מוֹצִיאִין אֶת \u0010c0\u0011 הָרִאשׁוֹן וְאַחַר כָּךְ מוֹצִיאִין הַשֵּׁנִי. וְאִם הָיוּ מְלִינִים הָרִאשׁוֹן, מוֹצִיאִין הַשֵּׁנִי. חָכָם וְתַלְמִיד חָכָם, מוֹצִיאִין הֶחָכָם. תַּלְמִיד חָכָם וְעַם הָאָרֶץ, מוֹצִיאִין תַּלְמִיד חָכָם. אִישׁ וְאִשָּׁה, מוֹצִיאִין הָאִשָּׁה, מִפְּנֵי שֶׁקְּרוֹבָה לְבֵית הַנִּוּוּל. הוֹצִיאוּ הָרִאשׁוֹן וּקְבָרוּהוּ, אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים, עַד \u0010c1\u0011 שֶׁיּוֹצִיאוּ הַשֵּׁנִי. הוֹצִיאוּ הַשֵּׁנִי וּקְבָרוּהוּ, בָּאִים וְעוֹמְדִים בְּשׁוּרָה, מְנַחֲמִים וּפוֹטְרִים אֶת הָרַבִּים; וְאֵין מְנַחֲמִים שְׁנֵי אֲבֵלִים כְּאֶחָד, אֶלָּא אִם כֵּן הָיָה כְּבוֹדָם שָׁוֶה וְקִלּוּסָן שָׁוֶה.",[],["\u0003הראשון. \u0004 היינו אותו שמת ראשון. ש\"ך:","\u0003שיוציאו. \u0004 כדי שלא לעכב קבורת השני ש\"ך:"]],["אֵין מַנִּיחִין מִטָּה שֶׁל אִשָּׁה בָּרְחוֹב, מִפְּנֵי הַכָּבוֹד. \u0005וְאֵין עוֹלִין \u0010c0\u0011 בְּחֶבֶר עִיר עַל הָאִשָּׁה (טוּר)\u0006.",[],["\u0003בחבר. \u0004 כ' הט\"ז בסימן רנ\"ה כ' הטור יש בעיר חבר עיר פירוש אדם גדול. ובברכות אמרינן ר\"י אומר אין מתפללין מוספין אלא בחבר עיר והיינו צבור ואיך שיהיה פירושו כאן מ\"מ לא בא למעט באשה אלא שאין עומדין בחבורה ברחובה של עיר \u0005(ר\"ל בחבר עיר הוא בחבר רוב עם ומשום ניוול ע\"ש)\u0006 אבל לענין ללוותה פשיטא שאין חילוק בין איש לאשה עכ\"ל:"]],["מֵת שֶׁלֹּא הָיָה לוֹ צָרְכֵי קְבוּרָה, וְגָבוּ לוֹ וְהוֹתִירוּ, אִם כְּשֶׁגָּבוּ \u0010c0\u0011 יַחְדָּו לְצָרְכֵי זֶה הַמֵּת, יִנָּתְנוּ לְיוֹרְשָׁיו; וְאִם לָאו, יַעֲשׂוּ מֵהֶם צָרְכֵי מֵתִים אֲחֵרִים.",[],["\u0003יחדו. \u0004 ל\"ש מעות או שאר דברים ינתנו ליורשיו ולא משום דקניה ליה זה המת בגבייה בעלמא אלא משום דזילותא הוא אחיל ליה ליורשיו וע\"ל סימן רנ\"ג ס\"ו:"]],["אָסוּר לְהָלִין הַמֵּת, אֶלָּא אִם כֵּן הֵלִינוּ לִכְבוֹדוֹ, לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין אוֹ מְקוֹנְנוֹת, אוֹ כְּדֵי שֶׁיָּבֹאוּ קְרוֹבִים אוֹ לְהַשְׁמִיעַ עֲיָרוֹת.\nכָּל הַמֵּתִים, הַמְמַהֵר לְהוֹצִיא מִטָּתוֹ הֲרֵי זֶה \u0010c0\u0011 מְשֻׁבָּח. אֲבָל עַל אָבִיו וְעַל אִמּוֹ, הֲרֵי זֶה מְגֻנֶּה, אֶלָּא אִם כֵּן הָיָה עֶרֶב שַׁבָּת אוֹ עֶרֶב יוֹם טוֹב, אוֹ שֶׁהָיוּ גְּשָׁמִים מְזַלְּפִים עַל מִטָּתוֹ.",[],["\u0003משובח. \u0004 לפי שאין דרך להספיד ולהתאבל עליהם הרבה הלכך יותר כבוד להם כשנקברים במהרה \u0005(משיעמדו הרבה ולא יספידום)\u0006 אבל על אביו ואמו שחייב להספידם ולקונן עליהם הרבה הממהר להוציא ה\"ז מגונה. עכ\"ל הש\"ך:"]],["נוֹשְׂאֵי הַמִּטָּה, וְחִלּוּפֵיהֶן, וְחִלּוּפֵי חִלּוּפֵיהֶן, בֵּין אוֹתָם שֶׁהֵם לִפְנֵי הַמִּטָּה בֵּין אוֹתָם שֶׁל אַחֲרֶיהָ, מֵאַחַר שֶׁלַּמִּטָּה צֹרֶךְ בָּהֶם, \u0010c0\u0011 פְּטוּרִים \u0005מִקְּרִיאַת שָׁמַע;\u0006 וּשְׁאָר הַמְּלַוִּין אֶת הַמֵּת, שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶם, חַיָּבִים. \u0005וְעַיֵּן בא\"ח סִימָן ע\"ב.\u0006\nאֵין מוֹצִיאִין אֶת הַמֵּת סָמוּךְ לִקְרִיאַת שְׁמַע, כָּל שֶׁאֵין שְׁהוּת לְהוֹצִיאוֹ לְקִבְרוֹ קֹדֶם שֶׁיַּגִּיעַ זְמַן קְרִיאַת שְׁמַע; וְאִם הִתְחִילוּ לְהוֹצִיאוֹ, אֵין מַפְסִיקִין כְּדֵי לִקְרוֹת. \u0005הַגָּה: וְיֵשׁ לְהַמְתִּין מִלְּקָבְרוֹ עַד שֶׁיּוּכְלוּ לְשַׁעֵר שֶׁכְּבָר הִתְפַּלְּלוּ רֹב הַקָּהָל; וְאֵין חִלּוּק בָּזֶה בֵּין קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית לִקְרִיאַת שְׁמַע שֶׁל עַרְבִית. וְיֵשׁ מְקִלִּין בְּשֶׁל עַרְבִית, הוֹאִיל וּזְמַנָּהּ כָּל הַלַּיְלָה (מְבֹאָר בא\"ח סִימָן ע\"ב)\u0006.\nבְּמָקוֹם שֶׁיֵּשׁ כַּתָּפִים \u0010c1\u0011 מְיֻחָדִים לָשֵׂאת אֶת הַמִּטָּה, אֲסוּרִים בִּנְעִילַת הַסַנְדָּל, שֶׁמָּא יַפְסִיק סַנְדָּלוֹ שֶׁל אֶחָד מֵהֶם, וְנִמְצָא מִתְעַכֵּב מֵהַמִּצְוָה. \u0005הַגָּה: יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁהָאֲבֵלִים יוֹצְאִים רִאשׁוֹן מִן הַבַּיִת, וְהַקְּרוֹבִים וְהַמִּטָּה אַחֲרֵיהֶם, וְהָרְחוֹקִים נוֹתְנִין הַמֵּת עַל הַמִּטָּה, וְלוֹקְחִים הָאֲבֵלִים וְהַקְּרוֹבִים הַמִּטָּה עַל כִּתְפֵיהֶם, וְאַחַר כָּךְ שְׁאָר הָעָם (כָּל בּוֹ)\u0006. יֵשׁ אוֹמְרִים כְּשֶׁמַּגִּיעִים עִם הַמֵּת לַקְּבָרוֹת, \u0010c2\u0011 מַעֲמִידִים אוֹתוֹ כָּל ד' אַמּוֹת קֹדֶם שֶׁנִּקְבַּר \u0005(שָׁם וּב\"ז)\u0006 ; וְכֵן נָהֲגוּ הָאִדָּנָא לְהַעֲמִידוֹ ב' ג' פְּעָמִים קֹדֶם שֶׁאוֹמְרִים עָלָיו צִדּוּק הַדִּין, וּבְיָמִים שֶׁאֵין אוֹמְרִים צִדּוּק הַדִּין אֵין צָרִיךְ לְהַעֲמִיד אוֹתוֹ \u0005(מ\"כ בְּשֵׁם מהרי\"ל)\u0006.",[],["\u0003פטורים. \u0004 שהעוסק במצוה פטור מהמצוה. ש\"ך:","\u0003מיוחדים. \u0004 כ' הט\"ז נ\"ל שלא יפה עושים באיזה קהלות שעושין להם חבורה של נושאי המטה ואין מניחים אחרים לשאת דא\"כ היו צריכין לילך יחף והם אין עושין כך עכ\"ל:","\u0003מעמידים. \u0004 כ' הלבוש וטעם ההעמדה שמעתי כדי להבריח רוחות הטומאה הרוצים להחזיק בו שלא להכניס עמו לקבורה כי כשמעמידים אותו הולכים להם וביום שא\"א בהם צדוק הדין אין צריך להעמיד אותו כי ביום זה אין כ\"כ רוחות טמאות מצויות עכ\"ל:"]],["מָקוֹם שֶׁנָּהֲגוּ לָצֵאת נָשִׁים לִפְנֵי הַמִּטָּה, יוֹצְאוֹת. מָקוֹם שֶׁנָּהֲגוּ לָצֵאת לְאַחַר הַמִּטָּה, יוֹצְאוֹת. וְעַכְשָׁו נָהֲגוּ שֶׁאֵין יוֹצְאוֹת אֶלָּא לְאַחַר הַמִּטָּה, וְאֵין לְשַׁנּוֹת.\nיֵשׁ \u0010c0\u0011 לִמְנֹעַ מִלָּצֵאת נָשִׁים לְבֵית הַקְּבָרוֹת אַחַר הַמִּטָּה.",[],["\u0003למנוע. \u0004 כלומר אף על פי שכ' בס\"א שנהגו לצאת אחר המטה ואין לשנות מ\"מ לא ילכו לבית הקברות אחר המטה שאם עושים כן גורמים רעות לעולם ח\"ו עכ\"ל הש\"ך:"]],["אִם פָּגְעוּ מֵת וְכַלָּה זֶה בָּזֶה, מַעֲבִירִין הַמֵּת מִלִּפְנֵי \u0010c0\u0011 הַכַּלָּה; וְכֵן אִם אֵין בָּעִיר כְּדֵי לָזֶה וְלָזֶה, מַקְדִּימִין וּמַכְנִיסִין הַכַּלָּה לַחֻפָּה, וְאַחַר כָּךְ קוֹבְרִים הַמֵּת. אֲבָל אַחַר שֶׁנִּכְנְסָה לַחֻפָּה, וְיֵשׁ לְפָנָיו לְנַחֵם אָבֵל וּלְשַׂמֵּחַ חָתָן, תַּנְחוּמֵי הָאֵבֶל קוֹדֵם. וְכֵן הַבְרָאַת הָאָבֵל \u0010c1\u0011 קוֹדֵם לְמִשְׁתֶּה שֶׁל חָתָן. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁיֵּשׁ בְּיָדוֹ סִפּוּק כְּדֵי שְׁנֵיהֶם, אֲבָל אִם אֵין בְּיָדוֹ כְּדֵי שְׁנֵיהֶם, מִשְׁתֵּה הֶחָתָן קוֹדֵם. \u0005חָתָן וְאָבֵל בב\"ה, יוֹצֵא הֶחָתָן עִם שׁוֹשְׁבִינָיו תְּחִלָּה, וְאַחַר כָּךְ הָאָבֵל, וְהַמְנַחֲמִים וְכֵן הַקְּרוּאִים שֶׁלָּהֶם אוֹכְלִים עִם הֶחָתָן כְּשֶׁיִּרְצוּ, וְלֹא עִם הָאָבֵל (בֵּית יוֹסֵף בְּשֵׁם הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006. הַמֵּת וְהַמִּילָה, מִילָה קוֹדֶמֶת; וְאִם הוּא מֵת מִצְוָה, מֵת מִצְוָה קוֹדֵם.",[],["\u0003הכלה. \u0004 להכניסה לחופה דלעולם מצות החיים קודמת למצות המתים ועיקר מצות הכלה להכניסה לחופה משום לא תוהו בראה וגו' עד כאן לשון הש\"ך:","\u0003קודם. \u0004 מפני שהחתן אוכל משלו ומאכיל לאחרים והאבל אינו אוכל עד שיאכילוהו אחרים. ש\"ך:"]],["מְבַטְּלִים תַּלְמוּד תּוֹרָה לְהוֹצָאַת הַמֵּת. לְמָאן דְּמַתְנֵי לַאֲחֵרִים, אֵין לוֹ שִׁעוּר, אֲפִלּוּ יֵשׁ עִמּוֹ כַּמָּה אֲלָפִים מִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּקָרֵי וְתָנֵי, דְּהַיְנוּ שֶׁקָּרָא \u0010c0\u0011 וְשָׁנָה וַעֲדַיִן לֹא שָׁנָה לַתַּלְמִידִים, אִם יֵשׁ ס' רִבּוֹא אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּלֹא קָרֵי וְתָנֵי, כֵּיוָן שֶׁיֵּשׁ לוֹ מִי שֶׁיִּתְעַסֵק עִמּוֹ אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ, וְהוּא שֶׁיֵּשׁ שָׁם עֲשָׂרָה. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו מִן הַסְּתָם מְבַטְּלִין, שֶׁאֵין לְךָ אֶחָד מִיִּשְׂרָאֵל בַּזְּמַן הַזֶּה שֶׁאֵינוֹ בַּמִּקְרָא אוֹ בַּמִּשְׁנָה. (בֵּית יוֹסֵף בְּשֵׁם הריטב\"א פ\"ב דִּכְתֻבּוֹת שכ\"כ בְּשֵׁם סמ\"ג)\u0006 וְאִשָּׁה, יֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּקָרֵי וְתָנֵי; וְיֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּלֹא קָרֵי וְתָנֵי, וְכֵן נָהֲגוּ בְּאִשָּׁה וְתִינוֹק לְקֻלָּא. וְאֵין מְבַטְּלִין תַּלְמוּד תּוֹרָה לְמֵת, כְּשֶׁיֵּשׁ מִי שֶׁיִּתְעַסֵק עִמּוֹ כָּל צָרְכּוֹ, אֶלָּא עוֹסֵק בַּתּוֹרָה. וְאֵינוֹ צָרִיךְ \u0010c1\u0011 לָצֵאת וְלִרְאוֹת אִם יֵשׁ עִמּוֹ כָּל צָרְכּוֹ אִם לָאו, אֶלָּא כֵּיוָן שֶׁיֵּשׁ שָׁם מִי שֶׁיַּעֲשֶׂה מַעֲשֶׂה, תַּלְמוּד תּוֹרָה שֶׁלּוֹ קוֹדֵם. וְתִינוֹקוֹת שֶׁל בֵּית רַבָּן אֵין מִתְבַּטְּלִין כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁמְּבַטְּלִין תַּלְמוּד תּוֹרָה, לְלַוּוֹתוֹ בִּשְׁעַת הוֹצָאָתוֹ; אֲבָל כָּל זְמַן שֶׁמֻּטָּל לְקָבְרוֹ, אֵין מְבַטְּלִין בִּשְׁבִילוֹ תַּלְמוּד תּוֹרָה, אֶלָּא אִם יֵשׁ חֲבוּרוֹת בָּעִיר שֶׁכָּל אַחַת מִתְעַסֶקֶת יוֹמָהּ, אוֹתָהּ שֶׁאֵינָהּ יוֹמָהּ מֻתֶּרֶת בֵּין בְּלִמּוּד בֵּין בִּשְׁאָר מְלָאכוֹת. וּבִשְׁעַת הוֹצָאָה, מְבַטְּלִין מִכָּל שְׁאָר מְלָאכוֹת וּבָאִים לְלַוּוֹתוֹ, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי, דְּלֹא מְפַלְּגִינָן בֵּין לֹא קָרֵי וְתָנֵי אֶלָּא בְּבִטּוּל תַּלְמוּד תּוֹרָה, אֲבָל בִּשְׁאָר מְלָאכוֹת, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי הַכֹּל בְּטֵלִים וּבָאִים לְלַוּוֹתוֹ. וְאִם אֵין חֲבוּרוֹת בָּעִיר, כָּל בַּעֲלֵי מְלָאכוֹת צְרִיכִים לְהִתְבַּטֵּל וּלְהִתְעַסֵק בּוֹ עַד שֶׁיִּקָּבֵר; אֲבָל מִתַּלְמוּד תּוֹרָה אֵין צְרִיכִים לְהִתְבַּטֵּל אֶלָּא בִּשְׁעַת הוֹצָאָתוֹ, כִּדְאַמְרָן.\nהָרוֹאֶה אֶת הַמֵּת וְאֵינוֹ מְלַוֵּהוּ, עוֹבֵר מִשּׁוּם לוֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 וּבַר נִדּוּי הוּא, וּלְפָחוֹת יְלַוֶּנּוּ ד' אַמּוֹת.\nאֲפִלּוּ בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ לְלַוּוֹת אֶת הַמֵּת, צָרִיךְ \u0010c2\u0011 לַעֲמֹד מִפָּנָיו.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ קַיֶּמֶת, צְרִיכִין לְלַוּוֹתוֹ כְּמוֹ בִּשְׁעַת הוֹצָאַת הַמֵּת.",[],["\u0003ושנה. \u0004 משמע תרוייהו בעינן אבל מלשון הריטב\"א שהביא הב\"י משמע דקרא או שנה קאמרינן. ש\"ך:","\u0003לצאת. \u0004 כ' הט\"ז זה קאי אמאן דלא קרי ותני שא\"צ לראות אם יש שם מתעסקי' ונראה דהדעה זאת חולקת על מ\"ש רמ\"א דעכשיו מן הסתם מבטלין ואם כן לפי דעת הרמ\"א יש לבטל גם בזה מ\"מ רב הלומד עם תלמידיו לא יבטל בשביל זה מן הסתם עכ\"ל. וכתב האגודה מה שרגילין לבטל ת\"ת כל זמן שיש מת בעיר הטעם פן יהיה צרכי המת נדחה כי כולם ילכו ללמוד ונ\"ל בקהלות שעשו כתות ויש אנשים מיוחדי' המתעסקי' בו אז אדם הלומד לש\"ש ואינו רגיל לטפל בהם יכול ללמוד ע\"כ. וכתב הש\"ך דמיירי שלא בשעת הוצאתו דיוכל ללמוד וא\"צ להתעסק אפי' למאן דמתני רק בשעת הוצאתו צריך לבטל בשבילו כמ\"ש ס\"ב ודלא כהב\"ח ע\"ש:","\u0003לעמוד. \u0004 כ' הט\"ז פי' מפני העוסקים עמו שהם גומלים חסדים אע\"פ שאין המת ת\"ח. ומכאן יש ללמוד דבכל דבר מצוה שאדם הולך ומתעסק בה יש לעמוד לפניו וכ\"מ בש\"ס פ\"ק דקידושין בוא וראה כמה חביבה מצוה בשעתה שהרי בעלי אומניות עומדים מפני מביאי בכורים וכו'. עכ\"ל \u0005(וכן הוא בספר חסידים סימן תק\"פ)\u0006:"]],["הַנּוֹתֵן מֵתוֹ בְּאָרוֹן וְלֹא קְבָרוֹ בַּקַּרְקַע, עוֹבֵר מִשּׁוּם מֵלִין אֶת הַמֵּת. וְאִם נְתָנוֹ בְּאָרוֹן וּקְבָרוֹ בַּקַּרְקַע, אֵינוֹ עוֹבֵר עָלָיו, וּמִכָּל מָקוֹם יָפֶה לְקָבְרוֹ בַּקַּרְקַע \u0010c0\u0011 מַמָּשׁ, אֲפִלּוּ בְּחוּץ לָאָרֶץ.\nנוֹתְנִין הַמֵּת עַל גַּבָּיו, וּפָנָיו \u0010c1\u0011 לְמַעְלָה, כְּאָדָם שֶׁהוּא יָשֵׁן.\nאֵין קוֹבְרִים ב' מֵתִים זֶה בְּצַד זֶה, אֶלָּא אִם כֵּן הָיָה דֹּפֶן הַקֶּבֶר מַפְסִיק בֵּינֵיהֶם; וְלֹא הַמֵּת בְּצַד עֲצָמוֹת; וְלֹא עֲצָמוֹת בְּצַד הַמֵּת. אֲבָל נִקְבָּר הָאִישׁ עִם בִּתּוֹ קְטַנָּה, וְהָאִשָּׁה עִם בְּנָהּ קָטָן וְעִם בֶּן בְּנָהּ קָטָן. זֶה \u0010c2\u0011 הַכְּלָל כָּל שֶׁיָּשֵׁן עִמּוֹ בְּחַיָּיו, נִקְבָּר עִמּוֹ בְּמוֹתוֹ.\nאֵין נוֹתְנִין ב' אֲרוֹנוֹת זֶה עַל זֶה; וְאִם נָתַן, כּוֹפִין הָעֶלְיוֹן \u0010c3\u0011 שֶׁיְּפַנֶּה. וְאִם יֵשׁ בֵּינֵיהֶם עָפָר שִׁשָּׁה טְפָחִים, מֻתָּר.\nאֵין קוֹבְרִין רָשָׁע אֵצֶל צַדִּיק, אֲפִלּוּ רָשָׁע חָמוּר אֵצֶל רָשָׁע קַל. וְכֵן אֵין קוֹבְרִין צַדִּיק \u0010c4\u0011 וְכָשֵׁר וּבֵינוֹנִי, אֵצֶל חָסִיד מֻפְלָג. \u0005אֲבָל קוֹבְרִים בַּעַל תְּשׁוּבָה אֵצֶל צַדִּיק גָּמוּר (בֵּית יוֹסֵף)\u0006.\nשְׁנַיִם שֶׁהָיוּ שׂוֹנְאִים זֶה לָזֶה, אֵין לְקָבְרָם יַחַד.",[],["\u0003ממש. \u0004 כלומר אע\"פ שהארון קבור בקרקע מ\"מ לא יהא הארון סתום מכל צד אלא יקבר המת בקרקע ממש ובלבוש ובפרישה תמהו על מה שנוהגין עכשיו לעשות לכהנים ארונות שלמים דהיינו שעושים למטה דף שהמת שוכב עליו ואומרים דעושים כן משום חשיבות הכהנים. דאדרבה הרי טוב יותר לשכב על העפר. ולפי מ\"ש הדרישה דבזמנינו שנותנים חרסים על פיו ועיניו הוי במקום עפר ניחא. א\"נ דאי אפשר לארונות שעושים עכשיו שלא יהיו נקובים בצדדים ובנקב סגי כמ\"ש הטור והפוסקים עכ\"ל הש\"ך \u0005(ועי\"ל לפי מנהגינו שמניחין כיס עפר תחת ראשו הוי כקבור בעפר אע\"פ שהכיס מפסיק כיון שהוא מפשתן דק כנהוג אין זה הפסק ולאותן שנותנין מעפר א\"י על פניו של מת ניחא טפי)\u0006:","\u0003למעלה. \u0004 וכ' הלבוש ונוהגין לכסות הארון בדף ושלא להטיל שום עפר על גופו מפני שבזיון הוא לו:","\u0003הכלל. \u0004 כ' הש\"ך נראה דדוקא אקטן קאי אבל בן גדול אף שמותר עם אביו וכן בת גדולה עם אמה מ\"מ אסור לקברם עמהם \u0005(ומ\"ש עם בן בנה הקטן ה\"ה דמותר עם בת בנה או בתה אלא במאי דסיים פתח וחדא מינייהו נקט)\u0006 פרישה:","\u0003שיפנה. \u0004 וכ' הב\"ח דאפילו אם א\"א לקבור במקום אחר ולכן צריך למחות בקהלות שהקוברים עושים כן שלא ישימו ע\"ז אלא בדאיכא בבירור הפסקת ו' טפחים מיהו אם א\"א לקברו בענין אחר ודאי שרי וכ\"מ מתשו' רב האי גאון שהביא הטור ופשוט הוא עכ\"ל הש\"ך \u0005(עיין בתשו' ח\"צ שאלה קמ\"ט)\u0006:","\u0003וכשר. \u0004 והט\"ז גורס וכ\"ש וכ' שכן הוא בס' ת\"ה:"]],["אֵין \u0010c0\u0011 מְפַנִּין הַמֵּת וְהָעֲצָמוֹת, לֹא מִקֶּבֶר מְכֻבָּד לְקֶבֶר מְכֻבָּד, וְלֹא מִקֶּבֶר בָּזוּי לְקֶבֶר בָּזוּי, וְלֹא מִבָּזוּי לִמְכֻבָּד, וְאֵין צָרִיךְ לוֹמַר מִמְּכֻבָּד לְבָזוּי. וּבְתוֹךְ שֶׁלּוֹ, אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי, מֻתָּר, שֶׁעָרֵב לְאָדָם שֶׁיְּהֵא נָח אֵצֶל אֲבוֹתָיו. וְכֵן כְּדֵי לְקָבְרוֹ \u0010c1\u0011 בְּאֶרֶץ יִשְׂרָאֵל, מֻתָּר. וְאִם נְתָנוּהוּ שָׁם עַל מְנַת לְפַנּוֹתוֹ, מֻתָּר בְּכָל עִנְיָן. וְאִם אֵינוֹ מִשְׁתַּמֵּר בְּזֶה הַקֶּבֶר, שֶׁיֵּשׁ לָחוּשׁ שֶׁמָּא יוֹצִיאוּהוּ עוֹבְדֵי כּוֹכָבִים, אוֹ שֶׁיִּכָּנְסוּ בּוֹ מַיִם, אוֹ שֶׁהוּא קֶבֶר הַנִּמְצָא, מִצְוָה לְפַנּוֹתוֹ. \u0005יֵשׁ נוֹהֲגִין לָתֵת מֵעֲפַר אֶרֶץ יִשְׂרָאֵל בַּקֶּבֶר (אוֹר זָרוּעַ)\u0006, וְיֵשׁ לְמִנְהָג זֶה עַל מַה שֶּׁיִּסְמֹכוּ \u0005(מִדְרָשׁ תַּנְחוּמָא פ' וַיְחִי)\u0006.\nאֵין מוֹלִיכִים מֵת מֵעִיר שֶׁיֵּשׁ בָּהּ קְבָרוֹת לְעִיר \u0005(אַחֶרֶת)\u0006, אֶלָּא אִם כֵּן מֵחוּצָה לָאָרֶץ, לָאָרֶץ. \u0005הַגָּה: אוֹ שֶׁמּוֹלִיכִין אוֹתוֹ לִמְקוֹם קִבְרוֹת אֲבוֹתָיו (כֵּן מַשְׁמָע בְּאוֹר זָרוּעַ)\u0006. וְאִם צִוָּה לְהוֹלִיכוֹ מִמָּקוֹם לְמָקוֹם, אוֹ שֶׁצִּוָּה לְקָבְרוֹ בְּבֵיתוֹ וְלֹא בְּבֵית הַקְּבָרוֹת, שׁוֹמְעִין לוֹ \u0005(ג\"ז שָׁם)\u0006. וּמֻתָּר לִתֵּן סִיד עָלָיו, כְּדֵי לְעַכֵּל \u0010c2\u0011 הַבָּשָׂר מַהֵר, וּלְהוֹלִיכוֹ לַמָּקוֹם אֲשֶׁר צִוָּה \u0005(רַשְׁבָּ\"א סִימָן שס\"ט)\u0006.\nאֵין מְלַקְּטִין עֲצָמוֹת, לֹא מִתּוֹךְ הָאָרוֹן וְלֹא מִתּוֹךְ הַקֶּבֶר, לְצַד זֶה, לִקְבֹּר שָׁם מֵת אַחֵר, אוֹ לְצֹרֶךְ הַמָּקוֹם.\nמָקוֹם שֶׁנּוֹהֲגִין לִקְבֹּר בְּמַהֲמוֹרוֹת \u0005(פי' בְּשׁוּחוֹת עֲמֻקוֹת מִן בְּמַהֲמֹרוֹת בַּל יָקוּמוּ (תְּהִלִּים קמ, יא)\u0006 ) בְּלא אָרוֹן, עַד שֶׁיִּתְעַכֵּל הַבָּשָׂר, וְאַחַר כָּךְ מְלַקְּטִין הָעֲצָמוֹת וְקוֹבְרִין אוֹתָן בְּאָרוֹן, מֻתָּר.\nאָרוֹן שֶׁפִּנּוּהוּ, אָסוּר בַּהֲנָאָה. אִם הוּא שֶׁל אֶבֶן וְשֶׁל חֶרֶס, יִשָּׁבֵר; וְשֶׁל עֵץ, יִשָּׂרֵף.\nהַמּוֹצֵא נְסָרִים בְּבֵית הַקְּבָרוֹת, לֹא יְזִיזֵם מִמְּקוֹמָם.\nאָסוּר לִפְתֹּחַ הַקֶּבֶר אַחַר שֶׁנִּסְתַּם הַגּוֹלֵל, אֲפִלּוּ אִם עוֹרְרִים הַיּוֹרְשִׁים לְפָתְחוֹ כְּדֵי לִבְדֹּק אִם הֵבִיא שְׁתֵּי שְׂעָרוֹת.",[],["\u0003מפנין. \u0004 הטעם שהבלבול קשה למתים מפני שמתייראים מיום הדין וזכר לדבר ישנתי אז ינוח לי ובשמואל הוא אומר למה הרגזתני להעלות וגו'. ט\"ז וש\"ך:","\u0003בא\"י. \u0004 שהוא כפרתו שעפר א\"י מכפרת דכתיב וכפר אדמתו עמו. ש\"ך:","\u0003הבשר. \u0004 שנאמר בשרו עליו יכאב כל זמן שבשרו עליו אינו נוח מן הדין. ט\"ז \u0005(ועיין ש\"י ח\"ב סי' צ\"ז)\u0006:"]],["קֶבֶר שֶׁל בִּנְיָן, אָסוּר בַּהֲנָאָה; אֲבָל קַרְקַע עוֹלָם שֶׁל קֶבֶר, אֵינוֹ נֶאֱסָר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהַקַּרְקַע שֶׁלָּקְחוּ מִן הַקֶּבֶר וְחָזְרוּ וְנָתְנוּ עָלָיו, דְּהָוֵי תָּלוּשׁ וּלְבַסּוֹף חִבְּרוֹ, אָסוּר בַּהֲנָאָה (טוּר בְּשֵׁם הר\"ר יְשַׁעְיָה)\u0006. וְיֵשׁ אוֹסְרִין עוֹד לֵישֵׁב עַל הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר לְמַצֵּבָה \u0005(גַּם זוֹ בִּשְׁמוֹ וכ\"כ הַגָּהוֹת אֲשֵׁרִ\"י בְּשֵׁם אוֹר זָרוּעַ פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. וְיֵשׁ \u0010c0\u0011 חוֹלְקִים וּמַתִּירִים \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. הַכֵּלִים שֶׁחוֹפְרִים וְקוֹבְרִים בָּהֶם, מֻתָּרִים בַּהֲנָאָה, וְאֵין לְהִשְׁתַּמֵּשׁ בָּהֶן אֶלָּא מִדַּעַת הַגַּבַּאי, כְּמוֹ בִּשְׁאָר צְדָקָה \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן צ\"ז)\u0006. וְהָא דְּקֶבֶר שֶׁל בִּנְיָן אָסוּר לְעוֹלָם, דַּוְקָא שֶׁבְּנָאוֹ לְשֵׁם מֵת, וּנְתָנוֹ בּוֹ אֲפִלּוּ עַל דַּעַת לְפַנּוֹתוֹ, וַאֲפִלּוּ לֹא נָתַן בּוֹ אֶלָּא נֵפֶל. אֲבָל אִם בְּנָאוֹ לִשְׁמוֹ, וְלֹא נְתָנוֹ בּוֹ, מֻתָּר. וְכֵן אִם נְתָנוֹ בּוֹ אַדַּעְתָּא לְפַנּוֹתוֹ, וְלֹא הִזְמִינוֹ מִתְּחִלָּה, מֻתָּר לְאַחַר שֶׁפִּנָּהוּ. אֲבָל אִם נְתָנוֹ בּוֹ עַל דַּעַת לִהְיוֹת בּוֹ עוֹלָמִית, אָסוּר אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ, אֲפִלּוּ לֹא בְּנָאוֹ לִשְׁמוֹ. וְאִם לֹא בְּנָאוֹ לִשְׁמוֹ, וּנְתָנוּהוּ בְּתוֹכוֹ וְהוֹסִיף בּוֹ דִּימוֹס \u0005(פֵּרוּשׁ נִדְבָּךְ, וְהוּא שׁוּרַת בִּנְיַן הַחוֹמָה)\u0006 לִשְׁמוֹ, כֻּלּוֹ אָסוּר, אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ וַאֲפִלּוּ שֶׁקְּבָרוֹ שָׁם עַל דַּעַת לְפַנּוֹתוֹ. וְאִם מַכִּיר הַדִּימוֹס שֶׁהוֹסִיף לִשְׁמוֹ, מְסִירוֹ, וְהוּא לְבַדּוֹ אָסוּר, וּשְׁאָר הַקֶּבֶר מֻתָּר.\nקֶבֶר הַנִּמְצָא, \u0010c1\u0011 מֻתָּר לְפַנּוֹתוֹ. פִּנָּהוּ, מְקוֹמוֹ טָהוֹר \u0010c2\u0011 וּמֻתָּר בַּהֲנָאָה. קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָמֵא \u0010c3\u0011 וְאָסוּר בַּהֲנָאָה. \u0010c4\u0011 וְהָרַמְבַּ\"ם גּוֹרֵס קֶבֶר הַנִּמְצָא, מֻתָּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה; קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָהוֹר וּמֻתָּר בַּהֲנָאָה.\nמֵת מִצְוָה, שֶׁמְּצָאוֹ אָדָם בַּשָּׂדֶה וּקְבָרוֹ שָׁם, אֲפִלּוּ שֶׁלֹּא מִדַּעַת בַּעַל הַשָּׂדֶה, אָסוּר לְפַנּוֹתוֹ, שֶׁמֵּת מִצְוָה קוֹנֶה מְקוֹמוֹ. וְכָל הַמּוֹצְאוֹ צָרִיךְ לְקָבְרוֹ \u0010c5\u0011 בַּמָּקוֹם שֶׁמְּצָאוֹ. וְאִם מְצָאוֹ עַל הַמֶּצֶר, שֶׁצָּרִיךְ לְפַנּוֹתוֹ מִשָּׁם מִפְּנֵי הָרַבִּים שֶׁלֹּא יַאֲהִילוּ עָלָיו, אִם מְצָאוֹ בֵּין שְׂדֵה בּוּר \u0005(פיר' שֶׁאֵינָהּ חֲרוּשָׁה וּזְרוּעָה)\u0006 לִשְׂדֵה נִיר \u0005(פֵּרוּשׁ נִיר נֶחֱרַשׁ וְלֹא נִזְרַע)\u0006, מְפַנֶּהוּ לִשְׂדֵה בּוּר. בֵּין שְׂדֵה נִיר לִשְׂדֵה זֶרַע, מְפַנֶּהוּ לִשְׂדֵה נִיר. בֵּין שְׂדֵה זֶרַע לִשְׂדֵה אִילָן, מְפַנֶּהוּ לִשְׂדֵה זֶרַע. בֵּין שְׂדֵה אִילָן לִשְׂדֵה כֶּרֶם, מְפַנֶּהוּ לִשְׂדֵה אִילָן. וְאִם שְׁתֵּיהֶם שָׁווֹת, מְפַנֶּהוּ לַקָּרוֹב שֶׁבָּהֶם. וְאִם שְׁתֵּיהֶן שָׁווֹת בְּקֵרוּב, מְפַנֶּהוּ לְאֵיזֶהוּ מֵהֶם שֶׁיִּרְצֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְצָאוֹ חוּץ לַתְּחוּם. אֲבָל אִם מְצָאוֹ בְּתוֹךְ הַתְּחוּם, מְבִיאוֹ לְבֵית הַקְּבָרוֹת. וְאֵינוֹ נִקְרָא מֵת מִצְוָה, אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ.\nאִם מָצְאוּ יִשְׂרָאֵל הָרוּג, יִקְבְּרוּהוּ כְּמוֹ שֶׁמְּצָאוּהוּ, בְּלֹא תַּכְרִיכִין, וְלֹא יַחְלְצוּ בּוֹ אֲפִלּוּ מִנְעָלָיו. \u0005הַגָּה: וְכֵן עוֹשִׂין לְיוֹלֶדֶת שֶׁמֵּתָה, אוֹ לְמִי \u0010c6\u0011 שֶׁנָּפַל וָמֵת (מהרי\"ל סִימָן ס\"ה)\u0006. וְיֵשׁ אוֹמְרִים שֶׁמַּלְבִּישִׁין אוֹתָם לְמַעְלָה מִבִּגְדֵיהֶם, תַּכְרִיכִין \u0005(הגהמי\"י בְּשֵׁם ר\"י מִדּוּרָא)\u0006. וְנָהֲגוּ שֶׁאֵין עוֹשִׂין לָהֶם תַּכְרִיכִין כִּשְׁאָר מֵתִים, רַק קוֹבְרִין אוֹתָן בְּבִגְדֵיהֶם, וּלְמַעְלָה מֵהֶם סָדִין, כִּשְׁאָר מֵתִים.\nקֶבֶר הַמַּזִּיק אֶת הָרַבִּים, כְּגוֹן שֶׁהוּא סָמוּךְ לַדֶּרֶךְ, אֲפִלּוּ נִקְבַּר שָׁם מִדַּעַת בַּעַל הַשָּׂדֶה, מֻתָּר לְפַנּוֹתוֹ, וּמְקוֹמוֹ טָהוֹר, וְאָסוּר בַּהֲנָאָה אִם קָדַם הַקֶּבֶר; אֲבָל אִם קָדַם הַדֶּרֶךְ, מְקוֹמוֹ \u0010c7\u0011 מֻתָּר בַּהֲנָאָה.\nקֶבֶר שֶׁפִּנָּהוּ, הֵיכָא דְּמֻתָּר בַּהֲנָאָה, לֹא יַעֲשֶׂנּוּ בֵּית \u0010c8\u0011 הַתֶּבֶן וְלֹא בֵּית הָעֵצִים וְלֹא בֵּית הָאוֹצָרוֹת.\nהַחוֹצֵב קֶבֶר לְאָבִיו וּקְבָרוֹ בְּמָקוֹם אַחֵר, לֹא יִקָּבֵר בּוֹ הוּא עוֹלָמִית, מִשּׁוּם כְּבוֹד אָבִיו; אֲבָל אַחֵר, מֻתָּר לִקָּבֵר בּוֹ.",[],["\u0003חולקים. \u0004 כתב מהרש\"ל שהעולם נוהגים איסור לישב על הקבר ובהג\"א כ' דאסור למכור מצבה שנשברה וגם אסור להשען על המצבה משום דאסור בהנאה ומטעם זה אסור לדרוך על הקברים. אך נושאי המטה שדורסין לפי שעה בהילוכן עם המטה משמע דאין איסור כשדורסין על הקברים. עכ\"ל הט\"ז:","\u0003לפנותו. \u0004 ולא חיישינן שמא מת מצוה הוא דמ\"מ קלא אית ליה. ש\"ך \u0005(והוא מפרק נגמר הדין)\u0006:","\u0003בהנאה. \u0004 שאין אדם אוסר דבר שאינו שלו ומיירי בקבר של בנין דאלו במחובר בלא\"ה אין מחובר נאסר וכ\"כ נ\"י וקבר הידוע היינו שנקבר שם מדעת בעל השדה. ש\"ך:","\u0003ואסור. \u0004 דרבנן גזרו עליו טומאה עולמית כדי שלא יפנוהו:","\u0003והרמב\"ם. \u0004 כ' הש\"ך דהכי פירושו קבר הנמצא דהיינו שלא היינו יודעים שהיה שם קבר מותר לפנותו דמסתמא נקבר שם שלא מדעת בעל השדה כיון שלא היה ידוע פנוהו מקומו טמא וכו' כלומר השדה שסביבותיו היכא דאיכא למיחש לקברים וקבר הידוע שאין שם אלא הוא לבדו אסור לפנותו פנוהו מקומו טהור וכו' כיון שידוע שאין שם קברים אחרים. ב\"י עכ\"ל:","\u0003במקום\u0004 \u0003שמצאו. \u0004 וא\"צ להוליכו לקברות וכתב מהרש\"ל ומה שהאידנא אין נזהרים בזה הוא לפי שאין הארץ שלנו ואין לנו רשות לקבור בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יוציאו אותו כדי לפשוט בגדיו מעליו או משום זלזול ע\"כ מוליכין אותו לבה\"ק מיוחד עכ\"ל:","\u0003שנפל. \u0004 במהרי\"ל כתב דאם דם יצא ממנו אז אין לטהר אותו כי הדם יסתלק ממנו אך יקברוהו במלבושיו. וכתב הב\"ח ונראה דהיינו דוקא כשמת במלבושיו אבל בנפלו ולא מת מיד אלא לאחר כמה ימים שכבר פשט מלבושיו וגם אין דם יוצא ממנו שכבר פסק ומת על מטתו מכח אותה נפילה אז ודאי מטהרין אותו ועושין לו תכריכין כשאר המתים על מטתן. ובזה יש חילוק בין נפל מן הגג להרוג דאלו בהרוג ביד עובד כוכבים אע\"פ שבשעה שמצאוהו כבר פסק הדם קוברים אותו כאשר נמצא כדי להעלות חימה ולנקום נקם וזה לא שייך בנפל מן הגג. וכן יולדת שמתה ודם יוצא ממנה אין לטהרה אלא קוברים אותה בלבושיה אבל אם לא מתה רק אחר כמה ימים ושבועות וכבר פסק הדם נוהגים עמה כמו בשאר מתים לטהרה ולעשות לה תכריכין. שוב מצאתי הטעם גבי הרוג דהרי כבר יצאו כל הדמים ממנו והם מובלעים בבגדיו וחיישינן שמא נבלע בתוכן רביעית דם שהנפש יוצאת בו ע\"כ יקברוהו כמו שמצאוהו ולא יחלצו אפי' מנעליו דשמא דם יציאת הנפש הוא בתוך המנעלים וע\"כ נוהגים בהרוג לחפור במרא וחצינא בקרקע במקום שנמצא שם ההרוג וכן כל דמו שיצא ממנו במקום קרוב לו וקוברין העפר שנבלע בו דמו עם ההרוג דשמא באותו הדם יש דם הנפש. ומזה הטעם ג\"כ במי שנפל מן הגג או נפל עליו הבית ומת ונעשה בגופו פצעים וחבורות ויוצא מהם דם וה\"ה ביולדת דרובם אינן מתים אלא מחמת שנעשה באברים הפנימיים שלה פצעים כשכורעת לילד ונבלע דם בכתונת שעל גופה ובשאר בגדים שעליה והדמים שיצאו עם יציאת הנפש נבלעו ג\"כ בתוכן משא\"כ כשאין שם פצעים ולא יצא מהם דם כלל אין קוברין אותם בבגדיהם אלא בתכריכים כשאר מתים ומטהרין אותם. ולפ\"ז מי שמת בדרך בקור גדול נראה דפושטין מלבושיו ומטהרין ומלבישין אותו תכריכים כיון שאין בו פצעים ולא יצא ממנו דם וכן מי שנטבע במים בבגדיו פושטין בגדיו ומטהרין אותו וגם חכריכים מלבישין אותו וכמ\"ש בסוף ס' מהרי\"ל ע\"כ ואני ראיתי בהרבה קהלות נוהגין לטהר כל יולדת ולהלבישה תכריכים ואחר כך מלבישין בגדיה למעלה מהתכריכין ולמעלה מהם הסדין. עכ\"ל הש\"ך:","\u0003מותר. \u0004 שהרי אין אדם אוסר דבר שאינו שלו ולאו כל כמיניה לאסור של רבים. ש\"ך:","\u0003התבן וכו'. \u0004 דגנאי הוא למת לעשות לו כן. ש\"ך:"]],["הַחוֹפֵר כּוּךְ לַמֵּת, פָּטוּר מִקְּרִיאַת שְׁמַע וּמִן הַתְּפִלָּה וּמִן הַתְּפִלִּין וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. וְאִם הֵם שְׁנַיִם, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, אֶחָד עוֹלֶה וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל, וְחוֹזֵר זֶה וְחוֹפֵר, וְעוֹלֶה חֲבֵרוֹ וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל. וְדַוְקָא כּוּךְ, דְּלֹא חָפִיר לֵיהּ אֶלָּא חַד, אֲבָל אִם הָיָה מָקוֹם שֶׁשְּׁנַיִם יְכוֹלִים לְהִתְעַסֵק בּוֹ כְּאֶחָד, פְּטוּרִים. \u0010c0\u0011\nמַרְחִיקִין הַקְּבָרוֹת מֵהָעִיר חֲמִשִּׁים אַמָּה.",[],["\u0003מרחיקין. \u0004 כתב הלבוש הטעם שלא יפגעו בו תמיד ויתעצבו ולא דק שהטעם הוא מפני שריחה רע. וכן משמע בש\"ס דב\"ב פ' לא יחפור. וכן פירש\"י ושאר מפרשים וכ\"כ הרמב\"ם והמחבר בח\"מ סי' קנ\"ה סכ\"ב עכ\"ל הש\"ך \u0005(ואפשר לומר דגם בעל הלבוש ס\"ל האי טעמא משום דריח רע שהרי כתבו בלבוש עיר שושן גבי נזקי שכנים סי' קנ\"ה אלא הא קמ\"ל דאפי' היכא דלא שייך האי טעמא דריח רע כגון שחפרו וקברו אותו בקרקע עמוק עמוק שאין ריח רע יוצא ממנו או באופן אחר דלא שייך בו טעם הנ\"ל מ\"מ תיקנו שירחיק חמשים אמה כדי שלא יראו תמיד ויתעצבו ואולי עי\"כ יעורר עצמו לעשות אבל ובכיה יותר מזמן שקבעו חז\"ל ויענש כמ\"ש חז\"ל ע\"כ הוא בכלל תקנות חז\"ל שלא יתאבל יותר מדאי. וכתב בה\"י אבל במדינתנו לא שייך דין זה בקצת מקומות הקברות באמצע העיר ובקצת מקומות הוא רחוק הרבה מהעיר לפי השתדלות מן השרים)\u0006:"]],["הַמּוֹכֵר קִבְרוֹ וְדֶרֶךְ קִבְרוֹ, מְקוֹם מַעֲמָדוֹ וּמְקוֹם הֶסְפֵּדוֹ, בָּאִים בְּנֵי \u0010c0\u0011 הַמִּשְׁפָּחָה וְקוֹבְרִין אוֹתוֹ בְּעַל כָּרְחוֹ שֶׁל לוֹקֵחַ, וּמַחֲזִירִין אֶת דָּמָיו.\nאִשָּׁה שֶׁיָּרְשָׁה קֶבֶר מִמִּשְׁפַּחְתָּהּ, נִקְבֶּרֶת בְּתוֹכוֹ הִיא, אֲבָל לֹא יוֹצְאֵי יְרֵכָה; אֶלָּא אִם כֵּן רָאֲתָה אוֹתָם בְּחַיֶיהָ.\nאָבִיהָ אוֹמֵר: תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: תִּקָּבֵר אֶצְלִי, תִּקָּבֵר אֵצֶל בַּעֲלָהּ. וְיֵשׁ גּוֹרְסִין תִּקָּבֵר אֵצֶל אָבִיהָ. וְאִם יֵשׁ לָהּ בָּנִים, וְאוֹמֶרֶת: אֵצֶל בָּנַי, קוֹבְרִין אוֹתָהּ אֵצֶל בָּנֶיהָ.\nאָבִיהָ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, קוֹבְרִים אוֹתָהּ אֵצֶל בַּעֲלָהּ.",[],["\u0003המשפחה. \u0004 שגנאי הוא להם שבני המשפחה לא יהיו קבורים במקום אחד כמנהגם. ש״ך \u0005(ואע״ג דמי שצוה שלא יספידוהו שומעין לו שאני התם דאמר כן בשעת מיתה אבל הכא זוזי אנסוהו. א״נ התם לדידיה לחוד אבל הכא מקום הספדו יורשיו ובני ביתו נספדים שם ואיכא פגם שלהן ועי' בתוס' פרק יש בכור (בכורות דף נ״ב) ד״ה באין בני משפחה)\u0006:"]],["קוֹבְרִים מֵתֵי עוֹבְדֵי כּוֹכָבִים וּמְנַחֲמִים אֲבֵלֵיהֶם, מִפְּנֵי דַּרְכֵי שָׁלוֹם.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת וּתְפִלִּין בְּרֹאשׁוֹ, מִשּׁוּם לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006, וְאִם הֵם מְכֻסִים, מֻתָּר.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת, אוֹ שֶׁל קֶבֶר, וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ, וְיִקְרָא בּוֹ אוֹ יִתְפַּלֵּל, וְהוּא הַדִּין עַל פֶּה אָסוּר לִקְרוֹת, אֶלָּא אִם כֵּן לִכְבוֹד הַמֵּת, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005וְעַיֵּן לְעֵיל סִימָן שד\"מ סָעִיף י\"ז.\u0006\nמֻתָּר לִכָּנֵס לְבֵית הַקְּבָרוֹת אוֹ לְתוֹךְ ד' אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר, וְהוּא לָבוּשׁ צִיצִית, וְהוּא שֶׁלֹּא יְהֵא נִגְרָר עַל הַקֶּבֶר. אֲבָל אִם נִגְרָר, אָסוּר מִשּׁוּם: לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּימֵיהֶם שֶׁהָיוּ מַטִּילִים צִיצִית בַּמַּלְבּוּשׁ שֶׁלּוֹבְשִׁים לְצֹרֶךְ עַצְמָן, אֲבָל הָאִדָּנָא שֶׁאֵין אָנוּ לוֹבְשִׁין אוֹתוֹ אֶלָּא לְשֵׁם מִצְוָה, אָסוּר, אֲפִלּוּ אֵינָם נִגְרָרִים. וְהָנֵי מִלֵּי כְּשֶׁהַצִּיצִיּוֹת מְגֻלִּים, אֲבָל אִם הֵם \u0010c0\u0011 מְכֻסִים, מֻתָּר.\nיֵשׁ נוֹהֲגִין לִקְשֹׁר שְׁנֵי צִיצִיּוֹת שֶׁבִּשְׁנֵי כְּנָפַיִם זֶה עִם זֶה כְּשֶׁנִּכְנָסִים לְבֵית הַקְּבָרוֹת, וְלֹא הוֹעִילוּ כְּלוּם בְּתַקָּנָתָם \u0005וְעַיֵּן בא\"ח סִימָן כ\"ג.\u0006\nכֵּיוָן שֶׁהִרְחִיק ד' אַמּוֹת, קוֹרֵא וּמִתְפַּלֵּל, וַאֲפִלּוּ רוֹאֶה הַקֶּבֶר אוֹ בֵּית הַקְּבָרוֹת. וְאִם יֵשׁ שָׁם מְחִצָּה, מֻתָּר אַחַר הַמְּחִצָּה, סָמוּךְ אֲפִלּוּ תּוֹךְ ד' אַמּוֹת לַקֶּבֶר.",[],["\u0003מכוסים. \u0004 כתב מהרש\"ל והעולם נוהגין היתר בטלית קטן וכ\"כ הב\"ח וסיים הטעם כיון שהציצית מכוסים וכתב עוד דה\"ה לקדיש צריך להרחיק ד\"א עכ\"ל הש\"ך:"]],["בֵּית הַקְּבָרוֹת, אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ; \u0005כְּגוֹן לִפָּנוֹת שָׁם (כָּל בּוֹ)\u0006 אוֹ לֶאֱכֹל וְלִשְׁתּוֹת שָׁם, וְאֵין קוֹרִין וְאֵין שׁוֹנִין שָׁם \u0005(סמ\"ג)\u0006, וְאֵין מְחַשְּׁבִין שָׁם \u0010c0\u0011 חֶשְׁבּוֹנוֹת. \u0005(בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 ; וְאֵין מַרְעִין בָּהֶם בְּהֵמוֹת; וְאֵין מוֹלִיכִין בָּהֶם אַמַּת הַמַּיִם; וְלֹא יְטַיֵּל בָּהֶם לְקַפַּנְדְרִיָא \u0005(פי' לְמַעֲבָר מִצַד זֶה לְצַד זֶה)\u0006 ; וְלֹא יְלַקֵּט מֵהֶם עֲשָׂבִים; וְאִם לִקֵּט, שֶׁצָּרִיךְ לְלָקְטָן לְצֹרֶךְ בֵּית הַקְּבָרוֹת, שׂוֹרְפָן בִּמְקוֹמָן. \u0005הַגָּה: וְכֵן אֵין לִקַּח מִקַּרְקַע עוֹלָם שֶׁל קֶבֶר, אַף עַל גַּב דְּמֻתָּר בַּהֲנָאָה (כֵּן מַשְׁמָע מֵהָרֹא\"שׁ וְהַמָּרְדְּכַי)\u0006. וְכָל זֶה אֵינוֹ אֶלָּא מִשּׁוּם כְּבוֹד הַמֵּתִים, וְלָכֵן אִם צָרִיךְ אוֹתוֹ לִרְפוּאָה, שָׁרֵי \u0005(ג\"ז בְּמָרְדְּכַי)\u0006. וְכֵן מֻתָּר לֵהָנוֹת מֵהָעֲשָׂבִים שֶׁעַל הַקְּבָרוֹת אוֹ פֵּרוֹת אִילָנוֹת שֶׁעֲלֵיהֶם לְצֹרֶךְ הַקְּבָרוֹת, כְּגוֹן שֶׁהַמּוֹשֵׁל עוֹבֵד כּוֹכָבִים מַרְעֶה בְּהֵמוֹת עַל הַקְּבָרִים וְאִי אֶפְשָׁר לִמְחוֹת בְּיָדוֹ כִּי אִם בְּהוֹצָאָה מְרֻבָּה, וְאֵין יַד הַקָּהָל מַשֶּׂגֶת, מוֹכְרִים דְּבָרִים אֵלּוּ כְּדֵי לְהַצִּיל הַקְּבָרוֹת מִיַּד עוֹבְדֵי כּוֹכָבִים, שֶׁזֶּהוּ כְּבוֹד הַמֵּתִים \u0005(ת\"ה סִימָן רפ\"ד ומהרי\"ו סִימָן נ')\u0006. וְאִם אֵין דְּבָרִים עַל הַקְּבָרוֹת לִמְכֹּר לְצֹרֶךְ הַהוֹצָאָה, אִם יַד הַקָּהָל מַשֶּׂגֶת וְשֶׁבְּיָדָם לִמְחוֹת בְּהוֹצָאָה מוּעֶטֶת, צְרִיכִין לִמְחוֹת, אִם אֵין חֲשָׁשׁ בַּדָּבָר שֶׁהַמּוֹשֵׁל יִתְגָּרֶה בָּהֶם עַל יְדֵי זֶה; אֲבָל בְּלָאו הָכֵי אֵין צְרִיכִין לִמְחוֹת \u0005(ג\"ז שָׁם)\u0006.\nאִילָנוֹת שֶׁנּוֹטְעִין בְּבֵית הַקְּבָרוֹת, \u0010c1\u0011 מֻתָּר לְלַקֵּט פֵּרוֹתֵיהֶם, מֵאַחַר שֶׁאֵינָם עַל הַקְּבָרוֹת עַצְמָם.\nקֶבֶר חָדָשׁ, נִמְדָּד וְנִמְכָּר וְנֶחְלָק; וְהַיָּשָׁן, אֵינוֹ \u0010c2\u0011 נִמְדָּד וְלֹא נִמְכָּר וְלֹא נֶחְלָק.",[],["\u0003חשבונות. \u0004 אפילו הם של רבים. ש\"ך:","\u0003ללקט. \u0004 כ' הב\"ח מה שנוהגין הגבאים ללקוט הפירות למוכרם והדמים לצדקה ומקצתם נותנים לעובד כוכבים שומר בית הקברות וגם עושה לו העובד כוכבים גן בבה\"ק צריך ליזהר שלא יהא אילן נטוע ולא הגן זרוע אלא במקום שאין שם ספק קבר עכ\"ל:","\u0003נמדד. \u0004 כתב הטור פי' שאין מודדין אותו כמה מתים נקברים במקצתם שיתנו אותה מדה למתים אחרים כנגדו ולא נמכר משום פגם משפחה ולא נחלק בין היורשין אלא כולם נקברים שורות שורות לעצמן והכל משום כבודן של מתים ובה\"ק חדש שאין נקבר בו אלא א' לא חששו לכבודו עכ\"ל:"]],["הַכֹּהֵן מֻזְהָר שֶׁלֹּא \u0010c0\u0011 לִטָּמֵא בְּמֵת, וְלֹא לְכָל טֻמְאוֹת הַפּוֹרְשׁוֹת מִמֶּנּוּ, וְלֹא \u0010c1\u0011 לְגוֹלָל, וְלֹא לְדוֹפֵק, וְלֹא לְאֵבֶר מִן הַחַי שֶׁאֵין בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה אִם הָיָה מְחֻבָּר, וְלֹא לְאִילָן \u0010c2\u0011 הַמֵּסֵךְ עַל הָאָרֶץ וַעֲנָפָיו מֻבְדָּלִים זֶה מִזֶּה וְטֻמְאָה תַּחַת אֶחָד מֵהֶן וְאֵין יָדוּעַ תַּחַת אֵיזֶה, אוֹ אֲבָנִים הַיּוֹצְאִים מֵהַגָּדֵר וְטֻמְאָה תַּחַת אֶחָד מֵהֶם וְאֵין יָדוּעַ תַּחַת אֵיזֶה, וְכֵן שָׂדֶה שֶׁנֶּחֱרַשׁ בּוֹ קֶבֶר וְאֵין יָדוּעַ מְקוֹמוֹ וְכָל אֶרֶץ הָעַמִּים, אָסוּר לְכֹהֵן לִטָּמֵא בָּהֶן. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּכֹהֲנִים אֲסוּרִים לִטָּמֵא לְחֶרֶב שֶׁנִּטְמָא בְּמֵת (כָּל בּוֹ בְּשֵׁם סֵפֶר יְרֵאִים ותשו' רַשְׁבָּ\"א בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006, וְיֵשׁ מְקִלִּין \u0005(תְּשׁוּבַת רַשְׁבָּ\"א שָׁם בְּשֵׁם הָרַאֲבַ\"ד וְעַיֵּן בתוס' דְּנָזִיר בַּאֲרִיכוּת)\u0006, וְכֵן נָהֲגוּ לְהָקֵל וְאֵין נִזְהָרִין מִזֶּה.",[],["\u0003במת. \u0004 אפי' נפל כדאיתא בפ' בתרא דאהלות שמא קברו בו נפלים. ט\"ז \u0005(אבל טומאת נבילות ושרצים אין הכהן מוזהר מליגע בהן)\u0006 \u0005(בה\"י)\u0006:","\u0003לגולל. \u0004 הוא אבן שנותנים על הקבר לציון. ודופק היינו שלפעמים סומכין האבן באבנים קטנים טור \u0005(ורש\"י פי' גולל זה כיסוי הארון ודופק הוא דופן של צדדים. כתובות דף ד')\u0006:","\u0003המיסך: \u0004 \u0005(אע\"פ שאין כאן אלא ספק טומאה הכהן מוזהר עליו)\u0006 ומוכח מכאן דאילן המיסך על המת דיוכל לעמוד תחת ענפיו שאינם מאהילין על המת דהרי כאן לא נאסר לעמוד תחת האילן אלא מטעם דאינו ידוע תחת איזה. פרישה:"]],["מִי שֶׁנִּשְׁבְּרָה מַפְרַקְתּוֹ \u0010c0\u0011 וְרֹב בָּשָׂר עִמָּהּ, וְכֵן מִי שֶׁנִּקְרַע מִגַּבּוֹ כְּדָג, אֲפִלּוּ עֲדַיִן הוּא חַי, חָשִׁיב כְּמֵת, וּמְטַמֵּא. אֲבָל גּוֹסֵס, וּמִי שֶׁנִּשְׁחֲטוּ בּוֹ ב' סִימָנִים אוֹ פָּצוּעַ פְּצָעִים הַרְבֵּה, אֵינָם מְטַמְּאִין, עַד שֶׁתֵּצֵא נַפְשָׁם; וּמִכָּל מָקוֹם אָסוּר לִכָּנֵס לְבַיִת שֶׁיֵּשׁ בּוֹ גּוֹסֵס. \u0005וְיֵשׁ מַתִּירִין, (ר\"ן סוֹף מַ\"ק וּמָרְדְּכַי פֶּרֶק אֵלּוּ מְגַלְּחִין בְּשֵׁם בה\"ג)\u0006, וְטוֹב \u0010c1\u0011 לְהַחְמִיר.",[],["\u0003ורוב. \u0004 ומשמע בש\"ס דחולין דבזקן אפי' בלא רוב בשר מטמא באהל וכ\"כ מהרש\"ל פ\"ק דחולין. ומשמעותו התם דאם נעשה גיסטרא שנחתך לרחבו בצואר כולה או בשדרה עד חללה או שנחלק לשנים מטמא באהל עכ\"ל הש\"ך:","\u0003להחמיר. \u0004 והב\"ח כתב דמדינא צריך ליזהר ואין כאן מקום לפסוק לקולא ע\"ש מיהו נראה דאין צריך להקיצו ולהגיד לו כשיש גוסס כמה שצריכים לעשות כשיש מת כמו שכתב בסימן שע\"ב וכן אם הגידו לו והוא ערום מותר להמתין עד שילביש עצמו ואח\"כ יצא עכ\"ל הש\"ך:"]],["אָסוּר לְכֹהֵן \u0010c0\u0011 לִכָּנֵס תַּחַת אֹהֶל שֶׁהַמֵּת תַּחְתָּיו, אֲפִלּוּ הוּא גָּדוֹל הַרְבֵּה, וַאֲפִלּוּ לְבַיִת אַחֵר אוֹ לַעֲלִיָּה אַחֶרֶת, הַפְּתוּחִים לְאוֹתוֹ בַּיִת \u0010c1\u0011 בְּנֶקֶב שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח, וּבַיִת לְאוֹתוֹ בַּיִת, עַד עוֹלָם; וְאִם סָתַם הַנֶּקֶב, מֻתָּר לוֹ לִכָּנֵס לַבַּיִת הָאַחֵר, שֶׁהַסְתִימָה חוֹצֶצֶת, אֲפִלּוּ לֹא בִּטְּלוּ לִהְיוֹת שָׁם עוֹלָמִית. וְהָנֵי מִלֵּי, שֶׁסָתַם כָּל הַנֶּקֶב; אֲבָל אִם לֹא סָתַם כָּל הַנֶּקֶב, אֶלָּא מִעֲטוֹ מִטֶּפַח, אִם נְתָנוֹ לִהְיוֹת שָׁם עוֹלָמִית, מְמַעֵט וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה שֶׁלֹּא תַּעֲבֹר; וְאִם לָאו, אֵינוֹ מְמַעֵט. \u0005הַגָּה: וְכָל דָּבָר הַמְקַבֵּל טֻמְאָה אֵינוֹ חוֹצֵץ בִּפְנֵי הַטֻּמְאָה (הַגָּהַת אַלְפָסִי פֶּרֶק בְּנֵי הָעִיר ובהל' טֻמְאָה לְהָרִי\"ף וְרַמְבַּ\"ן וְרֹא\"שׁ וּמָרְדְּכַי רֵישׁ פֶּרֶק לֹא יַחְפֹּר)\u0006. וְלֹא מִקְרֵי סְתִימָה בְּחַלּוֹן, אֶלָּא אִם כֵּן יָכוֹל לַעֲמֹד בְּלֹא \u0010c2\u0011 סְמִיכָה \u0005(ג\"ז שָׁם)\u0006.\nאֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה וְאֵין בָּהּ פּוֹתֵחַ טֶפַח, וְכַזַּיִת מֵהַמֵּת לְמַטָּה בַּבַּיִת כְּנֶגֶד הָאֲרֻבָּה, הַבַּיִת טָהוֹר \u0010c3\u0011 וְהָעֲלִיָּה טְמֵאָה.\nשְׁנֵי חֲדָרִים \u0010c4\u0011 פְּתוּחִים לְבַיִת, וּבְכָל אַחַת חֲצִי זַיִת מֵהַמֵּת, וְדַלְתוֹתֵיהֶם נְעוּלִים, הַבַּיִת \u0010c5\u0011 טָמֵא וְהֵם טְהוֹרִים; וְאִם נִפְתְחוּ, גַּם הֵם טְמֵאִים.\nחָצֵר הַמֻּקֶּפֶת זִיזִין וְאַכְסַדְרָאוֹת, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, אִם כָּל פִּתְחֵי הַבָּתִּים וְהַחַלּוֹנוֹת נְעוּלִים, טֻמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין וְהָאַכְסַדְרָאוֹת; \u0005וְהַטַּעַם, מִשּׁוּם דְּהוֹאִיל וְסוֹף הַטֻּמְאָה לָצֵאת דֶּרֶךְ שָׁם, רוֹאִין כְּאִלּוּ יָצְאָה; וְלָכֵן יֵשׁ \u0010c6\u0011 מַחְמִירִין לְכֹהֲנִים לֵילֵךְ דֶּרֶךְ שַׁעַר הָעִיר שֶׁסּוֹף הַמֵּת לָצֵאת מִשָּׁם (פִּסְקֵי מהרא\"י סִימָן כ\"ה וְכָל בּוֹ)\u0006, וְיֵשׁ מַתִּירִין \u0005(שָׁם הֵבִיא בְּשֵׁם י\"א)\u0006, וְהַמֵּקֵל לֹא הִפְסִיד בְּמָקוֹם שֶׁלֹּא נָהֲגוּ לְהַחְמִיר; וְאִם נִפְתַּח חַלּוֹן אוֹ \u0010c7\u0011 פֶּתַח מִצַּד הָאַחֵר, וְאוֹתָם שֶׁל צַד הֶחָצֵר כֻּלָּם נְעוּלִים, אֵין הַטֻּמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין. וְאִם נִפְתַּח גַּם כֵּן אֶחָד מֵהֶן לְצַד \u0010c8\u0011 הַזִּיזִין, הַטֻּמְאָה יוֹצֵאת מֵהַבַּיִת לְתַחַת הַזִּיזִין. וְכֵן אִם טֻמְאָה תַּחַת הַזִּיזִין, נִכְנֶסֶת מִתַּחְתֵּיהֶן \u0010c9\u0011 לַבַּיִת; לָכֵן גַּגִּים הַבּוֹלְטִים לְמַעְלָה לְחוּץ עַל פִּתְחֵי הַבָּתִּים, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, כָּל הַבָּתִּים שֶׁפִּתְחֵיהֶם \u0010c10\u0011 פְּתוּחִים, טְמֵאִים. \u0005הַגָּה: ב' גַּגִּין שֶׁאֵין נוֹגְעִין זֶה בָּזֶה, אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶם רַק פָּחוֹת מִג', לֹא הָוֵי חִבּוּר לַטֻּמְאָה, דְּלֹא אַמְרִינָן לָבוּד לְהַחְמִיר (מהרי\"ו בִּפְסָקָיו)\u0006. וְאִם הָיוּ זֶה לְמַעְלָה מִזֶּה, אַף עַל פִּי שֶׁאֵינָן נוֹגְעִים, אַמְרִינָן: \u0010c11\u0011 חָבוּט רָמֵי, וּכְאִלּוּ נוֹגְעִים \u0005(נ\"י בְּהִלְכוֹת טֻמְאָה רי\"ף)\u0006. הַכֹּהֲנִים אֵינָן יְכוֹלִין \u0010c12\u0011 לָכֹף לִקְרוֹבֵי הַמֵּת שֶׁיּוֹצִיאוּ הַמֵּת מִמְּקוֹמוֹ, כְּדֵי שֶׁהֵם יִהְיוּ רַשָּׁאִים לִכָּנֵס לְבֵיתָם, אִם לֹא בְּמָקוֹם שֶׁדֶּרֶךְ לְהוֹצִיא כָּל הַמֵּתִים \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ה)\u0006.\nאָסוּר \u0010c13\u0011 לִקְרַב בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאֵין הַקֶּבֶר מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת י' טְפָחִים, אֲבָל אִם הוּא מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת עֲשָׂרָה טְפָחִים, אוֹ בְּחָרִיץ עָמֹק י' טְפָחִים, אֵין צָרִיךְ לְהַרְחִיק מִמֶּנּוּ אֶלָּא ד' טְפָחִים. \u0005וּמֻתָּר לְכֹהֵן לַעֲמֹד אֵצֶל בַּיִת שֶׁיֵּשׁ בּוֹ מֵת, וּמֻתָּר לִגֹּעַ בִּכְתָלָיו, וּבִלְבַד שֶׁלֹּא יְהֵא שׁוּם דָּבָר מַאֲהִיל עָלָיו (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן קל\"ו)\u0006.\nמֵת הַמּוּנָח בִּסְפִינָה, אִם הִיא קְטַנָּה שֶׁמִּתְנַדְנֶדֶת כְּשֶׁדּוֹרְכִין בָּהּ, אָסוּר לְכֹהֵן \u0010c14\u0011 לִכָּנֵס בָּהּ.",[],["\u0003ליכנס. \u0004 כתב הרוקח אשת כהן המעוברת מותרת ליכנס באוהל המת דס\"ס הוא שמא נפל או שמא נקבה היא:","\u0003בנקב. \u0004 כתב הט\"ז דהיינו אם הוא במקום א' אבל אם אינו במקום א' אלא ע\"י צירוף יש טפח כגון מה שקורין גיגאטי\"ר שעשוי ע\"י סירוג אין מביא את הטומאה והוא משנה פי\"ג דאהלות הסירוגות ב\"ה אומרים עד שיהא כמלא מקדח במקום א' ומבואר שם דבין להביא את הטומאה בין להוציא עכ\"ל:","\u0003סמיכה. \u0004 כ' הט\"ז דהתוספות כתבו הטעם דכל שצריך סמיכה מקרי סתימת עראי ופשוט הוא לכ\"ע כל שמושיב באותו חלון עצים ואבנים כ\"כ הרבה עד שכותלי החלון מחזיקים אותם זה ודאי מהני וחוצץ דאין זה בכלל סמיכה כלל. ומעשה שהיה בטומאה שהיתה בבית סמוך לבהכ\"נ באופן שהיתה נכנסת דרך חלון בהכ\"נ של נשים וצוה מורה א' לסתום החלון באותו פרוכת קטן שתלוי שם בקרסי ברזל תמיד שהוא לצניעות הנשים וכו' ואמרתי שטעה המורה דבהדיא אמרינן במתני' דסדין שאינו עשוי כאהלים אינו חוצץ ועוד דמחמת דטבעות של ברזל הם עומדים וכלים אינם חוצצין ע\"ש שמאריך בכמה ראיות לסתור דברי המורה הנ\"ל \u0005(ובלקט הקמח כתב שמעשה כזה אירע בעה\"ק בבהכ\"נ הגדולה בשבת קודש והורו גאוני ההוראה לסתום החלון שהיה טפח על טפח בצמר חדא משום דהוי ראוי לשכיבה ולית ביה משום מוקצה ומשום בנין ותוספת בנין מותר וברשת של עץ ג\"כ התירו לסתום הן מפני כבוד הצבור שלא יתפללו במקום שהטומאה נכנסת דרך החלון ואין ראוי להניחם בלא ברכת כהנים באהבה עכ\"ל)\u0006 וכתב עוד דלא מועיל חציצת דלת או חלון כל שאינו יכול לעמוד בלא צירים של ברזל או שאר דבר של ברזל אע\"פ שהם לצורך קרקע וזה מועיל שלא יקבלו טומאה מ\"מ אינם חוצצים \u0005(ובנה\"כ השיג עליו בכל זה ופסק דשפיר חוצץ ע\"ש באורך)\u0006 עוד כתב הט\"ז ונראה דאם יש סתימה בחלון של ברזל שהוא עשוי כמו סבכה שקורין בלשון אשכנז גיגאטי\"ר והוא של ברזל אינו מועיל כיון שהוא מקבל טומאה ואינו עשוי כעין אוהל \u0005(וכתב נה\"כ דצ\"ל שהגיגאטי\"ר אינו קבוע בכותל דאל\"כ אינו מקבל טומאה וחוצץ ועיין שם)\u0006:","\u0003והעליה. \u0004 הטעם כתב הש\"ך משום דטומאה בוקעת ועולה כיון שהיא מונחת תחת הארובה ואין הטומאה מתפשטת לצדדי הבית הואיל שיש מקום לטומאה לעלות לארובה שכנגדה ואינה חוזרת ויורדת לבית כיון שאין בארובה טפח שאם היה בה טפח הוה ליה חשבינן בית ועליה כמו חדר א' וכתב הט\"ז וא\"ל שיהיה פתח הבית ההוא טמאה משום שסוף הטומאה לצאת דרך אותו הפחח כמ\"ש בס\"ד דכאן שאין שם רק כזית מן המת ואין עליו אהל הוה כמונח ברה\"ר ואינו מטמא כלל בבית ומזה למדנו שאם יש מת בבית ומונח בחדר שאין עליו אהל אין לכהן להיות בכל הבית הן מטעם שהטומאה חוזרת ויורדת והן מטעם שסוף הטומאה לצאת דרך הפתח דלא הקילו כאן אלא אם אין פתוח רק פחות מטפח עכ\"ל:","\u0003פתוחים. \u0004 היינו כששני החדרים כל א' מהם פתחו פתוח לבית בפ\"ע ושניהם הם לפנים מן הבית. ש\"ך:","\u0003טמא. \u0004 דסוף הטומאה לצאת ורואה אני כאלו שני חצאי הזיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולות אבל כשנפתחו חזרה הטומאה מן הבית לחדרים. ש\"ך:","\u0003מחמירין. \u0004 כ' הש\"ך אמנם אין להחמיר בבית של צדוק הדין דאדרבה אותו הפתח בא לטמא את האוהל פסקי מהרא\"י וכ' בס' מעדני מלך שטעם זה יספיק אם אין בו אלא פתח א' שבו מכניסין ומוציאין את המת אבל אם יש בו ב' פתחים שבפתח הא' מכניסין ובהשני מוציאין כמו שיש בבית צדוק הדין שבק\"ק פראג יש להחמיר שאין לכהנים ליכנס באותו הפתח שמוציאין ממנו המת עכ\"ל והט\"ז כ' דהעיקר תלוי בפתח הבית שהמת בתוכו דסוף הטומאה לצאת דרך שם ע\"כ מטמא אף שהוא נעול אבל בבתים אחרים מה מעלה יש בנעילתם וצ\"ל דמ\"ש המחבר אם כל פתחי הבתים נעולים הוא לאו דוקא עכ\"ל \u0005(ובת' ח\"צ סי' ק\"ג חולק ע\"ז ואחר שהביא ראיות לדבריו כ' וז\"ל הדבר ברור דבבית צדוק הדין אין לחוש כלל אם יכנסו בו הכהנים אף שיש מת בעיר יכולים הכהנים להקדים ולכנוס בו בין שיש לו פתח א' ובין שיש לו ב' פתחים וע\"ש עוד בזה)\u0006:","\u0003פתח. \u0004 שיש בו ד' על ד' כן הוא בלבוש:","\u0003הזיזין. \u0004 פירש הט\"ז דהיינו אותו החדר שהמת בתוכו נפתח גם כן לצד הזיזין באופן שנפתח אותו הבית משני צדדיו:","\u0003לבית. \u0004 פי' לבית שפתחו פתוח לצד הזיזין. ט\"ז:","\u0003פתוחים. \u0004 כתב הש\"ך אבל אם הם סתומים טהורים ולפ\"ז אף כשהטומאה באה באיזה בית אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת מהן עד אחר הוצאת המת א\"צ לצאת מבתיהן ולפ\"ז כהן שהוא בבית או חדר שהטומאה נוגע אליו והוא נעול בדלת וחלונות ונודע לו שהגיע הטומאה אליו אסור לצאת מן החדר עד אחר הוצאת המת שהרי כל זמן שלא נפתח החדר לא נכנסת הטומאה לתוכו וכשיפתח תכנס הטומאה לתוכו ובדרישה כתב וז\"ל וגדולה מזאת עשיתי במת עמי ביום השבת וצויתי להוציאו ולהניחו במרתף שתחת הבית ופתח המרתף לצד חוץ ולא היה גג ע\"ג [פתח] המרתף והכהנים נשארו בבית אלא שיש להקשות ע\"ז בהנחת מת במרתף ודלת המרתף סגור הא בעינן שיהיה ביציאת הקבר פתוח טפח וכמ\"ש בסי' שע\"ב וה\"נ אף שבמרתף יש חלל גדול סביב המת מ\"מ אם אין בהפתח פותח טפח אינם רשאים הכהנים להיות ע\"ג המרתף כל זמן שהוא סגור מיהו אם הדלת שבמרתף עשויה כמו שקורין בל\"א גיגאטי\"ר אף שאין בחור א' טפח מכל מקום כיון שיש בהצטרפות החורין יחד פתוח כמה טפחים יש צד להקל שהוא בכלל יציאתה פותח טפח \u0005(ועיין ש\"א שאלה צ\"ג ושבות יעקב שאלה פ\"ה)\u0006 והט\"ז חולק עליו מטעם שמבואר לעיל שמוכח מהמשנה דאהלות להדיא שאין נקבי הגיגאטי\"ר מצטרפין לטפח גם מ\"ש להתיר להכהנים לסגור פתחיהן וחלונות זהו דבר הנמנע דהא סגירת הפתח הוא ע\"י מפתח גם ע\"י צירים של ברזל וזה אינו חוצץ כמ\"ש לעיל בראיה ברורה ומעולם לא שמענו לנהוג בהיתר זה לכהנים וכמה הקילו רבותינו להיות חס על הכהן שלא להגיד לו עד שילביש עצמו ולא נהגו בהיתר זה אלא ודאי דליתא עכ\"ל \u0005(ובנה\"כ השיג עליו וכתב דהוא נמשך לשיטתו דלעיל ריש הסי' וכבר כתבתי דליתא ואדרבה מהרמב\"ם משמע דחוצץ גם י\"ל דהדרישה מיירי היכא דהדלת יכולה לעמוד בלא סמיכה כמו שעושים ברוב בתים גם יש לתמוה עליו ועל הדרישה היאך סתמו וכתבו דחור שבדלת שיעורו פותח טפח והא דבר זה יש פלוגתא דר\"ע ור\"ט באהלות פי\"ד ור\"ע ס\"ל דשיעורו מלא אגרוף וקי\"ל הלכה כר\"ע מחבירו וכ\"פ הרמב\"ם להדיא ובע\"כ צ\"ל לדבריהם דהיינו דוקא בסתם חור שנעשה בתחלה ע\"י אומן אבל בחור שעשוי להוציא ולהביא דהוי כעשוי לתשמיש מודה ר\"ע לר\"ט אלא דא\"כ ה\"ל לפרושי דמיירי בכה\"ג. וגם הרמב\"ם לא חילק בדבר משמע דס\"ל דבכל גוני שיעורו כאגרוף וצ\"ע עכ\"ל)\u0006 וכ' מהרש\"ל דבמקום שיש עירוב ועשו קורות שיש בהם היקף טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומאה נכנסת תחתיהם הקורה מביאה הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן א\"כ כשיש מת באחד מן הבתים אין כהן רשאי להיות בשום בית מן הבתים שבמבואות המחוברות ע\"י קורה של העירוב \u0005(וכתב הב\"ח שהקורה צריך להיות עגולה כדי שיהיה רחבה טפח)\u0006 וזוכרני כשהיינו לומדים בבית מורי ר\"מ ז\"ל והיה פתח פתוח מחצר הרב לחצר בהכ\"נ ומשקוף הפתח היה מגיע מצד א' תחת תקרת הבית שהיה בו מת ואסר מורי לכהנים לצאת ולבוא דרך אותו הפתח כל זמן שהמת בבית וכ' הדרישה ושמעתי דהיינו דוקא במחיצה שיש עליה גג קטן או מחיצה שמשקוף עליה רוחב טפח וכו' אבל מחיצה מושכת מבית לבית ואין גג עליה וגם אין פתח פתוח בתוך המחיצה אפילו אם הקורה המונח עליה בעובי טפח וגם גגות הבתים משני צדדי המחיצה בקצה שלהם מאהילים עליהם מ\"מ אינו מביא הטומאה כיון דבאמצעית המחיצה אין עליה גג ולא תקרה כיון שאין שם פתח נקרא כסתום באמצע ואין בו כח להוליך הטומאה וכתב הט\"ז דמשמע מדבריו באם יש מחיצה פנויה בלא גג עליה ויש פתח באמצעיתה מביאה את הטומאה מבית לבית כיון שבראש המחיצה יש שם אהל מן הגג של בית הטמא אע\"פ שאין הפתח מגיע עד אותו החלק שהוא תחת הגג ותמיהני מאד על הדבר הזה כיון שיש הפסק בחלק המחיצה מי יכניס הטומאה מן תחת הגג להפתח שבאמצע והלא אפי' ביש הפסק בפחות משלשה לא אמרינן לבוד להחמיר. וע\"כ לא אסר מהרש\"ל אלא שהתקרה היתה מונחת בלא מחיצה תחתיה מן תחת הגג של בית הטמא לתחת הגג של בית אחר נמצא שהיה חלל תחת התקרה בלי הפסק מחיצה סתומה משא\"כ כאן שיש הפסק במחיצה הבנויה על הארץ ואין בליטה טפח סמוך לחלק שתחת הגג השני ודאי אין כאן הבאת טומאה כלל מידי דהוה אשני בתים סמוכים ואין גג בולט למעלה מהם דאין נכנסת הטומאה מבית לבית אע\"פ ששניהם פתוחים דהא גגין בולטין בעינן ונראה דאין לחוש לטומאה כשיש מחיצה בנויה אע\"פ שיש פתח באמצעה לא בתוך המחיצה כולה אא\"כ יש עליה ג\"כ גג קטן או בליטה טפח מן אותו צד שנכנס תחת בית הטמא לחלק המגיע תחת גג השני. והש\"ך כ' ונראה דצריך שיהא הגג אוהל טפח מתחלה עד סוף אבל כל שיש ביניהם הפסק בחומה גבוה אף שהיא עבה כמה טפחים כיון שאין אהל טפח שוב אין לטומאה מקום לילך וכן הסכימו רבים וגדולים וכן המנהג פשוט עכ\"ל:","\u0003חבוט. \u0004 וכ' הב\"ח נ\"ל דאפי' היה גג העליון הרבה למעלה מג\"ט כיון שיש בגגו טפח אמרי' חביט רמי וע\"ש:","\u0003לכוף. \u0004 ונראה דאם הוא נפל דליכא משום כבוד כופין אותו להוציאו ממקומו כדי שיכנסו הכהנים לביתם כ\"כ הב\"ח ואין כן דעת הט\"ז אלא שאם הכהן רוצה לשלוח שם להוציא הנפל אל מקום אחר אין אבי הנפל יכול לעכב כיון שהוא ניזוק וזה לא חסר כלל עכ\"ל \u0005(ובנה\"כ מסכים לדעת הב\"ח ע\"ש)\u0006:","\u0003לקרב. \u0004 וכ' הדרישה מכאן מוכח דאפי' תוך ד' אמות של מת המונח לפנינו אסור לקרב בהן משום דתופס ד\"א או משום גזרה שמא יגע במת עצמו ולא כמו ששמעתי דמקילין לכהן הדורש לעמוד עליו אפי' תוך ד\"א של מת עכ\"ל והש\"ך כתב דנראה דטעם המקילין הוא דיש חילוק בין שהמת מונח בבית אז אסור לכהן לקרב למקום קביעתו שהוא תופס ד\"א אבל במונח על המטה שמוציאין אותו \u0005(וכ\"ש כשנושאין על המטה)\u0006 ובעת צדוק הדין מעמידין אותו אינו תופס דאין זה מיקרי קביעות וכן מחלק הרוקח עכ\"ל:","\u0003ליכנס. \u0004 אפי' חוץ לד\"א של מת כיון שא\"א שלא יסיט הטומאה אבל אם היא גדולה שאינה מתנדנדת כשדורכין בה מותר חוץ לד' אמות של מת עכ\"ל הש\"ך:"]],["אַף עַל פִּי שֶׁהַכֹּהֵן אָסוּר לִכָּנֵס לְבֵית הַפְּרָס, \u0005(פֵּרוּשׁ שָׂדֶה שֶׁנֶּאֱבַד בָּהּ קֶבֶר, וְשֶׁנֶּחֱרַשׁ בָּהּ קֶבֶר, וְשִׁעוּרָהּ מֵאָה אַמָּה)\u0006 אוֹ לְאֶרֶץ הָעַמִּים, אִם הָיָה צָרִיךְ לֵילֵךְ שָׁם לִשָּׂא אִשָּׁה אוֹ לִלְמֹד תּוֹרָה, וְאֵין לוֹ דֶּרֶךְ אַחֶרֶת, יָכוֹל \u0010c0\u0011 לַעֲבֹר דֶּרֶךְ שָׁם, אֲפִלּוּ אִם מוֹצֵא לִלְמֹד בְּמָקוֹם אַחֵר. וְכֵן אָבֵל הָעוֹבֵר דֶּרֶךְ שָׁם, יָכוֹל לֵילֵךְ אַחֲרָיו לְנַחֲמוֹ. וְכֵן מִטַּמֵּא בְּטֻּמְאָה שֶׁל דִּבְרֵיהֶם, לָדִין עִם עוֹבְדֵי כּוֹכָבִים וּלְעַרְעֵר עִמָּהֶם, מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדָם, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: כֹּהֵן שֶׁשּׁוֹכֵב עָרֹם, וְהוּא בְּאֹהֶל עִם הַמֵּת וְלֹא יָדַע, אֵין לְהַגִּיד לוֹ, אֶלָּא יִקְרְאוּ לוֹ סְתָם, שֶׁיֵּצֵא כְּדֵי שֶׁיַּלְבִּישׁ עַצְמוֹ תְּחִלָּה. אֲבָל אִם כְּבַר הִגִּידוּ לוֹ, אָסוּר לְהַמְתִּין עַד שֶׁיִּלְבַּשׁ עַצְמוֹ. \u0010c1\u0011 וְדַוְקָא אִם הוּא בְּאֹהֶל הַמֵּת, שֶׁהוּא טֻמְאָה דְּאוֹרַיְתָא, אֲבָל אִם הוּא בְּבֵית הַפְּרָס אוֹ אֶרֶץ הָעַמִּים, שֶׁהוּא טֻמְאָה דְּרַבָּנָן, יַלְבִּישׁ עַצְמוֹ תְּחִלָּה, דְּגָדוֹל כְּבוֹד הַבְּרִיּוֹת (ת\"ה סִימָן רפ\"ה)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ש\"ג לְעִנְיַן כִּלְאַיִם. כֹּהֵן שֶׁהוּא יָשֵׁן, וּמֵת עִמּוֹ בָּאֹהֶל, צְרִיכִין \u0010c2\u0011 לַהֲקִיצוֹ וּלְהַגִּיד לוֹ כְּדֵי שֶׁיֵּצֵא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ט)\u0006.\nקִבְרֵי עוֹבְדֵי כּוֹכָבִים, נָכוֹן לִזָּהֵר הַכֹּהֵן מִלֵּילֵךְ עֲלֵיהֶם; \u0005(מהר\"מ וְתוס' פ' הַמְקַבֵּל)\u0006 \u0005אַף עַל פִּי שֶׁיֵּשׁ \u0010c3\u0011 מְקִלִּין\u0006 \u0005(רַמְבַּ\"ם והגמי\"י בְּשֵׁם ס' יְרֵאִים)\u0006. \u0005וְנָכוֹן לְהַחְמִיר. אֲבָל קֶבֶר שֶׁל מוּמָר\u0006 \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006, \u0005מְטָּמֵא כְּשֶׁל יִשְׂרָאֵל\u0006 \u0005(רַשְׁבָּ\"א סי' קצ\"ד ורמ\"ב)\u0006.",[],["\u0003לעבור. \u0004 אבל לא על הקברות אפי' לדבר מצוה משום דהאידנא כולם סתומים ויש בהקברים חלל הרבה ע\"כ הטומאה בוקעת ועולה עד לרקיע ואפי' נגד צד הריקן שבו משא\"כ אי הוה סתום ואין בו חלל טפח אינו מטמא אלא כנגד הטומאה ממש ולא נגד צד הריקן שבו עכ\"ל הט\"ז:","\u0003ודוקא. \u0004 כתב הש\"ך נראה דדוקא נקט באהל המת אבל אם בבתים הסמוכים לבית שהמת בתוכו אף על פי שהם ג\"כ טמאים כדלעיל סי' שע\"א ס\"ד מ\"מ י\"ל דאינו אלא טומאה דרבנן כדאיתא בטור בסימן זה ובפוסקים ועב\"י דדבר תורה אהל שיש בו חלל פותח טפח טהור ע\"ש ודוק. וכשהבית שהמת בתוכו סתום מכל צד נמי ליכא בבתים הסמוכים טומאה אלא מדרבנן מפני שסוף הטומאה לצאת ואם כן בבתים הסמוכים בכל ענין ילביש עצמו תחלה עכ\"ל:","\u0003להקיצו. \u0004 כתב הש\"ך ולפי מ\"ש בסמוך דהיכא דאינו עם המת באהל עצמו רק בבית הסמוך לו ליכא אלא איסורא דרבנן א\"צ להקיצו. ואפשר לזה דקדק הרב וכתב ומת עמו באהל וכו' וע\"ל סי' שע\"ג עכ\"ל:","\u0003מקילין. \u0004 כתב הש\"ך אבל במגע ומשא י\"א דאפילו המקילים אוסרים וכן נראה דעת הב\"י ע\"ש עכ\"ל:"]],["כְּשֵׁם שֶׁהַכֹּהֵן מֻזְהָר שֶׁלֹּא לִטָּמְאוֹת, כָּךְ מֻזְהָרִים הַגְּדוֹלִים עַל הַקְּטַנִּים. \u0005וְדַוְקָא לְטַמְּאוֹתָן \u0010c0\u0011 בְּיָדַיִם, אֲבָל אִם הַקְּטַנִּים מִטָּמְאִין מֵעַצְמָן, עַיֵּן בְּא\"ח סִימָן שמ\"ג אִי צָרִיךְ לְהַפְרִישָׁן (הָרַשְׁבָּ\"א סִימָן קכ\"ח ומהרי\"ו, וְטוּר בְּשֵׁם הָרַמְבַּ\"ם כָּתַב כָּאן דְּאֵין צָרִיךְ)\u0006.\nאֲפִלּוּ בַּעַל מוּם, מֻזְהָר מִלִּטַּמֵּא, אֲבָל \u0010c1\u0011 חָלָל וְכֹהֶנֶת, מֻתָּרִים לִטָּמֵא.\nכָּל הַמֵּתִים הָאֲמוּרִים בַּפָּרָשָׁה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, מִצְוָה שֶׁיִּטָּמֵא לָהֶם; וְאִם לֹא רָצָה, מְטַמְאִים אוֹתוֹ עַל כָּרְחוֹ, אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה.\nאֵלּוּ הֵם הַקְּרוֹבִים שֶׁמִּטָּמֵא לָהֶם: אִשְׁתּוֹ נְשׂוּאָה שֶׁהִיא כְּשֵׁרָה; אֲבָל פְּסוּלָה, אוֹ \u0010c2\u0011 גְּרוּשָׁה, אוֹ אֲרוּסָה, לֹא אוֹנֵן וְלֹא מִטָּמֵא לָהּ; וְכֵן הִיא, לֹא אוֹנֶנֶת וְלֹא \u0010c3\u0011 מִטָּמְאָה לוֹ. וּמִטָּמֵא לְאִמּוֹ, \u0010c4\u0011 אֲפִלּוּ נִתְחַלְּלָה; וְלִבְנוֹ וּלְבִתּוֹ דְּקִים לֵיהּ שֶׁכָּלוּ לוֹ \u0010c5\u0011 חֳדָשָׁיו, אוֹ שֶׁהֵם מִשְּׁלֹשִׁים יוֹם וָאֵילָךְ, אֲפִלּוּ הֵם פְּסוּלִים; חוּץ מִבְּנוֹ וּבִתּוֹ מִשִּׁפְחָה אוֹ כּוּתִית; וּלְאָחִיו וְלַאֲחוֹתוֹ מֵאָבִיו, אֲפִלּוּ הֵם פְּסוּלִים, אֶלָּא אִם כֵּן הֵם בְּנֵי שִׁפְחָה אוֹ כּוּתִית; אֲבָל לְאָחִיו וְלַאֲחוֹתוֹ מֵאִמּוֹ, אֵינוֹ מִטָּמֵא. \u0005וְכֵן אֵינוֹ מִטָּמֵא\u0006 לַאֲחוֹתוֹ אֲרוּסָה, אֲפִלּוּ הִיא אֲרוּסָה לְכֹהֵן; וְלֹא לַאֲנוּסָה וּמְפֻתָּה; אֲבָל מִטָּמֵא לַאֲחוֹתוֹ אֲרוּסָה \u0010c6\u0011 שֶׁנִּתְגָּרְשָׁה, וּבוֹגֶרֶת, וּמֻכַּת עֵץ; וּמִטָּמֵא לְשׁוֹמֶרֶת יָבָם, אֲפִלּוּ אִם כָּתַב בִּכְתֻבָּתָהּ: אִי מִיתַת בְּלֹא בָּנִים תֶּהְדַּר כְּתֻבָּתֵךְ לְבֵי נָשָׁא \u0005(פֵּרוּשׁ לְבֵית אָבִיהָ)\u0006.\nכָּל אֵלּוּ שֶׁמִּטָּמֵא לָהֶם, אֲפִלּוּ שֶׁלֹּא לְצֹרֶךְ. וְיֵשׁ אוֹמְרִים דְּדַוְקָא לְצֹרֶךְ. \u0005הַגָּה: וְלַסְּבָרָא הָרִאשׁוֹנָה, אֲפִלּוּ מֵת לוֹ מֵת בְּשַׁבָּת, שֶׁאִי אֶפְשָׁר לְקָבְרוֹ בּוֹ בַּיּוֹם, שָׁרֵי לִטָּמְאוֹת לוֹ וּלְשָׁמְרוֹ, כְּדֵי שֶׁלֹּא יְהֵא מֻטָּל בְּבִזָּיוֹן (ת\"ה סי' רפ\"ג)\u0006 ; וְנָכוֹן לְהַחְמִיר כַּסְּבָרָא הָאַחֲרוֹנָה, שֶׁלֹּא לִטָּמְאוֹת רַק לְצֹרֶךְ קְבוּרָה וּלְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. \u0005(שָׁם בְּשֵׁם תּוֹסָפוֹת שנ\"ץ)\u0006.\nאֵינוֹ מִטָּמֵא לָהֶם, אֶלָּא עַד \u0010c7\u0011 שֶׁיִּסְתֹּם הַגּוֹלֵל. \u0005וְאִם דַּעְתּוֹ לְפַנּוֹתוֹ, מֻתָּר לִטָּמֵא לוֹ לְצֹרֶךְ, עַד שֶׁיִּסְתֹּם גּוֹלֵל שֵׁנִי (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן רצ\"ב)\u0006.\nאָסוּר לְכֹהֵן לְהִתְטַמֵּא לְמֵת, אֲפִלּוּ בְּעֵת שֶׁמִּטָּמֵא לִקְרוֹבָיו. לְפִיכָךְ כֹּהֵן שֶׁמֵּת לוֹ מֵת, צָרִיךְ לִזָּהֵר וּלְקָבְרוֹ בְּסוֹף בֵּית הַקְּבָרוֹת, כְּדֵי שֶׁלֹּא לִכָּנֵס לְבֵית הַקְּבָרוֹת וְלֹא יִתְטַמֵּא בְּקִבְרוֹת אֲחֵרִים כְּשֶׁיִּקְבֹּר מֵתוֹ. \u0005הַגָּה: \u0010c8\u0011 וְדַוְקָא לְאַחַר שֶׁפָּרַשׁ מִמֵּתוֹ, אֲבָל בְּעוֹד שֶׁהוּא עוֹסֵק בְּמֵתוֹ, מֻתָּר לִטָּמְאוֹת אַף לַאֲחֵרִים (טוּר)\u0006.\nכֹּהֵן שֶׁפָּרְשׁוּ אֲבוֹתָיו מִדַּרְכֵי צִבּוּר, כְּגוֹן הַמַּסוּרוֹת, אֵינוֹ מִטָּמֵא לָהֶם; וְלֹא לַהֲרוּגֵי בֵּית דִּין; וְלֹא לְמִי שֶׁמְּאַבֵּד עַצְמוֹ לָדַעַת, וְלֹא לְסָפֵק, כְּגוֹן שֶׁנִּתְעָרֵב וְלָדָהּ בִּוְלַד חֲבֶרְתָּהּ אוֹ סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן.\nאֵין הַכֹּהֵן מִטָּמֵא לְאֵבֶר מִן הַחַי מֵאָבִיו, וְלֹא לְעֶצֶם מֵעַצְמוֹת אָבִיו. וְכֵן הַמְלַקֵּט עֲצָמוֹת, אֵינוֹ מִטָּמֵא לָהֶם, אַף עַל פִּי שֶׁהַשִּׁדְרָה קַיֶּמֶת. חָסֵר מִמֶּנּוּ כָּל שֶׁהוּא, אֲפִלּוּ הוּא מֻנָּח אֶצְלוֹ, אֵינוֹ מִטָּמֵא לוֹ, שֶׁאֵינוֹ מִטָּמֵא אֶלָּא לְשָׁלֵם. וְיֵשׁ מִי שֶׁאוֹמֵר דְּהָנֵי מִלֵּי כְּשֶׁחָסֵר לְאַחַר מִיתָה, אֲבָל אִם חָסַר מִמֶּנּוּ אֵבֶר בְּחַיָּיו, וּמֵת, מִטָּמֵא לוֹ, אַף עַל פִּי שֶׁאֵינוֹ שָׁלֵם. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ מִטָּמֵא לְהָרוּג, דְּמִקְרֵי חָסֵר (כָּל בּוֹ בְּשֵׁם ר\"ש מאוירא)\u0006 וְנָכוֹן לְהַחְמִיר.",[],["\u0003בידים. \u0004 וכתב באגודה נ\"ל דתינוקות הישנים באהל המת אין מחוייבים להקיצם ולהוציאם אך מפני החינוך טוב הוא עכ\"ל \u0005(אבל א\"צ להוציא את הקטן שאינו בר דעת הצריך לאמו. בה\"י סי' שע\"א)\u0006:","\u0003חלל. \u0004 כ' הב\"ח דוקא חלל דאורייתא אבל של דבריהם כגון שנולד מחלוצה אסור לטמא ואם נולד מספק חלוצה הוי כהן גמור לכל דבר ויתבאר בא\"ע סי' ז' עיין שם:","\u0003גרושה. \u0004 פירוש אפילו יש לו בנים ממנה. מרדכי וכ\"כ האחרונים. ש\"ך:","\u0003מיטמאה. \u0004 כלומר אינה מחויבת לטמא לו אבל הרשות בידה לטמא. ש״ך: \u0005(וכ״כ בטור ובש״ע אה״ע סי' נ״ה וז״ל רש״י בפ' ד' אחין (יבמות דף כ״ט) ולא מיטמאה א״צ להתעסק בו ולאו דוקא נקט ולא מיטמאה דהא בנות אהרן לא הוזהרו על הטומאה אלא איידי דנקט ולא אוננת דאיצטריך ליה נקט ולא מיטמאה דבעי למיתני תרתי בדידה ובדידיה כך שמעתי ולי נראה ולא מיטמאה כגון ברגל שישראלים מוזהרים על הטומאה מונבלתם לא תגעו עכ״ל. נמצא לפי' שני שברש״י אסור לה לטמא לו ברגל משום דהיא ג״כ מוזהרת לטהר עצמה ברגל ומהתימא מהפוסקים ראשונים ואחרונים שהשמיטו את זה בגוף הדין שחייב לטהר את עצמו ברגל דהא אף לפי' הראשון לענין טהרת הרגל מודו דכ״ע חייבים לטהר עצמם עכ״ל בה״י והנה מ״ש שכל הפוסקים לא הביאו דין זה דחייב לטהר כו' לאו דוקא כל הפוסקים שהרי הרמב״ם הביאו בפט״ז מטומאת אוכלין והסמ״ג בעשין רמ״ו. וכן הפוסקים המדברים בדינין שאינן נהוגין עכשיו מביאים ג״כ דין זה. משא״כ הרא״ש והטור ושאר פוסקים שאינן מביאין אלא דינין הנהוגין אין מביאין דין זה. כי עיקר הדין לטהר ברגל קאי על זמן הבית שהיו צריכין להיות טהורים לאכול בקדשים כמ״ש רש״י ורמב״ם. אבל בזמה״ז אין נפקותא בזה בין הרגל לכולי שתא שהרי טמאי מתים אנן ואין לנו אפר פרה ומה גם גזרו טומאה על ארץ העמים ומה טהרה שייך ביה. ואף שאיזה פוסקים כתבו שגם בזמה״ז חייב אדם לטהר עצמו ברגל לאו מטומאת מת ושרץ קאמרי אלא מטומאה היוצא מגופו של אדם וכדומה. וגם מרמזת הטהרה על טהרת הנפש. כי ע״י טהרת הגוף מעורר ומזכך טהרת הנפש כדאיתא בכמה מקומות בראשית חכמה ובשל״ה וזה ברור. וע״כ תפסו הפוסקים פי' ראשון שברש״י דהיא לא מיטמאה לאו דוקא אלא שאינה מחייבת להתעסק בעניני קבורה אבל בנשואין הן כהן וכ״ש ישראל והן אשה כולם שוין לענין זה ליטמא ולהתעסק בשבעה מתים דידהו הן ברגל והן בשאר ימות השנה דמ״ש ואם לא רצו כופין אותן ועי' בשו״ת יד אליהו סימן ס״ח)\u0006:","\u0003נתחללה. \u0004 כגון אחר שנולד כהן זה ממנה נשאת לכהן כשהיתה גרושה. ש\"ך:","\u0003חדשיו. \u0004 לאפוקי ספק נפל דאין מטמאין לו וה\"ה לאחיו ולאחותו הקטנים שהם ספק נפלים אינו מטמא להם. ש\"ך:","\u0003שנתגרשה. \u0004 היינו מן האירוסין וק\"ל:","\u0003הגולל. \u0004 כתב הש\"ך בסי' שע\"ה כתב הטור שיש פלוגתא בין רש\"י ור\"ת מהו הגולל והב\"ח כ' דנקטינן כרש\"י שפירש דהוא כסוי הארון וכתב הרמב\"ן דלרש\"י כשנותנין אותו בבית בארון וסותמין הכסוי במסמרים ע\"ד ליתן הארון בקבר הוי סתימה והוא תמה עליו דהיאך אפשר לומר שאם סתמו ארונו בבית שלא יטמא בנו עליו כו' ולי נראה דמה שפירש\"י בכל מקום גולל היינו כסוי הארון אין ר\"ל אפילו סתמו בבית אלא ר\"ל משיסתם כסוי הארון בקבר תדע דבפ' שואל אמרי' כל שאומרים בפני המת יודע עד שיסתם הגולל דכתיב וישוב העפר אל הארץ כשהיה ופירש\"י גופו קרי עפר ומששב אל הארץ כאשר היה מיד והרוח תשוב שאין בו עוד רוח ע\"כ ולפ\"ז אפילו נסתם הארון במסמרים בבית גם לרש\"י בנו מיטמא עליו עד שיסתם בקבר עכ\"ל:","\u0003ודוקא. \u0004 והב\"ח פסק דאף בהליכה אסור להוסיף טומאה כיון שאפשר לו לקברו בסוף בה\"ק וכ\"כ הלבוש דנכון להחמיר כסברא זו והמ\"מ מיקל בדבר עכ\"ל הש\"ך:"]],["מִצְוָה לְהִטָּמְאוֹת לְמֵת מִצְוָה, אֲפִלּוּ הוּא כֹּהֵן גָּדוֹל וְנָזִיר וְהוֹלֵךְ לִשְׁחֹט אֶת פִּסְחוֹ, וְלָמוּל אֶת בְּנוֹ, וּמָצָא מֵת מִצְוָה, הֲרֵי זֶה מִטָּמֵא לוֹ.\nאֵינוֹ נִקְרָא מֵת מִצְוָה לְעִנְיָן זֶה, אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ. וְאִם מָצָא רֹאשׁוֹ וְרֻבּוֹ חוּץ מֵאֵבֶר אֶחָד, חוֹזֵר \u0010c0\u0011 לִטָּמֵא בִּשְׁבִיל אוֹתוֹ אֵבֶר.\nאֵיזֶהוּ מֵת מִצְוָה, שֶׁמְּצָאוֹ בַּדֶּרֶךְ אוֹ בְּעִיר שֶׁל עוֹבְדֵי כּוֹכָבִים, וְאֵין לוֹ קוֹבְרִים, וּמִמָּקוֹם שֶׁמְּצָאוֹ אֵינוֹ יָכוֹל לִקְרוֹת יִשְׂרָאֵל שֶׁיַּעֲנֵהוּ וְיָבֹא לְטַפֵּל בּוֹ וּלְקָבְרוֹ, אָסוּר לוֹ לָזוּז מִשָּׁם וּלְהַנִּיחַ אֶת הַמֵּת, אֲפִלּוּ לֵילֵךְ לָעִיר לְהָבִיא קוֹבְרִים, אֶלָּא יְטַמֵּא עַצְמוֹ וְיִקְבְּרֶנּוּ. אֲבָל אִם הָיוּ יִשְׂרָאֵל קְרוֹבִים לִמְקוֹם הַמֵּת, שֶׁהַמּוֹצֵא אֶת הַמֵּת קוֹרֵא אוֹתָם וְהֵם עוֹנִים לוֹ וּבָאִים לְקָבְרוֹ, אֵין זֶה מֵת מִצְוָה שֶׁיִּטָּמֵא עָלָיו הַכֹּהֵן, אֶלָּא קוֹרֵא אוֹתָם וְהֵם קוֹבְרִים. בָּאוּ בְּנֵי הָעִיר, אִם יֵשׁ לוֹ כָּל \u0010c1\u0011 צָרְכּוֹ, מוֹשֵׁךְ אֶת יָדָיו. \u0005(לְשׁוֹן רַמְבַּ\"ן בתה\"א ורא\"ש בְּהִלְכוֹת טֻמְאָה)\u0006 \u0005הַגָּה: יֵשׁ אוֹמְרִים אִם אֵינוֹ מוֹצֵא שֶׁיִּקְבְּרוּהוּ, רַק בְּשָׂכָר, אֵינוֹ חַיָּב לִשְׂכֹּר מִשֶּׁלּוֹ, אֶלָּא מִטָּמֵא, אִם יִרְצֶה\u0006 \u0005(נ\"י פֶּרֶק הָאִשָּׁה רַבָּה בְּשֵׁם ריטב\"א)\u0006. \u0005מֵת הַנִּמְצָא, וְלֹא יַדְעִינָן אִם עוֹבֵד כּוֹכָבִים אִם יִשְׂרָאֵל הוּא, אַזְלִינָן בָּתַר \u0010c2\u0011 רֻבָּא הַנִּמְצָאִים שָׁם, אִם יֵשׁ, שֶׁלֹּא נוּכַל לוֹמַר כָּל קָבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006.\nכָּל הַקְּרוֹבִים שֶׁהַכֹּהֵן מִטָּמֵא לָהֶם, שֶׁהֵם: אָבִיו, וְאִמּוֹ, וּבְנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ מֵאָבִיו הַבְּתוּלָה, וְאִשְׁתּוֹ, מִתְאַבְּלִים עֲלֵיהֶם. וְעוֹד הוֹסִיפוּ עֲלֵיהֶם: אָחִיו מֵאִמּוֹ, וַאֲחוֹתוֹ מֵאִמּוֹ, בֵּין בְּתוּלָה בֵּין נְשׂוּאָה, וַאֲחוֹתוֹ נְשׂוּאָה מֵאָבִיו, שֶׁמִּתְאַבְּלִים עֲלֵיהֶם אַף עַל פִּי שֶׁאֵין כֹּהֵן מִטָּמֵא לָהֶם. וּכְשֵׁם שֶׁהוּא מִתְאַבֵּל עַל אִשְׁתּוֹ, כָּךְ הִיא מִתְאַבֶּלֶת עָלָיו. וְדַוְקָא אִשְׁתּוֹ כְּשֵׁרָה וּנְשׂוּאָה, אֲבָל פְּסוּלָה אוֹ אֲרוּסָה, לֹא. אֲבָל בְּנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ, אֲפִלּוּ הֵם פְּסוּלִים, מִתְאַבֵּל עֲלֵיהֶם, חוּץ מִבְּנוֹ, וּבִתּוֹ וְאָחִיו וַאֲחוֹתוֹ מִשִּׁפְחָה וְכוּתִית, שֶׁאֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nהַגֵּר שֶׁנִּתְגַּיֵּר הוּא וּבָנָיו, אוֹ עֶבֶד שֶׁנִּשְׁתַּחְרֵר הוּא וְאִמּוֹ, אֵין מִתְאַבְּלִין זֶה עַל זֶה. \u0005וְהוּא הַדִּין גֵּר שֶׁנִּתְגַּיֵּר עִם אִמּוֹ, אֵין מִתְאַבֵּל עֲלֵיהֶם (סְבָרַת הָרַב מֵהַמָּרְדְּכַי הל' שְׂמָחוֹת מִמַּעֲשֶׂה שֶׁבָּא לִפְנֵי ר\"י לְמַאי דקי\"ל אֲבֵלוּת יוֹם רִאשׁוֹן דְּרַבָּנָן)\u0006.\nכָּל מִי שֶׁמִּתְאַבֵּל עָלָיו, מִתְאַבֵּל עִמּוֹ אִם מֵת לוֹ מֵת. וְדַוְקָא בְּעוֹדוֹ בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו אֵין צָרִיךְ לִנְהֹג אֲבֵלוּת; חוּץ מֵאִשְׁתּוֹ, שֶׁאַף עַל פִּי שֶׁמִּתְאַבֵּל עָלֶיהָ אֵינוֹ מִתְאַבֵּל עִמָּהּ אֶלָּא עַל אָבִיהָ אוֹ עַל אִמָּהּ מִשּׁוּם כְּבוֹד חָמִיו וַחֲמוֹתוֹ, אֲבָל עַל אָחִיהָ וַאֲחוֹתָהּ אוֹ בְּנָהּ וּבִתָּהּ מֵאִישׁ אַחֵר, אֵינוֹ מִתְאַבֵּל עִמָּהּ. וּמִכָּל מָקוֹם אֵינוֹ יָכוֹל לְכֹפָהּ לְהִתְקַשֵּׁט, אֲבָל יְכוֹלָה לִמְזֹג לוֹ הַכּוֹס וּלְהַצִּיעַ לוֹ הַמִּטָּה וְלִרְחֹץ פָּנָיו יָדָיו וְרַגְלָיו. וְכֵן הִיא אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ, אֶלָּא כְּשֶׁמֵּתוּ חָמִיהָ אוֹ חֲמוֹתָהּ, אֲבָל שְׁאָר קְרוֹבָיו שֶׁמֵּתוּ, אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהָאִידָּנָא נוֹהֲגִין לְהָקֵל בַּאֲבֵלוּת זֶה שֶׁל הַמִתְאַבְּלִים עִמּוֹ, דְּאֵין זֶה אֶלָּא מִשּׁוּם כְּבוֹד הַמִתְאַבְּלִים, וְעַכְשָׁו נָהֲגוּ כֻּלָּם לִמְחֹל. וְכֵן נוֹהֲגִין הָאִדָּנָא שֶׁלֹּא לְהִתְאַבֵּל כְּלָל עִם הַמִתְאַבְּלִים (טוּר בְּשֵׁם הָרֹא\"שׁ וְהוּא בְּפ' א\"מ וְרַמְבַּ\"ן בת\"ה והגמי\"י פֶּרֶק א)\u0006, וְכָל הַמַּחְמִיר בָּזֶה אֵינוֹ אֶלָּא מִן \u0010c3\u0011 הַמַּתְמִיהִים \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006. וּמִכָּל מָקוֹם נָהֲגוּ שֶׁכָּל קְרוֹבֵי הַמֵּת, הַפְּסוּלִין לוֹ \u0010c4\u0011 לְעֵדוּת, מַרְאִין קְצָת אֲבֵלוּת בְּעַצְמָן כָּל שָׁבוּעַ הָרִאשׁוֹנָה, דְּהַיְנוּ עַד אַחַר שַׁבָּת \u0010c5\u0011 הָרִאשׁוֹן, שֶׁאֵינָן רוֹחֲצִים וְאֵין מְשַׁנִּים קְצָת בִּגְדֵיהֶם כְּמוֹ בִּשְׁאָר שַׁבָּת \u0005(גְּדוֹלֵי אוסטריי\u0006 ךָ \u0005נָהֲגוּ כֵּן)\u0006. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ עוֹד לְהַחְמִיר בְּעִנְיָנִים אֲחֵרִים, וְהָעִקָּר כְּמוֹ שֶׁכָּתַבְתִּי. וְכָל זֶה בִּשְׁמוּעָה קְרוֹבָה, אוֹ שֶׁהָיָה אֵצֶל הַמִּיתָה; אֲבָל בִּשְׁמוּעָה רְחוֹקָה, אֵין לַאֲבֵלוּת זֶה מָקוֹם כְּלָל \u0005(תִּמְצָא הַכֹּל מְבֹאָר בת\"ה סִימָן רנ\"א)\u0006. מִי שֶׁרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ לְהִתְאַבֵּל עַל מִי שֶׁאֵינוֹ צָרִיךְ, אוֹ לִלְבֹּשׁ שְׁחֹרִים עַל קְרוֹבוֹ, אֵין מוֹחִין בְּיָדוֹ \u0005(הָרֹא\"שׁ כְּלָל כ\"ז דִּין ט')\u0006.\nאֵין מִתְאַבְּלִים עִם הַקְּרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, אֶלָּא כְּשֶׁמִּתְאַבְּלִים עַל הַקֻּרְבָה דִּשְׁאֵר, כְּגוֹן בְּנוֹ וְאָחִיו שֶׁמִּתְאַבֵּל עַל בֵּן וּבַת שֶׁלָּהֶם; אֲבָל עַל קֻרְבָה דְּקִדּוּשִׁין שֶׁלָּהֶם, כְּגוֹן שֶׁמֵּתָה אֵשֶׁת בְּנוֹ אוֹ אֵשֶׁת אָחִיו אוֹ בַּעַל בִּתּוֹ אוֹ בַּעַל אֲחוֹתוֹ, אֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nתִּינוֹק, כָּל שְׁלֹשִׁים יוֹם וְיוֹם שְׁלֹשִׁים בַּכְּלָל, אֵין מִתְאַבְּלִים עָלָיו, אֲפִלּוּ גָּמְרוּ שְׂעָרוֹ וְצִפָּרְנָיו; וּמִשָּׁם וָאֵילָךְ מִתְאַבֵּל עָלָיו, אֶלָּא אִם כֵּן נוֹדַע שֶׁהוּא בֶּן ח'. וְאִי קִים לֵיהּ בֵּיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, כְּגוֹן שֶׁבָּעַל וּפֵרֵשׁ וְנוֹלַד חַי לִט' חֳדָשִׁים גְּמוּרִים, אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד, מִתְאַבְּלִים עָלָיו. \u0005סָפֵק בֶּן ט' לָרִאשׁוֹן (אוֹ)\u0006 בֶּן ז' לָאַחֲרוֹן, שְׁנֵיהֶם מִתְאַבְּלִים עָלָיו \u0005(מָרְדְּכַי הִלְכוֹת אֲבֵלוּת וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק א' וּבֵית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר דִּתְאוֹמִים שֶׁמֵּת א' מֵהֶם תּוֹךְ שְׁלֹשִׁים יוֹם, וְהַשֵּׁנִי חַי וּמֵת אַחַר ל' יוֹם, אֵין מִתְאַבְּלִין \u0010c6\u0011 עָלָיו.\nעַל רַבּוֹ שֶׁלִּמְּדוֹ חָכְמָה נוֹהֵג דִּינֵי אֲנִינוּת, אֶלָּא שֶׁמְּבָרֵךְ וּמְזַמֵּן וּמִתְאַבֵּל עָלָיו בַּחֲלִיצַת סַנְדָּל וְכָל דִּינֵי אֲבֵלוּת, יוֹם \u0010c7\u0011 אֶחָד. \u0005(וְכָתַב הַבֵּית יוֹסֵף בְּשֵׁם רַבִּי שִׂמְחָה שֶׁצָרִיךְ לְשַׁנּוֹת מְקוֹמוֹ בב\"ה, מִיהוּ בְּמִקְצָת הַיּוֹם סָגֵי)\u0006.\nנָשִׂיא, אַף עַל פִּי שֶׁהַכֹּל מִטָּמְאִין לוֹ, אֵין מִתְאַבְּלִים עָלָיו. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין עַל בֵּן הָרִאשׁוֹן אוֹ בֵּן הַבְּכוֹר שֶׁמֵּת לְאָדָם (כָּל בּוֹ וריב\"ש וּבֵית יוֹסֵף הֵבִיאוּ מִי שֶׁנָּהֲגוּ כֵּן, וְהֵם כָּתְבוּ שֶׁהוּא טָעוּת)\u0006 ; וְהַמִּנְהָג הוּא מִנְהַג טָעוּת, אֶלָּא חַיָּבִים לְהִתְאַבֵּל עֲלֵיהֶם. וּמִכָּל מָקוֹם נִשְׁתַּרְבֵּב הַמִּנְהָג בְּעִירֵנוּ שֶׁאֵין אָב וָאֵם הוֹלְכִים אַחַר בְּנֵיהֶם \u0010c8\u0011 הָרִאשׁוֹן לְבֵית הַקְּבָרוֹת. יֵשׁ אוֹמְרִים בִּשְׁעַת הַדֶּבֶר אֵין מִתְאַבְּלִים, מִשּׁוּם בִּיעֲתוּתָא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ג')\u0006, וְשָׁמַעְתִּי קְצָת נָהֲגוּ כֵּן.",[],["\u0003ליטמא. \u0004 כלומר דאע\"ג דאינו מטמא עליו אלא כשמצאו ראשו ורובו היינו לטמאות לכתחלה אבל אם כבר קברו חוץ מאבר א' חוזר לטמאות על אותו אבר ובזה חמור מקרובים שאינו מטמא להם אא\"כ הם שלמים כמ\"ש בס\"ס שע\"ג עכ\"ל הש\"ך:","\u0003צרכו. \u0004 כתב מהרש\"ל לעולם הוא מת מצוה עד שיהיו שם נושאי המטה וקובריה עכ\"ל:","\u0003רובא. \u0004 כתב הש\"ך דר\"ל דאזלינן בתר עוברים ושבים המצויים שם או בתר רוב עיירות ולא אזלינן בתר העיר הקרובה אפילו בקורבה דמוכח דכל דפריש מרובא פריש אם לא שנוכל לומר כל קבוע וכו' כגון שידוע שהיו כאן ט' עובדי כוכבים וחד ישראל ונהרג אחד מהן במקומו לא אזלינן בתר רוב עובדי כוכבים אלא הוי כמחצה ע\"מ. וכתב הלבוש ולחומרא ואין הכהן מטמא מספק כדלעיל סי' שע\"ג ס\"ח עכ\"ל:","\u0003המתמיהים. \u0004 כתב הש\"ך ואע\"ג דמי שרוצה להחמיר ולהתאבל על מי שאינו צריך הרשות בידו וכמ\"ש הרב בסוף הג\"ה היינו דוקא כשמתאבל לגמרי כדין אבילות אבל כשאינו מתאבל אלא לפניו הוי כלועג לאבל עכ\"ל \u0005(ולי נראה הא דאמר אין מוחין בידו היינו מי שעושה זה מצד עצמו שיודע שאינו חייב בדבר אלא שעושים מקצת אבילות לכבוד המת מצד שהיה אוהבו או קרובו או מצד מע\"ט שהיה בו או משארי טעמים שזו היתר גמור כמו שמביא בד\"מ תשובת הרא\"ש כלל כ\"ז סי' ט' וז\"ל וששאלתם אם הרשות בידם ללבוש שחורים על חמיו שנפטר או על אוהבו י\"ב חודש. על חמיו פשיטא דרשות בידו כו' ועל אוהבו נמי אם רוצה להצטער עליו בלבישת שחורים או בשביל כבודו הרשות בידו. וכן מצינו בדוד שקבל הבראה על אבנר עכ\"ל. ומ\"ש שאינו אלא מן המתמיהים היינו מי שרוצה לעשות זה מצד החיוב לנהוג אבלות כמו האבלים ורוצה לדחוק עצמו בקורבה כמו האבלים ממש וזה נקרא כמו לועג לאבל. ובאה\"ע סי' קמ\"ה ס\"ט בהג\"ה אשה שנתגרשה על תנאי ומת הבעל אינה צריכה להתאבל עליו אבל אין איסור אם רצונה להחמיר על עצמה לבכות עליו ולצאת אחר מטתו עכ\"ל ופי' בה\"י דלא חיישינן שמא יוציאו לעז על הגט ויאמרו שאינו גט אעפ\"כ אין איסור בדבר הרי שאומר בלשון שרצונה להחמיר באיזה דבר שמותר)\u0006:","\u0003לעדות. \u0004 עי' בח\"מ סי' ל\"ג איזהו פסולין לעדות ומ\"מ נראה דדוקא פסולי עדות מחמת קורבה דשאר אבל לא מחמת קורבה דקדושין כדלקמן בסעיף שאח\"ז עכ\"ל הש\"ך:","\u0003הראשון. \u0004 וכתב הב\"ח דכ\"ש דאסור לילך לסעודת מצוה כגון ברית מילה עד מוצאי שבת וכתב בתשובת מ\"ב דיש מקומות שנוהגים רק פסולי עדות למת מראין קצת אבילות ויש מקומות שאפילו שלישי ברביעי מראין אבילות והיכא דנהוג נהוג והיכא דלא נהוג נראה דאין להראות אבילות רק הפסולים לעדות. ומ\"מ נראה דאין כל הקרובים שוים לזה אלא קרוב קרוב קודם. ואותם קרובים שמן הדין היו חייבים להתאבל ממש אע\"ג דהאידנא לא נהיגין הכי מ\"מ צריכין להראות אבילות ביום המיתה או ביום השמועה אם הוא תוך ל' יום עד מוצאי שבת הראשון ואין להחליף מבגדי חול לבגדי שבת גם אין לרחוץ בחמין ולא לחוף הראש רק בצונן או במים פושרין ואין לאכול חוץ מביתו לא בסעודת מצוה ולא בסעודת מריעות אבל כתונת לבן אין למנוע לכבוד שבת גם אין לשנות את מקומן בבהכ\"נ ובמו\"ש מותר בכל דבר בין אם הוא מופלג או סמוך ואותן הקרובים שמן הדין אין מתאבלין אין להחמיר בכל אלו ודי להם בבגד העליון של חול ושלא לאכול חוץ לבית ע\"כ ומ\"ש להתיר לקרובים שאין מתאבלים מן הדין ברחיצת חמין וכו' אין נראה כן מדברי הרב דהא אוסר ברחיצה לפסולי עדות דהיינו שני בשני אע\"פ שמן הדין אין מתאבלין. גם מ\"ש להחמיר באותן שמתאבלין מן הדין שלא להחליף כלל מבגדי חול אין נראה כן אלא משנים רק קצת מבגדיהם. ומ\"מ נראה דהולכים בדברים אלו אחר המנהג עכ\"ל הש\"ך:","\u0003עליו. \u0004 הט\"ז והש\"ך כתבו שט\"ס יש כאן בהג\"ה וכצ\"ל והשני חי עדיין אחר ל' יום ור\"ל דאין מתאבלין על הראשון ולא אמרי' מדזה הוא חי והוא בן קיימא מסתמא גם זה שמת הוה בן קיימא דלא כהלבוש שכתב שעל השני קאי דאין מתאבלין עליו אפי' מת אחר ל' דמסתמא נמי נפל היה דהא ודאי ליתא וכן הסכים הב\"ח והגאון מוהר\"ר משה חריף ז\"ל דעל השני שמת אחר ל' ודאי דמתאבלין עליו ודלא כמוהר\"ם מלובלין בתשובה ששגג בזה ג\"כ עכ\"ל הט\"ז:","\u0003אחד. \u0004 וכתב מהרש\"ל ונכון שלא לשתות יין ולא לאכול בשר כל היום עד לאחר קבורה מא\"ז עכ\"ל:","\u0003הראשון. \u0004 כתב הש\"ך אבל על בניהם השני הולכים אע\"פ שהראשון היה נפל וכן נוהגין עכ\"ל:"]],["מֵאֵימָתַי חָל הָאֲבֵלוּת, מִשֶּׁנִּקְבַּר וְנִגְמַר סְתִימַת הַקֶּבֶר בְּעָפָר, מִיָּד מַתְחִיל הָאֲבֵלוּת וּמְעַטֵּף רֹאשׁוֹ, אֲבָל אֵינוֹ חוֹלֵץ מִנְעָלָיו עַד שֶׁיַּגִּיעַ לְבֵיתוֹ \u0005(רַמְבַּ\"ן)\u0006. וְעַכְשָׁו נוֹהֲגִים לַחֲלֹץ מִנְעָל אַחַר סְתִימַת הַגּוֹלָל מִיָּד, כִּדְאִיתָא בְּסִימָן שע\"ו. \u0005הַגָּה: וְע\"ל סִימָן שפ\"ב. הָיָה סָבוּר שֶׁנִּסְתַּם הַקֶּבֶר וְהִתְחִיל לְהִתְאַבֵּל, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁטָּעָה, חוֹזֵר וּמַתְחִיל הָאֲבֵלוּת מֵחָדָשׁ (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל כ\"ז)\u0006.\nמִי שֶׁדַּרְכָּם לִשְׁלֹחַ הַמֵּת לִמְדִינָה \u0010c0\u0011 אַחֶרֶת לְקָבְרוֹ, וְאֵינָם יוֹדְעִים מָתַי יִקָּבֵר, מֵעֵת שֶׁיַּחַזְרוּ פְּנֵיהֶם מִלְלַוּוֹת מַתְחִילִין לִמְנוֹת שִׁבְעָה וּשְׁלֹשִׁים וּמַתְחִילִין לְהִתְאַבֵּל \u0005(ל' רַמְבַּ\"ם פֶּרֶק א' מה\"א ד\"ו)\u0006 ; וְהַהוֹלְכִים עִמּוֹ, מוֹנִים מִשֶּׁיִּקָבֵר. וְאִם גָדוֹל הַמִּשְׁפָּחָה הוֹלֵךְ עִמּוֹ, אַף אֵלוּ \u0010c1\u0011 שֶׁבְּכָאן אֵינָם מוֹנִים אֶלָא מִשֶּׁיִּקָבֵר; וּגְדוֹל \u0010c2\u0011 מִשְׁפָּחָה הַיְנוּ דְּבֵיתָא סָמוּךְ עֲלֵהּ וּגְרִירֵי כֻּלְהוּ בַּתְרֵיהּ, לֹא שְׁנָא אָח לֹא שְׁנָא בֵּן קָטָן; וְיֵשׁ מִי שֶׁאוֹמֵר וְהוּא שֶׁיְּהֵא בֶּן י\"ג.\nאִם מְפַנִּין אֶת הַמֵּת מִקֶבֶר לְקֶבֶר, אִם קְבָרוּהוּ בְּקֶבֶר רִאשׁוֹן עַל דַּעַת לִהְיוֹת קָבוּר שָׁם עוֹלָמִית, אֶלָא שֶׁאַחַר כָּךְ נִמְלְכוּ לְפַנּוֹתוֹ מִשָּׁם, אֵין מוֹנִין לוֹ אֶלָא מִשֶּׁיִּקָבֵר בְּקֶבֶר רִאשׁוֹן, אֲפִלוּ פִּנּוּהוּ תּוֹךְ ז'. אֲבָל אִם בִּתְחִלָה קְבָרוּהוּ עַל דַּעַת לְפַנּוֹתוֹ כְּשֶׁיִּזְדַּמֵּן לָהֶם, מַתְחִילִין אֲבֵלוּת מִיָּד; וְאִם פִּנּוּהוּ תּוֹךְ שִׁבְעָה, חוֹזְרִין וּמוֹנִין מִשֶּׁיִּקָבֵר שֵׁנִית; וְאִם לֹא פִּנּוּהוּ עַד לְאַחַר שִׁבְעָה, כְּבַר עָבַר אֲבֵלוּתָם וְאֵין מִתְאַבְּלִין עָלָיו פַּעַם אַחֶרֶת; וְאִם מִתְּחִלָה הָיָה דַּעְתָּם לְפַנּוֹתוֹ מִשָּׁם תּוֹךְ שִׁבְעָה, אֵין מַתְחִילִין לִמְנוֹת עַד שֶׁיִּקָבֵר בַּקֶבֶר הַשֵּׁנִי.\nאִם נָתְנוּ הַמֵּת בְּאָרוֹן, וּנְתָנוּהוּ בְּבַיִת אַחֵר לְפִי שֶׁהָיְתָה הָעִיר בְּמָצוֹר, מוֹנִים לוֹ מִיָּד שִׁבְעָה וּשְׁלֹשִׁים, אַף עַל פִּי שֶׁדַּעְתָּם לְקָבְרוֹ בְּבֵית הַקְבָרוֹת אַחַר הַמָּצוֹר, וּסְתִימַת אָרוֹן הָוֵי \u0010c3\u0011 כִּקְבוּרָה וְחָל עֲלֵיהֶם אֲבֵלוּת מִיָּד.\nהֲרוּגֵי מַלְכוּת שֶׁאֵין מַנִּיחִים אוֹתָם לִקָבֵר, מֵאֵימָתַי מַתְחִילִין לְהִתְאַבֵּל עֲלֵיהֶם וְלִמְנוֹת ז' וּשְׁלֹשִׁים, \u0010c4\u0011 מִשֶּׁנִּתְיָאֲשׁוּ לִשְׁאֹל לַמֶּלֶךְ לְקָבְרָן, אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ מִלִגְנֹב אוֹתָם.\nמִי שֶׁהוֹדִיעוּהוּ שֶׁצָּלְבוּ עוֹבְדֵי כּוֹכָבִים קְרוֹבוֹ בְּעִיר אַחֶרֶת וְנָהַג אֲבֵלוּת מִיָּד, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁעֲדַיִן עוֹמֵד בַּצְּלִיבָה, אוֹתוֹ אֲבֵלוּת לֹא עָלָה לוֹ וְחוֹזֵר וּמוֹנֶה מִשֶּׁיִּקָבֵר אוֹ מִשֶּׁנִּתְיָאֲשׁוּ \u0010c5\u0011 מִלְקָבְרוֹ \u0005(דַּעַת ר\"י וְרַמְבַּ\"ן)\u0006.\nמִי שֶׁטָּבַע בְּמַיִם שֶׁיֵּשׁ לָהֶם \u0010c6\u0011 סוֹף, אוֹ שֶׁיָּצָא קוֹל שֶׁהֲרָגוּהוּ לִסְטִים אוֹ שֶׁגְרַרְתּוֹ חַיָּה, מֵאֵימָתַי מוֹנִים, מִשֶּׁנִּתְיָאֲשׁוּ לְבַקֵשׁ. מְצָאוּהוּ אֵבָרִים אֵבָרִים וּמַכִּירִין אוֹתוֹ בְּסִימָנֵי גוּפוֹ, אֵין מוֹנִין לוֹ עַד שֶׁיִּמָּצֵא רֹאשׁוֹ וְרֻבּוֹ אוֹ יִתְיָאֲשׁוּ מִלְבַקֵשׁ \u0005(בָּרַיְתָא מְבִיאָהּ רַמְבַּ\"ן)\u0006 ; וְאִם נִמְצָא אַחַר שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ, אֵין הַקְרוֹבִין צְרִיכִים לַחֲזֹר וּלְהִתְאַבֵּל, אֶלָא הַבָּנִים, אִם הֵם \u0010c7\u0011 שָׁם בְּשָׁעָה שֶׁנִּמְצָא מִתְאַבְּלִים אוֹתוֹ הַיּוֹם דְּלֹא גָרַע מִלִקוּט עַצְמוֹת אָבִיו; אֲבָל אִם אֵינָם שָׁם, וְשָׁמְעוּ אַחַר שֶׁעָבַר הַיּוֹם, אֵין צְרִיכִין לְהִתְאַבֵּל. \u0005הַגָּה: אִם שָׁלְחוּ מֵתֵיהֶם לְעִיר אַחֶרֶת, \u0010c8\u0011 שֶׁדִּינָם לְהַתְחִיל הָאֲבֵלוּת מִשֶּׁיַּחֲזִירוּ פְּנֵיהֶם, וְהִתְחִילוּ לִמְנוֹת הָאֲבֵלוּת, וְאַחַר כָּךְ נִתְפַּס הַמֵּת וְלֹא נִתַּן לִקְבוּרָה זְמַן אָרֹךְ, אֵין צְרִיכִין לְהַפְסִיק אֲבֵלוּתָן, וְאֵין צְרִיכִין לַחֲזֹר וּלְהִתְאַבֵּל אַחַר כָּךְ, דְּמֵאַחַר שֶׁדִּינָם לְהַתְחִיל מִיָּד, אֵין צְרִיכִין לְהַפְסִיק (מָרְדְּכַי סוֹף מ\"ק)\u0006.\nמִי שֶׁמֵּת לוֹ קָרוֹב, וְלֹא יָדַע עַד שֶׁבָּא לַמָּקוֹם שֶׁמֵּת שָׁם הַמֵּת, אוֹ לִמְקוֹם קְבוּרָה, אִם הָיָה בְּמָקוֹם קָרוֹב שֶׁהוּא מַהֲלַךְ י' פַּרְסָאוֹת שֶׁאֶפְשָׁר שֶׁיָּבֹא בְּיוֹם אֶחָד, אֲפִלוּ בָּא בַּיּוֹם הַז', אִם מָצָא מְנַחֲמִים אֵצֶל גְדוֹל הַבַּיִת, אֲפִלוּ שֶׁנִּנְעֲרוּ לַעֲמֹד, הוֹאִיל וּמָצָא מְנַחֲמִים \u0005דְּהַיְנוּ שֶׁנּוֹהֲגִים עֲדַיִן קְצָת אֲבֵלוּת (טוּר וְרַשְׁבָּ\"א בִּתְשׁוּבָה)\u0006, עוֹלֶה וּמוֹנֶה לוֹ עִמָּהֶם תַּשְׁלוּם שְׁלֹשִׁים יוֹם; וְאִם לֹא מָצָא מְנַחֲמִים, מוֹנֶה לְעַצְמוֹ. וְכֵן אִם הָיָה בְּמָקוֹם רָחוֹק, אֲפִלוּ בָּא בְּיוֹם שֵׁנִי, מוֹנֶה לְעַצְמוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁבָּא. \u0005הַגָּה: \u0010c9\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִילוּ אִם בָּא אֶחָד, וְאֵין הַגָּדוֹל בַּבַּיִת רַק שֶׁהָלַךְ לְצֹרֶךְ הַמֵּת, אִם חָזַר תּוֹךְ ג' יָמִים הָוֵי כְּאִלּוּ הוּא בַּבַּיִת וְהַבָּא תּוֹךְ ג' מוֹנֶה עִמָּהֶם (וְכֵן הוּא בַּטּוּר)\u0006 ; וְיֵשׁ לְהָקֵל כִּסְבָרָא זוֹ. וְכָל שֶׁדִּינוֹ לִמְנוֹת עִמָּהֶם, אֲפִלּוּ אִם חָזַר אַחַר כָּךְ לְבֵיתוֹ, מוֹנֶה עִמָּהֶם \u0005(הָרַשְׁבָּ\"א סִימָן תע\"ז)\u0006.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁלֹּא שָׁמַע שֶׁמֵּת, עַד שֶׁבָּא. אֲבָל אִם נוֹדַע לוֹ בַּיּוֹם הַשֵּׁנִי וְהִתְחִיל לְהִתְאַבֵּל, לֹא יְקַצֵּר אֲבֵלוּתוֹ בִּשְׁבִיל שֶׁבָּא אֶצְלָם.\nמִי שֶׁהוּא אָבֵל, וּבְתוֹךְ ז' מֵת לוֹ מֵת אַחֵר, מוֹנֶה ז' לְמֵת אַחֲרוֹן וְעוֹלִים לוֹ לְתַשְׁלוּם שִׁבְעָה יְמֵי אֲבֵלוּת הָרִאשׁוֹן.\nמִי \u0010c10\u0011 שֶׁהִתְפַּלֵל עַרְבִית, וַעֲדַיִן הוּא יוֹם, וְשָׁמַע שֶׁמֵּת לוֹ מֵת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמּוֹנֶה מִיּוֹם הַמָּחֳרָת, וְאוֹתוֹ יוֹם אֵינוֹ עוֹלֶה.",[],["\u0003אחרת. \u0004 אבל הקוברים בבה\"ק סמוך לעיר החוזרים משערי העיר אין מתאבלין עד שיאמרו להם שנקבר ונ\"מ לענין קובר מתו בערב הרגל עכ\"ל הש\"ך \u0005(ועוד יש נ\"מ דכתב לעיל סי' שע\"ד דנשתרבב המנהג שאין אב ואם הולכין אחר בניהם הראשון א\"כ אם אירע כן בערב הרגל אין למנות מעת שיחזרו פניהם מללוות אלא ג\"כ עד שאומרים לו שנקבר. ונ\"מ שאם אירע כן שאומרים לו שנקבר הוא קודם בין השמשות זמן מה שא\"צ עוד למנות ז' אבל אם אומרים שנקבר והוא בין השמשות צריך למנות ז' אחר הרגל (בה\"י)\u0006 והנה בשיעור ריחוק מקום אחר לא הוזכר פה אלא כשהוא רחוק כ\"כ שאינם יודעים מתי יקבור וזהו סברת הרמב\"ם בשיעור זה. והרמב\"ן כתב סתם במוליכין אותו מעיר לעיר דכיון שמסרוהו לאיזו שמוליכין אותו והחזירו פניהם כבר נתיאשו ממנו ויאוש כסתימת גולל וכו' ואח\"כ כתב וכן נראין דברי הרמב\"ם ז\"ל שכתב מי שדרכן לשלוח המת למדינה אחרת לקברו ואינם יודעים מתי יקבר מעת שיחזרו פניהם מתחילין למנות כו' ואח\"כ כתב דעת בה\"ג שלא חילק אלא כדנפיק ממתא ואינשי ליה מקרובים חדא שעתא מקמי דליפול רגל חלה אבילות עליהם ובטלה ממנו גזרת ז' והכריע הב\"י כהרמב\"ם וזהו שכתב כאן כשהוא רחוק כ\"כ שאינם יודעים מתי יקבר. והרדב\"ז שאלה ס\"ג כתב ג\"כ כרמב\"ם והרמב\"ן אלא שכתב לבסוף והיכא דנקבר בה\"ש של ע\"ש חל האבילות אפילו על אותן שלא הלכו עם המטה ועולה להם יום א' וכן אם היה ערב הרגל מבטל מהם הרגל גזרת ז' אע\"פ שלא חזרו הקרובים אלא אחר שנכנס שבת או הרגל אע\"פ שבשאר הימים לא חל עליהם אבילות עד שיחזרו הקרובים כדעת הרמב\"ן. ע\"ש עוד. ועי' תשובת דרכי נועם שאלה י\"ט וך'. וראנ\"ח ח\"ב שאלה נ\"ח):","\u0003שבכאן. \u0004 כתב הש\"ך ומדברי הרמב\"ן מבואר דדוקא אם יכול לבא אל הקבר תוך ג' ימים אבל אם אינו יכול לבא תוך ג' ימים אלו שבבית מונין מיד וגדול הבית שבבה\"ק משיסתם הגולל ואין נגררים עמו ע\"כ ודוקא לחומרא אזלינן בתר גדול המשפחה דאין מונין אלא משיקבר אבל אם גדול המשפחה הוא אצל אלו שנשארו בבית אינו מעלה ומוריד אלא אעפ\"כ ההולכין עם המת אין מונין אלא משיקבר אבל דעת הטור דהכל הולך אחר גדול הבית דאם נשאר כאן אלו ואלו מונין משיצא המת וכן נראה דעת הרמב\"ן וכו' ע\"ש:","\u0003דביתא. \u0004 וכתב הרשב\"א דמי שמתה אשתו הבעל נקרא גדול המשפחה:","\u0003כקבורה. \u0004 דהוי כנתיאשו מלקברו דאע\"ג דרוצים לקברו אח\"כ בבה\"ק מ\"מ השתא במצור ה\"ל קבורה מעלייתא לדידהו שהרי אם תלכד העיר לא יקברוהו בענין אחר עכ\"ל הש\"ך:","\u0003משנתיאשו. \u0004 ואין חילוק בין נתיאשו תוך ל' או אחר ל'. ש\"ך:","\u0003מלקברו. \u0004 כתב הט\"ז מעשה ביהודי אחד שהרגוהו בעשרה בטבת והשליכוהו בנהר רינו\"ס ולפני אדר נתיאש בנו מלבקשו עוד והורה ר' יעקב למנות מעתה שבעה ושלשים ולאחר שעברו ימי האבילות נמצא אביו בתוך הנהר והובא לבה\"ק והורה לו הזקן רק לקרוע והסכים עמו הרמב\"ן עכ\"ל:","\u0003סוף. \u0004 לאפוקי אם אין להם סוף דאין מתאבלין כלל מאחר שאין היתר לאשתו לא ינהגו אבילות וכן מ\"ש או שיצא קול וכו' או שגררתו חיה דהיינו נמי בענין שמותרת אשתו להנשא וכ\"כ הרב בא\"ע סי' י\"ז ס\"ה דאשתו אסורה להספיד או ללבוש שחורים כל זמן שאין כאן עדות שהוא ראוי להשיאה על ידו ע\"ש עכ\"ל הש\"ך:","\u0003שם. \u0004 כ' הש\"ך וה\"ה אם אינן שם ושמע באותו היום צריכין להתאבל כל אותו היום וגם בקרובים הדין כן ודלא כהמחבר וצ\"ע עכ\"ל:","\u0003שדינם. \u0004 היינו היכא שלא הלך גדול הבית עמהם לעיר אחרת כדלעיל ס\"ב. ש\"ך:","\u0003וי\"א. \u0004 הנה הש\"ך האריך מאד בדינים אלו וכלל העולה מדבריו ומסקנתו לענין דינא הוא כך. מי שמת לו קרוב ונודע לו במקומו מונה לעצמו משנודע לו ואפילו בא אח\"כ למקום המת אצל שאר הקרובים שהתחילו כבר להתאבל לא יקצר אבלתו בשביל זה. וכן אם בא אצל הקרובים ואינם במקום שמת המת ולא במקום קבורה כל א' מונה לעצמו משעה שנודע לו. אבל אם לא ידע שמת לו מת עד שבא אצל הקרובים שבמקום המת או מקום קבורה אם היה במקום קרוב שהוא מהלך עשר פרסאות אפי' בא ביום הז' אם מצא מנחמין אצל גדול הבית אפי' שננערו לעמוד \u0005(הואיל ומצא מנחמין עדיין שנוהגים קצת אבילות)\u0006 מונה עמהן דכיון שהגדול מונה עמהם גם הוא מונה עמהם אבל אם לא מצא אצלם גדול הבית מונה לעצמו וכן גדול הבית שבא ממקום קרוב מונה לעצמו ואם בשעת קבור' הלכו מקצת הקרובים לבה\"ק מונין עם אלו שבבית בין גדולים בין קטנים בין שבה\"ק קרוב או רחוק בין באו תוך ג' בין ביום ז'. והוא שבאו ומצאו מנחמין אצלם אבל אם לא מצאו מנחמין ביום ז' אותן שהלכו לבה\"ק מונין לעצמן משיסתם הגולל. וכן הבא ממקום אחר לשם ומצא שהלך הגדול לבה\"ק כיון שחזר הגדול אצלם אפי' ביום ז' ומונה עמהם אף זה נגרר עמהם ונמצא כולם מונין מנין א'. והוא שבא זה ממקום קרוב. ודוקא שנשארו מקצתן בבית אבל אם לא נשארו מקצתן בבית מונה לעצמו אם לא שבא תוך ג'. ואם לא חזר הגדול תוך ז' שאז הגדול מונה לעצמו משיסתם הגולל אז הבא ממקום קרוב ג\"כ \u0005(אינו מונה עם אותן שבבית משיצא המת)\u0006 אלא מונה לעצמו משעה שנודע לו. וכל זה שהלך הגדול לבה\"ק במקום שאינו דר שם אבל הלך למקום שדר שם ונשאר שם אפי' אותן שנשארו כאן שהחזירו פניהם מהמת הולכים אחריו ומונים משיסתם הגולל. ודוקא שיכול לבא שם תוך שלשה אבל אם אינו יכול לבא שם תוך שלשה אלו שבכאן מונים מיד וגדול שבבה\"ק מונה משיסתם הגולל ואם התחילו אותן שבבית והגדול למנות אבילותן בשוה הן משיצא המת או משיסתם הגולל אז הבא ממקום קרוב מונה עמהן בכל ענין אפילו בא ביום השביעי בעוד שנוהגין קצת אבילות כיון שחזר הגדול קודם שעמדו המנחמין ומונה עמהן אבל אם התחילו אבילותן בשוה והלך הגדול אח\"כ לבית הקברות להתעסק בצרכי המת לעשות מצבה או בנין לקבר ולא חזר כלל אחר שבא הקרוב או שחזר אחר שעמדו המנחמין אז דינא הכי אם בא הקרוב תוך שלשה מונה עמהם ואם בא לאחר ג' מונה לעצמו ואם הלך הגדול לעסק אחר שלא לצורך המת אפילו בא הקרוב תוך ג' מונה לעצמו כיון שלא חזר הגדול לביתו ואם בא הקרוב ממקום רחוק בכל ענין מונה לעצמו וכל שדינו למנות עמהם אפילו חזר אחר כך לביתו מונה עמהם עכ\"ל:","\u0003שהתפלל. \u0004 אבל אם עדיין הוא לא התפלל ערבית כתבו מהרש\"ל וב\"ח שאותו יום עולה לו אף על פי שהקהל התפללו ערבית. ואפילו למ\"ד לעיל סימן קצ\"ו לענין נדה דבתר צבורא גרירה שאני גבי אשה שרובן אינן מתפללות ונגררות אחר הקהל לכן אף אם היא רגילה להתפלל לא חלקו בדבר משא\"כ הכא כ\"כ מהרש\"ל א\"נ יש לחלק דלעיל איירי שהקהל התפללו ערבית והיא רצתה להקל על עצמה לעשות יום וללבוש לבנים לאו כל כמינה לאפוקי נפשה מצבורא אבל כאן מן השמים שלחו לו אבלות בעוד יום ולא התפלל עדיין יכול לומר לדידי יום הוא ולפ\"ז אף אם אירע אבלות כזה לאשה שלא התפללה ג\"כ אותו יום עולה לה ודלא כדמשמע ממהרש\"ל וכן עיקר עכ\"ל הש\"ך \u0005(אחד שנקבר סמוך לשבת ותיכף אחר הקבורה הפכו פניהם לבהכ\"נ ולא ישבו על הארץ אעפ\"כ עולה יום ו' למנין ז' דהפיכת פניהם הוי התחלת אבלות)\u0006 \u0005(הראנ\"ח ח\"ב סימן נ\"א)\u0006:"]],["אֵין הַמְנַחֲמִים רַשָּׁאִים לִפְתֹּחַ, עַד שֶׁיִּפְתַּח הָאָבֵל תְּחִלָה. וְהָאָבֵל מֵסֵב בָּרֹאשׁ, וְכֵיוָן שֶׁנִּעְנַע הָאָבֵל בְּרֹאשׁוֹ, בְּעִנְיָן שֶׁנִּרְאֶה שֶׁפּוֹטֵר אֶת הַמְנַחֲמִים, אֵינָם רַשָּׁאִים לֵישֵׁב אֶצְלוֹ. \u0005אֵין אָבֵל אוֹ חוֹלֶה חַיָּבִים לַעֲמֹד, אֲפִלּוּ מִפְּנֵי נָשִׂיא (פ' א\"מ)\u0006.\nהַבָּא לְכַבֵּד אֶת חֲבֵרוֹ וְלָקוּם מִפָּנָיו, אוֹמֵר לוֹ: שֵׁב, אֶלָא אִם כֵּן הוּא אָבֵל אוֹ חוֹלֶה, דְּמַשְׁמָע: שֵׁב בָּאֲבֵלוּת שֶׁלְךָ, שֵׁב בַּחֹלִי שֶׁלְךָ. \u0005הַגָּה: לֹא יֹאמַר אָדָם: לֹא נִפְרַעְתִּי כְּפִי מַעֲשַׂי, אוֹ כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, שֶׁאַל יִפְתַּח פִּיו לַשָּׂטָן (כֵּן מַשְׁמָע בְּפֶרֶק מִי שֶׁמֵּתוֹ וּבְהַגָּהוֹת אַלְפָסִי שָׁם)\u0006. וְאַל יֹאמַר אָדָם לְאָבֵל: מַה לְּךְ לַעֲשׂוֹת כִּי אִי אֶפְשָׁר \u0010c0\u0011 לְשַׁנּוֹת, שֶׁזֶּהוּ כְּגִדּוּף, דְּמַשְׁמָע הָא אִם אֶפְשָׁר לְשַׁנּוֹת הָיָה עוֹשֶׂה, אֶלָּא יְקַבֵּל עָלָיו גְּזֵרַת הַשֵּׁם יִתְבָּרַךְ מֵאַהֲבָה \u0005(נ\"י פ' שׁוֹר שֶׁנָּגַח דְּמַשְׁמָע כֵּן בַּגְּמָרָא)\u0006.\nמֵת שֶׁאֵין לוֹ אֲבֵלִים לְהִתְנַחֵם, בָּאִים עֲשָׂרָה בְּנֵי אָדָם כְּשֵׁרִים וְיוֹשְׁבִים בִּמְקוֹמוֹ כָּל ז' יְמֵי הָאֲבֵלוּת, וּשְׁאָר הָעָם מִתְקַבְּצִים עֲלֵיהֶם; וְאִם לֹא הָיוּ שָׁם עֲשָׂרָה קְבוּעִים, בְּכָל יוֹם וְיוֹם מִתְקַבְּצִים עֲשָׂרָה מִשְּׁאָר הָעָם וְיוֹשְׁבִים בִּמְקוֹמוֹ. \u0005הַגָּה: וְלֹא רָאִיתִי נוֹהֲגִין כֵּן. וְכָתוּב במהרי\"ל: נוֹהֲגִים \u0010c1\u0011 לְהִתְפַּלֵּל בַּעֲשָׂרָה כָּל ז' בַּמָּקוֹם שֶׁנִּפְטַר שָׁם הָאָדָם, וְהַיְנוּ עַל אָדָם שֶׁלֹּא הִנִּיחַ קְרוֹבִים יְדוּעִים לְהִתְאַבֵּל עָלָיו, אֲבָל יֵשׁ לוֹ בְּשׁוּם מָקוֹם שֶׁמִּתְאַבְּלִים עָלָיו, אֵין צָרִיךְ וְכָזֶה רָאוּי לִנְהֹג.\u0006\nעַכְשָׁו נוֹהֲגִים שֶׁאַחַר שֶׁנִּגְמַר סְתִימַת הַקֶבֶר מֵעָפָר \u0005אוֹ לְאַחַר שֶׁהָפַךְ הָאָבֵל פָּנָיו מִן הַמֵּת,\u0006 חוֹלְצִין מִנְעָל וְסַנְדָּל וּמַרְחִיקִין \u0010c2\u0011 מְעַט מִבֵּית הַקְבָרוֹת, וְאוֹמְרִים קַדִּישׁ דְּהוּא עָתִיד לְחַדְּתָא עָלְמָא, וְאַחַר כָּךְ תּוֹלְשִׁין \u0010c3\u0011 עָפָר וְתוֹלְשִׁין עֲשָׂבִים, וּמַשְׁלִיכִים אַחַר גֵוָם וְרוֹחֲצִין יְדֵיהֶם \u0010c4\u0011 בְּמַיִם. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁיּוֹשְׁבִים ז\"פ, מִפְּנֵי שֶׁהָרוּחוֹת מְלַוּוֹת אוֹתוֹ, וְכָל זְמַן שֶׁיּוֹשְׁבִין, בּוֹרְחִין מִמֶּנּוּ (מהרי\"ל בִּתְשׁוּבָה כ\"ג בְּשֵׁם י\"א)\u0006. וּבִמְדִינוֹת אֵלּוּ לֹא נָהֲגוּ לֵישֵׁב רַק ג\"פ, אַחַר שֶׁרָחֲצוּ הַיָּדַיִם, וְאוֹמְרִים כָּל פַּעַם: וִיהִי \u0010c5\u0011 נֹעַם וְגו' \u0005(תְּהִלִּים צ, יז)\u0006, יוֹשֵׁב בְּסֵתֶר \u0005(תְּהִלִּים צא, א)\u0006 וְגו' וּכְשֶׁנִּקְבָּר הַמֵּת בְּיוֹם טוֹב, יְכוֹלִין לֵישֵׁב כָּךְ ג\"פ כְּמוֹ בַּחֹל \u0005(מ\"כ בְּהַגָּהוֹת מִנְהָגִים)\u0006. וְהוּא הַדִּין אִם נִקְבַּר סָמוּךְ לְשַׁבָּת, עוֹשִׂין כֵּן בְּשַׁבָּת. וְנָהֲגוּ לְהַקְפִּיד אִם יִכָּנֵס אָדָם לְבַיִת אַחֵר קֹדֶם שֶׁיִּרְחַץ וְיֵשֵׁב ג\"פ, וּמִנְהַג אֲבוֹתֵינוּ תּוֹרָה \u0005(שָׁם במהרי\"ל)\u0006. וְנִמְצָא בְּמִדְרָשׁוֹת לוֹמַר קַדִּישׁ עַל אָב \u0005(כָּל בּוֹ וריב\"ש בְּשֵׁם תַּנְחוּמָא וְסִפְרִי, וּבְחַיֵּי בְּשֵׁם מַסֶכֶת כַּלָּה, וּבֵית יוֹסֵף בְּשֵׁם הַזֹּהַר, וּבְאוֹר זָרוּעַ בְּשֵׁם תַּנָּא דְּבֵי אֵלִיָּהוּ רַבָּא)\u0006 ; עַל כֵּן נָהֲגוּ לוֹמַר עַל אָב וָאֵם קַדִּישׁ בַּתְרָא י\"ב חֹדֶשׁ, וְכֵן נָהֲגוּ לְהַפְטִיר בַּנָּבִיא, וּלְהִתְפַּלֵּל עַרְבִית בְּמוֹצָאֵי שַׁבָּתוֹת שֶׁהוּא הַזְּמַן שֶׁחוֹזְרִין הַנְּשָׁמוֹת לְגֵיהִנֹּם, וּכְשֶׁהַבֵּן מִתְפַּלֵּל וּמְקַדֵּשׁ בָּרַבִּים, פּוֹדֶה אָבִיו וְאִמּוֹ מִן הַגֵּיהִנֹּם \u0005(כָּל בּוֹ בְּשֵׁם הַגָּהוֹת)\u0006. וְנָהֲגוּ לוֹמַר קַדִּישׁ עַל הָאֵם אַף עַל פִּי שֶׁהָאָב חַי עֲדַיִן, אֵינוֹ בְּיָדוֹ לִמְחוֹת לִבְנוֹ שֶׁלֹּא יֹאמַר קַדִּישׁ עַל אִמּוֹ \u0005(סְבָרַת הַבֵּית יוֹסֵף עַל פִּי הַמִּנְהָג)\u0006. מִצְוָה לְהִתְעַנּוֹת בְּיוֹם שֶׁמֵּת אָב אוֹ אֵם \u0005(ריב\"ש וְכָל בּוֹ)\u0006. שְׁלֹשָׁה אַחִין וְאִישׁ \u0010c6\u0011 נָכְרִי, הַשְּׁלֹשָׁה אַחִין נוֹטְלִין הַשְּׁלֹשָׁה קַדִּישִׁין וְהָאוֹמֵר נוֹטֵל קַדִּישׁ אֶחָד. וְנָהֲגוּ שֶׁאִם מַגִּיעַ לְאָדָם יוֹם שֶׁמֵּת בּוֹ אָבִיו וְאִמּוֹ, שֶׁאוֹמְרִים עֲלֵיהֶם קַדִּישׁ יָתוֹם לְעוֹלָם, וּמִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, מִתְפַּלֵּל; וְאִם יֵשׁ אֲבֵלִים אֲחֵרִים, נָהֲגוּ שֶׁתּוֹךְ שִׁבְעָה לְאֶבְלָם הֵם \u0010c7\u0011 קוֹדְמִים, וְאֵין לוֹ קַדִּישׁ כְּלָל; תּוֹךְ שְׁלֹשִׁים, יֵשׁ לוֹ קַדִּישׁ \u0010c8\u0011 אֶחָד; לְאַחַר ל', כָּל הַקַּדִּישִׁים שֶׁל אוֹתוֹ הַיּוֹם הֵם שֶׁלּוֹ. וּמוֹנִין שִׁבְעָה וְל' מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמַע הָאָבֵל מִיָּד \u0005(במהרי\"ל)\u0006. וְאִם נָכְרִי הוּא כְּאֶחָד מִבְּנֵי הָעִיר לְעִנְיַן קַדִּישׁ זוֹ, הוֹלְכִים אַחַר \u0010c9\u0011 הַמִּנְהָג \u0005(אָגוּר)\u0006. וְאֵין מָקוֹם לְקַדִּישׁ זוֹ אֶלָּא עַל אָב וָאֵם בִּלְבַד, אֲבָל לֹא בִּשְׁאָר קְרוֹבִים \u0005(בְּאוֹר זָרוּעַ)\u0006. וְאִם אֵין בב\"ה אָבֵל עַל אָבִיו וְאִמּוֹ, אוֹמֵר אוֹתוֹ קַדִּישׁ מִי שֶׁאֵין לוֹ אָב וָאֵם, בְּעַד כָּל מֵתֵי יִשְׂרָאֵל. \u0005(שָׁם)\u0006 וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁשְּׁאָר קְרוֹבִים אוֹמְרִים קַדִּישׁ עַל קְרוֹבֵיהֶם כְּשֶׁאֵין אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, וְיֵשׁ מְקוֹמוֹת שֶׁאֲפִלּוּ יֵשׁ אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, אוֹמְרִים שְׁאָר קְרוֹבִים, אֶלָּא שֶׁעוֹשִׂים פְּשָׁרָה בֵּינֵיהֶם שֶׁאֵין אוֹמְרִים כָּל כָּךְ קַדִּישִׁים כְּמוֹ הָאֲבֵלִים עַל אָב וָאֵם \u0005(מהרי\"ק שֹׁרֶשׁ מ\"ד)\u0006 ; וְהוֹלְכִין בְּכָל זֶה אַחַר הַמִּנְהָג, וּבִלְבַד שֶׁיְּהֵא מִנְהָג קָבוּעַ בָּעִיר. וְהָאֲבֵלִים אוֹמְרִים קַדִּישׁ אֲפִלּוּ בְּשַׁבָּת וְיוֹם טוֹב \u0005(בְּאוֹר זָרוּעַ בְּשֵׁם ר\"י מקורבי\"ל)\u0006, אֲבָל לֹא נָהֲגוּ לְהִתְפַּלֵּל בְּשַׁבָּת וְיוֹם טוֹב \u0005(כֵּן הוּא בִּתְשׁוּבַת מהרי\"ל)\u0006, אַף עַל פִּי שֶׁאֵין אִסּוּר בַּדָּבָר, אֲבָל בִּימוֹת הַחֹל, מִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל, יִתְפַּלֵּל וְיוֹתֵר מוֹעִיל מִקַּדִּישׁ יָתוֹם שֶׁלֹּא נִתְקַן אֶלָּא לִקְטַנִּים; וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, יִתְפַּלֵּל לַמְנַצֵּחַ וּבָא לְצִיּוֹן וְכו' \u0005(בְּאוֹר זָרוּעַ)\u0006. וְנָהֲגוּ שֶׁאֵין אוֹמְרִים קַדִּישׁ וּתְפִלָּה \u0010c10\u0011 רַק י\"א חֳדָשִׁים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אֲבִיהֶם וְאִמָּם רְשָׁעִים, כִּי מִשְׁפַּט רָשָׁע י\"ב חֹדֶשׁ. וְאִם הָיוּ אֲבֵלִים כָּאן וּבָאוּ אַחַר כָּךְ אֲבֵלִים אֲחֵרִים, הַשְּׁנִיִּים יֵשׁ לָהֶם הַקַּדִּישִׁים וְהַתְּפִלּוֹת כָּל ל' יוֹם מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמְעוּ. יֵשׁ אוֹמְרִים דְּמוּמָר \u0010c11\u0011 שֶׁנֶּהֱרַג בְּיַד עוֹבְדֵי כּוֹכָבִים, בָּנָיו אוֹמְרִים עָלָיו קַדִּישׁ \u0005(הרד\"כ בַּיִת י\"א ובב\"ז)\u0006 וְעַיֵּן לְעֵיל סִימָן ש\"מ.",[],["\u0003לשנות. \u0004 כתב הט\"ז דמהרש\"ל דחה זה מהלכה שאמר הלא גם דוד המע\"ה אמר כן האוכל להשיבו עוד דמשמע אם היה אפשר להשיבו היה עושה. ותמיהני עליו דשאני גבי דוד שאמר למה זה אני צם האוכל להשיבו וגו' וזה אמר דוד כיון שכבר מת לא יועילו הצומות אבל אותן המנחמים שאומרים אל תצער עצמך כי מה לך לעשות אין אומרים על התפלה והצומות כן אלא על הצער שלא יצער עצמו כיון שא\"א בענין אחר דמשמע הא אפשר בענין אחר היה לו לצער על שלא יהיה כרצון האדם וזהו גידוף שמן הראוי להיות כרצון האל יתברך לא כרצון האדם עכ\"ל:","\u0003להתפלל. \u0004 בא\"ח סי' קל\"א כתב דאין אומרים תחנון בבית האבל והיינו כל ז' ימים. וכתב הרוקח שאחר גמר התפלה אומרים תחנון ואין קורין הלל בר\"ח בבית האבל לפי שיש שם אנינות לכך אין אומרים לא המתים יהללו יה משום לועג לרש וכתב הב\"ח דבימים נוראים אם האבל הגון ולא נמצא כמוהו הוא קודם להתפלל אפי' תוך ל' על אביו ואמו וכן נמצא בהג\"ה ולא כיש מקפידים עכ\"ל הט\"ז:","\u0003מעט. \u0004 היינו עכ\"פ ד' אמות וכתב בב\"ה בשם א\"ח דאם נקבר בלילה א\"א לא צדוק הדין ולא קדיש בבה\"ק:","\u0003עפר. \u0004 ואומרים זכור כי עפר אנחנו \u0005(ופה קהלתינו אין נוהגין לתלוש עשבים מפני סכנת בלבול. במס' שמחות מעשה באשה שחלה בנה והקיפו את העזרה מכאן נראה שנהגו להקיף בה\"ק (אגודה)\u0006 ומזה נתפשט המנהג שמודדין הבית חיים סביביו בפתילות ואח\"כ עושין בהן נרות של שעוה ונותנין אותו לבהכ\"נ והכל מנהג טוב):","\u0003במים. \u0004 לרמז דטומאה זו אינה נטהרת אלא בכעין ג' דברים הללו מים ואפר פרה ואזוב. הרמב\"ן:","\u0003נעם. \u0004 כתב מהרש\"ל שקיבל מאביו זקינו שיש לומר ז' פעמים דהיינו בפעם א' עד מלת כי ומלת כי בכלל ובפעם הב' עד כי מלאכיו. ובג' עד כי מלאכיו יצוה. ובד' עד יצוה לך. ובה' עד לך לשמרך. ובו' עד לשמרך בכל. ובז' עד בכל דרכיך ויש בו סודות וכ' בלבוש שגם הוא נהג כן. ט\"ז. ויאמר אתה גבור וכו' שיש בזה סוד הקבלה להבריח כחות הטומאה לבוש וע\"ש:","\u0003נכרי. \u0004 כלומר שאינו אח שלהן אפילו הוא תושב. ש\"ך:","\u0003קודמים. \u0004 כתוב במנהגים דאפי' הבן ז' הוא איש נכרי דוחה את התושב אפי' בן ל' או יא\"צ וכל זה דוקא בשבת שבתוך ז' אבל בחול אינו הולך לבהכ\"נ. אך אם הבן ז' הוא קטן שאינו בר מצוה והולך לבהכ\"נ כל ז' לומר קדיש או מי שאירע לו מיתת אב ואם תוך אותן ז' יאמר קדיש יתום פעם א' ע\"כ. וכ' הש\"ך ונראה דמי שבטלה אבלותו ברגל כגון שעה א' לפני הרגל דבטלה ממנו גזרת ז' או ל' ומ\"מ דין ז' ול' יש לו אפילו בחול כמו בשבת דהרי בדין הולך לבהכ\"נ והנה בתשובת מ\"ב הקשה שדברי המנהגים סותרים זא\"ז דמתחלה כתב יום שמת אב ואם לתושב דוחה את בן ל' מכ\"ש בן י\"ב חדש לתושב כל אותו יום התענית דהיינו תפלת ערבית ושחרית ומנחה. וכן הקדישים של אותו יום שאומרים לפני העמוד אלמא דס\"ל דיא\"צ עדיף. ושוב כתב דבן י\"ב חדש ויא\"צ אורח יש לאורח קדיש א' אבל בן ל' אורח מחלק עמו כל הקדישים והתפלות אלמא דבן ל' עדיף. ותירץ דברישא מיירי שיש הרבה יא\"צ ואיכא דוחק בקדישים ואינו מגיע לכל א' קדיש אז נדחה הבן ל' מפני היא\"צ. והטעם שאם לא יאמר היא\"צ באותו יום קדיש אז עבר היום בטל הקרבן. משא\"כ בבן ל' שיוכל לומר למחר אבל היכא דאיכא רווחא בקדישים כגון בשבת אז הבן ל' עדיף לומר ב' קדישים והיא\"צ קדיש א' עכ\"ל והסכים עמו הט\"ז וכתב שחילוק נכון הוא. אבל הש\"ך השיג עליו וכתב דהדברים כפשטן הם דס\"ל למנהגים דיא\"צ עדיף מבן שלשים ול\"ק מ\"ש בסוף דאורח יא\"צ אין לו רק קדיש א' ובן שלשים חולק עם התושב בן יב\"ח. די\"ל דודאי לענין אורח נגד תושב בן ל' עדיף. משום דמצי התושב לומר ליא\"צ האורח הואיל וזמנך קבוע וידוע קודם לכן שנה תמימה ואתה באת בגבולי די לך בקדיש א' אבל בבן ל' ליכא למימר הכי ולפ\"ז לדידן דקי\"ל דבן ל' עדיף א\"כ אם אירע בן ל' תושב תוך ז' לקטן יש לו ג\"כ קדיש א' והכי נהוג עכ\"ל וכ' עוד בתשו' מ\"ב דאפילו בן ז' א' גדול ותושב ובן ז' אחד קטן ואורח אפ\"ה חולקים בשוה והט\"ז כ' ונ\"ל דמי שמת בשבת או ביו\"ט וא\"א לקברו בו ביום דעכ\"פ יאמר קדיש תיכף אחר המיתה דאין אמירת קדיש תלוי באבילות כלל אבל בחול אין לעשות כן דהא כשהוא אונן פטור מן התפלה עכ\"ל \u0005(ובנה\"כ חולק ע\"ז וכתב כיון דטעם הקדיש הוא שפודה את אביו מגיהנם א\"כ כל זמן שלא נקבר אין בו דין גיהנם וכמדומה שכן נוהגין עכ\"ל)\u0006:","\u0003אחד. \u0004 ליא\"צ אבל לבן יב\"ח אין לו כלום שהתושב בן ל' דוחה את התושב בן יב\"ח בתפלה ובקדיש שלפני העמוד אך בקדיש ובפריסת שמע שעל פתח בה\"כ שניהם שוין בו ויחלקו בגורל ויש מנהגים אחרים בקדיש ובפריסת שמע שעל הפתח ונהרא נהרא ופשטיה ומשמע דאם הוא בשבת דיש ג' קדישים אומר הבן ל' ב' קדישים והיא\"צ קדיש א'. ובמנהגים כתב דיא\"צ תושב דוחה את בן ל' מיהו הלבוש בא\"ח סי' קל\"ג השיג ע\"ז וכתב שאין היא\"צ דוחה את בן ל' מכל וכל אלא די לו בקדיש א' וכן עיקר וכן נהגו עכ\"ל הש\"ך:","\u0003המנהג. \u0004 יש קהלות דנהגו דתושב דוחה את האורח ויש מקומות דשוין הם ומקומות דנהיגי דתושב דוחה האורח מ\"מ פעם ראשונה יש רשות לאורח להתפלל ולומר קדיש יתום פעם א' כ\"כ במנהגים ונ\"ל דהיינו דהוי כמו תושב בן יב\"ח ולפ\"ז היכא דהתושב אין לו קדיש א' כגון שיש כאן בן ל' וכה\"ג גם לאורח אין לו כלום. ש\"ך. וכתוב עוד במנהגים דאם אותו שמת יש לו בנים בעיר אחרת ובאו לשם אינם נקראים תושבים בשביל אביהם שנקבר שם רק אותן הדרים בתוך הקהלה וכל דרי הקהלה נקראים תושבים הן אותן שנותנין מס או משרתי הקהלה ואפי' עניי העיר שיש להם שם דירת קבע כולם נחשבים כתושבים ואם אדם קובע דירתו תוך הקהלה אז משעה שהוא חייב לישא בעול עם דרי הקהלה חשוב תושב אבל לא משעה שגמר פיסוק המס עם ההגמון אע\"ג שצריך ליתן המס להגמון. וכן איפכא מי שעקר דירה מן הקהלה אז משעה שאינו חייב לישא בעול עם דרי הקהילה חשוב כאורח אע\"פ שחייב עדיין ליתן המס להגמון ואם יש לבעל הבית מלמד או שמש המושכר לזמן והוא פנוי שאין לו אשה ובנים אז גם הוא נקרא תושב אבל אם יש לו אשה ובנים במקום א' אז דינו כאיש נכרי ואם בעה\"ב מגדל בביתו יתום אפי' בשכר ואין לו אב או אם במ\"א אז נקרא תושב אבל אם יש לו אב או אם אינו נקרא תושב אפי' אם מגדלו בתורת צדקה ומכ\"ש אם הוא אצלו בשכר ע\"כ ונראה דנערים ובחורים הלומדים בישיבה אפי' יש להם אב או אם במקום אחר יש להם דין תושב ואפילו בעה\"ב שלומד בישיבה אע\"פ שיש לו אשה ובנים במקום אחר ונותן מס במקום שאשתו ובניו שם מ\"מ דין תושב יש לו במקום שהוא לומד והכי נהוג. ש\"ך. וכתוב עוד במנהגים דהיכא ששניהם בני ל' או שניהם יא\"צ או בני י\"ב חודש נדחה האורח לגמרי מלהתפלל ולומר קדיש לפני העמוד אך בפריסת שמע וקדיש על הפתח שניהם שוין ויחלקו בגורל ואם האורח והתושב שניהם בני ז' יחלקו בגורל כי לענין שבעה אין שום עילוי לתושב על האורח עכ\"ל:","\u0003רק. \u0004 ע\"ל סי' ר\"מ ס\"ט מה שמחלק הט\"ז שם דצריך לכתוב הכ\"מ כל י\"ב חדש ומאי שנא מהכא לענין קדיש ע\"ש:","\u0003שנהרג. \u0004 דוקא נהרג דאז יש לו כפרה ע״י ההריגה אבל מת על מטתו לא וכ״מ לעיל סי' ש״מ לענין אבילות וחילוק זה בין מת או נהרג הוא בש״ס פ' נגמר הדין (סנהדרין דף מ״ז) עכ״ל הט״ז:"]],["הָעֲבָדִים וְהַשְּׁפָחוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, וְאֵין אוֹמְרִים עֲלֵיהֶם תַּנְחוּמֵי אֲבֵלִים, אֶלָא אוֹמְרִים לוֹ: הַמָּקוֹם יְמַלֵא חֶסְרוֹנְךָ, כְּשֵׁם שֶׁאוֹמְרִים לְאָדָם עַל שׁוֹרוֹ וַחֲמוֹרוֹ.\nאָבֵל מְנֻדֶּה, אֵין \u0010c0\u0011 מַבְרִין אוֹתוֹ וְאֵין אוֹמְרִים לוֹ תַּנְחוּמֵי אֲבֵלִים.\nמְנֻדֶּה שֶׁמֵּת, מְנַחֲמִים אֲבֵלָיו.",[],["\u0003מברין. \u0004 דכל דבר שהוא משום כבוד לחיים אין עושין לאבל שהוא מנודה. וע\"ל סי' שמ\"ה ס\"ד. עכ\"ל הש\"ך \u0005(ועיין בבה\"י)\u0006:"]],["אָבֵל \u0010c0\u0011 אָסוּר לֶאֱכֹל מִשֶּׁלוֹ בִּסְעֻדָּה רִאשׁוֹנָה, אֲבָל בַּשְּׁנִיָּה מֻתָּר, אֲפִלוּ בְּיוֹם רִאשׁוֹן. וּמִצְוָה עַל שְׁכֵנָיו שֶׁיַּאֲכִילוּהוּ מִשֶׁלָהֶם, כְּדֵי שֶׁלֹּא יֹאכַל מִשֶּׁלוֹ. וְיָכוֹל אֶחָד לְהַאֲכִיל אֶת חֲבֵרוֹ בִּימֵי אֶבְלוֹ, וְהוּא \u0010c1\u0011 יַחֲזֹר גַם כֵּן וְיַאֲכִילֶנּוּ בִּימֵי אֶבְלוֹ, וּבִלְבַד שֶׁלֹּא יַתְנוּ בִּתְחִלָה.\nאִשָּׁה שֶׁאֵרְעָהּ אֵבֶל, אֵין לַאֲנָשִׁים לְהַבְרוֹתָהּ; אֲבָל נָשִׁים מַבְרִין אוֹתָהּ. וְאִשָּׁה נְשׂוּאָה שֶׁאֵרְעָהּ אֵבֶל, אֵינָהּ יְכוֹלָה לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעֲלָהּ. וְכֵן מִי שֶׁיֵּשׁ לוֹ סוֹפֵר אוֹ שָׂכִיר, אִם אוֹכֵל בִּשְׂכָרוֹ וְאֵרְעוֹ אֵבֶל, לֹא יֹאכַל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. אֲבָל מִי שֶׁזָּן עָנִי אוֹ יָתוֹם אוֹ לִבְנוֹ וּבִתּוֹ, בְּלֹא תְּנַאי, וְאֶרְעָם אֵבֶל, יְכוֹלִים לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת.\nאִם רָצָה הָאָבֵל שֶׁלֹּא \u0010c2\u0011 לֶאֱכֹל בַּיּוֹם הָרִאשׁוֹן, מֻתָּר לֶאֱכֹל מִשֶּׁלוֹ אֲפִלוּ סְעֻדָּה רִאשׁוֹנָה. \u0005הַגָּה: וְכֵן אִם לֹא הִבְרוּהוּ בְּיוֹם רִאשׁוֹן שֶׁנִּמְשַׁךְ עַד הַלַּיְלָה, מֻתָּר לֶאֱכֹל בַּלַּיְלָה מִשֶּׁלּוֹ, וְאֵין צָרִיךְ הַבְרָאָה (טוּר בְּשֵׁם רֹב הַפּוֹסְקִים)\u0006.\nהָיוּ נוֹהֲגִים לְהִתְעַנּוֹת בְּיוֹם מִיתַת הַחֲכָמִים.\nמִי שֶׁנִּקְבַּר בְּעֶרֶב שַׁבָּת סָמוּךְ לַחֲשֵׁכָה קֹדֶם בֵּין הַשְּׁמָשׁוֹת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּבְרִין אוֹתוֹ אָז; וְלִי נִרְאֶה דְּכֵיוָן שֶׁאֵינוֹ חוֹבָה טוֹב שֶׁלֹּא לְהַבְרוֹתוֹ אָז, מִפְּנֵי כְּבוֹד הַשַּׁבָּת, וְכֵן נוֹהֲגִין.\nאֵין מַבְרִין עַל הַקָטָן אֶלָא אִם כֵּן הוּא בֶּן שְׁלשִׁים יוֹם שְׁלֵמִים, אוֹ קִים לֵהּ בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nמַרְבִּיצִין וּמְכַבְּדִין בְּבֵית הָאָבֵל, וּמְדִיחִין קְעָרוֹת, כּוֹסוֹת וּצְלוֹחִיּוֹת וְקִיתוֹנוֹת, וְאֵין מְבִיאִין שָׁם לֹא בְּשָׂמִים וְלֹא מֻגְמָר, אֲבָל מְבִיאִים אוֹתָם בַּבַּיִת \u0010c3\u0011 שֶׁהַמֵּת שָׁם וְאֵין מְבָרְכִים עֲלֵיהֶם; וְאֵין אוֹמְרִים שְׁמוּעָה וְאַגָדָה בְּבֵית הָאָבֵל, אֶלָא יוֹשְׁבִין וְדוֹמְמִים.\nכֵּיוָן שֶׁנִּקְבַּר הַמֵּת, מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן מְעַט בְּתוֹךְ הַסְעֻדָּה, כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו אֲבָל לֹא לִרְווֹת.\nמָקוֹם שֶׁנָּהֲגוּ לְהַבְרוֹת בְּבָשָׂר וְיַיִן וּמִינֵי מַטְעַמִּים עוֹשִׂים; וּמַבְרִין תְּחִלָה בְּבֵיצִים אוֹ בְּתַבְשִׁיל שֶׁל עֲדָשִׁים, זֵכֶר לַאֲבֵלוּת, וְאַחַר כָּךְ אוֹכְלִים כָּל צָרְכָּם.\nאֵין לֶאֱכֹל עִם הָאָבֵל כָּל כָּךְ בְּנֵי אָדָם \u0010c4\u0011 שֶׁיִּתְחַלְקוּ לִשְׁנֵי מְקוֹמוֹת.\nהֵיכָא שֶׁצָּרִיךְ לִמְנוֹת שִׁבְעָה אַחַר הָרֶגֶל, וְכֵן אִם שָׁמַע שְׁמוּעָה \u0010c5\u0011 בְּשַׁבָּת, צָרִיךְ לְהַבְרוֹתוֹ הַבְרָאָה רִאשׁוֹנָה שֶׁבִּימֵי אֲבֵלוּת. \u0005וְיֵשׁ אוֹמְרִים שֶׁכֵּיוָן שֶׁנִּדְחָה יוֹם רִאשׁוֹן אֵין מַבְרִין אוֹתוֹ, וְכֵן נוֹהֲגִים (בְּמָרְדְּכַי במ\"ק בְּשֵׁם י\"א ונ\"י)\u0006, וַאֲפִלּוּ הֵיכָא דְּעוֹלֶה לוֹ לְמִנְיַן ז' כְּגוֹן בִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים, שֶׁשֵּׁנִי עוֹלֶה.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nפָּרֵיס \u0005(פֵּרוּשׁ בּוֹצֵעַ לֶחֶם לְבָרֵךְ הַמּוֹצִיא)\u0006 מְנַחֵם גָדוֹל דִּבְּהוֹן, וּבְשַׁבָּת פָּרֵיס כְּאוֹרְחֵיהּ.",[],["\u0003אסור. \u0004כתב הט\"ז נראה דאם לא שלחו לו או שהוא יחידי בעיר אינו חייב לצער עצמו שלא לאכול כלל ומש\"ה כתב המחבר דמצוה על שכניו שיאכילוהו שלא יאכל משלו דלכאורה הוא יתור לשון אלא הכוונה דעיקר מצוה על השכנים שלא יגרמו שיצטרך לאכול משלו עד כאן לשונו:","\u0003יחזור. \u0004 פי אע\"פ ששניהם אבלים. ש\"ך:","\u0003לאכול. \u0004 ומשמע דאם רצה האבל להתענות באותו היום מותר וכ\"כ הב\"ח עכ\"ל הש\"ך \u0005(ובהג\"א פרק אלו מגלחין כתב בשם א\"ז אין מניחים את האבל להתענות ביום ראשון אלא מאכילין ומשקין אותו אפילו בתענית שלפני ראש השנה לא הניח הרשב\"ם להתענות ביום הקבורה ע\"כ. ב\"י ופוסקים. ומכל מקום שמעינן מהא אפילו למאי דפסקינן שמותר להתענות אם רצה האבל שלא להתענות בימים שלפני ראש השנה או בתעניות הדומים לזה הרשות בידו ואם מת בחצי היום וכבר קבל עליו התענית ממתין לעת ערב עד אחר התפלה ולא משלים לגמרי)\u0006:","\u0003שהמת. \u0004 כדי להעביר הסרחון:","\u0003שיתחלקו. \u0004 דהוי כסעודת מריעות ושיש בה שמחה. ש\"ך:","\u0003בשבת. \u0004 כתב הש\"ך צ\"ע דלקמן ס\"ס שצ\"ט פסק הב\"י דמברין בשבת וכתב שכן פשוט המנהג בכל העולם להברות בשבת ולא נשמע מעולם שום פוצה פה ומצפצף עכ\"ל \u0005(ואפשר שזהו לפי יש נוהגין שמברין כל ז' כפי מנהג הספרדיים בהרבה מקומות לפי שאין האבל מכין עצמו דבר מכח טרדת אבלותו. וגם כדי שלא לבייש מי שאין לו לזון עצמו ז' ימים ימי בטולו ממלאכתו. וכ\"כ רבינו ירוחם. וע\"כ גם בשבת מברין שהאבלים סומכין על זה ובלא זה אין לו מה יאכל בשבת. אך לפי הנוהגין שאין מברין אלא סעודה הראשונה באיזה לחם וביצים מעולם לא שמענו שעושין זה בשבת כנ\"ל)\u0006: \u0003.. \u0004"]],["כְּשֶׁמְּבָרְכִין בִּרְכַּת הַמָּזוֹן בְּבֵית הָאָבֵל, אוֹמֵר בְּרָכָה רְבִיעִית כְּנֻסַח זוֹ: בא\"י אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל אָבִינוּ מַלְכֵּנוּ בּוֹרְאֵנוּ גוֹאֲלֵנוּ קְדוֹשֵׁנוּ קְדוֹשׁ \u0010c0\u0011 יַעֲקֹב הַמֶּלֶךְ הַחַי הַטּוֹב וְהַמֵּטִיב אֵל אֱמֶת דַּיַּן אֱמֶת שׁוֹפֵט בְּצֶדֶק וְכו'. \u0005הַגָּה: לוֹקֵחַ נְפָשׁוֹת בְּמִשְׁפָּט שַׁלִּיט בְּעוֹלָמוֹ לַעֲשׂוֹת בּוֹ כִּרְצוֹנוֹ כִּי כָּל דְּרָכָיו בְּמִשְׁפָּט וַאֲנַחְנוּ עַמּוֹ וַעֲבָדָיו וּבַכֹּל אֲנַחְנוּ חַיָּבִים לְהוֹדוֹת לוֹ וּלְבָרְכוֹ גּוֹדֵר פִּרְצוֹת יִשְׂרָאֵל הוּא יִגְדֹּר הַפִּרְצָה הַזֹּאת מֵעָלֵינוּ וּמֵעַל אָבֵל זֶה לְחַיִּים \u0010c1\u0011 וּלְשָׁלוֹם (טוּר)\u0006.\nיֵשׁ מוֹסִיפִים בִּבְרָכָה שְׁלִישִׁית: נַחֵם ה' אֱלֹהֵינוּ אֶת אֲבֵלֵי יְרוּשָׁלַיִם וְאֶת הָאֲבֵלִים הַמִתְאַבְּלִים בָּאֵבֶל הַזֶּה, נַחֲמֵם מֵאֶבְלָם וְשַׂמְּחֵם מִיגוֹנָם, כָּאָמוּר: כְּאִישׁ אֲשֶׁר אִמּוֹ תְּנַחֲמֶנּוּ \u0005(יְשַׁעְיָה סו, יג)\u0006 וְכו' בא\"י מְנַחֵם צִיּוֹן בְּבִנְיַן יְרוּשָׁלַיִם.\nיֵשׁ אוֹמְרִים בְּבִרְכַּת זִמּוּן: נְבָרֵךְ מְנַחֵם אֲבֵלִים שֶׁאָכַלְנוּ מִשֶּׁלוֹ.\nבְּשַׁבָּת, אִם בֵּרַךְ בְּיָחִיד, אוֹ בְּג' אֲבֵלִים, מְבָרֵךְ כְּדֶרֶךְ שֶׁמְּבָרֵךְ בְּחוֹל, דְּצִנְעָא הוּא. וְאִם אָכְלוּ אֲחֵרִים עִמּוֹ וּבֵרְכוּ, אֵין מַזְכִּירִין מֵעֵין הַמְּאֹרָע, דְּכֵיוָן דְּאִכָּא אֲחֵרִים לָאו צִנְעָה הוּא.\nאָבֵל \u0010c2\u0011 מִצְטָרֵף לִתְפִלָה וּלְזִמּוּן, בֵּין לְג' בֵּין לַעֲשָׂרָה.",[],["\u0003יעקב. \u0004 רוענו רעה ישראל המלך הטוב והמטיב לכל אל שבכל יום ויום הוא הטיב הוא מטיב הוא ייטיב לנו המלך החי הטוב והמטיב וכו' דודאי צריך לומר הברכה מתחלה כתיקון חכמים עד כאן לשון הש\"ך:","\u0003ולשלום. \u0004 הרחמן הוא וכו':","\u0003מצטרף. \u0004 ומדברי המרדכי נראה דסעודה ראשונה שמברין את האבל שאסור לאכלה משלו אין האבל מצטרף בברכת המזון. וכ\"כ הרוקח דכן משמע בפ\"א דכתובות דף ח' ע\"ב ע\"ש עכ\"ל הש\"ך:"]],["אֵלוּ דְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶם: בִּמְלָאכָה, בִּרְחִיצָה וְסִיכָה וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה, וְאָסוּר לִקְרוֹת בַּתּוֹרָה, וְאָסוּר בִּשְׁאֵלַת שָׁלוֹם וּבִכְבִיסָה, וְחַיָּב בַּעֲטִיפַת הָרֹאשׁ וּבִכְפִיַּת הַמִּטָּה, כָּל שִׁבְעָה, וְאָסוּר לְהַנִּיחַ תְּפִלִין בַּיּוֹם הָרִאשׁוֹן, וְאָסוּר בְּגִהוּץ וּבְתִסְפֹּרֶת וְשִׂמְחָה וְאִחוּי קֶרַע כָּל ל' יוֹם \u0005וְכָל דִּבְרֵי אֲבֵלוּת נוֹהֲגִין בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה (בִּתְשׁוּבַת הָרַשְׁבָּ\"א סִימָן תמ\"ו)\u0006.\nמְלָאכָה כֵּיצַד, כָּל ג' יָמִים הָרִאשׁוֹנִים אָסוּר בִּמְלָאכָה, אֲפִלוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה; מִכָּאן וָאֵילָךְ, אִם הוּא עָנִי וְאֵין לוֹ מַה יֹאכַל, עוֹשֶׂה בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, וְאִשָּׁה טוֹוָה \u0010c0\u0011 בַּפֶּלֶךְ בְּתוֹךְ בֵּיתָהּ, אֲבָל אָמְרוּ חֲכָמִים: תָּבֹא מְאֵרָה לִשְׁכֵנָיו שֶׁהִצְרִיכוּהוּ לְכָךְ. \u0005כְּדֶרֶךְ \u0010c1\u0011 שֶׁמֻּתָּר לִכְתֹּב בְּחֹל הַמּוֹעֵד, כָּךְ מֻתָּר לִכְתֹּב בִּימֵי אֶבְלוֹ; אֲבָל לֹא בְּעִנְיָן אַחֵר (כָּל בּוֹ בְּשֵׁם הר\"מ וב\"י סוֹף סִימָן זֶה)\u0006.\nג כְּשֵׁם שֶׁהוּא אָסוּר בַּעֲשִׂיַּת מְלָאכָה, כָּךְ הוּא אָסוּר לִשָּׂא וְלִתֵּן בִּסְחוֹרָה, וְלֵילֵךְ מִמְּדִינָה לִמְדִינָה בִּסְחוֹרָה.\nאֲפִלוּ דָּבָר הָאָבֵד אָסוּר הָאָבֵל לַעֲשׂוֹת בֵּין עֲבָדָיו וְשִׁפְחוֹתָיו \u0010c2\u0011 וּבָנָיו וּבְנוֹתָיו שֶׁמַּעֲשֵׂה יְדֵיהֶם שֶׁלוֹ.\nאָסוּר לַעֲשׂוֹת מְלַאכְתּוֹ עַל יְדֵי אֲחֵרִים \u0005אֲפִלּוּ עוֹבֵד כּוֹכָבִים (מָרְדְּכַי רֵישׁ פֶּרֶק מִי שֶׁהָפַךְ)\u0006, אֶלָא אִם כֵּן הוּא דָּבָר הָאָבֵד, שֶׁדָּבָר הָאָבֵד מֻתָּר לְאָבֵל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים; אֲפִלוּ דָּבָר הָאָסוּר בַּמּוֹעֵד מִשּׁוּם טִרְחָא, מֻתָּר, וַאֲפִלוּ הוּא מַעֲשֵׂה אֻמָּן. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא יוּכַל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים, וְהוּא דָּבָר הָאָבֵד, מֻתָּר לַעֲשׂוֹת הָאָבֵל \u0010c3\u0011 בְּעַצְמוֹ (טוּר בְּשֵׁם הָרַמְבַּ\"ן וְהָרֹא\"שׁ וְכֵן כָּתַב רַבֵּנוּ יְרוּחָם)\u0006 ; וּלְאַחַר שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים יֵשׁ לְהָקֵל, וַאֲפִלּוּ תּוֹךְ ג' וְהוּא הֶפְסֵד מְרֻבֶּה.\nפְּרַקְמַטְיָא שֶׁלוֹ, בְּדָבָר הָאָבֵד, שֶׁאִם לֹא יִמְכֹּר יַפְסִיד מֵהַקֶרֶן, נִמְכֶּרֶת עַל יְדֵי אֲחֵרִים; אֲבָל אִם לֹא יַפְסִיד מֵהַקֶרֶן, אֶלָא שֶׁאִם יִמְכְּרֶנָּה עַתָּה יַרְוִיחַ בָּהּ יוֹתֵר מִשֶּׁאִם יִמְכְּרֶנָּה אַחַר כָּךְ, אָסוּר. וּמִכָּל מָקוֹם אִם שַׁיָּרוֹת אוֹ סְפִינוֹת בָּאוּ, אוֹ שֶׁהֵם מְבַקְשִׁים לָצֵאת, וּמוֹכְרִים בְּזוֹל אוֹ לוֹקְחִים בְּיֹקֶר, מֻתָּר לִמְכֹּר וְלִקְנוֹת עַל יְדֵי אֲחֵרִים, אֲפִלוּ שֶׁלֹּא לְצֹרֶךְ תַּשְׁמִישׁוֹ, אֶלָא לַעֲשׂוֹת סְחוֹרָה לְהִשְׂתַּכֵּר.\nלְהַלְווֹת לְעוֹבְדֵי כּוֹכָבִים בְּרִבִּית, לְאוֹתָם שֶׁרְגִילִים לִלְווֹת מִמֶּנּוּ, מֻתָּר לְהַלְווֹת לָהֶם עַל יְדֵי אֲחֵרִים, מִשּׁוּם דְּהָוֵי דָּבָר \u0010c4\u0011 הָאָבֵד.\nאִי מַסִיק זוּזֵי בְּאִינְשֵׁי, וְהָאִדָּנָא מַשְׁכַּח לְהוּ, וּבָתַר הָכִי לָא מַשְׁכַּח לְהוּ, שָׁרֵי \u0010c5\u0011 לְשַׁדּוֹרֵי עֲלַיְהוּ.\nאִם יֵשׁ לוֹ דִּין עַל אָדָם, אֵינוֹ תּוֹבֵעַ כָּל ז'. וְאִם הוּא דָּבָר הָאָבֵד, כְּגוֹן שֶׁבִּקֵשׁ לֵילֵךְ לִמְדִינַת הַיָּם, אוֹ שֶׁעֵדָיו \u0010c6\u0011 חוֹלִים, עוֹשֶׂה מֻרְשֶׁה וְדָן עִמּוֹ.\nכָּל הַדְּבָרִים שֶׁהִתִּירוּ בַּמּוֹעֵד מִשּׁוּם \u0010c7\u0011 צֹרֶךְ הַמּוֹעֵד, כֻּלָם אֲסוּרִים בְּאָבֵל, אֲפִלוּ עַל יְדֵי אֲחֵרִים.\nאָבֵל שֶׁשָּׂדֵהוּ בְּיַד אֲחֵרִים בַּאֲרִיסוּת אוֹ בַּחֲכִירוּת אוֹ בְּקַבְּלָנוּת, הֲרֵי אֵלוּ עוֹבְדִין כְּדַרְכָּן בִּימֵי הָאֵבֶל שֶׁל בַּעַל הַשָּׂדֶה, וַאֲפִלוּ נִשְׁלַם זְמַן חֲכִירוּתָם קֹדֶם וְנִשְׁאֲרוּ בַּשָּׂדֶה כְּמוֹ שֶׁהָיוּ.\nאִם הָאָבֵל הוּא אָרִיס בְּשָׂדֶה שֶׁל אֲחֵרִים, לֹא יַעֲבֹד הוּא בְּעַצְמוֹ, אֲבָל עַל יְדֵי אֲחֵרִים \u0010c8\u0011 מֻתָּר.\nאִם יֵשׁ שְׂכִיר יוֹם שֶׁעוֹבֵד שְׂדֵה הָאָבֵל, אֲפִלוּ בְּעִיר אַחֶרֶת, לֹא \u0010c9\u0011 יַעֲשֶׂה.\nאִם יֵשׁ לָאָבֵל חֲמוֹר אוֹ סְפִינָה מֻחְכָּר אוֹ מֻשְׂכָּר בְּיַד אַחֵר, הֲרֵי זֶה לֹא יַעֲשֶׂה בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַחֲמוֹר וְהַסְפִינָה, אִם לֹא שֶׁשְּׂכָרוֹ קֹדֶם שֶׁהִתְחִיל הָאֲבֵלוּת וַעֲדַיִן לֹא כָּלָה הַזְּמַן; אֲבָל אִם כָּלָה הַזְּמַן, אָסוּר.\nאִם הָיָה הַחֲמוֹר וְהַסְפִינָה בְּיַד אֲחֵרִים, לְמֶחֱצָה, לִשְׁלִישׁ וְלִרְבִיעַ, יֵשׁ מַתִּירִים וְיֵשׁ אוֹסְרִים.\nאִם הָאָבֵל מֻשְׂכָּר לְאַחֵר, לֹא יַעֲשֶׂה מְלָאכָה בִּימֵי אֶבְלוֹ. \u0005אֲבָל עַל יְדֵי אֲחֵרִים, \u0010c10\u0011 שָׁרֵי (זֶהוּ מֵהָרֹא\"שׁ)\u0006.\nהָיְתָה מְלֶאכֶת אֲחֵרִים בְּיָדוֹ, אֲפִלוּ בְּדָבָר \u0010c11\u0011 תָּלוּשׁ, כְּגוֹן לֶאֱרֹג, בֵּין בְּקַבְּלָנוּת בֵּין שֶׁלֹּא בְּקַבְּלָנוּת, לֹא יַעֲשֶׂה. \u0005הַגָּה: וְאִם הוּא דָּבָר הָאָבֵד, יַעֲשֶׂה עַל יְדֵי \u0010c12\u0011 אֲחֵרִים (ד\"ע)\u0006. מֻתָּר לְקַבֵּל מְלָאכָה בִּימֵי אֶבְלוֹ לַעֲשׂוֹת אַחַר כָּךְ, וּבִלְבַד שֶׁלֹּא יִשְׁקֹל וְלֹא יִמְדֹּד כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בִּשְׁאָר פְּעָמִים \u0005(מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006.\nהָיְתָה \u0010c13\u0011 מְלַאכְתּוֹ בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת בְּדָבָר תָּלוּשׁ, בְּבֵיתוֹ, לֹא יַעֲשׂוּ; בְּבֵית אֲחֵרִים, יַעֲשׂוּ. \u0005וּבִלְבַד שֶׁקִּבְּלוּ הַמְּלָאכָה קֹדֶם שֶׁנַּעֲשָׂה אָבֵל (מָרְדְּכַי סוֹף מ\"ק וְר\"י)\u0006.\nהָיָה לוֹ בִּנְיָן בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת, בְּחֹל אוֹ בְּחֹל הַמּוֹעֵד לֹא יַעֲשׂוּ, אֲפִלוּ הוּא חוּץ \u0010c14\u0011 לִתְחוּם הָעִיר; וְאִם אֵלוּ הַקַבְּלָנִים עוֹבְדֵי כּוֹכָבִים, מֻתָּרִים לִבְנוֹתוֹ בְּשַׁבָּת וְיוֹם טוֹב שֶׁחָלוּ בִּימֵי הָאֵבֶל, אִם הוּא חוּץ לִתְחוּם הָעִיר וְאֵין עִיר אַחֶרֶת שֶׁבָּהּ יִשְׂרָאֵל בְּתוֹךְ תְּחוּם שֶׁל אוֹתוֹ בַּיִת.\nאִם קִבְּלוּ אֲחֵרִים לַחֲרֹשׁ וְלִזְרֹעַ שָׂדֵהוּ, יֵשׁ אוֹמְרִים שֶׁמֻּתָּרִין לַחֲרֹשׁ וְלִזְרֹעַ בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַשָּׂדֶה, וְיֵשׁ מִי שֶׁאוֹסֵר.\nשְׁנֵי שֻׁתָּפִים חֶנְוָנִים שֶׁאֵרַע אֵבֶל לְאֶחָד מֵהֶם, נוֹעֲלִים חֲנוּתָם, שֶׁלֹּא יַעֲשֶׂה הַשֻּׁתָּף בְּפַרְהֶסְיָא, אֲבָל יָכוֹל לַעֲשׂוֹת בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, אֲפִלוּ בְּעֵסֶק הַשֻּׁתָּפוּת. וְאִם הָאָבֵל אָדָם חָשׁוּב, וְהַשֻּׁתָּפוּת נִקְרָא עַל שְׁמוֹ, שֶׁאֲפִלוּ אִם יַעֲשֵׂהוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ יָדוּעַ שֶּׁיֵּשׁ לָאָבֵל חֵלֶק בּוֹ, אָסוּר לַשֵּׁנִי לַעֲשׂוֹת אֲפִלוּ בְּתוֹךְ בֵּיתוֹ.\nכְּבוֹד הַבַּיִת, הֲדָחַת כּוֹסוֹת וְהַצָּעַת הַמִּטּוֹת, אֵין בָּהֶם מִשּׁוּם מְלָאכָה לְאָבֵל; וְכֵן מֻתָּר לְאִשָּׁה לֶאֱפוֹת וּלְבַשֵּׁל בִּימֵי אֶבְלָהּ \u0005כָּל הַצָּרִיךְ לָהּ, אֲבָל מַה שֶּׁאֵינוֹ צָרִיךְ לָהּ אָסוּר;\u0006 וְכֵן אִשָּׁה הַמְשָׁרֶתֶת בְּבֵית בַּעַל הַבַּיִת אֶחָד, וְאֵרְעָהּ אֵבֶל, מֻתֶּרֶת לֶאֱפוֹת וּלְבַשֵּׁל וְלַעֲשׂוֹת שְׁאָר צָרְכֵי הַבַּיִת, בֵּין שֶׁהִיא מְשָׁרֶתֶת בְּחִנָּם בֵּין \u0010c15\u0011 בְּשָׂכָר.\nהַהוֹלֵךְ מִמָּקוֹם לְמָקוֹם לִסְחוֹרָה, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, אִם יָכוֹל לְמַעֵט שֶׁלֹּא לַעֲשׂוֹת שׁוּם עֵסֶק בְּאוֹתָהּ הָעִיר, מוּטָב; וְאִם לָאו, שֶׁאִם לֹא יִקְנֶה בְּאוֹתָהּ הָעִיר לֹא יִמָּצֵא, יִקְנֶה לְצֹרֶךְ הַדֶּרֶךְ דְּבָרִים שֶׁיֵּשׁ בָּהֶם חַיֵּי נֶפֶשׁ.\nעַל כָּל הַמֵּתִים, רָצָה לְמַעֵט בְּעֵסֶק סְחוֹרָה הַמֻּתֶּרֶת לוֹ, כְּגוֹן דָּבָר הָאָבֵד, יְמַעֵט; רָצָה, אֵינוֹ מְמַעֵט. עַל אָבִיו וְאִמּוֹ, יְמַעֵט.\nעַל כָּל הַמֵּתִים אָסוּר עַד ל' יוֹם לֵילֵךְ בִּסְחוֹרָה לְמֵרָחוֹק, דְּאִכָּא פִּרְסוּם גָדוֹל וְדוֹמֶה לְשִׂמְחָה שֶׁהוֹלֵךְ בְּשַׁיָּרָא גְדוֹלָה וּשְׂמֵחִים הַרְבֵּה בַּדֶּרֶךְ; בְּאָבִיו וְאִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו וְיֹאמְרוּ: לֵךְ עִמָּנוּ.",[],["\u0003בפלך. \u0004 פי' דאין מתירין לה אלא מלאכה של צינעא ושל עראי כגון להיות טווה בפלך בתוך ביתה. ואם אינה מספקת בזה עושה אומנות שלה בצינעה תוך ביתה. עכ\"ל הטור:","\u0003המועד. \u0004 כמו שנתבאר בא\"ח כו' תקמ\"ה ע\"ש:","\u0003ובניו. \u0004 פי' אפי' הם גדולים אם סמוכים על שלחנו כ\"כ הטור ולבוש ור\"ל כ\"ש קטנים בסמוכים על שלחנו. אבל אם אינם סמוכים על שלחנו אפילו קטנים מעשה ידיהם לעצמן כמ\"ש בח\"מ סי' ע\"ד ס\"ב עכ\"ל הש\"ך:","\u0003בעצמו. \u0004 אפי' הוא דבר שיש בו טרחא ומעשה אומן כ\"מ בש\"ס. ש\"ך. מיהו יעשה בצינעה. שם:","\u0003האבד. \u0004 שאם לא ילוה להם ילכו לאחרים וילוו להם וירגילום לבא אצלם ואיכא פסידא. טור:","\u0003לשדורי. \u0004 כלומר לשלוח אחרים שיתבעו המעות מהם דה\"ל דבר האבוד. ש\"ך:","\u0003חולים. \u0004 ומתיירא שמא ימותו:","\u0003צורך. \u0004 ולא משום דבר האבד וכה\"ג. ש\"ך:","\u0003מותר. \u0004 כתב הש\"ך משום שאין זה נקרא מלאכת האבל אלא של בעל השדה:","\u0003יעשה. \u0004 כיון שאינו אצלו באריסות או בחכירות ובקבלנות. ש\"ך:","\u0003שרי. \u0004 כתב הש\"ך משמע אפי' אינו דבר האבד וכן משמע להדיא בלבוש דאע\"ג דלעיל ס\"ב וס\"ה אסור אפילו ע\"י אחרים מ\"מ הכא מותר ע\"י אחרים והוא יקח השכר מן הבעלים שהרי אין עיקר המלאכה שלו ע\"כ אבל לא נראה כן מדברי הרא\"ש מדמדמי ליה לעני המתפרנס מן הצדקה משמע דאפי' ע\"י אחרים אסור וכו' ע\"ש:","\u0003תלוש. \u0004 שיכול לעשותו בצינעה וכ\"ש דבר מחובר שאינו יכול לעשות אלא בפרהסיא. ש\"ך:","\u0003אחרים. \u0004 והלבוש כתב ונראה דאפי' אינו דבר האבד מותר לעשותו ע\"י אחרים כיון שעיקר המלאכה אינו שלו וכמ\"ש בסי\"ז גבי הוא עצמו מושכר והש\"ך כתב דדעת הרב נראה דדוקא התם שהוא מושכר לחדש או לחדשים שרי משא\"כ הכא. ולפי מ\"ש לעיל דבהוא עצמו מושכר אסור על ידי אחרים אם לא בדבר האבד כ\"ש הכא עכ\"ל:","\u0003מלאכתו. \u0004 כתב ר' ירוחם בשם המפרשים שמכאן יש ללמוד שאם היה לאבל מלמד או סופר או פועל שלא יעשה בביתו. עכ\"ל \u0005(וכ' בה\"י עליו לפי דברי האחרונים שכתבו סי' שפ\"ד שמלמד תינוקות מותר ללמוד עם התינוקות אחר ג' ימים אם אירע אבילות למלמד א\"כ כ\"ש הוא שמותר ללמוד עם התינוקות בתוך ביתו של אחר שאירע לו אבילות)\u0006:","\u0003לתחום. \u0004 אפי' מסרה להם קודם האבל או קודם ח\"ה אסור מפני מראית עין שכיון שיוכלו בני אדם ללכת שם ויראו המלאכה יאמרו ראו זה שמסר מלאכתו לאחרים בימי האבל או בחול המועד ולא ידעי דקבולת הוא גבייהו קודם לכן עכ\"ל הש\"ך:","\u0003בשכר. \u0004 כתב הט\"ז וא\"ל הא כתב בסט\"ז אם האבל מושכר לאחרים לא יעשה מלאכה בימי אבלו דהתם מיירי במלאכה גמורה שאסור לאבל בכל גוני משא\"כ במלאכת צרכי הבית דמותר לאשה עצמה כמ\"ש בסעיף הקודם ע\"כ מותר אפי' למשרתת. אבל עכ\"פ לא תעשה המשרתת מלאכה שאינה לצורך הבית אלא להרויח וכ\"ש שלא תצא מן הבית כדין אבל. וראיתי מי שהורה לשמש שאירע לו אבל שיעשה עבודתו לילך לבהכ\"נ ולשמש בצרכי הקהל ולא יפה הורה דטעה בטעם הדין הזה דהיתר משרתת. וכתב רש\"ל בשם אגודה דאבל מותר להקיז דם וכ' הכל בו דאבל שעושה מלאכה מנדין אותו עכ\"ל:"]],["רְחִיצָה כֵּיצַד, אָסוּר לִרְחֹץ כָּל גוּפוֹ, אֲפִלוּ בְּצוֹנֵן; אֲבָל פָּנָיו יָדָיו וְרַגְלָיו, בְּחַמִּין, אָסוּר; בְּצוֹנֵן, מֻתָּר. וְאִם הָיָה מְלֻכְלָךְ בְּטִּיט וְצוֹאָה, רוֹחֵץ כְּדַרְכּוֹ וְאֵינוֹ חוֹשֵׁשׁ. \u0005הַגָּה: וְכָל זֶה מִדִּינָא אֵינוֹ אָסוּר רַק שִׁבְעָה, אֲבָל אַחַר כָּךְ מֻתָּר בִּרְחִיצָה, אֶלָּא שֶׁנָּהֲגוּ \u0010c0\u0011 הָאִדָּנָא לֶאֱסֹר כָּל רְחִיצָה כָּל ל' יוֹם (מהר\"מ הִלְכוֹת שְׂמָחוֹת ובהגמי\"י פ\"ז מהל' י\"ט ופ\"י דהל' אֵבֶל)\u0006 ; וַאֲפִלּוּ לָחֹף הָרֹאשׁ אָסוּר \u0005(לְקַמָּן סי' ש\"צ ובא\"ז)\u0006 ; וְאֵין לְשַׁנּוֹת הַמִּנְהָג, כִּי מִנְהָג קָדוּם הוּא וְנִתְיַסֵּד עַל פִּי וָתִיקִין \u0005(א\"ז בְּשֵׁם רַשְׁבָּ\"א)\u0006.\nסִיכָה כֵּיצַד, אָסוּר לָסוּךְ אֲפִלוּ כָּל שֶׁהוּא, אִם מְכַוֵּן לְתַעֲנוּג, אֲבָל אִם הוּא לְהַעֲבִיר הַזֻּהֲמָא מֻתָּר; וְאֵין צָרִיךְ לוֹמַר מִשּׁוּם רְפוּאָה, כְּגוֹן שֶׁיֵּשׁ לוֹ חֲטָטִין בְּרֹאשׁוֹ.\nיוֹלֶדֶת אֲבֵלָה שֶׁצְּרִיכָה \u0010c1\u0011 לִרְחֹץ, מֻתָּר. וְכֵן מָאן דְּאִית לֵיהּ עִרְבּוּבְיָא בְּרֵישֵׁיהּ, מֻתָּר לָחֹף רֹאשׁוֹ בְּחַמִּין, דְּלֹא גָרַע מֵאִסְטְנִיס \u0005(פי' קַר הַגּוּף וּמְצֻנָּן)\u0006, שֶׁמֻּתָּר לִרְחֹץ כָּל גוּפוֹ. וְלֹא כָּל מִי שֶׁאָמַר: אִסְטְנִיס אֲנִי, מַתִּירִין לוֹ, אֶלָא דַּוְקָא שֶׁהוּא יָדוּעַ שֶׁהוּא אִסְטְנִיס וּמִתְנַהֵג בִּנְקִיּוּת, וְאִם לֹא יִרְחַץ יִצְטַעֵר הַרְבֵּה וְיָבֹא לִידֵי מֵחוּשׁ.\nמִי שֶׁתְּכָפוּהוּ אֲבֵלָיו, שֶׁאֵרְעוּ שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מֻתָּר לִרְחֹץ כָּל גוּפוֹ בְּצוֹנֵן.\nנִדָּה שֶׁנִּזְדַּמְּנָה זְמַן טְבִילָתָהּ בִּימֵי אֶבְלָהּ, אֵינָהּ טוֹבֶלֶת \u0005(טוּר בְּשֵׁם ר\"ת וְע\"פ ומהרי\"ק שֹׁרֶשׁ ל\"ה)\u0006. \u0005הַגָּה: וְכָל שֶׁכֵּן שֶׁאֵינָהּ רוֹחֶצֶת לִלְבֹּשׁ לְבָנִים. אֲבָל מִיָּד אַחַר ז', אַף עַל פִּי שֶׁנָּהֲגוּ אִסּוּר בִּרְחִיצָה כָּל ל', מִכָּל מָקוֹם הִיא מֻתֶּרֶת רַק שֶׁתְּשַׁנֶּה הַרְחִיצָה קְצָת\u0006 \u0005(א\"ז בְּסוֹף הִלְכוֹת אֵבֶל)\u0006, \u0005וְחָלוּק לָבָן תִּלְבֹּש וְסָדִין לָבָן תַּצִּיעַ, שֶׁלֹּא תָּבֹא לִידֵי סָפֵק\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ט\"ו)\u0006.\nאִשָּׁה לֹא תִּכְחֹל וְלֹא תְּפַרְקֵס בִּימֵי אֶבְלָהּ, שֶׁכָּל אֵלוּ אֲסוּרִים בִּרְחִיצָה. וְאֵשֶׁת אִישׁ אֵינָהּ אֲסוּרָה אֶלָא תּוֹךְ שִׁבְעָה, אֲבָל אַחַר ז' מֻתֶּרֶת בַּכֹּל, כְּדֵי שֶׁלֹּא תִּתְגַנֶּה עַל בַּעֲלָהּ. כַּלָה שֶׁאֵרְעָהּ אֵבֶל תּוֹךְ שְׁלֹשִׁים יוֹם לְחֻפָּתָהּ, מֻתֶּרֶת לְהִתְקַשֵּׁט אֲפִלוּ תּוֹךְ ז'. בּוֹגֶרֶת שֶׁאֵרְעָהּ אֵבֶל, כֵּיוָן שֶׁעוֹמֶדֶת לִנָּשֵׂא, מֻתֶּרֶת בְּכִחוּל וּפִרְקוּס אֲבָל אֲסוּרָה בִּרְחִיצַת חַמִּין כָּל גוּפָהּ; נַעֲרָה אֲבֵלָה, אֲסוּרָה אֲפִלוּ בְּכִחוּל וּפִרְקוּס.",[],["\u0003לאסור רחיצה כל ל' וכו'. \u0004 כצ\"ל וכן הוא בלבוש. ולא כמו שנדפס בספרים כל רחיצה כל ל' דודאי רחיצה בצונן ליכא איסורא כלל עכ\"ל הש\"ך \u0005(בא\"ז נתן טעם למנהג דחיישינן דילמא אתי למסרק רישיה דאסור כל ל' וא\"כ לדידן דשרי למסרק רישיה כדאיתא סי' ש\"צ ע\"ש היה מותר לרחוץ. ורש\"ל נתן טעם דאסרו משום תספורת כי כן דרך הנכנס למרחץ לגלח שערות ראשו. ט\"ז. וע\"ש עוד)\u0006:","\u0003מותר. \u0004 אפילו ביום ראשון מיהו אם אין לה צורך כ\"כ יש להחמיר ביום ראשון. ש\"ך:"]],["\u0005(אָבֵל)\u0006 אָסוּר בִּנְעִילַת הַסַנְדָּל, דַּוְקָא שֶׁל עוֹר; אֲבָל בְּאַנְפִּלְיָא שֶׁל בֶּגֶד אוֹ שֶׁל גֻמִּי אוֹ שֶׁל שֵׂעָר אוֹ שֶׁל עֵץ, מֻתָּר, שֶׁאֵין מִנְעָל אֶלָא שֶׁל עוֹר. וְאִם הוּא שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אָסוּר. \u0010c0\u0011\nחַיָּה מֻתֶּרֶת לִנְעֹל כָּל ל' יוֹם, מִפְּנֵי שֶׁהַצִּנָּה קָשָׁה לָהּ.\nכָּל אָדָם מֻתָּר לִנְעֹל בְּמָקוֹם שֶׁיֵּשׁ סַכָּנַת עַקְרָב.\nאָבֵל וּמְנֻדֶּה שֶׁהָיוּ מְהַלְכִים בַּדֶּרֶךְ, מֻתָּרִים בִּנְעִילַת הַסַנְדָּל, וּכְשֶׁיַּגִיעוּ לָעִיר, חוֹלְצִין. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הִיא עִיר שֶׁרֻבָּהּ עוֹבְדֵי כּוֹכָבִים, אֵין חוֹלְצִין עַד שֶׁיִּכָּנְסוּ לִרְחוֹב \u0010c1\u0011 הַיְּהוּדִים.\nאִם צָרִיךְ לַחֲלֹץ מִנְעָל בְּבֵית הַקְבָרוֹת אַחַר שֶׁנִּקְבַּר הַמֵּת, נִתְבָּאֵר בְּסִימָן שע\"ה. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁצָּרִיךְ לֵילֵךְ יָחֵף מִבֵּית הַקְּבָרוֹת לְבֵיתוֹ אִם מֵת אָבִיו אוֹ אִמּוֹ (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, וְלֹא \u0010c2\u0011 רָאִיתִי נוֹהֲגִין כֵּן.",[],["\u0003חיה. \u0004 וה\"ה חולה ומי שיש לו מכה ברגלו כמ\"ש בא\"ח סימן תרי\"ד ס\"ג. ש\"ך:","\u0003היהודים. \u0004 וכתב הרב בא\"ח סי' תקנ\"ד סי\"ז שכן נהגו:","\u0003ראיתי. \u0004 היינו משום רשעת העובדי כוכבים מיהו היכא דליכא חשש דרשעת העובדי כוכבים יש לחלוץ מיד בבה\"ק כדלעיל ר\"ס שע\"ה וסי' שע\"ו עכ\"ל הש\"ך. וכתב הט\"ז דלפי מ\"ש המרדכי דאם הולך לפני השר ויש הקפדה עליו אם ילך בלא מנעלים יתן עפר במנעליו וילך ע\"כ ה\"ה במקום סכנה ובכ\"מ שצריך לילך במנעלים יעשה כן. וכתב עוד בסי' שפ\"א בשם אחיו הגאון מוהר\"י דיש להתיר לאשה רחיצת הליבון אפי' תוך ז' ומ\"ש רמ\"א דתוך ז' אסור לרחוץ ללבישת ליבון הוא תימה דהא לאו רחיצה של תענוג היא והא דאסור רחיצה של טבילה מפני שהיא ללא צורך כיון שאסורה בתשמיש המטה אבל רחיצה של ליבון אמאי תיאסר ועכ\"פ נראה דגם רמ\"א לא נתכוין אלא שלא תרחוץ שהרי אפשר לה ללבוש לבנים בלא רחיצה לגמרי רק שהחלוק יהיה נקי כמ\"ש בסי' קצ\"ו ס\"ג בהג\"ה דבשעת הדחק סגי בהכי ובתשובת מ\"ב מתיר אפי' לרחוץ בתוך ז' ללבוש לבנים וחולק על הרמ\"א אלא דמ\"מ למעשה נ\"ל דלא תרחוץ אלא פנים של מטה ותלבוש חלוק נקי לא לבן ממש והמחמיר בזה לדחות לבישת הליבון לגמרי הוא מן המתמיהים עכ\"ל. וכתב מהרש\"ל מהר\"ם היה בעל ברית תוך שלשים יום של אביו ורחץ בלילה שלפני המילה ונתן טעם דהוה כרגל לגביה דידיה וחומרא בעלמא נהגו אבותינו ברחיצה ע\"כ:"]],["אָבֵל אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, אֲבָל בִּשְׁאָר דְּבַר קֻרְבָה מֻתָּר, אֲפִלוּ בִּמְזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו, בֵּין בַּאֲבֵלוּת דִּידֵהּ בֵּין בַּאֲבֵלוּת דִּידָהּ. \u0005אֲבָל חִבּוּק וְנִשּׁוּק יֵשׁ לְהַחְמִיר (רַבֵּנוּ יְרוּחָם)\u0006. וּמֻתֶּרֶת לֶאֱכֹל עִמּוֹ בִּקְעָרָה. וּמֻתֶּרֶת לִישַׁן עִמּוֹ הוּא \u0010c0\u0011 בְּבִגְדּוֹ וְהִיא בְּבִגְדָּהּ; וּמִיהוּ מִשּׁוּם לֵךְ לֵךְ אַמְרִינָן נְזִירָא יֵשׁ לְהַחְמִיר שֶׁלֹּא יִישַׁן \u0005(עִמָּהּ)\u0006 בְּמִטָּה כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר אֲבֵלוּת; אֲבָל אִם מֵת אָבִיו שֶׁל חָתָן אוֹ אִמָּהּ שֶׁל כַּלָה, שֶׁמַּכְנִיסִין אֶת הַמֵּת לַחֶדֶר וְאֶת הֶחָתָן וְאֶת הַכַּלָה לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ וְנוֹהֲגִים ז' יְמֵי הַמִּשְׁתֶּה, וְאַחַר כָּךְ שִׁבְעַת יְמֵי אֲבֵלוּת, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל י\"ד יוֹם, אֶלָא הוּא יָשֵׁן בֵּין הָאֲנָשִׁים וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים, כִּדְאִיתָא בְּסִימָן שמ\"ב. אֲבָל אִם כָּנַס לַחֻפָּה וְהִתְחִילוּ יְמֵי הַמִּשְׁתֶּה שֶׁלוֹ, וְאַחַר כָּךְ מֵת לוֹ מֵת, מֻתָּר לְהִתְיַחֵד עִמָּהּ כְּמוֹ בִּשְׁאָר אֲבֵלוּת, וְהוּא שֶׁבָּעַל; אֲבָל אִם לֹא בָּעַל, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל יְמֵי הָאֵבֶל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת.",[],["\u0003בבגדו. \u0004 אבל בלא בגדים אסור אפי' סינר מפסיק אפי' בשבת ורגל. טור ורמב\"ן:"]],["אָבֵל, כָּל שִׁבְעָה יָמִים אָסוּר לִקְרוֹת בְּתוֹרָה, נְבִיאִים וּכְתוּבִים, מִשְׁנָה, גְמָרָא, הֲלָכוֹת וְאַגָדוֹת. וְאִם רַבִּים צְרִיכִים לוֹ \u0010c0\u0011 לְהִתְלַמֵּד, מֻתָּר, וּבִלְבַד שֶׁלֹּא יַעֲמִיד תֻּרְגְמָן אֶלָא יֹאמַר לְאַחֵר, וְהָאַחֵר לַתֻּרְגְמָן, וְתֻרְגְמָן יַשְׁמִיעַ לָרַבִּים. \u0005הַגָּה: אוֹ יִדְרֹשׁ בְּעַצְמוֹ (מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. וְיָכוֹל לִפְסֹק אִסּוּר וְהֶתֵּר לְיָחִיד הַשּׁוֹאֵל אוֹתוֹ, אִם אֵין אַחֵר אֶלָּא הוּא, וּצְרִיכִין לוֹ \u0005(בא\"ז וְר' יְרוּחָם)\u0006. אָבֵל אָסוּר לוֹמַר הֲלָכָה לְתַלְמִידָיו, וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין \u0005(תא\"ו בְּשֵׁם י\"א)\u0006.\nאִם הָאָבֵל \u0010c1\u0011 כֹּהֵן, וְאֵין בב\"ה כֹּהֵן אַחֵר, אָסוּר לוֹ לַעֲלוֹת לִקְרוֹת בַּתּוֹרָה.\nאִם אֵין שָׁם מִי שֶׁיִּתְפַּלֵל לְהוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן, יָכוֹל הָאָבֵל לְהִתְפַּלֵל לְהוֹצִיאָן. \u0005הַגָּה: וּמִצְוָה לְהִתְפַּלֵּל שַׁחֲרִית וְעַרְבִית בַּמָּקוֹם שֶׁמֵּת שָׁם, אֲפִלּוּ אֵין אָבֵל, כִּי יֵשׁ בָּזֶה נַחַת רוּחַ לַנְּשָׁמָה (א\"ז)\u0006, וְהָאָבֵל מִצְטָרֵף לְמִנְיָן \u0005(שָׁם)\u0006.\nאָבֵל מֻתָּר לִקְרוֹת בְּאִיּוֹב וּבְקִינוֹת וּבִדְבָרִים הָרָעִים שֶׁבְּיִרְמִיָּה וּבְהִלְכוֹת אֲבֵלוּת \u0005וְעַיֵּן בא\"ח סִימָן תקנ\"ד סָעִיף ב'.\u0006 וְהָנֵי מִלֵי בֵּינוֹ לְבֵין עַצְמוֹ, אֲבָל אֵינוֹ לוֹמֵד עִם אֲחֵרִים, אֶלָא הֵם יוֹשְׁבִים וְנוֹשְׂאִים וְנוֹתְנִין בְּהִלְכוֹת אֲבֵלוּת, וְאִם טָעוּ מְשִׁיבָן בְּשָׂפָה רָפָה, וְהוּא אֵינוֹ שׁוֹאֵל. וְהָנֵי מִלֵי כְּשֶׁאֵין רַבִּים צְרִיכִים לוֹ, אֲבָל אִם רַבִּים צְרִיכִים לוֹ, אֲפִלוּ בַּהֲלָכוֹת אֲחֵרוֹת מֻתָּר, כִּדְאָמְרִינַן.\nאָבֵל שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, אֵין לוֹ לְבַטְּלָם מִלִמּוּדָם.",[],["\u0003להתלמד. \u0004 כתב הט\"ז נ\"ל דמלמד יכול ללמוד ההלכה עם תלמידיו אחר ג' ימים דזה הוה בכלל רבים צריכים לו דתינוקות של בית רבן הבל פיהם חביב מלימוד הגדולים גם נראה פשוט שאבל מותר להשתמש בתשמישי התורה כשקורין כגון גלילה וכיוצא בזה דקריאה לחוד אסור לו משום דכתיב משמחי לב וכן ראיתי בהג\"ה וז\"ל הרב ר\"ח היה אבל בזמן שני וחמישי והתפללו סליחות אצלו וקראו בתורה והוא היה הגולל ס\"ת כו' עכ\"ל:","\u0003כהן. \u0004 כ' הב\"ח ותימא דבסי' ת' בדין שבת כתב הרב דבאין שם כהן אחר אלא הוא מותר לקרותו וכאן לא כתב כלום וכ' הש\"ך דלק\"מ דהכא טעמא דאיסורא דאבל אסור בד\"ת אתא לאשמועינן ומדין אבלות בשבת לא מיירי אבל התם דמיירי בכל הסי' מדין איסור אבלות בשבת קאמר דמותר לעלות משום דאל\"כ ה\"ל אבלות דפרהסיא ואין אבלות דפרהסיא נוהג בשבת והכי משמע התם להדיא עיין שם עכ\"ל:"]],["אָבֵל אָסוּר בִּשְׁאֵלַת שָׁלוֹם. כֵּיצַד, שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים אֵינוֹ שׁוֹאֵל בִּשְׁלוֹם כָּל אָדָם, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, לֹא יָשִׁיב לָהֶם שָׁלוֹם אֶלָא יוֹדִיעֵם שֶׁהוּא אָבֵל. מִג' עַד שִׁבְעָה, אֵינוֹ שׁוֹאֵל, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, מֵשִׁיב לָהֶם. מִשִּׁבְעָה עַד ל', שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים שֶׁהֵם שְׁרוּיִים בְּשָׁלוֹם, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ, וְכָל שֶׁכֵּן שֶׁמֵּשִׁיב לְמִי שֶׁשּׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר קְרוֹבִים, אֲבָל עַל אָבִיו וְאִמּוֹ שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים אַחַר שִׁבְעָה, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ עַד אַחַר י\"ב חֹדֶשׁ. \u0005הַגָּה: וּמֵאַחַר שֶׁאָסוּר בִּשְׁאֵלַת שָׁלוֹם, כָּל שֶׁכֵּן שֶׁאָסוּר לְהַרְבּוֹת בִּדְבָרִים (רַמְבַּ\"ם פ\"ה וְכָל בּוֹ)\u0006. וְאִם עוֹשֶׂה לִכְבוֹד רַבִּים, כְּגוֹן שֶׁרַבִּים בָּאִים לְנַחֲמוֹ, מֻתָּר לוֹמַר לָהֶם: לְכוּ לְבָתֵּיכֶם לְשָׁלוֹם, דְּלִכְבוֹד רַבִּים שָׁרֵי \u0005(נ\"י פֶּרֶק אֵין מְגַלְּחִין וּבְהַגָּהוֹת מיי' וּבְמָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. וְיֵשׁ מְקִלִּין הָאִדָּנָא בִּשְׁאֵלַת שְׁלוֹם הָאָבֵל לְאַחַר \u0010c0\u0011 ל', וְאֵין טַעַם לָהֶם, אִם לֹא שֶׁיַּחְלְקוּ לוֹמַר שֶׁזֶּה מַה שֶּׁאָנוּ נוֹהֲגִים לֹא מִקְרֵי שְׁאֵלַת שָׁלוֹם \u0010c1\u0011 שֶׁבִּימֵיהֶם \u0005(סְבָרַת הָרַב)\u0006. וְעַיֵּן בא\"ח סִימָן פ\"ט.\nהַמּוֹצֵא אֶת חֲבֵרוֹ אָבֵל בְּתוֹךְ ל' יוֹם, מְדַבֵּר עִמּוֹ תַּנְחוּמִין וְאֵינוֹ שׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, שׁוֹאֵל בִּשְׁלוֹמוֹ וְאֵינוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִים כְּדַרְכּוֹ, אֶלָא מִן הַצַּד, שֶׁאֵינוֹ מַזְכִּיר לוֹ שֵׁם הַמֵּת, אֶלָא אוֹמֵר לוֹ: תִּתְנַחֵם. מֵתָה אִשְׁתּוֹ וְנָשָׂא אַחֶרֶת, אֵינוֹ נִכְנָס לְבֵיתוֹ לְדַבֵּר עִמּוֹ תַּנְחוּמִין. מְצָאוֹ בַּשּׁוּק, אוֹמֵר לוֹ: תִּתְנַחֵם, בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ. אֲבָל אִם לֹא נָשָׂא אַחֶרֶת, מְדַבֵּר עִמּוֹ תַּנְחוּמִין עַד שֶׁיַּעַבְרוּ ג' רְגָלִים. וְעַל אָבִיו וְעַל אִמּוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִין כָּל י\"ב חֹדֶשׁ; לְאַחַר י\"ב חֹדֶשׁ מְדַבֵּר עִמּוֹ מִן הַצַּד.\nמָקוֹם שֶׁנָּהֲגוּ לִהְיוֹת שׁוֹאֲלִים בִּשְׁלוֹם אֲבֵלִים בְּשַׁבָּת, שׁוֹאֲלִים. וְכָתַב הַרַמְבַּ\"ם שֶׁהָאָבֵל נוֹתֵן שָׁלוֹם לְכָל אָדָם בְּשַׁבָּת, שֶׁהוּא מִכְּלַל דְּבָרִים שֶׁבְּפַרְהֶסְיָא. \u0005הַגָּה: וְאָסוּר \u0010c2\u0011 לִשְׁלֹחַ מָנוֹת לְאָבֵל עַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וַאֲפִלּוּ בְּשַׁבָּת, בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת (תְּשׁוּבַת מהרי\"ל סי' ל\"א)\u0006 ; אֲבָל בְּמָקוֹם שֶׁנָּהֲגוּ לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת, גַּם זֶה שָׁרֵי.",[],["\u0003ל'. \u0004 על אביו ואמו. ש\"ך:","\u0003שבימיהם. \u0004 ובאמת אין זה טעם נכון דא\"כ תוך ל' נמי ולא מצינו לשום פוסק שחילק בכך עכ\"ל הש\"ך \u0005(ומיהו אפשר לומר כיון שרוב שאילת שלום שלנו אינו אלא שאומר צפרא טבא וזה מותר שאינו שאילת שלום ממש כדאיתא בב\"י בא\"ח סימן פ\"ה והביאו בש\"ע שם. ועוד מביא בב\"י שם בשם ר\"י פרישת שלום כמו כריעה אבל שלום בפה מותר כמו צפרא דמרי טב וכיוצא בו ע\"ש וכתב שם בד\"מ דבזוהר פקודי דף ק\"ג ע\"א משמע דאינו אסור רק כשמזכיר השם וזה שם לענין שלא יתן שלום לחבירו קודם שיתפלל וש\"מ שכל זה שאנו נוהגין אינו בכלל שאילת שלום כנ\"ל)\u0006:","\u0003מנות. \u0004 כ' הב\"ח בשם רבינו יהודה דאבל תוך ל' אינו יכול להזמין לאחרים או להזמן עם אחרים ע\"כ. ונראה דה\"ה כל י\"ב חדש על אביו ואמו עכ\"ל הט\"ז \u0005(וכן למזוג שקורין שענקי\"ן לאורח אבל. מהרי\"ל)\u0006 ואף בשבת במקום דנוהגין דאין שואלין בשלום בשבת. ד\"מ. וכתב מ\"א בא\"ח סי' תרנ\"ו ממשמעות דברי הרמ\"א דבמקום שאין נוהגים אבילות בפורים דינו כשבת ומותר לשלוח במקום שנהגו לשאול בשלומו \u0005(וט\"ז כתב שם אין נראה לסמוך על זה. עיין שם)\u0006:"]],["אָבֵל חַיָּב בַּעֲטִיפַת הָרֹאשׁ, דְּהַיְנוּ שֶׁיְּכַסֶה רֹאשׁוֹ בְּטַלִית אוֹ בְּסוּדָר וְיַחֲזִיר קְצָתוֹ עַל פִּיו וְעַל רֹאשׁ הַחֹטֶם; וְהָנֵי מִלֵי שֶׁצָּרִיךְ עֲטִיפָה, בְּכָל הַיּוֹם. אֲבָל כְּשֶׁבָּאִין מְנַחֲמִים אֶצְלוֹ, מְגַלֶה רֹאשׁוֹ לִכְבוֹדָם. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁאֵין נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ בַּעֲטִיפָה (הַגָּהוֹת מַיְמוֹנִי פ\"ה)\u0006 ; וְכֵן \u0010c0\u0011 הַמִּנְהָג פָּשׁוּט, וְאֵין לְהַחְמִיר לְשַׁנּוֹת בַּמֶּה שֶׁלֹּא נָהֲגוּ אֲבוֹתֵינוּ.",[],["\u0003המנהג. \u0004 מפני שמביא לידי שחוק גדול מן העובדי כוכבים ועבדים ושפחות שבינינו. מיהו יש לנהוג העטיפה קצת כמו עתה שמושכין הכובע לפני העינים כל ז' ימים ובשבת בצינעא ולא בפרהסיא. וכתב הב\"ח לפ\"ז מיד כשמתחיל החזן ברכו אז יגביה האבל את הכובע דלא להוי מלתא דפרהסיא. עכ\"ל:"]],["אָבֵל חַיָּב בִּכְפִיַּת הַמִּטָּה. וּבִשְׁעַת שֵׁנָה וַאֲכִילָה, יוֹשֵׁב עַל מִטָּה כְּפוּיָה, אֲבָל כָּל הַיּוֹם אֵינוֹ יוֹשֵׁב, אֲפִלוּ עַל מִטָּה כְּפוּיָה, אֶלָא עַל גַבֵּי קַרְקַע. וְכֵן הַמְנַחֲמִים אֵינָם רַשָּׁאִים לֵישֵׁב אֶלָא עַל גַבֵּי קַרְקַע. \u0010c0\u0011\nעַכְשָׁו לֹא נָהֲגוּ בִּכְפִיַּת הַמִּטָּה, מִפְּנֵי שֶׁיֹאמְרוּ הָעוֹבְדֵי כּוֹכָבִים שֶׁהוּא מְכַשְּׁפוּת, וְעוֹד שֶׁאֵין הַמִּטּוֹת שֶׁלָנוּ עֲשׂוּיוֹת כַּמִּטּוֹת שֶׁלָהֶן כְּדֵי שֶׁיְּהֵא נִכָּר בָּהֶם כְּפִיָּה.",[],["\u0003עכשיו. \u0004 כ' הש\"ך ומ\"מ אסור לו לישב ע\"ג ספסל או על כרים וכסתות כי אם ע\"ג קרקע אם לא חולה וזקן שיש להם צער בישיבה על גב קרקע מותרים להשים כר קטן מתחתיו. מיהו יכול לילך ולעמוד וא\"צ לישב כלל רק כשהמנחמים אצלו צריך לישב ע\"ג קרקע וה\"ה דכשרוצה לישן צריך לישן ע\"ג קרקע \u0005(ועכשיו רבים נהגו שלא לישן כל ז' ע\"ג קרקע אפשר מפני שטבעם חלוש והוי כחולים לענין זה)\u0006 מיהו המנחמים יושבים ע\"ג ספסל דמסתמא מחיל להו. עכ\"ל:"]],["אָבֵל אָסוּר לְהַנִּיחַ תְּפִלִין בְּיוֹם \u0010c0\u0011 רִאשׁוֹן; וְאַחַר שֶׁהֵנֵץ \u0010c1\u0011 הַחַמָּה בְּיוֹם שֵׁנִי, מֻתָּר לַהֲנִיחָם.\nמִבָּעֵי לֵהּ לְאָבֵל לְיַתּוֹבֵי דַּעְתֵּהּ לְכַוּוֹנֵי לִבֵּהּ לַתְּפִלִין שֶׁלֹּא יַסִיחַ דַּעְתּוֹ מֵהֶם, אֲבָל בִּשְׁעַת הֶסְפֵּד וּבְכִי לֹא מַנַּח לְהוּ.",[],["\u0003ראשון. \u0004 כתב הט\"ז דגם ביום שמועה קרובה אסור להניח תפילין כן כתב הרמב\"ן ומביאו ב\"י לקמן סימן ת\"ב עכ\"ל:","\u0003החמה. \u0004 כתב הש\"ך ויש פוסקים דאינו אסור אלא ביום ראשון וביום ב' מותר מיד אפי' קודם הנץ החמה \u0005(כשיאיר היום)\u0006 וכ\"פ הב\"ח עכ\"ל \u0005(ועיין בה\"י)\u0006:"]],["אָבֵל אָסוּר לְכַבֵּס כְּסוּתוֹ כָּל שִׁבְעָה יָמִים, אֲפִלוּ בְּמַיִם לְבַד; וּלְאַחַר שִׁבְעָה, מֻתָּר. וּכְשֵׁם שֶׁאָסוּר לְכַבֵּס, כָּךְ אָסוּר לִלְבֹּשׁ הַמְכֻבָּסִים קֹדֶם לָכֵן. \u0005וְאַחַר ז' שָׁרֵי, וְהָעוֹלָם נָהֲגוּ בּוֹ אִסּוּר (כְּדַעַת ריב\"א וְסִיעָתוֹ)\u0006. וְנוֹהֲגִין שֶׁאָדָם אַחֵר לוֹבְשָׁם תְּחִלָּה, וְאַחַר כָּךְ לוֹבְשָׁם הָאָבֵל, וְהַמִּנְהָג עִקָּר \u0005(טוּר בְּשֵׁם סמ\"ק וכ\"כ הַמָּרְדְּכַי ה\"א וְכָל בּוֹ)\u0006. וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ לְאַחַר שִׁבְעָה; וְאִם לְבָשׁוֹ אָדָם אַחֵר רַק \u0010c0\u0011 שָׁעָה אַחַת דַּי בְּכָךְ \u0005(כָּל בּוֹ וסמ\"ק)\u0006. וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לִלְבֹּשׁ חֲדָשִׁים. וְגַם הַסְדִינִים וְהַמַּצָּעוֹת שֶׁל מִטָּה אָסוּר לְכַבְּסָן וּלְהַצִּיעַ הַמְכֻבָּסִין. וְכֵן מִטְפְּחוֹת הַיָּדַיִם, אַף עַל פִּי שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד; וְכֵן כָּל אוֹתָן שֶׁשָּׁנִינוּ שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד, כְּגוֹן הַיּוֹצֵא מִבֵּית הַשִּׁבְיָה וּמִבֵּית הָאֲסוּרִים, וְהַמְּנֻדֶּה שֶׁהִתִּירוּ לוֹ חֲכָמִים, וְהַנִּשְׁאָל לְחָכָם וְהֻתַּר, וְהַבָּא מִמְּדִינַת הַיָּם שֶׁהָלַךְ \u0010c1\u0011 לְהַרְוִיחַ וְלֹא הָיָה לוֹ פְּנַאי \u0010c2\u0011 לְגַלֵחַ, אֲסוּרִים בִּימֵי אֶבְלוֹ, שֶׁאִם אֵרְעוֹ אֶחָד מֵהֶם, קֹדֶם הָאֲבֵלוּת וְנִכְנַס מִיָּד לְתוֹךְ הָאֲבֵלוּת, אָסוּר לְכַבֵּס אֶלָא אִם כֵּן אֵרְעוֹ אֶחָד מֵהֶם וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, אָז מֻתָּר לְכַבֵּס אַף בְּנֶתֶר וְחוֹל וַאֲפִלוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ. וְאַחַר שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מְכַבֵּס בְּמַיִם אֲבָל לֹא בְּנֶתֶר וְאָהָל.\nמֻתָּר לְכַבֵּס בִּגְדֵי קְטַנִּים שֶׁמֵּת אֲבִיהֶם.\nאָסוּר לִלְבֹּשׁ תּוֹךְ שִׁבְעָה כֵּלִים חֲדָשִׁים צְבוּעִים וִישָׁנִים יוֹצְאִים מִתַּחַת הַמַּכְבֵּשׁ. \u0005(פי' כְּלִי לַעֲצֹר בּוֹ הַבְּגָדִים)\u0006. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִלְבֹּשׁ בִּגְדֵי שַׁבָּת תּוֹךְ ד' שָׁבוּעוֹת הָרִאשׁוֹנִים, אֲבָל אַחַר כָּךְ מֻתָּר אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְכֵן לַעֲשׂוֹת בְּגָדִים חֲדָשִׁים\u0006 \u0005(כָּל בּוֹ בְּשֵׁם מוֹהֲרַ\"ם)\u0006, \u0005אָבֵל נָהֲגוּ אִסּוּר כָּל י\"ב חֹדֶשׁ.\u0006\nאָסוּר תּוֹךְ שִׁבְעָה \u0010c3\u0011 לְכַבֵּס וּלְהַנִּיחַ, בֵּין עַל יְדֵי עַצְמוֹ בֵּין עַל יְדֵי אֲחֵרִים. וְאִם הָיְתָה כְּסוּתוֹ בְּקִבֹּלֶת בְּיַד אֲחֵרִים, מְכַבֵּס אוֹתוֹ כִּדַרְכּוֹ כְּמוֹ שְׁאָר מְלַאכְתּוֹ בְּתָלוּשׁ שֶׁבְּיַד אֲחֵרִים, בְּקִבֹּלֶת.\nכָּל שְׁלֹשִׁים יוֹם אָסוּר לִלְבֹּשׁ \u0005אוֹ לְהַצִּיעַ תַּחְתָּיו (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 בֶּגֶד מְגֹהָץ, וְהוּא שֶׁיְּהֵא לָבָן וְחָדָשׁ, וַאֲפִלוּ הוּא שֶׁל פִּשְׁתָּן. וְעַל אָבִיו וְעַל אִמּוֹ, אָסוּר עַד שֶׁיַּגִיעַ הָרֶגֶל אַחַר שְׁלֹשִׁים וְיִגְעֲרוּ בּוֹ חֲבֵרָיו.\nגִהוּץ יֵשׁ אוֹמְרִים צק\"ל בִּלְשׁוֹן עֲרָב, וְיֵשׁ אוֹמְרִים דְּהַיְנוּ כִּבּוּס בְּמַיִם וְאֵפֶר אוֹ בְּנֶתֶר וּבֹרִית.\nאַחַר שִׁבְעָה מֻתָּר לְגַהֵץ, בֵּין לְעַצְמוֹ בֵּין לַאֲחֵרִים; וְלֹא אָמְרוּ שְׁלֹשִׁים יוֹם לְגִהוּץ, אֶלָא לִלְבֹּשׁ.\nיֵשׁ מִי שֶׁאוֹמֵר דְּהָאִידָּנָא לֵיכָּא אִסוּר גִהוּץ, שֶׁהֲרֵי אָמְרוּ גִהוּץ שֶׁלָנוּ כְּכִבּוּס שֶׁלָהֶם.",[],["\u0003שעה. \u0004 כלומר זמן מה וא\"צ שעה זמניות וכן משמע בפוסקים וכן נוהגין ולא כמ\"ש בלבוש שעה או שתים ואולי גם הוא לאו דוקא קאמר עכ\"ל הש\"ך וכתב הב\"ח דהמכובס במים לבד ולא בנתר וחול אין צריך להלבישו אחר תחלה ופשיטא דשרי לאחר ז' מיד:","\u0003להרויח. \u0004 לאפוקי לטיול. ועיין בא\"ח סי' תקל\"א:","\u0003לגלח. \u0004 וה\"ה כאן לכבס. ש\"ך:","\u0003לכבס. \u0004 הטעם משום דאסור בעשיית מלאכה. ש\"ך. וכ' מהרש\"ל עיין באו\"ח סי' תקנ\"א שהיתר פשוט לכבוד שבת לפרוש על השלחן המטפחת המכובסת:"]],["אָבֵל אָסוּר לְגַלֵחַ שְׂעָרוֹ, אֶחָד שְׂעַר רֹאשׁוֹ וְאֶחָד שְׂעַר זְקָנוֹ וְאֶחָד כָּל שֵׂעָר שֶׁבּוֹ, וַאֲפִלוּ שֶׁל בֵּית הַסְתָרִים, כָּל ל' יוֹם. וּשְׂעַר שֶׁל הַשָּׂפָה וּמֵהַצְּדָדִים, כָּל שֶׁמְּעַכֵּב אֶת הָאֲכִילָה, תּוֹךְ ז' אָסוּר; אַחַר שִׁבְעָה, מֻתָּר.\nיָשַׁב לְגַלֵחַ, וְאָמְרוּ לוֹ: מֵת אָבִיו, הֲרֵי זֶה מַשְׁלִים רֹאשׁוֹ, אֶחָד הַמְגַלֵחַ וְאֶחָד הַמִּתְגַלֵחַ; וּמַה שֶּׁהַסַפָּר גוֹמֵר, הַיְנוּ בִּדְלֵיכָּא סַפָּר אַחֵר בְּמָתָא.\nכָּל אוֹתָם שֶׁאָמְרוּ מֻתָּר לְגַלֵחַ בְּחֹל הַמּוֹעֵד, אִם אֵרְעוֹ אֶחָד מֵאֵלוּ קֹדֶם הָאֲבֵלוּת, וְנִכְנַס מִיָּד תּוֹךְ הָאֵבֶל, אָסוּר לְגַלֵחַ. אֲבָל אִם אֵרְעוֹ אֶחָד מֵאֵלוּ, וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מְגַלֵחַ כְּדַרְכּוֹ, בֵּין בְּתַעַר בֵּין בְּמִסְפָּרַיִם, וַאֲפִלוּ תּוֹךְ שִׁבְעָה. וְאָדָם אֶחָד שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מֵקֵל שְׂעָרוֹ בְּתַעַר אֲבָל לֹא בְּמִסְפָּרַיִם. \u0005וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006.\nעַל כָּל הַמֵּתִים מְגַלֵחַ לְאַחַר שְׁלֹשִׁים; עַל אָבִיו וְעַל אִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו. \u0005הַגָּה: וְאֵין הָרֶגֶל מְהָנֵי אִם פָּגַע קֹדֶם שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו (טוּר)\u0006. וְעַיֵּן בא\"ח סִימָן תקמ\"ח. וְשִׁעוּר גְּעָרָה יֵשׁ בּוֹ פְּלֻגְתָּא, וְנוֹהֲגִים בְּג' חֳדָשִׁים \u0005(כְּדַעַת מהרא\"י בִּפְסָקָיו וַאֲגֻדָּה ומהרי\"ל והר\"ן)\u0006. וּבִמְקוֹמוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין מִסְתַּפְּרִין עַל אָב וָאֵם כָּל י\"ב חֹדֶשׁ \u0005(מהרי\"ל מִנְהַג קְצָת מְקוֹמוֹת)\u0006, אִם לֹא לְצֹרֶךְ, כְּגוֹן שֶׁהִכְבִּיד עָלָיו שְׂעָרוֹ, אוֹ שֶׁהוֹלֵךְ בֵּין הָעוֹבְדֵי כּוֹכָבִים וּמִתְנַוֵּל בֵּינֵיהֶם בְּשַׂעֲרוֹתָיו, דְּמֻתָּר לְסַפֵּר \u0005(כֵּן הֵשִׁיב הָאוֹר זָרוּעַ)\u0006.\nאִשָּׁה מֻתֶּרֶת בִּנְטִילַת שֵׂעָר אַחַר ז'. \u0005הַגָּה: וְיֵשׁ אוֹסְרִים אַף לְאִשָּׁה, וְכֵן עִקָּר.\u0006\nלִסְרֹק רֹאשׁוֹ \u0010c0\u0011 בְּמַסְרֵק, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה.\nכְּשֵׁם שֶׁאָסוּר לְגַלֵחַ כָּל שְׁלֹשִׁים יוֹם, כָּךְ אָסוּר לִטֹּל צִפֹּרְנַיִם בִּכְלִי; אֲבָל בְּיָדָיו אוֹ בְּשִׁנָּיו, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה. וְאִשָּׁה שֶׁאֵרַע טְבִילָתָהּ אַחַר שִׁבְעָה, תּוֹךְ שְׁלֹשִׁים, אִם תִּטֹּל צִפָּרְנֶיהָ בְּיָדֶיהָ אוֹ בְּשִׁנֶּיהָ אֵינָהּ נוֹטֶלֶת יָפֶה, אֶלָא תֹּאמַר לְעוֹבֶדֶת כּוֹכָבִים לִטְּלָם בְּתַעַר אוֹ בְּמִסְפָּרַיִם. \u0005הַגָּה: וְלָאו דַּוְקָא עוֹבֶדֶת כּוֹכָבִים, אֶלָּא הוּא הַדִּין \u0010c1\u0011 יִשְׂרְאֵלִית, וְסִרְכָא דְּלִשְׁנָא דְּחֹל הַמּוֹעֵד נָקַט (דַּעַת עַצְמוֹ)\u0006.",[],["\u0003במסרק. \u0004 ובהגה' סמ\"ק בשם א\"ז מתיר דוקא לאשה ולא לאיש ומביאו הב\"ח. ש\"ך:","\u0003ישראלית. \u0004 והש\"ך כ' דדוקא נקט עובדת כוכבים דאלת\"ה אפילו לאיש לישתרי לגלח וליטול צפרניו ע\"י ישראל אחר אלא ודאי כיון דשלוחו הוא אסור אלא דוקא ע\"י עובדת כוכבים שרי דאמירה לעובד כוכבים לא אסור אלא משום שבות ובמקום מצוה לא גזרו ובט\"ז הקשה שהרי בס\"ה פסק דאשה מותרת בנטילת שער אחר ז' ולמה לא תהיה מותרת כאן ליטול צפרניה ע\"י עצמה בלא שינוי והלא אינם חמורים משער. גם קשה אפילו לדעת רמ\"א והלא בסי' שצ\"ג ס\"ג התיר ליטול צפרנים בשביל למול ולמה לא נתיר בשביל טבילת מצוה לכ\"ע עכ\"ל \u0005(ובנה\"כ כתב דלק\"מ דהכא כיון דאפשר ע\"י שינוי שאני דכל מה דאפשר לתקן עדיף. ומ\"ש מנטילת צפרני המוהל התם אין כונתו משום נוי רק שמתקן ב' צפרני אגודל שיש בהן צורך מילה כשהן משופעין ומחודדין לצורך הפריעה. עכ\"ל)\u0006:"]],["אָבֵל אָסוּר בְּשִׂמְחָה; לְפִיכָךְ לֹא יִקַח תִּינוֹק בְּחֵיקוֹ כָּל שִׁבְעָה, שֶׁמָּא יָבֹא לִידֵי שְׂחוֹק.\nעַל כָּל מֵתִים נִכְנָס לְבֵית הַמִּשְׁתֶּה לְאַחַר שְׁלֹשִׁים יוֹם; עַל אָבִיו וְעַל אִמּוֹ, לְאַחַר י\"ב חֹדֶשׁ. וְאַף אִם הַשָּׁנָה מְעֻבֶּרֶת, מֻתָּר לְאַחַר י\"ב חֹדֶשׁ. וּמִיהוּ שִׂמְחַת \u0010c0\u0011 מְרֵעוּת שֶׁהָיָה חַיָּב לִפְרֹעַ אוֹתָהּ מִיָּד, מֻתָּר לַעֲשׂוֹתָהּ מִיָּד אַחַר שִׁבְעָה. אֲבָל אִם אֵינוֹ חַיָּב לְפָרְעָהּ, אָסוּר לִכָּנֵס לָהּ עַד ל'. וְעַל אָבִיו וְעַל אִמּוֹ, אַף עַל פִּי שֶׁחַיָּב לְפָרְעָהּ, אָסוּר \u0005עַד\u0006 לְאַחַר י\"ב חֹדֶשׁ. \u0005הַגָּה: וּבַחֲבוּרַת מִצְוָה, כְּגוֹן שֶׁמַּשִּׂיא יָתוֹם וִיתוֹמָה לְשֵׁם שָׁמַיִם, וְאִם לֹא יֹאכַל שָׁם יִתְבַּטֵּל הַמַּעֲשֶׂה, מֻתָּר לְאַחַר ל', אֲבָל תּוֹךְ ל' אָסוּר לְכָל סְעֻדַּת מִצְוָה \u0010c1\u0011 שֶׁבָּעוֹלָם (טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. אֲבָל סְעֻדַּת מִצְוָה דְּלֵית בֵּיהּ שִׂמְחָה, מֻתָּר לִכָּנֵס בָּהּ, כְּגוֹן פִּדְיוֹן הַבֵּן אוֹ סְעֻדַּת בְּרִית מִילָה, מֻתָּר לֶאֱכֹל שָׁם אֲפִלּוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁלֹּא יֵצֵא מִפֶּתַח בֵּיתוֹ \u0005(ת\"ה סִי' רנ\"א)\u0006. וְיֵשׁ אוֹסְרִין בִּסְעֻדַּת בְּרִית מִילָה \u0005(מָרְדְּכַי)\u0006. וְהַמִּנְהָג שֶׁלֹּא לֶאֱכֹל בְּשׁוּם סְעֻדָּה בָּעוֹלָם כָּל י\"ב חֹדֶשׁ, אִם הוּא חוּץ לְבֵיתוֹ, וּבְתוֹךְ הַבַּיִת מְקִלִּין שֶׁאוֹכֵל בְּבֵיתוֹ בִּסְעֻדַּת בְּרִית מִילָה, וְכָל שֶׁכֵּן בִּשְׁאָר סְעֻדּוֹת שֶׁאֵין בָּהֶם שִׂמְחָה. אֲבָל בִּסְעֻדַּת נִשּׂוּאִין יֵשׁ לְהַחְמִיר, כֵּן נִרְאֶה לִי. אָבֵל שֶׁהוּא בַּעַל בְּרִית אוֹ מוֹהֵל, יִלְבַּשׁ בִּגְדֵי שַׁבָּת עַד לְאַחַר הַמִּילָה. וּמֻתָּר לִכָּנֵס לַמִּילָה לֶאֱכֹל שָׁם, אִם הוּא לְאַחַר \u0010c2\u0011 ל', אַף עַל פִּי שֶׁאֵין הַמִּילָה בְּבֵיתוֹ \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת מהרי\"ל)\u0006.\nלִכָּנֵס לַחֻפָּה שֶׁלֹּא בִּשְׁעַת אֲכִילָה, לִשְׁמֹעַ הַבְּרָכוֹת, יֵשׁ מַתִּירִין וְיֵשׁ אוֹסְרִין; אֶלָא עוֹמֵד חוּץ לַבַּיִת לִשְׁמֹעַ הַבְּרָכוֹת. \u0005הַגָּה: אָבֵל לֹא יִכָּנֵס לַבַּיִת כְּלָל בְּשָׁעָה שֶׁעוֹמְדִים שָׁם בְּמַזְמוּטֵי חָתָן וְכַלָּה, וְכֵן נוֹהֲגִים בְּאַשְׁכְּנַז (טוּר)\u0006 וּבִמְדִינוֹת אֵלּוּ. וְכָל זֶה בְּבַיִת שֶׁעוֹשִׂין הַחֲתֻנָּה וְאוֹכְלִין וְשׁוֹתִין וּשְׂמֵחִין שָׁם, אֲבָל בְּחֻפָּה שֶׁעוֹשִׂין בְּבֵית הַכְּנֶסֶת, שֶׁמְּבָרְכִין שָׁם בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין וְאֵין שִׂמְחָה כְּלָל, מֻתָּר מִיָּד אַחַר שִׁבְעָה \u0005(הַגָּהוֹת מַיְמוֹנִי)\u0006. וְיֵשׁ אוֹסְרִין עַד שְׁלֹשִׁים \u0005(שָׁם בְּשֵׁם ראבי\"ה)\u0006, וְכֵן נִרְאֶה לִי. וְיֵשׁ מְקוֹמוֹת שֶׁמַּחְמִירִין לִהְיוֹת הָאָבֵל עוֹמֵד כָּל י\"ב חֹדֶשׁ חוּץ לְבֵית הַכְּנֶסֶת לִשְׁמֹעַ הַבְּרָכוֹת \u0005(הַגָּהוֹת במהרי\"ל)\u0006. וּמִכָּל מָקוֹם נִרְאֶה דְּאָבֵל יָכוֹל לְבָרֵךְ בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין תַּחַת הַחֻפָּה שֶׁבְּבֵית הַכְּנֶסֶת. וְכֵן יוּכַל לְהַכְנִיס חָתָן כְּדֶרֶךְ אַרְצֵנוּ שֶׁשְּׁנֵי אֲנָשִׁים מַכְנִיסִין הֶחָתָן תַּחַת \u0010c3\u0011 הַחֻפָּה. וְיוּכַל לִלְבֹּשׁ קְצָת בִּגְדֵי שַׁבָּת בְּשָׁעָה שֶׁמַּכְנִיסִין, \u0010c4\u0011 וּבִלְבַד שֶׁיְּהֵא אַחַר ל' \u0005(ד\"ע)\u0006, וְכֵן נוֹהֲגִין. יֵשׁ מַתִּירִין לְאָבֵל לֶאֱכֹל בִּסְעֻדַּת נִשּׂוּאִין אוֹ בְּרִית מִילָה עִם הַמְּשַׁמְּשִׁין, וּבִלְבַד שֶׁלֹּא יְהֵא בִּמְקוֹם שִׂמְחָה כְּגוֹן בְּבַיִת אַחֵר \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006, וְיֵשׁ אוֹסְרִין \u0005(הַגָּהוֹת אֲשֵׁרִי)\u0006, וְכֵן נוֹהֲגִין, רַק שֶׁהָאָבֵל מְשַׁמֵּשׁ שָׁם, אִם יִרְצֶה, וְאוֹכֵל בְּבֵיתוֹ מִמַּה שֶּׁשּׁוֹלְחִין לוֹ מִן הַסְּעֻדָּה. יֵשׁ מַתִּירִין לְאָבֵל לֶאֱכֹל בְּאוֹתָהּ סְעֻדָּה שֶׁל דָּגִים שֶׁעוֹשִׂים לְאַחַר הַנִּשּׂוּאִין, כִּי מֵאַחַר שֶׁכְּבָר פָּסְקוּ לוֹמַר שֶׁהַשִּׂמְחָה \u0010c5\u0011 בִּמְעוֹנוֹ אִית לֵיהּ הֶכֵּר שֶׁאֵין שִׂמְחָה בְּאוֹתָהּ סְעֻדָּה, וְשָׁרֵי \u0005(בֵּית יוֹסֵף בְּשֵׁם רוֹקֵחַ)\u0006. יֵשׁ אוֹמְרִים דְּאָסוּר לֶאֱכֹל בִּסְעֻדָּה בַּלַּיְלָה שֶׁבְּיוֹם \u0010c6\u0011 הַמָּחֳרָת מֵת אָבִיו אוֹ אִמּוֹ \u0005(בְּהַגָּהוֹת מִנְהָגִים בְּשֵׁם מהרי\"ו)\u0006.",[],["\u0003מריעות. \u0004 שעושים ריעים זה עם זה שאוכלים ושותים עם זה היום וחוזרים ואוכלים עם זה למחר. ש\"ך:","\u0003שבעולם. \u0004 כתב הש\"ך משמע אפילו בשאר קרובים הדין כן. וכן לענין שאלת שלום ולענין נשואין אין חילוק כלל בין אביו ואמו לשאר קרובים. והב\"ח לא פירש כן ולא נהירא עכ\"ל:","\u0003ל'. \u0004 כתב הט\"ז דיש לתמוה על הרמ\"א שהרי בתשו' מהרי\"ל משמע דאחר ז' מותר. שוב ראיתי בד\"מ שהכריע כן מסברא דנפשיה לאסור עד אחר ל'. ודבר פשוט שעל אביו ואמו קאי דאלו בשאר קרובים פשיטא שמותר לאחר ל' דא\"ל דקמ\"ל איסורא תוך ל' דא\"כ ה\"ל לומר ואסור כל ל' אלא ע\"כ דבשאר קרובים אפי' תוך ל' שרי אחר ז' ימים והוא תמוה דבהדיא כתב הרא\"ש פ' אלו מגלחין דתוך ל' שוה בשאר קרובים לאביו ואמו. מ\"מ אין להקל בתוך ל' לאביו ואמו נגד הכרעת רמ\"א. עכ\"ל \u0005(ובנה\"כ כ' שהמעיין בתשו' מהרי\"ל סימן קכ\"ג יראה לעינים דאינו מתיר תוך ל' באביו ואמו ע\"ש)\u0006:","\u0003קצת. \u0004 בלבוש השמיט תיבת קצת ואולי גם הרב לאו דוקא נקט דה\"ה דיכול ללבוש כל בגדי שבת וכן נוהגין. ש\"ך:","\u0003ובלבד. \u0004 גם כאן פירש הב\"ח דיש להתיר לאבל על שאר קרוביו תוך ל' כמו בכניסת יתום ויתומה ואין כן דעת הש\"ך וכמ\"ש בס\"ק ב' ע\"ש. והט\"ז כ' ונ\"ל דלא התירו אלא להכניס החתן תחת החופה אבל לא ליכנס לאכול על סעודת החתונה דהא אפי' במשיא יתום ויתומה לא התירו לאכול בסעודה אם לא בדרך שאם לא יהיה שם יתבטל המעשה והא ודאי דמשיא יתומה הוה כמו אביה וטפי הוה מסתבר להתיר מאותו שמכניס החתן תחת החופה כנ\"ל שלא כקצת שנוהגים להקל בזה עכ\"ל \u0005(ויש נוהגין להיות מן המשמשים על הסעודה ולאכול אח\"כ עם המשמשים אחר גמר הסעודה וזה אין למחות בידם. אבל להסב על השלחן כשאר בעלי הסעודה ראוי למחות)\u0006:","\u0003במעונו. \u0004 כ' הב\"ח מיהו בליל ב' אע\"פ דנוהגין בק\"ק קראקא שלא לברך שהשמחה במעונו אין לאבל לאכול באותה סעודה דל\"ד ליום ב' שכבר בעל בעילת מצוה בליל ב' כפי מנהגם ולכך עושים סעודה של דגים ביום ב' משום ברכת דגים כדאיתא פ\"ק דכתובות הלכך אינה נקראת סעודת שמחה ואין אומרים לא אשר ברא ולא שהשמחה במעונו אבל בליל ב' מקמי בעילת מצוה דמברכים אשר ברא לא נגמרו הנשואים. ומה שלא נהגו לומר שהשמחה במעונו הוא מפני שמתאספים שם אנשים ונשים וכו' ע\"ש. וכתב הט\"ז ולפי המנהג שכ' רמ\"א שלא לאכול בשום סעודה גם באותה סעודה של דגים אסור. עכ\"ל:","\u0003המחרת. \u0004 וכ' הלבוש ולא ראיתי נוהגין כן ואני אומר בדבר שאינו מצוי לא שייך בו מנהג כמ\"ש לעיל ר\"ס ק\"ץ ע\"ש. ולא ראינו אינו ראיה. ואני ראיתי נוהגין לאיסור. גם לקמן ס\"ס ת\"ב כתב הרב בסתם לאיסור. עכ\"ל הש\"ך:"]],["אָסוּר לִשָּׂא אִשָּׁה כָּל ל' יוֹם, אֲפִלוּ בְּלֹא סְעֻדָּה; וּלְאַחַר שְׁלֹשִׁים, מֻתָּר, אֲפִלוּ עַל אָבִיו וְאִמּוֹ, וַאֲפִלוּ לַעֲשׂוֹת סְעֻדָּה. וּמֻתָּר לְקַדֵּשׁ אִשָּׁה אֲפִלוּ בְּיוֹם הַמִּיתָה, וְהוּא שֶׁלֹּא יַעֲשֶׂה סְעֻדָּה, אֶלָא אִם כֵּן עָבְרוּ שְׁלֹשִׁים יוֹם. \u0005וְיֵשׁ אוֹמְרִים דְּגַם \u0010c0\u0011 לְאָרֵס אָסוּר כָּל ל' יוֹם (טוּר וְהָרֹא\"שׁ וְהָרַמְבַּ\"ן)\u0006 וְכֵן עִקָּר.\nמֵתָה \u0010c1\u0011 אִשְׁתּוֹ, אָסוּר לִשָּׂא אַחֶרֶת עַד שֶׁיַּעַבְרוּ עָלֶיהָ שָׁלֹשׁ רְגָלִים, \u0005אֲבָל לִכָּנֵס לְבֵית הַמִּשְׁתֶּה, דִּינוֹ כְּמוֹ \u0010c2\u0011 בִּשְׁאָר קְרוֹבִים, (טוּר)\u0006 וְרֹאשׁ הַשָּׁנָה וְיוֹם כִּפּוּרִים אֵינָם \u0010c3\u0011 חֲשׁוּבִים כִּרְגָלִים לְעִנְיָן זֶה. וְאִם לֹא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, אוֹ שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, אוֹ שֶׁאֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, \u0010c4\u0011 מֻתָּר לְקַדֵּשׁ מִיָּד וְלִכְנֹס אַחַר שִׁבְעָה; וְלֹא יָבֹא עָלֶיהָ עַד לְאַחַר שְׁלֹשִׁים יוֹם, אֶלָא אִם כֵּן לֹא קִיֵּם מִצְוֹת פְּרִיָּה וּרְבִיָּה, שֶׁאָז מֻתָּר לָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְהוּא הַדִּין בִּשְׁאָר אֲבֵלוּת, אֲפִלּוּ בַּאֲבֵלוּת דְּאָבִיו וְאִמּוֹ, מֻתָּר לִשָּׂא וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה, אִם לֹא קִיֵּם פִּרְיָה וּרְבִיָּה. יֵשׁ אוֹמְרִים דְּאַף מִי שֶׁהוּא עָשִׁיר וִיכֹלֶת בְּיָדוֹ לִשְׂכֹּר לוֹ מְשָׁרְתִים וּמְשָׁרְתוֹת, מִכָּל מָקוֹם אִם אֵין בִּתּוֹ אוֹ כַּלָּתוֹ אֶצְלוֹ בְּבֵיתוֹ שֶׁתּוּכַל לְשַׁמְּשׁוֹ בַּחֲפִיפַת הָרֹאשׁ אוֹ שְׁאָר דְּבָרִים שֶׁמִּתְבַּיֵּשׁ מֵאֲחֵרִים, מִקְרֵי אֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, וְכָל כַּיּוֹצֵא בָּזֶה (פִּסְקֵי מהרא\"י סי\"ג)\u0006 ; וְלָכֵן נִשְׁתַּרְבֵּב הַמִּנְהָג שֶׁרַבִּים מְקִלִּין בָּעִנְיָן וְנוֹשְׂאִין נָשִׁים תּוֹךְ שָׁלֹשׁ רְגָלִים, וּבַעַל נֶפֶשׁ יָחוּשׁ לְעַצְמוֹ. מִי שֶׁתְּפָשׂוֹ הַשַּׂר וְאֵינוֹ רוֹצֶה לְהַנִּיחוֹ מִתְּפִיסָתוֹ, עַד שֶׁיִּשָּׂא אִשָּׁה תּוֹךְ שָׁלֹשׁ רְגָלִים אַחַר מִיתַת אִשְׁתּוֹ, יֵשׁ מַתִּירִין מִשּׁוּם צַעַר דִּידֵיהּ \u0005(בֵּית יוֹסֵף)\u0006, וְכֵן נִרְאֶה לִי עִקָּר.\nמִי שֶׁלֹּא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, וְשִׁדֵּךְ אִשָּׁה וְאַחַר שֶׁהֵכִין צָרְכֵי חֻפָּה, מֵת אֲחִי \u0010c5\u0011 הַמְשֻׁדֶּכֶת, מֻתָּר לְכָּנְּסָהּ וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְכֵן אִם יֵשׁ לוֹ בָּנִים קְטַנִּים וְנִתְרַצָּה לְאָחוֹת אִשְׁתּוֹ, \u0010c6\u0011 מֻתָּר לְכַנְּסָהּ, כִּי הִיא מְרַחֶמֶת עַל בְּנֵי אֲחוֹתָהּ יוֹתֵר מֵאַחֶרֶת (כ\"כ בְּפי' הָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּמָרְדְּכַי)\u0006.",[],["\u0003לארס. \u0004 מיהו לקשר עצמו בשידוכין בלא אירוסין ודאי שרי אפי' ביום המיתה. ב\"ח:","\u0003אשתו. \u0004 והיא שמת בעלה אינה מתאבלת אלא ל' יום רק שאסורה ליארס ולינשא עד אחר ג' חדשים משום הבחנה כמ\"ש בא\"ע סי' י\"ג עכ\"ל הטור. וכתב המרדכי הטעם שאין האשה צריכה להמתין ג' רגלים משום דאשה בכל דהו ניחא לה ושוכחת אהבת הראשון אחר ל' יום. ואם אירע שנשאת תוך ל' יום לאבלותה של שאר קרובים לא תבעל כן דעת הרמב\"ם לפי מה שפי' הב\"ח דבריו ע\"ש עכ\"ל הש\"ך:","\u0003בשאר. \u0004 וכן כל שאר אבילות אינו נוהג רק שלשים יום כמו בשאר קרובים. ש\"ך:","\u0003חשובים. \u0004 ובאגודה פסק דחשיבי כרגלים אף לענין זה \u0005(ובנה\"כ כ' דכל הפוסקים חולקים עליו וכן דעת כל האחרונים וטעמייהו מסתבר עכ\"ל)\u0006 ומיהו נראה לפי המנהג שכתב רמ\"א שרבים מקילין ובעל נפש יחוש לעצמו אבל אם עברו ג' רגלים עם ר\"ה ויוה\"כ יוכל לסמוך על בעל אגודה. והטעם לזה אינו משום תוספת אבילות אלא כדי שתשתכח הראשונה מדעתו בשעה שיהיה עם השניה וע\"י שמחת הרגלים הוא שוכח הראשונה ע\"כ יש מי שרוצה לחלק בזה אם היה לו אשה חולנית זמן רב או שהיה להם איבה ורצה לגרשה ומתה שאז ודאי נשכח אהבת הראשונה מלבו מיד. משא\"כ אם היתה עמו באהבה תמיד וחלתה כדרך העולם ומתה דאז אהבת הראשונה תקועה בלבו ואינה נשכחת עד אחר ג' רגלים. אבל לא נראה לחלק כן מדעתנו מה שאינו נזכר בגדולי פוסקים וגם האחרונים אין מזכירין מזה רק בת' מיימונית מפלפל ומאריך בזה ע\"ש בהלכות שמחות. ואין לזוז מדברי הרמ\"א. ועי' בתשובת חב\"י שאלה ד' מעשה שאירע שם והחמיר בזה ועי' תשובת ראנ\"ח ח\"ב שאלה ד':","\u0003לקדש. \u0004 והב\"ח כתב דהיינו לדעת המחבר דמתיר בס\"א לקדש ביום המיתה ולא קיימא לן הכי אלא דאחר שבעה מיד רשאי לקדשה ולכנסה:","\u0003לכנסה. \u0004 כתב הש\"ך הטעם כיון דאיכא הפסד בדבר אם לא יכניס וגם לא קיים פריה ורביה וע\"ל סי' שמ\"ב. והט\"ז כתב דהך לכנסה קאי אלאחר שבעה דבתוך ז' אפי' במקום הפסד אסור ע\"ש:","\u0003מותר לכנסה. \u0004 מיד ולבא עליה אחר שבעה כ\"כ הלבוש והב\"ח כתב דלא יבא עליה עד אחר ל' ונראה דלא פליגי דהלבוש מיירי בשלא קיים פו\"ר והב\"ח איירי בדקיים עכ\"ל הש\"ך:"]],["אָבֵל, ג' יָמִים הָרִאשׁוֹנִים אֵינוֹ יוֹצֵא לְבֵית הָאָבֵל וְלֹא לְבֵית \u0010c0\u0011 הַקְבָרוֹת; מִכָּאן וָאֵילָךְ, אִם מֵת לַאֲחֵרִים מֵת בִּשְׁכוּנָתוֹ, יוֹצֵא אַחַר הַמִּטָּה לְבֵית הַקְבָרוֹת, וְאֵינוֹ יוֹשֵׁב בִּמְקוֹם הַמְנַחֲמִים אֶלָא בִּמְקוֹם הַמִּתְנַחֲמִים; וְאִם אֵין שָׁם כְּדֵי מִטָּה וְקוֹבְרֶיהָ, יוֹצֵא אֲפִלוּ בְּיוֹם רִאשׁוֹן וַאֲפִלוּ בִּשְׁכוּנָה אַחֶרֶת. \u0005הַגָּה: וּמִקְצָת יוֹם ג' הֲרֵי הוּא כְּכֻלּוֹ (הַגָּהוֹת מַיְמוֹנִי פ\"ז)\u0006. וְלֹא רָאִיתִי נוֹהֲגִין כֵּן עַכְשָׁו, כִּי אֵין אָבֵל הוֹלֵךְ לְבֵית הַקְּבָרוֹת וְלֹא לְבֵית הָאָבֵל כָּל שִׁבְעָה; וְאֶפְשָׁר שֶׁלָּאו חִיּוּב הוּא, אֶלָּא רְשׁוּת, וּמֵאַחַר שֶׁעַכְשָׁו אֵין מִתְנַחֲמִין כְּמוֹ בִּימֵיהֶם, שֵׁב וְאַל תַּעֲשֶׂה עָדִיף.\nאָבֵל, שָׁבוּעַ הָרִאשׁוֹן אֵינוֹ יוֹצֵא מִפֶּתַח בֵּיתוֹ, וַאֲפִלוּ לִשְׁמֹעַ בִּרְכוֹת חֻפָּה אוֹ בִּרְכוֹת הַמִּילָה. \u0005הַגָּה: מִיהוּ הַמֵּקֵל לָצֵאת בַּלַּיְלָה, מִפְּנֵי הַצֹּרֶךְ, לֹא הִפְסִיד (ת\"ה סִימָן ר\"צ)\u0006. וְהָא דְּאָסוּר לָצֵאת חוּץ לְבֵיתוֹ, הַיְנוּ דַּוְקָא לְטַיֵּל, אוֹ לְמַשָּׂא וּמַתָּן וְכַדּוֹמֶה, אֲבָל אִם שָׁלַח מוֹשֵׁל אַחֲרָיו \u0005(מָרְדְּכַי ה\"א)\u0006 אוֹ שֶׁצָּרִיךְ לֵילֵךְ בַּדֶּרֶךְ אוֹ לִשְׁאָר דְּבָרִים הַצְּרִיכִים לוֹ הַרְבֵּה, כְּגוֹן דָּבָר הָאָבֵד, מֻתָּר לוֹ לָצֵאת \u0005(תּוֹסָפוֹת סוֹף מ\"ק)\u0006, וְכֵן נוֹהֲגִין. וְדִין נְעִילַת סַנְדָּלָיו, עַיֵּן לְעֵיל סִימָן שפ\"ב. שְׁנִיָּה, יוֹצֵא וְאֵינוֹ יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר; שְׁלִישִׁית, יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר. \u0005הַגָּה: וְאִם רוֹצֶה שֶׁלֹּא לֵישֵׁב בִּמְקוֹמוֹ בְּשָׁבוּעַ שְׁלִישִׁית וּלְדַבֵּר, הָרְשׁוּת בְּיָדוֹ (הגמי\"י)\u0006. וְעַכְשָׁו נוֹהֲגִין שֶׁאֵין יוֹשְׁבִין בִּמְקוֹמָם כָּל שְׁלֹשִׁים; וְעַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וְאֵין לְמִנְהָג זֶה עִקָּר, מִכָּל מָקוֹם אֵין לְשַׁנּוֹת מִן הַמִּנְהָג, כִּי כָּל מָקוֹם לְפִי מִנְהָגוֹ; רְבִיעִית, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. אֲפִלוּ לֹא שָׁלְמוּ שְׁלֹשָׁה שְׁבוּעוֹת, כְּגוֹן שֶׁמֵּת בְּאֶמְצַע שָׁבוּעַ, מִיָּד כְּשֶׁכָּלָה אוֹתוֹ שָׁבוּעַ וּשְׁנַיִם שֶׁאַחֲרָיו, חָשׁוּב שָׁבוּעַ הַבָּא רְבִיעִית.\nהָאָבֵל אֵינוֹ יוֹצֵא בַּחֹל לְבֵית הַכְּנֶסֶת, אֲבָל בְּשַׁבָּת יוֹצֵא. \u0005וְכֵן לְבֵית הַמִּדְרָשׁ (בֵּיתיוֹסֵף)\u0006. וְאָנוּ נוֹהֲגִים שֶׁבְּכָל יוֹם קְרִיאַת הַתּוֹרָה יוֹצֵא לב\"ה. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין יוֹצֵא אֶלָּא בְּשַׁבָּת. וְאִם הָאָבֵל מוֹהֵל אוֹ בַּעַל \u0010c1\u0011 בְּרִית, לְאַחַר שְׁלֹשָׁה, מִתְפַּלֵּל בְּבֵיתוֹ, וּכְשֶׁמְּבִיאִין הַתִּינוֹק לָמוּל, הוֹלֵךְ הָאָבֵל לְבֵית הַכְּנֶסֶת (הַגָּהוֹת אֲשֵׁרִי)\u0006. אֲבָל, תּוֹךְ שְׁלֹשָׁה, לֹא יֵצֵא אֶלָּא אִם כֵּן אֵין מוֹהֵל אַחֵר \u0010c2\u0011 בָּעִיר \u0005(אוֹר זָרוּעַ)\u0006 ; וְיֵשׁ \u0010c3\u0011 מְקִלִּין אֲפִלּוּ תּוֹךְ שְׁלֹשָׁה, אֲפִלּוּ אִם יֵשׁ מוֹהֵל אַחֵר בָּעִיר \u0005(בֵּית יוֹסֵף)\u0006 ; וּמֻתָּר לוֹ לְתַקֵּן הַצִּפָּרְנַיִם וּלְגַלֵּחַ לְצֹרֶךְ הַמִּילָה, אֲבָל אִם יֵשׁ מוֹהֵל אַחֵר אָסוּר \u0005(סְבָרַת הָרַב דְּלֹא כְּאוֹר זָרוּעַ דְּמַתִּיר סְתָם)\u0006. וְכֵן כָּל דְּבַר מִצְוָה שֶׁאִי אֶפְשָׁר לַעֲשׂוֹת בְּלֹא הָאָבֵל, מֻתָּר לוֹ לָצֵאת לְקַיֵּם הַמִּצְוָה \u0005(סְבָרַת הָרַב וּבֵית יוֹסֵף)\u0006.\nהַנּוֹהֲגִים כְּשֶׁהֵם אֲבֵלִים שֶׁלֹּא לְשַׁנּוֹת מְקוֹמָם בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת, יָפֶה הֵם עוֹשִׂים. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁגַּם בְּשַׁבָּת יְשַׁנֶּה מְקוֹמוֹ (נִמּוּקֵי יוֹסֵף סוֹף פֶּרֶק הַמּוֹכֵר פֵּרוֹת)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת הַמִּנְהָג.",[],["\u0003הקברות. \u0004 אם מת לאחרים מת. כ\"כ הש\"ך \u0005(אבל אם מת לו מת יוצא אפילו ביום כנ\"ל:\n\n\u0006","\u0003ברית. \u0004 פי' סנדק ולכן תוך שלשה ימים לא יוצא אבל אבי הבן פשיטא דאפי' תוך ג' ימים יוצא לכ\"ע. ש\"ך:","\u0003בעיר. \u0004 ואז מותר אפילו ביום ראשון. ש\"ך:","\u0003מקילין. \u0004 כתב הש\"ך וקשה דהב\"י כ\"כ לפי מנהגו שהאבל יוצא לבהכ\"נ להתפלל בכל יום קריאת התורה כ\"ש שיוצא כדי למול אפילו תוך ג' ימים ראשונים ואפילו יש מוהל אחר בעיר וא\"כ מאחר שכתב הרב דאנו נוהגים שאינו יוצא אלא בשבת למה כתב סברת היש מקילין כאן עכ\"ל:"]],["אֵין מִתְקַשִּׁין עַל הַמֵּת יוֹתֵר מִדַּאי; וְכָל הַמִּתְקַשֶּׁה עָלָיו יוֹתֵר מִדַּאי, עַל מֵת אַחֵר הוּא בּוֹכֶה; אֶלָא שְׁלֹשָׁה יָמִים לִבְכִי, שִׁבְעָה לְהֶסְפֵּד, שְׁלֹשִׁים לְתִסְפֹּרֶת וּלְגִהוּץ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר הָעָם. אֲבָל תַּלְמִידֵי חֲכָמִים, הַכֹּל לְפִי חָכְמָתָם; וְאֵין בּוֹכִים עֲלֵיהֶם יוֹתֵר מִל' יוֹם; וְאֵין מַסְפִּידִין עֲלֵיהֶם יוֹתֵר מִי\"ב חֹדֶשׁ; וְכֵן חָכָם שֶׁבָּא שְׁמוּעָתוֹ לְאַחַר י\"ב חֹדֶשׁ, אֵין מַסְפִּידִין אוֹתוֹ.\nיוֹצְאִין לְבֵית הַקְבָרוֹת \u0010c0\u0011 וּפוֹקְדִים עַל הַמֵּתִים שְׁלֹשָׁה יָמִים, שֶׁמָּא עֲדַיִן הוּא חַי.\nכָּל שְׁלֹשָׁה יָמִים יִרְאֶה הָאָבֵל כְּאִלוּ חֶרֶב מֻנַּחַת לוֹ בֵּין כְּתֵפָיו; מִשִּׁלֹשָׁה וְעַד שִׁבְעָה, כְּאִלוּ זָקוּף כְּנֶגְדּוֹ בְּקֶרֶן זָוִית; מִשִּׁבְעָה וְעַד שְׁלֹשִׁים, כְּאִלוּ עוֹבֵר לְפָנָיו בַּשּׁוּק; וְכָל אוֹתָהּ הַשָּׁנָה הַדִּין מְתוּחָה כְּנֶגֶד אוֹתָהּ מִשְׁפָּחָה; וְאִם נוֹלָד בֵּן זָכָר בְּאוֹתָהּ מִשְׁפָּחָה, נִתְרַפֵּאת כָּל הַמִּשְׁפָּחָה.\nאֶחָד מֵהַחֲבוּרָה שֶׁמֵּת, תִּדְאַג כָּל הַחֲבוּרָה.\nכָּל מִי שֶׁאֵינוֹ מִתְאַבֵּל כְּמוֹ שֶׁצִּוּוּ חֲכָמִים, הֲרֵי זֶה אַכְזָרִי; אֶלָא יִפְחַד וְיִדְאַג וִיפַשְׁפֵּשׁ בְּמַעֲשָׂיו וְיַחֲזֹר בִּתְשׁוּבָה.",[],["\u0003ופוקדים. \u0004 כתב הפרישה זה היה דוקא בימיהם שהיו מניחין את המת בכוכין והיה אפשר לגלות את המת ולראותו. וכתב עוד בשם מהרש\"ל אדם שמת לו מת ובתוך ל' נולד לו בן אין עושין שמחה ומשתה ביום המילה רוקח עכ\"ל. וכמדומה שאין נוהגין כן. ש\"ך:"]],["כֵּיוָן שֶׁעָמְדוּ מְנַחֲמִים מֵאֵצֶל הָאָבֵל בְּיוֹם שְׁבִיעִי, מֻתָּר בְּכָל דְּבָרִים שֶׁאָסוּר בָּהֶם תּוֹךְ שִׁבְעָה, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ, לֹא שְׁנָא מִקִצָת יוֹם שְׁבִיעִי לֹא שְׁנָא מִקְצָת יוֹם שְׁלֹשִׁים, כֵּיוָן שֶׁהֵנֵץ \u0010c0\u0011 הַחַמָּה בְּיוֹם שְׁלֹשִׁים, בָּטְלוּ מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים \u0005(רֹא\"שׁ וְרַבֵּנוּ יְרוּחָם)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ שֶׁאֵין הַמְּנַחֲמִין רְגִילִין לָבוֹא בְּיוֹם ז', צָרִיךְ לְהַמְתִּין עַד שָׁעָה שֶׁרְגִילִין הַמְּנַחֲמִים לָבוֹא בִּשְׁאָר יָמִים, דְּהַיְנוּ לְאַחַר יְצִיאָה מִבֵּית הַכְּנֶסֶת שֶׁרְגִילִין לָבוֹא מְנַחֲמִין, כֵּן נִרְאֶה לִי, וּדְלֹא כְּמוֹ שֶׁרְגִילִין לְהַמְתִּין שָׁעָה עַל הַיּוֹם, דְּאֵין הַדָּבָר תָּלוּי רַק בַּעֲמִידַת הַמְּנַחֲמִין.\u0006 \u0005(וְכֵן מַשְׁמָע בַּאֲשֵׁרִי)\u0006.\nשָׁמַע שְׁמוּעָה רְחוֹקָה בַּלַיְלָה, כֵּיוָן דְּסָגֵי בְּשָׁעָה אַחַת, סַלְקָא, אֲפִלוּ בַּלַיְלָה.\nמִי שֶׁמֵּת אָבִיו אוֹ אִמּוֹ בְּרֹאשׁ חֹדֶשׁ נִיסָן, לֹא אַמְרִינָן בכ\"ט בַּאֲדָר שֶׁאַחֲרָיו מִקְצָת הַיּוֹם כְּכֻלוֹ, אֶלָא צָרִיךְ לִנְהֹג דְּבָרִים הָאֲסוּרִים בי\"ב חֹדֶשׁ עַד \u0010c1\u0011 שֶׁיִּכָּנֵס רֹאשׁ חֹדֶשׁ נִיסָן. \u0005הַגָּה: וְנָהֲגוּ \u0010c2\u0011 לְהוֹסִיף עוֹד הַיּוֹם שֶׁמֵּת בּוֹ הָאָב אוֹ הָאֵם לִנְהֹג בּוֹ דִּין י\"ב חֹדֶשׁ, וְנָכוֹן הוּא.\u0006",[],["\u0003החמה. \u0004 דביום ל' שאין מנחמים מותר מיד בהנץ החמה. ש\"ך:","\u0003שיכנס. \u0004 הטעם בת\"ה שם דכל שתלוי במנין הימים אמרי' מקצת יום האחרון ככולו משא\"כ באבלות התלוי בי\"ב חדש בכל דוכתי אם תאמר מקצתו ככולו לא יצטרך להתאבל רק קצת חדש האחרון וזה אינו. עכ\"ל הט\"ז:","\u0003להוסיף. \u0004 ואפילו חל אותו היום בשבת נוהג בו דין י\"ב חדש כן הוא בת\"ה סי' רצ\"ב. מיהו כשהשנה מעוברת דמותר ליכנס לבית המשתה לאחר י\"ב חדש כמ\"ש בסי' שצ\"א ס\"ב אין נוהג דין י\"ב חדש ביום שמת בו אב או אם אע\"פ שאומר קדיש וברכו ומתענה בו ביום דמאחר שכבר הפסיק מאבלותו שוב אינו חוזר לאבלותו כ\"כ הב\"ח. ונראה דהיינו דוקא בשאר מיני אבילות אבל לאכול בסעודת שמחה ומשתה אסור בכל שנה ביום שמת בו אב או אם וכמ\"ש הרב לקמן ס\"ס ת\"ב כ\"ש הכא עכ\"ל הש\"ך \u0005(ועי' מ\"ש לעיל סי' שצ\"א. ומיהו אפילו לדעת המקילין בזה כמ\"ש הלבוש וכמ\"ש לעיל מ\"מ בשנה ראשונה אפילו בשנת העיבור לא יאכל בסעודה של שמחה. ומכל מקום נוהגין שאם חל יארציי\"ט שלו בשבת או ביום טוב שלובשים טלית של חול כדי לשנות קצת. וכן נוהגין כל השנים אפילו לאחר שנה ראשונה ובענין תענית יארציי\"ט אם ישלים עיין סי' ת\"ב)\u0006:"]],["אָבֵל שֶׁלֹּא נָהַג אֲבֵלוּתוֹ תּוֹךְ שִׁבְעָה, בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד, מַשְׁלִים אוֹתוֹ כָּל שְׁלֹשִׁים, חוּץ מֵהַקְרִיעָה, שֶׁאִם לֹא קָרַע בִּשְׁעַת חִמּוּם, אֵינוֹ \u0010c0\u0011 קוֹרֵעַ, אֶלָא תּוֹךְ שִׁבְעָה, חוּץ מֵאָבִיו וְאִמּוֹ שֶׁקוֹרֵעַ אֲפִלוּ לְאַחַר שִׁבְעָה.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁלֹּא נָהַג אֲבֵלוּת כְּלָל כָּל שִׁבְעָה; אֲבָל אִם זִלְזֵל בְּמִקְצָת הַיָּמִים, וְלֹא נָהַג בָּהֶם אֲבֵלוּת, כְּגוֹן מִי שֶׁאָמְרוּ לוֹ שֶׁמֵּת לוֹ מֵת בַּיּוֹם הָא', וְהָיָה בְּעִיר אַחֶרֶת וְלֹא נָהַג אֲבֵלוּת, וּבַיּוֹם הַשֵּׁנִי בָּא לְעִירוֹ וְנָהַג אֲבֵלוּת, אֵין צָרִיךְ לְהַשְׁלִים, וּמוֹנֶה שִׁבְעָה מִיּוֹם הָרִאשׁוֹן.\nקָטָן שֶׁמֵּת אָבִיו וְאִמּוֹ, \u0010c1\u0011 אֲפִלוּ הִגְדִּיל תּוֹךְ שִׁבְעָה, בָּטֵל מִמֶּנּוּ כָּל דִּין אֲבֵלוּת וְאֵינוֹ חַיָּב בּוֹ.",[],["\u0003קורע. \u0004 כ' הב\"ח דהיכא שהיה אנוס שהיה חולה ומסוכן שא\"א לקרוע או שאין דעתו צלולה ומיושבת עליו וחזר לבוריו ולדעתו אחר ז' שחשוב עכשיו כשעת חימום דל\"ד לשוגג או מזיד דעבר שעת חימום כיון שהיה בריא בשעה ששמע שמת לו מת וחייב באותה שעה אבל זה לא נתחמם אלא בשעה שחזר לבוריו ודעתו צלולה ומיושבת ובאותה שעה חל עליו חובת קריעה עכ\"ל \u0005(וט\"ז פסק דפטור מלקרוע אח\"כ ע\"ש ודבריו נראין תמוהין חדא שאין מזכיר דברי חמיו כדרכו ועוד תחלת דבריו משכימים עם הב\"ח ואח\"כ מסיים וע\"כ פטור אח\"כ מלקרוע. ע\"כ נ\"ל שטעות נפל בדבריו או איזה חסרון יש כאן וע\"ש)\u0006:","\u0003הגדיל. \u0004 והב\"ח פסק כדעת מהר\"ם דבהגדיל תוך שבעה מונה ז' ול' משעה שהגדיל אבל אם הגדיל אחר ל' בטל ממנו גזרת ז' ול' ע\"ש והט\"ז מאריך בדין זה וסוף דבריו סיים לענין הלכה למעשה נראה כפסק הש\"ע דקטן פטור מהאבלות כי דבריו הם צודקים וברורים. ומקום הניחו לנו רבותינו אבות העולם לזכות בו בס\"ד:"]],["מִתְאַבְּלִין עַל פִּי עֵד אֶחָד, וְעֵד מִפִּי עֵד \u0010c0\u0011 וְעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי \u0010c1\u0011 תֻּמּוֹ.\nשְׁנַיִם אוֹמְרִים: מֵת, וּשְׁנַיִם אוֹמְרִים: לֹא מֵת, אֵינוֹ מִתְאַבֵּל.",[],["\u0003ועובד כוכבים. \u0004 כתב רש\"ל עובדת כוכבים שספרה לפי תומה לראובן שמתה אחותו פסק ראבי\"ה שמתאבל על פיה דנאמנת להחמיר. וא\"מ פסק דהלכתא כדברי המיקל באבל ועובד כוכבים אינו נאמן להחמיר במילי דאבלות. וה\"ר ישעיה אומר דאין עובד כוכבים מסל\"ת נאמן אלא לעדות אשה או על פירותיו דשל ערלה הן אבל בכל עדיות דעלמא אין עובד כוכבים מסל\"ת נאמן בין להקל בין להחמיר ע\"כ תשובת אור זרוע. עכ\"ל:","\u0003שנים. \u0004 כ' הרמב\"ן זה הכלל כל עדות שמשיאים האשה על פיהם הקרובים מתאבלים. ועי' בא\"ע סי' י\"ז נתבאר עדות שמשיאים האשה על פיהם. וכ' הב\"ח היכא שכתבו לאחד שמת קרובו ואיכא ספק אם הוא תוך ל' חייב להתאבל דכל כמה דמצינן לאוקמיה אחזקתיה מוקמינן ואמרינן השתא מקרוב מת. מיהו היכא שהוא כתב יד של חכם אמרינן דמסתמא לאחר ל' הוא. דאם איתא שהיה אפשר שיגיע הכתב לידו תוך ל' לא היה כותב בסתם אלא היה מבאר. וכ\"כ בתשו' ר\"מ מינץ דצריך להתאבל מטעם חזקה כנ\"ל. וכ' דאם אירע שהורו דאין להתאבל מספק ואח\"כ נודע לו למפרע שמת תוך ל' צ\"ע אם יחזור ויתאבל או לא ע\"ש. ונ\"ל דצריך להתאבל בכה\"ג וע\"ל ר\"ס שצ\"ו ודוק עכ\"ל הש\"ך \u0005(ועי' בתשו' שזכרתי)\u0006 \u0005(ובנה\"כ הגיה דבריו שצ\"ל ול\"נ דאין צריך להתאבל וכו')\u0006 ובט\"ז פסק דהיכא דאיכא ספק אם הוא תוך ל' או לאו א\"צ להתאבל ע\"ש שמאריך בכמה ראיות להעמיד דבריו:"]],["אֲבֵלוּת יוֹם רִאשׁוֹן, אִם הוּא יוֹם מִיתָה וּקְבוּרָה, הָוֵי דְּאוֹרַיְתָא; וּשְׁאָר הַיָּמִים, מִדְּרַבָּנָן. בַּמֶּה דְּבָרִים אֲמוּרִים, \u0010c0\u0011 בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֲפִלוּ בְּיוֹם רִאשׁוֹן הֵם מִדְּרַבָּנָן. וְיֵשׁ אוֹמְרִים שֶׁאַף אֲבֵלוּת יוֹם רִאשׁוֹן דְּמִיתָה וּקְבוּרָה הָוֵי \u0010c1\u0011 דְּרַבָּנָן בְּכָל הַמֵּתִים.",[],["\u0003בשבעה. \u0004 שהם אביו ואמו בנו ובתו אחיו ואחותו בתולה ואשתו נשואה:","\u0003דרבנן. \u0004 והכי קי\"ל כמ\"ש בסי' שצ\"ט סי\"ג:"]],["הַקוֹבֵר מֵתוֹ קֹדֶם הָרֶגֶל, בְּעִנְיָן שֶׁחָל עָלָיו אֲבֵלוּת, וְנָהַג בּוֹ \u0010c0\u0011 אֲפִלוּ שָׁעָה אַחַת קֹדֶם הָרֶגֶל, מַפְסִיק הָאֲבֵלוּת וּמְבַטֵּל מִמֶּנּוּ גְזֵרַת שִׁבְעָה וִימֵי הָרֶגֶל עוֹלִים לוֹ לִמִנְיַן שְׁלֹשִׁים, הֲרֵי שִׁבְעָה לִפְנֵי הָרֶגֶל, וִימֵי הָרֶגֶל, וּמַשְׁלִים עֲלֵיהֶם הַשְּׁלֹשִׁים. וְדַוְקָא שֶׁנָּהַג אֲבֵלוּת בְּאוֹתָהּ שָׁעָה, אֲפִלוּ לֹא נָהַג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, כְּגוֹן שֶׁשָּׁמַע שְׁמוּעָה קְרוֹבָה בְּיוֹם שַׁבָּת שֶׁחָל לִהְיוֹת בְּעֶרֶב הָרֶגֶל, שֶׁאַף עַל פִּי שֶׁאֵינוֹ נוֹהֵג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, הָרֶגֶל מַפְסִיק. אָבֵל אִם שָׁגַג אוֹ הֵזִיד וְלֹא נָהַג אֲבֵלוּת, \u0005אוֹ\u0006 שֶׁהָיָה קָרוֹב לַחֲשֵׁכָה וְלֹא הָיָה יָכוֹל לִנְהֹג, אֵין הָרֶגֶל מְבַטֵּל הָאֲבֵלוּת; וְכָל שֶׁכֵּן אִם לֹא יָדַע בְּמִיתַת הַמֵּת קֹדֶם הָרֶגֶל, שֶׁאֵין הָרֶגֶל מְבַטְּלוֹ, אֶלָא נוֹהֵג בָּרֶגֶל דְּבָרִים שֶׁבְּצִנְעָא, וּמוֹנֶה שִׁבְעָה אַחַר הָרֶגֶל, וּבְאוֹתָהּ הַשִּׁבְעָה מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂים בְּצִנְעָה בְּתוֹךְ בֵּיתוֹ, דְּכֵיוָן דִּכְבָר נִתְבַּטֵּל בְּשִׁבְעַת יְמֵי הָרֶגֶל מִמְּלָאכָה, אַף עַל פִּי שֶׁלֹּא נִתְבַּטֵּל מֵחֲמַת הָאֵבֶל אֶלָא מֵחֲמַת הָרֶגֶל, סוֹף סוֹף נָהַג בְּדִין אֲבֵלוּת בְּעִנְיַן מְלָאכָה, הִלְכָּךְ אֵין לְהַחְמִיר בּוֹ כְּמוֹ בִּשְׁאָר אֲבֵלוּת וּמְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים. וְכָל יְמֵי הָרֶגֶל רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ, הִלְכָּךְ אֵין מִתְעַסְקִין בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל. וְרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁהֲרֵי דִּין שְׁלֹשִׁים דְּהַיְנוּ גִהוּץ וְתִסְפֹּרֶת נוֹהֲגִים בָּרֶגֶל, וְלֹא מִתּוֹרַת רֶגֶל בִּלְבַד אָסוּר בָּהֶם, אֶלָא אַף מִתּוֹרַת אֵבֶל, שֶׁהֲרֵי מִתּוֹרַת הָרֶגֶל \u0010c1\u0011 מֻתָּר לִלְבֹּשׁ כֵּלִים מְגֹהֲצִים חֲדָשִׁים וּלְבָנִים, וְנוֹטֵל \u0010c2\u0011 צִפָּרְנָיו בְּמִסְפָּרַיִם וְשָׂמֵחַ שִׂמְחַת מְרֵעוּת, וְהַבָּא מִמְּדִינַת הַיָּם וּמִבֵּית הַשִּׁבְיָה וְהַשְּׁאָר שֶׁמָּנוּ חֲכָמִים, מֻתָּרִין לְסַפֵּר וּלְכַבֵּס, וּמִדִּין אֲבֵלוּת אָסוּר בְּכֻלָם כְּמוֹ בַּחֹל.\nהַקוֹבֵר מֵתוֹ בָּרֶגֶל \u0010c3\u0011 בְּחֹל הַמּוֹעֵד, נֹהַג דִּין אֲנִינוּת כָּל זְמַן שֶׁלֹּא נִקְבַּר; וּלְאַחַר שֶׁנִּקְבַּר, נוֹהֵג דְּבָרִים שֶׁבְּצִנְעָא \u0005וּמִכָּל מָקוֹם מֻתָּר לְיַחֵד עִם אִשְׁתּוֹ (בֵּית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006 וְעַיֵּן לִעֵיל סִימָן שפ\"ג וּבְא\"ח סִימָן תקמ\"ח, וְהָרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁמַּשְׁלִים עָלָיו שְׁלֹשִׁים; אֲפִלוּ קְבָרוֹ בְּחַג הַסֻכּוֹת, לֹא אַמְרִינָן דִּשְׁמִינִי \u0010c4\u0011 עֲצֶרֶת מְבַטֵּל, וּמִתְעַסְקִים בָּרֶגֶל לְנַחֲמוֹ. \u0005הַגָּה: וְכָל מְלָאכָה הַמֻּתֶּרֶת לַעֲשׂוֹת לוֹ בַּמּוֹעֵד בְּדָבָר הָאָבֵד, מֻתָּר לַעֲשׂוֹת בְּעַצְמוֹ; וְאִם אֵין דָּבָר הָאָבֵד, נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂין בְּצִנְעָא תּוֹךְ בֵּיתוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006, וּלְאַחַר הָרֶגֶל מַתְחִיל לִמְנוֹת שִׁבְעָה, וְלִכְשֶׁיִּכְלוּ שִׁבְעָה לְמִיתַת הַמֵּת אַף עַל פִּי שֶׁעֲדַיִן לֹא כָּלוּ שִׁבְעַת יְמֵי הָאֲבֵלוּת, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו עוֹשִׂין לוֹ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ; וְאֵין רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל מִנְיַן הַיָּמִים שֶׁנִּחֲמוּהוּ בָּרֶגֶל, אֲבָל מַרְאִים לוֹ פָּנִים, כְּגוֹן אִם קְבָרוֹ בִּשְׁלֹשָׁה יָמִים הָאַחֲרוֹנִים שֶׁל רֶגֶל, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בִּשְׁלֹשָׁה יָמִים אַחֲרוֹנִים שֶׁל אֵבֶל, וּבִמְקוֹמוֹת שֶׁעוֹשִׂים שְׁנֵי יָמִים, מוֹנֶה הַשִּׁבְעָה מִיּוֹם טוֹב \u0010c5\u0011 שֵׁנִי הָאַחֲרוֹן, הוֹאִיל וּמִדִּבְרֵיהֶם הוּא עוֹלֶה מֵהַמִּנְיָן, וּמוֹנֶה מֵאַחֲרָיו שִׁשָּׁה יָמִים בִּלְבַד.\nאִם קָבַר אֶת מֵתוֹ שִׁבְעָה יָמִים קֹדֶם הָרֶגֶל, וְנָהַג בָּהֶם גְזֵרַת שִׁבְעָה, הָרֶגֶל מְבַטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים, אֲפִלוּ חָל יוֹם שְׁבִיעִי בְּעֶרֶב הָרֶגֶל, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ וְעוֹלֶה לְכָאן וּלְכָאן, וּמֻתָּר לְכַבֵּס וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב הָרֶגֶל. \u0005הַגָּה: סָמוּךְ לַחֲשֵׁכָה (טוּר)\u0006. וּבְעֶרֶב \u0010c6\u0011 פֶּסַח מֻתָּר בַּכֹּל אַחַר חֲצוֹת, דְּהַיְנוּ מִזְּמַן שְׁחִיטַת הַפֶּסַח וָאֵילָךְ; וְעָדִיף שֶׁיְּגַלֵּחַ קֹדֶם חֲצוֹת, הוֹאִיל וַאֲחֵרִים אֲסוּרִים לְגַלֵּחַ אַחַר חֲצוֹת \u0005(תְּשׁוּבַת ר\"י מִינְ\u0006 ץ \u0005ס\"ד)\u0006. וְכֵן אִם חָל שְׁמִינִי בְּשַׁבָּת שֶׁבְּעֶרֶב הָרֶגֶל, מֻתָּר לְכַבֵּס וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב שַׁבָּת, וְאִם לֹא גִלַח בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב שַׁבָּת, מֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, שֶׁכְּבָר נִתְבַּטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים. אֲבָל בְּחֹל הַמּוֹעֵד לֹא יְגַלַח, כֵּיוָן שֶׁהָיָה אֶפְשָׁר לוֹ לְגַלֵחַ קֹדֶם הָרֶגֶל. וְאִם חָל שְׁבִיעִי שֶׁלוֹ בְּשַׁבַּת עֶרֶב הָרֶגֶל, אָסוּר לְגַלֵחַ בְּעֶרֶב שַׁבָּת, וּמֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, וְכֵן בְּחֹל הַמּוֹעֵד, כֵּיוָן שֶׁלֹּא הָיָה יָכוֹל לְגַלֵחַ קֹדֶם הָרֶגֶל.\nהָא דְּרֶגֶל מְבַטֵּל גְזֵרַת שְׁלֹשִׁים, בִּשְׁאָר מֵתִים. אֲבָל בְּאָבִיו וְאִמּוֹ, שֶׁאָסוּר \u0005לְסַפֵּר\u0006 עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, אֲפִלוּ פָּגַע בּוֹ הָרֶגֶל לְאַחַר ל' יוֹם, אֵינוֹ מְבַטֵּל.\nאִם חָל אֶחָד מִיְּמֵי הָאֲבֵלוּת, חוּץ מֵהַשְּׁבִיעִי, בְּעֶרֶב הָרֶגֶל, \u0010c7\u0011 מֻתָּר לְכַבֵּס, וְלֹא יִלְבְּשֶׁנּוּ עַד הַלַיְלָה. וְטוֹב לִזָּהֵר מִלְכַבֵּס עַד אַחַר חֲצוֹת, כְּדֵי שֶׁיְּהֵא נִכָּר שֶׁמִּפְּנֵי הָרֶגֶל הוּא מְכַבֵּס. אֲבָל לִרְחֹץ, אָסוּר עַד הַלַיְלָה. וְיֵשׁ מַתִּירִין לִרְחֹץ אַחַר תְּפִלַת הַמִּנְחָה, סָמוּךְ לַחֲשֵׁכָה, \u0005וְכֵן \u0010c8\u0011 נוֹהֲגִין.\u0006\nרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים חֲשׁוּבִים כִּרְגָלִים לְבַטֵּל הָאֲבֵלוּת.\nנָהַג שָׁעָה אַחַת לִפְנֵי הַפֶּסַח, אוֹתָהּ שָׁעָה חֲשׁוּבָה כְּז', וְח' יְמֵי הַפֶּסַח הֲרֵי ט\"ו, וּמַשְׁלִים עֲלֵיהֶם ט\"ו אֲחֵרִים.\nשָׁעָה אַחַת לִפְנֵי עֲצֶרֶת חֲשׁוּבָה כְּשִׁבְעָה. וַעֲצֶרֶת, כֵּיוָן שֶׁאִם לֹא הִקְרִיב קָרְבָּנוֹת עֲצֶרֶת בַּעֲצֶרֶת יֵשׁ לוֹ תַּשְׁלוּמִין כָּל שִׁבְעָה, חָשׁוּב כְּשִׁבְעָה, הֲרֵי י\"ד, וּמַשְׁלִים עֲלֵיהֶם ט\"ז אֲחֵרִים; וְיוֹם שֵׁנִי שֶׁל עֲצֶרֶת עוֹלֶה לְמִנְיַן הַט\"ז.\nשָׁעָה אַחַת לִפְנֵי רֹאשׁ הַשָּׁנָה בָּטְלָה מִמֶּנּוּ גְזֵרַת שִׁבְעָה, מִפְּנֵי רֹאשׁ הַשָּׁנָה; וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ יוֹם כִּפּוּרִים; וּמְגַלֵחַ עֶרֶב יוֹם כִּפּוּרִים. וְהוּא הַדִּין לְקוֹבֵר מֵתוֹ בִּשְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁמְגַלֵחַ בְּעֶרֶב יוֹם הַכִּפּוּרִים.\nשָׁעָה אַחַת לִפְנֵי יוֹם הַכִּפּוּרִים בְּטֵלָה מִמֶּנּוּ גְזֵרַת ז' מִפְּנֵי יוֹם כִּפּוּרִים, וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ הֶחָג, וּמְגַלֵחַ בְּעֶרֶב הֶחָג.\nשָׁעָה אַחַת לִפְנָי הֶחָג וְהֶחָג, הֲרֵי י\"ד; וּשְׁמִינִי עֲצֶרֶת שִׁבְעָה, הֲרֵי כ\"א; וְיוֹם שֵׁנִי שֶׁל שְׁמִינִי עֲצֶרֶת, הֲרֵי \u0010c9\u0011 כ\"ב; וּמַשְׁלִים עֲלֵיהֶם ח' אֲחֵרִים.\nהַקוֹבֵר אֶת מֵתוֹ שָׁעָה אַחַת לִפְנֵי הָרֶגֶל, אוֹתָהּ שָׁעָה וְהָרֶגֶל חֲשׁוּבִים כְּי\"ד, וּמִיָּד אַחַר הָרֶגֶל יֵשׁ לוֹ דִּין שָׁבוּעַ שְׁלִישִׁי לְעִנְיָן שֶׁיּוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר.\nבִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יוֹם טוֹב, מִי שֶׁמֵּת לוֹ מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁהוּא יוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח אוֹ שֶׁל חַג, אוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁל עֲצֶרֶת, וּקְבָרוֹ בּוֹ בַּיּוֹם, נוֹהֵג בּוֹ אֲבֵלוּת, הוֹאִיל וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵיהֶם, וַאֲבֵלוּת יוֹם רִאשׁוֹן שֶׁהוּא יוֹם מִיתָה וּקְבוּרָה שֶׁל תּוֹרָה, יִדָּחֶה עֲשֵׂה שֶׁל דִּבְרֵיהֶם מִפְּנֵי עֲשֵׂה שֶׁל תּוֹרָה. אֲבָל אִם מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה, וְקָבְרוּ בּוֹ בַּיּוֹם, אֵינוֹ נוֹהֵג בּוֹ אֲבֵלוּת, שֶׁשְּׁנֵי הַיָּמִים כְּיוֹם אָרֹךְ הֵם. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֵין אֲבֵלוּתָם אֶלָא מִדְּרַבָּנָן, לְפִיכָךְ אֵינוֹ נוֹהֵג עֲלֵיהֶם אֲבֵלוּת בְּשׁוּם יוֹם טוֹב. וַאֲפִלוּ בְּאוֹתָם שֶׁאָמַרְנוּ שֶׁנּוֹהֵג אֲבֵלוּת בְּיוֹם טוֹב שֵׁנִי, אֵינוֹ קוֹרֵעַ. וְהָעוֹלָם נוֹהֲגִין שֶׁלֹּא לְהִתְאַבֵּל בְּיוֹם טוֹב שֵׁנִי שֶׁל גָלֻיּוֹת עַל שׁוּם מֵת, אֲפִלוּ הוּא יוֹם מִיתָה וּקְבוּרָה. \u0005הַגָּה: דְּסוֹבְרִין כְּדַעַת הָאוֹמְרִים שֶׁאֵין שׁוּם אֲבֵלוּת דְּאוֹרַיְתָא, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת (ר\"ת וְר\"י וְרֹא\"שׁ)\u0006.\nמֵת לוֹ מֵת בְּעֶרֶב יוֹם טוֹב, וְנִתְיָרֵא שֶׁמָּא לֹא יַסְפִּיק לְקָבְרוֹ מִבְּעוֹד יוֹם, \u0010c10\u0011 וּמְסָרוֹ לְעוֹבְדֵי כּוֹכָבִים שֶׁיּוֹלִיכוּהוּ לְקָבְרוֹ, כֵּיוָן שֶׁהוֹצִיאוּהוּ מֵהָעִיר וְנִתְכַּסָה מֵעֵינֵי הַקְרוֹבִים חָלָה עָלָיו אֲבֵלוּת; וְאִם הוּא שָׁעָה אַחַת קֹדֶם הָרֶגֶל, וְנָהַג בּוֹ אֲבֵלוּת, בָּטְלָה לָהּ גְזֵרַת שִׁבְעָה אַף עַל פִּי שֶׁנִּקְבַּר בְּיוֹם טוֹב.",[],["\u0003שעה. \u0004 פי' כל שהוא ולא בעינן שעה זמנית ואפילו חליצת מנעל לחוד שנהג מעט די בכך. וכ\"כ בתשו' מ\"ב. ט\"ז וש\"ך:","\u0003ללבוש. \u0004 כ' בתשו' מ\"ב שמעשה היה בחתן שנשא ערב הרגל ובתוך הרגל מת לו מת ופסק דאע\"ג דחתן דעלמא שאירע לו אבילות בתוך ז' ימי המשתה אינו מונה שלשים אלא אחר ימי המשתה מטעם דהוא עדיף מרגל דאיהו מותר בגיהוץ ותספורת משא\"כ חתן זה דימי משתה שלו הם ברגל ממילא אסור בגיהוץ וכו' מחמת הרגל הלכך עולה לו למנין שלשים וכתב הט\"ז דבעיניו יפלא מאד דברים הללו דע\"כ לא אמרו דעולה אלא כשיש איסור מחמת אבילותו אלא שאותו האיסור הוא גם כן מחמת הרגל בזה שייך שפיר דעולה כיון דעכ\"פ הוא נוהג איסור ויכול לומר אני נוהג האיסור מחמת האבילות. משא\"כ בחתן זה שאין בו חיוב אבילות כלל וזה שנוהג איסור הוא מחמת הרגל לחוד היאך יעלה על הדעת לומר שיהיה זה נחשב לימי השלשים. ע\"כ נראה דליתא להאי דינא אלא דימי הרגל אינם עולים לו כלל כמו בשאר חתן וכו' ע\"ש. והאי דימי הרגל עולים למנין שלשים שכתב המחבר כתב הש\"ך דהיינו אף בנודע לו מיתת המת ברגל אע\"פ שלא נודע לו קודם הרגל ודלא כמ\"ש בב\"י דבנודע לו קודם הרגל דוקא הוא דעולה ואולי גם הב\"י לאו דוקא קאמר או ט\"ס הוא וצ\"ל ברגל עכ\"ל:","\u0003צפרניו. \u0004 היינו לדעת המחבר בא\"ח סי' תקל\"ב אבל אנן קי\"ל להחמיר כמ\"ש הר\"ב שם וסתם כאן הדברים לפי שאין כאן מקום דיני מועד. ש\"ך:","\u0003המועד. \u0004 ה\"ה ביו\"ט שני או בי\"ט ראשון כשרוצה לקברו ע\"י עממים חל עליו אנינות כדלעיל סי' שמ\"א ס\"א ולאחר שיקבר כל אלו הדינים נוהגים בו עכ\"ל הש\"ך:","\u0003עצרת. \u0004 כתב הש\"ך ואין ש\"ע עולה רק ליום א' כשקברו ברגל ודוקא כשקברו קודם חג הסכות הוא דעולה ש\"ע ג\"כ לז' ימים \u0005(ועי' לקמן סעיף י\"א)\u0006 משא\"כ הכא. ודלא כמהרש\"ל בתשו' שכ' דמבטל הוא דאינו מבטל אבל למנין ז' לענין הל' עולה ש\"ע אפילו קברו ברגל. מיהו בתשובת משאת בנימין פסק כמהרש\"ל וכן נראה דעת הדרישה עכ\"ל. גם הט\"ז מאריך בראיות לסתור דברי מהרש\"ל ותשובת מ\"ב הנ\"ל ע\"ש:","\u0003שני. \u0004 כ' הב\"ח וה\"ה אם מת ביו\"ט ראשון של ר\"ה מונה השבעה מיו\"ט הב' דהוי ג\"כ מדבריהם. ע\"ש בס\"ס זה \u0005(וכ\"כ בתשו' גינת ורדים כלל ה' וכ\"כ בתשו' תורת חיים סי' י\"א)\u0006:","\u0003פסח. \u0004 כתב הש\"ך דדין זה הוציא הרב מתשו' מהר\"י מינץ וצ\"ע דאדרבה משם משמע דלענין כבוס ורחיצה ע\"פ שוה לשאר עיו\"ט דלא הותר רק סמוך לחשכה אך שכתב שם דבע\"פ יש לגלח קודם חצות הואיל ואחרים ג\"כ אסורים לגלח אחר חצות מפני שהוא זמן שחיטת הפסח וכמ\"ש בא\"ח סי' תקמ\"ח ע\"ש וצ\"ע. עכ\"ל:","\u0003לכבס. \u0004 דכבר בטל ממנו גזירת ז' אבל לספר אסור דלא נתבטל ממנו גזירת ל' כיון דאין כאן ז' ימים קודם הרגל. ש\"ך:","\u0003נוהגין. \u0004 וכתב בת\"ה דאפילו מת לו מת בע\"ש ואותו שבת הוא ערב הרגל מותר לרחוץ בע\"ש לפי מנהגינו. וא\"ל היאך כתב הרב וכן נוהגין הא לעיל ר\"ס שפ\"א כ' דאנן נהגינן איסור רחיצה כל ל' וכן בר\"ס שפ\"ט כתב דנהגינן איסור כביסה כל ל' י\"ל דאינו אלא חומרא ומדינא שרי והכא משום כבוד הרגל לא נהגו להחמיר וכ\"כ הלבוש ואע\"ג דבא\"ח סי' תקמ\"ח ס\"ח וס\"י כתב הרב דלדידן דנוהגים איסור רחיצה כל ל' אסור לרחוץ דהא הרגל לא בטל ממנו רק גזירת ז' וה\"ה לענין כבוס במקום דנוהגין איסור כבוס כל ל' ע\"כ היינו משום דכך ראוי להורות אי הוי איסור רחיצה וכבוס כל ל' מן הדין אבל כאן כתב דמ\"מ המנהג אינו כן וכ\"כ הב\"ח אלא דצריך ליישב לאיזה צורך כתב הרב שם כן כיון דס\"ס המנהג אינו כך. ונ\"ל דס\"ל דהא דמנהג אינו כן היינו משום כבוד הרגל והלכך היכא דליכא משום כבוד הרגל אסור ונ\"מ דלאחר הרגל אסור רחיצה וכביסה עד ל' דהרגל לא ביטל ממנו רק גזרת ז' ודוק עכ\"ל הש\"ך:","\u0003כ\"ב. \u0004 כתב הט\"ז קשה ליחשב ש\"ע כרגל בפני עצמו גם לענין ביטול שלשים כיון דנתבטל השבעה קודם החג והחג נחשב לשבעה הרי י\"ד כמו דאמרי' בי\"כ בס\"י. תירץ הרא\"ש דשאני הכא שלא נהג דין ל' כלל ואע\"ג שנהג גיהוץ ותספורת מ\"מ הרי בלאו אבילות נמי אסור באלו מחמת הרגל וצ\"ע לתרץ זה אליבא דהרמב\"ן דס\"ל דיש באבלות איסור נוסף על איסור הרגל א\"כ קשה למה לא יבטל ש\"ע גזרת ל' כיון שכבר נהג בדין ל' בתוספת האיסור. ונראה דמ\"מ יש שינוי משאר ל' בחול דהתם יש היכר בעיקר דין גיהוץ ותספורת משא\"כ כאן שאין היכר אלא בתוספת וזה אין הוכחה כ\"כ לכך די בזה שנאמר הרגל עולה למנין הל' אבל לא להיות כנהג מקצת שלשים ממש לענין שש\"ע יבטל לגמרי שאר הל' עכ\"ל:","\u0003ומסרו. \u0004 כתב הט\"ז ראיתי להזכיר פה מה שראיתי בקצת מקומות כשקוברין מת ביו\"ט ראשון ע\"י עממים באים ישראלים ומחזירים העפר לתוך הקבר על המת עד זיבולא בתרייתא והוא איסור גמור בעיני דהרי מלאכה גמורה היא ויש בזה משום בונה ופשיטא דאסור ע\"י ישראל. ע\"כ יש ליזהר בזה לעשות ע\"י עובדי כוכבים על כל צרה שלא תבוא עכ\"ל:"]],["שַׁבָּת אֵינוֹ מַפְסִיק אֲבֵלוּת וְעוֹלֶה לְמִנְיַן שִׁבְעָה, שֶׁהֲרֵי קְצָת דִּינֵי אֲבֵלוּת נוֹהֲגִים בּוֹ, דְּהַיְנוּ דְּבָרִים שֶׁבְּצִנְעָא שֶׁהֵם: תַּשְׁמִישׁ הַמִּטָּה וּרְחִיצָה. אֲבָל דְּבָרִים שֶׁבְּפַרְהֶסְיָא \u0005לֹא,\u0006 דְּהַיְנוּ לְהָסִיר עֲטִיפָתוֹ, \u0005וְדַוְקָא כְּשֶׁהוּא מְעֻטָּף עֲטִיפוֹת יִשְׁמְעֵאלִים כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ו, אֲבָל קְצָת עֲטִיפָה שֶׁנּוֹהֲגִים בִּקְצָת מְקוֹמוֹת כָּל ל', אֵין צָרִיךְ לְהָסִיר בְּשַׁבָּת, הוֹאִיל וְיֵשׁ לוֹ \u0010c0\u0011 מִנְעָלִים בְּרַגְלָיו (מהרי\"ו סִימָן ה')\u0006, וְלִלְבֹּשׁ מִנְעָלָיו, וְלִזְקֹף הַמִּטָּה מִכְּפִיָּתָהּ, וְשֶׁלֹּא לִלְבֹּשׁ בֶּגֶד קָרוּעַ, אֶלָא מַחֲלִיפוֹ, וְאִם אֵין לוֹ לְהַחֲלִיף \u0010c1\u0011 מַחֲזִיר קִרְעוֹ לְאַחֲרָיו; וְתַלְמוּד תּוֹרָה הָוֵי דָּבָר שֶׁבְּצִנְעָא, אֲבָל \u0010c2\u0011 לַחֲזֹר הַפָּרָשָׁה, כֵּיוָן שֶׁחַיָּב אָדָם לְהַשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר, הָוֵי כְּקוֹרֵא אֶת שְׁמַע וּמֻתָּר. וְאִם קָרְאוּ אֶת הָאָבֵל לַעֲלוֹת לַתּוֹרָה, צָרִיךְ לַעֲלוֹת, שֶׁאִם הָיָה נִמְנָע הָיָה דָּבָר שֶׁל פַּרְהֶסְיָא; וְרַבֵּנוּ תָּם הָיוּ קוֹרִים אוֹתוֹ בְּכָל פַּעַם שְׁלִישִׁי, וְאֵרַע בּוֹ אֲבֵלוּת וְלֹא קְרָאוֹ הַחַזָּן, וְעָלָה הוּא מֵעַצְמוֹ וְאָמַר כֵּיוָן שֶׁהֻרְגַל לִקְרוֹתוֹ שְׁלִישִׁי בְּכָל שַׁבָּת, הָרוֹאָה שֶׁאֵינוֹ עוֹלֶה אוֹמֵר שֶׁבִּשְׁבִיל אֲבֵלוּת הוּא נִמְנָע, וְהָוֵי דְּבָרִים שֶׁל פַּרְהֶסְיָא. \u0005וְכֵן אִם הַכֹּהֵן אָבֵל וְאֵין כֹּהֵן אַחֵר בְּבֵית הַכְּנֶסֶת, מֻתָּר לִקְרוֹתוֹ; אֲבָל בְּעִנְיָן אַחֵר, אָסוּר (הַגָּהוֹת מַיְמוֹנִי פ\"ג מה\"א)\u0006.\nגְרָרַתּוּ חַיָּה אוֹ הֲרָגוּהוּ לִסְטִים, וּבְשַׁבָּת נִתְיָאֵשׁ מִלְבַקֵשׁ, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג בְּשַׁבָּת עוֹלֶה לוֹ לְיוֹם אֶחָד. \u0005הַגָּה: אִם פָּגַע יוֹם ל' שֶׁל אֲבֵלוּת בְּשַׁבָּת וְיוֹם כ\"ט בְּעֶרֶב שַׁבָּת, מֻתָּר לוֹ לִרְחֹץ בְּעֶרֶב שַׁבָּת, אַף בִּמְקוֹמוֹת שֶׁנּוֹהֲגִין שֶׁלֹּא לִרְחֹץ כָּל שְׁלֹשִׁים, דְּהוֹאִיל וּמִדִּינָא שָׁרֵי לְאַחַר שִׁבְעָה, אֶלָּא שֶׁנָּהֲגוּ לְהַחְמִיר כָּל ל', בִּכְהַאי גַּוְנָא שָׁרֵי מִשּׁוּם כְּבוֹד שַׁבָּת (הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם מַהֲרַ\"ם פ\"י ופ\"ו דְּיוֹם טוֹב)\u0006. וְהוּא הַדִּין כָּל כַּיּוֹצֵא בָּזֶה, כְּגוֹן לַחֲזֹר עַל מְקוֹמוֹ בְּלֵיל שַׁבָּת וְלִלְבֹּשׁ בִּגְדֵי שַׁבָּת, דְּהָא נָמִי אֵינוֹ אֶלָּא מִנְהָג בְּעָלְמָא \u0005(כֵּן נִרְאֶה מִדִּבְרֵי מַהַרַ\"שׁ)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִי' שפ\"ט וש\"צ; וְאַף עַל פִּי שֶׁיֵּשׁ לְחַלֵּק בֵּין רְחִיצָה שֶׁאֲסוּרָה בְּשַׁבָּת וּבֵין דְּבָרִים אֵלּוּ שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹת בְּשַׁבָּת, מִכָּל מָקוֹם אֵין נ\"ל לְחַלֵּק בְּכָךְ.",[],["\u0003מנעלים. \u0004 כתב הש\"ך לא ידעתי מה ענין מנעלים ברגליו לכאן דמאן דמתיר משום מנעלים ברגליו מתיר אפילו בעטיפת ישמעאלים וכ\"מ בש\"ס וברמב\"ן. ובאמת במהרי\"ו כתב דהכא מותר מטעם כיון שנוהגים בעטיפה זו גם אחר ז' ימי אבלות דלא אסרינן דבר שבפרהסיא אלא מה שאינו רק תוך ז' ואח\"כ כתב דמותר ג\"כ מטעמא דמנעלים ברגליו ע\"ש. ובלבוש השמיט האי סיומא דהואיל ויש מנעלים ברגליו עכ\"ל:","\u0003מחזיר. \u0004 כתב הש\"ך והאידנא לא נהגו לדקדק בזה. ואפשר דהמנעלים מוכיחים עליהם כמ\"ש הב\"י דהיכא דהמנעלים ברגליו א\"צ לחזרת קרע ע\"ש עכ\"ל:","\u0003הפרשה. \u0004 כתב בדרישה בשם מהרש\"ל דה\"ה לחזור שנים מקרא ואחד תרגום מותר ע\"ש:"]],["אֵין מַנִּיחִין אֶת הַמִּטָּה בָּרְחוֹב בְּחֹל הַמּוֹעֵד, שֶׁלֹּא לְהַרְגִיל אֶת הַהֶסְפֵּד, שֶׁאָסוּר לְהַרְגִיל אֶת הַהֶסְפֵּד בְּחֹל הַמּוֹעֵד, אֶלָא לִכְבוֹד תַּלְמִיד חָכָם; לְפִיכָךְ אֵין מוֹלִיכִין הַמֵּת לְבֵית הַקְבָרוֹת בְּחֹל הַמּוֹעֵד, עַד שֶׁיִּהְיֶה כָּל הַקֶבֶר מְתֻקָן וּמְזֻמָּן.\nאֵין קוֹרְעִין בְּחֹל הַמּוֹעֵד אֶלָא מִי שֶׁהוּא חַיָּב לִקְרֹעַ כִּדְאִיתָא בְּסִימָן ש\"מ, אֲבָל מִי שֶׁאֵינוֹ חַיָּב, וְרוֹצֶה לִקְרֹעַ מִפְּנֵי הַכָּבוֹד, אָסוּר.\nשָׁמַע בְּחֹל הַמּוֹעֵד שְׁמוּעָה קְרוֹבָה, חַיָּב לִקְרֹעַ.\nאֵין חוֹלְצִין כָּתֵף בַּמּוֹעֵד, וְאֵין מַבְרִין בּוֹ אֶלָא קְרוֹבָיו שֶׁל מֵת; אֲבָל הַקְרוֹבִים, מַבְרִין. וְהוּא הַדִּין לַחֲנֻכָּה וּפוּרִים וְרֹאשׁ חֹדֶשׁ. וּכְשֶׁמַּבְרִין, אֵין מַבְרִין אֶלָא עַל מִטּוֹת זְקוּפוֹת, אֲבָל בְּיוֹם טוֹב, אֲפִלוּ בְּיוֹם טוֹב שֵׁנִי, אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַבְרִין; וּבְחֹל הַמּוֹעֵד מַבְרִין הַכֹּל עַל הֶחָכָם לְתוֹךְ הָרְחוֹב, כְּדֶרֶךְ שֶׁמַּבְרִין אֶת הַקְרוֹבִים, שֶׁהַכֹּל כִּקְרוֹבָיו.\nנָשִׁים בְּחֹל הַמּוֹעֵד מְעַנּוֹת, דְּהַיְנוּ שֶׁכֻּלָן עוֹנוֹת כְּאַחַת; אֲבָל לֹא מְטַפְּחוֹת, דְּהַיְנוּ לְהַכּוֹת כַּף עַל כַּף. בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְטַפְּחוֹת, אֲבָל לֹא מְקוֹנְנוֹת, דְּהַיְנוּ שֶׁאַחַת מְדַבֶּרֶת וְכֻלָן עוֹנוֹת אַחֲרֶיהָ. נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְטַפְּחוֹת; וְהָנֵי מִלֵי לְאִינַשׁ דְּעַלְמָא, אֲבָל לְתַלְמִיד חָכָם, בֵּין בְּחֹל הַמּוֹעֵד בֵּין בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְקוֹנְנוֹת כְּדַרְכָּן בַּחֹל; וְהָנֵי מִלֵי בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו, לֹא. וְיוֹם שְׁמוּעָה, אֲפִלוּ רְחוֹקָה, כִּבְפָנָיו דְּמֵי.\nאוֹמְרִים עַל הַמֵּת צִדּוּק הַדִּין וְקַדִּישׁ, כְּדַרְכָּן. וְכֵן בְּיוֹם טוֹב שֵׁנִי; אֲבָל בְּיוֹם טוֹב רִאשׁוֹן, כֵּיוָן שֶׁאֵין מִתְעַסְקִים בַּמֵּת אֵין אוֹמְרִים אוֹתוֹ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין שֶׁלֹּא לוֹמַר צִדּוּק הַדִּין בַּמּוֹעֵד (הַטּוּר הֵבִיא כַּמָּה רַבְּוָתָא)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט בִּמְדִינוֹת אֵלּוּ שֶׁלֹּא לוֹמַר צִדּוּק הדִּין בְּכָל הַיָּמִים שֶׁאֵין אוֹמְרִים בָּהֶם תַּחֲנוּן \u0005(בְּמִנְהָגִים)\u0006 ; וְלָכֵן אֵין אוֹמְרִים גַּם כֵּן כְּשֶׁקּוֹבְרִין אַחַר חֲצוֹת \u0010c0\u0011 בְּעֶרֶב שַׁבָּת. יֵשׁ אוֹמְרִים שֶׁאִם קוֹבְרִים הַמֵּת בַּלַּיְלָה, שֶׁאֵין אוֹמְרִים קַדִּישׁ וְלֹא צִדּוּק הדִּין \u0005(כָּל בּוֹ)\u0006.\nמֵת לוֹ מֵת קֹדֶם פּוּרִים, וּפָגַע בּוֹ פּוּרִים, אֵינוֹ מַפְסִיק הָאֲבֵלוּת; וּמִכָּל מָקוֹם אֵין אֲבֵלוּת \u0010c1\u0011 נוֹהֵג בּוֹ, לֹא בְּי\"ד וְלֹא בְּט\"ו, אֶלָא דְּבָרִים שֶׁבְּצִנְעָא נוֹהֵג, וְחַיָּב לִשְׁלֹחַ מָנוֹת. וְאַף עַל פִּי שֶׁאֵינוֹ מִתְאַבֵּל בָּהֶם, עוֹלִים לוֹ מִמִּנְיַן הַשִּׁבְעָה, כְּמוֹ שַׁבָּת.",[],["\u0003בע\"ש. \u0004 \u0005(אע\"פ שבערב)\u0006 [אבל בערב] ר\"ח וערב חנוכה אומרים אפי' לאחר חצות \u0005(לא)\u0006 [דלא] עדיפי מע\"ש כ\"כ הלבוש ומשמע דה\"ה שאין אומרים ג\"כ בערב יו\"ט אחר חצות. ש\"ך:","\u0003נוהג. \u0004 ומהרש\"ל פסק דצריך לנהוג כל דיני אבילות ושכן המנהג וכ\"כ המחבר בא\"ח סי' תרצ\"ו ס\"ד. ובדרישה כתב ליישב דברי המחבר דלא סתרי אהדדי דבא\"ח מיירי שמת לו מת בו ביום וכאן מיירי שמת קודם לכן ודוחק \u0005(ויש רוצים להגיה בא\"ח דהאי בחנוכה צ\"ל בצינעא. וה\"ק כל דברי אבלות בצינעא נוהגים בפורים. ובזה מיושב מה שמזכיר שם חנוכה בהלכות פורים וה\"ל להביאו בהלכות חנוכה סי' ת\"ע ששם מזכיר דיני חנוכה בהספד אלא ודאי שט\"ס הוא וצ\"ל בצינעא)\u0006 והרב בהג\"ה שם פסק כהמחבר כאן וכתב שכן נוהגין והב\"ח לא הביא אלא דברי מהרש\"ל ע\"ש. עכ\"ל הש\"ך:"]],["מִי שֶׁבָּאָה לוֹ שְׁמוּעָה שֶׁמֵּת לוֹ קָרוֹב, אִם בְּתוֹךְ ל' יוֹם הִגִיעָה הַשְּׁמוּעָה, אֲפִלוּ יוֹם ל' עַצְמוֹ, הֲרֵי זוֹ שְׁמוּעָה קְרוֹבָה וְחַיָּב לִנְהֹג שִׁבְעָה יְמֵי אֲבֵלוּת מִיּוֹם שֶׁהִגִיעַ הַשְּׁמוּעָה; וְקוֹרֵעַ וּמוֹנֶה ל' יוֹם \u0005מִיּוֹם הַשְּׁמוּעָה (כָּךְ מַשְׁמָע מֵהַרַמְבַּ\"ם וּמִנִּמּוּקֵי יוֹסֵף פא\"מ וּבְמָרְדְּכַי)\u0006 לְתִסְפֹּרֶת עִם שְׁאָר דְּבָרִים. \u0010c0\u0011 כְּלָלוֹ שֶׁל דָּבָר, יוֹם שְׁמוּעָתוֹ הַקְרוֹבָה כְּיוֹם הַקְבוּרָה. וְאִם שָׁמַע מִיּוֹם ל' וָאֵילָךְ, אֵין צָרִיךְ לִנְהֹג אֶלָא שָׁעָה אַחַת, לֹא שְׁנָא שָׁמַע בַּיּוֹם לֹא שְׁנָא שָׁמַע בַּלַיְלָה, שֶׁאִם שָׁמַע בַּלַיְלָה וְנָהַג מִקְצָת אֲבֵלוּת בַּלַיְלָה שָׁעָה אַחַת, עוֹלֶה לוֹ; וַאֲפִלוּ שָׁמַע עַל אָבִיו וְאִמּוֹ. וְהָנֵי מִלֵי לְעִנְיַן גְזֵרַת שִׁבְעָה, אֲבָל לְעִנְיַן גְזֵרַת שְׁלֹשִׁים, נוֹהֵג עַל אָבִיו וְאִמּוֹ בְּתִסְפֹּרֶת עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, וּבְגִהוּץ עַד שֶׁיַּגִיעַ הָרֶגֶל וְיִגְעֲרוּ בּוֹ, וְכֵן בִּשְׁאֵלַת שָׁלוֹם וְלִכָּנֵס לְבֵית הַמִּשְׁתֶּה; וּמוֹנֶה מִיּוֹם מִיתָה וְלֹא מִיּוֹם שְׁמוּעָה. לְפִיכָךְ אִם בָּאָה לוֹ שְׁמוּעָה עַל אָבִיו וְאִמּוֹ לְאַחַר י\"ב חֹדֶשׁ, אֵינוֹ נוֹהֵג אֶלָא יוֹם אֶחָד אַף בִּגְזֵרַת ל'.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה, אֵין צָרִיךְ לִנְהֹג כָּל דִּין אֲבֵלוּת, אֶלָא דַּיּוֹ בַּחֲלִיצַת מִנְעָל, וְאֵין צָרִיךְ לֹא עֲטִיפָה וְלֹא כְּפִיַּת הַמִּטָּה, וּמֻתָּר בִּמְלָאכָה, רְחִיצָה וְסִיכָה וְתַשְׁמִישׁ הַמִּטָּה וּבְתַלְמוּד תּוֹרָה, וְאִם אֵין לוֹ מִנְעָלִים בְּרַגְלָיו צָרִיךְ שֶׁיִּכְפֶה מִטָּתוֹ אוֹ יַעֲטֹף רֹאשׁוֹ, שֶׁצָּרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר בּוֹ שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת; וְאִם הָיָה עוֹסֵק בַּתּוֹרָה אוֹ בִּמְלָאכָה, אוֹ שֶׁהָיָה רוֹחֵץ וְסָךְ, וּבָאָה לוֹ שְׁמוּעָה, מַפְסִיק שָׁעָה אַחַת מִשּׁוּם אֲבֵלוּת, וְחוֹזֵר לְמַה שֶּׁבְּיָדוֹ, אֲבָל אִם הָיָה לָבוּשׁ תְּפִלִין, אֵינוֹ צָרִיךְ \u0010c1\u0011 לְחָלְצָן, וּמִכָּל מָקוֹם אֵינוֹ יוֹצֵא יְדֵי אֲבֵלוּת בְּהֶפְסֵק זֶה, וְצָרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת, כְּגוֹן חֲלִיצַת מִנְעָל אוֹ כְּפִיַּת הַמִּטָּה וַעֲטִיפָה; וּמִיהוּ בְּחָדָא סָגֵי.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nאֵין קוֹרְעִין עַל שְׁמוּעָה רְחוֹקָה; וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ לְעוֹלָם. \u0005וּבְמָקוֹם שֶׁאֵין לוֹ לִקְרֹעַ, אָסוּר \u0010c2\u0011 לְהַחְמִיר עַל עַצְמוֹ וְלִקְרֹעַ (אוֹר זָרוּעַ)\u0006.\nהַשּׁוֹמֵעַ שְׁמוּעָה בְּשַׁבָּת אוֹ בָּרֶגֶל, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נַעֲשֵׂית רְחוֹקָה, אֵינוֹ נוֹהֵג אֶלָא יוֹם \u0010c3\u0011 אֶחָד, וּבְשַׁבָּת וְרֶגֶל אָסוּר בִּדְבָרִים שֶׁל צִנְעָא.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה בְּשַׁבָּת אוֹ בָּרֶגֶל, אֵינוֹ נוֹהֵג אֲפִלוּ דְּבָרִים שֶׁבְּצִנְעָא, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נוֹהֵג שָׁעָה אַחַת, וְדַיּוֹ.\nהַשּׁוֹמֵעַ שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת הַשַּׁבָּת \u0010c4\u0011 עוֹלָה לוֹ לְיוֹם אֶחָד, וּלְמָחָר קוֹרֵעַ, וַהֲוָה לֵיהּ יוֹם שִׁשִּׁי שְׁבִיעִי לַאֲבֵלוּת.\nעֲשָׂרָה יָמִים אַחַר חַג הַסֻכּוֹת שָׁמַע שֶׁמֵּת לוֹ מֵת בְּעֶרֶב הֶחָג, אַף עַל פִּי שֶׁאִם נִמְנֶה שָׁעָה אַחַת לִפְנֵי הֶחָג ז' וְשִׁבְעַת יְמֵי הֶחָג וְיוֹם שְׁמִינִי עֲצֶרֶת כ\"א, וַעֲשָׂרָה יָמִים אֲחֵרִים הֲרֵי ל\"א, אֵין לָזֶה דִּין שְׁמוּעָה רְחוֹקָה, אֶלָא דִּין שְׁמוּעָה \u0010c5\u0011 קְרוֹבָה, שֶׁאֵין הָרֶגֶל עוֹלֶה לְמִי שֶׁלֹּא נָהַג אֲבֵלוּת קֹדֶם לוֹ כְּלָל; וְכָל שֶׁכֵּן לְמִי שֶׁלֹּא הָיָה יוֹדֵעַ שֶׁמֵּת לוֹ מֵת \u0005(ר' יְרוּחָם בְּשֵׁם בַּעַל הַמָּאוֹר וְכ\"ד הָרַמְבַּ\"ן)\u0006.\nשָׁמַע שְׁתֵּי שְׁמוּעוֹת רְחוֹקוֹת בְּיוֹם אֶחָד, אֵינוֹ נוֹהֵג עֲלֵיהֶן אֶלָא יוֹם אֶחָד. הָיוּ קְרוֹבוֹת, אוֹ שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, מוֹנֶה לִשְׁתֵּיהֶם כְּאֶחָד שִׁבְעָה וּשְׁלֹשִׁים. שָׁמַע לְזֶה הַיּוֹם וְלָזֶה \u0010c6\u0011 לְמָחָר, מוֹנֶה לַשֵּׁנִי מִיּוֹם שְׁמוּעָה, שִׁבְעָה וּשְׁלֹשִׁים.\nשָׁמַע שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת עֶרֶב הָרֶגֶל, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג, עוֹלֶה לוֹ אוֹתוֹ שַׁבָּת \u0010c7\u0011 לִמִנְיַן שִׁבְעָה.\nמִי שֶׁהִתְפַּלֵל כְּבַר עַרְבִית וַעֲדַיִן יוֹם הוּא, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, מוֹנֶה מִיּוֹם \u0010c8\u0011 מָחָר, וְאוֹתוֹ יוֹם אֵינוֹ עוֹלֶה לוֹ.\nמִי שֶׁמֵּת לוֹ מֵת וְלא נוֹדַע לוֹ, אֵינוֹ חוֹבָה שֶׁיֹאמְרוּ לוֹ; וַאֲפִלוּ בְּאָבִיו וְאִמּוֹ; וְעַל זֶה נֶאֱמַר: מוֹצִיא דִּבָּה הוּא כְּסִיל \u0005(מִשְׁלֵי י, יח)\u0006 וּמֻתָּר לְהַזְמִינוֹ לִסְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין וְכָל שִׂמְחָה, כֵּיוָן שֶׁאֵינוֹ יוֹדֵעַ. מִיהוּ אִם שׁוֹאֵל עָלָיו, אֵין לוֹ \u0010c9\u0011 לְשַׁקֵר וְלוֹמַר: חַי הוּא, שֶׁנֶּאֱמַר: מִדְּבַר שֶׁקֶר תִּרְחָק \u0005(שְׁמוֹת כג, ז)\u0006. \u0005הַגָּה: וּמִכָּל מָקוֹם בְּבָנִים זְכָרִים, נָהֲגוּ לְהוֹדִיעַ, כְּדֵי שֶׁיֹּאמְרוּ קַדִּישׁ; אֲבָל בְּבָנוֹת, אֵין מִנְהָג כְּלָל לְהוֹדִיעָם\u0006 \u0005(מהרי\"ו סי' י\"ג)\u0006. \u0005מִצְוָה לְהִתְעַנּוֹת יוֹם שֶׁמֵּת בּוֹ אָבִיו אוֹ אִמּוֹ\u0006 \u0005(כָּל בּוֹ בְּשֵׁם הר\"מ וְעוֹד פּוֹסְקִים)\u0006, \u0005וּמִתְעַנִּין יוֹם הַמִּיתָה וְלֹא יוֹם הַקְּבוּרָה\u0006 \u0005(מהרי\"ו סִימָן קכ\"א ומהרא\"י סִימָן רצ\"ו וְהָאַחֲרוֹנִים)\u0006, \u0005אִם לֹא מִי שֶׁהָיָה \u0010c10\u0011 אֵצֶל הַקְּבוּרָה וְלֹא אֵצֶל הַמִּיתָה.\u0006 \u0005(בְּקַבָּלָה מִפִּי זָקֵן מֻפְלָג מַהֲרַ\"ם לַנְדֹּא)\u0006 ; \u0005וְאִם אֵרַע יוֹם זֶה בְּיוֹם שֶׁאֵין אוֹמְרִים בּוֹ תַּחֲנוּן, אֵין מִתְעַנִּין כְּלָל. וְאִם מֵתוּ בַּאֲדָר וְנִתְעַבְּרָה הַשָּׁנָה, הָעִקָּר לְהִתְעַנּוֹת בָּאֲדָר \u0010c11\u0011 הָרִאשׁוֹן\u0006 \u0005(ת\"ה סִימָן רצ\"ד ומהר\"י מִינְ ץ)\u0006, אַף עַל פִּי שֶׁיֵּשׁ חוֹלְקִין, כָּךְ הוּא עִקָּר. וְאִם מֵתוּ בִּשְׁנַת הָעִבּוּר בָּאֲדָר הַשֵּׁנִי, מִתְעַנֶּה גַּם כֵּן בְּעִבּוּר בָּאֲדָר \u0010c12\u0011 הַשֵּׁנִי \u0005(ג\"ז שָׁם)\u0006. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תקס\"ח סָעִיף ז'. וְעַיֵּן לְעֵיל סִימָן שצ\"א שֶׁאֵין לֶאֱכֹל בִּסְעֻדָּה בְּלֵיל יוֹם שֶׁמֵּת בּוֹ אָב וָאֵם. וְאִם חָל תַּעֲנִית זֶה בְּעֶרֶב שַׁבָּת, דִּינוֹ כִּשְׁאָר תַּעֲנִית. וְעַיֵּן בא\"ח סִימָן רמ\"ט. מִיהוּ אִם בְּפַעַם רִאשׁוֹן הִשְׁלִים, יִנְהֹג כֵּן כָּל יָמָיו.\u0006",[],["\u0003כללו. \u0004 כתב הט\"ז דמבואר בב\"י בשם הרמב\"ן דביום שמועה קרובה לא יניח תפילין כמו ביום הקבורה עכ\"ל:","\u0003לחלצן. \u0004 לפי שאף בשעת אבילות מניח תפילין ואינו חולצן אלא ביום ראשון בלבד. ולא תהא שמועה רחוקה חמורה מיום ב' של אבילות קרובה עכ\"ל הרמב\"ן. ש\"ך:","\u0003להחמיר. \u0004 משום \u0005(בל תשחית)\u0006 אם לא על אביו ואמו או אדם גדול שהיה רגיל להקשות לו בדבר הלכה דהוי מיסתפי מיניה אם בא לעשות מילתא יתירה לכבודו מותר. כ\"כ הב\"ח בסי' ש\"מ סכ\"ה בשם א\"ז. עכ\"ל הש\"ך:","\u0003אחד. \u0004 ר\"ל שעה א' אבל אם שמע שמועה בשבת שהוא כ\"ט אז נוהג לאחר השבת שבעה ושלשים. מהרש\"ל. וטעם בזה שאינו נוהג אבילות אחר השבת אע\"ג דהתחיל ביום השבת והוא ביום השלשים דכיון שאינו מתאבל אבילות גמור באותו שבת רק בדברים שבצנעא ע\"כ אין גזרת אבילות אחריו כ\"כ הב\"י בשם הרשב\"א. וכתב הרמב\"ן דבאותו שבת ורגל אסור בדבר שבצנעא כל אותו יום ולא אמרינן בזה מקצתו ככולו כיון שיש עליו חוב ליום שאחריו שעה א' היאך נאמר שיפסיק האבילות ויחזור לו עכ\"ל הט\"ז. ובש\"ך כתב דמכאן פסק הב\"ח דאם חל יום הז' של אבילות בשבת דצריך לישב על הארץ במוצאי שבת ולנהוג אבילות שעה אחת דהא הכא אע\"ג דדברים שבצנעא נוהג בשבת לא נפטר בזה וצריך לעשות במו\"ש מעשה שניכר בו משום אבילות עכ\"ד. ולפע\"ד ל\"ד כלל דהכא כיון שחכמים חייבו לנהוג אבילות כראוי עכ\"פ שעה א' וביום השבת אין נוהגין אבילות רק במקצת א\"כ מעולם לא נהג זה דין אבילות כראוי אפילו שעה א' לכן חייב למוצאי שבת או למוצאי הרגל לנהוג אבילות שעה א' אבל מי שנהג אבילות ז' ימים ובתוך הז' חל יום השבת למה יתחייב באבילות במו\"ש ואפילו זלזל במקצת הימים ולא נהג אבילות קי\"ל לעיל סי' שצ\"ו דא\"צ להשלים וכ\"ש יום השבת דנהג אבילות כדינו עכ\"ל. וגם הט\"ז השיג עליו וכתב שאין זה אלא דברי תימה ואותן האנשים שעושין כן לאו דסמכי נינהו. ואפשר שבא להם הטעות ממה שראו בס\"ו בשמועה רחוקה שבמו\"ש ורגל נוהג אבלות שעה אחת וסברי שבכל שבת של אבילות עושים כן. והוא טעות גמור דשם הוי עיקר החיוב במו\"ש משום שמועה רחוקה משא\"כ בזה עכ\"ל:","\u0003עולה. \u0004 כ' הט\"ז שבטור כתוב אחר זה והר\"ר יחיאל כ' שאין שבת עולה לו בתחלת המנין אלא יתחיל למנות ביום א' וכו' ופסק הב\"י כדעה הראשונה. ומ\"מ הבאתי דברי הר\"ר יחיאל ללמוד ממנו שאם מת באחד בשבת דה\"ל יום השבת ז' של אבלות דאין לנהוג בו איסור בדברים שבצנעא אלא במקצת היום דהיינו בשחרית בהנץ החמה. וא\"ל הא אמרינן בסי' שצ\"ה בענין מקצת היום ככולו של יום השביעי דתלוי דוקא בעמדו המנחמים מאצלו ולא סגי בהנץ החמה כמו ביום ל'. הא לאו קושיא היא כלל דבכ\"מ שאמרו מקצתו ככולו היינו שאותו מקצת צריך להיות מאותו ענין שחייב בשאר הימים כגון במנין שבעה שצריך לעשות מעשה בחליצת סנדל וכיוצא בזה ושם אמרי' דצריך באותו מקצת של יום הז' לעשות מעשה החיוב עליו ונתנו גבול שעד שעת קימת המנחמים מאצלו ראוי להיות בקום ועשה מה שמוטל עליו לנהוג אבילות בעת ההיא משא\"כ בדין ל' שאין עליו חיוב רק בשב וא\"ת דהיינו איסור גיהוץ ותספורת בזה סגי בהנץ החמה כיון דכבר נהג איסור בשב וא\"ת די בכך. ומש\"ה בשמע שמועה רחוקה שנוהנ שעה א' צריך לעשות מעשה דוקא בשעה הזאת כמו בשמועה קרובה ז' ימים. הלכך כשחל יום השביעי בשבת סגי במקצת דהא גם ביום השבת כולו לא יעשה מעשה הניכר משום אבילות רק דבר שבצנעה נוהג והוא בשב וא\"ת וסגי במקצת ממנו דהוי ממש כיום השלשים כנ\"ל ברור. ודלא כהב\"ח שרוצה לחלוק על הר\"ר יחיאל ולומר דלא אמרי' ביום השבת מקצתו ככולו ורוצה לאסור לאותו אבל שחל יום השביעי שלו בשבת שלא יקרא בתורה אפילו במנחה דליתא ואפילו בשחרית יש היתר לקרותו בתורה אלא כיון שבחול ממתין עד אחר תפלת שחרית גם בשבת יעשה כן אבל במנחה יש היתר גמור לקרותו לתורה כדעת הר\"ר יחיאל שאין עליו דין שביעי לגמרי ואין חולק עליו בזה. ויש ג\"כ להביא ראיה ממ\"ש בס\"ה בשם הרמב\"ן דבכל אותו שבת אסור בדבר שבצנעא והיינו משום שיש עליו עדיין חיוב אבילות במו\"ש. משמע הא לא\"ה אינו אסור כל השבת אלא מקצתו ככולו וכן הוא עיקר בלי ספק עכ\"ל. וגם הש\"ך חולק על הב\"ח בזה וכתב דהכי משמע לישנא דש\"ס ופוסקים דלא לישתמיט חד לפלוגי בהכי:","\u0003קרובה. \u0004 כתב הש\"ך ומתחיל למנות ז' ול' משעה ששמע וכתבו הב\"ח והדרישה בשם מהרש\"ל דלפ\"ז היכא דמת ביום א' ונקבר ביום ב' אע\"פ שהקרובים שהיו אצל הקבורה מונים מיום הקבורה כי אז היתה סתימת הגולל מ\"מ אותן שלא היו אצל הקבורה ולא נודע להן שמת עד שהגיע יום ל' מיום הקבורה א\"צ לנהוג אבילות כיון דיום שמועה דידהו הוא יום ל\"א מיום המיתה וה\"ל שמועה רחוקה דלגבי דין שמועה יום המיתה הוא עיקר עכ\"ל וכ\"כ הט\"ז:","\u0003למחר. \u0004 וכן במתו לו ב' זה אחר זה כדלעיל סי' שע\"ה ס\"י. ש\"ך:","\u0003למנין. \u0004 ושוב הרגל מבטל ממנו גזרת ז' כדלעיל ר\"ס שצ\"ט. ש\"ך:","\u0003מחר. \u0004 כתב הט\"ז ונראה דאם שמע שמועה קרובה בסוף יום שלשים אחר תפלת ערבית ועדיין יום הוא ודאי לא אמרינן דהוי לילה מכח התפלה דלהחמיר אמרינן כן לענין שלא יעלה יום שעבר למנין שבעה אבל לא להקל לומר שהוא שמועה רחוקה אלא צריך להתאבל ודומה למ\"ש בסי' רס\"ב לענין מילה דלא איכפת לן בתפלה ובזה עכ\"פ מונה מיום השמועה ולא ממחרת דלא ליהוי כתרי מילי דסתרי אהדדי עכ\"ל \u0005(ועיין לעיל סי' שע\"ה)\u0006:","\u0003לשקר. \u0004 ונראה דיש לומר בלשון דמשמע לתרי אפי דהיינו שאין מבואר בפירוש בדבריו שהוא מת אלא שהלשון סובל לחיים ולמות וראיה מר' חייא ששאל לרב אבא קיים א\"ל אמא קיימת ופי' התוספות דחיבילא' בשתממתיהאעבידו ששא\"תמה ששולאאלניאמערל באפביירוששאלשנימתעלעאכ\"מיל והמטת\"וזך: ז \u0005(ה\n\u0006","הבי\u0003א\u0004ן\u0003צ\u0004ר\u0003ל\u0004'\u0003. \u0004 והלבוש השיג ע\"ז דהא טעמא דמתענין הוא מפני הסכנה דריע מזלי' ביום זה שמת אביו או אמו וא\"כ אין חילוק ולעולם יש להתענות יום המיתה עכ\"ד. וכן משמע בתשובת מהר\"י ברין שהביא בב\"ח גם בתשובת משאת בנימין הקשה על דברי הר\"ב דאטו ב' אחים הדרים בעיר אחת והאחד היה אצל מיתת אביו והשני לא היה בעיר כשמת אביו וקודם הקבורה בא גם השני שאז האחד יעשה יא\"צ ביום המיתה והב' למחרתו ואיכא משום דלא תתגודדו וגם דמי לחוכא ואיטלולא ואנן בעינן דרכיה דרכי נועם ע\"כ. גם מדברי שאר אחרונים משמע דלעולם מתענין יום המיתה ולא יום הקבורה. ובתשובת מ\"ב שם כתב דדוקא משנה ראשונה ואילך אבל בשנה ראשונה לעולם עושין יא\"צ מיום הקבורה דאל\"כ לפעמים לא ישלים אבלות י\"ב חדש כגון אם מת בע\"ש סמוך לשבת שאין פנאי לקברו עד יום א' ואם יעשה היא\"צ ביום המיתה גם האבלות יפסוק בו ביום כי כבר נהוג עלמא שלא להתאבל רק עד היא\"צ וזה ודאי לאו שפיר דמי דהאבלות מתחלת מיום הקבורה וצריך להשלים עד אותו היום עכ\"ד ומעולם לא שמענו ולא ראינו לחלק שנות היא\"צ ולומר דבשנה ראשונה יש לעשות מיום הקבורה ואח\"כ מיום המיתה גם מדברי כל האחרונים שכתבו סתמא דיש לעשות ביום המיתה משמע גם בשנה ראשונה ולענין קושייתו נ\"ל דהא בלא\"ה נמי קשה דלפעמים משכחת לה שיהא יום הקבורה מרוחק הרבה מיום המיתה כגון שהוליכוהו למקום אחר לקברו שם דאין האבלות מתחיל אלא מיום הקבורה וכמ\"ש לעיל סי' שע\"ה והיא\"צ תתחיל מיום המיתה. ודוחק לומר דלענין אבלות די\"ב חדש אזלינן בתר יום המיתה וגם דוחק לומר דאם אירע בכה\"ג יש לעשות היא\"צ קודם י\"ב חודש. וכן משמע בת\"ה דלעולם עושים היא\"צ בתשלום האבלות. ומן הדין אפילו באותו יום היא\"צ שוב א\"צ לנהוג אבלות כי כבר נשלם זמן י\"ב חדש רק שהעולם נוהגין דכל אותו היום אין מבטלין דין אבלות די\"ב חדש. ואפשר משום דאומרים קדיש וברכו ומתענים לכן נוהגים ענין אבלות באותו יום אבל מן הדין א\"צ וגם נ\"מ למי שמתענה ואומר קדיש וברכו ביום המיתה והוא מת היום ונקבר למחר דאבלות לעולם מיום קבורה מנינן ע\"כ דברי הת\"ה. ע\"כ נראה דלעולם יש להתענות יום המיתה אלא דאם אירע דיום המיתה מרוחק מיום הקבורה ג' או ד' ימים או יותר יש להתענות בשנה ראשונה ביום הקבורה כדי שיעשה היא\"צ בתשלום האבלות כיון דא\"א בענין אחר וגם מילתא דלא שכיחא היא יש לסמוך בכה\"ג אמ\"ד לעשות ביום הקבורה ומשנה ראשונה ואילך יתענה ביום המיתה אבל מי שמת אביו ונקבר ביום שלאחריו יש להתענות ביום המיתה אף בשנה ראשונה כנ\"ל ודוק עכ\"ל הש\"ך. אבל הט\"ז פסק דלעולם לא יעשה היא\"צ רק ביום המיתה אף שהוא מרוחק הרבה מיום הקבורה ומה לנו במה שלא התאבל י\"ב חדש אם א\"א בכך ולית מאן דחש לזה עכ\"ל:","\u0003הראשון. \u0004 וכתב הש\"ך דבא\"ח ס' תקס\"ח מסיים הרב מיהו יש מחמירין להתענות בשניהם וכ\"כ מהרש\"ל שכן נוהגין והביאו הב\"ח עכ\"ל:","\u0003השני. \u0004 וה\"ה אם מתו בשנת העיבור באדר הראשון מתענים בשנת העיבור באדר הראשון וכ\"כ מהרש\"ל שם דפשוט שאם מת בראשון או בשני שכך מתענין בשנים המעוברות. עד כאן לשון הש\"ך:"]],["הַמְלַקֵט עַצְמוֹת אָבִיו, אוֹ שֶׁל שְׁאָר קְרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, מִתְאַבֵּל עֲלֵיהֶם כָּל הַיּוֹם כֻּלוֹ, בְּכָל הַדְּבָרִים הַנּוֹהֲגִים בְּאָבֵל, בִּכְפִיַּת הַמִּטָּה וַעֲטִיפַת הָרֹאשׁ וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה וּרְחִיצָה וְסִיכָה; וְלָעֶרֶב אֵין מִתְאַבֵּל עֲלֵיהֶם, אֲפִלוּ צְרוּרִים לוֹ בִּסְדִינוֹ. הָיָה עוֹמֵד וּמְלַקֵט, וְחָשְׁכָה לוֹ, מֻתָּר בַּיּוֹם שֶׁלְאַחֲרָיו. לְפִיכָךְ אֵין מְלַקְטִין אוֹתָם סָמוּךְ לַחֲשֵׁכָה, כְּדֵי שֶׁלֹּא יִהְיֶה נִמְצָא שֶׁלֹּא הִתְאַבֵּל עַל לִקוּט עַצְמוֹת אָבִיו. \u0005וְאֵין \u0010c0\u0011 אֲנִינוּת בְּלִקּוּט עֲצָמוֹת, רַק חָל עָלָיו אֲבֵלוּת מִיָּד (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכָּל שֶׁקוֹרֵעַ עָלָיו בִּשְׁעַת מִיתָתוֹ, קוֹרֵעַ עָלָיו בִּשְׁעַת לִקוּט עֲצָמוֹת. וְכָל שֶׁאֵינוֹ מִתְאַחֶה בִּשְׁעַת מִיתָתוֹ, אֵינוֹ מִתְאַחֶה בִּשְׁעַת לִקוּט עֲצָמוֹת.\nעֲצָמוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, אֲבָל אוֹמְרִים עֲלֵיהֶם תַּנְחוּמִין לְעַצְמָם. וְאֵין מַבְרִין עֲלֵיהֶם בְּחֶבֶר עִיר, אֲבָל מַבְרִין עֲלֵיהֶם בְּבֵיתוֹ. וְאֵין אוֹמְרִים עֲלֵיהֶם קִינָה וּנְהִי, אֲבָל אוֹמְרִים עֲלֵיהֶם קִלוּסִין. \u0005דְּהַיְנוּ שִׁבְחוֹ שֶׁל מֵת, וּמְשַׁבְּחִין לְהקב\"ה שֶׁמֵּמִית וּמְחַיֶּה (בַּטּוּר תִּמְצָא מְבֹאָר)\u0006.\nאֵין מְלַקְטִין עַצְמוֹת אָבִיו בַּמּוֹעֵד, וְאֵין צָרִיךְ לוֹמַר עַצְמוֹת שְׁאָר קְרוֹבִים.\nשָׁמַע שֶׁהַיּוֹם לִקְטוּ עַצְמוֹת אֶחָד מִקְרוֹבָיו שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם, אַף עַל פִּי שֶׁלֹּא הָיָה שָׁם, מִתְאַבֵּל עֲלֵיהֶם. \u0005אֲבָל שָׁמַע שֶׁנִּלְקְטוּ אֶתְמוֹל, אֵין מִתְאַבֵּל עֲלֵיהֶם (טוּר בְּשֵׁם הַיְּרוּשַׁלְמִי)\u0006.\nאֵין מְפָרְקִין אֶת הָעֲצָמוֹת וְלֹא מַפְסִיקִין אֶת הַגִידִים.\nלִקוּט עֲצָמוֹת אֵינוֹ אֶלָא \u0010c1\u0011 מִשֶּׁיִּכְלֶה הַבָּשָׂר; כָּלָה הַבָּשָׂר, אֵין הַצּוּרָה נִכֶּרֶת בָּעֲצָמוֹת, לְפִיכָךְ יָכוֹל לְלַקֵט בְּיָדוֹ עַצְמוֹת אָבִיו וְאִמּוֹ; וְאַף עַל פִּי כֵן נָכוֹן הַדָּבָר שֶׁלֹּא יִלְקְטֵם הוּא עַצְמוֹ, מֵהַהִיא דְּרַבִּי אֱלִיעֶזֶר בַּר צָדוֹק דִּבְסָמוּךְ.\nמְלַקֵט אָדָם עַצְמוֹת שְׁנֵי מֵתִים כְּאֶחָד בְּרֹאשׁ אֲפַרְסְקָל מִכָּאן, וּבְרֹאשׁ אֲפַרְסְקָל מִכָּאן, דִּבְרֵי רַבִּי יוֹחָנָן בֶּן נוּרִי. ר\"א אוֹמֵר: סוֹף אֲפַרְסְקָל לְהִתְעַכֵּל, וְסוֹף עֲצָמוֹת לְהִתְעַכֵּל, וְנִמְצְאוּ עַצְמוֹת שְׁנֵי מֵתִים מִתְעָרְבִים, אֶלָא מְלַקְטִין וְנוֹתְנִין כָּל אֶחָד לְעַצְמוֹ בְּאָרוֹן שֶׁל אֲרָזִים. אָמַר רַבִּי אֱלִיעֶזֶר בַּר צָדוֹק: כָּךְ אָמַר לִי אַבָּא בִּשְׁעַת מִיתָתוֹ: מִתְּחִלָה קִבְרוּנִי בְּבִקְעָה, וּלְבַסוֹף לְקֹט עַצְמוֹתַי וּתְנֵם בָּאֲרָזִים, וְאַל תִּלְקְטֵם אַתָּה בְּיָדְךָ, שֶׁלֹּא יִהְיוּ בְּזוּיוֹת עָלֶיךָ.\nהַמְלַקֵט עֲצָמוֹת, וְהַמְשַׁמֵּר אֶת הַמֵּת, וְהַמּוֹלִיךְ אוֹתָם מִמָּקוֹם לְמָקוֹם, פָּטוּר מִקְרִיאַת שְׁמַע וּמִתְּפִלָה וּמֵהַתְּפִלִין, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, בֵּין בְּחֹל בֵּין בְּשַׁבָּת, לֹא שְׁנָא עַצְמוֹת קְרוֹבִים לֹא שְׁנָא עַצְמוֹת רְחוֹקִים, בֵּין אִם הוּא בִּסְפִינָה אוֹ בַּדֶּרֶךְ, וַאֲפִלוּ אִם הֵם מְלַקְטִים \u0010c2\u0011 רַבִּים. וְאִם רָצָה לְהַחְמִיר עַל עַצְמוֹ, לֹא יַחְמִיר, מִפְּנֵי כְּבוֹד עֲצָמוֹת.\nהַמּוֹלִיךְ עֲצָמוֹת מִמָּקוֹם לְמָקוֹם, הֲרֵי זֶה לֹא יִתְּנֵם בְּשַׂק אוֹ בְּדִסְקִיָּא וְיַנִּיחֵם עַל הַחֲמוֹר וְיִרְכַּב עֲלֵיהֶם, מִפְּנֵי \u0010c3\u0011 שֶׁנּוֹהֵג בָּהֶם מִנְהַג בִּזָּיוֹן; אֲבָל אִם מַפְשִׁילוֹ לַאֲחוֹרָיו עַל הַחֲמוֹר, שַׁפִּיר דָּמֵי. וְאִם הָיָה מִתְיָרֵא מִפְּנֵי הַגַנָּבִים וְהַלִסְטִים, מֻתָּר. \u0005הַגָּה: וְהַחַי יִתֵּן אֶל לִבּוֹ דְּבָרִים שֶׁל מִיתָה; דְּיִסְפַּד, יִסְפְּדוּנֵהּ; דְּיִקְבַּר, יִקְבְּרוּנֵהּ; דְּיִטְעֹן, יַטְעִינֵהּ; דְּיִדַּל, יַדְלוּנֵהּ; וְגָדוֹל הַשָּׁלוֹם שֶׁנִּתַּן לַצַּדִּיקִים, שֶׁבְּשָׁעָה שֶׁהַצַּדִּיק נִפְטָר ג' כִּתּוֹת שֶׁל מַלְאָכִים נוֹתְנִים לוֹ שָׁלוֹם. (הַכֹּל בַּטּוּר וְהָרֹא\"שׁ וְכָל בּוֹ)\u0006 \u0005(וְאוֹמְרִים יָבֹא שָׁלוֹם כָּל הַכָּתוּב לַחַיִּים קָדוֹשׁ יֵאָמֶר לוֹ)\u0006. בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. \u0005(יְשַׁעְיָה כה, ח')\u0006.",[],["\u0003אנינות. \u0004 כלומר שיאסר קודם שיקברו העצמות באכילת בשר ושתיית יין כדין אונן לעיל סי' שמ\"א אלא מיד חל עליו האבלות אף קודם שיקברם ע\"ל סי' שע\"ה ס\"ז. כהן אינו רשאי ללקט עצמות אביו דשמא נחסר אביו סא\"ז פי' אם נחסר כל שהוא מאביו אסור ליטמא לו כדלעיל ס\"ס שע\"ג דרישה עכ\"ל הש\"ך:","\u0003משיכלה. \u0004 כלומר לענין זה שילקטם הוא בעצמו כדמפרש ואזיל אבל אה\"נ דאף כשלא כלה הבשר חייב להתאבל כל היום כדלעיל סי' שע\"ה ס\"ז. ש\"ך:","\u0003רבים. \u0004 כתב הש\"ך ודוקא מלקטים רבים אבל משמרים רבים זה משמר וזה קורא וכמ\"ש בא\"ח סי' ע\"א ס\"ד \u0005(ודין מקום הקבר שנלקטו ממנו העצמות אם מותר לקבור בו מתים אחרים ע\"ל סי' שס\"ג ושס\"ד. וע' בתשו' ש\"י שאלה פ\"ז)\u0006:","\u0003שנוהג. \u0004 ע\"ל סי' רפ\"ב ס\"ג. והרחמן יגדור פרצת עמו ישראל וינחם אותם בבנין ירושלים במהרה בימינו אמן כן יהי רצון:"]]]};
